<?php

declare(strict_types=1);

namespace PortLibs\Pandoc;

final class PdfEngineHandoff
{
    private const MAX_SOURCE_MAP_BYTES = 1048576;
    private const MAX_DEPENDENCY_FILE_BYTES = 1048576;
    private const MAX_PDF_OUTPUT_INSPECTION_BYTES = 1048576;
    private const MAX_XMP_METADATA_BYTES = 262144;
    private const MAX_OUTPUT_INTENT_PROFILE_BYTES = 262144;
    private const MAX_EMBEDDED_FILE_STREAM_BYTES = 262144;
    private const MAX_SIGNATURE_CONTENTS_BYTES = 262144;
    private const MAX_DOCUMENT_SECURITY_STORE_STREAM_BYTES = 262144;
    private const MAX_PIECE_INFO_PRIVATE_STREAM_BYTES = 262144;
    private const MAX_LEGAL_ATTESTATION_STREAM_BYTES = 262144;
    private const MAX_XFA_PACKET_BYTES = 262144;
    private const MAX_EMBEDDED_FONT_STREAM_BYTES = 262144;
    private const MAX_IMAGE_STREAM_BYTES = 262144;
    private const MAX_FORM_XOBJECT_STREAM_BYTES = 262144;
    private const MAX_ANNOTATION_APPEARANCE_STREAM_BYTES = 262144;
    private const MAX_PAGE_CONTENT_STREAM_BYTES = 262144;
    private const MAX_XREF_STREAM_BYTES = 262144;
    private const MAX_OBJECT_STREAM_BYTES = 262144;
    private const MAX_TRANSCRIPT_BYTES = 1048576;
    private const XMP_PDF_A_ID_NAMESPACE = 'http://www.aiim.org/pdfa/ns/id/';
    private const XMP_PDF_UA_ID_NAMESPACE = 'http://www.aiim.org/pdfua/ns/id/';
    private const XMP_PDF_X_ID_NAMESPACE = 'http://www.npes.org/pdfx/ns/id/';
    private const XMP_PDF_A_EXTENSION_NAMESPACE = 'http://www.aiim.org/pdfa/ns/extension/';
    private const XMP_PDF_A_SCHEMA_NAMESPACE = 'http://www.aiim.org/pdfa/ns/schema#';
    private const XMP_PDF_A_PROPERTY_NAMESPACE = 'http://www.aiim.org/pdfa/ns/property#';
    private const XMP_MEDIA_MANAGEMENT_NAMESPACE = 'http://ns.adobe.com/xap/1.0/mm/';
    private const XMP_RESOURCE_REF_NAMESPACE = 'http://ns.adobe.com/xap/1.0/sType/ResourceRef#';
    private const XMP_RESOURCE_EVENT_NAMESPACE = 'http://ns.adobe.com/xap/1.0/sType/ResourceEvent#';
    private const XMP_RDF_NAMESPACE = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#';
    private const PDF_DOC_ENCODING_OVERRIDES = [
        0x18 => 0x02D8,
        0x19 => 0x02C7,
        0x1A => 0x02C6,
        0x1B => 0x02D9,
        0x1C => 0x02DD,
        0x1D => 0x02DB,
        0x1E => 0x02DA,
        0x1F => 0x02DC,
        0x7F => 0xFFFD,
        0x80 => 0x2022,
        0x81 => 0x2020,
        0x82 => 0x2021,
        0x83 => 0x2026,
        0x84 => 0x2014,
        0x85 => 0x2013,
        0x86 => 0x0192,
        0x87 => 0x2044,
        0x88 => 0x2039,
        0x89 => 0x203A,
        0x8A => 0x2212,
        0x8B => 0x2030,
        0x8C => 0x201E,
        0x8D => 0x201C,
        0x8E => 0x201D,
        0x8F => 0x2018,
        0x90 => 0x2019,
        0x91 => 0x201A,
        0x92 => 0x2122,
        0x93 => 0xFB01,
        0x94 => 0xFB02,
        0x95 => 0x0141,
        0x96 => 0x0152,
        0x97 => 0x0160,
        0x98 => 0x0178,
        0x99 => 0x017D,
        0x9A => 0x0131,
        0x9B => 0x0142,
        0x9C => 0x0153,
        0x9D => 0x0161,
        0x9E => 0x017E,
        0x9F => 0xFFFD,
        0xA0 => 0x20AC,
    ];

    /**
     * @var array<string, array{family:string, intermediate:string, extension:string, defaultArgs:list<string>}>
     */
    private const ENGINE_PROFILES = [
        'pdflatex' => ['family' => 'latex', 'intermediate' => 'latex', 'extension' => 'tex', 'defaultArgs' => ['-halt-on-error', '-interaction=nonstopmode']],
        'lualatex' => ['family' => 'latex', 'intermediate' => 'latex', 'extension' => 'tex', 'defaultArgs' => ['-halt-on-error', '-interaction=nonstopmode']],
        'xelatex' => ['family' => 'latex', 'intermediate' => 'latex', 'extension' => 'tex', 'defaultArgs' => ['-halt-on-error', '-interaction=nonstopmode']],
        'latexmk' => ['family' => 'latex', 'intermediate' => 'latex', 'extension' => 'tex', 'defaultArgs' => ['-pdf', '-halt-on-error', '-interaction=nonstopmode']],
        'tectonic' => ['family' => 'latex', 'intermediate' => 'latex', 'extension' => 'tex', 'defaultArgs' => []],
        'context' => ['family' => 'context', 'intermediate' => 'context', 'extension' => 'tex', 'defaultArgs' => []],
        'pdfroff' => ['family' => 'roff', 'intermediate' => 'ms', 'extension' => 'ms', 'defaultArgs' => []],
        'wkhtmltopdf' => ['family' => 'html', 'intermediate' => 'html5', 'extension' => 'html', 'defaultArgs' => []],
        'weasyprint' => ['family' => 'html', 'intermediate' => 'html5', 'extension' => 'html', 'defaultArgs' => []],
        'prince' => ['family' => 'html', 'intermediate' => 'html5', 'extension' => 'html', 'defaultArgs' => []],
        'pagedjs-cli' => ['family' => 'html', 'intermediate' => 'html5', 'extension' => 'html', 'defaultArgs' => []],
        'typst' => ['family' => 'typst', 'intermediate' => 'typst', 'extension' => 'typ', 'defaultArgs' => []],
    ];

    /**
     * @param array{
     *     engine?: string,
     *     outputPath?: string,
     *     output?: string,
     *     sourcePath?: string,
     *     source?: string,
     *     engineOptions?: list<string>|string,
     *     engineEnvironment?: array<string, string>,
     *     templatePath?: string,
     *     includeInHeader?: list<string>|string,
     *     resourcePaths?: list<string>|string,
     *     resourceFiles?: list<string>|string,
     *     variables?: array<string, mixed>
     * } $options
     * @return array{
     *     kind: string,
     *     target: string,
     *     willExecute: bool,
     *     engineProgram: string,
     *     engine: string,
     *     engineFamily: string,
     *     intermediateFormat: string,
     *     sourceFile: string,
     *     outputFile: string,
     *     argv: list<string>,
     *     engineOptions: list<string>,
     *     engineEnvironment: array<string, string>,
     *     sourceBytes: string|null,
     *     sourceSha256: string|null,
     *     templateFile: string|null,
     *     includeInHeaderFiles: list<string>,
     *     resourcePaths: list<string>,
     *     resourceFiles: list<string>,
     *     resourceFileManifest: list<array{path:string, kind:string, sources:list<string>, title:string|null, alt:string|null}>,
     *     remoteResourceReferences: list<string>,
     *     skippedResourceReferences: list<string>,
     *     templateVariables: array<string, mixed>,
     *     writerArguments: list<string>,
     *     sourceArtifacts: list<string>,
     *     engineLogFile: string|null,
     *     engineArtifactStem: string,
     *     engineDependencyFile: string|null,
     *     expectedEngineArtifacts: list<string>,
     *     typstImportPathPolicy: array<string, mixed>,
     *     typstBoundaryProvenance: array<string, mixed>,
     *     metadata: array<string, mixed>,
     *     diagnostics: list<string>
     * }
     */
    public function plan(AstNode $document, array $options = []): array
    {
        if ($document->type !== 'document') {
            throw new \InvalidArgumentException('PDF engine handoff expects a document node');
        }

        $engineProgram = $this->requireString($options['engine'] ?? 'pdflatex', 'PDF engine');
        $engine = $this->engineName($engineProgram);
        if (!isset(self::ENGINE_PROFILES[$engine])) {
            throw new \InvalidArgumentException('Unsupported PDF engine: ' . $engineProgram);
        }

        $profile = self::ENGINE_PROFILES[$engine];
        $outputFile = $this->normalizeRelativePath((string) ($options['outputPath'] ?? $options['output'] ?? 'document.pdf'), 'PDF output path');
        if (!preg_match('/\.pdf\z/i', $outputFile)) {
            throw new \InvalidArgumentException('PDF output path must end with .pdf');
        }

        $sourceFile = isset($options['sourcePath'])
            ? $this->normalizeRelativePath($this->requireString($options['sourcePath'], 'PDF source path'), 'PDF source path')
            : $this->deriveSourcePath($outputFile, $profile['extension']);
        $sourceInput = $this->sourceInputFor($engine, $sourceFile);
        $engineOptions = $this->normalizeStringList($options['engineOptions'] ?? []);
        $engineEnvironment = $this->normalizeEngineEnvironment($options['engineEnvironment'] ?? []);
        $typstOutputFormatPolicy = $this->typstOutputFormatPolicyFor($engine, $outputFile, $engineOptions);
        $sourceBytes = array_key_exists('source', $options)
            ? $this->requireString($options['source'], 'PDF intermediate source')
            : $this->renderIntermediateSource($document, $profile['intermediate']);
        $templateFile = array_key_exists('templatePath', $options)
            ? $this->normalizeRelativePath($this->requireString($options['templatePath'], 'PDF template path'), 'PDF template path')
            : null;
        $includeInHeaderFiles = $this->normalizeRelativePathList($options['includeInHeader'] ?? [], 'PDF include-in-header path');
        $resourcePaths = $this->normalizeRelativePathList($options['resourcePaths'] ?? [], 'PDF resource path');
        $resourceInventory = $this->resourceInventoryFor($document, $options['resourceFiles'] ?? []);
        $metadata = $this->metadataSummary($document);
        $variables = array_key_exists('variables', $options)
            ? $this->normalizeVariables($options['variables'])
            : [];
        $templateVariables = array_replace($metadata, $variables);
        $writerArguments = $this->writerArgumentsFor($templateFile, $includeInHeaderFiles, $resourcePaths, $variables);
        $sourceArtifacts = array_values(array_filter(
            array_merge([$templateFile], $includeInHeaderFiles),
            static fn (?string $path): bool => $path !== null && $path !== ''
        ));
        $engineArtifactStem = $this->engineArtifactStemFor($profile['family'], $sourceFile, $engineOptions);
        $expectedEngineArtifacts = $this->expectedEngineArtifactsFor($engine, $profile['family'], $engineArtifactStem);
        $recorderFile = $this->recorderFileFor($engine, $profile['family'], $engineArtifactStem, $engineOptions);
        if ($recorderFile !== null && !in_array($recorderFile, $expectedEngineArtifacts, true)) {
            $expectedEngineArtifacts[] = $recorderFile;
        }
        $engineDependencyFile = $this->engineDependencyFileFor($engine, $profile['family'], $engineArtifactStem, $engineOptions);
        if ($engineDependencyFile !== null && !in_array($engineDependencyFile, $expectedEngineArtifacts, true)) {
            $expectedEngineArtifacts[] = $engineDependencyFile;
        }
        $typstTimingFile = $this->typstTimingOutputFileFor($engine, $profile['family'], $engineOptions);
        if ($typstTimingFile !== null && !in_array($typstTimingFile, $expectedEngineArtifacts, true)) {
            $expectedEngineArtifacts[] = $typstTimingFile;
        }
        $typstBoundaryProvenance = $this->typstBoundaryProvenanceFor($engine, $profile['family'], $engineOptions, $engineEnvironment);
        $typstBoundarySummary = $this->typstBoundarySummaryFor($typstBoundaryProvenance);
        $typstBoundaryMatrix = $this->typstBoundaryMatrixFor(
            $engine,
            $typstBoundaryProvenance,
            $typstBoundarySummary,
            $sourceInput,
            $typstOutputFormatPolicy
        );
        $typstImportPathPolicy = $this->typstImportPathPolicyFor($engine, is_string($sourceBytes) ? $sourceBytes : null);
        $engineBoundaryRoot = $this->engineBoundaryRootFor($engine, $profile['family'], $engineOptions, $engineEnvironment);
        $sourceMapFile = $this->sourceMapFileFor($profile['family'], $engineArtifactStem, $engineOptions);
        if ($sourceMapFile !== null && !in_array($sourceMapFile, $expectedEngineArtifacts, true)) {
            $expectedEngineArtifacts[] = $sourceMapFile;
        }
        $engineLogFile = $this->firstEngineLogFile($expectedEngineArtifacts);

        $diagnostics = ['pdf-engine-not-executed'];
        if ($sourceBytes === null) {
            $diagnostics[] = 'intermediate-writer-pending:' . $profile['intermediate'];
        } elseif (array_key_exists('source', $options)) {
            $diagnostics[] = 'intermediate-source-supplied';
        } else {
            $diagnostics[] = 'intermediate-source-rendered:' . $profile['intermediate'];
        }
        if ($sourceInput !== []) {
            $diagnostics[] = 'typst-source-input:' . $sourceInput['mode'];
            if (($sourceInput['issues'] ?? []) !== []) {
                $diagnostics[] = 'typst-source-input-issues:' . count($sourceInput['issues']);
            }
        }
        $this->appendTypstImportPathPolicyDiagnostics($diagnostics, $typstImportPathPolicy);
        if ($templateFile !== null) {
            $diagnostics[] = 'pdf-template-supplied';
        }
        if ($includeInHeaderFiles !== []) {
            $diagnostics[] = 'pdf-include-in-header:' . count($includeInHeaderFiles);
        }
        if ($resourcePaths !== []) {
            $diagnostics[] = 'pdf-resource-paths:' . count($resourcePaths);
        }
        if ($resourceInventory['files'] !== []) {
            $diagnostics[] = 'pdf-resource-files:' . count($resourceInventory['files']);
        }
        if ($resourceInventory['remote'] !== []) {
            $diagnostics[] = 'pdf-remote-resources:' . count($resourceInventory['remote']);
        }
        if ($resourceInventory['skipped'] !== []) {
            $diagnostics[] = 'pdf-skipped-resources:' . count($resourceInventory['skipped']);
        }
        if ($variables !== []) {
            $diagnostics[] = 'pdf-template-variables:' . count($this->flattenVariableArguments($variables));
        }
        if ($typstOutputFormatPolicy !== []) {
            $diagnostics[] = 'typst-output-format-policy:' . $typstOutputFormatPolicy['reviewStatus'];
            if ($typstOutputFormatPolicy['explicitFormat'] !== null) {
                $diagnostics[] = 'typst-output-format-explicit:' . $typstOutputFormatPolicy['explicitFormat'];
            }
            if (($typstOutputFormatPolicy['formatHistory'] ?? []) !== []) {
                $diagnostics[] = 'typst-output-format-history:' . count($typstOutputFormatPolicy['formatHistory']);
            }
            if (($typstOutputFormatPolicy['overrides'] ?? []) !== []) {
                $diagnostics[] = 'typst-output-format-overrides:' . count($typstOutputFormatPolicy['overrides']);
            }
            if ($typstOutputFormatPolicy['issues'] !== []) {
                $diagnostics[] = 'typst-output-format-issues:' . count($typstOutputFormatPolicy['issues']);
            }
        }
        if ($engineLogFile !== null) {
            $diagnostics[] = 'pdf-engine-log:' . $engineLogFile;
        }
        if ($recorderFile !== null) {
            $diagnostics[] = 'pdf-engine-recorder:' . $recorderFile;
        }
        if ($engineDependencyFile !== null) {
            $diagnostics[] = 'pdf-engine-dependency-file:' . $engineDependencyFile;
        }
        if ($typstBoundaryProvenance !== []) {
            $diagnostics[] = 'typst-boundary-provenance:' . $typstBoundaryProvenance['reviewStatus'];
            if (($typstBoundaryProvenance['root'] ?? null) !== null) {
                $diagnostics[] = 'typst-root-boundary:' . $typstBoundaryProvenance['root']['path'];
            }
            if (($typstBoundaryProvenance['rootEnvironment'] ?? null) !== null) {
                $rootEnvironment = $typstBoundaryProvenance['rootEnvironment'];
                if (is_array($rootEnvironment) && is_string($rootEnvironment['path'] ?? null)) {
                    $diagnostics[] = 'typst-root-environment:' . ($rootEnvironment['path'] === '' ? 'invalid' : $rootEnvironment['path']);
                    if (in_array('root-environment-shadowed', $rootEnvironment['issues'] ?? [], true)) {
                        $diagnostics[] = 'typst-root-environment-shadowed';
                    }
                }
            }
            if (($typstBoundaryProvenance['fontPaths'] ?? []) !== []) {
                $diagnostics[] = 'typst-font-paths:' . count($typstBoundaryProvenance['fontPaths']);
            }
            if (($typstBoundaryProvenance['fontPathPolicy'] ?? []) !== []) {
                $fontPathPolicy = $typstBoundaryProvenance['fontPathPolicy'];
                if (is_array($fontPathPolicy) && is_string($fontPathPolicy['reviewStatus'] ?? null)) {
                    $diagnostics[] = 'typst-font-path-policy:' . $fontPathPolicy['reviewStatus'];
                }
                if (is_array($fontPathPolicy) && is_int($fontPathPolicy['unsafeFontPathCount'] ?? null) && $fontPathPolicy['unsafeFontPathCount'] > 0) {
                    $diagnostics[] = 'typst-font-path-unsafe:' . $fontPathPolicy['unsafeFontPathCount'];
                }
            }
            if (($typstBoundaryProvenance['certificates'] ?? []) !== []) {
                $diagnostics[] = 'typst-certificates:' . count($typstBoundaryProvenance['certificates']);
            }
            if (($typstBoundaryProvenance['certificateEnvironment'] ?? null) !== null) {
                $certificateEnvironment = $typstBoundaryProvenance['certificateEnvironment'];
                if (is_array($certificateEnvironment) && is_string($certificateEnvironment['path'] ?? null)) {
                    $diagnostics[] = 'typst-certificate-environment:' . ($certificateEnvironment['path'] === '' ? 'invalid' : $certificateEnvironment['path']);
                    if (in_array('certificate-environment-shadowed', $certificateEnvironment['issues'] ?? [], true)) {
                        $diagnostics[] = 'typst-certificate-environment-shadowed';
                    }
                }
            }
            if (($typstBoundaryProvenance['certificatePolicy'] ?? []) !== []) {
                $certificatePolicy = $typstBoundaryProvenance['certificatePolicy'];
                if (is_array($certificatePolicy) && is_string($certificatePolicy['reviewStatus'] ?? null)) {
                    $diagnostics[] = 'typst-certificate-policy:' . $certificatePolicy['reviewStatus'];
                }
                if (is_array($certificatePolicy) && is_int($certificatePolicy['unsafeCertificateCount'] ?? null) && $certificatePolicy['unsafeCertificateCount'] > 0) {
                    $diagnostics[] = 'typst-certificate-unsafe:' . $certificatePolicy['unsafeCertificateCount'];
                }
            }
            if (($typstBoundaryProvenance['packagePath'] ?? null) !== null) {
                $diagnostics[] = 'typst-package-path:' . $typstBoundaryProvenance['packagePath']['path'];
            }
            if (($typstBoundaryProvenance['packagePathEnvironment'] ?? null) !== null) {
                $packagePathEnvironment = $typstBoundaryProvenance['packagePathEnvironment'];
                $diagnostics[] = 'typst-package-path-environment:' . ($packagePathEnvironment['path'] === '' ? 'invalid' : $packagePathEnvironment['path']);
                if (in_array('package-path-environment-shadowed', $packagePathEnvironment['issues'] ?? [], true)) {
                    $diagnostics[] = 'typst-package-path-environment-shadowed';
                }
            }
            if (($typstBoundaryProvenance['packageCache'] ?? null) !== null) {
                $diagnostics[] = 'typst-package-cache:' . $typstBoundaryProvenance['packageCache']['path'];
            }
            if (($typstBoundaryProvenance['packageCacheEnvironment'] ?? null) !== null) {
                $packageCacheEnvironment = $typstBoundaryProvenance['packageCacheEnvironment'];
                $diagnostics[] = 'typst-package-cache-environment:' . ($packageCacheEnvironment['path'] === '' ? 'invalid' : $packageCacheEnvironment['path']);
                if (in_array('package-cache-environment-shadowed', $packageCacheEnvironment['issues'] ?? [], true)) {
                    $diagnostics[] = 'typst-package-cache-environment-shadowed';
                }
            }
            if (($typstBoundaryProvenance['packageStoragePolicy'] ?? []) !== []) {
                $packageStoragePolicy = $typstBoundaryProvenance['packageStoragePolicy'];
                if (is_array($packageStoragePolicy) && is_string($packageStoragePolicy['reviewStatus'] ?? null)) {
                    $diagnostics[] = 'typst-package-storage-policy:' . $packageStoragePolicy['reviewStatus'];
                }
                if (is_array($packageStoragePolicy) && is_int($packageStoragePolicy['unsafeStorageEntryCount'] ?? null) && $packageStoragePolicy['unsafeStorageEntryCount'] > 0) {
                    $diagnostics[] = 'typst-package-storage-unsafe:' . $packageStoragePolicy['unsafeStorageEntryCount'];
                }
            }
            if (($typstBoundaryProvenance['inputVariables'] ?? []) !== []) {
                $diagnostics[] = 'typst-boundary-inputs:' . count($typstBoundaryProvenance['inputVariables']);
            }
            if (($typstBoundaryProvenance['inputVariableOverrides'] ?? []) !== []) {
                $diagnostics[] = 'typst-boundary-input-overrides:' . count($typstBoundaryProvenance['inputVariableOverrides']);
            }
            if (($typstBoundaryProvenance['inputVariablePolicy'] ?? []) !== []) {
                $inputVariablePolicy = $typstBoundaryProvenance['inputVariablePolicy'];
                if (is_array($inputVariablePolicy) && is_string($inputVariablePolicy['reviewStatus'] ?? null)) {
                    $diagnostics[] = 'typst-input-variable-policy:' . $inputVariablePolicy['reviewStatus'];
                }
                if (is_array($inputVariablePolicy) && is_int($inputVariablePolicy['unsafeInputVariableCount'] ?? null) && $inputVariablePolicy['unsafeInputVariableCount'] > 0) {
                    $diagnostics[] = 'typst-input-variable-unsafe:' . $inputVariablePolicy['unsafeInputVariableCount'];
                }
                if (is_array($inputVariablePolicy) && is_int($inputVariablePolicy['duplicateInputNameCount'] ?? null) && $inputVariablePolicy['duplicateInputNameCount'] > 0) {
                    $diagnostics[] = 'typst-input-variable-overridden:' . $inputVariablePolicy['duplicateInputNameCount'];
                }
            }
            if (($typstBoundaryProvenance['environmentVariables'] ?? []) !== []) {
                $diagnostics[] = 'typst-boundary-environment:' . count($typstBoundaryProvenance['environmentVariables']);
            }
            if (($typstBoundaryProvenance['systemFonts'] ?? []) !== []) {
                $systemFonts = $typstBoundaryProvenance['systemFonts'];
                if (is_array($systemFonts) && is_string($systemFonts['systemFontAccess'] ?? null)) {
                    $diagnostics[] = 'typst-system-font-access:' . $systemFonts['systemFontAccess'];
                }
                if (is_array($systemFonts) && is_int($systemFonts['flagCount'] ?? null) && $systemFonts['flagCount'] > 0) {
                    $diagnostics[] = 'typst-ignore-system-fonts:' . $systemFonts['flagCount'];
                }
                if (is_array($systemFonts) && ($systemFonts['issues'] ?? []) !== []) {
                    $diagnostics[] = 'typst-system-font-issues:' . count($systemFonts['issues']);
                }
            }
            if (($typstBoundaryProvenance['embeddedFonts'] ?? []) !== []) {
                $embeddedFonts = $typstBoundaryProvenance['embeddedFonts'];
                if (is_array($embeddedFonts) && is_string($embeddedFonts['embeddedFontAccess'] ?? null)) {
                    $diagnostics[] = 'typst-embedded-font-access:' . $embeddedFonts['embeddedFontAccess'];
                }
                if (is_array($embeddedFonts) && is_int($embeddedFonts['flagCount'] ?? null) && $embeddedFonts['flagCount'] > 0) {
                    $diagnostics[] = 'typst-ignore-embedded-fonts:' . $embeddedFonts['flagCount'];
                }
                if (is_array($embeddedFonts) && ($embeddedFonts['issues'] ?? []) !== []) {
                    $diagnostics[] = 'typst-embedded-font-issues:' . count($embeddedFonts['issues']);
                }
            }
            if (($typstBoundaryProvenance['openOutput'] ?? []) !== []) {
                $openOutput = $typstBoundaryProvenance['openOutput'];
                if (is_array($openOutput) && ($openOutput['enabled'] ?? false) === true) {
                    $diagnostics[] = 'typst-open-output:enabled';
                }
                if (is_array($openOutput) && is_int($openOutput['flagCount'] ?? null) && $openOutput['flagCount'] > 0) {
                    $diagnostics[] = 'typst-open-output-flags:' . $openOutput['flagCount'];
                }
                if (is_array($openOutput) && is_array($openOutput['viewer'] ?? null)) {
                    $viewer = $openOutput['viewer'];
                    if (is_string($viewer['viewer'] ?? null)) {
                        $diagnostics[] = 'typst-open-output-viewer:' . $viewer['viewer'];
                    }
                }
                if (is_array($openOutput) && is_array($openOutput['viewers'] ?? null) && count($openOutput['viewers']) > 1) {
                    $diagnostics[] = 'typst-open-output-viewers:' . count($openOutput['viewers']);
                }
            }
            if (($typstBoundaryProvenance['featureGates'] ?? null) !== null) {
                $featureGates = $typstBoundaryProvenance['featureGates'];
                if (is_array($featureGates) && is_int($featureGates['featureCount'] ?? null)) {
                    $diagnostics[] = 'typst-feature-gates:' . $featureGates['featureCount'];
                }
            }
            if (($typstBoundaryProvenance['featureGateEnvironment'] ?? null) !== null) {
                $featureGateEnvironment = $typstBoundaryProvenance['featureGateEnvironment'];
                if (is_array($featureGateEnvironment) && is_int($featureGateEnvironment['featureCount'] ?? null)) {
                    $diagnostics[] = 'typst-feature-gates-environment:' . $featureGateEnvironment['featureCount'];
                    if (in_array('features-environment-shadowed', $featureGateEnvironment['issues'] ?? [], true)) {
                        $diagnostics[] = 'typst-feature-gates-environment-shadowed';
                    }
                }
            }
            if (($typstBoundaryProvenance['executionPolicy'] ?? null) !== null) {
                $executionPolicy = $typstBoundaryProvenance['executionPolicy'];
                if (is_array($executionPolicy) && is_array($executionPolicy['jobs'] ?? null)) {
                    $jobs = $executionPolicy['jobs'];
                    if (is_string($jobs['value'] ?? null)) {
                        $diagnostics[] = 'typst-execution-jobs:' . ($jobs['value'] === '' ? 'invalid' : $jobs['value']);
                    }
                }
                if (is_array($executionPolicy) && ($executionPolicy['issues'] ?? []) !== []) {
                    $diagnostics[] = 'typst-execution-policy-issues:' . count($executionPolicy['issues']);
                }
            }
            if (($typstBoundaryProvenance['timingsOutput'] ?? null) !== null) {
                $timingsOutput = $typstBoundaryProvenance['timingsOutput'];
                if (is_array($timingsOutput) && is_string($timingsOutput['path'] ?? null)) {
