        $typstBoundaryProvenance = is_array($plan['typstBoundaryProvenance'] ?? null)
            ? $plan['typstBoundaryProvenance']
            : $this->typstBoundaryProvenanceFor($engine, $engine === 'typst' ? 'typst' : '', $planEngineOptions, $planEngineEnvironment);
        $typstDependencyFormat = $this->typstDependencyFormatFromBoundaryProvenance($typstBoundaryProvenance);
        $typstBoundarySummary = is_array($plan['typstBoundarySummary'] ?? null)
            ? $plan['typstBoundarySummary']
            : $this->typstBoundarySummaryFor($typstBoundaryProvenance);

        $sourceBytes = $plan['sourceBytes'] ?? null;
        $typstImportPathPolicy = is_array($plan['typstImportPathPolicy'] ?? null)
            ? $plan['typstImportPathPolicy']
            : $this->typstImportPathPolicyFor($engine, is_string($sourceBytes) ? $sourceBytes : null);
        $this->appendTypstImportPathPolicyDiagnostics($diagnostics, $typstImportPathPolicy);
        $sourceSha256 = null;
        $sourceArtifactsSha256 = [];
        $resourceArtifactsSha256 = [];
        $missingResourceFiles = [];
        $producedArtifactsSha256 = [];
        $engineDependencyArtifactsSha256 = [];
        $engineInputFiles = [];
        $engineExternalInputFiles = [];
        $engineExternalDependencies = [];
        $engineOutputFiles = [];
        $engineDependencyEdges = [];
        $typstDependencyEdgePackageProvenance = [];
        $missingEngineInputFiles = [];
        $engineTranscriptInputFiles = [];
        $engineTranscriptExternalInputFiles = [];
        $missingEngineTranscriptInputFiles = [];
        $bibliographyArtifactsSha256 = [];
        $bibliographyLogFiles = [];
        $bibliographyLogTexts = [];
        $sourceMapArtifactsSha256 = [];
        $sourceMapFiles = [];
        $sourceMapInputsByKey = [];
        $sourceMapInputFiles = [];
        $sourceMapExternalInputs = [];
        $sourceMapLineRangesByKey = [];
        $engineLogFiles = [];
        $engineLogTexts = [];
        $status = 'ok';
        $reason = null;

        if (is_string($sourceBytes)) {
            if ($sourceIsStdin) {
                $sourceSha256 = hash('sha256', $sourceBytes);
                $diagnostics[] = 'staged-source-from-stdin';
            } elseif (!array_key_exists($sourceFile, $files)) {
                $files[$sourceFile] = $sourceBytes;
                $diagnostics[] = 'staged-source-from-plan';
            } elseif ($files[$sourceFile] !== $sourceBytes) {
                $status = 'failed';
                $reason = 'source-mismatch';
            }
        }

        if (!$sourceIsStdin && array_key_exists($sourceFile, $files)) {
            $sourceSha256 = hash('sha256', $files[$sourceFile]);
        }

        foreach ($this->normalizePlanStringList($plan['sourceArtifacts'] ?? [], 'PDF source artifact') as $artifactPath) {
            if (!array_key_exists($artifactPath, $files)) {
                if ($reason === null) {
                    $status = 'failed';
                    $reason = 'missing-source-artifact';
                }
                $diagnostics[] = 'missing-source-artifact:' . $artifactPath;
                continue;
            }

            $sourceArtifactsSha256[$artifactPath] = hash('sha256', $files[$artifactPath]);
        }
        if ($sourceArtifactsSha256 !== [] && $reason === null) {
            $diagnostics[] = 'source-artifacts-validated:' . count($sourceArtifactsSha256);
        }

        $resourceFiles = $this->normalizeResourceFileList($plan['resourceFiles'] ?? [], 'PDF resource file');
        foreach ($resourceFiles as $resourcePath) {
            if (!array_key_exists($resourcePath, $files)) {
                $missingResourceFiles[] = $resourcePath;
                if ($reason === null) {
                    $status = 'failed';
                    $reason = 'missing-resource-file';
                }
                $diagnostics[] = 'missing-resource-file:' . $resourcePath;
                continue;
            }

            $resourceArtifactsSha256[$resourcePath] = hash('sha256', $files[$resourcePath]);
        }
        if ($resourceArtifactsSha256 !== [] && $reason === null) {
            $diagnostics[] = 'resource-files-validated:' . count($resourceArtifactsSha256);
        }

        $expectedEngineArtifacts = $this->normalizePlanStringList($plan['expectedEngineArtifacts'] ?? [], 'PDF expected engine artifact');
        $reservedFiles = array_fill_keys(array_merge([$sourceFile, $outputFile], array_keys($sourceArtifactsSha256), $resourceFiles), true);
        foreach ($files as $path => $bytes) {
            if (isset($reservedFiles[$path])) {
                continue;
            }
            if (!in_array($path, $expectedEngineArtifacts, true) && !$this->isKnownEngineArtifact($path, $sourceFile, $engineArtifactStem)) {
                continue;
            }

            $producedArtifactsSha256[$path] = hash('sha256', $bytes);
            if ($this->isBibliographyArtifactPath($path)) {
                $bibliographyArtifactsSha256[$path] = hash('sha256', $bytes);
                if ($this->isBibliographyLogPath($path)) {
                    $bibliographyLogFiles[] = $path;
                    $bibliographyLogTexts[] = $bytes;
                }
            }
            if ($this->isEngineDependencyArtifactPath($path)) {
                $engineDependencyArtifactsSha256[$path] = hash('sha256', $bytes);
                try {
                    $dependencies = $this->extractEngineDependencyArtifact(
                        $path,
                        $bytes,
                        $engine === 'typst' ? $typstDependencyFormat : null
                    );
                } catch (\RuntimeException $exception) {
                    if ($reason === null) {
                        $status = 'failed';
                        $reason = 'engine-dependency-decode-error';
                    }
                    $diagnostics[] = 'engine-dependency-decode-error:' . $path . ':' . $exception->getMessage();
                    continue;
                }

                foreach ($dependencies['inputFiles'] as $inputFile) {
                    $engineInputFiles[$inputFile] = true;
                }
                foreach ($dependencies['externalInputFiles'] as $externalInputFile) {
                    $engineExternalInputFiles[$externalInputFile] = true;
                }
                foreach ($dependencies['externalDependencies'] as $externalDependency) {
                    if (
                        !is_array($externalDependency)
                        || !is_string($externalDependency['input'] ?? null)
                        || !is_string($externalDependency['raw'] ?? null)
                        || !is_string($externalDependency['kind'] ?? null)
                    ) {
                        continue;
                    }

                    $key = $externalDependency['input'] . "\0" . $externalDependency['raw'] . "\0" . $externalDependency['kind'];
                    $engineExternalDependencies[$key] = [
                        'input' => $externalDependency['input'],
                        'raw' => $externalDependency['raw'],
                        'kind' => $externalDependency['kind'],
                    ];
                }
                foreach ($dependencies['outputFiles'] as $outputFilePath) {
                    $engineOutputFiles[$outputFilePath] = true;
                }
                foreach ($dependencies['dependencyEdges'] as $dependencyEdge) {
                    $dependencyEdge['artifact'] = $path;
                    $engineDependencyEdges[] = $dependencyEdge;
                    $packageDependencies = $this->typstPackageDependenciesFor($dependencyEdge['externalInputFiles']);
                    if ($packageDependencies !== []) {
                        $typstDependencyEdgePackageProvenance[] = [
                            'artifact' => $path,
                            'outputFiles' => $dependencyEdge['outputFiles'],
                            'inputFiles' => $dependencyEdge['inputFiles'],
                            'externalInputFiles' => $dependencyEdge['externalInputFiles'],
                            'packageDependencies' => $packageDependencies,
                        ];
                    }
                }
            }
            if ($this->isSourceMapArtifactPath($path)) {
                $sourceMapFiles[] = $path;
                $sourceMapArtifactsSha256[$path] = hash('sha256', $bytes);
                try {
                    $sourceMap = $this->extractSourceMapArtifact($path, $bytes);
                } catch (\RuntimeException $exception) {
                    if ($reason === null) {
                        $status = 'failed';
                        $reason = 'source-map-decode-error';
                    }
                    $diagnostics[] = 'source-map-decode-error:' . $path . ':' . $exception->getMessage();
                    continue;
                }

                foreach ($sourceMap['inputs'] as $input) {
                    $sourceMapInputsByKey[$input['tag'] . ':' . $input['path']] = $input;
                }
                foreach ($sourceMap['inputFiles'] as $inputFile) {
                    $sourceMapInputFiles[$inputFile] = true;
                }
                foreach ($sourceMap['externalInputs'] as $externalInput) {
                    $sourceMapExternalInputs[$externalInput] = true;
                }
                foreach ($sourceMap['lineRanges'] as $range) {
                    $key = $range['tag'] . ':' . $range['path'];
                    if (!isset($sourceMapLineRangesByKey[$key])) {
                        $sourceMapLineRangesByKey[$key] = $range;
                        continue;
                    }
                    $sourceMapLineRangesByKey[$key]['minLine'] = min($sourceMapLineRangesByKey[$key]['minLine'], $range['minLine']);
                    $sourceMapLineRangesByKey[$key]['maxLine'] = max($sourceMapLineRangesByKey[$key]['maxLine'], $range['maxLine']);
                    $sourceMapLineRangesByKey[$key]['references'] += $range['references'];
                }
            }
            if ($this->isEngineLogPath($path)) {
                $engineLogFiles[] = $path;
                $engineLogTexts[] = $bytes;
            }
        }
        ksort($producedArtifactsSha256);
        ksort($engineDependencyArtifactsSha256);
        ksort($bibliographyArtifactsSha256);
        ksort($sourceMapArtifactsSha256);
        sort($engineLogFiles);
        sort($bibliographyLogFiles);
        sort($sourceMapFiles);
        if ($sourceIsStdin && isset($engineInputFiles['-'])) {
            unset($engineInputFiles['-']);
            $diagnostics[] = 'typst-source-input-dependency-stdin';
        }
        $engineInputFileList = array_keys($engineInputFiles);
        sort($engineInputFileList);
        $engineExternalInputFileList = array_keys($engineExternalInputFiles);
        sort($engineExternalInputFileList);
        $engineExternalDependencyList = array_values($engineExternalDependencies);
        usort(
            $engineExternalDependencyList,
            static fn (array $a, array $b): int => [$a['input'], $a['kind'], $a['raw']] <=> [$b['input'], $b['kind'], $b['raw']]
        );
        $engineOutputFileList = array_keys($engineOutputFiles);
        sort($engineOutputFileList);
        $engineTypstPackageInputList = array_values(array_filter(
            $engineExternalInputFileList,
            static fn (string $input): bool => str_starts_with($input, 'typst-package:')
        ));
        $engineTypstPackageDependencies = $this->typstPackageDependenciesFor($engineTypstPackageInputList);
        $typstImportPathPolicy = $this->typstImportPathPolicyWithSidecarPackageComparison(
            $engine,
            $typstImportPathPolicy,
            $engineTypstPackageInputList
        );
        $typstPackageDependencyPolicy = $this->typstPackageDependencyPolicy(
            $engine,
            $engineTypstPackageDependencies,
            $engineDependencyEdges,
            $engineDependencyArtifactsSha256
        );
        $typstExternalDependencyPolicy = $this->typstExternalDependencyPolicy(
            $engine,
            $engineDependencyArtifactsSha256,
            $engineExternalDependencyList
        );
        $typstDependencyOutputPolicy = $this->typstDependencyOutputPolicy(
            $engine,
            $engineDependencyArtifactsSha256,
            $outputFile,
            $engineOutputFileList
        );
        $engineBoundaryInputPaths = $sourceIsStdin
            ? $engineInputFileList
            : array_merge([$sourceFile], $engineInputFileList);
        $engineBoundaryViolations = $this->engineBoundaryViolationsFor(
            $engineBoundaryRoot,
            $engineBoundaryInputPaths
        );
        if ($engineBoundaryRoot !== null) {
            $diagnostics[] = 'engine-boundary-root:' . $engineBoundaryRoot;
        }
        if ($engineBoundaryViolations !== []) {
            if ($reason === null) {
                $status = 'failed';
                $reason = 'engine-boundary-violation';
            }
            $diagnostics[] = 'engine-boundary-violations:' . count($engineBoundaryViolations);
            foreach ($engineBoundaryViolations as $violation) {
                $diagnostics[] = 'engine-boundary-violation:' . $violation;
            }
        }
        $typstReadBoundaryPolicy = $this->typstReadBoundaryPolicy(
            $engine,
            $this->typstRootPathFromBoundaryProvenance($typstBoundaryProvenance),
            $sourceFile,
            $engineInputFileList
        );
        foreach ($engineInputFileList as $inputFile) {
            if (array_key_exists($inputFile, $files)) {
                continue;
            }

            $missingEngineInputFiles[] = $inputFile;
            if ($reason === null) {
                $status = 'failed';
                $reason = 'missing-engine-input-file';
            }
            $diagnostics[] = 'missing-engine-input-file:' . $inputFile;
        }
        $sourceMapInputs = array_values($sourceMapInputsByKey);
        usort($sourceMapInputs, static fn (array $a, array $b): int => [$a['tag'], $a['path']] <=> [$b['tag'], $b['path']]);
        $sourceMapInputFileList = array_keys($sourceMapInputFiles);
        sort($sourceMapInputFileList);
        $sourceMapExternalInputList = array_keys($sourceMapExternalInputs);
        sort($sourceMapExternalInputList);
        $sourceMapLineRanges = array_values($sourceMapLineRangesByKey);
        usort($sourceMapLineRanges, static fn (array $a, array $b): int => [$a['tag'], $a['path']] <=> [$b['tag'], $b['path']]);
        if ($producedArtifactsSha256 !== []) {
            $diagnostics[] = 'produced-engine-artifacts:' . count($producedArtifactsSha256);
        }
        if ($engineDependencyArtifactsSha256 !== []) {
            $diagnostics[] = 'engine-dependency-artifacts:' . count($engineDependencyArtifactsSha256);
        }
        if ($engineInputFileList !== []) {
            $diagnostics[] = 'engine-dependency-files:' . count($engineInputFileList);
        }
        if ($engineExternalInputFileList !== []) {
            $diagnostics[] = 'engine-external-input-files:' . count($engineExternalInputFileList);
        }
        if ($engineTypstPackageInputList !== []) {
            $diagnostics[] = 'engine-typst-package-inputs:' . count($engineTypstPackageInputList);
        }
        if ($engineTypstPackageDependencies !== []) {
            $diagnostics[] = 'engine-typst-package-dependencies:' . count($engineTypstPackageDependencies);
        }
        $this->appendTypstImportPathPolicyDiagnostics($diagnostics, $typstImportPathPolicy);
        if ($typstPackageDependencyPolicy !== []) {
            $diagnostics[] = 'typst-package-dependency-policy:' . $typstPackageDependencyPolicy['reviewStatus'];
            $diagnostics[] = 'typst-package-dependency-count:' . $typstPackageDependencyPolicy['packageDependencyCount'];
            $diagnostics[] = 'typst-package-dependency-policy-packages:' . $typstPackageDependencyPolicy['packageCount'];
            foreach (($typstPackageDependencyPolicy['sourceClassCounts'] ?? []) as $sourceClass => $count) {
                $diagnostics[] = 'typst-package-dependency-source:' . $sourceClass . ':' . $count;
            }
            foreach (($typstPackageDependencyPolicy['unsupportedReasonCounts'] ?? []) as $reasonKey => $count) {
                $diagnostics[] = 'typst-package-unsupported-reason:' . $reasonKey . ':' . $count;
            }
            if (($typstPackageDependencyPolicy['duplicateDependencyCount'] ?? 0) > 0) {
                $diagnostics[] = 'typst-package-dependency-duplicates:' . $typstPackageDependencyPolicy['duplicateDependencyCount'];
                $diagnostics[] = 'typst-package-dependency-duplicate-groups:' . count($typstPackageDependencyPolicy['duplicateDependencySummaries'] ?? []);
                foreach (($typstPackageDependencyPolicy['duplicateDependencySummaries'] ?? []) as $summary) {
                    if (!is_array($summary) || !is_string($summary['packageCoordinate'] ?? null)) {
                        continue;
                    }
                    $diagnostics[] = 'typst-package-dependency-duplicate:' . $summary['packageCoordinate'] . ':' . ($summary['dependencyCount'] ?? 0);
                }
            }
            if ($typstPackageDependencyPolicy['sidecarFileCount'] > 0) {
                $diagnostics[] = 'typst-package-dependency-policy-sidecars:' . $typstPackageDependencyPolicy['sidecarFileCount'];
            }
            if ($typstPackageDependencyPolicy['versionConflictCount'] > 0) {
                $diagnostics[] = 'typst-package-dependency-policy-conflicts:' . $typstPackageDependencyPolicy['versionConflictCount'];
            }
            if ($typstPackageDependencyPolicy['issues'] !== []) {
                $diagnostics[] = 'typst-package-dependency-policy-issues:' . count($typstPackageDependencyPolicy['issues']);
            }
            if ($typstPackageDependencyPolicy['subpathDependencyCount'] > 0) {
                $diagnostics[] = 'typst-package-dependency-subpaths:' . $typstPackageDependencyPolicy['subpathDependencyCount'];
            }
        }
        if ($typstExternalDependencyPolicy !== []) {
            $diagnostics[] = 'typst-external-dependency-policy:' . $typstExternalDependencyPolicy['reviewStatus'];
            $diagnostics[] = 'typst-external-dependencies:' . $typstExternalDependencyPolicy['externalDependencyCount'];
            if ($typstExternalDependencyPolicy['issues'] !== []) {
                $diagnostics[] = 'typst-external-dependency-issues:' . count($typstExternalDependencyPolicy['issues']);
            }
        }
        if ($engineDependencyEdges !== []) {
            $diagnostics[] = 'engine-dependency-edges:' . count($engineDependencyEdges);
        }
        if ($typstDependencyEdgePackageProvenance !== []) {
            $diagnostics[] = 'typst-dependency-edge-package-provenance:' . count($typstDependencyEdgePackageProvenance);
