                if ($pdfEmbeddedFiles !== []) {
                    $diagnostics[] = 'pdf-byte-embedded-file-metadata:' . count($pdfEmbeddedFiles);
                    $embeddedStreams = 0;
                    $embeddedCollectionItems = 0;
