            'missingResourceFiles' => is_array($finalRun) && is_array($finalRun['missingResourceFiles'] ?? null) ? $finalRun['missingResourceFiles'] : [],
            'missingEngineInputFiles' => is_array($finalRun) && is_array($finalRun['missingEngineInputFiles'] ?? null) ? $finalRun['missingEngineInputFiles'] : [],
            'missingEngineTranscriptInputFiles' => is_array($finalRun) && is_array($finalRun['missingEngineTranscriptInputFiles'] ?? null) ? $finalRun['missingEngineTranscriptInputFiles'] : [],
            'engineMissingProgram' => is_array($finalRun) && ($finalRun['engineMissingProgram'] ?? false) === true,
            'engineMissingProgramName' => is_array($finalRun) && is_string($finalRun['engineMissingProgramName'] ?? null) ? $finalRun['engineMissingProgramName'] : null,
            'finalEngineMissingDependencies' => is_array($finalRun) && is_array($finalRun['engineMissingDependencies'] ?? null) ? $finalRun['engineMissingDependencies'] : [],
            'finalEngineMissingDependencyKinds' => is_array($finalRun) && is_array($finalRun['engineMissingDependencyKinds'] ?? null) ? $finalRun['engineMissingDependencyKinds'] : [],
            'engineMissingDependencies' => $engineMissingDependencies,
            'engineMissingDependencyKinds' => $engineMissingDependencyKinds,
            'engineWarnings' => array_values(array_unique($warnings)),
            'engineErrors' => array_values(array_unique($errors)),
            'bibliographyWarnings' => array_values(array_unique($bibliographyWarnings)),
            'bibliographyErrors' => array_values(array_unique($bibliographyErrors)),
            'bibliographyNeeded' => $finalBibliographyNeeded,
            'rerunNeeded' => $finalRerunNeeded,
            'diagnostics' => $diagnostics,
        ];
    }

    private function engineName(string $engineProgram): string
    {
        $engineProgram = $this->requireString($engineProgram, 'PDF engine');
        $normalized = str_replace('\\', '/', $engineProgram);
        $basename = strtolower(basename($normalized));

        return preg_replace('/(?:\.exe|\.bat|\.cmd)\z/i', '', $basename) ?? $basename;
    }

    /**
     * @param array{family:string, intermediate:string, extension:string, defaultArgs:list<string>} $profile
     * @param list<string> $engineOptions
     * @return list<string>
     */
    private function argvFor(string $program, string $engine, array $profile, string $sourceFile, string $outputFile, array $engineOptions): array
    {
        $argv = [$program];

        if ($engine === 'typst') {
            return array_merge($argv, ['compile'], $engineOptions, [$sourceFile, $outputFile]);
        }

        if ($engine === 'pdfroff') {
            return array_merge($argv, $engineOptions, ['-o', $outputFile, $sourceFile]);
        }

        if ($engine === 'prince' || $engine === 'pagedjs-cli') {
            return array_merge($argv, $engineOptions, [$sourceFile, '-o', $outputFile]);
        }

        if ($profile['family'] === 'html') {
            return array_merge($argv, $engineOptions, [$sourceFile, $outputFile]);
        }

        return array_merge($argv, $profile['defaultArgs'], $engineOptions, [$sourceFile]);
    }

    /**
     * @param list<string> $includeInHeaderFiles
     * @param list<string> $resourcePaths
     * @param array<string, mixed> $variables
     * @return list<string>
     */
    private function writerArgumentsFor(?string $templateFile, array $includeInHeaderFiles, array $resourcePaths, array $variables): array
    {
        $arguments = [];
        if ($templateFile !== null) {
            $arguments[] = '--template=' . $templateFile;
        }
        foreach ($includeInHeaderFiles as $path) {
            $arguments[] = '--include-in-header=' . $path;
        }
        if ($resourcePaths !== []) {
            $arguments[] = '--resource-path=' . implode(':', $resourcePaths);
        }
        foreach ($this->flattenVariableArguments($variables) as $argument) {
            $arguments[] = '-V';
            $arguments[] = $argument;
        }

        return $arguments;
    }

    /**
     * @param array<string, mixed> $variables
     * @return list<string>
     */
    private function flattenVariableArguments(array $variables, string $prefix = ''): array
    {
        $arguments = [];
        foreach ($variables as $name => $value) {
            $variableName = $prefix === '' ? (string) $name : $prefix . '.' . $name;
            if (is_array($value) && !array_is_list($value)) {
                array_push($arguments, ...$this->flattenVariableArguments($value, $variableName));
                continue;
            }

            if (is_array($value)) {
                foreach ($value as $item) {
                    $arguments[] = $variableName . '=' . $this->templateVariableScalar($item, $variableName);
                }
                continue;
            }

            $arguments[] = $variableName . '=' . $this->templateVariableScalar($value, $variableName);
        }

        return $arguments;
    }

    private function templateVariableScalar(mixed $value, string $name): string
    {
        if ($value === null) {
            return '';
        }
        if (is_bool($value)) {
            return $value ? 'true' : 'false';
        }
        if (is_int($value) || is_float($value)) {
            return (string) $value;
        }
        if (!is_string($value)) {
            throw new \InvalidArgumentException('PDF template variable ' . $name . ' must be scalar');
        }

        return $value;
    }

    private function renderIntermediateSource(AstNode $document, string $intermediateFormat): ?string
    {
        if ($intermediateFormat === 'latex') {
            return (new LatexWriter())->write($document);
        }

        return null;
    }

    /**
     * @return array<string, mixed>
     */
    private function metadataSummary(AstNode $document): array
    {
        $metadata = $document->attr('meta', $document->attr('metadata', []));
        if (!is_array($metadata)) {
            return [];
        }

        $summary = [];
        foreach (['title', 'author', 'authors', 'date', 'lang', 'papersize', 'geometry', 'documentclass'] as $key) {
            if (array_key_exists($key, $metadata)) {
                $summary[$key] = $this->normalizeMetadataValue($metadata[$key]);
            }
        }

        return $summary;
    }

    private function normalizeMetadataValue(mixed $value): mixed
    {
        if (is_scalar($value) || $value === null) {
            return $value;
        }

        if (is_array($value)) {
            $normalized = [];
            foreach ($value as $key => $item) {
                $normalized[$key] = $this->normalizeMetadataValue($item);
            }

            return $normalized;
        }

        return (string) $value;
    }

    /**
     * @return array{
     *     files:list<string>,
     *     manifest:list<array{path:string, kind:string, sources:list<string>, title:string|null, alt:string|null}>,
     *     remote:list<string>,
     *     skipped:list<string>
     * }
     */
    private function resourceInventoryFor(AstNode $document, mixed $explicitResourceFiles): array
    {
        $entries = [];
        $remote = [];
        $skipped = [];

        foreach ($this->normalizeResourceFileList($explicitResourceFiles, 'PDF resource file') as $path) {
            $this->addResourceEntry($entries, $path, 'resource', 'explicit');
        }

        $this->collectDocumentResources($document, $entries, $remote, $skipped);
        ksort($entries);
        sort($remote);
        sort($skipped);

        return [
            'files' => array_keys($entries),
            'manifest' => array_values($entries),
            'remote' => array_values(array_unique($remote)),
            'skipped' => array_values(array_unique($skipped)),
        ];
    }

    /**
     * @param array<string, array{path:string, kind:string, sources:list<string>, title:string|null, alt:string|null}> $entries
     * @param list<string> $remote
     * @param list<string> $skipped
     */
    private function collectDocumentResources(AstNode $node, array &$entries, array &$remote, array &$skipped): void
    {
        if ($node->type === 'image') {
            $url = $node->attr('url', '');
            if (is_string($url)) {
                $classified = $this->classifyResourceReference($url);
                if ($classified['type'] === 'local') {
                    $this->addResourceEntry(
                        $entries,
                        $classified['value'],
                        'image',
                        'document-image',
                        $this->nullableString($node->attr('title', null)),
                        $this->nullableString($node->attr('alt', null))
                    );
                } elseif ($classified['type'] === 'remote') {
                    $remote[] = $classified['value'];
                } else {
                    $skipped[] = $classified['value'];
                }
            }
        }

        foreach ($node->children as $child) {
            $this->collectDocumentResources($child, $entries, $remote, $skipped);
        }
    }

    /**
     * @param array<string, array{path:string, kind:string, sources:list<string>, title:string|null, alt:string|null}> $entries
     */
    private function addResourceEntry(
        array &$entries,
        string $path,
        string $kind,
        string $source,
        ?string $title = null,
        ?string $alt = null
    ): void {
        if (!isset($entries[$path])) {
            $entries[$path] = [
                'path' => $path,
                'kind' => $kind,
                'sources' => [],
                'title' => null,
                'alt' => null,
            ];
        }

        if (!in_array($source, $entries[$path]['sources'], true)) {
            $entries[$path]['sources'][] = $source;
        }
        if ($kind === 'image') {
            $entries[$path]['kind'] = 'image';
        }
        if ($entries[$path]['title'] === null && $title !== null && $title !== '') {
            $entries[$path]['title'] = $title;
        }
        if ($entries[$path]['alt'] === null && $alt !== null && $alt !== '') {
            $entries[$path]['alt'] = $alt;
        }
    }

    /**
     * @return array{type:string, value:string}
     */
    private function classifyResourceReference(string $reference): array
    {
        $reference = str_replace('\\', '/', trim($reference));
        if ($reference === '') {
            return ['type' => 'skipped', 'value' => 'empty-resource-reference'];
        }
        if (str_contains($reference, "\0")) {
            return ['type' => 'skipped', 'value' => 'resource-reference-contains-nul'];
        }
        if ($this->isUriResourceReference($reference)) {
            return ['type' => 'remote', 'value' => $reference];
        }
        if (str_starts_with($reference, '#') || str_contains($reference, '?') || str_contains($reference, '#')) {
            return ['type' => 'skipped', 'value' => $reference];
        }

        try {
            return ['type' => 'local', 'value' => $this->normalizeRelativePath($reference, 'PDF document resource path')];
        } catch (\InvalidArgumentException) {
            return ['type' => 'skipped', 'value' => $reference];
        }
    }

    private function isUriResourceReference(string $reference): bool
    {
        return str_starts_with($reference, '//')
            || preg_match('/\A[A-Za-z][A-Za-z0-9+.-]*:/', $reference) === 1;
    }

    private function nullableString(mixed $value): ?string
    {
        return is_string($value) ? $value : null;
    }

    private function deriveSourcePath(string $outputFile, string $extension): string
    {
        $lastSlash = strrpos($outputFile, '/');
        $directory = $lastSlash === false ? '' : substr($outputFile, 0, $lastSlash + 1);
        $basename = $lastSlash === false ? $outputFile : substr($outputFile, $lastSlash + 1);
        $stem = preg_replace('/\.pdf\z/i', '', $basename) ?? 'document';
        if ($stem === '') {
            $stem = 'document';
        }

        return $directory . $stem . '.' . $extension;
    }

    /**
     * @return array{mode:string, sourceFile:string, path:string|null, stagedAsFile:bool, reviewStatus:string, issues:list<string>}|array{}
     */
    private function sourceInputFor(string $engine, string $sourceFile): array
    {
        if ($engine !== 'typst' || $sourceFile !== '-') {
            return [];
        }

        return [
            'mode' => 'stdin',
            'sourceFile' => '-',
            'path' => null,
            'stagedAsFile' => false,
            'reviewStatus' => 'review',
            'issues' => ['source-stdin-boundary'],
        ];
    }

    /**
     * @return list<string>
     */
    private function engineArtifactStemFor(string $family, string $sourceFile, array $engineOptions): string
    {
        $sourceStem = $this->sourceStem($sourceFile);
        if ($family !== 'latex' && $family !== 'context') {
            return $sourceStem;
        }

        $directory = $this->sourceDirectory($sourceStem);
        $basename = $this->sourceBasename($sourceStem);
        $jobName = $family === 'latex'
            ? $this->safeEngineJobName($this->engineOptionValue($engineOptions, ['-jobname', '--jobname']))
            : null;
        $outputDirectory = $family === 'latex'
            ? $this->safeEngineOutputDirectory($this->engineOptionValue($engineOptions, ['-output-directory', '--output-directory', '-outdir', '--outdir']))
            : null;

        if ($jobName !== null) {
            $basename = $jobName;
        }
        if ($outputDirectory !== null) {
            $directory = $outputDirectory;
        }

        return $directory === '' ? $basename : $directory . '/' . $basename;
    }

    /**
     * @return list<string>
     */
    private function expectedEngineArtifactsFor(string $engine, string $family, string $artifactStem): array
    {
        $extensions = [];

        if ($family === 'latex') {
            $extensions = ['log', 'aux', 'out', 'toc'];
            if ($engine === 'latexmk') {
                $extensions[] = 'fls';
                $extensions[] = 'fdb_latexmk';
            }
        } elseif ($family === 'context') {
            $extensions = ['log', 'tuc'];
        }

        $artifacts = [];
        foreach ($extensions as $extension) {
            $artifacts[] = $artifactStem . '.' . $extension;
        }

        return $artifacts;
    }

    /**
     * @param list<string> $engineOptions
     */
    private function sourceMapFileFor(string $family, string $artifactStem, array $engineOptions): ?string
    {
        if ($family !== 'latex') {
            return null;
        }

        foreach ($engineOptions as $option) {
            if ($this->isSyncTexEngineOption($option)) {
                return $artifactStem . '.synctex.gz';
            }
        }

        return null;
    }

    /**
     * @param list<string> $engineOptions
     */
    private function engineDependencyFileFor(string $engine, string $family, string $artifactStem, array $engineOptions): ?string
    {
        if ($engine !== 'typst' || $family !== 'typst') {
            return null;
        }

        $values = $this->engineOptionValues($engineOptions, ['--deps', '--make-deps'], true, true);
        if ($values === []) {
            return null;
        }

        $entry = $this->typstBoundaryFileEntry($values[count($values) - 1], 'dependency-output');

        return ($entry['safe'] ?? false) === true && ($entry['kind'] ?? null) === 'relative'
            ? $entry['path']
            : null;
    }

    /**
     * @param list<string> $engineOptions
     */
    private function typstTimingOutputFileFor(string $engine, string $family, array $engineOptions): ?string
    {
        if ($engine !== 'typst' || $family !== 'typst') {
            return null;
        }

        $values = $this->engineOptionValues($engineOptions, ['--timings', '-t'], true);
        if ($values === []) {
            return null;
        }

        $entry = $this->typstBoundaryFileEntry($values[count($values) - 1], 'timings-output');

        return ($entry['safe'] ?? false) === true && ($entry['kind'] ?? null) === 'relative'
            ? $entry['path']
            : null;
    }

    /**
     * @param list<string> $engineOptions
     */
    private function engineBoundaryRootFor(string $engine, string $family, array $engineOptions, array $engineEnvironment = []): ?string
    {
        if ($engine !== 'typst' || $family !== 'typst') {
            return null;
        }

        $rootValues = $this->engineOptionValues($engineOptions, ['--root'], true);
        if ($rootValues === [] && array_key_exists('TYPST_ROOT', $engineEnvironment)) {
            $rootValues = [$engineEnvironment['TYPST_ROOT']];
        }
        if ($rootValues === []) {
            return null;
        }
        $root = $this->typstBoundaryPathEntry($rootValues[count($rootValues) - 1], 'root');
        if (($root['safe'] ?? false) !== true || !is_string($root['path'] ?? null) || $root['path'] === '') {
            return null;
        }

        return $root['path'];
    }

    /**
     * @param list<string> $paths
     * @return list<string>
     */
    private function engineBoundaryViolationsFor(?string $boundaryRoot, array $paths): array
    {
        if ($boundaryRoot === null || $boundaryRoot === '.') {
            return [];
        }

        $violations = [];
        foreach ($paths as $path) {
            if (!is_string($path) || $path === '') {
                continue;
            }
            if ($path === $boundaryRoot || str_starts_with($path, $boundaryRoot . '/')) {
                continue;
            }

            $violations[$path] = true;
        }

        $violationList = array_keys($violations);
        sort($violationList);

        return $violationList;
    }

    /**
     * @param list<string> $engineOptions
     */
    private function recorderFileFor(string $engine, string $family, string $artifactStem, array $engineOptions): ?string
    {
        if ($family !== 'latex') {
            return null;
        }
        if ($engine === 'latexmk') {
            return $artifactStem . '.fls';
        }

        foreach ($engineOptions as $option) {
            if ($this->isRecorderEngineOption($option)) {
                return $artifactStem . '.fls';
            }
        }

        return null;
    }

    private function isSyncTexEngineOption(string $option): bool
    {
        $option = strtolower(trim($option));
        if (!str_contains($option, 'synctex')) {
            return false;
        }

        return preg_match('/synctex\s*=\s*(?:0|false|off|no)\b/i', $option) !== 1;
    }

    private function isRecorderEngineOption(string $option): bool
    {
        $option = strtolower(trim($option));
        if (!str_contains($option, 'recorder')) {
            return false;
        }

        return preg_match('/recorder\s*=\s*(?:0|false|off|no)\b/i', $option) !== 1;
    }

    /**
     * @param list<string> $artifacts
     */
    private function firstEngineLogFile(array $artifacts): ?string
    {
        foreach ($artifacts as $artifact) {
            if ($this->isEngineLogPath($artifact)) {
                return $artifact;
            }
        }

        return null;
    }

    private function sourceStem(string $sourceFile): string
    {
        $lastSlash = strrpos($sourceFile, '/');
        $lastDot = strrpos($sourceFile, '.');
        if ($lastDot !== false && ($lastSlash === false || $lastDot > $lastSlash)) {
            return substr($sourceFile, 0, $lastDot);
        }

        return $sourceFile;
    }

    private function sourceDirectory(string $path): string
    {
        $lastSlash = strrpos($path, '/');

        return $lastSlash === false ? '' : substr($path, 0, $lastSlash);
    }

    private function sourceBasename(string $path): string
    {
        $lastSlash = strrpos($path, '/');

        return $lastSlash === false ? $path : substr($path, $lastSlash + 1);
    }

    /**
     * @param list<string> $engineOptions
     * @return array{reviewStatus:string, declaredOutputFile:string, inferredOutputFormat:string, explicitFormat:string|null, formatOptions:list<string>, issues:list<string>}|array{}
     */
    private function typstOutputFormatPolicyFor(string $engine, string $outputFile, array $engineOptions): array
    {
        if ($engine !== 'typst') {
            return [];
        }

        $issues = [];
        $formatOptions = [];
        $formatHistory = [];
        $formatValues = $this->typstOutputFormatOptionValues($engineOptions);
        foreach ($formatValues as $value) {
            $entry = $this->typstOutputFormatEntry($value);
            $formatHistory[] = $entry;
            foreach ($entry['issues'] as $issue) {
                $issues[] = $issue;
            }
            if ($entry['format'] === null) {
                continue;
            }

            $formatOptions[] = $entry['format'];
        }

        $inferredOutputFormat = strtolower((string) pathinfo($outputFile, PATHINFO_EXTENSION));
        if ($inferredOutputFormat === '') {
            $inferredOutputFormat = 'unknown';
        }

        if ($inferredOutputFormat !== 'pdf') {
            $issues[] = 'output-extension-not-pdf:' . $inferredOutputFormat;
        }

        $explicitFormat = $formatOptions === [] ? null : $formatOptions[count($formatOptions) - 1];
        $distinctFormats = array_values(array_unique($formatOptions));
        $overrides = [];
        if (count($distinctFormats) > 1) {
            $issues[] = 'conflicting-format-options:' . count($distinctFormats);
        }
        if (count($formatValues) > 1) {
            $overrides[] = [
                'option' => 'format',
                'count' => count($formatValues),
                'values' => $formatValues,
                'selected' => $formatValues[count($formatValues) - 1],
                'issue' => 'format-boundary-overridden',
            ];
            $issues[] = 'format-boundary-overridden';
        }
        if ($explicitFormat !== null && $explicitFormat !== 'pdf') {
            $issues[] = 'explicit-format-not-pdf:' . $explicitFormat;
        }

        $policy = [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'declaredOutputFile' => $outputFile,
            'inferredOutputFormat' => $inferredOutputFormat,
            'explicitFormat' => $explicitFormat,
            'formatOptions' => $formatOptions,
            'issues' => array_values(array_unique($issues)),
        ];
        if (count($formatValues) > 1 || in_array('', $formatValues, true)) {
            $policy['formatHistory'] = $formatHistory;
        }
        if ($overrides !== []) {
            $policy['overrides'] = $overrides;
        }

        return $policy;
    }

    /**
     * @param list<string> $engineOptions
     * @return list<string>
     */
    private function typstOutputFormatOptionValues(array $engineOptions): array
    {
        $values = [];
        $count = count($engineOptions);
        foreach ($engineOptions as $index => $option) {
            $option = trim($option);
            if ($option === '-f') {
                $next = $engineOptions[$index + 1] ?? '';
                $values[] = is_string($next) && $next !== '' && !str_starts_with($next, '-')
                    ? $next
                    : '';
                continue;
            }
            if (str_starts_with($option, '-f=')) {
                $values[] = substr($option, strlen('-f='));
                continue;
            }
            if (strlen($option) > 2 && str_starts_with($option, '-f') && !str_starts_with($option, '--')) {
                $value = substr($option, 2);
                $values[] = str_starts_with($value, '=') ? substr($value, 1) : $value;
                continue;
            }
            if ($option === '--format') {
                $next = $engineOptions[$index + 1] ?? '';
                $values[] = is_string($next) && $next !== '' && !str_starts_with($next, '-')
                    ? $next
                    : '';
                continue;
            }
            if (str_starts_with($option, '--format=')) {
                $values[] = substr($option, strlen('--format='));
            }
        }

        return $values;
    }

    /**
     * @return array{raw:string, value:string, format:string|null, safe:bool, issues:list<string>}
     */
    private function typstOutputFormatEntry(string $raw): array
    {
        $value = strtolower(trim($raw));
        if ($value === '') {
            return [
                'raw' => $raw,
                'value' => '',
                'format' => null,
                'safe' => false,
                'issues' => ['missing-format-value'],
            ];
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'format' => $value,
            'safe' => $value === 'pdf',
            'issues' => $value === 'pdf' ? [] : ['explicit-format-not-pdf:' . $value],
        ];
    }

    /**
     * @param list<string> $engineOptions
     * @param list<string> $names
     */
    private function engineOptionValue(array $engineOptions, array $names, bool $preserveMissing = false): ?string
    {
        $values = $this->engineOptionValues($engineOptions, $names, $preserveMissing);

        return $values === [] ? null : $values[count($values) - 1];
    }

    /**
     * @param list<string> $engineOptions
     * @param list<string> $names
     * @return list<string>
     */
    private function engineOptionValues(
        array $engineOptions,
        array $names,
        bool $preserveMissing = false,
        bool $allowSingleDashValue = false,
        ?string $dashPrefixedValuePattern = null
    ): array
    {
        $values = [];
        $count = count($engineOptions);
        foreach ($engineOptions as $index => $option) {
            $option = trim($option);
            foreach ($names as $name) {
                if ($option === $name) {
                    $next = $engineOptions[$index + 1] ?? null;
                    if (
                        $index + 1 < $count
                        && is_string($next)
                        && $next !== ''
                        && ($next === '-'
                            ? $allowSingleDashValue
                            : (!str_starts_with($next, '-')
                                || ($dashPrefixedValuePattern !== null && preg_match($dashPrefixedValuePattern, $next) === 1)))
                    ) {
                        $values[] = $next;
                        continue;
                    }
                    if ($preserveMissing) {
                        $values[] = '';
                    }
                    continue;
                }
                if (str_starts_with($option, $name . '=')) {
                    $values[] = substr($option, strlen($name) + 1);
                    continue;
                }
                if (strlen($name) === 2 && str_starts_with($name, '-') && !str_starts_with($name, '--') && str_starts_with($option, $name) && strlen($option) > 2) {
                    $value = substr($option, 2);
                    $values[] = str_starts_with($value, '=') ? substr($value, 1) : $value;
                }
            }
        }

        return $values;
    }

    /**
     * @param list<string> $engineOptions
     * @return list<string>
     */
    private function typstFontPathValues(array $engineOptions): array
    {
        $values = [];
        foreach ($this->engineOptionValues($engineOptions, ['--font-path'], true) as $value) {
            array_push($values, ...$this->splitTypstFontPathValue($value));
        }

        return $values;
    }

    /**
     * @return list<string>
     */
    private function splitTypstFontPathValue(string $raw): array
    {
        $value = str_replace('\\', '/', trim($raw));
        if ($value === '' || !str_contains($raw, PATH_SEPARATOR)) {
            return [$raw];
        }
        if (PATH_SEPARATOR === ':'
            && (preg_match('/\A[A-Za-z]:\//', $value) === 1
                || preg_match('/\A[A-Za-z][A-Za-z0-9+.-]*:\/\//', $value) === 1)
        ) {
            return [$raw];
        }

        return explode(PATH_SEPARATOR, $raw);
    }

    /**
     * @param list<string> $engineOptions
     */
    private function engineOptionFlagCount(array $engineOptions, string $name): int
    {
        $count = 0;
        foreach ($engineOptions as $option) {
            if (trim($option) === $name) {
                $count++;
            }
        }

        return $count;
    }

    /**
     * @return list<string>
     */
    private function typstEnvironmentPathListValues(string $raw): array
    {
        return $this->splitTypstFontPathValue($raw);
    }

    /**
     * @return array{raw:string, value:string, enabled:bool, safe:bool, issues:list<string>}
     */
    private function typstEnvironmentFlagEntry(string $raw, string $kind): array
    {
        $value = strtolower(trim($raw));
        $issues = [];
        $enabled = false;

        if (in_array($value, ['1', 'true', 'yes', 'on'], true)) {
            $enabled = true;
        } elseif (!in_array($value, ['0', 'false', 'no', 'off'], true)) {
            $issues[] = $kind . '-environment-invalid-boundary';
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'enabled' => $enabled,
            'safe' => $issues === [],
            'issues' => $issues,
        ];
    }

    /**
     * @param list<string> $engineOptions
     * @return list<array{raw:string|null, viewer:string|null, mode:string, safe:bool, issues:list<string>}>
     */
    private function typstOpenOutputEntries(array $engineOptions): array
    {
        $entries = [];
        foreach ($engineOptions as $index => $option) {
            $option = trim($option);
            if ($option === '--open') {
                $next = $engineOptions[$index + 1] ?? null;
                $raw = is_string($next) && $next !== '' && !str_starts_with($next, '-')
                    ? $next
                    : null;
                $entries[] = $this->typstOpenOutputEntry($raw);
                continue;
            }
            if (str_starts_with($option, '--open=')) {
                $entries[] = $this->typstOpenOutputEntry(substr($option, strlen('--open=')));
            }
        }

        return $entries;
    }

    /**
     * @return array{raw:string|null, viewer:string|null, mode:string, safe:bool, issues:list<string>}
     */
    private function typstOpenOutputEntry(?string $raw): array
    {
        if ($raw === null) {
            return [
                'raw' => null,
                'viewer' => null,
                'mode' => 'default-viewer',
                'safe' => false,
                'issues' => [],
            ];
        }

        $viewer = trim($raw);
        $issues = [];
        if ($viewer === '') {
            $issues[] = 'open-output-viewer-empty-boundary';
        } elseif (str_contains($raw, "\0") || preg_match('/[[:cntrl:]]/', $raw) === 1) {
            $issues[] = 'open-output-viewer-invalid-boundary';
        }

        return [
            'raw' => $raw,
            'viewer' => $viewer,
            'mode' => 'specific-viewer',
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @param array<string, list<string>> $optionValues
     * @return list<array{option:string, count:int, values:list<string>, selected:string, issue:string}>
     */
    private function typstBoundaryOverrideEntries(array $optionValues): array
    {
        $issueByOption = [
            'root' => 'root-boundary-overridden',
            'packagePath' => 'package-path-boundary-overridden',
            'packageCache' => 'package-cache-boundary-overridden',
            'pages' => 'pages-boundary-overridden',
            'ppi' => 'ppi-boundary-overridden',
            'pdfStandard' => 'pdf-standard-boundary-overridden',
            'features' => 'features-boundary-overridden',
            'jobs' => 'jobs-boundary-overridden',
            'dependencyOutput' => 'dependency-output-boundary-overridden',
            'timingsOutput' => 'timings-output-boundary-overridden',
            'diagnosticFormat' => 'diagnostic-format-boundary-overridden',
            'diagnosticColor' => 'diagnostic-color-boundary-overridden',
            'dependencyFormat' => 'dependency-format-boundary-overridden',
            'creationTimestamp' => 'creation-timestamp-boundary-overridden',
            'outputFormat' => 'format-boundary-overridden',
        ];
        $entries = [];
        foreach ($optionValues as $option => $values) {
            if (count($values) < 2) {
                continue;
            }
            $values = array_values($values);
            $entries[] = [
                'option' => $option,
                'count' => count($values),
                'values' => $values,
                'selected' => $values[count($values) - 1],
                'issue' => $issueByOption[$option] ?? $option . '-boundary-overridden',
            ];
        }

        return $entries;
    }

