        }
        if ($certificatePolicy !== []) {
            $provenance['certificatePolicy'] = $certificatePolicy;
        }
        if ($fontPathPolicy !== []) {
            $provenance['fontPathPolicy'] = $fontPathPolicy;
        }
        if ($packageStoragePolicy !== []) {
            $provenance['packageStoragePolicy'] = $packageStoragePolicy;
        }
        if ($creationTimestamp !== null) {
            $provenance['creationTimestamp'] = $creationTimestamp;
        }
        if ($creationTimestampEnvironmentShadow !== null) {
            $provenance['creationTimestampEnvironment'] = $creationTimestampEnvironmentShadow;
        }
        if ($rootEnvironmentShadow !== null) {
            $provenance['rootEnvironment'] = $rootEnvironmentShadow;
        }
        if ($packagePathEnvironmentShadow !== null) {
            $provenance['packagePathEnvironment'] = $packagePathEnvironmentShadow;
        }
        if ($packageCacheEnvironmentShadow !== null) {
            $provenance['packageCacheEnvironment'] = $packageCacheEnvironmentShadow;
        }
        if ($certificateEnvironmentShadow !== null) {
            $provenance['certificateEnvironment'] = $certificateEnvironmentShadow;
        }
        if ($pdfStandard !== null) {
            $provenance['pdfStandard'] = $pdfStandard;
        }
        if ($pdfStandardPolicy !== []) {
            $provenance['pdfStandardPolicy'] = $pdfStandardPolicy;
        }
        if ($featureGates !== null) {
            $provenance['featureGates'] = $featureGates;
        }
        if ($featureGateEnvironmentShadow !== null) {
            $provenance['featureGateEnvironment'] = $featureGateEnvironmentShadow;
        }
        if ($jobs !== null) {
            $jobIssues = [];
            foreach ($jobsHistory as $entry) {
                foreach ($entry['issues'] as $issue) {
                    $jobIssues[] = $issue;
                }
            }
            foreach ($overrides as $override) {
                if ($override['option'] === 'jobs') {
                    $jobIssues[] = $override['issue'];
                }
            }
            $provenance['executionPolicy'] = [
                'jobs' => $jobs,
                'issues' => array_values(array_unique($jobIssues)),
            ];
        }
        if ($timingsOutput !== null) {
            $provenance['timingsOutput'] = $timingsOutput;
        }
        if ($diagnosticFormat !== null || $diagnosticColor !== null) {
            $diagnosticOutputIssues = [];
            foreach (array_filter([$diagnosticFormat, $diagnosticColor]) as $entry) {
                foreach ($entry['issues'] as $issue) {
                    $diagnosticOutputIssues[] = $issue;
                }
            }
            $provenance['diagnosticOutput'] = [
                'format' => $diagnosticFormat,
                'color' => $diagnosticColor,
                'issues' => array_values(array_unique($diagnosticOutputIssues)),
            ];
        }
        if ($dependencyOutputFile !== null || $dependencyFormat !== null) {
            $dependencyOutputIssues = [];
            foreach (array_filter([$dependencyOutputFile, $dependencyFormat]) as $entry) {
                foreach ($entry['issues'] as $issue) {
                    $dependencyOutputIssues[] = $issue;
                }
            }
            $provenance['dependencyOutput'] = [
                'file' => $dependencyOutputFile,
                'format' => $dependencyFormat,
                'issues' => array_values(array_unique($dependencyOutputIssues)),
            ];
        }
        if ($outputFormat !== null) {
            $provenance['outputFormat'] = $outputFormat;
            $provenance['outputFormatPolicy'] = $outputFormatPolicy;
        }
        if ($inputVariableOverrides !== []) {
            $provenance['inputVariableOverrides'] = $inputVariableOverrides;
        }
        if ($inputVariablePolicy !== []) {
            $provenance['inputVariablePolicy'] = $inputVariablePolicy;
        }
        if ($ignoreSystemFontCount > 0 || ($systemFontEnvironmentFlag['issues'] ?? []) !== []) {
            $provenance['systemFonts'] = [
                'ignoreSystemFonts' => $ignoreSystemFontCount > 0,
                'systemFontAccess' => $ignoreSystemFontCount > 0 ? 'disabled' : 'default',
                'flagCount' => $ignoreSystemFontCount,
                'fontPathCount' => count($fontPaths),
                'issues' => $systemFontEnvironmentFlag['issues'] ?? [],
            ];
            if ($systemFontEnvironmentFlag !== null) {
                $provenance['systemFonts']['environmentVariable'] = 'TYPST_IGNORE_SYSTEM_FONTS';
                $provenance['systemFonts']['environmentValue'] = $systemFontEnvironmentFlag['raw'];
            }
        }
        if ($ignoreEmbeddedFontCount > 0 || ($embeddedFontEnvironmentFlag['issues'] ?? []) !== []) {
            $provenance['embeddedFonts'] = [
                'ignoreEmbeddedFonts' => $ignoreEmbeddedFontCount > 0,
                'embeddedFontAccess' => $ignoreEmbeddedFontCount > 0 ? 'disabled' : 'default',
                'flagCount' => $ignoreEmbeddedFontCount,
                'issues' => $embeddedFontEnvironmentFlag['issues'] ?? [],
            ];
            if ($embeddedFontEnvironmentFlag !== null) {
                $provenance['embeddedFonts']['environmentVariable'] = 'TYPST_IGNORE_EMBEDDED_FONTS';
                $provenance['embeddedFonts']['environmentValue'] = $embeddedFontEnvironmentFlag['raw'];
            }
        }
        if ($openOutputCount > 0) {
            $openOutputViewers = array_values(array_filter(
                $openOutputEntries,
                fn (array $entry): bool => ($entry['viewer'] ?? null) !== null
            ));
            $provenance['openOutput'] = [
                'enabled' => true,
                'flagCount' => $openOutputCount,
                'issues' => array_values(array_unique($openOutputIssues)),
            ];
            if ($openOutputViewers !== []) {
                $provenance['openOutput']['viewer'] = $openOutputViewers[count($openOutputViewers) - 1];
                $provenance['openOutput']['viewers'] = $openOutputViewers;
            }
        }
        if ($pageSelection !== null || $ppi !== null || $noPdfTagsCount > 0 || $prettyOutputCount > 0) {
            $pdfExportIssues = $pdfTagIssues;
            foreach ($pageSelectionHistory as $entry) {
                foreach ($entry['issues'] as $issue) {
                    $pdfExportIssues[] = $issue;
                }
            }
            foreach ($ppiHistory as $entry) {
                foreach ($entry['issues'] as $issue) {
                    $pdfExportIssues[] = $issue;
                }
            }
            foreach (($pageSelectionPolicy['issues'] ?? []) as $issue) {
                $pdfExportIssues[] = $issue;
            }
            foreach ($overrides as $override) {
                if (in_array($override['option'], ['pages', 'ppi'], true)) {
                    $pdfExportIssues[] = $override['issue'];
                }
            }
            $pdfExport = [
                'pageSelection' => $pageSelection,
                'issues' => array_values(array_unique($pdfExportIssues)),
            ];
            if ($ppi !== null) {
                $pdfExport['ppi'] = $ppi;
            }
            if ($pageSelectionPolicy !== []) {
                $pdfExport['pageSelectionPolicy'] = $pageSelectionPolicy;
            }
            if ($noPdfTagsCount > 0) {
                $pdfExport['tags'] = [
                    'disabled' => true,
                    'flagCount' => $noPdfTagsCount,
                    'issues' => $pdfTagIssues,
                ];
            }
            if ($prettyOutputCount > 0) {
                $pdfExport['pretty'] = [
                    'enabled' => true,
                    'flagCount' => $prettyOutputCount,
                    'issues' => [],
                ];
            }
            $provenance['pdfExport'] = $pdfExport;
        }
        if ($overrides !== []) {
            $provenance['overrides'] = $overrides;
        }
        if ($this->typstBoundaryHistoryHasIssues($rootHistory)) {
            $provenance['rootHistory'] = $rootHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($packagePathHistory)) {
            $provenance['packagePathHistory'] = $packagePathHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($packageCacheHistory)) {
            $provenance['packageCacheHistory'] = $packageCacheHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($creationTimestampHistory)) {
            $provenance['creationTimestampHistory'] = $creationTimestampHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($pageSelectionHistory)) {
            $provenance['pageSelectionHistory'] = $pageSelectionHistory;
        }
        if (count($ppiHistory) > 1 || $this->typstBoundaryHistoryHasIssues($ppiHistory)) {
            $provenance['ppiHistory'] = $ppiHistory;
        }
        if (count($pdfStandardHistory) > 1 || $this->typstBoundaryHistoryHasIssues($pdfStandardHistory)) {
            $provenance['pdfStandardHistory'] = $pdfStandardHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($featureGateHistory)) {
            $provenance['featureGateHistory'] = $featureGateHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($jobsHistory)) {
            $provenance['jobsHistory'] = $jobsHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($dependencyOutputHistory)) {
            $provenance['dependencyOutputHistory'] = $dependencyOutputHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($timingsOutputHistory)) {
            $provenance['timingsOutputHistory'] = $timingsOutputHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($diagnosticFormatHistory)) {
            $provenance['diagnosticFormatHistory'] = $diagnosticFormatHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($diagnosticColorHistory)) {
            $provenance['diagnosticColorHistory'] = $diagnosticColorHistory;
        }
        if ($this->typstBoundaryHistoryHasIssues($dependencyFormatHistory)) {
            $provenance['dependencyFormatHistory'] = $dependencyFormatHistory;
        }
        if (count($outputFormatHistory) > 1 || $this->typstBoundaryHistoryHasIssues($outputFormatHistory)) {
            $provenance['outputFormatHistory'] = $outputFormatHistory;
        }

        return $provenance;
    }

    /**
     * @param list<array{raw:string, value:string, format:string|null, safe:bool, issues:list<string>}> $formatHistory
     * @param list<array{option:string, count:int, values:list<string>, selected:string, issue:string}> $overrides
     * @return array<string, mixed>
     */
    private function typstOutputFormatBoundaryPolicy(array $formatHistory, array $overrides): array
    {
        if ($formatHistory === []) {
            return [];
        }

        $formatOptions = [];
        $issues = [];
        foreach ($formatHistory as $entry) {
            foreach ($entry['issues'] as $issue) {
                $issues[] = $issue;
            }
            if ($entry['format'] !== null) {
                $formatOptions[] = $entry['format'];
            }
        }

        $distinctFormats = array_values(array_unique($formatOptions));
        sort($distinctFormats);
        if (count($distinctFormats) > 1) {
            $issues[] = 'conflicting-format-options:' . count($distinctFormats);
        }
        foreach ($overrides as $override) {
            if ($override['option'] === 'outputFormat') {
                $issues[] = $override['issue'];
            }
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'explicitFormat' => $formatOptions === [] ? null : $formatOptions[count($formatOptions) - 1],
            'formatOptions' => $formatOptions,
            'distinctFormats' => $distinctFormats,
            'formatEntryCount' => count($formatHistory),
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @param array<string, mixed> $provenance
     * @param array<string, mixed> $summary
     * @param array<string, mixed> $sourceInput
     * @param array<string, mixed> $outputFormatPolicy
     * @param array<string, mixed> $readBoundaryPolicy
     * @param array<string, mixed> $dependencyOutputPolicy
     * @param array<string, mixed> $externalDependencyPolicy
     * @param array<string, mixed> $packageDependencyPolicy
     * @param list<array<string, mixed>> $warningProvenance
     * @return array<string, mixed>
     */
    private function typstBoundaryMatrixFor(
        string $engine,
        array $provenance,
        array $summary,
        array $sourceInput = [],
        array $outputFormatPolicy = [],
        array $readBoundaryPolicy = [],
        array $dependencyOutputPolicy = [],
        array $externalDependencyPolicy = [],
        array $packageDependencyPolicy = [],
        array $warningProvenance = []
    ): array {
        $hasRuntimeProvenance = $readBoundaryPolicy !== []
            || $dependencyOutputPolicy !== []
            || $externalDependencyPolicy !== []
            || $packageDependencyPolicy !== []
            || $warningProvenance !== [];
        if ($engine !== 'typst' || ($provenance === [] && $sourceInput === [] && !$hasRuntimeProvenance)) {
            return [];
        }

        $normalizeIssues = static function (array $rawIssues): array {
            $issues = array_values(array_filter(
                $rawIssues,
                static fn (mixed $issue): bool => is_string($issue) && $issue !== ''
            ));
            $issues = array_values(array_unique($issues));
            sort($issues);

            return $issues;
        };
        $entryIssues = static function (mixed $entry) use ($normalizeIssues): array {
            if (!is_array($entry)) {
                return [];
            }

            return $normalizeIssues(is_array($entry['issues'] ?? null) ? $entry['issues'] : []);
        };
        $listIssues = static function (array $entries) use ($entryIssues, $normalizeIssues): array {
            $issues = [];
            foreach ($entries as $entry) {
                array_push($issues, ...$entryIssues($entry));
            }

            return $normalizeIssues($issues);
        };
        $optionIssues = static function (array $entries) use ($normalizeIssues): array {
            $issues = [];
            foreach ($entries as $entry) {
                if (!is_array($entry) || !is_string($entry['issue'] ?? null) || $entry['issue'] === '') {
                    continue;
                }

                $issues[] = $entry['issue'];
            }

            return $normalizeIssues($issues);
        };
        $countMap = static function (mixed $entries): array {
            if (!is_array($entries)) {
                return [];
            }

            $counts = [];
            foreach ($entries as $key => $count) {
                if (!is_string($key) || $key === '' || !is_int($count)) {
                    continue;
                }

                $counts[$key] = $count;
            }
            ksort($counts);

            return $counts;
        };
        $stringList = static function (mixed $entries): array {
            if (!is_array($entries)) {
                return [];
            }

            return array_values(array_filter(
                $entries,
                static fn (mixed $entry): bool => is_string($entry) && $entry !== ''
            ));
        };
        $countUnsafe = static function (array $entries): int {
            $count = 0;
            foreach ($entries as $entry) {
                if (!is_array($entry) || ($entry['safe'] ?? false) !== true) {
                    ++$count;
                }
            }

            return $count;
        };

        $cases = [];
        $matrixIssues = [];
        $appendCase = static function (
            string $case,
            string $reviewStatus,
            int $observed,
            array $details,
            array $caseIssues
        ) use (&$cases, &$matrixIssues, $normalizeIssues): void {
            if ($observed <= 0 && $details === [] && $caseIssues === []) {
                return;
            }

            $caseIssues = $normalizeIssues($caseIssues);
            if ($caseIssues !== [] && $reviewStatus === 'ok') {
                $reviewStatus = 'review';
            }
            foreach ($caseIssues as $issue) {
                $matrixIssues[] = $case . ':' . $issue;
            }

            $cases[] = [
                'case' => $case,
                'reviewStatus' => $reviewStatus,
                'observed' => $observed,
                'details' => $details,
                'issues' => $caseIssues,
            ];
        };

        if ($sourceInput !== []) {
            $sourceInputIssues = $entryIssues($sourceInput);
            $appendCase('source-input', ($sourceInput['reviewStatus'] ?? 'ok') === 'ok' && $sourceInputIssues === [] ? 'ok' : 'review', 1, [
                'mode' => is_string($sourceInput['mode'] ?? null) ? $sourceInput['mode'] : null,
                'sourceFile' => is_string($sourceInput['sourceFile'] ?? null) ? $sourceInput['sourceFile'] : null,
                'path' => is_string($sourceInput['path'] ?? null) ? $sourceInput['path'] : null,
                'stagedAsFile' => ($sourceInput['stagedAsFile'] ?? false) === true,
            ], $sourceInputIssues);
        }

        $root = is_array($provenance['root'] ?? null) ? $provenance['root'] : [];
        $rootHistory = is_array($provenance['rootHistory'] ?? null) ? $provenance['rootHistory'] : [];
        $rootBoundaryOverrides = array_values(array_filter(
            is_array($provenance['overrides'] ?? null) ? $provenance['overrides'] : [],
            static fn (mixed $entry): bool => is_array($entry) && ($entry['option'] ?? null) === 'root'
        ));
        $rootIssues = array_merge(
            $entryIssues($root),
            $listIssues($rootHistory),
            $optionIssues($rootBoundaryOverrides)
        );
        if ($root !== [] || $rootHistory !== [] || $rootIssues !== []) {
            $appendCase('root-boundary', ($root['safe'] ?? false) === true && $rootIssues === [] ? 'ok' : 'review', $rootHistory === [] ? (int) ($root !== []) : count($rootHistory), [
                'raw' => is_string($root['raw'] ?? null) ? $root['raw'] : null,
                'path' => is_string($root['path'] ?? null) ? $root['path'] : null,
                'kind' => is_string($root['kind'] ?? null) ? $root['kind'] : null,
                'safe' => ($root['safe'] ?? false) === true,
                'source' => is_string($root['source'] ?? null) ? $root['source'] : null,
                'environmentVariable' => is_string($root['environmentVariable'] ?? null) ? $root['environmentVariable'] : null,
                'historyEntryCount' => $rootHistory === [] ? (int) ($root !== []) : count($rootHistory),
                'overrideCount' => count($rootBoundaryOverrides),
            ], $rootIssues);
        }

        $shadowEntries = [];
        foreach ([
            'rootEnvironment',
            'certificateEnvironment',
            'packagePathEnvironment',
            'packageCacheEnvironment',
            'featureGateEnvironment',
            'creationTimestampEnvironment',
        ] as $key) {
            if (is_array($provenance[$key] ?? null)) {
                $shadowEntries[] = $provenance[$key];
            }
        }
        $shadowedVariables = [];
        foreach ($shadowEntries as $entry) {
            if (!is_string($entry['shadowedBy'] ?? null)) {
                continue;
            }
            $environmentVariable = is_string($entry['environmentVariable'] ?? null) ? $entry['environmentVariable'] : null;
            if ($environmentVariable !== null && $environmentVariable !== '') {
                $shadowedVariables[] = $environmentVariable;
            }
        }
        sort($shadowedVariables);
        $environmentVariables = array_values(array_filter(
            is_array($provenance['environmentVariables'] ?? null) ? $provenance['environmentVariables'] : [],
            static fn (mixed $value): bool => is_string($value) && $value !== ''
        ));
        sort($environmentVariables);
        if ($shadowEntries !== [] || $environmentVariables !== []) {
            $appendCase('environment-shadows', $shadowedVariables === [] ? 'ok' : 'review', max(count($environmentVariables), count($shadowEntries)), [
                'environmentVariableCount' => count($environmentVariables),
                'shadowedCount' => count($shadowedVariables),
                'shadowedVariables' => $shadowedVariables,
            ], $listIssues($shadowEntries));
        }

        $fontPaths = is_array($provenance['fontPaths'] ?? null) ? $provenance['fontPaths'] : [];
        $fontPathPolicy = is_array($provenance['fontPathPolicy'] ?? null) ? $provenance['fontPathPolicy'] : [];
        $fontPathIssues = array_merge(
            $listIssues($fontPaths),
            is_array($fontPathPolicy['issues'] ?? null) ? $fontPathPolicy['issues'] : []
        );
        $fontPathCount = is_int($fontPathPolicy['fontPathCount'] ?? null)
            ? $fontPathPolicy['fontPathCount']
            : (is_int($summary['fontPathCount'] ?? null) ? $summary['fontPathCount'] : count($fontPaths));
        if ($fontPathCount > 0 || $fontPathIssues !== []) {
            $environmentFontPathCount = 0;
            $cliFontPathCount = 0;
            $fontPathEnvironmentVariables = [];
            foreach ($fontPaths as $fontPath) {
                if (is_array($fontPath) && ($fontPath['source'] ?? null) === 'environment') {
                    ++$environmentFontPathCount;
                    if (is_string($fontPath['environmentVariable'] ?? null) && $fontPath['environmentVariable'] !== '') {
                        $fontPathEnvironmentVariables[] = $fontPath['environmentVariable'];
                    }
                    continue;
                }

                ++$cliFontPathCount;
            }
            $fontPathEnvironmentVariables = array_values(array_unique($fontPathEnvironmentVariables));
            sort($fontPathEnvironmentVariables);
            $appendCase('font-path-policy', ($fontPathPolicy['reviewStatus'] ?? 'ok') === 'ok' && $fontPathIssues === [] ? 'ok' : 'review', $fontPathCount, [
                'safeFontPathCount' => is_int($fontPathPolicy['safeFontPathCount'] ?? null) ? $fontPathPolicy['safeFontPathCount'] : count(array_filter($fontPaths, static fn (mixed $entry): bool => is_array($entry) && ($entry['safe'] ?? false) === true)),
                'unsafeFontPathCount' => is_int($fontPathPolicy['unsafeFontPathCount'] ?? null) ? $fontPathPolicy['unsafeFontPathCount'] : count(array_filter($fontPaths, static fn (mixed $entry): bool => !is_array($entry) || ($entry['safe'] ?? false) !== true)),
                'relativeFontPathCount' => is_int($fontPathPolicy['relativeFontPathCount'] ?? null) ? $fontPathPolicy['relativeFontPathCount'] : 0,
                'workspaceFontPathCount' => is_int($fontPathPolicy['workspaceFontPathCount'] ?? null) ? $fontPathPolicy['workspaceFontPathCount'] : 0,
                'absoluteFontPathCount' => is_int($fontPathPolicy['absoluteFontPathCount'] ?? null) ? $fontPathPolicy['absoluteFontPathCount'] : 0,
                'uriFontPathCount' => is_int($fontPathPolicy['uriFontPathCount'] ?? null) ? $fontPathPolicy['uriFontPathCount'] : 0,
                'invalidFontPathCount' => is_int($fontPathPolicy['invalidFontPathCount'] ?? null) ? $fontPathPolicy['invalidFontPathCount'] : 0,
                'cliFontPathCount' => $cliFontPathCount,
                'environmentFontPathCount' => $environmentFontPathCount,
                'environmentVariables' => $fontPathEnvironmentVariables,
            ], $fontPathIssues);
        }

        $inputVariables = is_array($provenance['inputVariables'] ?? null) ? $provenance['inputVariables'] : [];
        $inputVariableOverrides = is_array($provenance['inputVariableOverrides'] ?? null) ? $provenance['inputVariableOverrides'] : [];
        $inputVariablePolicy = is_array($provenance['inputVariablePolicy'] ?? null) ? $provenance['inputVariablePolicy'] : [];
        $inputBoundaryOverrides = array_values(array_filter(
            is_array($provenance['overrides'] ?? null) ? $provenance['overrides'] : [],
            static fn (mixed $entry): bool => is_array($entry) && is_string($entry['option'] ?? null) && str_starts_with($entry['option'], 'input:')
        ));
        $inputIssues = array_merge(
            $listIssues($inputVariables),
            $optionIssues($inputVariableOverrides),
            $optionIssues($inputBoundaryOverrides)
        );
        $inputNames = [];
        $unsafeInputVariableCount = 0;
        foreach ($inputVariables as $inputVariable) {
            if (!is_array($inputVariable)) {
                ++$unsafeInputVariableCount;
                continue;
            }
            if (($inputVariable['safe'] ?? false) !== true) {
                ++$unsafeInputVariableCount;
            }
            if (is_string($inputVariable['name'] ?? null) && $inputVariable['name'] !== '') {
                $inputNames[] = $inputVariable['name'];
            }
        }
        $inputNames = array_values(array_unique($inputNames));
        sort($inputNames);
        $overriddenInputNames = [];
        foreach ($inputVariableOverrides as $override) {
            if (is_array($override) && is_string($override['name'] ?? null) && $override['name'] !== '') {
                $overriddenInputNames[] = $override['name'];
            }
        }
        foreach ($inputBoundaryOverrides as $override) {
            $option = is_array($override) && is_string($override['option'] ?? null) ? $override['option'] : '';
            if (str_starts_with($option, 'input:') && substr($option, strlen('input:')) !== '') {
                $overriddenInputNames[] = substr($option, strlen('input:'));
            }
        }
        $overriddenInputNames = array_values(array_unique($overriddenInputNames));
        sort($overriddenInputNames);
        if ($inputVariables !== [] || $inputVariableOverrides !== [] || $inputIssues !== []) {
            $selectedByName = is_array($inputVariablePolicy['selectedByName'] ?? null)
                ? $inputVariablePolicy['selectedByName']
                : [];
            ksort($selectedByName);
            $appendCase('input-variables', $unsafeInputVariableCount === 0 && $inputVariableOverrides === [] && $inputIssues === [] ? 'ok' : 'review', count($inputVariables), [
                'inputVariableCount' => count($inputVariables),
                'unsafeInputVariableCount' => $unsafeInputVariableCount,
                'safeInputVariableCount' => is_int($inputVariablePolicy['safeInputVariableCount'] ?? null) ? $inputVariablePolicy['safeInputVariableCount'] : count($inputVariables) - $unsafeInputVariableCount,
                'distinctInputNameCount' => is_int($inputVariablePolicy['distinctInputNameCount'] ?? null) ? $inputVariablePolicy['distinctInputNameCount'] : count($inputNames),
                'duplicateInputNameCount' => is_int($inputVariablePolicy['duplicateInputNameCount'] ?? null) ? $inputVariablePolicy['duplicateInputNameCount'] : count($overriddenInputNames),
                'duplicateAssignmentCount' => is_int($inputVariablePolicy['duplicateAssignmentCount'] ?? null) ? $inputVariablePolicy['duplicateAssignmentCount'] : count($inputVariableOverrides),
                'overrideCount' => count($inputVariableOverrides),
                'inputNames' => $inputNames,
                'overriddenInputNames' => $overriddenInputNames,
                'selectedByName' => $selectedByName,
            ], $inputIssues);
        }

        $boundaryOverrides = is_array($provenance['overrides'] ?? null) ? array_values(array_filter(
            $provenance['overrides'],
            static fn (mixed $entry): bool => is_array($entry)
        )) : [];
        if ($boundaryOverrides !== []) {
            $overriddenOptions = [];
            $selectedByOption = [];
            $historyEntryCount = 0;
            foreach ($boundaryOverrides as $override) {
                $option = is_string($override['option'] ?? null) ? $override['option'] : '';
                if ($option === '') {
                    continue;
                }

                $overriddenOptions[] = $option;
                if (is_string($override['selected'] ?? null)) {
                    $selectedByOption[$option] = $override['selected'];
                }
                $historyEntryCount += is_int($override['count'] ?? null)
                    ? $override['count']
                    : count(is_array($override['values'] ?? null) ? $override['values'] : []);
            }
            $overriddenOptions = array_values(array_unique($overriddenOptions));
            sort($overriddenOptions);
            ksort($selectedByOption);
            $overrideIssues = $optionIssues($boundaryOverrides);
            $appendCase('boundary-overrides', 'review', count($boundaryOverrides), [
                'overrideCount' => count($boundaryOverrides),
