            }
            foreach ($creationTimestampEntries as $entry) {
                if (!is_array($entry)) {
                    ++$invalidTimestampCount;
                    continue;
                }
                if (($entry['deterministic'] ?? false) === true) {
                    ++$deterministicTimestampCount;
                }
                if (($entry['safe'] ?? false) !== true) {
                    ++$invalidTimestampCount;
                }
                if (($entry['kind'] ?? null) === 'unix-seconds') {
                    ++$unixTimestampCount;
                }
            }
            $creationTimestampIssues = array_merge(
                $entryIssues($creationTimestamp),
                $entryIssues($creationTimestampEnvironment),
                $listIssues($creationTimestampHistory),
                $optionIssues($creationTimestampOverrides)
            );
            $appendCase('creation-timestamp', $creationTimestampIssues === [] ? 'ok' : 'review', count($creationTimestampEntries), [
                'raw' => is_string($creationTimestamp['raw'] ?? null) ? $creationTimestamp['raw'] : null,
                'kind' => is_string($creationTimestamp['kind'] ?? null) ? $creationTimestamp['kind'] : null,
                'timestamp' => is_int($creationTimestamp['timestamp'] ?? null) ? $creationTimestamp['timestamp'] : null,
                'iso8601' => is_string($creationTimestamp['iso8601'] ?? null) ? $creationTimestamp['iso8601'] : null,
                'deterministic' => ($creationTimestamp['deterministic'] ?? false) === true,
                'historyEntryCount' => $creationTimestampHistory === [] ? (int) ($creationTimestamp !== []) : count($creationTimestampHistory),
                'deterministicTimestampCount' => $deterministicTimestampCount,
                'invalidHistoryCount' => $invalidHistoryCount,
                'invalidTimestampCount' => $invalidTimestampCount,
                'unixTimestampCount' => $unixTimestampCount,
                'overrideCount' => count($creationTimestampOverrides),
                'environmentShadowed' => is_string($creationTimestampEnvironment['shadowedBy'] ?? null),
                'environmentRaw' => is_string($creationTimestampEnvironment['raw'] ?? null) ? $creationTimestampEnvironment['raw'] : null,
                'environmentVariable' => is_string($creationTimestamp['environmentVariable'] ?? null)
                    ? $creationTimestamp['environmentVariable']
                    : (is_string($creationTimestampEnvironment['environmentVariable'] ?? null) ? $creationTimestampEnvironment['environmentVariable'] : null),
                'environmentTimestamp' => is_int($creationTimestampEnvironment['timestamp'] ?? null) ? $creationTimestampEnvironment['timestamp'] : null,
                'environmentIso8601' => is_string($creationTimestampEnvironment['iso8601'] ?? null) ? $creationTimestampEnvironment['iso8601'] : null,
                'environmentSelected' => is_string($creationTimestampEnvironment['selected'] ?? null) ? $creationTimestampEnvironment['selected'] : null,
                'shadowedBy' => is_string($creationTimestampEnvironment['shadowedBy'] ?? null) ? $creationTimestampEnvironment['shadowedBy'] : null,
                'selected' => is_string($creationTimestampEnvironment['selected'] ?? null) ? $creationTimestampEnvironment['selected'] : null,
                'source' => is_string($creationTimestamp['source'] ?? null) ? $creationTimestamp['source'] : null,
            ], $creationTimestampIssues);
        }

        $openOutput = is_array($provenance['openOutput'] ?? null) ? $provenance['openOutput'] : [];
        if ($openOutput !== []) {
            $openOutputIssues = is_array($openOutput['issues'] ?? null) ? $openOutput['issues'] : [];
            $openOutputViewers = is_array($openOutput['viewers'] ?? null) ? $openOutput['viewers'] : [];
            $defaultViewerCount = 0;
            $specificViewerCount = 0;
            $invalidViewerCount = 0;
            $viewerNames = [];
            $rawViewerValues = [];
            foreach ($openOutputViewers as $viewer) {
                if (!is_array($viewer)) {
                    continue;
                }
                if (($viewer['mode'] ?? null) === 'default-viewer') {
                    ++$defaultViewerCount;
                } elseif (($viewer['mode'] ?? null) === 'specific-viewer') {
                    ++$specificViewerCount;
                }
                if (($viewer['safe'] ?? false) !== true) {
                    ++$invalidViewerCount;
                }
                if (is_string($viewer['viewer'] ?? null) && $viewer['viewer'] !== '') {
                    $viewerNames[] = $viewer['viewer'];
                }
                if (is_string($viewer['raw'] ?? null)) {
                    $rawViewerValues[] = $viewer['raw'];
                }
            }
            $viewerNames = array_values(array_unique($viewerNames));
            $viewer = is_array($openOutput['viewer'] ?? null) ? $openOutput['viewer'] : [];
            $appendCase('open-output', $openOutputIssues === [] ? 'ok' : 'review', is_int($openOutput['flagCount'] ?? null) ? $openOutput['flagCount'] : 0, [
                'enabled' => ($openOutput['enabled'] ?? false) === true,
                'viewerCount' => count($openOutputViewers),
                'defaultViewerCount' => $defaultViewerCount,
                'specificViewerCount' => $specificViewerCount,
                'invalidViewerCount' => $invalidViewerCount,
                'viewer' => is_string($viewer['viewer'] ?? null) ? $viewer['viewer'] : null,
                'viewerNames' => $viewerNames,
                'rawViewerValues' => $rawViewerValues,
            ], $openOutputIssues);
        }

        if ($readBoundaryPolicy !== []) {
            $readIssues = is_array($readBoundaryPolicy['issues'] ?? null) ? $readBoundaryPolicy['issues'] : [];
            $inputFiles = $stringList($readBoundaryPolicy['inputFiles'] ?? null);
            $insideRootFiles = $stringList($readBoundaryPolicy['insideRootFiles'] ?? null);
            $outsideRootFiles = $stringList($readBoundaryPolicy['outsideRootFiles'] ?? null);
            $appendCase('root-read-boundary', ($readBoundaryPolicy['reviewStatus'] ?? 'ok') === 'ok' && $readIssues === [] ? 'ok' : 'review', count($inputFiles), [
                'root' => is_string($readBoundaryPolicy['root'] ?? null) ? $readBoundaryPolicy['root'] : null,
                'sourceFile' => is_string($readBoundaryPolicy['sourceFile'] ?? null) ? $readBoundaryPolicy['sourceFile'] : null,
                'inputFileCount' => count($inputFiles),
                'inputFiles' => $inputFiles,
                'insideRootCount' => count($insideRootFiles),
                'insideRootFiles' => $insideRootFiles,
                'outsideRootCount' => count($outsideRootFiles),
                'outsideRootFiles' => $outsideRootFiles,
            ], $readIssues);
        }

        if ($dependencyOutputPolicy !== []) {
            $dependencyOutputIssues = is_array($dependencyOutputPolicy['issues'] ?? null) ? $dependencyOutputPolicy['issues'] : [];
            $dependencyOutputFiles = array_values(array_filter(
                is_array($dependencyOutputPolicy['dependencyOutputFiles'] ?? null) ? $dependencyOutputPolicy['dependencyOutputFiles'] : [],
                static fn (mixed $path): bool => is_string($path) && $path !== ''
            ));
            $extraOutputFiles = array_values(array_filter(
                is_array($dependencyOutputPolicy['extraOutputFiles'] ?? null) ? $dependencyOutputPolicy['extraOutputFiles'] : [],
                static fn (mixed $path): bool => is_string($path) && $path !== ''
            ));
            $appendCase('dependency-output-policy', ($dependencyOutputPolicy['reviewStatus'] ?? 'ok') === 'ok' && $dependencyOutputIssues === [] ? 'ok' : 'review', count(is_array($dependencyOutputPolicy['dependencyOutputFiles'] ?? null) ? $dependencyOutputPolicy['dependencyOutputFiles'] : []), [
                'declaredOutputPresent' => ($dependencyOutputPolicy['declaredOutputPresent'] ?? false) === true,
                'declaredOutputFile' => is_string($dependencyOutputPolicy['declaredOutputFile'] ?? null) ? $dependencyOutputPolicy['declaredOutputFile'] : null,
                'dependencyOutputFiles' => $dependencyOutputFiles,
                'extraOutputFileCount' => count($extraOutputFiles),
                'extraOutputFiles' => $extraOutputFiles,
            ], $dependencyOutputIssues);
        }

        if ($externalDependencyPolicy !== []) {
            $externalDependencyIssues = is_array($externalDependencyPolicy['issues'] ?? null) ? $externalDependencyPolicy['issues'] : [];
            $dependencyKindCounts = [];
            foreach (is_array($externalDependencyPolicy['dependencies'] ?? null) ? $externalDependencyPolicy['dependencies'] : [] as $dependency) {
                if (!is_array($dependency) || !is_string($dependency['kind'] ?? null) || $dependency['kind'] === '') {
                    continue;
                }

                $dependencyKindCounts[$dependency['kind']] = ($dependencyKindCounts[$dependency['kind']] ?? 0) + 1;
            }
            ksort($dependencyKindCounts);
            $appendCase('external-dependencies', ($externalDependencyPolicy['reviewStatus'] ?? 'ok') === 'ok' && $externalDependencyIssues === [] ? 'ok' : 'review', is_int($externalDependencyPolicy['externalDependencyCount'] ?? null) ? $externalDependencyPolicy['externalDependencyCount'] : 0, [
                'packageDependencyCount' => is_int($externalDependencyPolicy['packageDependencyCount'] ?? null) ? $externalDependencyPolicy['packageDependencyCount'] : 0,
                'nonPackageDependencyCount' => is_int($externalDependencyPolicy['nonPackageDependencyCount'] ?? null) ? $externalDependencyPolicy['nonPackageDependencyCount'] : 0,
                'dependencyKindCounts' => $dependencyKindCounts,
            ], $externalDependencyIssues);
        }

        if ($packageDependencyPolicy !== []) {
            $packageDependencyIssues = is_array($packageDependencyPolicy['issues'] ?? null) ? $packageDependencyPolicy['issues'] : [];
            $appendCase('package-dependencies', ($packageDependencyPolicy['reviewStatus'] ?? 'ok') === 'ok' && $packageDependencyIssues === [] ? 'ok' : 'review', is_int($packageDependencyPolicy['packageDependencyCount'] ?? null) ? $packageDependencyPolicy['packageDependencyCount'] : 0, [
                'packageCount' => is_int($packageDependencyPolicy['packageCount'] ?? null) ? $packageDependencyPolicy['packageCount'] : 0,
                'sidecarFileCount' => is_int($packageDependencyPolicy['sidecarFileCount'] ?? null) ? $packageDependencyPolicy['sidecarFileCount'] : 0,
                'versionConflictCount' => is_int($packageDependencyPolicy['versionConflictCount'] ?? null) ? $packageDependencyPolicy['versionConflictCount'] : 0,
                'duplicateDependencyCount' => is_int($packageDependencyPolicy['duplicateDependencyCount'] ?? null) ? $packageDependencyPolicy['duplicateDependencyCount'] : 0,
                'duplicateDependencyGroupCount' => count(is_array($packageDependencyPolicy['duplicateDependencySummaries'] ?? null) ? $packageDependencyPolicy['duplicateDependencySummaries'] : []),
                'subpathDependencyCount' => is_int($packageDependencyPolicy['subpathDependencyCount'] ?? null) ? $packageDependencyPolicy['subpathDependencyCount'] : 0,
                'unsupportedPackageCount' => is_int($packageDependencyPolicy['unsupportedPackageCount'] ?? null) ? $packageDependencyPolicy['unsupportedPackageCount'] : 0,
                'sourceClasses' => array_values(array_filter(
                    is_array($packageDependencyPolicy['sourceClasses'] ?? null) ? $packageDependencyPolicy['sourceClasses'] : [],
                    static fn (mixed $sourceClass): bool => is_string($sourceClass) && $sourceClass !== ''
                )),
                'sourceClassCounts' => $countMap($packageDependencyPolicy['sourceClassCounts'] ?? null),
                'unsupportedReasonCounts' => $countMap($packageDependencyPolicy['unsupportedReasonCounts'] ?? null),
            ], $packageDependencyIssues);
        }

        if ($warningProvenance !== []) {
            $warningIssues = $listIssues($warningProvenance);
            $insideRootCount = 0;
            $outsideRootCount = 0;
            $unboundedCount = 0;
            $externalSourceCount = 0;
            $unknownSourceCount = 0;
            $locatedSourceCount = 0;
            $hintCount = 0;
            foreach ($warningProvenance as $warning) {
                if (!is_array($warning)) {
                    continue;
                }

                if (is_string($warning['sourceFile'] ?? null) && $warning['sourceFile'] !== '') {
                    ++$locatedSourceCount;
                }
                $hintCount += count(is_array($warning['hints'] ?? null) ? $warning['hints'] : []);

                match ($warning['boundaryStatus'] ?? null) {
                    'inside-root' => ++$insideRootCount,
                    'outside-root' => ++$outsideRootCount,
                    'unbounded' => ++$unboundedCount,
                    'external-source' => ++$externalSourceCount,
                    'unknown-source' => ++$unknownSourceCount,
                    default => null,
                };
            }
            $appendCase('warning-provenance', $warningIssues === [] ? 'ok' : 'review', count($warningProvenance), [
                'sourceIssueCount' => count($warningIssues),
                'locatedSourceCount' => $locatedSourceCount,
                'insideRootCount' => $insideRootCount,
                'outsideRootCount' => $outsideRootCount,
                'unboundedCount' => $unboundedCount,
                'externalSourceCount' => $externalSourceCount,
                'unknownSourceCount' => $unknownSourceCount,
                'hintCount' => $hintCount,
            ], $warningIssues);
        }

        if ($cases === []) {
            return [];
        }

        $matrixIssues = $normalizeIssues($matrixIssues);
        $reviewCaseCount = 0;
        foreach ($cases as $case) {
            if (($case['reviewStatus'] ?? 'ok') !== 'ok') {
                ++$reviewCaseCount;
            }
        }

        return [
            'reviewStatus' => $reviewCaseCount === 0 && $matrixIssues === [] ? 'ok' : 'review',
            'caseCount' => count($cases),
            'reviewCaseCount' => $reviewCaseCount,
            'issueCount' => count($matrixIssues),
            'cases' => $cases,
            'issues' => $matrixIssues,
        ];
    }

    /**
     * @param array<string, mixed> $provenance
     * @return array<string, mixed>
     */
    private function typstBoundarySummaryFor(array $provenance): array
    {
        if ($provenance === []) {
            return [];
        }

        $pathEntries = [];
        $appendPathEntry = static function (mixed $entry) use (&$pathEntries): void {
            if (!is_array($entry) || !is_string($entry['kind'] ?? null)) {
                return;
            }

            $pathEntries[] = $entry;
        };

        $appendPathEntry($provenance['root'] ?? null);
        $appendPathEntry($provenance['rootEnvironment'] ?? null);
        foreach (['fontPaths', 'certificates'] as $listKey) {
            foreach (is_array($provenance[$listKey] ?? null) ? $provenance[$listKey] : [] as $entry) {
                $appendPathEntry($entry);
            }
        }
        $appendPathEntry($provenance['certificateEnvironment'] ?? null);
        $appendPathEntry($provenance['packagePath'] ?? null);
        $appendPathEntry($provenance['packagePathEnvironment'] ?? null);
        $appendPathEntry($provenance['packageCache'] ?? null);
        $appendPathEntry($provenance['packageCacheEnvironment'] ?? null);
        if (is_array($provenance['dependencyOutput'] ?? null)) {
            $appendPathEntry($provenance['dependencyOutput']['file'] ?? null);
        }
        $appendPathEntry($provenance['timingsOutput'] ?? null);

        $kindCounts = [
            'relative' => 0,
            'workspace' => 0,
            'absolute' => 0,
            'uri' => 0,
            'stdout' => 0,
            'invalid' => 0,
        ];
        $safePathCount = 0;
        $unsafePathCount = 0;
        foreach ($pathEntries as $entry) {
            $kind = is_string($entry['kind'] ?? null) ? $entry['kind'] : 'invalid';
            if (!array_key_exists($kind, $kindCounts)) {
                $kind = 'invalid';
            }
            ++$kindCounts[$kind];

            if (($entry['safe'] ?? false) === true) {
                ++$safePathCount;
            } else {
                ++$unsafePathCount;
            }
        }

        $inputVariables = is_array($provenance['inputVariables'] ?? null) ? $provenance['inputVariables'] : [];
        $unsafeInputVariableCount = 0;
        foreach ($inputVariables as $inputVariable) {
            if (!is_array($inputVariable) || ($inputVariable['safe'] ?? false) !== true) {
                ++$unsafeInputVariableCount;
            }
        }

        $dependencyOutputPresent = is_array($provenance['dependencyOutput']['file'] ?? null);
        $timingsOutputPresent = is_array($provenance['timingsOutput'] ?? null);
        $systemFontAccess = is_array($provenance['systemFonts'] ?? null) ? $provenance['systemFonts'] : [];
        $embeddedFontAccess = is_array($provenance['embeddedFonts'] ?? null) ? $provenance['embeddedFonts'] : [];
        $systemFontAccessDisabled = ($systemFontAccess['systemFontAccess'] ?? null) === 'disabled';
        $embeddedFontAccessDisabled = ($embeddedFontAccess['embeddedFontAccess'] ?? null) === 'disabled';
        $systemFontAccessFlagCount = is_int($systemFontAccess['flagCount'] ?? null) ? $systemFontAccess['flagCount'] : 0;
        $embeddedFontAccessFlagCount = is_int($embeddedFontAccess['flagCount'] ?? null) ? $embeddedFontAccess['flagCount'] : 0;
        $outputFormat = is_array($provenance['outputFormat'] ?? null) ? $provenance['outputFormat'] : [];
        $outputFormatPolicy = is_array($provenance['outputFormatPolicy'] ?? null) ? $provenance['outputFormatPolicy'] : [];
        $outputFormatOptions = array_values(array_filter(
            is_array($outputFormatPolicy['formatOptions'] ?? null) ? $outputFormatPolicy['formatOptions'] : [],
            static fn (mixed $format): bool => is_string($format) && $format !== ''
        ));
        $distinctOutputFormats = array_values(array_filter(
            is_array($outputFormatPolicy['distinctFormats'] ?? null) ? $outputFormatPolicy['distinctFormats'] : [],
            static fn (mixed $format): bool => is_string($format) && $format !== ''
        ));
        if ($distinctOutputFormats === [] && $outputFormatOptions !== []) {
            $distinctOutputFormats = array_values(array_unique($outputFormatOptions));
            sort($distinctOutputFormats);
        }
        $outputFormatIssues = array_values(array_filter(
            is_array($outputFormatPolicy['issues'] ?? null) ? $outputFormatPolicy['issues'] : [],
            static fn (mixed $issue): bool => is_string($issue) && $issue !== ''
        ));
        $outputFormatEntryCount = is_int($outputFormatPolicy['formatEntryCount'] ?? null)
            ? $outputFormatPolicy['formatEntryCount']
            : (int) ($outputFormat !== []);
        $pdfExport = is_array($provenance['pdfExport'] ?? null) ? $provenance['pdfExport'] : [];
        $pdfExportControlCount = 0;
        foreach ([
            is_array($provenance['pdfStandard'] ?? null),
            is_array($pdfExport['pageSelection'] ?? null),
            is_array($pdfExport['ppi'] ?? null),
            is_array($pdfExport['tags'] ?? null),
            is_array($pdfExport['pretty'] ?? null),
        ] as $present) {
            if ($present) {
                ++$pdfExportControlCount;
            }
        }

        $historyEntryCount = 0;
        foreach ($provenance as $key => $value) {
            if (is_string($key) && str_ends_with($key, 'History') && is_array($value)) {
                $historyEntryCount += count($value);
            }
        }

        $issues = array_values(array_filter(
            is_array($provenance['issues'] ?? null) ? $provenance['issues'] : [],
            static fn (mixed $issue): bool => is_string($issue) && $issue !== ''
        ));

        return [
            'reviewStatus' => is_string($provenance['reviewStatus'] ?? null) ? $provenance['reviewStatus'] : ($issues === [] ? 'ok' : 'review'),
            'pathEntryCount' => count($pathEntries),
            'safePathEntryCount' => $safePathCount,
            'unsafePathEntryCount' => $unsafePathCount,
            'relativePathEntryCount' => $kindCounts['relative'],
            'workspacePathEntryCount' => $kindCounts['workspace'],
            'absolutePathEntryCount' => $kindCounts['absolute'],
            'uriPathEntryCount' => $kindCounts['uri'],
            'stdoutPathEntryCount' => $kindCounts['stdout'],
            'invalidPathEntryCount' => $kindCounts['invalid'],
            'fontPathCount' => is_array($provenance['fontPaths'] ?? null) ? count($provenance['fontPaths']) : 0,
            'certificateCount' => is_array($provenance['certificates'] ?? null) ? count($provenance['certificates']) : 0,
            'packageStorageEntryCount' => is_array($provenance['packageStoragePolicy'] ?? null) && is_int($provenance['packageStoragePolicy']['storageEntryCount'] ?? null)
                ? $provenance['packageStoragePolicy']['storageEntryCount']
                : (int) is_array($provenance['packagePath'] ?? null) + (int) is_array($provenance['packageCache'] ?? null),
            'inputVariableCount' => count($inputVariables),
            'unsafeInputVariableCount' => $unsafeInputVariableCount,
            'sidecarOutputCount' => (int) $dependencyOutputPresent + (int) $timingsOutputPresent,
            'dependencyOutputPresent' => $dependencyOutputPresent,
            'timingsOutputPresent' => $timingsOutputPresent,
            'diagnosticOutputPresent' => is_array($provenance['diagnosticOutput'] ?? null),
            'fontAccessControlCount' => (int) $systemFontAccessDisabled + (int) $embeddedFontAccessDisabled,
            'systemFontAccessDisabled' => $systemFontAccessDisabled,
            'systemFontAccessFlagCount' => $systemFontAccessFlagCount,
            'embeddedFontAccessDisabled' => $embeddedFontAccessDisabled,
            'embeddedFontAccessFlagCount' => $embeddedFontAccessFlagCount,
            'outputFormatControlCount' => (int) ($outputFormat !== []),
            'outputFormatEntryCount' => $outputFormatEntryCount,
            'outputFormatOptionCount' => count($outputFormatOptions),
            'distinctOutputFormatCount' => count($distinctOutputFormats),
            'outputFormatIssueCount' => count($outputFormatIssues),
            'pdfExportControlCount' => $pdfExportControlCount,
            'featureGateCount' => is_array($provenance['featureGates'] ?? null) && is_int($provenance['featureGates']['featureCount'] ?? null) ? $provenance['featureGates']['featureCount'] : 0,
            'executionPolicyPresent' => is_array($provenance['executionPolicy'] ?? null),
            'openOutputSideEffectCount' => is_array($provenance['openOutput'] ?? null) && is_int($provenance['openOutput']['flagCount'] ?? null) ? $provenance['openOutput']['flagCount'] : 0,
            'overrideCount' => is_array($provenance['overrides'] ?? null) ? count($provenance['overrides']) : 0,
            'historyEntryCount' => $historyEntryCount,
            'issueCount' => count($issues),
            'issues' => $issues,
        ];
    }

    /**
     * @param list<array<string, mixed>> $history
     */
    private function typstBoundaryHistoryHasIssues(array $history): bool
    {
        if (count($history) < 2) {
            return false;
        }

        foreach ($history as $entry) {
            if (($entry['issues'] ?? []) !== []) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array{raw:string, path:string, kind:string, safe:bool, issues:list<string>}> $fontPaths
     * @return array{reviewStatus:string, fontPathCount:int, safeFontPathCount:int, unsafeFontPathCount:int, relativeFontPathCount:int, workspaceFontPathCount:int, absoluteFontPathCount:int, uriFontPathCount:int, invalidFontPathCount:int, issues:list<string>}|array{}
     */
    private function typstFontPathPolicy(array $fontPaths): array
    {
        if ($fontPaths === []) {
            return [];
        }

        $safeCount = 0;
        $unsafeCount = 0;
        $kindCounts = [
            'relative' => 0,
            'workspace' => 0,
            'absolute' => 0,
            'uri' => 0,
            'invalid' => 0,
        ];
        $issues = [];
        foreach ($fontPaths as $fontPath) {
            $kind = is_string($fontPath['kind'] ?? null) ? $fontPath['kind'] : 'invalid';
            if (array_key_exists($kind, $kindCounts)) {
                ++$kindCounts[$kind];
            } else {
                ++$kindCounts['invalid'];
            }

            if (($fontPath['safe'] ?? false) === true) {
                ++$safeCount;
            } else {
                ++$unsafeCount;
            }

            foreach (($fontPath['issues'] ?? []) as $issue) {
                if (is_string($issue)) {
                    $issues[] = $issue;
                }
            }
        }

        if ($unsafeCount === 0 || ($kindCounts['absolute'] === 0 && $kindCounts['uri'] === 0)) {
            return [];
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'fontPathCount' => count($fontPaths),
            'safeFontPathCount' => $safeCount,
            'unsafeFontPathCount' => $unsafeCount,
            'relativeFontPathCount' => $kindCounts['relative'],
            'workspaceFontPathCount' => $kindCounts['workspace'],
            'absoluteFontPathCount' => $kindCounts['absolute'],
            'uriFontPathCount' => $kindCounts['uri'],
            'invalidFontPathCount' => $kindCounts['invalid'],
            'issues' => array_values(array_unique($issues)),
        ];
    }

