    /**
     * @param list<array{raw:string, path:string, kind:string, safe:bool, issues:list<string>}> $packagePaths
     * @param list<array{raw:string, path:string, kind:string, safe:bool, issues:list<string>}> $packageCaches
     * @return array{reviewStatus:string, storageEntryCount:int, safeStorageEntryCount:int, unsafeStorageEntryCount:int, packagePathCount:int, packageCacheCount:int, relativeStorageEntryCount:int, workspaceStorageEntryCount:int, absoluteStorageEntryCount:int, uriStorageEntryCount:int, invalidStorageEntryCount:int, issues:list<string>}|array{}
     */
    private function typstPackageStoragePolicy(array $packagePaths, array $packageCaches): array
    {
        $entries = array_merge($packagePaths, $packageCaches);
        if ($entries === []) {
            return [];
        }

        $safeCount = 0;
        $unsafeCount = 0;
        $kindCounts = [
            'relative' => 0,
            'workspace' => 0,
            'absolute' => 0,
            'uri' => 0,
            'invalid' => 0,
        ];
        $issues = [];
        foreach ($entries as $entry) {
            $kind = is_string($entry['kind'] ?? null) ? $entry['kind'] : 'invalid';
            if (array_key_exists($kind, $kindCounts)) {
                ++$kindCounts[$kind];
            } else {
                ++$kindCounts['invalid'];
            }

            if (($entry['safe'] ?? false) === true) {
                ++$safeCount;
            } else {
                ++$unsafeCount;
            }

            foreach (($entry['issues'] ?? []) as $issue) {
                if (is_string($issue)) {
                    $issues[] = $issue;
                }
            }
        }

        if ($unsafeCount === 0) {
            return [];
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'storageEntryCount' => count($entries),
            'safeStorageEntryCount' => $safeCount,
            'unsafeStorageEntryCount' => $unsafeCount,
            'packagePathCount' => count($packagePaths),
            'packageCacheCount' => count($packageCaches),
            'relativeStorageEntryCount' => $kindCounts['relative'],
            'workspaceStorageEntryCount' => $kindCounts['workspace'],
            'absoluteStorageEntryCount' => $kindCounts['absolute'],
            'uriStorageEntryCount' => $kindCounts['uri'],
            'invalidStorageEntryCount' => $kindCounts['invalid'],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @param array<string, mixed> $typstBoundaryProvenance
     */
    private function typstRootPathFromBoundaryProvenance(array $typstBoundaryProvenance): ?string
    {
        $root = $typstBoundaryProvenance['root'] ?? null;
        if (!is_array($root) || ($root['safe'] ?? false) !== true || !is_string($root['path'] ?? null)) {
            return null;
        }

        return $root['path'] === '' ? null : $root['path'];
    }

    /**
     * @param array<string, mixed> $typstBoundaryProvenance
     */
    private function typstDependencyFormatFromBoundaryProvenance(array $typstBoundaryProvenance): ?string
    {
        $format = $typstBoundaryProvenance['dependencyOutput']['format']['format'] ?? null;

        return is_string($format) && $format !== '' ? $format : null;
    }

    /**
     * @param list<string> $engineInputFiles
     * @return array{reviewStatus:string, root:string, sourceFile:string, inputFiles:list<string>, insideRootFiles:list<string>, outsideRootFiles:list<string>, issues:list<string>}|array{}
     */
    private function typstReadBoundaryPolicy(string $engine, ?string $typstRoot, string $sourceFile, array $engineInputFiles): array
    {
        if ($engine !== 'typst' || $typstRoot === null) {
            return [];
        }

        $inputFiles = $engineInputFiles;
        $sourceIsStdin = $sourceFile === '-';
        if (!$sourceIsStdin && !in_array($sourceFile, $inputFiles, true)) {
            $inputFiles[] = $sourceFile;
        }
        $inputFiles = array_values(array_unique($inputFiles));
        sort($inputFiles);

        $insideRootFiles = [];
        $outsideRootFiles = [];
        foreach ($inputFiles as $inputFile) {
            if ($this->pathIsInsideTypstRoot($inputFile, $typstRoot)) {
                $insideRootFiles[] = $inputFile;
                continue;
            }

            $outsideRootFiles[] = $inputFile;
        }

        $issues = [];
        if (!$sourceIsStdin && !$this->pathIsInsideTypstRoot($sourceFile, $typstRoot)) {
            $issues[] = 'source-outside-root';
        }
        if ($outsideRootFiles !== []) {
            $issues[] = 'input-outside-root:' . count($outsideRootFiles);
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'root' => $typstRoot,
            'sourceFile' => $sourceFile,
            'inputFiles' => $inputFiles,
            'insideRootFiles' => $insideRootFiles,
            'outsideRootFiles' => $outsideRootFiles,
            'issues' => $issues,
        ];
    }

    private function pathIsInsideTypstRoot(string $path, string $typstRoot): bool
    {
        if ($typstRoot === '.') {
            return true;
        }

        return $path === $typstRoot || str_starts_with($path, $typstRoot . '/');
    }

    /**
     * @return array{raw:string, path:string, kind:string, safe:bool, issues:list<string>}
     */
    private function typstBoundaryPathEntry(string $raw, string $kind): array
    {
        $value = str_replace('\\', '/', trim($raw));
        if ($value === '') {
            return [
                'raw' => $raw,
                'path' => '',
                'kind' => 'invalid',
                'safe' => false,
                'issues' => [$kind . '-empty'],
            ];
        }
        if (str_starts_with($value, '/')
            || preg_match('/\A[A-Za-z]:\//', $value) === 1
            || $this->isUriResourceReference($value)
        ) {
            return [
                'raw' => $raw,
                'path' => $value,
                'kind' => $this->isUriResourceReference($value) ? 'uri' : 'absolute',
                'safe' => false,
                'issues' => [$kind . '-external-boundary'],
            ];
        }
        if ($value === '.') {
            return [
                'raw' => $raw,
                'path' => '.',
                'kind' => 'workspace',
                'safe' => true,
                'issues' => [],
            ];
        }

        try {
            return [
                'raw' => $raw,
                'path' => $this->normalizeRelativePath($value, 'Typst ' . $kind . ' path'),
                'kind' => 'relative',
                'safe' => true,
                'issues' => [],
            ];
        } catch (\InvalidArgumentException) {
            return [
                'raw' => $raw,
                'path' => $value,
                'kind' => 'invalid',
                'safe' => false,
                'issues' => [$kind . '-invalid-boundary'],
            ];
        }
    }

    private function typstBoundaryPathEntryFromSource(string $raw, string $kind, ?string $environmentVariable): array
    {
        $entry = $this->typstBoundaryPathEntry($raw, $kind);
        if ($environmentVariable !== null) {
            $entry['source'] = 'environment';
            $entry['environmentVariable'] = $environmentVariable;
        }

        return $entry;
    }

    /**
     * @return array{raw:string, path:string, kind:string, safe:bool, issues:list<string>}
     */
    private function typstBoundaryFileEntry(string $raw, string $kind): array
    {
        $value = str_replace('\\', '/', trim($raw));
        if ($value === '') {
            return [
                'raw' => $raw,
                'path' => '',
                'kind' => 'invalid',
                'safe' => false,
                'issues' => [$kind . '-empty'],
            ];
        }
        if ($kind === 'dependency-output' && $value === '-') {
            return [
                'raw' => $raw,
                'path' => '-',
                'kind' => 'stdout',
                'safe' => false,
                'issues' => [$kind . '-stdout-boundary'],
            ];
        }
        if (
            str_starts_with($value, '/')
            || preg_match('/\A[A-Za-z]:\//', $value) === 1
            || $this->isUriResourceReference($value)
        ) {
            return [
                'raw' => $raw,
                'path' => $value,
                'kind' => $this->isUriResourceReference($value) ? 'uri' : 'absolute',
                'safe' => false,
                'issues' => [$kind . '-external-boundary'],
            ];
        }

        try {
            return [
                'raw' => $raw,
                'path' => $this->normalizeRelativePath($value, 'Typst ' . $kind . ' file'),
                'kind' => 'relative',
                'safe' => true,
                'issues' => [],
            ];
        } catch (\InvalidArgumentException) {
            return [
                'raw' => $raw,
                'path' => $value,
                'kind' => 'invalid',
                'safe' => false,
                'issues' => [$kind . '-invalid-boundary'],
            ];
        }
    }

    /**
     * @return array{raw:string, name:string, value:string, safe:bool, issues:list<string>}
     */
    private function typstInputVariableEntry(string $raw): array
    {
        $assignment = trim($raw);
        $separator = strpos($assignment, '=');
        $issues = [];
        $name = $separator === false ? $assignment : substr($assignment, 0, $separator);
        $value = $separator === false ? '' : substr($assignment, $separator + 1);

        if ($separator === false || $separator === 0 || preg_match('/\A[A-Za-z_][A-Za-z0-9_-]*\z/', $name) !== 1) {
            $issues[] = 'input-variable-invalid-boundary';
        }
        if (str_contains($value, "\0")) {
            $issues[] = 'input-value-invalid-boundary';
        }

        return [
            'raw' => $raw,
            'name' => $name,
            'value' => $value,
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @return array{raw:string, value:string, standards:list<string>, standardCount:int, safe:bool, issues:list<string>}
     */
    private function typstPdfStandardEntry(string $raw): array
    {
        $value = strtolower(trim($raw));
        $issues = [];
        $standards = [];

        if ($value === '') {
            $issues[] = 'pdf-standard-empty-boundary';
        } elseif (str_contains($raw, "\0") || preg_match('/[[:cntrl:]]/', $raw) === 1) {
            $issues[] = 'pdf-standard-invalid-boundary';
        } else {
            $parts = explode(',', $value);
            foreach ($parts as $part) {
                $standard = trim($part);
                if ($standard === '') {
                    $issues[] = 'pdf-standard-empty-token-boundary';
                    continue;
                }
                if (preg_match('/\A[a-z0-9][a-z0-9._:+-]*\z/', $standard) !== 1) {
                    $issues[] = 'pdf-standard-invalid-boundary';
                    continue;
                }

                $standards[] = $standard;
            }

            if (count($standards) !== count(array_unique($standards))) {
                $issues[] = 'pdf-standard-duplicate-boundary';
            }
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'standards' => $standards,
            'standardCount' => count($standards),
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @param array{standards:list<string>, standardCount:int}|null $pdfStandard
     * @return array{reviewStatus:string, standardCount:int, pdfVersionCount:int, pdfaCount:int, pdfuaCount:int, otherStandardCount:int, pdfVersions:list<string>, pdfaStandards:list<string>, pdfuaStandards:list<string>, issues:list<string>}|array{}
     */
    private function typstPdfStandardPolicy(?array $pdfStandard): array
    {
        if ($pdfStandard === null || !isset($pdfStandard['standards']) || !is_array($pdfStandard['standards'])) {
            return [];
        }

        $standards = array_values(array_filter(
            $pdfStandard['standards'],
            static fn (mixed $standard): bool => is_string($standard) && $standard !== ''
        ));
        if ($standards === []) {
            return [];
        }

        $pdfVersions = [];
        $pdfaStandards = [];
        $pdfuaStandards = [];
        $otherStandards = [];
        foreach ($standards as $standard) {
            if (preg_match('/\A(?:1\.[4567]|2\.0)\z/', $standard) === 1) {
                $pdfVersions[] = $standard;
                continue;
            }
            if (preg_match('/\Aa-\d/', $standard) === 1) {
                $pdfaStandards[] = $standard;
                continue;
            }
            if (preg_match('/\Aua-\d/', $standard) === 1) {
                $pdfuaStandards[] = $standard;
                continue;
            }

            $otherStandards[] = $standard;
        }

        $pdfVersions = array_values(array_unique($pdfVersions));
        $pdfaStandards = array_values(array_unique($pdfaStandards));
        $pdfuaStandards = array_values(array_unique($pdfuaStandards));
        $otherStandards = array_values(array_unique($otherStandards));
        $issues = [];

        if (count($pdfVersions) > 1) {
            $issues[] = 'pdf-standard-multiple-pdf-versions-boundary';
        }
        if (count($pdfaStandards) > 1) {
            $issues[] = 'pdf-standard-multiple-pdfa-boundary';
        }
        if ($pdfaStandards !== [] && $pdfuaStandards !== []) {
            $issues[] = 'pdf-standard-pdfa-pdfua-conflict-boundary';
        }
        if (in_array('2.0', $pdfVersions, true) && in_array('ua-1', $pdfuaStandards, true)) {
            $issues[] = 'pdf-standard-pdfua-version-conflict-boundary';
        }

        $issues = array_values(array_unique($issues));
        if ($issues === []) {
            return [];
        }

        return [
            'reviewStatus' => 'review',
            'standardCount' => count($standards),
            'pdfVersionCount' => count($pdfVersions),
            'pdfaCount' => count($pdfaStandards),
            'pdfuaCount' => count($pdfuaStandards),
            'otherStandardCount' => count($otherStandards),
            'pdfVersions' => $pdfVersions,
            'pdfaStandards' => $pdfaStandards,
            'pdfuaStandards' => $pdfuaStandards,
            'issues' => $issues,
        ];
    }

    /**
     * @return array{raw:string, value:string, features:list<string>, featureCount:int, safe:bool, issues:list<string>}
     */
    private function typstFeatureGateEntry(string $raw): array
    {
        $value = trim($raw);
        $issues = [];
        $features = [];
        if ($value === '') {
            $issues[] = 'features-empty-boundary';
        } elseif (strlen($value) > 256 || str_contains($raw, "\0") || preg_match('/[[:cntrl:]]/', $raw) === 1) {
            $issues[] = 'features-invalid-boundary';
        } else {
            foreach (explode(',', $value) as $feature) {
                $feature = strtolower(trim($feature));
                if ($feature === '') {
                    $issues[] = 'features-empty-token-boundary';
                    continue;
                }
                if (preg_match('/\A[a-z][a-z0-9_-]*\z/', $feature) !== 1) {
                    $issues[] = 'features-invalid-token-boundary:' . $feature;
                    continue;
                }

                $features[] = $feature;
            }
            if (count($features) !== count(array_unique($features))) {
                $issues[] = 'features-duplicate-boundary';
            }
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'features' => $features,
            'featureCount' => count($features),
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    private function typstFeatureGateEntryFromSource(string $raw, ?string $environmentVariable): array
    {
        $entry = $this->typstFeatureGateEntry($raw);
        if ($environmentVariable !== null) {
            $entry['source'] = 'environment';
            $entry['environmentVariable'] = $environmentVariable;
        }

        return $entry;
    }

    /**
     * @return array{raw:string, value:string, format:string|null, machineReadable:bool, safe:bool, issues:list<string>}
     */
    private function typstDiagnosticFormatEntry(string $raw): array
    {
        $value = strtolower(trim($raw));
        $issues = [];
        $format = null;
        if ($value === '') {
            $issues[] = 'diagnostic-format-empty-boundary';
        } elseif (str_contains($raw, "\0") || preg_match('/[[:cntrl:]]/', $raw) === 1) {
            $issues[] = 'diagnostic-format-invalid-boundary';
        } elseif (!in_array($value, ['human', 'short', 'json'], true)) {
            $issues[] = 'diagnostic-format-invalid-boundary';
        } else {
            $format = $value;
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'format' => $format,
            'machineReadable' => $format === 'json',
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @return array{raw:string, value:string, color:string|null, ansiColor:string, safe:bool, issues:list<string>}
     */
    private function typstDiagnosticColorEntry(string $raw): array
    {
        $value = strtolower(trim($raw));
        $issues = [];
        $color = null;
        if ($value === '') {
            $issues[] = 'diagnostic-color-empty-boundary';
        } elseif (str_contains($raw, "\0") || preg_match('/[[:cntrl:]]/', $raw) === 1) {
            $issues[] = 'diagnostic-color-invalid-boundary';
        } elseif (!in_array($value, ['auto', 'always', 'never'], true)) {
            $issues[] = 'diagnostic-color-invalid-boundary';
        } else {
            $color = $value;
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'color' => $color,
            'ansiColor' => match ($color) {
                'always' => 'enabled',
                'never' => 'disabled',
                'auto' => 'auto',
                default => 'unknown',
            },
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @return array{raw:string, value:string, format:string|null, makeCompatible:bool, machineReadable:bool, safe:bool, issues:list<string>}
     */
    private function typstDependencyFormatEntry(string $raw): array
    {
        $value = strtolower(trim($raw));
        $issues = [];
        $format = null;
        if ($value === '') {
            $issues[] = 'dependency-format-empty-boundary';
        } elseif (str_contains($raw, "\0") || preg_match('/[[:cntrl:]]/', $raw) === 1 || preg_match('/\A[a-z][a-z0-9_-]*\z/', $value) !== 1) {
            $issues[] = 'dependency-format-invalid-boundary';
        } else {
            $format = $value;
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'format' => $format,
            'makeCompatible' => $format === 'make',
            'machineReadable' => in_array($format, ['json', 'zero'], true),
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @param list<array{raw:string, name:string, value:string, safe:bool, issues:list<string>}> $inputVariables
     * @return list<array{option:string, count:int, values:list<string>, selected:string, issue:string}>
     */
    private function typstInputVariableOverrideOptionEntries(array $inputVariables): array
    {
        $valuesByName = [];
        foreach ($inputVariables as $inputVariable) {
            $name = $inputVariable['name'];
            if (preg_match('/\A[A-Za-z_][A-Za-z0-9_-]*\z/', $name) !== 1) {
                continue;
            }

            $valuesByName[$name][] = $inputVariable['value'];
        }

        ksort($valuesByName);
        $entries = [];
        foreach ($valuesByName as $name => $values) {
            if (count($values) < 2) {
                continue;
            }

            $entries[] = [
                'option' => 'input:' . $name,
                'count' => count($values),
                'values' => $values,
                'selected' => $values[count($values) - 1],
                'issue' => 'input-variable-boundary-overridden:' . $name,
            ];
        }

        return $entries;
    }

    /**
     * @param list<array{raw:string, name:string, value:string, safe:bool, issues:list<string>}> $inputVariables
     * @return list<array{name:string, count:int, values:list<string>, selected:string, issue:string}>
     */
    private function typstInputVariableOverrideEntries(array $inputVariables): array
    {
        $valuesByName = [];
        foreach ($inputVariables as $entry) {
            if (($entry['safe'] ?? false) !== true || $entry['name'] === '') {
                continue;
            }
            $valuesByName[$entry['name']][] = $entry['value'];
        }

        $entries = [];
        foreach ($valuesByName as $name => $values) {
            if (count($values) < 2) {
                continue;
            }
            $values = array_values($values);
            $entries[] = [
                'name' => $name,
                'count' => count($values),
                'values' => $values,
                'selected' => $values[count($values) - 1],
                'issue' => 'input-variable-boundary-overridden',
            ];
        }

        return $entries;
    }

    /**
     * @param list<array{raw:string, name:string, value:string, safe:bool, issues:list<string>}> $inputVariables
     * @param list<array{name:string, count:int, values:list<string>, selected:string, issue:string}> $inputVariableOverrides
     * @return array{reviewStatus:string, inputVariableCount:int, safeInputVariableCount:int, unsafeInputVariableCount:int, distinctInputNameCount:int, duplicateInputNameCount:int, duplicateAssignmentCount:int, inputNames:list<string>, overriddenInputNames:list<string>, valuesByName:array<string, list<string>>, selectedByName:array<string, string>, issues:list<string>}|array{}
     */
    private function typstInputVariablePolicy(array $inputVariables, array $inputVariableOverrides): array
    {
        if ($inputVariables === []) {
            return [];
        }

        $issues = [];
        $safeInputVariableCount = 0;
        $unsafeInputVariableCount = 0;
        $valuesByName = [];
        foreach ($inputVariables as $inputVariable) {
            foreach ($inputVariable['issues'] ?? [] as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issues[] = $issue;
                }
            }

            if (($inputVariable['safe'] ?? false) !== true) {
                ++$unsafeInputVariableCount;
                continue;
            }

            ++$safeInputVariableCount;
            $name = is_string($inputVariable['name'] ?? null) ? $inputVariable['name'] : '';
            if ($name === '') {
                continue;
            }

            $valuesByName[$name][] = is_string($inputVariable['value'] ?? null) ? $inputVariable['value'] : '';
        }

        ksort($valuesByName);
        $selectedByName = [];
        foreach ($valuesByName as $name => $values) {
            $selectedByName[$name] = $values[count($values) - 1];
        }

        $overriddenInputNames = [];
        $duplicateAssignmentCount = 0;
        foreach ($inputVariableOverrides as $override) {
            $name = is_string($override['name'] ?? null) ? $override['name'] : '';
            if ($name !== '') {
                $overriddenInputNames[] = $name;
            }
            if (is_int($override['count'] ?? null) && $override['count'] > 1) {
                $duplicateAssignmentCount += $override['count'] - 1;
            }
            if (is_string($override['issue'] ?? null) && $override['issue'] !== '') {
                $issues[] = $override['issue'];
            }
            if ($name !== '') {
                $issues[] = 'input-variable-boundary-overridden:' . $name;
            }
        }

        $inputNames = array_keys($valuesByName);
        $overriddenInputNames = array_values(array_unique($overriddenInputNames));
        sort($overriddenInputNames);
        $issues = array_values(array_unique($issues));
        sort($issues);

        if ($issues === []) {
            return [];
        }

        return [
            'reviewStatus' => 'review',
            'inputVariableCount' => count($inputVariables),
            'safeInputVariableCount' => $safeInputVariableCount,
            'unsafeInputVariableCount' => $unsafeInputVariableCount,
            'distinctInputNameCount' => count($inputNames),
            'duplicateInputNameCount' => count($overriddenInputNames),
            'duplicateAssignmentCount' => $duplicateAssignmentCount,
            'inputNames' => $inputNames,
            'overriddenInputNames' => $overriddenInputNames,
            'valuesByName' => $valuesByName,
            'selectedByName' => $selectedByName,
            'issues' => $issues,
        ];
    }

    /**
     * @return array{raw:string, value:string, mode:string, jobCount:int|null, safe:bool, issues:list<string>}
     */
    private function typstExecutionJobsEntry(string $raw): array
    {
        $value = strtolower(trim($raw));
        $issues = [];
        $mode = 'invalid';
        $jobCount = null;

        if ($value === '') {
            $issues[] = 'jobs-empty-boundary';
        } elseif ($value === 'auto') {
            $mode = 'auto';
        } elseif (preg_match('/\A[0-9]+\z/', $value) !== 1) {
            $issues[] = 'jobs-invalid-boundary';
        } elseif (!$this->decimalStringLessThanOrEqual($value, '1024')) {
            $issues[] = 'jobs-excessive-boundary';
        } else {
            $jobCount = (int) $value;
            if ($jobCount < 1) {
                $issues[] = 'jobs-nonpositive-boundary';
            } else {
                $mode = 'fixed';
            }
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'mode' => $mode,
            'jobCount' => $jobCount,
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @return array{raw:string, value:string, kind:string, timestamp:int|null, iso8601:string|null, deterministic:bool, safe:bool, issues:list<string>}
     */
    private function typstCreationTimestampEntry(string $raw): array
    {
        $value = trim($raw);
        $issues = [];
        $timestamp = null;
        $iso8601 = null;

        if ($value === '') {
            $issues[] = 'creation-timestamp-empty-boundary';
        } elseif (preg_match('/\A[0-9]+\z/', $value) !== 1) {
            $issues[] = 'creation-timestamp-invalid-boundary';
        } elseif (!$this->decimalStringLessThanOrEqual($value, '253402300799')) {
            $issues[] = 'creation-timestamp-out-of-range-boundary';
        } else {
            $timestamp = (int) $value;
            $iso8601 = gmdate('Y-m-d\TH:i:s\Z', $timestamp);
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'kind' => $issues === [] ? 'unix-seconds' : 'invalid',
            'timestamp' => $timestamp,
            'iso8601' => $iso8601,
            'deterministic' => $issues === [],
            'safe' => $issues === [],
            'issues' => $issues,
        ];
    }

    private function typstCreationTimestampEntryFromSource(string $raw, ?string $environmentVariable): array
    {
        $entry = $this->typstCreationTimestampEntry($raw);
        if ($environmentVariable !== null) {
            $entry['source'] = 'environment';
            $entry['environmentVariable'] = $environmentVariable;
        }

        return $entry;
    }

    /**
     * @return array{raw:string, value:string, segments:list<array{raw:string, kind:string, start:int|null, end:int|null, issues:list<string>}>, safe:bool, issues:list<string>}
     */
    private function typstPageSelectionEntry(string $raw): array
    {
        $value = trim($raw);
        $issues = [];
        $segments = [];
        if ($value === '') {
            $issues[] = 'pages-empty-boundary';
        } else {
            foreach (explode(',', $value) as $segment) {
                $segment = trim($segment);
                $segmentIssues = [];
                $kind = 'invalid';
                $start = null;
                $end = null;
                if ($segment === '') {
                    $segmentIssues[] = 'pages-empty-segment-boundary';
                } elseif (preg_match('/\A[1-9][0-9]*\z/', $segment) === 1) {
                    $kind = 'page';
                    $start = (int) $segment;
                    $end = $start;
                } elseif (preg_match('/\A([1-9][0-9]*)-([1-9][0-9]*)\z/', $segment, $matches) === 1) {
                    $kind = 'range';
                    $start = (int) $matches[1];
                    $end = (int) $matches[2];
                    if ($start > $end) {
                        $segmentIssues[] = 'pages-descending-range-boundary:' . $segment;
                    }
                } elseif (preg_match('/\A([1-9][0-9]*)-\z/', $segment, $matches) === 1) {
                    $kind = 'range-from';
                    $start = (int) $matches[1];
                } else {
                    $segmentIssues[] = 'pages-invalid-segment-boundary:' . $segment;
                }

                foreach ($segmentIssues as $issue) {
                    $issues[] = $issue;
                }
                $segments[] = [
                    'raw' => $segment,
                    'kind' => $kind,
                    'start' => $start,
                    'end' => $end,
                    'issues' => $segmentIssues,
                ];
            }
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'segments' => $segments,
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @param array{segments?:list<array{raw:string, kind:string, start:int|null, end:int|null, issues:list<string>}>}|null $pageSelection
     * @return array{reviewStatus:string, segmentCount:int, pageSegmentCount:int, rangeSegmentCount:int, rangeFromSegmentCount:int, invalidSegmentCount:int, finiteRangeCount:int, openEndedRangeCount:int, overlapCount:int, overlaps:list<array{left:string, right:string}>, issues:list<string>}|array{}
     */
    private function typstPageSelectionPolicy(?array $pageSelection): array
    {
        if ($pageSelection === null || !isset($pageSelection['segments']) || !is_array($pageSelection['segments'])) {
            return [];
        }

        $kindCounts = [
            'page' => 0,
            'range' => 0,
            'range-from' => 0,
            'invalid' => 0,
        ];
        $intervals = [];
        foreach ($pageSelection['segments'] as $segment) {
            if (!is_array($segment)) {
                ++$kindCounts['invalid'];
                continue;
            }

            $kind = is_string($segment['kind'] ?? null) ? $segment['kind'] : 'invalid';
            if (!array_key_exists($kind, $kindCounts)) {
                $kind = 'invalid';
            }
            ++$kindCounts[$kind];

            $start = $segment['start'] ?? null;
            $end = $segment['end'] ?? null;
            if (!is_int($start) || !in_array($kind, ['page', 'range', 'range-from'], true)) {
                continue;
            }

            $intervals[] = [
                'raw' => is_string($segment['raw'] ?? null) ? $segment['raw'] : '',
                'start' => $start,
                'end' => is_int($end) ? $end : null,
            ];
        }

        $overlaps = [];
        $intervalCount = count($intervals);
        for ($leftIndex = 0; $leftIndex < $intervalCount; ++$leftIndex) {
            for ($rightIndex = $leftIndex + 1; $rightIndex < $intervalCount; ++$rightIndex) {
                $left = $intervals[$leftIndex];
                $right = $intervals[$rightIndex];
                $leftEnd = $left['end'] ?? PHP_INT_MAX;
                $rightEnd = $right['end'] ?? PHP_INT_MAX;
                if ($left['start'] <= $rightEnd && $right['start'] <= $leftEnd) {
                    $overlaps[] = [
                        'left' => $left['raw'],
                        'right' => $right['raw'],
                    ];
                }
            }
        }

        if ($overlaps === []) {
            return [];
        }

        return [
            'reviewStatus' => 'review',
            'segmentCount' => count($pageSelection['segments']),
            'pageSegmentCount' => $kindCounts['page'],
            'rangeSegmentCount' => $kindCounts['range'],
            'rangeFromSegmentCount' => $kindCounts['range-from'],
            'invalidSegmentCount' => $kindCounts['invalid'],
            'finiteRangeCount' => $kindCounts['page'] + $kindCounts['range'],
            'openEndedRangeCount' => $kindCounts['range-from'],
            'overlapCount' => count($overlaps),
            'overlaps' => $overlaps,
            'issues' => ['pages-overlapping-selection-boundary'],
        ];
    }

    /**
     * @return array{raw:string, value:string, ppi:int|null, safe:bool, issues:list<string>}
     */
    private function typstPpiEntry(string $raw): array
    {
        $value = trim($raw);
        $issues = [];
        $ppi = null;

        if ($value === '') {
            $issues[] = 'ppi-empty-boundary';
        } elseif (preg_match('/\A[0-9]+\z/', $value) !== 1) {
            $issues[] = 'ppi-invalid-boundary';
        } elseif (!$this->decimalStringLessThanOrEqual($value, '2400')) {
            $issues[] = 'ppi-excessive-boundary';
        } else {
            $ppi = (int) $value;
            if ($ppi < 1) {
                $issues[] = 'ppi-nonpositive-boundary';
            }
        }

        return [
            'raw' => $raw,
            'value' => $value,
            'ppi' => $ppi,
            'safe' => $issues === [],
            'issues' => array_values(array_unique($issues)),
        ];
    }

    /**
     * @param array{standards?:list<string>}|null $pdfStandard
     */
    private function typstPdfStandardRequestsPdfUa(?array $pdfStandard): bool
    {
        if ($pdfStandard === null || !isset($pdfStandard['standards']) || !is_array($pdfStandard['standards'])) {
            return false;
        }

        foreach ($pdfStandard['standards'] as $standard) {
            if ($standard === 'ua-1') {
                return true;
            }
        }

        return false;
    }

    private function decimalStringLessThanOrEqual(string $value, string $maximum): bool
    {
        $value = ltrim($value, '0');
        $maximum = ltrim($maximum, '0');
        if ($value === '') {
            $value = '0';
        }
        if ($maximum === '') {
            $maximum = '0';
        }

        $valueLength = strlen($value);
        $maximumLength = strlen($maximum);
        if ($valueLength !== $maximumLength) {
            return $valueLength < $maximumLength;
        }

        return strcmp($value, $maximum) <= 0;
    }

    private function safeEngineJobName(?string $value): ?string
    {
        if ($value === null) {
            return null;
        }

        try {
            $jobName = $this->normalizeRelativePath($value, 'PDF engine job name');
        } catch (\InvalidArgumentException) {
            return null;
        }

        return str_contains($jobName, '/') ? null : $jobName;
    }

    private function safeEngineOutputDirectory(?string $value): ?string
    {
        if ($value === null) {
            return null;
        }

        $value = str_replace('\\', '/', trim($value));
        if ($value === '' || $value === '.') {
            return '';
        }

        try {
            return $this->normalizeRelativePath($value, 'PDF engine output directory');
        } catch (\InvalidArgumentException) {
            return null;
        }
    }

    private function isKnownEngineArtifact(string $path, string $sourceFile, ?string $artifactStem = null): bool
    {
        $stems = [$this->sourceStem($sourceFile)];
        if ($artifactStem !== null && $artifactStem !== '') {
            $stems[] = $artifactStem;
        }
        $stems = array_values(array_unique($stems));

        foreach ($stems as $stem) {
            if (!str_starts_with($path, $stem . '.')) {
                continue;
            }

            $extension = substr($path, strlen($stem) + 1);
            if (in_array($extension, [
                'aux',
                'bbl',
                'bcf',
                'blg',
                'fdb_latexmk',
                'fls',
                'log',
                'out',
                'run.xml',
                'synctex',
                'synctex.gz',
                'toc',
                'tuc',
                'd',
                'deps',
                'xdv',
            ], true)) {
                return true;
            }
        }

        return false;
    }

    private function isBibliographyArtifactPath(string $path): bool
    {
        return preg_match('/\.(?:bbl|bcf|blg|run\.xml)\z/i', $path) === 1;
    }

    private function isBibliographyLogPath(string $path): bool
    {
        return preg_match('/\.blg\z/i', $path) === 1;
    }

    private function isEngineDependencyArtifactPath(string $path): bool
    {
        return preg_match('/\.(?:fls|d|deps)\z/i', $path) === 1;
    }

    private function isSourceMapArtifactPath(string $path): bool
    {
        return preg_match('/\.synctex(?:\.gz)?\z/i', $path) === 1;
    }

    private function isEngineLogPath(string $path): bool
    {
        return preg_match('/\.log\z/i', $path) === 1;
    }

    /**
     * @param list<string> $texts
     * @return array{inputFiles:list<string>, externalInputFiles:list<string>}
     */
    private function extractEngineTranscriptInputs(array $texts): array
    {
        $inputFiles = [];
        $externalInputFiles = [];

        foreach ($texts as $text) {
            if (strlen($text) > self::MAX_TRANSCRIPT_BYTES) {
                throw new \RuntimeException('engine transcript exceeds bounded byte limit');
            }

            foreach (preg_split('/\R/u', $text) ?: [] as $line) {
                foreach ($this->engineTranscriptPathCandidates($line) as $candidate) {
                    $classified = $this->normalizeEngineDependencyPath($candidate, 'engine transcript');
                    if ($classified['local']) {
                        $inputFiles[$classified['path']] = true;
                    } else {
                        $externalInputFiles[$classified['path']] = true;
                    }
                }
            }
        }

        $inputFileList = array_keys($inputFiles);
        sort($inputFileList);
        $externalInputFileList = array_keys($externalInputFiles);
        sort($externalInputFileList);

        return [
            'inputFiles' => $inputFileList,
            'externalInputFiles' => $externalInputFileList,
        ];
    }

    /**
     * @return list<string>
     */
    private function engineTranscriptPathCandidates(string $line): array
    {
        if (!str_contains($line, '(')) {
            return [];
        }

        if (preg_match_all('/\((?:"([^"]+)"|\'([^\']+)\'|([^\s()]+))/u', $line, $matches, PREG_SET_ORDER) < 1) {
            return [];
        }

        $candidates = [];
        foreach ($matches as $match) {
            $candidate = '';
            foreach ([1, 2, 3] as $index) {
                if (isset($match[$index]) && $match[$index] !== '') {
                    $candidate = $match[$index];
                    break;
                }
            }

            $candidate = trim($candidate, " \t\n\r\0\x0B'\"`()[]{}<>");
            if ($candidate === '' || !$this->isLikelyEngineTranscriptPath($candidate)) {
                continue;
            }

            $candidates[] = $candidate;
        }

        return array_values(array_unique($candidates));
    }

    private function isLikelyEngineTranscriptPath(string $candidate): bool
    {
        return preg_match('/\.(?:typ|tex|sty|cls|clo|def|cfg|fd|map|enc|mf|tfm|otf|ttf|bib|bst|bbx|cbx|lbx|aux|out|toc|lof|lot|bbl|bcf|run\.xml|png|jpe?g|pdf|eps|svg|xdv)\z/i', $candidate) === 1;
    }

    /**
     * @return array{inputFiles:list<string>, externalInputFiles:list<string>, externalDependencies:list<array{input:string, raw:string, kind:string}>, outputFiles:list<string>, dependencyEdges:list<array{outputFiles:list<string>, inputFiles:list<string>, externalInputFiles:list<string>}>}
     */
    private function extractEngineDependencyArtifact(string $path, string $bytes, ?string $dependencyFormat = null): array
    {
        if (strlen($bytes) > self::MAX_DEPENDENCY_FILE_BYTES) {
            throw new \RuntimeException('dependency file exceeds bounded byte limit');
        }

        if ($dependencyFormat === 'zero' || ($dependencyFormat === null && str_contains($bytes, "\0"))) {
            return $this->extractZeroDependencyArtifact($path, $bytes);
        }

        $inputFiles = [];
        $externalInputFiles = [];
        $externalDependencies = [];
        $outputFiles = [];
        $dependencyEdges = [];
        $recorderRows = false;

        foreach (preg_split('/\R/u', $bytes) ?: [] as $line) {
            $line = trim($line);
            if ($line === '' || preg_match('/\APWD\s+/i', $line) === 1) {
                continue;
            }
            if (preg_match('/\A(INPUT|OUTPUT)\s+(.+)\z/i', $line, $matches) !== 1) {
                continue;
            }

            $recorderRows = true;
            $classified = $this->normalizeEngineDependencyPath($matches[2], $path);
            if (strtoupper($matches[1]) === 'INPUT') {
                if ($classified['local']) {
                    $inputFiles[$classified['path']] = true;
                } else {
                    $externalInputFiles[$classified['path']] = true;
                    $this->addExternalDependency($externalDependencies, $classified);
                }
                continue;
            }

            if ($classified['local']) {
                $outputFiles[$classified['path']] = true;
            }
        }

        if (!$recorderRows && preg_match('/\.(?:d|deps)\z/i', $path) === 1) {
            $makeDependencies = $this->extractMakeDependencyArtifact($path, $bytes);
            foreach ($makeDependencies['inputFiles'] as $inputFile) {
                $inputFiles[$inputFile] = true;
            }
            foreach ($makeDependencies['externalInputFiles'] as $externalInputFile) {
                $externalInputFiles[$externalInputFile] = true;
            }
            foreach ($makeDependencies['externalDependencies'] as $externalDependency) {
                $externalDependencies[$externalDependency['input'] . "\0" . $externalDependency['raw'] . "\0" . $externalDependency['kind']] = $externalDependency;
            }
            foreach ($makeDependencies['outputFiles'] as $outputFile) {
                $outputFiles[$outputFile] = true;
            }
            foreach ($makeDependencies['dependencyEdges'] as $dependencyEdge) {
                $dependencyEdges[] = $dependencyEdge;
            }
        }

        $inputFileList = array_keys($inputFiles);
        sort($inputFileList);
        $externalInputFileList = array_keys($externalInputFiles);
        sort($externalInputFileList);
        $externalDependencyList = array_values($externalDependencies);
        usort(
            $externalDependencyList,
            static fn (array $a, array $b): int => [$a['input'], $a['kind'], $a['raw']] <=> [$b['input'], $b['kind'], $b['raw']]
        );
        $outputFileList = array_keys($outputFiles);
        sort($outputFileList);

        return [
            'inputFiles' => $inputFileList,
            'externalInputFiles' => $externalInputFileList,
            'externalDependencies' => $externalDependencyList,
            'outputFiles' => $outputFileList,
            'dependencyEdges' => $dependencyEdges,
        ];
    }

    /**
     * @return array{inputFiles:list<string>, externalInputFiles:list<string>, externalDependencies:list<array{input:string, raw:string, kind:string}>, outputFiles:list<string>, dependencyEdges:list<array{outputFiles:list<string>, inputFiles:list<string>, externalInputFiles:list<string>}>}
     */
    private function extractZeroDependencyArtifact(string $path, string $bytes): array
    {
        $inputFiles = [];
        $externalInputFiles = [];
        $externalDependencies = [];

        foreach (explode("\0", $bytes) as $dependency) {
            $dependency = trim($dependency);
            if ($dependency === '') {
                continue;
            }

            $classified = $this->normalizeEngineDependencyPath($dependency, $path);
            if ($classified['local']) {
                $inputFiles[$classified['path']] = true;
            } else {
                $externalInputFiles[$classified['path']] = true;
                $this->addExternalDependency($externalDependencies, $classified);
            }
        }

        $inputFileList = array_keys($inputFiles);
        sort($inputFileList);
        $externalInputFileList = array_keys($externalInputFiles);
        sort($externalInputFileList);
        $externalDependencyList = array_values($externalDependencies);
        usort(
            $externalDependencyList,
            static fn (array $a, array $b): int => [$a['input'], $a['kind'], $a['raw']] <=> [$b['input'], $b['kind'], $b['raw']]
        );
        $dependencyEdges = [];
        if ($inputFileList !== [] || $externalInputFileList !== []) {
            $dependencyEdges[] = [
                'outputFiles' => [],
                'inputFiles' => $inputFileList,
                'externalInputFiles' => $externalInputFileList,
            ];
        }

        return [
            'inputFiles' => $inputFileList,
            'externalInputFiles' => $externalInputFileList,
            'externalDependencies' => $externalDependencyList,
            'outputFiles' => [],
            'dependencyEdges' => $dependencyEdges,
        ];
    }

    /**
     * @return array{inputFiles:list<string>, externalInputFiles:list<string>, externalDependencies:list<array{input:string, raw:string, kind:string}>, outputFiles:list<string>, dependencyEdges:list<array{outputFiles:list<string>, inputFiles:list<string>, externalInputFiles:list<string>}>}
     */
    private function extractMakeDependencyArtifact(string $path, string $bytes): array
    {
        $inputFiles = [];
        $externalInputFiles = [];
        $externalDependencies = [];
        $outputFiles = [];
        $dependencyEdges = [];
        $text = preg_replace("/\\\\\r?\n/", ' ', $bytes) ?? $bytes;

        foreach (preg_split('/\R/u', $text) ?: [] as $line) {
            $line = trim($line);
            if ($line === '' || str_starts_with($line, '#')) {
                continue;
            }

            $colonOffset = $this->findMakeDependencyColon($line);
            if ($colonOffset === null) {
                continue;
            }

            $edgeOutputFiles = [];
            $edgeInputFiles = [];
            $edgeExternalInputFiles = [];

            foreach ($this->tokenizeMakeDependencyWords(substr($line, 0, $colonOffset)) as $target) {
                $classified = $this->normalizeEngineDependencyPath($target, $path);
                if ($classified['local']) {
                    $outputFiles[$classified['path']] = true;
                    $edgeOutputFiles[$classified['path']] = true;
                }
            }

            foreach ($this->tokenizeMakeDependencyWords(substr($line, $colonOffset + 1)) as $dependency) {
                $classified = $this->normalizeEngineDependencyPath($dependency, $path);
                if ($classified['local']) {
                    $inputFiles[$classified['path']] = true;
                    $edgeInputFiles[$classified['path']] = true;
                } else {
                    $externalInputFiles[$classified['path']] = true;
                    $this->addExternalDependency($externalDependencies, $classified);
                    $edgeExternalInputFiles[$classified['path']] = true;
                }
            }

            if ($edgeOutputFiles !== [] || $edgeInputFiles !== [] || $edgeExternalInputFiles !== []) {
                $edgeOutputFileList = array_keys($edgeOutputFiles);
                sort($edgeOutputFileList);
                $edgeInputFileList = array_keys($edgeInputFiles);
                sort($edgeInputFileList);
                $edgeExternalInputFileList = array_keys($edgeExternalInputFiles);
                sort($edgeExternalInputFileList);
                $dependencyEdges[] = [
                    'outputFiles' => $edgeOutputFileList,
                    'inputFiles' => $edgeInputFileList,
                    'externalInputFiles' => $edgeExternalInputFileList,
                ];
            }
        }

        $inputFileList = array_keys($inputFiles);
        sort($inputFileList);
        $externalInputFileList = array_keys($externalInputFiles);
        sort($externalInputFileList);
        $externalDependencyList = array_values($externalDependencies);
        usort(
            $externalDependencyList,
            static fn (array $a, array $b): int => [$a['input'], $a['kind'], $a['raw']] <=> [$b['input'], $b['kind'], $b['raw']]
        );
        $outputFileList = array_keys($outputFiles);
        sort($outputFileList);

        return [
            'inputFiles' => $inputFileList,
            'externalInputFiles' => $externalInputFileList,
            'externalDependencies' => $externalDependencyList,
            'outputFiles' => $outputFileList,
            'dependencyEdges' => $dependencyEdges,
        ];
    }

    private function findMakeDependencyColon(string $line): ?int
    {
        $length = strlen($line);
        for ($index = 0; $index < $length; $index++) {
            if ($line[$index] !== ':') {
                continue;
            }

            $slashes = 0;
            for ($previous = $index - 1; $previous >= 0 && $line[$previous] === '\\'; $previous--) {
                $slashes++;
            }
            if ($slashes % 2 === 0) {
                return $index;
            }
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private function tokenizeMakeDependencyWords(string $text): array
    {
        $tokens = [];
        $current = '';
        $escaping = false;
        $length = strlen($text);

        for ($index = 0; $index < $length; $index++) {
            $character = $text[$index];
            if ($escaping) {
                $current .= $character;
                $escaping = false;
                continue;
            }
            if ($character === '\\') {
                $escaping = true;
                continue;
            }
            if (ctype_space($character)) {
                if ($current !== '') {
                    $tokens[] = $current;
                    $current = '';
                }
                continue;
            }

            $current .= $character;
        }
        if ($escaping) {
            $current .= '\\';
        }
        if ($current !== '') {
            $tokens[] = $current;
        }

        return $tokens;
    }

    /**
     * @param array<string, array{input:string, raw:string, kind:string}> $dependencies
     * @param array{path:string, local:bool, raw:string, externalKind:string|null} $classified
     */
    private function addExternalDependency(array &$dependencies, array $classified): void
    {
        if ($classified['local']) {
            return;
        }

        $kind = $classified['externalKind'] ?? 'external';
        $entry = [
            'input' => $classified['path'],
            'raw' => $classified['raw'],
            'kind' => $kind,
        ];
        $dependencies[$entry['input'] . "\0" . $entry['raw'] . "\0" . $entry['kind']] = $entry;
    }

    /**
     * @return array{path:string, local:bool, raw:string, externalKind:string|null}
     */
    private function normalizeEngineDependencyPath(string $path, string $artifactPath): array
    {
        $path = str_replace('\\', '/', trim($path));
        $path = trim($path, " \t\n\r\0\x0B'\"`");
        if ($path === '') {
            throw new \RuntimeException('dependency path is empty in ' . $artifactPath);
        }
        if (str_contains($path, "\0")) {
            throw new \RuntimeException('dependency path contains NUL bytes in ' . $artifactPath);
        }
        $rawPath = $path;
        $fileUri = preg_match('/\Afile:\/\//i', $path) === 1;
        if ($fileUri) {
            $uriPath = parse_url($path, PHP_URL_PATH);
            if (is_string($uriPath) && $uriPath !== '') {
                $path = rawurldecode($uriPath);
            }
        }
        $typstPackageInput = $this->typstPackageInputForDependencyPath($path);
        if ($typstPackageInput !== null) {
            return ['path' => $typstPackageInput, 'local' => false, 'raw' => $rawPath, 'externalKind' => 'typst-package'];
        }
        $externalKind = null;
        if (str_starts_with($path, '/')) {
            $externalKind = $fileUri ? 'file-uri' : 'absolute';
        } elseif (preg_match('/\A[A-Za-z]:\//', $path) === 1) {
            $externalKind = 'windows-absolute';
        } elseif ($this->isUriResourceReference($path)) {
            $externalKind = 'uri';
        }
        if ($externalKind !== null) {
            return ['path' => $this->externalSourceMapInputName($path), 'local' => false, 'raw' => $rawPath, 'externalKind' => $externalKind];
        }

        try {
            return ['path' => $this->normalizeRelativePath($path, 'PDF engine dependency path'), 'local' => true, 'raw' => $rawPath, 'externalKind' => null];
        } catch (\InvalidArgumentException) {
            return ['path' => $this->externalSourceMapInputName($path), 'local' => false, 'raw' => $rawPath, 'externalKind' => 'invalid'];
        }
    }

    private function isTypstPackageReference(string $path): bool
    {
        return preg_match('/\A@[A-Za-z0-9_-]+\/[A-Za-z0-9_.-]+:[A-Za-z0-9][A-Za-z0-9_.+\-]*(?:\/[^\s]+)?\z/', $path) === 1;
    }

    private function typstPackageInputForDependencyPath(string $path): ?string
    {
        if (str_starts_with($path, 'typst-package:')) {
            $reference = substr($path, strlen('typst-package:'));

            return $this->isTypstPackageReference($reference) ? 'typst-package:' . $reference : null;
        }
        if ($this->isTypstPackageReference($path)) {
            return 'typst-package:' . $path;
        }
        if (preg_match('~(?:\A|/)typst/packages/([A-Za-z0-9_-]+)/([A-Za-z0-9_.-]+)/([A-Za-z0-9][A-Za-z0-9_.+\-]*)(?:/(.+))?\z~', $path, $matches) !== 1) {
            return null;
        }

        $reference = '@' . $matches[1] . '/' . $matches[2] . ':' . $matches[3];
        if (isset($matches[4]) && $matches[4] !== '') {
            try {
                $reference .= '/' . $this->normalizeRelativePath($matches[4], 'Typst package dependency subpath');
            } catch (\InvalidArgumentException) {
                return null;
            }
        }

        return 'typst-package:' . $reference;
    }

    /**
     * @param list<string> $inputs
     * @return list<array{input:string, reference:string, namespace:string, package:string, version:string, subpath:string|null, sourceClass:string}>
     */
    private function typstPackageDependenciesFor(array $inputs): array
    {
        $dependencies = [];
        foreach ($inputs as $input) {
            if (!str_starts_with($input, 'typst-package:')) {
                continue;
            }

            $reference = substr($input, strlen('typst-package:'));
            if (preg_match('/\A@([A-Za-z0-9_-]+)\/([A-Za-z0-9_.-]+):([A-Za-z0-9][A-Za-z0-9_.+\-]*)(?:\/(.+))?\z/', $reference, $matches) !== 1) {
                continue;
            }

            $namespace = $matches[1];
            $dependencies[] = [
                'input' => $input,
                'reference' => $reference,
                'namespace' => $namespace,
                'package' => $matches[2],
                'version' => $matches[3],
                'subpath' => $matches[4] ?? null,
                'sourceClass' => $this->typstPackageSourceClass($namespace),
            ];
        }

        return $dependencies;
    }

    private function typstPackageSourceClass(string $namespace): string
    {
        if ($namespace === 'preview') {
            return 'preview-registry';
        }
        if ($namespace === 'typst') {
            return 'typst-registry';
        }

        return 'custom-namespace';
    }

    /**
     * @param list<string> $diagnostics
     */
    private function appendTypstImportPathPolicyDiagnostics(array &$diagnostics, array $policy): void
    {
        if ($policy === []) {
            return;
        }

        $append = static function (string $diagnostic) use (&$diagnostics): void {
            if (!in_array($diagnostic, $diagnostics, true)) {
                $diagnostics[] = $diagnostic;
            }
        };

        $append('typst-import-path-policy:' . (is_string($policy['reviewStatus'] ?? null) ? $policy['reviewStatus'] : 'review'));
        $append('typst-import-paths:' . (int) ($policy['pathCount'] ?? 0));
        foreach ([
            'packagePathCount' => 'typst-import-path-packages',
            'localPathCount' => 'typst-import-path-local',
            'remotePathCount' => 'typst-import-path-remote',
            'absolutePathCount' => 'typst-import-path-absolute',
            'unsafePathCount' => 'typst-import-path-unsafe',
            'duplicatePathCount' => 'typst-import-path-duplicates',
            'unsupportedCount' => 'typst-import-path-unsupported',
        ] as $key => $diagnosticPrefix) {
            $count = (int) ($policy[$key] ?? 0);
            if ($count > 0) {
                $append($diagnosticPrefix . ':' . $count);
            }
        }

        foreach (is_array($policy['sourceClassCounts'] ?? null) ? $policy['sourceClassCounts'] : [] as $sourceClass => $count) {
            if (is_string($sourceClass) && is_int($count) && $count > 0) {
                $append('typst-import-path-source:' . $sourceClass . ':' . $count);
            }
        }
        foreach (is_array($policy['unsupportedReasonCounts'] ?? null) ? $policy['unsupportedReasonCounts'] : [] as $reason => $count) {
            if (is_string($reason) && is_int($count) && $count > 0) {
                $append('typst-import-path-unsupported-reason:' . $reason . ':' . $count);
            }
        }
        foreach (is_array($policy['issueCounts'] ?? null) ? $policy['issueCounts'] : [] as $issue => $count) {
            if (is_string($issue) && is_int($count) && $count > 0) {
                $append('typst-import-path-issue:' . $issue . ':' . $count);
            }
        }
        foreach ([
            'duplicateUnsupportedExpressionCount' => 'typst-import-path-unsupported-expression-duplicates',
            'sourceSidecarPackageConflictCount' => 'typst-import-path-source-sidecar-conflicts',
            'literalDynamicImportConflictCount' => 'typst-import-path-literal-dynamic-conflicts',
            'dynamicSidecarPackageConflictCount' => 'typst-import-path-dynamic-sidecar-conflicts',
        ] as $key => $diagnosticPrefix) {
            $count = (int) ($policy[$key] ?? 0);
            if ($count > 0) {
                $append($diagnosticPrefix . ':' . $count);
            }
        }
    }

    /**
     * @return array<string, mixed>
     */
    private function typstImportPathPolicyFor(string $engine, ?string $sourceBytes): array
    {
        if ($engine !== 'typst' || $sourceBytes === null || $sourceBytes === '') {
            return [];
        }

        $entries = [];
        $unsupported = [];
        $matches = [];
        $searchBytes = $this->typstDirectiveSearchBytes($sourceBytes);
        if (preg_match_all('/#(import|include)\b/i', $searchBytes, $matches, PREG_SET_ORDER | PREG_OFFSET_CAPTURE) === false) {
            return [];
        }

        $sourceLength = strlen($sourceBytes);
        foreach ($matches as $match) {
            $operation = strtolower($match[1][0]);
            $directiveOffset = $match[0][1];
            $cursor = $directiveOffset + strlen($match[0][0]);
            $cursor = $this->skipTypstWhitespaceAndComments($sourceBytes, $cursor);

            $lineColumn = $this->sourceLineColumnForOffset($sourceBytes, $directiveOffset);
            if ($cursor >= $sourceLength || ($sourceBytes[$cursor] !== '"' && $sourceBytes[$cursor] !== "'")) {
                $unsupported[] = [
                    'operation' => $operation,
                    'reason' => 'dynamic-' . $operation . '-path',
                    'expression' => $this->readTypstImportPathExpressionSnippet($sourceBytes, $cursor, $operation),
                    'line' => $lineColumn['line'],
                    'column' => $lineColumn['column'],
                ];
                continue;
            }

            $literal = $this->readTypstQuotedPathLiteral($sourceBytes, $cursor);
            if ($literal === null) {
                $unsupported[] = [
                    'operation' => $operation,
                    'reason' => 'unterminated-' . $operation . '-path',
                    'expression' => $this->readTypstImportPathExpressionSnippet($sourceBytes, $cursor, $operation),
                    'line' => $lineColumn['line'],
                    'column' => $lineColumn['column'],
                ];
                continue;
            }

            $entries[] = $this->typstImportPathEntry($operation, $literal['raw'], $lineColumn['line'], $lineColumn['column']);
        }

        if ($entries === [] && $unsupported === []) {
            return [];
        }

        $operationCounts = ['import' => 0, 'include' => 0];
        $kindCounts = ['package' => 0, 'relative' => 0, 'absolute' => 0, 'uri' => 0, 'invalid' => 0];
        $sourceClassCounts = [];
        $issueCounts = [];
        $packageReferences = [];
        $packageInputs = [];
        $localImportHints = [];
        $remoteImportPaths = [];
        $unsafeImportPaths = [];
        $pathOccurrences = [];
        $unsafePathCount = 0;

        foreach ($entries as $entry) {
            $operation = is_string($entry['operation'] ?? null) ? $entry['operation'] : 'import';
            if (isset($operationCounts[$operation])) {
                ++$operationCounts[$operation];
            }

            $kind = is_string($entry['pathKind'] ?? null) ? $entry['pathKind'] : 'invalid';
            if (!isset($kindCounts[$kind])) {
                $kind = 'invalid';
            }
            ++$kindCounts[$kind];

            $path = is_string($entry['path'] ?? null) ? $entry['path'] : '';
            if ($path !== '') {
                $pathOccurrences[$path][] = $entry;
            }
            if (($entry['safe'] ?? false) !== true) {
                ++$unsafePathCount;
                if ($path !== '') {
                    $unsafeImportPaths[$path] = true;
                }
            }
            if ($kind === 'package') {
                $reference = is_string($entry['packageReference'] ?? null) ? $entry['packageReference'] : $path;
                if ($reference !== '') {
                    $packageReferences[$reference] = true;
                    $packageInputs['typst-package:' . $reference] = true;
                }
                $sourceClass = is_string($entry['sourceClass'] ?? null) ? $entry['sourceClass'] : '';
                if ($sourceClass !== '') {
                    $sourceClassCounts[$sourceClass] = ($sourceClassCounts[$sourceClass] ?? 0) + 1;
                }
            }
            if (($entry['localHint'] ?? false) === true && $path !== '') {
                $localImportHints[$path] = true;
            }
            if ($kind === 'uri' && $path !== '') {
                $remoteImportPaths[$path] = true;
            }
            foreach (is_array($entry['issues'] ?? null) ? $entry['issues'] : [] as $issue) {
                if (is_string($issue) && $issue !== '') {
                    $issueCounts[$issue] = ($issueCounts[$issue] ?? 0) + 1;
                }
            }
        }

        $duplicates = [];
        foreach ($pathOccurrences as $path => $occurrences) {
            if (count($occurrences) < 2) {
                continue;
            }

            $duplicateOperationCounts = [];
            $lines = [];
            foreach ($occurrences as $occurrence) {
                $operation = is_string($occurrence['operation'] ?? null) ? $occurrence['operation'] : 'import';
                $duplicateOperationCounts[$operation] = ($duplicateOperationCounts[$operation] ?? 0) + 1;
                if (is_int($occurrence['line'] ?? null)) {
                    $lines[] = $occurrence['line'];
                }
            }
            ksort($duplicateOperationCounts);
            $lines = array_values(array_unique($lines));
            sort($lines);
            $duplicates[] = [
                'path' => $path,
                'count' => count($occurrences),
                'operations' => $duplicateOperationCounts,
                'lines' => $lines,
            ];
        }
        usort($duplicates, static fn (array $a, array $b): int => $a['path'] <=> $b['path']);
        if ($duplicates !== []) {
            $issueCounts['duplicate-import-path'] = count($duplicates);
        }

        $unsupportedReasonCounts = [];
        $unsupportedExpressionSummaries = [];
        $unsupportedExpressionSummaryMap = [];
        foreach ($unsupported as $unsupportedEntry) {
            $reason = is_string($unsupportedEntry['reason'] ?? null) ? $unsupportedEntry['reason'] : 'unknown-typst-import-path';
            $unsupportedReasonCounts[$reason] = ($unsupportedReasonCounts[$reason] ?? 0) + 1;
            $operation = is_string($unsupportedEntry['operation'] ?? null) ? $unsupportedEntry['operation'] : 'import';
            $expression = is_string($unsupportedEntry['expression'] ?? null) ? $unsupportedEntry['expression'] : '';
            $summaryKey = $operation . "\0" . $reason . "\0" . $expression;
            if (!isset($unsupportedExpressionSummaryMap[$summaryKey])) {
                $unsupportedExpressionSummaryMap[$summaryKey] = [
                    'operation' => $operation,
                    'reason' => $reason,
                    'expression' => $expression,
                    'count' => 0,
                    'lines' => [],
                ];
            }
            ++$unsupportedExpressionSummaryMap[$summaryKey]['count'];
            if (is_int($unsupportedEntry['line'] ?? null)) {
                $unsupportedExpressionSummaryMap[$summaryKey]['lines'][] = $unsupportedEntry['line'];
            }
        }
        foreach ($unsupportedExpressionSummaryMap as $summary) {
            $lines = array_values(array_unique(array_filter(
                $summary['lines'],
                static fn (mixed $line): bool => is_int($line)
            )));
            sort($lines);
            $summary['lines'] = $lines;
            $unsupportedExpressionSummaries[] = $summary;
        }
        usort($unsupportedExpressionSummaries, static fn (array $a, array $b): int => [
            $a['operation'],
            $a['reason'],
            $a['expression'],
        ] <=> [
            $b['operation'],
            $b['reason'],
            $b['expression'],
        ]);
        $duplicateUnsupportedExpressionSummaries = array_values(array_filter(
            $unsupportedExpressionSummaries,
            static fn (array $summary): bool => (int) ($summary['count'] ?? 0) > 1
        ));
        $duplicateUnsupportedExpressionReferenceCount = array_sum(array_map(
            static fn (array $summary): int => max(0, (int) ($summary['count'] ?? 0) - 1),
            $duplicateUnsupportedExpressionSummaries
        ));
        if ($duplicateUnsupportedExpressionSummaries !== []) {
            $issueCounts['duplicate-unsupported-expression'] = count($duplicateUnsupportedExpressionSummaries);
        }

        ksort($sourceClassCounts);
        ksort($issueCounts);
        ksort($unsupportedReasonCounts);
        $packageReferenceList = array_keys($packageReferences);
        sort($packageReferenceList);
        $packageInputList = array_keys($packageInputs);
        sort($packageInputList);
        $localImportHintList = array_keys($localImportHints);
        sort($localImportHintList);
        $remoteImportPathList = array_keys($remoteImportPaths);
        sort($remoteImportPathList);
        $unsafeImportPathList = array_keys($unsafeImportPaths);
        sort($unsafeImportPathList);

        $packageDependencies = $this->typstPackageDependenciesFor($packageInputList);
        $issues = [];
        if ($kindCounts['package'] > 0) {
            $issues[] = 'package-import-paths:' . $kindCounts['package'];
        }
        foreach ($issueCounts as $issue => $count) {
            $issues[] = $issue . ':' . $count;
        }
        foreach ($unsupportedReasonCounts as $reason => $count) {
            $issues[] = 'unsupported-' . $reason . ':' . $count;
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'metadataOnly' => true,
            'byteExposurePolicy' => 'metadata-only',
            'networkAccessPolicy' => 'not-executed',
            'pathCount' => count($entries),
            'literalPathCount' => count($entries),
            'importCount' => $operationCounts['import'],
            'includeCount' => $operationCounts['include'],
            'packagePathCount' => $kindCounts['package'],
            'relativePathCount' => $kindCounts['relative'],
            'localPathCount' => $kindCounts['relative'],
            'remotePathCount' => $kindCounts['uri'],
            'absolutePathCount' => $kindCounts['absolute'],
            'invalidPathCount' => $kindCounts['invalid'],
            'unsafePathCount' => $unsafePathCount,
            'duplicatePathCount' => count($duplicates),
            'duplicateReferenceCount' => array_sum(array_map(static fn (array $duplicate): int => max(0, $duplicate['count'] - 1), $duplicates)),
            'unsupportedCount' => count($unsupported),
            'unsupportedReasonCounts' => $unsupportedReasonCounts,
            'unsupportedExpressionSummaries' => $unsupportedExpressionSummaries,
            'duplicateUnsupportedExpressionCount' => count($duplicateUnsupportedExpressionSummaries),
            'duplicateUnsupportedExpressionReferenceCount' => $duplicateUnsupportedExpressionReferenceCount,
            'duplicateUnsupportedExpressionSummaries' => $duplicateUnsupportedExpressionSummaries,
            'sourceClassCounts' => $sourceClassCounts,
            'packageImportReferences' => $packageReferenceList,
            'packageDependencies' => $packageDependencies,
            'localImportHints' => $localImportHintList,
            'remoteImportPaths' => $remoteImportPathList,
            'unsafeImportPaths' => $unsafeImportPathList,
            'paths' => $entries,
            'duplicates' => $duplicates,
            'unsupported' => $unsupported,
            'issueCounts' => $issueCounts,
            'issues' => $issues,
        ];
    }

    /**
     * @param list<string> $engineTypstPackageInputs
     * @return array<string, mixed>
     */
    private function typstImportPathPolicyWithSidecarPackageComparison(string $engine, array $policy, array $engineTypstPackageInputs): array
    {
        if ($engine !== 'typst' || $policy === [] || $engineTypstPackageInputs === []) {
            return $policy;
        }

        $sourcePackageReferences = array_values(array_filter(
            $policy['packageImportReferences'] ?? [],
            static fn (mixed $reference): bool => is_string($reference) && $reference !== ''
        ));
        $sourcePackageReferences = array_values(array_unique($sourcePackageReferences));
        sort($sourcePackageReferences);

        $sidecarPackageReferences = [];
        foreach ($this->typstPackageDependenciesFor($engineTypstPackageInputs) as $dependency) {
            if (is_string($dependency['reference'] ?? null) && $dependency['reference'] !== '') {
                $sidecarPackageReferences[] = $dependency['reference'];
            }
        }
        $sidecarPackageReferences = array_values(array_unique($sidecarPackageReferences));
        sort($sidecarPackageReferences);

        $sourceOnlyPackageImports = array_values(array_diff($sourcePackageReferences, $sidecarPackageReferences));
        $sidecarOnlyPackageImports = array_values(array_diff($sidecarPackageReferences, $sourcePackageReferences));
        sort($sourceOnlyPackageImports);
        sort($sidecarOnlyPackageImports);
        $sourceSidecarConflictCount = count($sourceOnlyPackageImports) + count($sidecarOnlyPackageImports);
        $policy['sourceSidecarPackageComparison'] = [
            'sourcePackageCount' => count($sourcePackageReferences),
            'sidecarPackageCount' => count($sidecarPackageReferences),
            'sourceOnlyCount' => count($sourceOnlyPackageImports),
            'sidecarOnlyCount' => count($sidecarOnlyPackageImports),
            'sourcePackageReferences' => $sourcePackageReferences,
            'sidecarPackageReferences' => $sidecarPackageReferences,
            'sourceOnlyPackageImports' => $sourceOnlyPackageImports,
            'sidecarOnlyPackageImports' => $sidecarOnlyPackageImports,
        ];
        $policy['sourceSidecarPackageConflictCount'] = $sourceSidecarConflictCount;
        $policy['sourceSidecarPackageConflicts'] = [];
        if ($sourceOnlyPackageImports !== []) {
            $policy['sourceSidecarPackageConflicts'][] = [
                'kind' => 'source-only-package-imports',
                'packageReferences' => $sourceOnlyPackageImports,
            ];
        }
        if ($sidecarOnlyPackageImports !== []) {
            $policy['sourceSidecarPackageConflicts'][] = [
                'kind' => 'sidecar-only-package-dependencies',
                'packageReferences' => $sidecarOnlyPackageImports,
            ];
        }

        $dynamicUnsupported = $this->typstDynamicUnsupportedImportRows($policy);
        $dynamicExpressions = $this->typstUnsupportedExpressionRows($dynamicUnsupported);
        $literalDynamicConflictCount = $sourcePackageReferences !== [] ? count($dynamicUnsupported) : 0;
        $policy['literalDynamicImportConflictCount'] = $literalDynamicConflictCount;
        $policy['literalDynamicImportConflicts'] = $literalDynamicConflictCount > 0 ? [[
            'literalPackageReferences' => $sourcePackageReferences,
            'dynamicExpressions' => $dynamicExpressions,
        ]] : [];

        $dynamicSidecarConflictCount = $dynamicUnsupported !== [] ? count($sidecarOnlyPackageImports) : 0;
        $policy['dynamicSidecarPackageConflictCount'] = $dynamicSidecarConflictCount;
        $policy['dynamicSidecarPackageConflicts'] = $dynamicSidecarConflictCount > 0 ? [[
            'sidecarOnlyPackageReferences' => $sidecarOnlyPackageImports,
            'dynamicExpressions' => $dynamicExpressions,
        ]] : [];

        $issueCounts = is_array($policy['issueCounts'] ?? null) ? $policy['issueCounts'] : [];
        if ($sourceSidecarConflictCount > 0) {
            $issueCounts['source-sidecar-package-disagreement'] = $sourceSidecarConflictCount;
        }
        if ($literalDynamicConflictCount > 0) {
            $issueCounts['literal-dynamic-import-mix'] = $literalDynamicConflictCount;
        }
        if ($dynamicSidecarConflictCount > 0) {
            $issueCounts['dynamic-sidecar-package-disagreement'] = $dynamicSidecarConflictCount;
        }
        ksort($issueCounts);
        $policy['issueCounts'] = $issueCounts;

        $issues = is_array($policy['issues'] ?? null)
            ? array_values(array_filter($policy['issues'], static fn (mixed $issue): bool => is_string($issue) && $issue !== ''))
            : [];
        foreach ([
            'source-sidecar-package-disagreement' => $sourceSidecarConflictCount,
            'literal-dynamic-import-mix' => $literalDynamicConflictCount,
            'dynamic-sidecar-package-disagreement' => $dynamicSidecarConflictCount,
        ] as $issue => $count) {
            if ($count > 0) {
                $issues[] = $issue . ':' . $count;
            }
        }
        $policy['issues'] = array_values(array_unique($issues));
        if ($policy['issues'] !== []) {
            $policy['reviewStatus'] = 'review';
        }

        return $policy;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function typstDynamicUnsupportedImportRows(array $policy): array
    {
        $rows = [];
        foreach (is_array($policy['unsupported'] ?? null) ? $policy['unsupported'] : [] as $entry) {
            if (!is_array($entry)) {
                continue;
            }
            $reason = is_string($entry['reason'] ?? null) ? $entry['reason'] : '';
            if (str_starts_with($reason, 'dynamic-')) {
                $rows[] = $entry;
            }
        }

        return $rows;
    }

    /**
     * @param list<array<string, mixed>> $unsupportedRows
     * @return list<array{operation:string, reason:string, expression:string, line:int|null, column:int|null}>
     */
    private function typstUnsupportedExpressionRows(array $unsupportedRows): array
    {
        $rows = [];
        foreach ($unsupportedRows as $entry) {
            $rows[] = [
                'operation' => is_string($entry['operation'] ?? null) ? $entry['operation'] : 'import',
                'reason' => is_string($entry['reason'] ?? null) ? $entry['reason'] : 'unknown-typst-import-path',
                'expression' => is_string($entry['expression'] ?? null) ? $entry['expression'] : '',
                'line' => is_int($entry['line'] ?? null) ? $entry['line'] : null,
                'column' => is_int($entry['column'] ?? null) ? $entry['column'] : null,
            ];
        }

        return $rows;
    }

    private function typstDirectiveSearchBytes(string $sourceBytes): string
    {
        $masked = $sourceBytes;
        $length = strlen($sourceBytes);
        $state = 'code';
        $quote = '';
        $escaped = false;
        $blockDepth = 0;

        for ($cursor = 0; $cursor < $length; ++$cursor) {
            $char = $sourceBytes[$cursor];
            $next = $cursor + 1 < $length ? $sourceBytes[$cursor + 1] : '';

            if ($state === 'line-comment') {
                if ($char === "\n" || $char === "\r") {
                    $state = 'code';
                    continue;
                }
                $masked[$cursor] = ' ';
                continue;
            }

            if ($state === 'block-comment') {
                if ($char !== "\n" && $char !== "\r") {
                    $masked[$cursor] = ' ';
                }
                if ($char === '/' && $next === '*') {
                    $masked[$cursor] = ' ';
                    $masked[$cursor + 1] = ' ';
                    ++$cursor;
                    ++$blockDepth;
                    continue;
                }
                if ($char === '*' && $next === '/') {
                    $masked[$cursor] = ' ';
                    $masked[$cursor + 1] = ' ';
                    ++$cursor;
                    --$blockDepth;
                    if ($blockDepth <= 0) {
                        $state = 'code';
                    }
                    continue;
                }
                continue;
            }

            if ($state === 'string') {
                if ($char !== "\n" && $char !== "\r") {
                    $masked[$cursor] = ' ';
                }
                if ($escaped) {
                    $escaped = false;
                    continue;
                }
                if ($char === '\\') {
                    $escaped = true;
                    continue;
                }
                if ($char === $quote) {
                    $state = 'code';
                    $quote = '';
                }
                continue;
            }

            if ($char === '/' && $next === '/') {
                $masked[$cursor] = ' ';
                $masked[$cursor + 1] = ' ';
                ++$cursor;
                $state = 'line-comment';
                continue;
            }
            if ($char === '/' && $next === '*') {
                $masked[$cursor] = ' ';
                $masked[$cursor + 1] = ' ';
                ++$cursor;
                $state = 'block-comment';
                $blockDepth = 1;
                continue;
            }
            if ($char === '"' || $char === "'") {
                $masked[$cursor] = ' ';
                $state = 'string';
                $quote = $char;
                $escaped = false;
            }
        }

        return $masked;
    }

    private function skipTypstWhitespaceAndComments(string $sourceBytes, int $offset): int
    {
        $cursor = max(0, $offset);
        $length = strlen($sourceBytes);

        while ($cursor < $length) {
            while ($cursor < $length && ctype_space($sourceBytes[$cursor])) {
                ++$cursor;
            }
            if ($cursor + 1 >= $length) {
                return $cursor;
            }
            if ($sourceBytes[$cursor] === '/' && $sourceBytes[$cursor + 1] === '/') {
                $cursor += 2;
                while ($cursor < $length && $sourceBytes[$cursor] !== "\n" && $sourceBytes[$cursor] !== "\r") {
                    ++$cursor;
                }
                continue;
            }
            if ($sourceBytes[$cursor] === '/' && $sourceBytes[$cursor + 1] === '*') {
                $cursor += 2;
                $depth = 1;
                while ($cursor < $length && $depth > 0) {
                    if ($cursor + 1 < $length && $sourceBytes[$cursor] === '/' && $sourceBytes[$cursor + 1] === '*') {
                        $cursor += 2;
                        ++$depth;
                        continue;
                    }
                    if ($cursor + 1 < $length && $sourceBytes[$cursor] === '*' && $sourceBytes[$cursor + 1] === '/') {
                        $cursor += 2;
                        --$depth;
                        continue;
                    }
                    ++$cursor;
                }
                continue;
            }
            break;
        }

        return $cursor;
    }

    private function readTypstImportPathExpressionSnippet(string $sourceBytes, int $offset, string $operation): string
    {
        $length = strlen($sourceBytes);
        if ($offset >= $length) {
            return '';
        }

        $raw = '';
        $quote = '';
        $escaped = false;
        $blockCommentDepth = 0;
        $roundDepth = 0;
        $squareDepth = 0;
        $curlyDepth = 0;

        for ($cursor = max(0, $offset); $cursor < $length; ++$cursor) {
            $char = $sourceBytes[$cursor];
            $next = $cursor + 1 < $length ? $sourceBytes[$cursor + 1] : '';

            if ($blockCommentDepth > 0) {
                if ($char === "\n" || $char === "\r") {
                    $raw .= ' ';
                    continue;
                }
                if ($char === '/' && $next === '*') {
                    ++$blockCommentDepth;
                    ++$cursor;
                    continue;
                }
                if ($char === '*' && $next === '/') {
                    --$blockCommentDepth;
                    ++$cursor;
                    continue;
                }
                continue;
            }

            if ($quote !== '') {
                $raw .= $char;
                if ($escaped) {
                    $escaped = false;
                    continue;
                }
                if ($char === '\\') {
                    $escaped = true;
                    continue;
                }
                if ($char === $quote) {
                    $quote = '';
                }
                continue;
            }

            if ($char === "\n" || $char === "\r") {
                break;
            }
            if ($char === '/' && $next === '/') {
                break;
            }
            if ($char === '/' && $next === '*') {
                $raw .= ' ';
                $blockCommentDepth = 1;
                ++$cursor;
                continue;
            }
            if ($operation === 'import' && $char === ':' && $roundDepth === 0 && $squareDepth === 0 && $curlyDepth === 0) {
                break;
            }
            if ($char === '"' || $char === "'") {
                $quote = $char;
                $escaped = false;
                $raw .= $char;
                continue;
            }

            if ($char === '(') {
                ++$roundDepth;
            } elseif ($char === ')' && $roundDepth > 0) {
                --$roundDepth;
            } elseif ($char === '[') {
                ++$squareDepth;
            } elseif ($char === ']' && $squareDepth > 0) {
                --$squareDepth;
            } elseif ($char === '{') {
                ++$curlyDepth;
            } elseif ($char === '}' && $curlyDepth > 0) {
                --$curlyDepth;
            }

            $raw .= $char;
        }

        $compact = preg_replace('/\s+/', ' ', trim($raw));
        $snippet = is_string($compact) ? $compact : trim($raw);
        if (strlen($snippet) > 160) {
            return substr($snippet, 0, 157) . '...';
        }

        return $snippet;
    }

    /**
     * @return array<string, mixed>
     */
    private function typstImportPathEntry(string $operation, string $rawPath, int $line, int $column): array
    {
        $path = str_replace('\\', '/', trim($rawPath));
        $entry = [
            'operation' => $operation,
            'raw' => $rawPath,
            'path' => $path,
            'pathKind' => 'invalid',
            'safe' => false,
            'localHint' => false,
            'packageReference' => null,
            'sourceClass' => null,
            'line' => $line,
            'column' => $column,
            'issues' => [],
        ];

        if ($path === '') {
            $entry['issues'][] = 'empty-' . $operation . '-path';
            return $entry;
        }
        if (str_contains($path, "\0")) {
            $entry['issues'][] = 'nul-' . $operation . '-path';
            return $entry;
        }

        if ($this->isTypstPackageReference($path)) {
            $dependency = $this->typstPackageDependenciesFor(['typst-package:' . $path])[0] ?? null;
            $entry['pathKind'] = 'package';
            $entry['safe'] = true;
            $entry['packageReference'] = is_array($dependency) && is_string($dependency['reference'] ?? null) ? $dependency['reference'] : $path;
            $entry['sourceClass'] = is_array($dependency) && is_string($dependency['sourceClass'] ?? null) ? $dependency['sourceClass'] : null;
            return $entry;
        }

        if (str_starts_with($path, '/') || preg_match('/\A[A-Za-z]:\//', $path) === 1) {
            $entry['pathKind'] = 'absolute';
            $entry['issues'][] = 'absolute-' . $operation . '-path';
            return $entry;
        }

        if ($this->isUriResourceReference($path)) {
            $entry['pathKind'] = 'uri';
            $entry['issues'][] = 'remote-' . $operation . '-path';
            return $entry;
        }

        try {
            $entry['path'] = $this->normalizeRelativePath($path, 'Typst ' . $operation . ' path');
            $entry['pathKind'] = 'relative';
            $entry['safe'] = true;
            $entry['localHint'] = true;
        } catch (\InvalidArgumentException) {
            $entry['pathKind'] = 'relative';
            $entry['localHint'] = true;
            $entry['issues'][] = $this->pathContainsParentSegment($path)
                ? 'parent-relative-' . $operation . '-path'
                : 'invalid-local-' . $operation . '-path';
        }

        return $entry;
    }

    /**
     * @return array{raw:string,endOffset:int}|null
     */
    private function readTypstQuotedPathLiteral(string $sourceBytes, int $offset): ?array
    {
        $quote = $sourceBytes[$offset] ?? '';
        if ($quote !== '"' && $quote !== "'") {
            return null;
        }

        $raw = '';
        $escaped = false;
        $length = strlen($sourceBytes);
        for ($cursor = $offset + 1; $cursor < $length; ++$cursor) {
            $char = $sourceBytes[$cursor];
            if ($escaped) {
                $raw .= $char;
                $escaped = false;
                continue;
            }
            if ($char === '\\') {
                $escaped = true;
                continue;
            }
            if ($char === $quote) {
                return ['raw' => $raw, 'endOffset' => $cursor + 1];
            }
            if ($char === "\n" || $char === "\r") {
                return null;
            }
            $raw .= $char;
        }

        return null;
    }

    /**
     * @return array{line:int,column:int}
     */
    private function sourceLineColumnForOffset(string $sourceBytes, int $offset): array
    {
        $offset = max(0, min(strlen($sourceBytes), $offset));
        $prefix = substr($sourceBytes, 0, $offset);
        $line = substr_count($prefix, "\n") + 1;
        $lastNewline = strrpos($prefix, "\n");
        $column = $lastNewline === false ? $offset + 1 : $offset - $lastNewline;

        return ['line' => $line, 'column' => $column];
    }

    private function pathContainsParentSegment(string $path): bool
    {
        foreach (explode('/', str_replace('\\', '/', $path)) as $part) {
            if ($part === '..') {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array{input:string, reference:string, namespace:string, package:string, version:string, subpath:string|null, sourceClass:string}> $dependencies
     * @param list<array{artifact:string, outputFiles:list<string>, inputFiles:list<string>, externalInputFiles:list<string>}> $dependencyEdges
     * @param array<string, string> $engineDependencyArtifactsSha256
     * @return array<string, mixed>
     */
    private function typstPackageDependencyPolicy(
        string $engine,
        array $dependencies,
        array $dependencyEdges,
        array $engineDependencyArtifactsSha256
    ): array
    {
        if ($engine !== 'typst' || $dependencies === []) {
            return [];
        }

        $namespaces = [];
        $namespaceCounts = [];
        $packages = [];
        $packageCoordinates = [];
        $versions = [];
        $versionsByPackage = [];
        $inputsByPackageVersion = [];
        $inputsByCoordinate = [];
        $sourceClasses = [];
        $sourceClassCounts = [];
        $unsupportedPackageReasons = [];
        $unsupportedReasonCounts = [];
        $subpathDependencyCount = 0;
        foreach ($dependencies as $dependency) {
            $namespace = $dependency['namespace'];
            $packageName = $namespace . '/' . $dependency['package'];
            $version = $dependency['version'];
            $coordinate = $packageName . ':' . $version;

            $namespaces[$namespace] = true;
            $namespaceCounts[$namespace] = ($namespaceCounts[$namespace] ?? 0) + 1;
            $packages[$packageName] = true;
            $packageCoordinates[$coordinate] = true;
            $versions[$version] = true;
            $versionsByPackage[$packageName][$version] = true;
            $inputsByPackageVersion[$packageName][$version][] = $dependency['input'];
            $inputsByCoordinate[$coordinate][$dependency['input']] = true;
            $sourceClass = $dependency['sourceClass'];
            $sourceClasses[$sourceClass] = true;
            $sourceClassCounts[$sourceClass] = ($sourceClassCounts[$sourceClass] ?? 0) + 1;
            $unsupportedReason = $this->typstPackageUnsupportedReason($sourceClass);
            $unsupportedReasonCounts[$unsupportedReason] = ($unsupportedReasonCounts[$unsupportedReason] ?? 0) + 1;
            $unsupportedPackageReasons[] = [
                'input' => $dependency['input'],
                'reference' => $dependency['reference'],
                'sourceClass' => $sourceClass,
                'reason' => $unsupportedReason,
            ];
            if ($dependency['subpath'] !== null) {
                $subpathDependencyCount++;
            }
        }

        $namespaceList = array_keys($namespaces);
        $packageList = array_keys($packages);
        $packageCoordinateList = array_keys($packageCoordinates);
        $versionList = array_keys($versions);
        $sourceClassList = array_keys($sourceClasses);
        sort($namespaceList);
        sort($packageList);
        sort($packageCoordinateList);
        sort($versionList);
        sort($sourceClassList);
        ksort($namespaceCounts);
        ksort($sourceClassCounts);
        ksort($unsupportedReasonCounts);

        $versionConflicts = [];
        foreach ($versionsByPackage as $packageName => $packageVersions) {
            $conflictVersions = array_keys($packageVersions);
            sort($conflictVersions);
            if (count($conflictVersions) < 2) {
                continue;
            }

            $inputs = [];
            foreach ($conflictVersions as $version) {
                foreach ($inputsByPackageVersion[$packageName][$version] ?? [] as $input) {
                    $inputs[$input] = true;
                }
            }
            $inputList = array_keys($inputs);
            sort($inputList);
            $versionConflicts[] = [
                'package' => $packageName,
                'versions' => $conflictVersions,
                'inputs' => $inputList,
            ];
        }
        usort($versionConflicts, static fn (array $a, array $b): int => $a['package'] <=> $b['package']);

        $duplicateDependencyCount = 0;
        $duplicateDependencySummaries = [];
        ksort($inputsByCoordinate);
        foreach ($inputsByCoordinate as $coordinate => $inputs) {
            $inputList = array_keys($inputs);
            sort($inputList);
            if (count($inputList) < 2) {
                continue;
            }

            $duplicateDependencyCount += count($inputList) - 1;
            $duplicateDependencySummaries[] = [
                'packageCoordinate' => $coordinate,
                'dependencyCount' => count($inputList),
                'inputs' => $inputList,
            ];
        }

        $sidecarFiles = array_keys($engineDependencyArtifactsSha256);
        sort($sidecarFiles);
        $sidecarPackageInputCounts = [];
        foreach ($dependencyEdges as $edge) {
            $artifact = $edge['artifact'] ?? null;
            if (!is_string($artifact) || $artifact === '') {
                continue;
            }

            $packageInputs = [];
            foreach (($edge['externalInputFiles'] ?? []) as $externalInputFile) {
                if (is_string($externalInputFile) && str_starts_with($externalInputFile, 'typst-package:')) {
                    $packageInputs[$externalInputFile] = true;
                }
            }
            if ($packageInputs === []) {
                continue;
            }

            $packageInputList = array_keys($packageInputs);
            sort($packageInputList);
            $sidecarPackageInputCounts[] = [
                'artifact' => $artifact,
                'packageInputCount' => count($packageInputList),
                'packageInputs' => $packageInputList,
            ];
        }
        usort($sidecarPackageInputCounts, static fn (array $a, array $b): int => $a['artifact'] <=> $b['artifact']);

        $issues = ['typst-package-dependencies:' . count($dependencies)];
        foreach ($versionConflicts as $conflict) {
            $issues[] = 'package-version-conflict:' . $conflict['package'];
        }
        foreach ($duplicateDependencySummaries as $summary) {
            $issues[] = 'duplicate-package-dependency:' . $summary['packageCoordinate'];
        }

        return [
            'reviewStatus' => 'review',
            'packageDependencyCount' => count($dependencies),
            'namespaces' => $namespaceList,
            'packages' => $packageList,
            'versions' => $versionList,
            'sourceClasses' => $sourceClassList,
            'sourceClassCounts' => $sourceClassCounts,
            'subpathDependencyCount' => $subpathDependencyCount,
            'packageCount' => count($packageCoordinateList),
            'namespaceCounts' => $namespaceCounts,
            'packageCoordinates' => $packageCoordinateList,
            'packageNames' => $packageList,
            'sidecarFileCount' => count($sidecarFiles),
            'sidecarFiles' => $sidecarFiles,
            'sidecarPackageInputCounts' => $sidecarPackageInputCounts,
            'metadataOnly' => true,
            'byteExposurePolicy' => 'metadata-only',
            'networkAccessPolicy' => 'not-executed',
            'unsupportedPackageCount' => count($unsupportedPackageReasons),
            'unsupportedPackageReasons' => $unsupportedPackageReasons,
            'unsupportedReasonCounts' => $unsupportedReasonCounts,
            'duplicateDependencyCount' => $duplicateDependencyCount,
            'duplicateDependencySummaries' => $duplicateDependencySummaries,
            'versionConflictCount' => count($versionConflicts),
            'versionConflicts' => $versionConflicts,
            'issues' => $issues,
        ];
    }

    private function typstPackageUnsupportedReason(string $sourceClass): string
    {
        if ($sourceClass === 'preview-registry') {
            return 'preview-registry-network-not-executed';
        }
        if ($sourceClass === 'typst-registry') {
            return 'typst-registry-network-not-executed';
        }

        return 'custom-namespace-not-resolved';
    }

    /**
     * @param array<string, string> $engineDependencyArtifactsSha256
     * @param list<array{input:string, raw:string, kind:string}> $externalDependencies
     * @return array{reviewStatus:string, externalDependencyCount:int, packageDependencyCount:int, nonPackageDependencyCount:int, dependencies:list<array{input:string, raw:string, kind:string, reviewStatus:string, issues:list<string>}>, issues:list<string>}|array{}
     */
    private function typstExternalDependencyPolicy(
        string $engine,
        array $engineDependencyArtifactsSha256,
        array $externalDependencies
    ): array {
        if ($engine !== 'typst' || $engineDependencyArtifactsSha256 === [] || $externalDependencies === []) {
            return [];
        }

        $dependencies = [];
        $issues = [];
        $packageDependencyCount = 0;
        $nonPackageDependencyCount = 0;
        foreach ($externalDependencies as $externalDependency) {
            $input = $externalDependency['input'] ?? null;
            $raw = $externalDependency['raw'] ?? null;
            $kind = $externalDependency['kind'] ?? null;
            if (!is_string($input) || $input === '' || !is_string($raw) || $raw === '' || !is_string($kind) || $kind === '') {
                continue;
            }

            $dependencyIssues = [];
            if ($kind === 'typst-package') {
                ++$packageDependencyCount;
            } else {
                ++$nonPackageDependencyCount;
                if ($kind === 'uri') {
                    $dependencyIssues[] = 'remote-dependency-boundary';
                } elseif ($kind === 'file-uri') {
                    $dependencyIssues[] = 'file-uri-dependency-boundary';
                } elseif ($kind === 'invalid') {
                    $dependencyIssues[] = 'invalid-external-dependency-boundary';
                }
            }
            foreach ($dependencyIssues as $dependencyIssue) {
                $issues[] = $dependencyIssue;
            }

            $dependencies[] = [
                'input' => $input,
                'raw' => $raw,
                'kind' => $kind,
                'reviewStatus' => $dependencyIssues === [] ? 'ok' : 'review',
                'issues' => $dependencyIssues,
            ];
        }

        usort(
            $dependencies,
            static fn (array $a, array $b): int => [$a['input'], $a['kind'], $a['raw']] <=> [$b['input'], $b['kind'], $b['raw']]
        );
        $issues = array_values(array_unique($issues));
        sort($issues);

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'externalDependencyCount' => count($dependencies),
            'packageDependencyCount' => $packageDependencyCount,
            'nonPackageDependencyCount' => $nonPackageDependencyCount,
            'dependencies' => $dependencies,
            'issues' => $issues,
        ];
    }

    /**
     * @param array<string, string> $engineDependencyArtifactsSha256
     * @param list<string> $engineOutputFiles
     * @return array{reviewStatus:string, declaredOutputFile:string, dependencyOutputFiles:list<string>, declaredOutputPresent:bool, extraOutputFiles:list<string>, issues:list<string>}|array{}
     */
    private function typstDependencyOutputPolicy(
        string $engine,
        array $engineDependencyArtifactsSha256,
        string $outputFile,
        array $engineOutputFiles
    ): array {
        if ($engine !== 'typst' || $engineDependencyArtifactsSha256 === []) {
            return [];
        }

        $extraOutputFiles = array_values(array_diff($engineOutputFiles, [$outputFile]));
        sort($extraOutputFiles);
        $declaredOutputPresent = in_array($outputFile, $engineOutputFiles, true);
        $issues = [];
        if ($engineOutputFiles === []) {
            $issues[] = 'missing-output-targets';
        }
        if (!$declaredOutputPresent) {
            $issues[] = 'missing-declared-output';
        }
        if ($extraOutputFiles !== []) {
            $issues[] = 'unexpected-output-files:' . count($extraOutputFiles);
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'declaredOutputFile' => $outputFile,
            'dependencyOutputFiles' => $engineOutputFiles,
            'declaredOutputPresent' => $declaredOutputPresent,
            'extraOutputFiles' => $extraOutputFiles,
            'issues' => $issues,
        ];
    }

    /**
     * @return array{
     *     inputs:list<array{tag:int, path:string}>,
     *     inputFiles:list<string>,
     *     externalInputs:list<string>,
     *     lineRanges:list<array{tag:int, path:string, minLine:int, maxLine:int, references:int}>
     * }
     */
    private function extractSourceMapArtifact(string $path, string $bytes): array
    {
        if (preg_match('/\.gz\z/i', $path) === 1) {
            $text = GzipStream::decode($bytes, self::MAX_SOURCE_MAP_BYTES);
        } else {
            if (strlen($bytes) > self::MAX_SOURCE_MAP_BYTES) {
                throw new \RuntimeException('source map exceeds bounded byte limit');
            }
            $text = $bytes;
        }

        $inputs = [];
        $inputFiles = [];
        $externalInputs = [];
        $lineStats = [];

        foreach (preg_split('/\R/u', $text) ?: [] as $line) {
            $line = trim($line);
            if ($line === '') {
                continue;
            }

            if (preg_match('/\AInput:(\d+):(.+)\z/', $line, $matches) === 1) {
                $tag = (int) $matches[1];
                $input = $this->normalizeSourceMapInputPath($matches[2]);
                $inputs[$tag] = ['tag' => $tag, 'path' => $input['path']];
                if ($input['local']) {
                    $inputFiles[$input['path']] = true;
                } else {
                    $externalInputs[$input['path']] = true;
                }
                continue;
            }

            if (preg_match_all('/[\[\(]\s*(\d+),(\d+):/', $line, $matches, PREG_SET_ORDER) < 1) {
                continue;
            }

            foreach ($matches as $match) {
                $tag = (int) $match[1];
                $sourceLine = (int) $match[2];
                if ($sourceLine < 1) {
                    continue;
                }
                if (!isset($lineStats[$tag])) {
                    $lineStats[$tag] = [
                        'minLine' => $sourceLine,
                        'maxLine' => $sourceLine,
                        'references' => 0,
                    ];
                }
                $lineStats[$tag]['minLine'] = min($lineStats[$tag]['minLine'], $sourceLine);
                $lineStats[$tag]['maxLine'] = max($lineStats[$tag]['maxLine'], $sourceLine);
                $lineStats[$tag]['references']++;
            }
        }

        ksort($inputs);
        $ranges = [];
        foreach ($lineStats as $tag => $stats) {
            if (!isset($inputs[$tag])) {
                continue;
            }

            $ranges[] = [
                'tag' => (int) $tag,
                'path' => $inputs[$tag]['path'],
                'minLine' => $stats['minLine'],
                'maxLine' => $stats['maxLine'],
                'references' => $stats['references'],
            ];
        }
        usort($ranges, static fn (array $a, array $b): int => [$a['tag'], $a['path']] <=> [$b['tag'], $b['path']]);

        $inputFileList = array_keys($inputFiles);
        sort($inputFileList);
        $externalInputList = array_keys($externalInputs);
        sort($externalInputList);

        return [
            'inputs' => array_values($inputs),
            'inputFiles' => $inputFileList,
            'externalInputs' => $externalInputList,
            'lineRanges' => $ranges,
        ];
    }

    /**
     * @return array{path:string, local:bool}
     */
    private function normalizeSourceMapInputPath(string $path): array
    {
        $path = str_replace('\\', '/', trim($path));
        $path = trim($path, " \t\n\r\0\x0B'\"`");
        if ($path === '') {
            throw new \RuntimeException('source map input path is empty');
        }
        if (str_contains($path, "\0")) {
            throw new \RuntimeException('source map input path contains NUL bytes');
        }

        if (preg_match('/\Afile:\/\//i', $path) === 1) {
            $uriPath = parse_url($path, PHP_URL_PATH);
            if (is_string($uriPath) && $uriPath !== '') {
                $path = rawurldecode($uriPath);
            }
        }

        if (
            str_starts_with($path, '/')
            || preg_match('/\A[A-Za-z]:\//', $path) === 1
            || $this->isUriResourceReference($path)
        ) {
            return ['path' => $this->externalSourceMapInputName($path), 'local' => false];
        }

        try {
            return ['path' => $this->normalizeRelativePath($path, 'SyncTeX input path'), 'local' => true];
        } catch (\InvalidArgumentException) {
            return ['path' => $this->externalSourceMapInputName($path), 'local' => false];
        }
    }

    private function externalSourceMapInputName(string $path): string
    {
        $path = str_replace('\\', '/', trim($path));
        $uriPath = parse_url($path, PHP_URL_PATH);
        if (is_string($uriPath) && $uriPath !== '') {
            $path = $uriPath;
        }

        $basename = basename($path);

        return $basename === '' || $basename === '.' ? 'external-source' : $basename;
    }

    /**
     * @param list<array{tag:int, path:string}> $inputs
     */
    private function sourceMapReferencesSource(string $sourceFile, array $inputs): bool
    {
        $sourceFile = str_replace('\\', '/', $sourceFile);
        $sourceBasename = basename($sourceFile);
        foreach ($inputs as $input) {
            $inputPath = str_replace('\\', '/', $input['path']);
            if (
                $inputPath === $sourceFile
                || str_ends_with($inputPath, '/' . $sourceFile)
                || basename($inputPath) === $sourceBasename
            ) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<string> $texts
     * @return array{missing:bool, program:string|null}
     */
    private function extractMissingEngineProgram(string $engineProgram, int $exitCode, array $texts, mixed $explicit): array
    {
        $program = $this->engineName($engineProgram);
        if ($explicit !== null) {
            if (is_bool($explicit)) {
                return ['missing' => $explicit, 'program' => $explicit ? $program : null];
            }
            if (is_string($explicit)) {
                return ['missing' => true, 'program' => $this->engineName($explicit)];
            }

            throw new \InvalidArgumentException('PDF fake runner missingProgram must be a boolean or string');
        }

        $engineProgramLower = strtolower(str_replace('\\', '/', $engineProgram));
        $programLower = strtolower($program);
        foreach ($texts as $text) {
            foreach (preg_split('/\R/u', $text) ?: [] as $line) {
                $line = trim($line);
                if ($line === '') {
                    continue;
                }

                $lineLower = strtolower(str_replace('\\', '/', $line));
                $looksMissing = preg_match('/command not found|executable file not found|not recognized as an internal or external command|no such file or directory|\benoent\b|could not find executable|\bnot found\b/i', $line) === 1;
                if (!$looksMissing) {
                    continue;
                }

                $mentionsProgram = str_contains($lineLower, $programLower)
                    || str_contains($lineLower, $engineProgramLower);
                if ($mentionsProgram || $exitCode === 126 || $exitCode === 127) {
                    return ['missing' => true, 'program' => $program];
                }
            }
        }

        return ['missing' => false, 'program' => null];
    }

    /**
     * @param list<string> $texts
     * @return array{warnings:list<string>, errors:list<string>, rerunNeeded:bool}
     */
    private function extractEngineMessages(array $texts): array
    {
        $warnings = [];
        $errors = [];
        $rerunNeeded = false;

        foreach ($texts as $text) {
            foreach (preg_split('/\R/u', $text) ?: [] as $line) {
                $line = trim($line);
                if ($line === '') {
                    continue;
                }
                if ($this->isEngineErrorLine($line)) {
                    $errors[] = $line;
                    continue;
                }
                if ($this->isEngineWarningLine($line)) {
                    $warnings[] = $line;
                }
                if ($this->isEngineRerunLine($line)) {
                    $rerunNeeded = true;
                }
            }
        }

        return [
            'warnings' => array_values(array_unique($warnings)),
            'errors' => array_values(array_unique($errors)),
            'rerunNeeded' => $rerunNeeded,
        ];
    }

    /**
     * @param list<string> $texts
     * @return list<array{message:string, sourceFile:string|null, line:int|null, column:int|null, endLine:int|null, endColumn:int|null, hints:list<string>, root:string|null, insideRoot:bool|null, boundaryStatus:string, issues:list<string>}>
     */
    private function extractTypstWarningProvenance(string $engine, array $texts, ?string $root): array
    {
        if ($engine !== 'typst') {
            return [];
        }

        $warnings = [];
        $seen = [];
        foreach ($texts as $text) {
            if (!is_string($text) || $text === '') {
                continue;
            }

            foreach ($this->extractTypstJsonWarningProvenance($text, $root) as $warning) {
                $key = json_encode($warning);
                if ($key === false) {
                    $key = serialize($warning);
                }
                if (isset($seen[$key])) {
                    continue;
                }

                $seen[$key] = true;
                $warnings[] = $warning;
            }

            $lines = preg_split('/\R/u', $text);
            if ($lines === false) {
                $lines = preg_split('/\r\n|\r|\n/', $text) ?: [];
            }
            $lineCount = count($lines);
            for ($index = 0; $index < $lineCount; $index++) {
                $line = trim((string) $lines[$index]);
                if (
                    preg_match('/\Awarning:\s*(.+)\z/i', $line, $matches) !== 1
                    || preg_match('/\b0\s+warnings?\b/i', $line) === 1
                ) {
                    continue;
                }

                $message = trim($matches[1]);
                $location = null;
                $hints = [];
                for ($probe = $index + 1; $probe < $lineCount; $probe++) {
                    $probeLine = trim((string) $lines[$probe]);
                    if ($probeLine === '') {
                        continue;
                    }
                    if (preg_match('/\A(?:warning|error):\s+/i', $probeLine) === 1) {
                        break;
                    }
                    if ($location === null) {
                        $location = $this->parseTypstDiagnosticLocation($probeLine);
                    }

                    $hint = $this->typstDiagnosticHintLine($probeLine);
                    if ($hint !== null) {
                        $hints[] = $hint;
                    }
                }

                $warning = $this->typstWarningProvenanceEntry(
                    $message,
                    $location,
                    $root,
                    array_values(array_unique($hints))
                );
                $key = json_encode($warning);
                if ($key === false) {
                    $key = serialize($warning);
                }
                if (isset($seen[$key])) {
                    continue;
                }

                $seen[$key] = true;
                $warnings[] = $warning;
            }
        }

        return $warnings;
    }

    /**
     * @return list<array{message:string, sourceFile:string|null, line:int|null, column:int|null, endLine:int|null, endColumn:int|null, hints:list<string>, root:string|null, insideRoot:bool|null, boundaryStatus:string, issues:list<string>}>
     */
    private function extractTypstJsonWarningProvenance(string $text, ?string $root): array
    {
        $warnings = [];
        foreach ($this->decodeJsonDiagnosticRecords($text) as $record) {
            if (!is_array($record)) {
                continue;
            }

            $severity = $record['severity'] ?? $record['level'] ?? $record['kind'] ?? null;
            if (!is_string($severity) || strtolower($severity) !== 'warning') {
                continue;
            }

            $message = $record['message'] ?? $record['text'] ?? $record['title'] ?? null;
            if (!is_string($message) || trim($message) === '') {
                continue;
            }

            $warnings[] = $this->typstWarningProvenanceEntry(
                trim($message),
                $this->parseTypstJsonDiagnosticLocation($record),
                $root,
                $this->typstJsonDiagnosticHints($record)
            );
        }

        return $warnings;
    }

    /**
     * @return list<mixed>
     */
    private function decodeJsonDiagnosticRecords(string $text): array
    {
        $records = [];
        $trimmed = trim($text);
        if ($trimmed === '') {
            return [];
        }

        if ($trimmed[0] === '{' || $trimmed[0] === '[') {
            $decoded = json_decode($trimmed, true);
            if (is_array($decoded)) {
                if (array_is_list($decoded)) {
                    return $decoded;
                }

                return [$decoded];
            }
        }

        $lines = preg_split('/\R/u', $text);
        if ($lines === false) {
            $lines = preg_split('/\r\n|\r|\n/', $text) ?: [];
        }

        foreach ($lines as $line) {
            $line = trim((string) $line);
            if ($line === '' || ($line[0] !== '{' && $line[0] !== '[')) {
                continue;
            }

            $decoded = json_decode($line, true);
            if (!is_array($decoded)) {
                continue;
            }

            if (array_is_list($decoded)) {
                foreach ($decoded as $item) {
                    $records[] = $item;
                }
                continue;
            }

            $records[] = $decoded;
        }

        return $records;
    }

    /**
     * @param array<string, mixed> $record
     * @return array{sourceFile:string, sourceLocal:bool, line:int, column:int, endLine:int|null, endColumn:int|null}|null
     */
    private function parseTypstJsonDiagnosticLocation(array $record): ?array
    {
        $location = $record['span'] ?? $record['location'] ?? $record['range'] ?? $record;
        if (!is_array($location)) {
            return null;
        }

        $path = $this->typstJsonDiagnosticPath($location);
        if ($path === null) {
            $path = $this->typstJsonDiagnosticPath($record);
        }
        if ($path === null) {
            return null;
        }

        try {
            $classified = $this->normalizeEngineDependencyPath($path, 'Typst JSON warning diagnostic');
        } catch (\RuntimeException) {
            return null;
        }

        $start = is_array($location['start'] ?? null) ? $location['start'] : (is_array($location['range']['start'] ?? null) ? $location['range']['start'] : null);
        $end = is_array($location['end'] ?? null) ? $location['end'] : (is_array($location['range']['end'] ?? null) ? $location['range']['end'] : null);
        $line = $this->positiveIntFromKeys($location, ['line', 'lineNumber']);
        if ($line === null && $start !== null) {
            $line = $this->positiveIntFromKeys($start, ['line', 'lineNumber']);
        }
        $column = $this->positiveIntFromKeys($location, ['column', 'col', 'columnNumber', 'character']);
        if ($column === null && $start !== null) {
            $column = $this->positiveIntFromKeys($start, ['column', 'col', 'columnNumber', 'character']);
        }
        if ($line === null || $column === null) {
            return null;
        }

        $endLine = $this->positiveIntFromKeys($location, ['endLine', 'endLineNumber']);
        if ($endLine === null && $end !== null) {
            $endLine = $this->positiveIntFromKeys($end, ['line', 'lineNumber']);
        }
        $endColumn = $this->positiveIntFromKeys($location, ['endColumn', 'endCol', 'endColumnNumber', 'endCharacter']);
        if ($endColumn === null && $end !== null) {
            $endColumn = $this->positiveIntFromKeys($end, ['column', 'col', 'columnNumber', 'character']);
        }

        return [
            'sourceFile' => $classified['path'],
            'sourceLocal' => $classified['local'],
            'line' => $line,
            'column' => $column,
            'endLine' => $endLine,
            'endColumn' => $endColumn,
        ];
    }

    /**
     * @param array<string, mixed> $location
     */
    private function typstJsonDiagnosticPath(array $location): ?string
    {
        foreach (['path', 'file', 'filename', 'source'] as $key) {
            if (is_string($location[$key] ?? null) && $location[$key] !== '') {
                return $location[$key];
            }
        }

        foreach (['file', 'source', 'input'] as $key) {
            if (is_array($location[$key] ?? null)) {
                $path = $this->typstJsonDiagnosticPath($location[$key]);
                if ($path !== null) {
                    return $path;
                }
            }
        }

        return null;
    }

    /**
     * @param array<string, mixed> $record
     * @return list<string>
     */
    private function typstJsonDiagnosticHints(array $record): array
    {
        $hints = [];
        foreach (['hint', 'help'] as $key) {
            if (is_string($record[$key] ?? null) && trim($record[$key]) !== '') {
                $hints[] = trim($record[$key]);
            }
        }

        foreach (['hints', 'helps', 'notes'] as $key) {
            if (!is_array($record[$key] ?? null)) {
                continue;
            }
            foreach ($record[$key] as $hint) {
                if (is_string($hint) && trim($hint) !== '') {
                    $hints[] = trim($hint);
                    continue;
                }
                if (is_array($hint) && is_string($hint['message'] ?? null) && trim($hint['message']) !== '') {
                    $hints[] = trim($hint['message']);
                }
            }
        }

        return array_values(array_unique($hints));
    }

    private function positiveIntValue(mixed $value): ?int
    {
        if (is_int($value)) {
            return $value > 0 ? $value : null;
        }
        if (is_string($value) && preg_match('/\A[1-9]\d*\z/', $value) === 1) {
            return (int) $value;
        }

        return null;
    }

    /**
     * @param array<string, mixed> $values
     * @param list<string> $keys
     */
    private function positiveIntFromKeys(array $values, array $keys): ?int
    {
        foreach ($keys as $key) {
            $value = $this->positiveIntValue($values[$key] ?? null);
            if ($value !== null) {
                return $value;
            }
        }

        return null;
    }

    /**
     * @return array{sourceFile:string, sourceLocal:bool, line:int, column:int, endLine:int|null, endColumn:int|null}|null
     */
    private function parseTypstDiagnosticLocation(string $line): ?array
    {
        if (preg_match('~([A-Za-z0-9_.@/-][A-Za-z0-9_.@/ -]*\.typ):([1-9]\d*):([1-9]\d*)(?:-(?:(\d+):)?([1-9]\d*))?~u', $line, $matches) !== 1) {
            return null;
        }

        try {
            $classified = $this->normalizeEngineDependencyPath($matches[1], 'Typst warning diagnostic');
        } catch (\RuntimeException) {
            return null;
        }

        $lineNumber = (int) $matches[2];
        $column = (int) $matches[3];
        $endLine = null;
        $endColumn = null;
        if (isset($matches[5]) && $matches[5] !== '') {
            $endLine = isset($matches[4]) && $matches[4] !== '' ? (int) $matches[4] : $lineNumber;
            $endColumn = (int) $matches[5];
        }

        return [
            'sourceFile' => $classified['path'],
            'sourceLocal' => $classified['local'],
            'line' => $lineNumber,
            'column' => $column,
            'endLine' => $endLine,
            'endColumn' => $endColumn,
        ];
    }

    private function typstDiagnosticHintLine(string $line): ?string
    {
        if (preg_match('/\A(?:[=\-*]\s*)?(?:hint|help):\s*(.+)\z/i', trim($line), $matches) !== 1) {
            return null;
        }

        $hint = trim($matches[1]);

        return $hint === '' ? null : $hint;
    }

    /**
     * @param array{sourceFile:string, sourceLocal:bool, line:int, column:int, endLine:int|null, endColumn:int|null}|null $location
     * @param list<string> $hints
     * @return array{message:string, sourceFile:string|null, line:int|null, column:int|null, endLine:int|null, endColumn:int|null, hints:list<string>, root:string|null, insideRoot:bool|null, boundaryStatus:string, issues:list<string>}
     */
    private function typstWarningProvenanceEntry(string $message, ?array $location, ?string $root, array $hints): array
    {
        $sourceFile = null;
        $line = null;
        $column = null;
        $endLine = null;
        $endColumn = null;
        $insideRoot = null;
        $boundaryStatus = 'unknown-source';
        $issues = ['warning-source-missing'];

        if ($location !== null) {
            $sourceFile = $location['sourceFile'];
            $line = $location['line'];
            $column = $location['column'];
            $endLine = $location['endLine'];
            $endColumn = $location['endColumn'];
            $issues = [];

            if (!$location['sourceLocal']) {
                $insideRoot = false;
                $boundaryStatus = 'external-source';
                $issues[] = 'warning-source-external';
            } elseif ($root === null) {
                $boundaryStatus = 'unbounded';
            } elseif ($root === '.' || $sourceFile === $root || str_starts_with($sourceFile, $root . '/')) {
                $insideRoot = true;
                $boundaryStatus = 'inside-root';
            } else {
                $insideRoot = false;
                $boundaryStatus = 'outside-root';
                $issues[] = 'warning-source-outside-root';
            }
        }

        return [
            'message' => $message,
            'sourceFile' => $sourceFile,
            'line' => $line,
            'column' => $column,
            'endLine' => $endLine,
            'endColumn' => $endColumn,
            'hints' => $hints,
            'root' => $root,
            'insideRoot' => $insideRoot,
            'boundaryStatus' => $boundaryStatus,
            'issues' => $issues,
        ];
    }

    /**
     * @param list<array{issues:list<string>}> $warnings
     */
    private function countTypstWarningSourceIssues(array $warnings): int
    {
        $count = 0;
        foreach ($warnings as $warning) {
            if (!is_array($warning['issues'] ?? null)) {
                continue;
            }

            $count += count($warning['issues']);
        }

        return $count;
    }

    /**
     * @param list<string> $texts
     * @return list<array{kind:string, name:string, message:string}>
     */
    private function extractEngineMissingDependencies(array $texts): array
    {
        $dependencies = [];
        $seen = [];

        foreach ($texts as $text) {
            foreach (preg_split('/\R/u', $text) ?: [] as $line) {
                $line = trim($line);
                if ($line === '') {
                    continue;
                }

                if (preg_match('~\bFile\s+[`\'"]([^`\'"]+)[`\'"]\s+not\s+found\b~i', $line, $matches) === 1) {
                    $name = $this->normalizeEngineMissingDependencyName($matches[1]);
                    $this->addEngineMissingDependency(
                        $dependencies,
                        $seen,
                        $this->engineMissingDependencyKindForFile($name),
                        $name,
                        $line
                    );
                }
                if (preg_match('~I\s+can[\'’]t\s+find\s+file\s+[`\'"]?([^`\'"\s.]+(?:\.[A-Za-z0-9_-]+)?)[`\'"]?~i', $line, $matches) === 1) {
                    $name = $this->normalizeEngineMissingDependencyName($matches[1]);
                    $this->addEngineMissingDependency(
                        $dependencies,
                        $seen,
                        $this->engineMissingDependencyKindForFile($name),
                        $name,
                        $line
                    );
                }
                if (preg_match('~fontspec\s+Error:\s+The\s+font\s+[`\'"]([^`\'"]+)[`\'"]\s+(?:cannot\s+be\s+found|not\s+found)~i', $line, $matches) === 1) {
                    $this->addEngineMissingDependency(
                        $dependencies,
                        $seen,
                        'font',
                        $this->normalizeEngineMissingDependencyName($matches[1]),
                        $line
                    );
                }
                if (preg_match('~\bFont\b.*=\s*[`\'"]([^`\'"]+)[`\'"].*(?:not\s+loadable|not\s+found)~i', $line, $matches) === 1) {
                    $this->addEngineMissingDependency(
                        $dependencies,
                        $seen,
                        'font',
                        $this->normalizeEngineMissingDependencyName($matches[1]),
                        $line
                    );
                }
                if (preg_match('~\bkpathsea:\s+Running\s+mk(?:textfm|tex(?:pk|mf)?)\s+([^\s]+)~i', $line, $matches) === 1) {
                    $this->addEngineMissingDependency(
                        $dependencies,
                        $seen,
                        'font-metric',
                        $this->normalizeEngineMissingDependencyName($matches[1]),
                        $line
                    );
                }
            }
        }

        return array_values($dependencies);
    }

    /**
     * @param list<array{kind:string, name:string, message:string}> $dependencies
     * @return array<string, int>
     */
    private function summarizeEngineMissingDependencyKinds(array $dependencies): array
    {
        $counts = [];
        foreach ($dependencies as $dependency) {
            $kind = $dependency['kind'];
            $counts[$kind] = ($counts[$kind] ?? 0) + 1;
        }
        ksort($counts);

        return $counts;
    }

    /**
     * @param list<array{kind:string, name:string, message:string}> $dependencies
     * @param array<string, true> $seen
     */
    private function addEngineMissingDependency(array &$dependencies, array &$seen, string $kind, string $name, string $message): void
    {
        $name = $this->normalizeEngineMissingDependencyName($name);
        if ($name === '') {
            return;
        }

        $key = $kind . ':' . strtolower($name);
        if (isset($seen[$key])) {
            return;
        }

        $seen[$key] = true;
        $dependencies[] = [
            'kind' => $kind,
            'name' => $name,
            'message' => $message,
        ];
    }

    private function normalizeEngineMissingDependencyName(string $name): string
    {
        return trim($name, " \t\n\r\0\x0B`'\".,;:");
    }

    private function engineMissingDependencyKindForFile(string $name): string
    {
        $extension = strtolower(pathinfo($name, PATHINFO_EXTENSION));
        if ($extension === 'typ') {
            return 'typst-file';
        }
        if (in_array($extension, ['sty', 'cls', 'clo', 'def', 'cfg', 'lco', 'fd', 'map', 'enc'], true)) {
            return 'tex-file';
        }
        if (in_array($extension, ['tfm', 'ofm', 'vf'], true)) {
            return 'font-metric';
        }

        return 'engine-file';
    }

    /**
     * @param list<string> $texts
     * @return array{warnings:list<string>, errors:list<string>, needed:bool}
     */
    private function extractBibliographyMessages(array $texts): array
    {
        $warnings = [];
        $errors = [];
        $needed = false;

        foreach ($texts as $text) {
            foreach (preg_split('/\R/u', $text) ?: [] as $line) {
                $line = trim($line);
                if ($line === '') {
                    continue;
                }
                if ($this->isBibliographyErrorLine($line)) {
                    $errors[] = $line;
                    continue;
                }
                if ($this->isBibliographyWarningLine($line)) {
                    $warnings[] = $line;
                }
                if ($this->isBibliographyRunNeededLine($line)) {
                    $needed = true;
                }
            }
        }

        return [
            'warnings' => array_values(array_unique($warnings)),
            'errors' => array_values(array_unique($errors)),
            'needed' => $needed,
        ];
    }

    private function isBibliographyWarningLine(string $line): bool
    {
        if (preg_match('/\b0\s+warnings?\b/i', $line) === 1) {
            return false;
        }

        return preg_match('/\bwarning\b|^Warning--/i', $line) === 1
            && preg_match('/\b(?:biber|bibtex|biblatex|natbib|citation|citations|bibliograph|bibliography|entry|database)\b|^Warning--/i', $line) === 1;
    }

    private function isBibliographyErrorLine(string $line): bool
    {
        if (preg_match('/\b0\s+errors?\b/i', $line) === 1) {
            return false;
        }

        return preg_match('/\b(?:biber|bibtex|biblatex|natbib)\b.*\berror\b|\berror\b.*\b(?:biber|bibtex|biblatex|natbib|citation|bibliograph|bibliography)\b|\AI (?:couldn\'t open database file|found no \\\\bibdata command|found no \\\\bibstyle command)\b|\b[1-9]\d*\s+error messages?\b/i', $line) === 1;
    }

    private function isBibliographyRunNeededLine(string $line): bool
    {
        return preg_match('/please\s+\(re\)run\s+(?:biber|bibtex)|please\s+rerun\s+(?:biber|bibtex)|\brerun\s+(?:biber|bibtex)\b|\b(?:run|re-run)\s+(?:biber|bibtex)\b|undefined citations?|\bCitation\b.*\bundefined\b|No file .*\.bbl\b/i', $line) === 1;
    }

    private function isEngineWarningLine(string $line): bool
    {
        if (preg_match('/\b(?:Overfull|Underfull)\s+\\\\[hv]box\b/i', $line) === 1) {
            return true;
        }

        return preg_match('/\bwarning\b|\bwarning:/i', $line) === 1
            && preg_match('/\b0\s+warnings?\b/i', $line) !== 1;
    }

    private function isEngineErrorLine(string $line): bool
    {
        return preg_match('/\A! .*\bError:|\A! .*Error\b|\bFatal error\b|\bError:/i', $line) === 1
            && preg_match('/\b0\s+errors?\b/i', $line) !== 1;
    }

    private function isEngineRerunLine(string $line): bool
    {
        return preg_match('/\brerun\b/i', $line) === 1
            && preg_match('/cross-references?|bibliograph|citation|label|file .* changed|rerunfilecheck/i', $line) === 1;
    }

    /**
     * @param list<string> $texts
     * @return array{file:string|null, pages:int|null, bytes:int|null}
     */
    private function extractDeclaredOutput(array $texts): array
    {
        $output = ['file' => null, 'pages' => null, 'bytes' => null];

        foreach ($texts as $text) {
            foreach (preg_split('/\R/u', $text) ?: [] as $line) {
                $line = trim($line);
                if ($line === '') {
                    continue;
                }
                if (preg_match('/\bOutput written on\s+(.+?)\s+\((\d+)\s+pages?,\s+(\d+)\s+bytes?\)\.?/i', $line, $matches) !== 1) {
                    continue;
                }

                $output = [
                    'file' => $this->normalizeDeclaredOutputFile($matches[1]),
                    'pages' => (int) $matches[2],
                    'bytes' => (int) $matches[3],
                ];
            }
        }

        return $output;
    }

    private function normalizeDeclaredOutputFile(string $path): string
    {
        $path = str_replace('\\', '/', trim($path));
        $path = trim($path, " \t\n\r\0\x0B'\"`");
        while (str_starts_with($path, './')) {
            $path = substr($path, 2);
        }

        return $path;
    }

    private function declaredOutputFileMatches(string $declaredOutputFile, string $outputFile): bool
    {
        return $declaredOutputFile === $outputFile
            || basename($declaredOutputFile) === basename($outputFile);
    }

    private function hasCompletePdfTrailer(string $pdfBytes): bool
    {
        return preg_match('/%%EOF\s*\z/s', $pdfBytes) === 1;
    }

    /**
     * @return array{
     *     trailerCount:int,
     *     trailerRevisions:list<array{revision:int, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, startxref:int|null, id:list<string>}>,
     *     trailerIdPolicy:array{reviewStatus:string, trailerCount:int, trailerIdCount:int, missingIdCount:int, incompleteIdCount:int, changedIdCount:int, uniqueFirstIdCount:int, uniqueSecondIdCount:int, firstId:string|null, latestId:string|null, stableFirstId:bool|null, stableSecondId:bool|null, revisions:list<array{revision:int, id:list<string>, complete:bool}>, issues:list<string>}|array{},
     *     startXrefOffsets:list<int>,
     *     incrementalUpdates:bool,
     *     xrefStreams:list<array{object:string, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, index:list<int>, w:list<int>, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>,
     *     xrefStreamFilters:array<string, int>,
     *     objectStreams:list<array{object:string, objectCount:int|null, firstByteOffset:int|null, extends:string|null, objectNumbers:list<int>, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>,
     *     objectStreamMembers:list<array{objectStream:string, objectNumber:int, memberIndex:int, declaredOffset:int, streamOffset:int, memberBytes:int|null, memberSha256:string|null, valueKind:string|null, dictionaryKeys:list<string>, type:string|null, subtype:string|null, title:string|null}>,
     *     objectStreamFilters:array<string, int>,
     *     pageCount:int|null,
     *     pageBoxes:list<array{page:int, pageObject:string|null, mediaBox:list<float>|null, cropBox:list<float>|null, bleedBox:list<float>|null, trimBox:list<float>|null, artBox:list<float>|null, rotation:int|null, inherited:list<string>}>,
