    /**
     * @return array{object:string|null, linearizedVersion:float|null, fileLength:int|null, primaryHintOffset:int|null, primaryHintLength:int|null, firstPageObject:int|null, firstPageEndOffset:int|null, pageCount:int|null, mainXrefOffset:int|null, hintTables:list<array{offset:int, length:int}>, lengthMatches:bool|null}|array{}
     */
    private function extractPdfLinearizationMetadata(string $pdfBytes): array
    {
        if (preg_match('/\A%PDF-[^\r\n]*(?:\r\n|\r|\n)(?:%[^\r\n]*(?:\r\n|\r|\n))*\s*(\d+)\s+(\d+)\s+obj\s*(<<.*?>>)\s*endobj/s', $pdfBytes, $matches) !== 1) {
            return [];
        }

        $dictionary = $matches[3];
        if (!str_contains($dictionary, '/Linearized')) {
            return [];
        }

        $version = $this->extractPdfNumberToken($dictionary, 'Linearized');
        if ($version === null) {
            return [];
        }

        $hintTables = [];
        $hints = $this->extractPdfIntegerArrayToken($dictionary, 'H');
        for ($i = 0; $i + 1 < count($hints) && count($hintTables) < 8; $i += 2) {
            $hintTables[] = [
                'offset' => $hints[$i],
                'length' => $hints[$i + 1],
            ];
        }

        $fileLength = $this->extractPdfIntegerToken($dictionary, 'L');

        return [
            'object' => $matches[1] . ' ' . $matches[2] . ' R',
            'linearizedVersion' => $version,
            'fileLength' => $fileLength,
            'primaryHintOffset' => $hintTables[0]['offset'] ?? null,
            'primaryHintLength' => $hintTables[0]['length'] ?? null,
            'firstPageObject' => $this->extractPdfIntegerToken($dictionary, 'O'),
            'firstPageEndOffset' => $this->extractPdfIntegerToken($dictionary, 'E'),
            'pageCount' => $this->extractPdfIntegerToken($dictionary, 'N'),
            'mainXrefOffset' => $this->extractPdfIntegerToken($dictionary, 'T'),
            'hintTables' => $hintTables,
            'lengthMatches' => $fileLength === null ? null : $fileLength === strlen($pdfBytes),
        ];
    }

    private function extractPdfHeaderVersion(string $pdfBytes): ?string
    {
        if (preg_match('/\A%PDF-(\d+\.\d+)\b/', $pdfBytes, $matches) !== 1) {
            return null;
        }

        return $matches[1];
    }

    private function effectivePdfVersion(?string $headerVersion, ?string $catalogVersion): ?string
    {
        if ($headerVersion === null) {
            return $catalogVersion;
        }
        if ($catalogVersion === null) {
            return $headerVersion;
        }

        return version_compare($catalogVersion, $headerVersion, '>') ? $catalogVersion : $headerVersion;
    }

    /**
     * @return list<array{prefix:string, baseVersion:string|null, extensionLevel:int|null}>
     */
    private function extractPdfExtensionMetadata(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/Extensions')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $extensions = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Extensions', $objects);
        if ($extensions === null) {
            return [];
        }

        $metadata = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($extensions) as $entry) {
            $dictionary = null;
            if ($entry['value']['kind'] === 'dictionary') {
                $dictionary = $entry['value']['value'];
            } elseif ($entry['value']['kind'] === 'reference') {
                $dictionary = $objects[$this->pdfReferenceKey($entry['value']['value'])] ?? null;
            }

            if ($dictionary === null) {
                continue;
            }

            $metadata[] = [
                'prefix' => $entry['key'],
                'baseVersion' => $this->extractPdfNameToken($dictionary, 'BaseVersion'),
                'extensionLevel' => $this->extractPdfIntegerToken($dictionary, 'ExtensionLevel'),
            ];
        }

        usort($metadata, static fn (array $a, array $b): int => $a['prefix'] <=> $b['prefix']);

        return $metadata;
    }

    /**
     * @return list<array{revision:int, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, startxref:int|null, id:list<string>}>
     */
    private function extractPdfTrailerRevisions(string $pdfBytes): array
    {
        $revisions = [];
        $offset = 0;
        $length = strlen($pdfBytes);

        while ($offset < $length && ($position = strpos($pdfBytes, 'trailer', $offset)) !== false) {
            $before = $position > 0 ? $pdfBytes[$position - 1] : '';
            $afterPosition = $position + strlen('trailer');
            $after = $afterPosition < $length ? $pdfBytes[$afterPosition] : '';
            if (
                ($before !== '' && preg_match('/[A-Za-z0-9_.-]/', $before) === 1)
                || ($after !== '' && preg_match('/[A-Za-z0-9_.-]/', $after) === 1)
            ) {
                $offset = $afterPosition;
                continue;
            }

            $cursor = $afterPosition;
            while ($cursor < $length && ctype_space($pdfBytes[$cursor])) {
                $cursor++;
            }
            if (substr($pdfBytes, $cursor, 2) !== '<<') {
                $offset = min($length, $cursor + 1);
                continue;
            }

            $parsed = $this->parsePdfDictionary($pdfBytes, $cursor);
            if ($parsed === null) {
                $offset = $cursor + 2;
                continue;
            }

            $dictionary = $parsed['value'];
            $revisions[] = [
                'revision' => count($revisions) + 1,
                'size' => $this->extractPdfIntegerToken($dictionary, 'Size'),
                'root' => $this->extractPdfReferenceToken($dictionary, 'Root'),
                'info' => $this->extractPdfReferenceToken($dictionary, 'Info'),
                'encrypt' => $this->extractPdfReferenceToken($dictionary, 'Encrypt'),
                'prev' => $this->extractPdfIntegerToken($dictionary, 'Prev'),
                'startxref' => $this->extractPdfStartXrefAfter($pdfBytes, $parsed['next']),
                'id' => $this->extractPdfTrailerIdValues($dictionary),
            ];
            $offset = $parsed['next'];
        }

        return $revisions;
    }

    /**
     * @param list<array{revision:int, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, startxref:int|null, id:list<string>}> $revisions
     * @return list<int>
     */
    private function pdfStartXrefOffsets(array $revisions): array
    {
        $offsets = [];
        foreach ($revisions as $revision) {
            if ($revision['startxref'] !== null) {
                $offsets[] = $revision['startxref'];
            }
        }

        return $offsets;
    }

    /**
     * @param list<array{revision:int, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, startxref:int|null, id:list<string>}> $revisions
     */
    private function pdfHasIncrementalUpdates(array $revisions): bool
    {
        if (count($revisions) > 1) {
            return true;
        }

        foreach ($revisions as $revision) {
            if ($revision['prev'] !== null) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array{revision:int, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, startxref:int|null, id:list<string>}> $revisions
     * @return array{reviewStatus:string, trailerCount:int, trailerIdCount:int, missingIdCount:int, incompleteIdCount:int, changedIdCount:int, uniqueFirstIdCount:int, uniqueSecondIdCount:int, firstId:string|null, latestId:string|null, stableFirstId:bool|null, stableSecondId:bool|null, revisions:list<array{revision:int, id:list<string>, complete:bool}>, issues:list<string>}|array{}
     */
    private function summarizePdfTrailerIdPolicy(array $revisions): array
    {
        if ($revisions === []) {
            return [];
        }

        $rows = [];
        $firstIds = [];
        $secondIds = [];
        $missingIdCount = 0;
        $incompleteIdCount = 0;
        foreach ($revisions as $revision) {
            $ids = array_values(array_filter(
                $revision['id'] ?? [],
                static fn (mixed $id): bool => is_string($id) && $id !== ''
            ));
            $complete = count($ids) >= 2;
            if ($ids === []) {
                ++$missingIdCount;
            } elseif (!$complete) {
                ++$incompleteIdCount;
            }

            if (isset($ids[0])) {
                $firstIds[$ids[0]] = true;
            }
            if (isset($ids[1])) {
                $secondIds[$ids[1]] = true;
            }

            $rows[] = [
                'revision' => $revision['revision'],
                'id' => $ids,
                'complete' => $complete,
            ];
        }

        $uniqueFirstIdCount = count($firstIds);
        $uniqueSecondIdCount = count($secondIds);
        $stableFirstId = $uniqueFirstIdCount === 0 ? null : $uniqueFirstIdCount === 1;
        $stableSecondId = $uniqueSecondIdCount === 0 ? null : $uniqueSecondIdCount === 1;
        $changedIdCount = ($stableFirstId === false ? 1 : 0) + ($stableSecondId === false ? 1 : 0);
        $issues = [];
        if ($missingIdCount > 0) {
            $issues[] = 'trailer-id-missing';
        }
        if ($incompleteIdCount > 0) {
            $issues[] = 'trailer-id-incomplete';
        }
        if ($stableFirstId === false) {
            $issues[] = 'trailer-first-id-changed';
        }
        if ($stableSecondId === false) {
            $issues[] = 'trailer-second-id-changed';
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'trailerCount' => count($revisions),
            'trailerIdCount' => count($revisions) - $missingIdCount,
            'missingIdCount' => $missingIdCount,
            'incompleteIdCount' => $incompleteIdCount,
            'changedIdCount' => $changedIdCount,
            'uniqueFirstIdCount' => $uniqueFirstIdCount,
            'uniqueSecondIdCount' => $uniqueSecondIdCount,
            'firstId' => $rows[0]['id'][0] ?? null,
            'latestId' => $rows[count($rows) - 1]['id'][1] ?? ($rows[count($rows) - 1]['id'][0] ?? null),
            'stableFirstId' => $stableFirstId,
            'stableSecondId' => $stableSecondId,
            'revisions' => $rows,
            'issues' => $issues,
        ];
    }

    /**
     * @return list<array{object:string, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, index:list<int>, w:list<int>, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function extractPdfXrefStreams(string $pdfBytes): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $streams = [];
        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'Type') !== 'XRef') {
                continue;
            }

            $stream = $this->summarizePdfStructuralStream($body, self::MAX_XREF_STREAM_BYTES);
            $streams[] = [
                'object' => $reference . ' R',
                'size' => $this->extractPdfIntegerToken($body, 'Size'),
                'root' => $this->extractPdfReferenceToken($body, 'Root'),
                'info' => $this->extractPdfReferenceToken($body, 'Info'),
                'encrypt' => $this->extractPdfReferenceToken($body, 'Encrypt'),
                'prev' => $this->extractPdfIntegerToken($body, 'Prev'),
                'index' => $this->extractPdfIntegerArrayToken($body, 'Index'),
                'w' => $this->extractPdfIntegerArrayToken($body, 'W'),
                'filters' => $this->extractPdfFilterNames($body, $objects),
                'streamBytes' => $stream['bytes'],
                'streamSha256' => $stream['sha256'],
                'streamSkipped' => $stream['skipped'],
            ];
        }

        usort($streams, fn (array $a, array $b): int => $this->pdfReferenceSortKey($a['object']) <=> $this->pdfReferenceSortKey($b['object']));

        return $streams;
    }

    /**
     * @return list<array{object:string, objectCount:int|null, firstByteOffset:int|null, extends:string|null, objectNumbers:list<int>, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function extractPdfObjectStreams(string $pdfBytes): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $streams = [];
        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'Type') !== 'ObjStm') {
                continue;
            }

            $stream = $this->summarizePdfStructuralStream($body, self::MAX_OBJECT_STREAM_BYTES);
            $streams[] = [
                'object' => $reference . ' R',
                'objectCount' => $this->extractPdfIntegerToken($body, 'N'),
                'firstByteOffset' => $this->extractPdfIntegerToken($body, 'First'),
                'extends' => $this->extractPdfReferenceToken($body, 'Extends'),
                'objectNumbers' => $this->extractPdfObjectStreamObjectNumbers($body),
                'filters' => $this->extractPdfFilterNames($body, $objects),
                'streamBytes' => $stream['bytes'],
                'streamSha256' => $stream['sha256'],
                'streamSkipped' => $stream['skipped'],
            ];
        }

        usort($streams, fn (array $a, array $b): int => $this->pdfReferenceSortKey($a['object']) <=> $this->pdfReferenceSortKey($b['object']));

        return $streams;
    }

    /**
     * @return list<array{objectStream:string, objectNumber:int, memberIndex:int, declaredOffset:int, streamOffset:int, memberBytes:int|null, memberSha256:string|null, valueKind:string|null, dictionaryKeys:list<string>, type:string|null, subtype:string|null, title:string|null}>
     */
    private function extractPdfObjectStreamMembers(string $pdfBytes): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $members = [];
        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'Type') !== 'ObjStm') {
                continue;
            }
            if (preg_match('/\/Filter\b/s', $body) === 1) {
                continue;
            }

            $bytes = $this->extractPdfStreamBytes($body);
            if ($bytes === null || strlen($bytes) > self::MAX_OBJECT_STREAM_BYTES) {
                continue;
            }

            $first = $this->extractPdfIntegerToken($body, 'First');
            if ($first === null) {
                continue;
            }

            $streamReference = $reference . ' R';
            $payloadStart = max(0, min(strlen($bytes), $first));
            $payloadBytes = max(0, strlen($bytes) - $payloadStart);
            $pairs = $this->extractPdfObjectStreamHeaderPairs($body);
            foreach ($pairs as $index => $pair) {
                $memberBytes = null;
                $memberSha256 = null;
                $valueKind = null;
                $dictionaryKeys = [];
                $type = null;
                $subtype = null;
                $title = null;
                if ($pair['offset'] <= $payloadBytes) {
                    $endOffset = $this->nextPdfObjectStreamMemberOffset($pairs, $pair['offset'], $payloadBytes);
                    $memberBody = substr($bytes, $payloadStart + $pair['offset'], max(0, $endOffset - $pair['offset']));
                    $memberBytes = strlen($memberBody);
                    $memberSha256 = hash('sha256', $memberBody);
                    $parsed = $this->parsePdfValueAt(ltrim($memberBody), 0);
                    if ($parsed !== null) {
                        $valueKind = $parsed['kind'] === 'keyword' && $parsed['value'] === 'null' ? 'null' : $parsed['kind'];
                        if ($parsed['kind'] === 'dictionary') {
                            foreach ($this->extractPdfTopLevelDictionaryEntries($parsed['value']) as $entry) {
                                $dictionaryKeys[] = $entry['key'];
                            }
                            $dictionaryKeys = array_values(array_unique($dictionaryKeys));
                            sort($dictionaryKeys);
                            $type = $this->extractPdfStringOrNameValue($parsed['value'], 'Type');
                            $subtype = $this->extractPdfStringOrNameValue($parsed['value'], 'Subtype');
                            $title = $this->extractPdfStringOrNameValue($parsed['value'], 'Title');
                        }
                    }
                }

                $members[] = [
                    'objectStream' => $streamReference,
                    'objectNumber' => $pair['objectNumber'],
                    'memberIndex' => $index + 1,
                    'declaredOffset' => $pair['offset'],
                    'streamOffset' => $payloadStart + $pair['offset'],
                    'memberBytes' => $memberBytes,
                    'memberSha256' => $memberSha256,
                    'valueKind' => $valueKind,
                    'dictionaryKeys' => $dictionaryKeys,
                    'type' => $type,
                    'subtype' => $subtype,
                    'title' => $title,
                ];
            }
        }

        usort($members, function (array $a, array $b): int {
            $left = $this->pdfReferenceSortKey($a['objectStream']);
            $right = $this->pdfReferenceSortKey($b['objectStream']);

            return [$left[0], $left[1], $a['memberIndex']] <=> [$right[0], $right[1], $b['memberIndex']];
        });

        return $members;
    }

    /**
     * @return list<array{objectNumber:int, offset:int}>
     */
    private function extractPdfObjectStreamHeaderPairs(string $dictionary): array
    {
        if (preg_match('/\/Filter\b/s', $dictionary) === 1) {
            return [];
        }

        $bytes = $this->extractPdfStreamBytes($dictionary);
        if ($bytes === null || strlen($bytes) > self::MAX_OBJECT_STREAM_BYTES) {
            return [];
        }

        $first = $this->extractPdfIntegerToken($dictionary, 'First');
        if ($first === null) {
            return [];
        }

        $objectCount = $this->extractPdfIntegerToken($dictionary, 'N');
        $headerLength = max(0, min(strlen($bytes), $first));
        $header = substr($bytes, 0, $headerLength);
        if (preg_match_all('/-?\d+/', $header, $matches) < 1) {
            return [];
        }

        $numbers = array_map('intval', $matches[0]);
        $pairs = [];
        $limit = $objectCount === null ? intdiv(count($numbers), 2) : max(0, $objectCount);
        for ($i = 0; $i + 1 < count($numbers) && count($pairs) < $limit; $i += 2) {
            if ($numbers[$i] < 0 || $numbers[$i + 1] < 0) {
                continue;
            }

            $pairs[] = [
                'objectNumber' => $numbers[$i],
                'offset' => $numbers[$i + 1],
            ];
        }

        return $pairs;
    }

    /**
     * @param list<array{objectNumber:int, offset:int}> $pairs
     */
    private function nextPdfObjectStreamMemberOffset(array $pairs, int $offset, int $payloadBytes): int
    {
        $next = $payloadBytes;
        foreach ($pairs as $pair) {
            if ($pair['offset'] > $offset && $pair['offset'] < $next) {
                $next = $pair['offset'];
            }
        }

        return $next;
    }

    /**
     * @param list<array{filters:list<string>}> $streams
     * @return array<string, int>
     */
    private function summarizePdfStructuralStreamFilters(array $streams): array
    {
        $filters = [];
        foreach ($streams as $stream) {
            foreach ($stream['filters'] as $filter) {
                if ($filter === '') {
                    continue;
                }

                $filters[$filter] = ($filters[$filter] ?? 0) + 1;
            }
        }

        ksort($filters);

        return $filters;
    }

    /**
     * @param list<array{object:string, filters:list<string>, streamBytes:int|null, streamSkipped:string|null}> $xrefStreams
     * @param list<array{object:string, filters:list<string>, streamBytes:int|null, streamSkipped:string|null}> $objectStreams
     * @param list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, filters:list<string>, streamBytes:int|null, streamSkipped:string|null}> $pageContentStreams
     * @param list<array{page:int, pageObject:string|null, resourceName:string, imageObject:string|null, filters:list<string>, streamBytes:int|null, streamSkipped:string|null}> $images
     * @param list<array{page:int, pageObject:string|null, resourceName:string, formObject:string|null, filters:list<string>, streamBytes:int|null, streamSkipped:string|null}> $formXObjects
     * @param list<array{source:string, appearanceObject:string|null, filters:list<string>, streamBytes:int|null, streamSkipped:string|null}> $annotationAppearances
     * @param list<array{source:string, object:string|null, filters:list<string>, streamBytes:int|null, streamSkipped:string|null}> $embeddedFileStreams
     * @return array{streamCount:int, filterCount:int, filters:array<string, int>, surfaces:array<string, int>, actions:array<string, int>, streams:list<array{surface:string, source:string, object:string|null, filters:list<string>, action:string, streamBytes:int|null, streamSkipped:string|null}>}|array{}
     */
    private function summarizePdfStreamFilterPolicy(
        array $xrefStreams,
        array $objectStreams,
        array $pageContentStreams,
        array $images,
        array $formXObjects,
        array $annotationAppearances,
        array $embeddedFileStreams
    ): array {
        $streams = [];

        foreach ($xrefStreams as $stream) {
            $object = is_string($stream['object'] ?? null) ? $stream['object'] : null;
            $source = $object === null ? 'xref:unknown' : 'xref:' . $object;
            $this->addPdfStreamFilterPolicyEntry(
                $streams,
                'xref-stream',
                $source,
                $object,
                $stream['filters'] ?? [],
                $stream['streamBytes'] ?? null,
                $stream['streamSkipped'] ?? null
            );
        }

        foreach ($objectStreams as $stream) {
            $object = is_string($stream['object'] ?? null) ? $stream['object'] : null;
            $source = $object === null ? 'object-stream:unknown' : 'object-stream:' . $object;
            $this->addPdfStreamFilterPolicyEntry(
                $streams,
                'object-stream',
                $source,
                $object,
                $stream['filters'] ?? [],
                $stream['streamBytes'] ?? null,
                $stream['streamSkipped'] ?? null
            );
        }

        foreach ($pageContentStreams as $stream) {
            $this->addPdfStreamFilterPolicyEntry(
                $streams,
                'page-content',
                is_string($stream['source'] ?? null) ? $stream['source'] : 'page:unknown.Contents',
                is_string($stream['contentObject'] ?? null) ? $stream['contentObject'] : null,
                $stream['filters'] ?? [],
                $stream['streamBytes'] ?? null,
                $stream['streamSkipped'] ?? null
            );
        }

        foreach ($images as $image) {
            $pageObject = is_string($image['pageObject'] ?? null) ? $image['pageObject'] : 'unknown';
            $resourceName = is_string($image['resourceName'] ?? null) && $image['resourceName'] !== '' ? $image['resourceName'] : 'unknown';
            $this->addPdfStreamFilterPolicyEntry(
                $streams,
                'image-xobject',
                'page:' . $pageObject . '.XObject.' . $resourceName,
                is_string($image['imageObject'] ?? null) ? $image['imageObject'] : null,
                $image['filters'] ?? [],
                $image['streamBytes'] ?? null,
                $image['streamSkipped'] ?? null
            );
        }

        foreach ($formXObjects as $form) {
            $pageObject = is_string($form['pageObject'] ?? null) ? $form['pageObject'] : 'unknown';
            $resourceName = is_string($form['resourceName'] ?? null) && $form['resourceName'] !== '' ? $form['resourceName'] : 'unknown';
            $this->addPdfStreamFilterPolicyEntry(
                $streams,
                'form-xobject',
                'page:' . $pageObject . '.XObject.' . $resourceName,
                is_string($form['formObject'] ?? null) ? $form['formObject'] : null,
                $form['filters'] ?? [],
                $form['streamBytes'] ?? null,
                $form['streamSkipped'] ?? null
            );
        }

        foreach ($annotationAppearances as $appearance) {
            $this->addPdfStreamFilterPolicyEntry(
                $streams,
                'annotation-appearance',
                is_string($appearance['source'] ?? null) ? $appearance['source'] : 'annotation:unknown.AP',
                is_string($appearance['appearanceObject'] ?? null) ? $appearance['appearanceObject'] : null,
                $appearance['filters'] ?? [],
                $appearance['streamBytes'] ?? null,
                $appearance['streamSkipped'] ?? null
            );
        }

        foreach ($embeddedFileStreams as $embeddedFileStream) {
            $this->addPdfStreamFilterPolicyEntry(
                $streams,
                'embedded-file',
                is_string($embeddedFileStream['source'] ?? null) ? $embeddedFileStream['source'] : 'embedded-file:unknown',
                is_string($embeddedFileStream['object'] ?? null) ? $embeddedFileStream['object'] : null,
                $embeddedFileStream['filters'] ?? [],
                $embeddedFileStream['streamBytes'] ?? null,
                $embeddedFileStream['streamSkipped'] ?? null
            );
        }

        if ($streams === []) {
            return [];
        }

        $filters = [];
        $surfaces = [];
        $actions = [];
        foreach ($streams as $stream) {
            $surfaces[$stream['surface']] = ($surfaces[$stream['surface']] ?? 0) + 1;
            $actions[$stream['action']] = ($actions[$stream['action']] ?? 0) + 1;
            foreach ($stream['filters'] as $filter) {
                $filters[$filter] = ($filters[$filter] ?? 0) + 1;
            }
        }

        ksort($filters);
        ksort($surfaces);
        ksort($actions);

        return [
            'streamCount' => count($streams),
            'filterCount' => array_sum($filters),
            'filters' => $filters,
            'surfaces' => $surfaces,
            'actions' => $actions,
            'streams' => $streams,
        ];
    }

    /**
     * @param list<array{surface:string, source:string, object:string|null, filters:list<string>, action:string, streamBytes:int|null, streamSkipped:string|null}> $streams
     * @param list<string> $filters
     */
    private function addPdfStreamFilterPolicyEntry(
        array &$streams,
        string $surface,
        string $source,
        ?string $object,
        array $filters,
        ?int $streamBytes,
        ?string $streamSkipped
    ): void {
        $filters = array_values(array_unique(array_filter($filters, static fn (string $filter): bool => $filter !== '')));
        sort($filters);
        if ($filters === []) {
            return;
        }

        $streams[] = [
            'surface' => $surface,
            'source' => $source,
            'object' => $object,
            'filters' => $filters,
            'action' => $this->pdfStreamFilterPolicyAction($filters),
            'streamBytes' => $streamBytes,
            'streamSkipped' => $streamSkipped === '' ? null : $streamSkipped,
        ];
    }

    /**
     * @param list<string> $filters
     */
    private function pdfStreamFilterPolicyAction(array $filters): string
    {
        $deferredFilters = [
            'ASCII85Decode' => true,
            'ASCIIHexDecode' => true,
            'FlateDecode' => true,
            'LZWDecode' => true,
            'RunLengthDecode' => true,
        ];
        $imageFilters = [
            'CCITTFaxDecode' => true,
            'DCTDecode' => true,
            'JBIG2Decode' => true,
            'JPXDecode' => true,
        ];
        $hasImageFilter = false;

        foreach ($filters as $filter) {
            if ($filter === 'Crypt') {
                return 'requires-decryption';
            }
            if (isset($imageFilters[$filter])) {
                $hasImageFilter = true;
                continue;
            }
            if (isset($deferredFilters[$filter])) {
                continue;
            }

            return 'unsupported-filter';
        }

        return $hasImageFilter ? 'image-codec-review' : 'deferred-decode';
    }

    /**
     * @param array{streams?:list<array{surface:string, source:string, object:string|null, filters:list<string>}>} $streamFilterPolicy
     * @return array{streamCount:int, parameterSetCount:int, filters:array<string, int>, surfaces:array<string, int>, predictors:array<string, int>, streams:list<array{surface:string, source:string, object:string|null, filters:list<string>, parameterSets:list<array{filter:string|null, parameterSource:string, predictor:int|null, predictorLabel:string|null, colors:int|null, bitsPerComponent:int|null, columns:int|null, earlyChange:int|null, k:int|null, rows:int|null, blackIs1:bool|null, encodedByteAlign:bool|null, endOfLine:bool|null, endOfBlock:bool|null, damagedRowsBeforeError:int|null, jbig2Globals:string|null, cryptName:string|null, cryptType:string|null, rawKeys:list<string>}>}>}|array{}
     */
    private function summarizePdfStreamDecodeParameters(array $streamFilterPolicy, string $pdfBytes): array
    {
        $policyStreams = $streamFilterPolicy['streams'] ?? [];
        if (!is_array($policyStreams) || $policyStreams === []) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $streams = [];
        foreach ($policyStreams as $stream) {
            if (!is_array($stream)) {
                continue;
            }

            $object = is_string($stream['object'] ?? null) && $stream['object'] !== ''
                ? $stream['object']
                : null;
            if ($object === null) {
                continue;
            }

            $dictionary = $objects[$this->pdfReferenceKey($object)] ?? null;
            if ($dictionary === null) {
                continue;
            }

            $parameterSets = $this->extractPdfDecodeParameterSets($dictionary, $objects);
            if ($parameterSets === []) {
                continue;
            }

            $streams[] = [
                'surface' => is_string($stream['surface'] ?? null) ? $stream['surface'] : 'unknown',
                'source' => is_string($stream['source'] ?? null) ? $stream['source'] : 'stream:unknown',
                'object' => $object,
                'filters' => $this->extractPdfFilterNamesInOrder($dictionary, $objects),
                'parameterSets' => $parameterSets,
            ];
        }

        if ($streams === []) {
            return [];
        }

        $filters = [];
        $surfaces = [];
        $predictors = [];
        $parameterSetCount = 0;
        foreach ($streams as $stream) {
            $surfaces[$stream['surface']] = ($surfaces[$stream['surface']] ?? 0) + 1;
            foreach ($stream['parameterSets'] as $parameterSet) {
                $parameterSetCount++;
                $filter = is_string($parameterSet['filter'] ?? null) && $parameterSet['filter'] !== ''
                    ? $parameterSet['filter']
                    : 'unknown';
                $filters[$filter] = ($filters[$filter] ?? 0) + 1;
                $predictor = $parameterSet['predictorLabel'] ?? null;
                if (is_string($predictor) && $predictor !== '') {
                    $predictors[$predictor] = ($predictors[$predictor] ?? 0) + 1;
                }
            }
        }

        ksort($filters);
        ksort($surfaces);
        ksort($predictors);

        return [
            'streamCount' => count($streams),
            'parameterSetCount' => $parameterSetCount,
            'filters' => $filters,
            'surfaces' => $surfaces,
            'predictors' => $predictors,
            'streams' => $streams,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{filter:string|null, parameterSource:string, predictor:int|null, predictorLabel:string|null, colors:int|null, bitsPerComponent:int|null, columns:int|null, earlyChange:int|null, k:int|null, rows:int|null, blackIs1:bool|null, encodedByteAlign:bool|null, endOfLine:bool|null, endOfBlock:bool|null, damagedRowsBeforeError:int|null, jbig2Globals:string|null, cryptName:string|null, cryptType:string|null, rawKeys:list<string>}>
     */
    private function extractPdfDecodeParameterSets(string $streamDictionary, array $objects): array
    {
        $sourceName = 'DecodeParms';
        $value = $this->extractPdfValueForName($streamDictionary, 'DecodeParms');
        if ($value === null) {
            $sourceName = 'DP';
            $value = $this->extractPdfValueForName($streamDictionary, 'DP');
        }
        if ($value === null) {
            return [];
        }

        return $this->summarizePdfDecodeParameterValue(
            $value,
            $objects,
            $this->extractPdfFilterNamesInOrder($streamDictionary, $objects),
            $sourceName,
            0
        );
    }

    /**
     * @param array{kind:string, value:string, next?:int} $value
     * @param array<string, string> $objects
     * @param list<string|null> $filters
     * @return list<array{filter:string|null, parameterSource:string, predictor:int|null, predictorLabel:string|null, colors:int|null, bitsPerComponent:int|null, columns:int|null, earlyChange:int|null, k:int|null, rows:int|null, blackIs1:bool|null, encodedByteAlign:bool|null, endOfLine:bool|null, endOfBlock:bool|null, damagedRowsBeforeError:int|null, jbig2Globals:string|null, cryptName:string|null, cryptType:string|null, rawKeys:list<string>}>
     */
    private function summarizePdfDecodeParameterValue(array $value, array $objects, array $filters, string $sourceName, int $depth): array
    {
        if ($value['kind'] === 'keyword' && $value['value'] === 'null') {
            return [];
        }

        if ($value['kind'] === 'dictionary') {
            return [
                $this->summarizePdfDecodeParameterDictionary(
                    $value['value'],
                    count($filters) === 1 ? $filters[0] : ($filters[0] ?? null),
                    $sourceName
                ),
            ];
        }

        if ($value['kind'] === 'array') {
            $sets = [];
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $index => $arrayValue) {
                if (($arrayValue['kind'] ?? null) === 'keyword' && ($arrayValue['value'] ?? null) === 'null') {
                    continue;
                }
                foreach ($this->summarizePdfDecodeParameterValue(
                    $arrayValue,
                    $objects,
                    [$filters[$index] ?? null],
                    $sourceName . '[' . $index . ']',
                    $depth + 1
                ) as $set) {
                    $sets[] = $set;
                }
            }

            return $sets;
        }

        if ($value['kind'] === 'reference') {
            if ($depth >= 3) {
                return [];
            }
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return [];
            }
            $resolved = $this->parsePdfValueAt($body, 0);

            return $resolved === null
                ? []
                : $this->summarizePdfDecodeParameterValue($resolved, $objects, $filters, $sourceName . ':' . $value['value'], $depth + 1);
        }

        return [];
    }

    /**
     * @return array{filter:string|null, parameterSource:string, predictor:int|null, predictorLabel:string|null, colors:int|null, bitsPerComponent:int|null, columns:int|null, earlyChange:int|null, k:int|null, rows:int|null, blackIs1:bool|null, encodedByteAlign:bool|null, endOfLine:bool|null, endOfBlock:bool|null, damagedRowsBeforeError:int|null, jbig2Globals:string|null, cryptName:string|null, cryptType:string|null, rawKeys:list<string>}
     */
    private function summarizePdfDecodeParameterDictionary(string $dictionary, ?string $filter, string $parameterSource): array
    {
        $rawKeys = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            $rawKeys[] = $entry['key'];
        }
        $rawKeys = array_values(array_unique($rawKeys));
        sort($rawKeys);

        $predictor = $this->extractPdfIntegerToken($dictionary, 'Predictor');

        return [
            'filter' => $filter === '' ? null : $filter,
            'parameterSource' => $parameterSource,
            'predictor' => $predictor,
            'predictorLabel' => $this->pdfDecodePredictorLabel($predictor),
            'colors' => $this->extractPdfIntegerToken($dictionary, 'Colors'),
            'bitsPerComponent' => $this->extractPdfIntegerToken($dictionary, 'BitsPerComponent'),
            'columns' => $this->extractPdfIntegerToken($dictionary, 'Columns'),
            'earlyChange' => $this->extractPdfIntegerToken($dictionary, 'EarlyChange'),
            'k' => $this->extractPdfIntegerToken($dictionary, 'K'),
            'rows' => $this->extractPdfIntegerToken($dictionary, 'Rows'),
            'blackIs1' => $this->extractPdfBooleanToken($dictionary, 'BlackIs1'),
            'encodedByteAlign' => $this->extractPdfBooleanToken($dictionary, 'EncodedByteAlign'),
            'endOfLine' => $this->extractPdfBooleanToken($dictionary, 'EndOfLine'),
            'endOfBlock' => $this->extractPdfBooleanToken($dictionary, 'EndOfBlock'),
            'damagedRowsBeforeError' => $this->extractPdfIntegerToken($dictionary, 'DamagedRowsBeforeError'),
            'jbig2Globals' => $this->extractPdfReferenceToken($dictionary, 'JBIG2Globals'),
            'cryptName' => $this->extractPdfStringOrNameValue($dictionary, 'Name'),
            'cryptType' => $this->extractPdfStringOrNameValue($dictionary, 'Type'),
            'rawKeys' => $rawKeys,
        ];
    }

    private function pdfDecodePredictorLabel(?int $predictor): ?string
    {
        if ($predictor === null) {
            return null;
        }

        return match ($predictor) {
            1 => 'none',
            2 => 'tiff-2',
            10 => 'png-none',
            11 => 'png-sub',
            12 => 'png-up',
            13 => 'png-average',
            14 => 'png-paeth',
            15 => 'png-optimum',
            default => 'unknown-' . $predictor,
        };
    }

    /**
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function extractPdfFilterNamesInOrder(string $dictionary, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'Filter');
        if ($value === null) {
            return [];
        }

        return array_values(array_filter(
            $this->summarizePdfFilterValue($value, $objects, 0),
            static fn (string $filter): bool => $filter !== ''
        ));
    }

    /**
     * @return array{bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function summarizePdfStructuralStream(string $dictionary, int $maxBytes): array
    {
        $summary = [
            'bytes' => null,
            'sha256' => null,
            'skipped' => null,
        ];
        $bytes = $this->extractPdfStreamBytes($dictionary);
        if ($bytes === null) {
            return $summary;
        }

        $summary['bytes'] = strlen($bytes);
        if (preg_match('/\/Filter\b/s', $dictionary) === 1) {
            $summary['skipped'] = 'filtered';

            return $summary;
        }
        if (strlen($bytes) > $maxBytes) {
            $summary['skipped'] = 'too-large';

            return $summary;
        }

        $summary['sha256'] = hash('sha256', $bytes);

        return $summary;
    }

    /**
     * @return list<int>
     */
    private function extractPdfObjectStreamObjectNumbers(string $dictionary): array
    {
        if (preg_match('/\/Filter\b/s', $dictionary) === 1) {
            return [];
        }

        $bytes = $this->extractPdfStreamBytes($dictionary);
        if ($bytes === null || strlen($bytes) > self::MAX_OBJECT_STREAM_BYTES) {
            return [];
        }

        $first = $this->extractPdfIntegerToken($dictionary, 'First');
        $objectCount = $this->extractPdfIntegerToken($dictionary, 'N');
        $headerLength = $first === null ? strlen($bytes) : max(0, min(strlen($bytes), $first));
        $header = substr($bytes, 0, $headerLength);
        if (preg_match_all('/-?\d+/', $header, $matches) < 1) {
            return [];
        }

        $numbers = array_map('intval', $matches[0]);
        $objects = [];
        $limit = $objectCount === null ? count($numbers) : max(0, $objectCount);
        for ($i = 0; $i + 1 < count($numbers) && count($objects) < $limit; $i += 2) {
            if ($numbers[$i] < 0) {
                continue;
            }

            $objects[] = $numbers[$i];
        }

        return $objects;
    }

    /**
     * @return list<int>
     */
    private function extractPdfIntegerArrayToken(string $dictionary, string $name): array
    {
        $array = $this->extractPdfArrayValue($dictionary, $name);
        if ($array === null || preg_match_all('/-?\d+/', $array, $matches) < 1) {
            return [];
        }

        return array_map('intval', $matches[0]);
    }

    /**
     * @return list<float>|null
     */
    private function extractPdfNumberArrayToken(string $dictionary, string $name, int $required): ?array
    {
        $array = $this->extractPdfArrayValue($dictionary, $name);
        if ($array === null || preg_match_all('/[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[Ee][-+]?\d+)?/', $array, $matches) < $required) {
            return null;
        }

        $numbers = [];
        foreach (array_slice($matches[0], 0, $required) as $number) {
            $numbers[] = (float) $number;
        }

        return $numbers;
    }

    /**
     * @return array{0:int, 1:int}
     */
    private function pdfReferenceSortKey(string $reference): array
    {
        if (preg_match('/\A(\d+)\s+(\d+)\s+R\z/', trim($reference), $matches) === 1) {
            return [(int) $matches[1], (int) $matches[2]];
        }

        return [PHP_INT_MAX, PHP_INT_MAX];
    }

    private function extractPdfStartXrefAfter(string $pdfBytes, int $offset): ?int
    {
        $end = strpos($pdfBytes, '%%EOF', $offset);
        if ($end === false) {
            $end = min(strlen($pdfBytes), $offset + 4096);
        }

        $chunk = substr($pdfBytes, $offset, max(0, min($end, $offset + 4096) - $offset));
        if (preg_match('/\bstartxref\s+(\d+)\b/s', $chunk, $matches) !== 1) {
            return null;
        }

        return (int) $matches[1];
    }

    private function extractPdfReferenceToken(string $dictionary, string $name): ?string
    {
        if (preg_match('/\/' . preg_quote($name, '/') . '\s+(\d+)\s+(\d+)\s+R\b/s', $dictionary, $matches) !== 1) {
            return null;
        }

        return $matches[1] . ' ' . $matches[2] . ' R';
    }

    /**
     * @return list<string>
     */
    private function extractPdfTrailerIdValues(string $dictionary): array
    {
        $array = $this->extractPdfArrayValue($dictionary, 'ID');
        if ($array === null) {
            return [];
        }

        $ids = [];
        if (preg_match_all('/<([0-9A-Fa-f\s]+)>/', $array, $matches) >= 1) {
            foreach ($matches[1] as $rawHex) {
                $id = strtoupper(preg_replace('/\s+/', '', $rawHex) ?? '');
                if ($id !== '') {
                    $ids[] = $id;
                }
                if (count($ids) >= 2) {
                    return $ids;
                }
            }
        }

        $cursor = 0;
        $length = strlen($array);
        while ($cursor < $length && count($ids) < 2) {
            if ($array[$cursor] !== '(') {
                $cursor++;
                continue;
            }

            $parsed = $this->parsePdfLiteralString($array, $cursor);
            if ($parsed === null) {
                $cursor++;
                continue;
            }

            $id = trim($parsed['value']);
            if ($id !== '') {
                $ids[] = $id;
            }
            $cursor = $parsed['next'];
        }

        return $ids;
    }

    /**
     * @return array<string, string>
     */
    private function extractPdfDocumentInfo(string $pdfBytes): array
    {
        $dictionary = $this->extractPdfInfoDictionary($pdfBytes);
        if ($dictionary === null) {
            return [];
        }

        $info = [];
        foreach (['Title', 'Author', 'Subject', 'Keywords', 'Creator', 'Producer', 'CreationDate', 'ModDate'] as $key) {
            $values = $this->extractPdfNamedStrings($dictionary, $key);
            if ($values === []) {
                continue;
            }

            $value = trim($values[0]);
            if ($value !== '') {
                $info[$key] = $value;
            }
        }

        $trapped = $this->extractPdfNameToken($dictionary, 'Trapped');
        if ($trapped !== null && $trapped !== '') {
            $info['Trapped'] = $trapped;
        }
        foreach (['GTS_PDFXVersion', 'GTS_PDFXConformance'] as $key) {
            $value = $this->extractPdfStringOrNameValue($dictionary, $key);
            if ($value !== null) {
                $info[$key] = $value;
            }
        }

        return $info;
    }

    /**
     * @param array<string, string> $documentInfo
     * @return list<array{key:string, source:string, raw:string, normalized:string|null, precision:string|null, timezone:string|null, timezoneOffsetMinutes:int|null, year:int|null, month:int|null, day:int|null, hour:int|null, minute:int|null, second:int|null, valid:bool}>
     */
    private function extractPdfDocumentInfoDateMetadata(array $documentInfo): array
    {
        $dates = [];
        foreach (['CreationDate', 'ModDate'] as $key) {
            $raw = trim($documentInfo[$key] ?? '');
            if ($raw === '') {
                continue;
            }

            $dates[] = $this->parsePdfDocumentInfoDate($key, $raw);
        }

        return $dates;
    }

    /**
     * @return array{key:string, source:string, raw:string, normalized:string|null, precision:string|null, timezone:string|null, timezoneOffsetMinutes:int|null, year:int|null, month:int|null, day:int|null, hour:int|null, minute:int|null, second:int|null, valid:bool}
     */
    private function parsePdfDocumentInfoDate(string $key, string $raw): array
    {
        $metadata = [
            'key' => $key,
            'source' => 'Info.' . $key,
            'raw' => $raw,
            'normalized' => null,
            'precision' => null,
            'timezone' => null,
            'timezoneOffsetMinutes' => null,
            'year' => null,
            'month' => null,
            'day' => null,
            'hour' => null,
            'minute' => null,
            'second' => null,
            'valid' => false,
        ];

        if (preg_match('/\A(?:D:)?(\d{4})(\d{2})?(\d{2})?(\d{2})?(\d{2})?(\d{2})?(?:(Z|z)|([+\-])(\d{2})\'?(\d{2})?\'?)?\z/', $raw, $matches) !== 1) {
            return $metadata;
        }

        $year = (int) $matches[1];
        $month = isset($matches[2]) && $matches[2] !== '' ? (int) $matches[2] : null;
        $day = isset($matches[3]) && $matches[3] !== '' ? (int) $matches[3] : null;
        $hour = isset($matches[4]) && $matches[4] !== '' ? (int) $matches[4] : null;
        $minute = isset($matches[5]) && $matches[5] !== '' ? (int) $matches[5] : null;
        $second = isset($matches[6]) && $matches[6] !== '' ? (int) $matches[6] : null;
        $precision = 'year';
        if ($month !== null) {
            $precision = 'month';
        }
        if ($day !== null) {
            $precision = 'day';
        }
        if ($hour !== null) {
            $precision = 'hour';
        }
        if ($minute !== null) {
            $precision = 'minute';
        }
        if ($second !== null) {
            $precision = 'second';
        }

        $metadata['year'] = $year;
        $metadata['month'] = $month;
        $metadata['day'] = $day;
        $metadata['hour'] = $hour;
        $metadata['minute'] = $minute;
        $metadata['second'] = $second;
        $metadata['precision'] = $precision;

        $valid = true;
        if ($month !== null && ($month < 1 || $month > 12)) {
            $valid = false;
        }
        if ($day !== null && !checkdate($month ?? 1, $day, $year)) {
            $valid = false;
        }
        if ($hour !== null && ($hour < 0 || $hour > 23)) {
            $valid = false;
        }
        if ($minute !== null && ($minute < 0 || $minute > 59)) {
            $valid = false;
        }
        if ($second !== null && ($second < 0 || $second > 59)) {
            $valid = false;
        }

        if (isset($matches[7]) && $matches[7] !== '') {
            $metadata['timezone'] = 'Z';
            $metadata['timezoneOffsetMinutes'] = 0;
        } elseif (isset($matches[8]) && $matches[8] !== '') {
            $tzHour = isset($matches[9]) && $matches[9] !== '' ? (int) $matches[9] : 0;
            $tzMinute = isset($matches[10]) && $matches[10] !== '' ? (int) $matches[10] : 0;
            if ($tzHour > 23 || $tzMinute > 59) {
                $valid = false;
            }

            $metadata['timezone'] = sprintf('%s%02d:%02d', $matches[8], $tzHour, $tzMinute);
            $metadata['timezoneOffsetMinutes'] = ($matches[8] === '-' ? -1 : 1) * (($tzHour * 60) + $tzMinute);
        }

        $metadata['valid'] = $valid;
        if (!$valid) {
            return $metadata;
        }

        $normalized = sprintf('%04d', $year);
        if ($month !== null) {
            $normalized .= sprintf('-%02d', $month);
        }
        if ($day !== null) {
            $normalized .= sprintf('-%02d', $day);
        }
        if ($hour !== null) {
            $normalized .= sprintf('T%02d', $hour);
            if ($minute !== null) {
                $normalized .= sprintf(':%02d', $minute);
                if ($second !== null) {
                    $normalized .= sprintf(':%02d', $second);
                }
            }
            if (is_string($metadata['timezone'])) {
                $normalized .= $metadata['timezone'];
            }
        }
        $metadata['normalized'] = $normalized;

        return $metadata;
    }

    /**
     * @return array<string, mixed>
     */
    private function extractPdfXmpMetadata(string $pdfBytes, ?string $catalog): array
    {
        $stream = $this->extractPdfMetadataStream($pdfBytes, $catalog);
        if ($stream === null) {
            return [];
        }

        return $this->summarizePdfXmpMetadataStream($stream);
    }

    /**
     * @return array<string, mixed>
     */
    private function extractPdfCatalogMetadata(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null) {
            return [];
        }

        $metadataReference = $this->extractPdfReferenceToken($catalog, 'Metadata');
        if ($metadataReference === null) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $metadataObject = $objects[$this->pdfReferenceKey($metadataReference)] ?? null;
        if ($metadataObject === null) {
            return [];
        }

        $stream = $this->pdfMetadataStreamForObject($metadataObject, $objects);
        if ($stream === null) {
            return [];
        }

        $metadata = $this->summarizePdfXmpMetadataStream($stream);
        if ($metadata === []) {
            return [];
        }

        return array_merge([
            'source' => 'catalog.Metadata',
            'metadataObject' => $metadataReference,
        ], $metadata);
    }

    /**
     * @param array{bytes:string, filtered:bool, compressedBytes?:int|null, decodedFilter?:string|null} $stream
     * @return array<string, mixed>
     */
    private function summarizePdfXmpMetadataStream(array $stream): array
    {
        $decodedFilter = is_string($stream['decodedFilter'] ?? null) && $stream['decodedFilter'] !== ''
            ? $stream['decodedFilter']
            : null;
        if ($stream['filtered'] && $decodedFilter === null) {
            return [
                'packetBytes' => strlen($stream['bytes']),
                'skipped' => 'filtered',
            ];
        }
        if (strlen($stream['bytes']) > self::MAX_XMP_METADATA_BYTES) {
            return [
                'packetBytes' => strlen($stream['bytes']),
                'skipped' => 'too-large',
            ];
        }

        $xml = $stream['bytes'];
        if (
            !str_contains($xml, '<rdf:RDF')
            && !str_contains($xml, '<x:xmpmeta')
            && !str_contains($xml, '<?xpacket')
        ) {
            return [];
        }

        $metadata = [
            'packetBytes' => strlen($xml),
            'packetSha256' => hash('sha256', $xml),
        ];
        if ($decodedFilter !== null) {
            $metadata['decodedFilter'] = $decodedFilter;
            $metadata['compressedBytes'] = is_int($stream['compressedBytes'] ?? null)
                ? $stream['compressedBytes']
                : null;
        }

        foreach ([
            'title' => 'title',
            'description' => 'description',
            'rights' => 'rights',
            'format' => 'format',
            'source' => 'source',
            'creatorTool' => 'CreatorTool',
            'createDate' => 'CreateDate',
            'modifyDate' => 'ModifyDate',
            'metadataDate' => 'MetadataDate',
            'documentId' => 'DocumentID',
            'instanceId' => 'InstanceID',
        ] as $target => $name) {
            $value = in_array($name, ['title', 'description', 'rights'], true)
                ? $this->xmpLocalizedText($xml, $name)
                : $this->xmpScalarText($xml, $name);
            if ($value !== null && $value !== '') {
                $metadata[$target] = $value;
            }
        }

        $creators = $this->xmpListText($xml, 'creator');
        if ($creators !== []) {
            $metadata['creators'] = $creators;
        }

        foreach ([
            'subjects' => 'subject',
            'languages' => 'language',
            'relations' => 'relation',
        ] as $target => $name) {
            $values = $this->xmpListText($xml, $name);
            if ($values !== []) {
                $metadata[$target] = $values;
            }
        }

        $pdfaPart = $this->xmpNamespaceScalarText($xml, self::XMP_PDF_A_ID_NAMESPACE, 'part', ['pdfaid']);
        $pdfaConformance = $this->xmpNamespaceScalarText($xml, self::XMP_PDF_A_ID_NAMESPACE, 'conformance', ['pdfaid']);
        if ($pdfaPart !== null || $pdfaConformance !== null) {
            $metadata['pdfaIdentification'] = [
                'part' => $pdfaPart,
                'conformance' => $pdfaConformance,
            ];
        }

        $pdfuaPart = $this->xmpNamespaceScalarText($xml, self::XMP_PDF_UA_ID_NAMESPACE, 'part', ['pdfuaid']);
        $pdfuaAmendment = $this->xmpNamespaceScalarText($xml, self::XMP_PDF_UA_ID_NAMESPACE, 'amd', ['pdfuaid']);
        $pdfuaCorrigendum = $this->xmpNamespaceScalarText($xml, self::XMP_PDF_UA_ID_NAMESPACE, 'corr', ['pdfuaid']);
        if ($pdfuaPart !== null || $pdfuaAmendment !== null || $pdfuaCorrigendum !== null) {
            $metadata['pdfuaIdentification'] = [
                'part' => $pdfuaPart,
                'amendment' => $pdfuaAmendment,
                'corrigendum' => $pdfuaCorrigendum,
            ];
        }

        $pdfxVersion = $this->xmpNamespaceScalarText($xml, self::XMP_PDF_X_ID_NAMESPACE, 'GTS_PDFXVersion', ['pdfxid']);
        $pdfxConformance = $this->xmpNamespaceScalarText($xml, self::XMP_PDF_X_ID_NAMESPACE, 'GTS_PDFXConformance', ['pdfxid']);
        if ($pdfxVersion !== null || $pdfxConformance !== null) {
            $metadata['pdfxIdentification'] = [
                'version' => $pdfxVersion,
                'conformance' => $pdfxConformance,
            ];
        }

        $extensionSchemas = $this->xmpPdfaExtensionSchemas($xml);
        if ($extensionSchemas !== []) {
            $metadata['pdfaExtensionSchemas'] = $extensionSchemas;
        }
        foreach ($this->xmpMediaManagementMetadata($xml) as $key => $value) {
            $metadata[$key] = $value;
        }

        return $metadata;
    }

    /**
     * @return list<array{schema:string|null, namespaceUri:string|null, prefix:string|null, properties:list<array{name:string, valueType:string|null, category:string|null, description:string|null}>}>
     */
    private function xmpPdfaExtensionSchemas(string $xml): array
    {
        if (
            !str_contains($xml, self::XMP_PDF_A_EXTENSION_NAMESPACE)
            && !str_contains($xml, self::XMP_PDF_A_SCHEMA_NAMESPACE)
            && !str_contains($xml, 'pdfaExtension:schemas')
            && !str_contains($xml, 'pdfaSchema:schema')
        ) {
            return [];
        }

        $dom = new \DOMDocument('1.0', 'UTF-8');
        $dom->resolveExternals = false;
        $dom->substituteEntities = false;
        $previous = libxml_use_internal_errors(true);
        try {
            $loaded = $dom->loadXML($xml, LIBXML_NONET | LIBXML_COMPACT);
        } finally {
            libxml_clear_errors();
            libxml_use_internal_errors($previous);
        }
        if (!$loaded) {
            return [];
        }

        $xpath = new \DOMXPath($dom);
        $xpath->registerNamespace('pdfaSchema', self::XMP_PDF_A_SCHEMA_NAMESPACE);
        $schemaNodes = $xpath->query('//pdfaSchema:schema');
        if (!$schemaNodes instanceof \DOMNodeList || $schemaNodes->length === 0) {
            return [];
        }

        $schemas = [];
        $seen = [];
        foreach ($schemaNodes as $schemaNode) {
            if (!$schemaNode instanceof \DOMElement || !$schemaNode->parentNode instanceof \DOMElement) {
                continue;
            }

            $schemaContainer = $schemaNode->parentNode;
            $schema = $this->normalizeXmpText($schemaNode->textContent);
            $namespaceUri = $this->xmpDirectChildText($schemaContainer, self::XMP_PDF_A_SCHEMA_NAMESPACE, 'namespaceURI');
            $prefix = $this->xmpDirectChildText($schemaContainer, self::XMP_PDF_A_SCHEMA_NAMESPACE, 'prefix');
            $key = implode("\0", [$schema ?? '', $namespaceUri ?? '', $prefix ?? '']);
            if (isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;

            $schemas[] = [
                'schema' => $schema,
                'namespaceUri' => $namespaceUri,
                'prefix' => $prefix,
                'properties' => $this->xmpPdfaExtensionSchemaProperties($schemaContainer),
            ];
            if (count($schemas) >= 64) {
                break;
            }
        }

        usort(
            $schemas,
            static fn (array $a, array $b): int => [
                $a['prefix'] ?? '',
                $a['schema'] ?? '',
                $a['namespaceUri'] ?? '',
            ] <=> [
                $b['prefix'] ?? '',
                $b['schema'] ?? '',
                $b['namespaceUri'] ?? '',
            ]
        );

        return $schemas;
    }

    /**
     * @return list<array{name:string, valueType:string|null, category:string|null, description:string|null}>
     */
    private function xmpPdfaExtensionSchemaProperties(\DOMElement $schemaContainer): array
    {
        $properties = [];
        $seen = [];
        foreach ($this->xmpDescendantElements($schemaContainer, self::XMP_PDF_A_PROPERTY_NAMESPACE, 'name') as $nameNode) {
            if (!$nameNode->parentNode instanceof \DOMElement) {
                continue;
            }

            $propertyContainer = $nameNode->parentNode;
            $name = $this->normalizeXmpText($nameNode->textContent);
            if ($name === null || $name === '') {
                continue;
            }

            $valueType = $this->xmpDirectChildText($propertyContainer, self::XMP_PDF_A_PROPERTY_NAMESPACE, 'valueType');
            $category = $this->xmpDirectChildText($propertyContainer, self::XMP_PDF_A_PROPERTY_NAMESPACE, 'category');
            $description = $this->xmpDirectChildText($propertyContainer, self::XMP_PDF_A_PROPERTY_NAMESPACE, 'description');
            $key = implode("\0", [$name, $valueType ?? '', $category ?? '', $description ?? '']);
            if (isset($seen[$key])) {
                continue;
            }
            $seen[$key] = true;

            $properties[] = [
                'name' => $name,
                'valueType' => $valueType,
                'category' => $category,
                'description' => $description,
            ];
            if (count($properties) >= 256) {
                break;
            }
        }

        usort(
            $properties,
            static fn (array $a, array $b): int => [
                $a['name'],
                $a['valueType'] ?? '',
            ] <=> [
                $b['name'],
                $b['valueType'] ?? '',
            ]
        );

        return $properties;
    }

    /**
     * @return array<string, mixed>
     */
    private function xmpMediaManagementMetadata(string $xml): array
    {
        if (
            !str_contains($xml, self::XMP_MEDIA_MANAGEMENT_NAMESPACE)
            && !str_contains($xml, 'xmpMM:')
            && !str_contains($xml, 'DerivedFrom')
            && !str_contains($xml, 'History')
        ) {
            return [];
        }

        $metadata = [];
        foreach ([
            'originalDocumentId' => 'OriginalDocumentID',
            'renditionClass' => 'RenditionClass',
            'renditionParams' => 'RenditionParams',
            'versionId' => 'VersionID',
        ] as $target => $name) {
            $value = $this->xmpNamespaceScalarText($xml, self::XMP_MEDIA_MANAGEMENT_NAMESPACE, $name, ['xmpMM']);
            if ($value !== null && $value !== '') {
                $metadata[$target] = $value;
            }
        }

        $dom = $this->loadXmpDom($xml);
        if ($dom === null) {
            return $metadata;
        }

        $derivedFrom = $this->xmpMediaManagementDerivedFrom($dom);
        if ($derivedFrom !== []) {
            $metadata['derivedFrom'] = $derivedFrom;
        }

        $history = $this->xmpMediaManagementHistory($dom);
        if ($history !== []) {
            $metadata['history'] = $history;
        }

        return $metadata;
    }

    private function loadXmpDom(string $xml): ?\DOMDocument
    {
        $dom = new \DOMDocument('1.0', 'UTF-8');
        $dom->resolveExternals = false;
        $dom->substituteEntities = false;
        $previous = libxml_use_internal_errors(true);
        try {
            $loaded = $dom->loadXML($xml, LIBXML_NONET | LIBXML_COMPACT);
        } finally {
            libxml_clear_errors();
            libxml_use_internal_errors($previous);
        }

        return $loaded ? $dom : null;
    }

    /**
     * @return array<string, string>
     */
    private function xmpMediaManagementDerivedFrom(\DOMDocument $dom): array
    {
        $node = $this->firstXmpElement($dom, self::XMP_MEDIA_MANAGEMENT_NAMESPACE, 'DerivedFrom');
        if ($node === null) {
            return [];
        }

        $derivedFrom = [];
        foreach ([
            'documentId' => 'documentID',
            'instanceId' => 'instanceID',
            'originalDocumentId' => 'originalDocumentID',
            'renditionClass' => 'renditionClass',
            'renditionParams' => 'renditionParams',
            'manager' => 'manager',
            'managerVariant' => 'managerVariant',
            'managerTo' => 'managerTo',
            'managerUi' => 'managerUI',
        ] as $target => $name) {
            $value = $this->xmpStructuredPropertyText($node, self::XMP_RESOURCE_REF_NAMESPACE, $name);
            if ($value !== null && $value !== '') {
                $derivedFrom[$target] = $value;
            }
        }

        return $derivedFrom;
    }

    /**
     * @return list<array<string, string>>
     */
    private function xmpMediaManagementHistory(\DOMDocument $dom): array
    {
        $historyNode = $this->firstXmpElement($dom, self::XMP_MEDIA_MANAGEMENT_NAMESPACE, 'History');
        if ($historyNode === null) {
            return [];
        }

        $events = [];
        foreach ($historyNode->getElementsByTagNameNS(self::XMP_RDF_NAMESPACE, 'li') as $eventNode) {
            if (!$eventNode instanceof \DOMElement) {
                continue;
            }

            $event = [];
            foreach ([
                'action' => 'action',
                'instanceId' => 'instanceID',
                'when' => 'when',
                'softwareAgent' => 'softwareAgent',
                'changed' => 'changed',
                'parameters' => 'parameters',
            ] as $target => $name) {
                $value = $this->xmpStructuredPropertyText($eventNode, self::XMP_RESOURCE_EVENT_NAMESPACE, $name);
                if ($value !== null && $value !== '') {
                    $event[$target] = $value;
                }
            }

            if ($event !== []) {
                $events[] = $event;
            }
            if (count($events) >= 64) {
                break;
            }
        }

        return $events;
    }

    private function firstXmpElement(\DOMDocument $dom, string $namespaceUri, string $localName): ?\DOMElement
    {
        foreach ($dom->getElementsByTagNameNS($namespaceUri, $localName) as $node) {
            if ($node instanceof \DOMElement) {
                return $node;
            }
        }

        return null;
    }

    private function xmpStructuredPropertyText(\DOMElement $element, string $namespaceUri, string $localName): ?string
    {
        $attribute = $element->getAttributeNS($namespaceUri, $localName);
        if ($attribute !== '') {
            return $this->normalizeXmpText($attribute);
        }
        $attribute = $element->getAttribute($localName);
        if ($attribute !== '') {
            return $this->normalizeXmpText($attribute);
        }

        foreach ($element->childNodes as $child) {
            if (
                $child instanceof \DOMElement
                && $child->namespaceURI === $namespaceUri
                && $child->localName === $localName
            ) {
                return $this->normalizeXmpText($child->textContent);
            }
        }

        foreach ($this->xmpDescendantElements($element, $namespaceUri, $localName) as $descendant) {
            return $this->normalizeXmpText($descendant->textContent);
        }

        return null;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function extractPdfPageMetadata(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $pages = [];
        $visited = [];
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageMetadataFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $pages,
                0
            );
        }

        if ($pages === []) {
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $summary = $this->summarizePdfPageMetadata($body, $reference, $objects);
                if ($summary !== null) {
                    $pages[] = $summary;
                }
            }
        }

        foreach ($pages as $index => &$page) {
            $page['page'] = $index + 1;
        }
        unset($page);

        return $pages;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array<string, mixed>> $pages
     */
    private function collectPdfPageMetadataFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$pages,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $summary = $this->summarizePdfPageMetadata($body, $reference, $objects);
            if ($summary !== null) {
                $pages[] = $summary;
            }

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageMetadataFromTree(
                $objects,
                $this->pdfReferenceKey($kidReference),
                $visited,
                $pages,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array<string, mixed>|null
     */
    private function summarizePdfPageMetadata(string $pageDictionary, string $pageReference, array $objects): ?array
    {
        $metadataReference = $this->extractPdfReferenceToken($pageDictionary, 'Metadata');
        if ($metadataReference === null) {
            return null;
        }

        $metadataObject = $objects[$this->pdfReferenceKey($metadataReference)] ?? null;
        if ($metadataObject === null) {
            return null;
        }

        $stream = $this->pdfMetadataStreamForObject($metadataObject, $objects);
        if ($stream === null) {
            return null;
        }

        $metadata = $this->summarizePdfXmpMetadataStream($stream);
        if ($metadata === []) {
            return null;
        }

        return array_merge([
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'metadataObject' => $metadataReference,
        ], $metadata);
    }

    /**
     * @return list<array{source:string, page:int|null, pageObject:string|null, application:string, pieceObject:string|null, lastModified:string|null, privateObject:string|null, privateKeys:list<string>, privateValues:array<string, bool|float|int|string|null>, privateStreamBytes:int|null, privateStreamSha256:string|null, privateStreamSkipped:string|null}>
     */
    private function extractPdfPieceInfo(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $entries = [];
        $pageEntries = [];

        if ($catalog !== null) {
            $pieceInfo = $this->extractPdfDictionaryOrReferenceValue($catalog, 'PieceInfo', $objects);
            if ($pieceInfo !== null) {
                array_push(
                    $entries,
                    ...$this->summarizePdfPieceInfoDictionary(
                        $pieceInfo,
                        'catalog.PieceInfo',
                        null,
                        null,
                        $objects
                    )
                );
            }
        }

        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');
        if ($pagesReference !== null) {
            $this->collectPdfPieceInfoFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $pageEntries,
                $pageNumber,
                0
            );
        }

        if ($pageEntries === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                array_push(
                    $pageEntries,
                    ...$this->summarizePdfPagePieceInfo(
                        $body,
                        $reference,
                        $objects,
                        $pageNumber
                    )
                );
            }
        }

        array_push($entries, ...$pageEntries);

        return $entries;
    }

    /**
     * @return list<array{source:string, page:int|null, pageObject:string|null, spiderInfoObject:string|null, version:float|null, commandCount:int, sourceUrls:list<string>, captures:list<array{commandObject:string|null, sourceUrl:string|null, sourceTitle:string|null, commandName:string|null, commandType:string|null, identifier:string|null, timestamp:string|null, flags:int|null, depth:int|null, pageReferences:list<string>, parentCommand:string|null, nextCommand:string|null}>}>
     */
    private function extractPdfWebCaptureMetadata(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $entries = [];
        $pageEntries = [];

        if ($catalog !== null) {
            $summary = $this->summarizePdfSpiderInfoValue(
                $this->extractPdfValueForName($catalog, 'SpiderInfo'),
                'catalog.SpiderInfo',
                null,
                null,
                $objects
            );
            if ($summary !== null) {
                $entries[] = $summary;
            }
        }

        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');
        if ($pagesReference !== null) {
            $this->collectPdfWebCaptureFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $pageEntries,
                $pageNumber,
                0
            );
        }

        if ($pageEntries === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $summary = $this->summarizePdfPageSpiderInfo($body, $reference, $objects, $pageNumber);
                if ($summary !== null) {
                    $pageEntries[] = $summary;
                }
            }
        }

        array_push($entries, ...$pageEntries);

        return $entries;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{source:string, page:int|null, pageObject:string|null, spiderInfoObject:string|null, version:float|null, commandCount:int, sourceUrls:list<string>, captures:list<array{commandObject:string|null, sourceUrl:string|null, sourceTitle:string|null, commandName:string|null, commandType:string|null, identifier:string|null, timestamp:string|null, flags:int|null, depth:int|null, pageReferences:list<string>, parentCommand:string|null, nextCommand:string|null}>}> $entries
     */
    private function collectPdfWebCaptureFromPageTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$entries,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $summary = $this->summarizePdfPageSpiderInfo($body, $reference, $objects, $pageNumber);
            if ($summary !== null) {
                $entries[] = $summary;
            }

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfWebCaptureFromPageTree(
                $objects,
                $kidReference,
                $visited,
                $entries,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{source:string, page:int|null, pageObject:string|null, spiderInfoObject:string|null, version:float|null, commandCount:int, sourceUrls:list<string>, captures:list<array{commandObject:string|null, sourceUrl:string|null, sourceTitle:string|null, commandName:string|null, commandType:string|null, identifier:string|null, timestamp:string|null, flags:int|null, depth:int|null, pageReferences:list<string>, parentCommand:string|null, nextCommand:string|null}>}|null
     */
    private function summarizePdfPageSpiderInfo(string $pageDictionary, string $pageReference, array $objects, int $pageNumber): ?array
    {
        return $this->summarizePdfSpiderInfoValue(
            $this->extractPdfValueForName($pageDictionary, 'SpiderInfo'),
            'page:' . $pageReference . ' R.SpiderInfo',
            $pageNumber,
            $pageReference . ' R',
            $objects
        );
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     * @return array{source:string, page:int|null, pageObject:string|null, spiderInfoObject:string|null, version:float|null, commandCount:int, sourceUrls:list<string>, captures:list<array{commandObject:string|null, sourceUrl:string|null, sourceTitle:string|null, commandName:string|null, commandType:string|null, identifier:string|null, timestamp:string|null, flags:int|null, depth:int|null, pageReferences:list<string>, parentCommand:string|null, nextCommand:string|null}>}|null
     */
    private function summarizePdfSpiderInfoValue(
        ?array $value,
        string $source,
        ?int $page,
        ?string $pageObject,
        array $objects
    ): ?array {
        $resolved = $this->resolvePdfDictionaryValue($value, $objects);
        if ($resolved['dictionary'] === null) {
            return null;
        }

        $commands = $this->extractPdfWebCaptureCommands(
            $this->extractPdfValueForName($resolved['dictionary'], 'C'),
            $objects
        );
        $sourceUrls = [];
        foreach ($commands as $command) {
            if (($command['sourceUrl'] ?? null) !== null) {
                $sourceUrls[] = $command['sourceUrl'];
            }
        }
        $sourceUrls = $this->uniqueStrings($sourceUrls);
        sort($sourceUrls);

        return [
            'source' => $source,
            'page' => $page,
            'pageObject' => $pageObject,
            'spiderInfoObject' => $resolved['object'],
            'version' => $this->extractPdfNumberToken($resolved['dictionary'], 'V'),
            'commandCount' => count($commands),
            'sourceUrls' => $sourceUrls,
            'captures' => $commands,
        ];
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     * @return list<array{commandObject:string|null, sourceUrl:string|null, sourceTitle:string|null, commandName:string|null, commandType:string|null, identifier:string|null, timestamp:string|null, flags:int|null, depth:int|null, pageReferences:list<string>, parentCommand:string|null, nextCommand:string|null}>
     */
    private function extractPdfWebCaptureCommands(?array $value, array $objects, int $depth = 0): array
    {
        if ($value === null || $depth > 8) {
            return [];
        }

        if ($value['kind'] === 'array') {
            $commands = [];
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $entry) {
                $summary = $this->summarizePdfWebCaptureCommandValue($entry, $objects, $depth + 1);
                if ($summary !== null) {
                    $commands[] = $summary;
                }
                if (count($commands) >= 64) {
                    break;
                }
            }

            return $commands;
        }

        if ($value['kind'] === 'reference') {
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return [];
            }
            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved === null) {
                return [];
            }
            if ($resolved['kind'] === 'array') {
                return $this->extractPdfWebCaptureCommands($resolved, $objects, $depth + 1);
            }
        }

        $summary = $this->summarizePdfWebCaptureCommandValue($value, $objects, $depth + 1);

        return $summary === null ? [] : [$summary];
    }

    /**
     * @param array{kind:string, value:string, next?:int} $value
     * @param array<string, string> $objects
     * @return array{commandObject:string|null, sourceUrl:string|null, sourceTitle:string|null, commandName:string|null, commandType:string|null, identifier:string|null, timestamp:string|null, flags:int|null, depth:int|null, pageReferences:list<string>, parentCommand:string|null, nextCommand:string|null}|null
     */
    private function summarizePdfWebCaptureCommandValue(array $value, array $objects, int $depth = 0): ?array
    {
        $resolved = $this->resolvePdfDictionaryValue($value, $objects);
        if ($resolved['dictionary'] === null) {
            return null;
        }

        $pageReferences = [];
        foreach (['Pages', 'Page'] as $name) {
            foreach ($this->collectPdfReferencesFromValue($this->extractPdfValueForName($resolved['dictionary'], $name), $objects) as $reference) {
                $pageReferences[] = $reference;
            }
        }
        $pageReferences = $this->uniqueStrings($pageReferences);

        return [
            'commandObject' => $resolved['object'],
            'sourceUrl' => $this->extractPdfStringOrNameValue($resolved['dictionary'], 'URL'),
            'sourceTitle' => $this->extractPdfStringOrNameValue($resolved['dictionary'], 'Title')
                ?? $this->extractPdfStringOrNameValue($resolved['dictionary'], 'T'),
            'commandName' => $this->extractPdfStringOrNameValue($resolved['dictionary'], 'N'),
            'commandType' => $this->extractPdfStringOrNameValue($resolved['dictionary'], 'CT')
                ?? $this->extractPdfStringOrNameValue($resolved['dictionary'], 'S'),
            'identifier' => $this->extractPdfStringOrNameValue($resolved['dictionary'], 'ID'),
            'timestamp' => $this->extractPdfStringOrNameValue($resolved['dictionary'], 'TS'),
            'flags' => $this->extractPdfIntegerToken($resolved['dictionary'], 'F'),
            'depth' => $this->extractPdfIntegerToken($resolved['dictionary'], 'L'),
            'pageReferences' => $pageReferences,
            'parentCommand' => $this->extractPdfReferenceValue($resolved['dictionary'], 'P'),
            'nextCommand' => $this->extractPdfReferenceValue($resolved['dictionary'], 'Next'),
        ];
    }

    /**
     * @param list<array{source:string, page:int|null, pageObject:string|null, spiderInfoObject:string|null, version:float|null, commandCount:int, sourceUrls:list<string>, captures:list<array{commandObject:string|null, sourceUrl:string|null, sourceTitle:string|null, commandName:string|null, commandType:string|null, identifier:string|null, timestamp:string|null, flags:int|null, depth:int|null, pageReferences:list<string>, parentCommand:string|null, nextCommand:string|null}>}> $metadata
     * @param list<string> $pageObjects
     * @return array{reviewStatus:string, captureCount:int, commandCount:int, catalogCaptureCount:int, pageCaptureCount:int, sourceUrlCount:int, remoteSourceUrlCount:int, fileSourceUrlCount:int, relativeSourceUrlCount:int, missingSourceUrlCount:int, sourceSchemes:array<string, int>, pageReferenceCount:int, unresolvedPageReferences:list<string>, commandLinkCount:int, unresolvedCommandLinks:list<string>, maxDepth:int|null, issues:list<string>}|array{}
     */
    private function summarizePdfWebCapturePolicy(array $metadata, array $pageObjects): array
    {
        if ($metadata === []) {
            return [];
        }

        $knownPageObjects = [];
        foreach ($pageObjects as $pageObject) {
            if ($pageObject !== '') {
                $knownPageObjects[$pageObject] = true;
            }
        }

        $commandObjects = [];
        foreach ($metadata as $webCapture) {
            foreach (($webCapture['captures'] ?? []) as $capture) {
                $commandObject = $capture['commandObject'] ?? null;
                if (is_string($commandObject) && $commandObject !== '' && $commandObject !== 'inline') {
                    $commandObjects[$commandObject] = true;
                }
            }
        }

        $catalogCaptureCount = 0;
        $pageCaptureCount = 0;
        $commandCount = 0;
        $sourceUrls = [];
        $sourceSchemes = [];
        $remoteSourceUrlCount = 0;
        $fileSourceUrlCount = 0;
        $relativeSourceUrlCount = 0;
        $missingSourceUrlCount = 0;
        $pageReferenceCount = 0;
        $unresolvedPageReferences = [];
        $commandLinkCount = 0;
        $unresolvedCommandLinks = [];
        $maxDepth = null;
        $issues = [];

        foreach ($metadata as $webCapture) {
            $source = is_string($webCapture['source'] ?? null) ? $webCapture['source'] : '';
            if (str_starts_with($source, 'page:')) {
                $pageCaptureCount++;
            } elseif ($source !== '') {
                $catalogCaptureCount++;
            }

            foreach (($webCapture['captures'] ?? []) as $capture) {
                $commandCount++;
                $sourceUrl = is_string($capture['sourceUrl'] ?? null) && $capture['sourceUrl'] !== ''
                    ? $capture['sourceUrl']
                    : null;
                if ($sourceUrl === null) {
                    $missingSourceUrlCount++;
                } elseif (!isset($sourceUrls[$sourceUrl])) {
                    $sourceUrls[$sourceUrl] = true;
                    $scheme = $this->pdfActionTargetScheme($sourceUrl) ?? 'relative';
                    $sourceSchemes[$scheme] = ($sourceSchemes[$scheme] ?? 0) + 1;
                    if (in_array($scheme, ['ftp', 'ftps', 'http', 'https'], true)) {
                        $remoteSourceUrlCount++;
                    } elseif ($scheme === 'file') {
                        $fileSourceUrlCount++;
                    } elseif ($scheme === 'relative') {
                        $relativeSourceUrlCount++;
                    }
                }

                $depth = $capture['depth'] ?? null;
                if (is_int($depth)) {
                    $maxDepth = $maxDepth === null ? $depth : max($maxDepth, $depth);
                }

                foreach (($capture['pageReferences'] ?? []) as $pageReference) {
                    if (!is_string($pageReference) || $pageReference === '') {
                        continue;
                    }
                    $pageReferenceCount++;
                    if (!isset($knownPageObjects[$pageReference])) {
                        $unresolvedPageReferences[$pageReference] = true;
                    }
                }

                foreach (['parentCommand', 'nextCommand'] as $linkKey) {
                    $linkedCommand = $capture[$linkKey] ?? null;
                    if (!is_string($linkedCommand) || $linkedCommand === '') {
                        continue;
                    }
                    $commandLinkCount++;
                    if (!isset($commandObjects[$linkedCommand])) {
                        $unresolvedCommandLinks[$linkedCommand] = true;
                    }
                }
            }
        }

        if ($remoteSourceUrlCount > 0) {
            $issues[] = 'remote-source-url';
        }
        if ($fileSourceUrlCount > 0) {
            $issues[] = 'file-source-url';
        }
        if ($relativeSourceUrlCount > 0) {
            $issues[] = 'relative-source-url';
        }
        if ($missingSourceUrlCount > 0) {
            $issues[] = 'web-capture-command-missing-url';
        }
        if ($unresolvedPageReferences !== []) {
            $issues[] = 'web-capture-missing-page-reference';
        }
        if ($unresolvedCommandLinks !== []) {
            $issues[] = 'web-capture-unresolved-command-link';
        }
        if ($maxDepth !== null && $maxDepth > 1) {
            $issues[] = 'deep-web-capture';
        }
        if ($commandCount === 0) {
            $issues[] = 'web-capture-without-commands';
        }

        ksort($sourceSchemes);
        $issues = $this->uniqueStrings($issues);
        sort($issues, SORT_STRING);

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'captureCount' => count($metadata),
            'commandCount' => $commandCount,
            'catalogCaptureCount' => $catalogCaptureCount,
            'pageCaptureCount' => $pageCaptureCount,
            'sourceUrlCount' => count($sourceUrls),
            'remoteSourceUrlCount' => $remoteSourceUrlCount,
            'fileSourceUrlCount' => $fileSourceUrlCount,
            'relativeSourceUrlCount' => $relativeSourceUrlCount,
            'missingSourceUrlCount' => $missingSourceUrlCount,
            'sourceSchemes' => $sourceSchemes,
            'pageReferenceCount' => $pageReferenceCount,
            'unresolvedPageReferences' => $this->sortedPdfReferenceKeys($unresolvedPageReferences),
            'commandLinkCount' => $commandLinkCount,
            'unresolvedCommandLinks' => $this->sortedPdfReferenceKeys($unresolvedCommandLinks),
            'maxDepth' => $maxDepth,
            'issues' => $issues,
        ];
    }

    /**
     * @return list<string>
     */
    private function pdfPageObjectReferences(string $pdfBytes): array
    {
        $pageObjects = [];
        foreach ($this->pdfObjectBodiesByReference($pdfBytes) as $reference => $body) {
            if (preg_match('/\/Type\s*\/Page\b/s', $body) === 1) {
                $pageObjects[$reference . ' R'] = true;
            }
        }

        return $this->sortedPdfReferenceKeys($pageObjects);
    }

    private function extractPdfReferenceValue(string $dictionary, string $name): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, $name);

        return $value !== null && $value['kind'] === 'reference' ? $value['value'] : null;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{source:string, page:int|null, pageObject:string|null, application:string, pieceObject:string|null, lastModified:string|null, privateObject:string|null, privateKeys:list<string>, privateValues:array<string, bool|float|int|string|null>, privateStreamBytes:int|null, privateStreamSha256:string|null, privateStreamSkipped:string|null}> $entries
     */
    private function collectPdfPieceInfoFromPageTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$entries,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            array_push(
                $entries,
                ...$this->summarizePdfPagePieceInfo(
                    $body,
                    $reference,
                    $objects,
                    $pageNumber
                )
            );

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPieceInfoFromPageTree(
                $objects,
                $kidReference,
                $visited,
                $entries,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{source:string, page:int|null, pageObject:string|null, application:string, pieceObject:string|null, lastModified:string|null, privateObject:string|null, privateKeys:list<string>, privateValues:array<string, bool|float|int|string|null>, privateStreamBytes:int|null, privateStreamSha256:string|null, privateStreamSkipped:string|null}>
     */
    private function summarizePdfPagePieceInfo(string $pageDictionary, string $pageReference, array $objects, int $pageNumber): array
    {
        $pieceInfo = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'PieceInfo', $objects);
        if ($pieceInfo === null) {
            return [];
        }

        return $this->summarizePdfPieceInfoDictionary(
            $pieceInfo,
            'page:' . $pageReference . ' R.PieceInfo',
            $pageNumber,
            $pageReference . ' R',
            $objects
        );
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{source:string, page:int|null, pageObject:string|null, application:string, pieceObject:string|null, lastModified:string|null, privateObject:string|null, privateKeys:list<string>, privateValues:array<string, bool|float|int|string|null>, privateStreamBytes:int|null, privateStreamSha256:string|null, privateStreamSkipped:string|null}>
     */
    private function summarizePdfPieceInfoDictionary(
        string $pieceInfo,
        string $source,
        ?int $page,
        ?string $pageObject,
        array $objects
    ): array {
        $entries = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($pieceInfo) as $entry) {
            if ($entry['key'] === 'Type') {
                continue;
            }

            $pieceObject = null;
            $pieceDictionary = null;
            if ($entry['value']['kind'] === 'reference') {
                $pieceObject = $entry['value']['value'];
                $pieceDictionary = $objects[$this->pdfReferenceKey($entry['value']['value'])] ?? null;
            } elseif ($entry['value']['kind'] === 'dictionary') {
                $pieceObject = 'inline';
                $pieceDictionary = $entry['value']['value'];
            }

            if ($pieceDictionary === null) {
                continue;
            }

            $private = $this->summarizePdfPieceInfoPrivateObject($pieceDictionary, $objects);
            $entries[] = [
                'source' => $source,
                'page' => $page,
                'pageObject' => $pageObject,
                'application' => $entry['key'],
                'pieceObject' => $pieceObject,
                'lastModified' => $this->extractPdfStringOrNameValue($pieceDictionary, 'LastModified'),
                'privateObject' => $private['object'],
                'privateKeys' => $private['keys'],
                'privateValues' => $private['values'],
                'privateStreamBytes' => $private['streamBytes'],
                'privateStreamSha256' => $private['streamSha256'],
                'privateStreamSkipped' => $private['streamSkipped'],
            ];
        }

        return $entries;
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string|null, keys:list<string>, values:array<string, bool|float|int|string|null>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}
     */
    private function summarizePdfPieceInfoPrivateObject(string $pieceDictionary, array $objects): array
    {
        $summary = [
            'object' => null,
            'keys' => [],
            'values' => [],
            'streamBytes' => null,
            'streamSha256' => null,
            'streamSkipped' => null,
        ];

        $value = $this->extractPdfValueForName($pieceDictionary, 'Private');
        if ($value === null) {
            return $summary;
        }

        if ($value['kind'] === 'reference') {
            $summary['object'] = $value['value'];
            $privateObject = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($privateObject === null) {
                return $summary;
            }
        } elseif ($value['kind'] === 'dictionary') {
            $summary['object'] = 'inline';
            $privateObject = $value['value'];
        } else {
            $scalar = $this->pdfPieceInfoScalarValue($value);
            if ($scalar['ok']) {
                $summary['keys'] = ['value'];
                $summary['values'] = ['value' => $scalar['value']];
            }

            return $summary;
        }

        foreach ($this->extractPdfTopLevelDictionaryEntries($privateObject) as $entry) {
            if ($this->isPdfPieceInfoPrivateTechnicalKey($entry['key'])) {
                continue;
            }

            $summary['keys'][] = $entry['key'];
            $scalar = $this->pdfPieceInfoScalarValue($entry['value']);
            if ($scalar['ok']) {
                $summary['values'][$entry['key']] = $scalar['value'];
            }
        }
        $summary['keys'] = array_values(array_unique($summary['keys']));
        sort($summary['keys']);
        ksort($summary['values']);

        $streamBytes = $this->extractPdfStreamBytes($privateObject);
        if ($streamBytes !== null) {
            $summary['streamBytes'] = strlen($streamBytes);
            if (preg_match('/\/Filter\b/s', $privateObject) === 1) {
                $summary['streamSkipped'] = 'filtered';
            } elseif (strlen($streamBytes) > self::MAX_PIECE_INFO_PRIVATE_STREAM_BYTES) {
                $summary['streamSkipped'] = 'too-large';
            } else {
                $summary['streamSha256'] = hash('sha256', $streamBytes);
            }
        }

        return $summary;
    }

    private function isPdfPieceInfoPrivateTechnicalKey(string $key): bool
    {
        return in_array($key, ['DecodeParms', 'DL', 'Filter', 'Length', 'Subtype', 'Type'], true);
    }

    /**
     * @param array{kind:string, value:string} $value
     * @return array{ok:bool, value:bool|float|int|string|null}
     */
    private function pdfPieceInfoScalarValue(array $value): array
    {
        if (in_array($value['kind'], ['literal', 'hex', 'name', 'reference'], true)) {
            return ['ok' => true, 'value' => $value['value']];
        }

        if ($value['kind'] === 'number') {
            $number = $value['value'];
            if (preg_match('/[.Ee]/', $number) === 1) {
                return ['ok' => true, 'value' => (float) $number];
            }

            return ['ok' => true, 'value' => (int) $number];
        }

        if ($value['kind'] === 'keyword') {
            if ($value['value'] === 'true' || $value['value'] === 'false') {
                return ['ok' => true, 'value' => $value['value'] === 'true'];
            }
            if ($value['value'] === 'null') {
                return ['ok' => true, 'value' => null];
            }
        }

        return ['ok' => false, 'value' => null];
    }

    /**
     * @return array{bytes:string, filtered:bool, compressedBytes:int|null, decodedFilter:string|null}|null
     */
    private function extractPdfMetadataStream(string $pdfBytes, ?string $catalog): ?array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $candidates = [];
        $metadataReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Metadata');
        if ($metadataReference !== null) {
            $reference = $this->pdfReferenceKey($metadataReference);
            if (isset($objects[$reference])) {
                $candidates[] = $objects[$reference];
            }
        }

        foreach ($this->pdfObjectBodies($pdfBytes) as $body) {
            if (
                !str_contains($body, '/Metadata')
                && !str_contains($body, '/Subtype /XML')
                && !str_contains($body, '/Subtype/XML')
            ) {
                continue;
            }
            $candidates[] = $body;
        }

        foreach ($candidates as $body) {
            $stream = $this->pdfMetadataStreamForObject($body, $objects);
            if ($stream === null) {
                continue;
            }

            return $stream;
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{bytes:string, filtered:bool, compressedBytes:int|null, decodedFilter:string|null}|null
     */
    private function pdfMetadataStreamForObject(string $objectBody, array $objects): ?array
    {
        $bytes = $this->extractPdfStreamBytes($objectBody);
        if ($bytes === null) {
            return null;
        }

        $filters = $this->extractPdfFilterNames($objectBody, $objects);
        if ($filters === []) {
            return [
                'bytes' => $bytes,
                'filtered' => false,
                'compressedBytes' => null,
                'decodedFilter' => null,
            ];
        }

        if ($filters === ['FlateDecode'] && $this->pdfMetadataStreamHasSimpleDecodeParameters($objectBody)) {
            try {
                return [
                    'bytes' => DeflateStream::decode($bytes, DeflateStream::FORMAT_ZLIB, self::MAX_XMP_METADATA_BYTES),
                    'filtered' => true,
                    'compressedBytes' => strlen($bytes),
                    'decodedFilter' => 'FlateDecode',
                ];
            } catch (\RuntimeException) {
                // Preserve the existing skipped-filter handoff for malformed compressed metadata.
            }
        }

        return [
            'bytes' => $bytes,
            'filtered' => true,
            'compressedBytes' => null,
            'decodedFilter' => null,
        ];
    }

    private function pdfMetadataStreamHasSimpleDecodeParameters(string $objectBody): bool
    {
        $decodeParameters = $this->extractPdfValueForName($objectBody, 'DecodeParms');

        return $decodeParameters === null
            || (($decodeParameters['kind'] ?? null) === 'keyword' && ($decodeParameters['value'] ?? null) === 'null');
    }

    /**
     * @return list<array{type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}>
     */
    private function extractPdfOutputIntents(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/OutputIntents')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $array = $this->extractPdfOutputIntentArrayValue($catalog, $objects);
        if ($array === null) {
            return [];
        }

        return $this->summarizePdfOutputIntentArray($array, $objects);
    }

    /**
     * @return list<array{page:int, pageObject:string|null, source:string, type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}>
     */
    private function extractPdfPageOutputIntents(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $intents = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageOutputIntentsFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $intents,
                $pageNumber,
                0
            );
        }

        if ($intents === []) {
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                array_push(
                    $intents,
                    ...$this->summarizePdfPageOutputIntents(
                        $body,
                        $reference,
                        $objects,
                        $pageNumber
                    )
                );
            }
        }

        return $intents;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, source:string, type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}> $intents
     */
    private function collectPdfPageOutputIntentsFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$intents,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            array_push(
                $intents,
                ...$this->summarizePdfPageOutputIntents($body, $reference, $objects, $pageNumber)
            );

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageOutputIntentsFromTree(
                $objects,
                $this->pdfReferenceKey($kidReference),
                $visited,
                $intents,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, source:string, type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}>
     */
    private function summarizePdfPageOutputIntents(string $pageDictionary, string $pageReference, array $objects, int $pageNumber): array
    {
        if (!str_contains($pageDictionary, '/OutputIntents')) {
            return [];
        }

        $array = $this->extractPdfOutputIntentArrayValue($pageDictionary, $objects);
        if ($array === null) {
            return [];
        }

        $intents = [];
        $source = 'page:' . $pageReference . ' R.OutputIntents';
        foreach ($this->summarizePdfOutputIntentArray($array, $objects) as $intent) {
            $intents[] = array_merge([
                'page' => $pageNumber,
                'pageObject' => $pageReference . ' R',
                'source' => $source,
            ], $intent);
        }

        return $intents;
    }

    /**
     * @param array<string, mixed> $xmpMetadata
     * @param list<array{type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}> $outputIntents
     * @param array{marked:bool|null, userProperties:bool|null, suspects:bool|null, structTreeRoot:string|null, roleMap:array<string, string>, structureChildren:int|null, parentTree:string|null, parentTreeNextKey:int|null, idTree:string|null}|array{} $taggingMetadata
     * @param array<string, mixed> $encryption
     * @return array<string, mixed>
     */
    private function summarizePdfConformancePolicy(
        array $xmpMetadata,
        array $outputIntents,
        ?string $language,
        array $taggingMetadata,
        array $encryption
    ): array
    {
        $pdfaIdentification = isset($xmpMetadata['pdfaIdentification']) && is_array($xmpMetadata['pdfaIdentification'])
            ? $xmpMetadata['pdfaIdentification']
            : [];
        $pdfaPart = is_string($pdfaIdentification['part'] ?? null) && $pdfaIdentification['part'] !== ''
            ? $pdfaIdentification['part']
            : null;
        $pdfaConformance = is_string($pdfaIdentification['conformance'] ?? null) && $pdfaIdentification['conformance'] !== ''
            ? $pdfaIdentification['conformance']
            : null;
        $pdfaClaimed = $pdfaPart !== null || $pdfaConformance !== null;

        $pdfuaIdentification = isset($xmpMetadata['pdfuaIdentification']) && is_array($xmpMetadata['pdfuaIdentification'])
            ? $xmpMetadata['pdfuaIdentification']
            : [];
        $pdfuaPart = is_string($pdfuaIdentification['part'] ?? null) && $pdfuaIdentification['part'] !== ''
            ? $pdfuaIdentification['part']
            : null;
        $pdfuaAmendment = is_string($pdfuaIdentification['amendment'] ?? null) && $pdfuaIdentification['amendment'] !== ''
            ? $pdfuaIdentification['amendment']
            : null;
        $pdfuaCorrigendum = is_string($pdfuaIdentification['corrigendum'] ?? null) && $pdfuaIdentification['corrigendum'] !== ''
            ? $pdfuaIdentification['corrigendum']
            : null;
        $pdfuaClaimed = $pdfuaPart !== null || $pdfuaAmendment !== null || $pdfuaCorrigendum !== null;

        if (!$pdfaClaimed && !$pdfuaClaimed) {
            return [];
        }

        $encrypted = ($encryption['encrypted'] ?? false) === true;
        $tagged = is_bool($taggingMetadata['marked'] ?? null) ? $taggingMetadata['marked'] : null;
        $structTreeRoot = is_string($taggingMetadata['structTreeRoot'] ?? null) && $taggingMetadata['structTreeRoot'] !== ''
            ? $taggingMetadata['structTreeRoot']
            : null;

        $issues = [];
        if ($pdfaClaimed && $encrypted) {
            $issues[] = 'pdfa-output-encrypted';
        }
        if ($pdfaClaimed && $outputIntents === []) {
            $issues[] = 'pdfa-missing-output-intent';
        }
        if ($pdfuaClaimed && $tagged !== true) {
            $issues[] = 'pdfua-not-marked';
        }
        if ($pdfuaClaimed && $structTreeRoot === null) {
            $issues[] = 'pdfua-missing-structure-tree';
        }
        if ($pdfuaClaimed && ($language === null || $language === '')) {
            $issues[] = 'pdfua-missing-language';
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'pdfaClaimed' => $pdfaClaimed,
            'pdfaPart' => $pdfaPart,
            'pdfaConformance' => $pdfaConformance,
            'pdfuaClaimed' => $pdfuaClaimed,
            'pdfuaPart' => $pdfuaPart,
            'pdfuaAmendment' => $pdfuaAmendment,
            'pdfuaCorrigendum' => $pdfuaCorrigendum,
            'encrypted' => $encrypted,
            'language' => $language,
            'tagged' => $tagged,
            'structTreeRoot' => $structTreeRoot,
            'outputIntentCount' => count($outputIntents),
            'issues' => $issues,
        ];
    }

    /**
     * @param array<string, mixed> $xmpMetadata
     * @param list<array{name:string, unicodeName:string|null, description:string|null, afRelationship:string|null, filespec:string|null, embeddedFile:string|null, subtype:string|null, size:int|null, modDate:string|null, checksum:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, collectionItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, source:string}> $embeddedFiles
     * @return array<string, mixed>
     */
    private function summarizePdfAssociatedFilePolicy(array $xmpMetadata, array $embeddedFiles): array
    {
        if ($embeddedFiles === []) {
            return [];
        }

        $pdfaIdentification = isset($xmpMetadata['pdfaIdentification']) && is_array($xmpMetadata['pdfaIdentification'])
            ? $xmpMetadata['pdfaIdentification']
            : [];
        $pdfaPart = is_string($pdfaIdentification['part'] ?? null) && $pdfaIdentification['part'] !== ''
            ? $pdfaIdentification['part']
            : null;
        $pdfaConformance = is_string($pdfaIdentification['conformance'] ?? null) && $pdfaIdentification['conformance'] !== ''
            ? $pdfaIdentification['conformance']
            : null;
        $pdfaClaimed = $pdfaPart !== null || $pdfaConformance !== null;
        $standardRelationships = array_fill_keys(['Alternative', 'Data', 'Source', 'Supplement', 'Unspecified'], true);
        $relationshipCounts = [];
        $associatedFileCount = 0;
        $unassociatedFileCount = 0;
        $missingRelationshipCount = 0;
        $issueSet = [];
        $files = [];

        foreach ($embeddedFiles as $embeddedFile) {
            $source = is_string($embeddedFile['source'] ?? null) ? $embeddedFile['source'] : '';
            $relationship = is_string($embeddedFile['afRelationship'] ?? null) && $embeddedFile['afRelationship'] !== ''
                ? $embeddedFile['afRelationship']
                : null;
            $associated = $this->isPdfAssociatedFileSource($source);
            $fileIssues = [];

            if ($associated) {
                $associatedFileCount++;
                if ($relationship === null) {
                    $missingRelationshipCount++;
                    $fileIssues[] = 'associated-file-missing-afrelationship';
                } else {
                    $relationshipCounts[$relationship] = ($relationshipCounts[$relationship] ?? 0) + 1;
                    if (!isset($standardRelationships[$relationship])) {
                        $fileIssues[] = 'associated-file-nonstandard-afrelationship';
                    }
                }

                if ($pdfaClaimed && $pdfaPart !== '3') {
                    $fileIssues[] = 'pdfa-associated-files-require-pdfa-3';
                }
            } else {
                $unassociatedFileCount++;
                if ($pdfaClaimed && (($embeddedFile['embeddedFile'] ?? null) !== null || ($embeddedFile['streamBytes'] ?? null) !== null)) {
                    $fileIssues[] = 'pdfa-embedded-file-not-associated';
                }
            }

            $fileIssues = array_values(array_unique($fileIssues));
            foreach ($fileIssues as $issue) {
                $issueSet[$issue] = true;
            }

            $files[] = [
                'name' => (string) ($embeddedFile['name'] ?? ''),
                'source' => $source,
                'filespec' => is_string($embeddedFile['filespec'] ?? null) ? $embeddedFile['filespec'] : null,
                'embeddedFile' => is_string($embeddedFile['embeddedFile'] ?? null) ? $embeddedFile['embeddedFile'] : null,
                'afRelationship' => $relationship,
                'associated' => $associated,
                'issues' => $fileIssues,
            ];
        }

        ksort($relationshipCounts);
        $issues = array_keys($issueSet);
        sort($issues, SORT_STRING);

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'pdfaClaimed' => $pdfaClaimed,
            'pdfaPart' => $pdfaPart,
            'pdfaConformance' => $pdfaConformance,
            'embeddedFileCount' => count($embeddedFiles),
            'associatedFileCount' => $associatedFileCount,
            'unassociatedFileCount' => $unassociatedFileCount,
            'missingRelationshipCount' => $missingRelationshipCount,
            'relationshipCounts' => $relationshipCounts,
            'issues' => $issues,
            'files' => $files,
        ];
    }

    private function isPdfAssociatedFileSource(string $source): bool
    {
        return $source === 'catalog.AF'
            || str_ends_with($source, '.AF')
            || str_contains($source, '.AF.');
    }

    /**
     * @param array<string, mixed> $xmpMetadata
     * @param list<array{type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}> $outputIntents
     * @param list<array{page:int, pageObject:string|null, source:string, type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}> $pageOutputIntents
     * @return array<string, mixed>
     */
    private function summarizePdfOutputIntentPolicy(array $xmpMetadata, array $outputIntents, array $pageOutputIntents): array
    {
        $pdfxIdentification = isset($xmpMetadata['pdfxIdentification']) && is_array($xmpMetadata['pdfxIdentification'])
            ? $xmpMetadata['pdfxIdentification']
            : [];
        $pdfxVersion = is_string($pdfxIdentification['version'] ?? null) && $pdfxIdentification['version'] !== ''
            ? $pdfxIdentification['version']
            : null;
        $pdfxConformance = is_string($pdfxIdentification['conformance'] ?? null) && $pdfxIdentification['conformance'] !== ''
            ? $pdfxIdentification['conformance']
            : null;
        $hasPdfxIdentification = $pdfxVersion !== null || $pdfxConformance !== null;

        $intents = [];
        $pdfxIntentCount = 0;
        $documentPdfxIntentCount = 0;
        $pagePdfxIntentCount = 0;
        $missingConditionCount = 0;
        $embeddedProfileCount = 0;
        $issues = [];

        foreach ($outputIntents as $index => $intent) {
            $entry = $this->pdfOutputIntentPolicyEntry($intent, 'document', null, 'catalog.OutputIntents[' . $index . ']');
            $intents[] = $entry;
            if ($entry['pdfxIntent']) {
                $pdfxIntentCount++;
                $documentPdfxIntentCount++;
            }
            if ($entry['pdfxIntent'] && $entry['outputConditionIdentifier'] === null) {
                $missingConditionCount++;
            }
            if ($entry['pdfxIntent'] && $entry['hasDestOutputProfile']) {
                $embeddedProfileCount++;
            }
        }

        foreach ($pageOutputIntents as $intent) {
            $page = is_int($intent['page'] ?? null) ? $intent['page'] : null;
            $source = is_string($intent['source'] ?? null) && $intent['source'] !== ''
                ? $intent['source']
                : 'page.OutputIntents';
            $entry = $this->pdfOutputIntentPolicyEntry($intent, 'page', $page, $source);
            $intents[] = $entry;
            if ($entry['pdfxIntent']) {
                $pdfxIntentCount++;
                $pagePdfxIntentCount++;
            }
            if ($entry['pdfxIntent'] && $entry['outputConditionIdentifier'] === null) {
                $missingConditionCount++;
            }
            if ($entry['pdfxIntent'] && $entry['hasDestOutputProfile']) {
                $embeddedProfileCount++;
            }
        }

        if (!$hasPdfxIdentification && $pdfxIntentCount === 0) {
            return [];
        }

        if ($hasPdfxIdentification && $documentPdfxIntentCount === 0) {
            $issues[] = $pagePdfxIntentCount > 0
                ? 'pdfx-output-intent-page-scoped'
                : 'missing-pdfx-output-intent';
        }
        if (!$hasPdfxIdentification && $pdfxIntentCount > 0) {
            $issues[] = 'missing-pdfx-xmp-identification';
        }
        if ($missingConditionCount > 0) {
            $issues[] = 'missing-output-condition-identifier';
        }
        if ($pdfxIntentCount > 0 && $embeddedProfileCount === 0) {
            $issues[] = 'missing-dest-output-profile';
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'pdfxVersion' => $pdfxVersion,
            'pdfxConformance' => $pdfxConformance,
            'pdfxIntentCount' => $pdfxIntentCount,
            'documentPdfxIntentCount' => $documentPdfxIntentCount,
            'pagePdfxIntentCount' => $pagePdfxIntentCount,
            'embeddedProfileCount' => $embeddedProfileCount,
            'issues' => $issues,
            'intents' => $intents,
        ];
    }

    /**
     * @param array<string, mixed> $intent
     * @return array{scope:string, page:int|null, source:string, subtype:string|null, outputConditionIdentifier:string|null, registryName:string|null, hasDestOutputProfile:bool, profileComponents:int|null, profileSkipped:string|null, pdfxIntent:bool}
     */
    private function pdfOutputIntentPolicyEntry(array $intent, string $scope, ?int $page, string $source): array
    {
        $subtype = is_string($intent['subtype'] ?? null) && $intent['subtype'] !== ''
            ? $intent['subtype']
            : null;
        $outputConditionIdentifier = is_string($intent['outputConditionIdentifier'] ?? null) && $intent['outputConditionIdentifier'] !== ''
            ? $intent['outputConditionIdentifier']
            : null;
        $registryName = is_string($intent['registryName'] ?? null) && $intent['registryName'] !== ''
            ? $intent['registryName']
            : null;
        $destOutputProfile = is_string($intent['destOutputProfile'] ?? null) && $intent['destOutputProfile'] !== ''
            ? $intent['destOutputProfile']
            : null;

        return [
            'scope' => $scope,
            'page' => $page,
            'source' => $source,
            'subtype' => $subtype,
            'outputConditionIdentifier' => $outputConditionIdentifier,
            'registryName' => $registryName,
            'hasDestOutputProfile' => $destOutputProfile !== null,
            'profileComponents' => is_int($intent['profileComponents'] ?? null) ? $intent['profileComponents'] : null,
            'profileSkipped' => is_string($intent['profileSkipped'] ?? null) && $intent['profileSkipped'] !== ''
                ? $intent['profileSkipped']
                : null,
            'pdfxIntent' => $subtype !== null && str_contains(strtoupper($subtype), 'PDFX'),
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}>
     */
    private function summarizePdfOutputIntentArray(string $array, array $objects): array
    {
        $intents = [];
        $cursor = 0;
        $length = strlen($array);
        while ($cursor < $length && count($intents) < 16) {
            while ($cursor < $length && ctype_space($array[$cursor])) {
                $cursor++;
            }

            if ($cursor >= $length) {
                break;
            }

            if (substr($array, $cursor, 2) === '<<') {
                $parsed = $this->parsePdfDictionary($array, $cursor);
                if ($parsed !== null) {
                    $intent = $this->summarizePdfOutputIntent($parsed['value'], $objects);
                    if ($intent !== null) {
                        $intents[] = $intent;
                    }
                    $cursor = $parsed['next'];
                    continue;
                }
            }

            if (preg_match('/\A(\d+)\s+(\d+)\s+R\b/s', substr($array, $cursor), $matches) === 1) {
                $reference = $matches[1] . ' ' . $matches[2];
                if (isset($objects[$reference])) {
                    $intent = $this->summarizePdfOutputIntent($objects[$reference], $objects);
                    if ($intent !== null) {
                        $intents[] = $intent;
                    }
                }
                $cursor += strlen($matches[0]);
                continue;
            }

            $cursor++;
        }

        return $intents;
    }

    /**
     * @param array<string, string> $objects
     */
    private function extractPdfOutputIntentArrayValue(string $catalog, array $objects): ?string
    {
        $array = $this->extractPdfArrayValue($catalog, 'OutputIntents');
        if ($array !== null) {
            return $array;
        }

        $reference = $this->extractPdfReferenceToken($catalog, 'OutputIntents');
        if ($reference === null) {
            return null;
        }

        $body = $objects[$this->pdfReferenceKey($reference)] ?? null;
        if ($body === null) {
            return null;
        }

        $offset = strpos($body, '[');
        if ($offset === false) {
            return null;
        }

        $parsed = $this->parsePdfArray($body, $offset);

        return $parsed === null ? null : $parsed['value'];
    }

    /**
     * @param array<string, string> $objects
     * @return array{type:string|null, subtype:string|null, outputConditionIdentifier:string|null, outputCondition:string|null, registryName:string|null, info:string|null, destOutputProfile:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null}|null
     */
    private function summarizePdfOutputIntent(string $dictionary, array $objects): ?array
    {
        if (
            !str_contains($dictionary, '/OutputIntent')
            && !str_contains($dictionary, '/OutputConditionIdentifier')
            && !str_contains($dictionary, '/DestOutputProfile')
        ) {
            return null;
        }

        $profileReference = $this->extractPdfReferenceToken($dictionary, 'DestOutputProfile');
        $profile = $profileReference === null
            ? [
                'components' => null,
                'alternate' => null,
                'bytes' => null,
                'sha256' => null,
                'skipped' => null,
            ]
            : $this->summarizePdfOutputProfile($objects[$this->pdfReferenceKey($profileReference)] ?? null);

        return [
            'type' => $this->extractPdfNameToken($dictionary, 'Type'),
            'subtype' => $this->extractPdfNameToken($dictionary, 'S'),
            'outputConditionIdentifier' => $this->extractPdfStringOrNameValue($dictionary, 'OutputConditionIdentifier'),
            'outputCondition' => $this->extractPdfStringOrNameValue($dictionary, 'OutputCondition'),
            'registryName' => $this->extractPdfStringOrNameValue($dictionary, 'RegistryName'),
            'info' => $this->extractPdfStringOrNameValue($dictionary, 'Info'),
            'destOutputProfile' => $profileReference,
            'profileComponents' => $profile['components'],
            'profileAlternate' => $profile['alternate'],
            'profileBytes' => $profile['bytes'],
            'profileSha256' => $profile['sha256'],
            'profileSkipped' => $profile['skipped'],
        ];
    }

    /**
     * @return array{components:int|null, alternate:string|null, bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function summarizePdfOutputProfile(?string $profileObject): array
    {
        $profile = [
            'components' => null,
            'alternate' => null,
            'bytes' => null,
            'sha256' => null,
            'skipped' => null,
        ];

        if ($profileObject === null) {
            return $profile;
        }

        $profile['components'] = $this->extractPdfIntegerToken($profileObject, 'N');
        $profile['alternate'] = $this->extractPdfNameToken($profileObject, 'Alternate');
        $bytes = $this->extractPdfStreamBytes($profileObject);
        if ($bytes === null) {
            return $profile;
        }

        $profile['bytes'] = strlen($bytes);
        if (preg_match('/\/Filter\b/s', $profileObject) === 1) {
            $profile['skipped'] = 'filtered';

            return $profile;
        }
        if (strlen($bytes) > self::MAX_OUTPUT_INTENT_PROFILE_BYTES) {
            $profile['skipped'] = 'too-large';

            return $profile;
        }

        $profile['sha256'] = hash('sha256', $bytes);

        return $profile;
    }

    private function extractPdfStreamBytes(string $objectBody): ?string
    {
        $streamPosition = strpos($objectBody, 'stream');
        if ($streamPosition === false) {
            return null;
        }

        $start = $streamPosition + strlen('stream');
        if (substr($objectBody, $start, 2) === "\r\n") {
            $start += 2;
        } elseif (isset($objectBody[$start]) && ($objectBody[$start] === "\n" || $objectBody[$start] === "\r")) {
            $start++;
        }

        $end = strpos($objectBody, 'endstream', $start);
        if ($end === false || $end < $start) {
            return null;
        }

        $bytes = substr($objectBody, $start, $end - $start);
        if (str_ends_with($bytes, "\r\n")) {
            return substr($bytes, 0, -2);
        }
        if (str_ends_with($bytes, "\n") || str_ends_with($bytes, "\r")) {
            return substr($bytes, 0, -1);
        }

        return $bytes;
    }

    private function xmpLocalizedText(string $xml, string $name): ?string
    {
        $block = null;
        foreach ($this->xmpNamespacePrefixes($xml, 'http://purl.org/dc/elements/1.1/', ['dc']) as $prefix) {
            $block = $this->xmpQualifiedElementBlock($xml, $prefix, $name);
            if ($block !== null) {
                break;
            }
        }
        $block ??= $this->xmpUnqualifiedElementBlock($xml, $name);
        if ($block === null) {
            return $this->xmpUnqualifiedScalarText($xml, $name);
        }

        if (preg_match('/<[^:>]*(?::)?li\b[^>]*\bxml:lang\s*=\s*["\']x-default["\'][^>]*>(.*?)<\/[^:>]*(?::)?li>/s', $block, $matches) === 1) {
            return $this->normalizeXmpText($matches[1]);
        }

        foreach ($this->xmpElementTextsFromBlock($block, 'li') as $value) {
            return $value;
        }

        return $this->normalizeXmpText($block);
    }

    private function xmpScalarText(string $xml, string $name): ?string
    {
        $block = $this->xmpElementBlock($xml, $name);
        if ($block !== null) {
            return $this->normalizeXmpText($block);
        }

        if (preg_match('/\b(?:[A-Za-z_][A-Za-z0-9_.-]*:)?' . preg_quote($name, '/') . '\s*=\s*(["\'])(.*?)\1/s', $xml, $matches) === 1) {
            return $this->normalizeXmpText($matches[2]);
        }

        return null;
    }

    private function xmpQualifiedScalarText(string $xml, string $prefix, string $name): ?string
    {
        $block = $this->xmpQualifiedElementBlock($xml, $prefix, $name);
        if ($block !== null) {
            return $this->normalizeXmpText($block);
        }

        if (preg_match('/\b' . preg_quote($prefix, '/') . ':' . preg_quote($name, '/') . '\s*=\s*(["\'])(.*?)\1/s', $xml, $matches) === 1) {
            return $this->normalizeXmpText($matches[2]);
        }

        return null;
    }

    /**
     * @param list<string> $fallbackPrefixes
     */
    private function xmpNamespaceScalarText(string $xml, string $namespaceUri, string $name, array $fallbackPrefixes): ?string
    {
        foreach ($this->xmpNamespacePrefixes($xml, $namespaceUri, $fallbackPrefixes) as $prefix) {
            $value = $this->xmpQualifiedScalarText($xml, $prefix, $name);
            if ($value !== null) {
                return $value;
            }
        }

        return null;
    }

    /**
     * @param list<string> $fallbackPrefixes
     * @return list<string>
     */
    private function xmpNamespacePrefixes(string $xml, string $namespaceUri, array $fallbackPrefixes): array
    {
        $prefixes = [];
        if (preg_match_all('/\bxmlns:([A-Za-z_][A-Za-z0-9_.-]*)\s*=\s*(["\'])(.*?)\2/s', $xml, $matches, PREG_SET_ORDER) >= 1) {
            foreach ($matches as $match) {
                $uri = html_entity_decode($match[3], ENT_QUOTES | ENT_XML1, 'UTF-8');
                if ($uri === $namespaceUri) {
                    $prefixes[] = $match[1];
                }
            }
        }

        foreach ($fallbackPrefixes as $prefix) {
            if (is_string($prefix) && $prefix !== '') {
                $prefixes[] = $prefix;
            }
        }

        return array_values(array_unique($prefixes));
    }

    /**
     * @return list<string>
     */
    private function xmpListText(string $xml, string $name): array
    {
        $block = $this->xmpElementBlock($xml, $name);
        if ($block === null) {
            $scalar = $this->xmpScalarText($xml, $name);

            return $scalar === null || $scalar === '' ? [] : [$scalar];
        }

        $values = $this->xmpElementTextsFromBlock($block, 'li');
        if ($values === []) {
            $scalar = $this->normalizeXmpText($block);
            if ($scalar !== null && $scalar !== '') {
                $values[] = $scalar;
            }
        }

        return array_values(array_unique($values));
    }

    private function xmpElementBlock(string $xml, string $name): ?string
    {
        if (preg_match('/<(?:[A-Za-z_][A-Za-z0-9_.-]*:)?' . preg_quote($name, '/') . '\b[^>]*>(.*?)<\/(?:[A-Za-z_][A-Za-z0-9_.-]*:)?' . preg_quote($name, '/') . '>/s', $xml, $matches) !== 1) {
            return null;
        }

        return $matches[1];
    }

    private function xmpQualifiedElementBlock(string $xml, string $prefix, string $name): ?string
    {
        if (preg_match('/<' . preg_quote($prefix, '/') . ':' . preg_quote($name, '/') . '\b[^>]*>(.*?)<\/' . preg_quote($prefix, '/') . ':' . preg_quote($name, '/') . '>/s', $xml, $matches) !== 1) {
            return null;
        }

        return $matches[1];
    }

    private function xmpUnqualifiedElementBlock(string $xml, string $name): ?string
    {
        if (preg_match('/<' . preg_quote($name, '/') . '\b[^>]*>(.*?)<\/' . preg_quote($name, '/') . '>/s', $xml, $matches) !== 1) {
            return null;
        }

        return $matches[1];
    }

    private function xmpUnqualifiedScalarText(string $xml, string $name): ?string
    {
        if (preg_match('/\b' . preg_quote($name, '/') . '\s*=\s*(["\'])(.*?)\1/s', $xml, $matches) !== 1) {
            return null;
        }

        return $this->normalizeXmpText($matches[2]);
    }

    private function xmpDirectChildText(\DOMElement $element, string $namespaceUri, string $localName): ?string
    {
        foreach ($element->childNodes as $child) {
            if (
                $child instanceof \DOMElement
                && $child->namespaceURI === $namespaceUri
                && $child->localName === $localName
            ) {
                return $this->normalizeXmpText($child->textContent);
            }
        }

        return null;
    }

    /**
     * @return list<\DOMElement>
     */
    private function xmpDescendantElements(\DOMNode $node, string $namespaceUri, string $localName): array
    {
        $elements = [];
        foreach ($node->childNodes as $child) {
            if (
                $child instanceof \DOMElement
                && $child->namespaceURI === $namespaceUri
                && $child->localName === $localName
            ) {
                $elements[] = $child;
            }

            foreach ($this->xmpDescendantElements($child, $namespaceUri, $localName) as $descendant) {
                $elements[] = $descendant;
            }
        }

        return $elements;
    }

    /**
     * @return list<string>
     */
    private function xmpElementTextsFromBlock(string $block, string $name): array
    {
        if (preg_match_all('/<(?:[A-Za-z_][A-Za-z0-9_.-]*:)?' . preg_quote($name, '/') . '\b[^>]*>(.*?)<\/(?:[A-Za-z_][A-Za-z0-9_.-]*:)?' . preg_quote($name, '/') . '>/s', $block, $matches) < 1) {
            return [];
        }

        $values = [];
        foreach ($matches[1] as $rawValue) {
            $value = $this->normalizeXmpText($rawValue);
            if ($value !== null && $value !== '') {
                $values[] = $value;
            }
        }

        return $values;
    }

    private function normalizeXmpText(string $text): ?string
    {
        $text = preg_replace('/<[^>]+>/', ' ', $text) ?? $text;
        $text = html_entity_decode($text, ENT_QUOTES | ENT_XML1, 'UTF-8');
        $text = preg_replace('/\s+/u', ' ', $text) ?? $text;
        $text = trim($text);

        return $text === '' ? null : $text;
    }

    private function extractPdfInfoDictionary(string $pdfBytes): ?string
    {
        if (preg_match('/\/Info\s+(\d+)\s+(\d+)\s+R\b/s', $pdfBytes, $matches) === 1) {
            $objects = $this->pdfObjectBodiesByReference($pdfBytes);
            $key = $matches[1] . ' ' . $matches[2];

            return $objects[$key] ?? null;
        }

        $offset = 0;
        while (($position = strpos($pdfBytes, '/Info', $offset)) !== false) {
            $cursor = $position + strlen('/Info');
            if ($cursor < strlen($pdfBytes) && preg_match('/[A-Za-z0-9_.-]/', $pdfBytes[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < strlen($pdfBytes) && ctype_space($pdfBytes[$cursor])) {
                $cursor++;
            }
            if (substr($pdfBytes, $cursor, 2) !== '<<') {
                $offset = $cursor + 1;
                continue;
            }

            $parsed = $this->parsePdfDictionary($pdfBytes, $cursor);
            if ($parsed !== null) {
                return $parsed['value'];
            }

            $offset = $cursor + 2;
        }

        return null;
    }

    private function extractPdfCatalogLanguage(string $pdfBytes, ?string $catalog = null): ?string
    {
        if ($catalog !== null) {
            foreach ($this->extractPdfNamedStrings($catalog, 'Lang') as $language) {
                $language = trim($language);
                if ($language !== '') {
                    return $language;
                }
            }

            $language = $this->extractPdfNameToken($catalog, 'Lang');
            if ($language !== null && $language !== '') {
                return $language;
            }
        }

        foreach ($this->pdfObjectBodies($pdfBytes) as $body) {
            if (preg_match('/\/Type\s*\/Catalog\b/s', $body) !== 1 || !str_contains($body, '/Lang')) {
                continue;
            }

            foreach ($this->extractPdfNamedStrings($body, 'Lang') as $language) {
                $language = trim($language);
                if ($language !== '') {
                    return $language;
                }
            }

            $language = $this->extractPdfNameToken($body, 'Lang');
            if ($language !== null && $language !== '') {
                return $language;
            }
        }

        return null;
    }

    private function extractPdfCatalogDictionary(string $pdfBytes): ?string
    {
        if (preg_match('/\/Root\s+(\d+)\s+(\d+)\s+R\b/s', $pdfBytes, $matches) === 1) {
            $objects = $this->pdfObjectBodiesByReference($pdfBytes);
            $key = $matches[1] . ' ' . $matches[2];
            if (isset($objects[$key])) {
                return $objects[$key];
            }
        }

        foreach ($this->pdfObjectBodies($pdfBytes) as $body) {
            if (preg_match('/\/Type\s*\/Catalog\b/s', $body) === 1) {
                return $body;
            }
        }

        $offset = 0;
        while (($position = strpos($pdfBytes, '/Root', $offset)) !== false) {
            $cursor = $position + strlen('/Root');
            if ($cursor < strlen($pdfBytes) && preg_match('/[A-Za-z0-9_.-]/', $pdfBytes[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < strlen($pdfBytes) && ctype_space($pdfBytes[$cursor])) {
                $cursor++;
            }
            if (substr($pdfBytes, $cursor, 2) !== '<<') {
                $offset = $cursor + 1;
                continue;
            }

            $parsed = $this->parsePdfDictionary($pdfBytes, $cursor);
            if ($parsed !== null) {
                return $parsed['value'];
            }

            $offset = $cursor + 2;
        }

        return null;
    }

    private function extractPdfCatalogName(?string $catalog, string $name): ?string
    {
        if ($catalog === null) {
            return null;
        }

        $value = $this->extractPdfNameToken($catalog, $name);

        return $value === '' ? null : $value;
    }

    /**
     * @return array<string, mixed>|null
     */
    private function extractPdfOpenAction(string $pdfBytes, ?string $catalog): ?array
    {
        if ($catalog === null || !str_contains($catalog, '/OpenAction')) {
            return null;
        }

        if (preg_match('/\/OpenAction\s+(\d+)\s+(\d+)\s+R\b/s', $catalog, $matches) === 1) {
            $objects = $this->pdfObjectBodiesByReference($pdfBytes);
            $body = $objects[$matches[1] . ' ' . $matches[2]] ?? null;
            if ($body !== null) {
                return $this->summarizePdfOpenActionValue($body);
            }
        }

        return $this->extractPdfOpenActionValue($catalog);
    }

    /**
     * @return array<string, mixed>|null
     */
    private function extractPdfOpenActionValue(string $dictionary): ?array
    {
        $needle = '/OpenAction';
        $offset = 0;
        $length = strlen($dictionary);
        while (($position = strpos($dictionary, $needle, $offset)) !== false) {
            $cursor = $position + strlen($needle);
            if ($cursor < $length && preg_match('/[A-Za-z0-9_.-]/', $dictionary[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < $length && ctype_space($dictionary[$cursor])) {
                $cursor++;
            }

            if ($cursor >= $length) {
                return null;
            }

            if ($dictionary[$cursor] === '[') {
                $parsed = $this->parsePdfArray($dictionary, $cursor);
                return $parsed === null ? null : $this->summarizePdfDestinationArray($parsed['value']);
            }

            if (substr($dictionary, $cursor, 2) === '<<') {
                $parsed = $this->parsePdfDictionary($dictionary, $cursor);
                return $parsed === null ? null : $this->summarizePdfActionDictionary($parsed['value']);
            }

            if ($dictionary[$cursor] === '(') {
                $parsed = $this->parsePdfLiteralString($dictionary, $cursor);
                if ($parsed !== null && trim($parsed['value']) !== '') {
                    return ['type' => 'named-destination', 'target' => trim($parsed['value'])];
                }
            }

            if ($dictionary[$cursor] === '<' && ($cursor + 1 >= $length || $dictionary[$cursor + 1] !== '<')) {
                $parsed = $this->parsePdfHexString($dictionary, $cursor);
                if ($parsed !== null && trim($parsed['value']) !== '') {
                    return ['type' => 'named-destination', 'target' => trim($parsed['value'])];
                }
            }

            if (preg_match('/\/([A-Za-z0-9_.#+-]+)/A', substr($dictionary, $cursor), $matches) === 1) {
                return ['type' => 'named-action', 'target' => $this->decodePdfNameToken($matches[1])];
            }

            $offset = $cursor + 1;
        }

        return null;
    }

    /**
     * @return array<string, mixed>|null
     */
    private function summarizePdfOpenActionValue(string $value): ?array
    {
        $value = trim($value);
        if ($value === '') {
            return null;
        }
        if (str_starts_with($value, '<<')) {
            return $this->summarizePdfActionDictionary($value);
        }
        if (str_starts_with($value, '[')) {
            return $this->summarizePdfDestinationArray($value);
        }

        return $this->extractPdfOpenActionValue('/OpenAction ' . $value);
    }

    /**
     * @return array<string, mixed>|null
     */
    private function summarizePdfActionDictionary(string $dictionary): ?array
    {
        $type = $this->extractPdfNameToken($dictionary, 'S');
        if ($type === null || $type === '') {
            return ['type' => 'action'];
        }

        if ($type === 'URI') {
            $targets = $this->extractPdfNamedStrings($dictionary, 'URI');
            $target = $targets === [] ? null : trim($targets[0]);

            return $target === null || $target === ''
                ? ['type' => 'URI']
                : ['type' => 'URI', 'target' => $target];
        }

        if ($type === 'GoTo') {
            $destination = $this->extractPdfDestinationValue($dictionary, 'D');

            return $destination === null
                ? ['type' => 'GoTo']
                : array_merge(['type' => 'GoTo'], $destination);
        }

        if ($type === 'Named') {
            $target = $this->extractPdfNameToken($dictionary, 'N');
            if ($target === null) {
                $values = $this->extractPdfNamedStrings($dictionary, 'N');
                $target = $values === [] ? null : trim($values[0]);
            }

            return $target === null || $target === ''
                ? ['type' => 'Named']
                : ['type' => 'Named', 'target' => $target];
        }

        if ($type === 'Launch') {
            $target = $this->pdfLaunchActionTarget($dictionary);

            return $target === null || $target === ''
                ? ['type' => 'Launch']
                : ['type' => 'Launch', 'target' => $target];
        }

        return ['type' => $type];
    }

    /**
     * @return array<string, mixed>|null
     */
    private function extractPdfDestinationValue(string $dictionary, string $name): ?array
    {
        $needle = '/' . $name;
        $offset = 0;
        $length = strlen($dictionary);
        while (($position = strpos($dictionary, $needle, $offset)) !== false) {
            $cursor = $position + strlen($needle);
            if ($cursor < $length && preg_match('/[A-Za-z0-9_.-]/', $dictionary[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < $length && ctype_space($dictionary[$cursor])) {
                $cursor++;
            }
            if ($cursor >= $length) {
                return null;
            }
            if ($dictionary[$cursor] === '[') {
                $parsed = $this->parsePdfArray($dictionary, $cursor);
                return $parsed === null ? null : $this->summarizePdfDestinationArray($parsed['value']);
            }
            if ($dictionary[$cursor] === '(') {
                $parsed = $this->parsePdfLiteralString($dictionary, $cursor);
                return $parsed === null || trim($parsed['value']) === ''
                    ? null
                    : ['target' => trim($parsed['value'])];
            }
            if ($dictionary[$cursor] === '<' && ($cursor + 1 >= $length || $dictionary[$cursor + 1] !== '<')) {
                $parsed = $this->parsePdfHexString($dictionary, $cursor);
                return $parsed === null || trim($parsed['value']) === ''
                    ? null
                    : ['target' => trim($parsed['value'])];
            }
            if (preg_match('/\/([A-Za-z0-9_.#+-]+)/A', substr($dictionary, $cursor), $matches) === 1) {
                return ['target' => $this->decodePdfNameToken($matches[1])];
            }

            $offset = $cursor + 1;
        }

        return null;
    }

    /**
     * @return array<string, mixed>
     */
    private function summarizePdfDestinationArray(string $array): array
    {
        $summary = ['type' => 'destination'];
        if (preg_match('/\b(\d+)\s+(\d+)\s+R\b/s', $array, $matches) === 1) {
            $summary['pageObject'] = $matches[1] . ' ' . $matches[2] . ' R';
        }
        if (preg_match('/\/(XYZ|Fit|FitH|FitV|FitR|FitB|FitBH|FitBV)\b/s', $array, $matches) === 1) {
            $summary['fit'] = $matches[1];
        }
        if (!isset($summary['pageObject'])) {
            if (preg_match('/\[\s*\/([A-Za-z0-9_.#+-]+)/s', $array, $matches) === 1) {
                $summary['target'] = $this->decodePdfNameToken($matches[1]);
            } else {
                $strings = [];
                if (preg_match('/\[\s*\(/s', $array) === 1) {
                    $parsed = $this->parsePdfLiteralString($array, strpos($array, '(') ?: 0);
                    if ($parsed !== null) {
                        $strings[] = trim($parsed['value']);
                    }
                }
                if ($strings !== [] && $strings[0] !== '') {
                    $summary['target'] = $strings[0];
                }
            }
        }

        return $summary;
    }

    /**
     * @return list<array{name:string, source:string, target:string|null, pageObject:string|null, fit:string|null}>
     */
    private function extractPdfNamedDestinations(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || (!str_contains($catalog, '/Names') && !str_contains($catalog, '/Dests'))) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $destinations = [];
        $visited = [];

        $names = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Names', $objects);
        if ($names !== null) {
            $dests = $this->extractPdfDictionaryOrReferenceValue($names, 'Dests', $objects);
            if ($dests !== null) {
                $this->collectPdfNameTreeDestinations(
                    $destinations,
                    'catalog.Names.Dests',
                    $dests,
                    $objects,
                    $visited,
                    0
                );
            }
        }

        $legacyDests = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Dests', $objects);
        if ($legacyDests !== null) {
            $this->collectPdfDestinationDictionaryEntries(
                $destinations,
                'catalog.Dests',
                $legacyDests,
                $objects,
                $visited
            );
        }

        $destinations = array_values($destinations);
        usort(
            $destinations,
            static fn (array $a, array $b): int => [
                $a['name'],
                $a['source'],
                $a['target'] ?? '',
                $a['pageObject'] ?? '',
                $a['fit'] ?? '',
            ] <=> [
                $b['name'],
                $b['source'],
                $b['target'] ?? '',
                $b['pageObject'] ?? '',
                $b['fit'] ?? '',
            ]
        );

        return $destinations;
    }

    /**
     * @return list<array{category:string, source:string, entryCount:int, names:list<string>, valueKinds:array<string, int>, valueReferences:list<string>, kidCount:int, limits:list<string>}>
     */
    private function extractPdfNameTrees(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/Names')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $names = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($catalog, 'Names'), $objects);
        if ($names['dictionary'] === null) {
            return [];
        }

        $trees = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($names['dictionary']) as $entry) {
            if (in_array($entry['key'], ['Kids', 'Limits', 'Names', 'Type'], true)) {
                continue;
            }

            $root = $this->resolvePdfDictionaryValue($entry['value'], $objects);
            if ($root['dictionary'] === null) {
                continue;
            }

            $state = [
                'entryCount' => 0,
                'names' => [],
                'valueKinds' => [],
                'valueReferences' => [],
                'kidCount' => 0,
                'limits' => [],
            ];
            $visited = [];
            if (is_string($root['object']) && $root['object'] !== 'inline') {
                $visited[$this->pdfReferenceKey($root['object'])] = true;
            }

            $this->collectPdfNameTreeInventory(
                $state,
                $root['dictionary'],
                $objects,
                $visited,
                0
            );

            $state['names'] = $this->uniqueStrings($state['names']);
            sort($state['names']);
            ksort($state['valueKinds']);
            $state['valueReferences'] = $this->uniqueStrings($state['valueReferences']);
            sort($state['valueReferences']);
            $state['limits'] = $this->uniqueStrings($state['limits']);

            $trees[] = [
                'category' => $entry['key'],
                'source' => 'catalog.Names.' . $entry['key'],
                'entryCount' => $state['entryCount'],
                'names' => $state['names'],
                'valueKinds' => $state['valueKinds'],
                'valueReferences' => $state['valueReferences'],
                'kidCount' => $state['kidCount'],
                'limits' => $state['limits'],
            ];
        }

        usort($trees, static fn (array $a, array $b): int => $a['category'] <=> $b['category']);

        return $trees;
    }

    /**
     * @param array{entryCount:int, names:list<string>, valueKinds:array<string, int>, valueReferences:list<string>, kidCount:int, limits:list<string>} $state
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfNameTreeInventory(
        array &$state,
        string $dictionary,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $limits = $this->extractPdfArrayValue($dictionary, 'Limits');
        if ($limits !== null) {
            foreach ($this->collectPdfNamesFromArray($limits) as $limit) {
                $state['limits'][] = $limit;
            }
        }

        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array !== null) {
            $values = $this->pdfTopLevelArrayValues($array);
            for ($index = 0; $index + 1 < count($values); $index += 2) {
                $name = $values[$index];
                $value = $values[$index + 1];
                if (!in_array($name['kind'], ['literal', 'hex', 'name'], true)) {
                    continue;
                }

                $nameValue = trim($name['value']);
                if ($nameValue === '') {
                    continue;
                }

                $state['entryCount']++;
                if (count($state['names']) < 128) {
                    $state['names'][] = $nameValue;
                }
                $state['valueKinds'][$value['kind']] = ($state['valueKinds'][$value['kind']] ?? 0) + 1;
                if ($value['kind'] === 'reference') {
                    $state['valueReferences'][] = $value['value'];
                }
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $state['kidCount']++;
            $this->collectPdfNameTreeInventory(
                $state,
                $objects[$kidReference],
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @return list<array{category:string, source:string, reviewStatus:string, entryCount:int, kidCount:int, limits:list<string>, issues:list<string>, nodes:list<array{source:string, object:string|null, kind:string, entryCount:int, names:list<string>, kidCount:int, limits:list<string>, reviewStatus:string, issues:list<string>}>}>
     */
    private function extractPdfNameTreePolicies(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/Names')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $names = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($catalog, 'Names'), $objects);
        if ($names['dictionary'] === null) {
            return [];
        }

        $policies = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($names['dictionary']) as $entry) {
            if (in_array($entry['key'], ['Kids', 'Limits', 'Names', 'Type'], true)) {
                continue;
            }

            $root = $this->resolvePdfDictionaryValue($entry['value'], $objects);
            if ($root['dictionary'] === null) {
                continue;
            }

            $nodes = [];
            $visited = [];
            $rootObject = null;
            if (is_string($root['object']) && $root['object'] !== 'inline') {
                $visited[$this->pdfReferenceKey($root['object'])] = true;
                $rootObject = $root['object'];
            }

            $this->collectPdfNameTreePolicyNodes(
                $nodes,
                'catalog.Names.' . $entry['key'],
                $rootObject,
                'root',
                $root['dictionary'],
                $objects,
                $visited,
                0
            );

            $issues = [];
            $limits = [];
            $entryCount = 0;
            $kidCount = 0;
            foreach ($nodes as $node) {
                $entryCount += $node['entryCount'];
                $kidCount += $node['kidCount'];
                foreach ($node['limits'] as $limit) {
                    $limits[] = $limit;
                }
                foreach ($node['issues'] as $issue) {
                    $issues[] = $issue;
                }
            }

            $issues = $this->uniqueStrings($issues);
            sort($issues);

            $policies[] = [
                'category' => $entry['key'],
                'source' => 'catalog.Names.' . $entry['key'],
                'reviewStatus' => $issues === [] ? 'ok' : 'review',
                'entryCount' => $entryCount,
                'kidCount' => $kidCount,
                'limits' => $this->uniqueStrings($limits),
                'issues' => $issues,
                'nodes' => $nodes,
            ];
        }

        usort($policies, static fn (array $a, array $b): int => $a['category'] <=> $b['category']);

        return $policies;
    }

    /**
     * @param list<array{source:string, object:string|null, kind:string, entryCount:int, names:list<string>, kidCount:int, limits:list<string>, reviewStatus:string, issues:list<string>}> $nodes
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfNameTreePolicyNodes(
        array &$nodes,
        string $source,
        ?string $object,
        string $kind,
        string $dictionary,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $nameKeys = $this->extractPdfNameTreeNameKeys($dictionary);
        $limits = $this->extractPdfNameTreeLimitValues($dictionary);
        $limitValues = $limits ?? [];
        $kids = $this->extractPdfReferenceArray($dictionary, 'Kids');
        $issues = $this->pdfNameTreeNodeLimitIssues($nameKeys, $limits);
        $parentLimitsValid = count($limitValues) === 2
            && strcmp($limitValues[0], $limitValues[1]) <= 0;

        $previousKidUpper = null;
        foreach ($kids as $kidReference) {
            $kidDictionary = $objects[$kidReference] ?? null;
            if ($kidDictionary === null) {
                $issues[] = 'kid-reference-missing';
                continue;
            }

            $kidLimits = $this->extractPdfNameTreeLimitValues($kidDictionary);
            if ($kidLimits === null || count($kidLimits) !== 2) {
                $issues[] = 'kid-limits-missing';
            } elseif (strcmp($kidLimits[0], $kidLimits[1]) > 0) {
                $issues[] = 'kid-limits-out-of-order';
            } else {
                if (
                    $parentLimitsValid
                    && (strcmp($kidLimits[0], $limitValues[0]) < 0 || strcmp($kidLimits[1], $limitValues[1]) > 0)
                ) {
                    $issues[] = 'kid-limits-outside-parent';
                }
                if ($previousKidUpper !== null && strcmp($previousKidUpper, $kidLimits[0]) >= 0) {
                    $issues[] = 'kid-limits-overlap-or-unsorted';
                }
                $previousKidUpper = $kidLimits[1];
            }
        }

        $issues = $this->uniqueStrings($issues);
        sort($issues);
        $nodes[] = [
            'source' => $source,
            'object' => $object,
            'kind' => $kind,
            'entryCount' => count($nameKeys),
            'names' => array_slice($nameKeys, 0, 128),
            'kidCount' => count($kids),
            'limits' => $limitValues,
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'issues' => $issues,
        ];

        foreach ($kids as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $this->collectPdfNameTreePolicyNodes(
                $nodes,
                $source . '.Kids.' . $this->formatPdfIndirectReference($kidReference),
                $this->formatPdfIndirectReference($kidReference),
                'kid',
                $objects[$kidReference],
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @return list<string>
     */
    private function extractPdfNameTreeNameKeys(string $dictionary): array
    {
        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array === null) {
            return [];
        }

        $names = [];
        $values = $this->pdfTopLevelArrayValues($array);
        for ($index = 0; $index + 1 < count($values); $index += 2) {
            $name = $values[$index];
            if (!in_array($name['kind'], ['literal', 'hex', 'name'], true)) {
                continue;
            }

            $nameValue = trim($name['value']);
            if ($nameValue !== '') {
                $names[] = $nameValue;
            }
        }

        return $names;
    }

    /**
     * @return list<string>|null
     */
    private function extractPdfNameTreeLimitValues(string $dictionary): ?array
    {
        $array = $this->extractPdfArrayValue($dictionary, 'Limits');
        if ($array === null) {
            return null;
        }

        $limits = [];
        foreach ($this->pdfTopLevelArrayValues($array) as $value) {
            if (!in_array($value['kind'], ['literal', 'hex', 'name'], true)) {
                continue;
            }

            $limit = trim($value['value']);
            if ($limit !== '') {
                $limits[] = $limit;
            }
        }

        return $limits;
    }

    /**
     * @param list<string>|null $limits
     * @return list<string>
     */
    private function pdfNameTreeNodeLimitIssues(array $names, ?array $limits): array
    {
        if ($limits === null) {
            return [];
        }

        if (count($limits) !== 2) {
            return ['invalid-limits'];
        }

        $issues = [];
        if (strcmp($limits[0], $limits[1]) > 0) {
            $issues[] = 'limits-out-of-order';
        }

        if ($names !== []) {
            $sortedNames = $names;
            sort($sortedNames);
            $firstName = $sortedNames[0];
            $lastName = $sortedNames[count($sortedNames) - 1];
            if (strcmp($firstName, $limits[0]) < 0 || strcmp($lastName, $limits[1]) > 0) {
                $issues[] = 'names-outside-limits';
            }
        }

        return $issues;
    }

    private function formatPdfIndirectReference(string $reference): string
    {
        $reference = $this->pdfReferenceKey($reference);
        if (preg_match('/\A(\d+)\s+(\d+)\z/', $reference, $matches) === 1) {
            return $matches[1] . ' ' . $matches[2] . ' R';
        }

        return $reference;
    }

    /**
     * @param array<string, array{name:string, source:string, target:string|null, pageObject:string|null, fit:string|null}> $destinations
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfNameTreeDestinations(
        array &$destinations,
        string $source,
        string $dictionary,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array !== null) {
            $cursor = str_starts_with($array, '[') ? 1 : 0;
            $length = strlen($array);
            if (str_ends_with($array, ']')) {
                $length--;
            }

            while ($cursor < $length) {
                $name = $this->parsePdfValueAt($array, $cursor);
                if ($name === null) {
                    $cursor++;
                    continue;
                }
                $cursor = $name['next'];
                $value = $this->parsePdfValueAt($array, $cursor);
                if ($value === null) {
                    break;
                }
                $cursor = $value['next'];
                if (!in_array($name['kind'], ['literal', 'hex', 'name'], true)) {
                    continue;
                }

                $nameValue = trim($name['value']);
                if ($nameValue === '') {
                    continue;
                }

                $summary = $this->summarizePdfNamedDestinationValue($value, $objects);
                if ($summary !== null) {
                    $this->addPdfNamedDestination($destinations, $nameValue, $source, $summary);
                }
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $this->collectPdfNameTreeDestinations(
                $destinations,
                $source . '.Kids.' . $kidReference . ' R',
                $objects[$kidReference],
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, array{name:string, source:string, target:string|null, pageObject:string|null, fit:string|null}> $destinations
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfDestinationDictionaryEntries(
        array &$destinations,
        string $source,
        string $dictionary,
        array $objects,
        array &$visited
    ): void {
        if (str_contains($dictionary, '/Names') || str_contains($dictionary, '/Kids')) {
            $this->collectPdfNameTreeDestinations($destinations, $source, $dictionary, $objects, $visited, 0);
        }

        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            $name = $entry['key'];
            if (in_array($name, ['Kids', 'Limits', 'Names', 'Type'], true)) {
                continue;
            }

            $summary = $this->summarizePdfNamedDestinationValue($entry['value'], $objects);
            if ($summary !== null) {
                $this->addPdfNamedDestination($destinations, $name, $source, $summary);
            }
        }
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array<string, mixed>|null
     */
    private function summarizePdfNamedDestinationValue(array $value, array $objects): ?array
    {
        if ($value['kind'] === 'array') {
            return $this->summarizePdfDestinationArray($value['value']);
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfDestinationDictionary($value['value'], $objects);
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return null;
            }

            return $this->summarizePdfDestinationObjectBody($body, $objects);
        }

        if (in_array($value['kind'], ['literal', 'hex', 'name'], true)) {
            $target = trim($value['value']);

            return $target === '' ? null : ['type' => 'named-destination', 'target' => $target];
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return array<string, mixed>|null
     */
    private function summarizePdfDestinationObjectBody(string $body, array $objects): ?array
    {
        $body = trim($body);
        if ($body === '') {
            return null;
        }

        if (str_starts_with($body, '[')) {
            $parsed = $this->parsePdfArray($body, 0);

            return $parsed === null ? null : $this->summarizePdfDestinationArray($parsed['value']);
        }

        if (str_starts_with($body, '<<')) {
            $parsed = $this->parsePdfDictionary($body, 0);

            return $parsed === null ? null : $this->summarizePdfDestinationDictionary($parsed['value'], $objects);
        }

        $value = $this->parsePdfValueAt($body, 0);

        return $value === null ? null : $this->summarizePdfNamedDestinationValue($value, $objects);
    }

    /**
     * @param array<string, string> $objects
     * @return array<string, mixed>|null
     */
    private function summarizePdfDestinationDictionary(string $dictionary, array $objects): ?array
    {
        $destination = $this->extractPdfDestinationValue($dictionary, 'D')
            ?? $this->extractPdfDestinationValue($dictionary, 'Dest');
        if ($destination !== null) {
            return $destination;
        }

        $value = $this->extractPdfValueForName($dictionary, 'D');
        if ($value !== null) {
            return $this->summarizePdfNamedDestinationValue($value, $objects);
        }

        return null;
    }

    /**
     * @param array<string, array{name:string, source:string, target:string|null, pageObject:string|null, fit:string|null}> $destinations
     * @param array<string, mixed> $summary
     */
    private function addPdfNamedDestination(array &$destinations, string $name, string $source, array $summary): void
    {
        $entry = [
            'name' => $name,
            'source' => $source,
            'target' => is_string($summary['target'] ?? null) && $summary['target'] !== '' ? $summary['target'] : null,
            'pageObject' => is_string($summary['pageObject'] ?? null) && $summary['pageObject'] !== '' ? $summary['pageObject'] : null,
            'fit' => is_string($summary['fit'] ?? null) && $summary['fit'] !== '' ? $summary['fit'] : null,
        ];
        $key = implode("\0", [
            $entry['name'],
            $entry['source'],
            $entry['target'] ?? '',
            $entry['pageObject'] ?? '',
            $entry['fit'] ?? '',
        ]);
        $destinations[$key] = $entry;
    }

    /**
     * @return list<array{source:string, name:string|null, pageObject:string|null, target:string|null, fit:string|null, arguments:list<float|null>, left:float|null, top:float|null, right:float|null, bottom:float|null, zoom:float|null}>
     */
    private function extractPdfDestinationOptions(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $options = [];

        $openAction = $this->extractPdfValueForName($catalog, 'OpenAction');
        if ($openAction !== null) {
            $this->addPdfDestinationOptionFromValue($options, 'catalog.OpenAction', null, $openAction, $objects);
        }

        $names = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Names', $objects);
        if ($names !== null) {
            $dests = $this->extractPdfDictionaryOrReferenceValue($names, 'Dests', $objects);
            if ($dests !== null) {
                $visited = [];
                $this->collectPdfNameTreeDestinationOptions(
                    $options,
                    'catalog.Names.Dests',
                    $dests,
                    $objects,
                    $visited,
                    0
                );
            }
        }

        $legacyDests = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Dests', $objects);
        if ($legacyDests !== null) {
            $visited = [];
            $this->collectPdfDestinationDictionaryOptions(
                $options,
                'catalog.Dests',
                $legacyDests,
                $objects,
                $visited
            );
        }

        foreach ($objects as $reference => $body) {
            if (str_contains($body, '/Title') && preg_match('/\/(?:Parent|Dest|A|Next|Prev|First|Last)\b/s', $body) === 1) {
                $destination = $this->extractPdfValueForName($body, 'Dest');
                if ($destination !== null) {
                    $this->addPdfDestinationOptionFromValue($options, 'outline:' . $reference . ' R.Dest', null, $destination, $objects);
                }

                $action = $this->extractPdfDictionaryOrReferenceValue($body, 'A', $objects);
                if ($action !== null && $this->extractPdfNameToken($action, 'S') === 'GoTo') {
                    $actionDestination = $this->extractPdfValueForName($action, 'D');
                    if ($actionDestination !== null) {
                        $this->addPdfDestinationOptionFromValue($options, 'outline:' . $reference . ' R.A.D', null, $actionDestination, $objects);
                    }
                }
            }

            $subtype = $this->extractPdfNameToken($body, 'Subtype');
            if ($subtype === null || !$this->isPdfAnnotationSubtype($subtype)) {
                continue;
            }

            $destination = $this->extractPdfValueForName($body, 'Dest');
            if ($destination !== null) {
                $this->addPdfDestinationOptionFromValue($options, 'annotation:' . $reference . ' R.Dest', null, $destination, $objects);
            }

            $action = $this->extractPdfDictionaryOrReferenceValue($body, 'A', $objects);
            if ($action !== null && $this->extractPdfNameToken($action, 'S') === 'GoTo') {
                $actionDestination = $this->extractPdfValueForName($action, 'D');
                if ($actionDestination !== null) {
                    $this->addPdfDestinationOptionFromValue($options, 'annotation:' . $reference . ' R.A.D', null, $actionDestination, $objects);
                }
            }
        }

        $options = array_values($options);
        usort(
            $options,
            static fn (array $a, array $b): int => [
                $a['source'],
                $a['name'] ?? '',
                $a['target'] ?? '',
                $a['pageObject'] ?? '',
                $a['fit'] ?? '',
                json_encode($a['arguments']),
            ] <=> [
                $b['source'],
                $b['name'] ?? '',
                $b['target'] ?? '',
                $b['pageObject'] ?? '',
                $b['fit'] ?? '',
                json_encode($b['arguments']),
            ]
        );

        return $options;
    }

    /**
     * @param array<string, array{source:string, name:string|null, pageObject:string|null, target:string|null, fit:string|null, arguments:list<float|null>, left:float|null, top:float|null, right:float|null, bottom:float|null, zoom:float|null}> $options
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfNameTreeDestinationOptions(
        array &$options,
        string $source,
        string $dictionary,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array !== null) {
            $values = $this->pdfTopLevelArrayValues($array);
            for ($index = 0; $index + 1 < count($values); $index += 2) {
                $name = $values[$index];
                $value = $values[$index + 1];
                if (!in_array($name['kind'], ['literal', 'hex', 'name'], true)) {
                    continue;
                }

                $nameValue = trim($name['value']);
                if ($nameValue === '') {
                    continue;
                }

                $this->addPdfDestinationOptionFromValue($options, $source, $nameValue, $value, $objects);
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $this->collectPdfNameTreeDestinationOptions(
                $options,
                $source . '.Kids.' . $kidReference . ' R',
                $objects[$kidReference],
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, array{source:string, name:string|null, pageObject:string|null, target:string|null, fit:string|null, arguments:list<float|null>, left:float|null, top:float|null, right:float|null, bottom:float|null, zoom:float|null}> $options
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfDestinationDictionaryOptions(
        array &$options,
        string $source,
        string $dictionary,
        array $objects,
        array &$visited
    ): void {
        if (str_contains($dictionary, '/Names') || str_contains($dictionary, '/Kids')) {
            $this->collectPdfNameTreeDestinationOptions($options, $source, $dictionary, $objects, $visited, 0);
        }

        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            $name = $entry['key'];
            if (in_array($name, ['Kids', 'Limits', 'Names', 'Type'], true)) {
                continue;
            }

            $this->addPdfDestinationOptionFromValue($options, $source, $name, $entry['value'], $objects);
        }
    }

    /**
     * @param array<string, array{source:string, name:string|null, pageObject:string|null, target:string|null, fit:string|null, arguments:list<float|null>, left:float|null, top:float|null, right:float|null, bottom:float|null, zoom:float|null}> $options
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     */
    private function addPdfDestinationOptionFromValue(
        array &$options,
        string $source,
        ?string $name,
        array $value,
        array $objects
    ): void {
        $summary = $this->summarizePdfDestinationOptionValue($value, $objects, 0);
        if ($summary === null) {
            return;
        }

        $entry = array_merge([
            'source' => $source,
            'name' => $name,
        ], $summary);
        $key = implode("\0", [
            $entry['source'],
            $entry['name'] ?? '',
            $entry['target'] ?? '',
            $entry['pageObject'] ?? '',
            $entry['fit'] ?? '',
            json_encode($entry['arguments']),
        ]);
        $options[$key] = $entry;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{pageObject:string|null, target:string|null, fit:string|null, arguments:list<float|null>, left:float|null, top:float|null, right:float|null, bottom:float|null, zoom:float|null}|null
     */
    private function summarizePdfDestinationOptionValue(array $value, array $objects, int $depth): ?array
    {
        if ($depth > 8) {
            return null;
        }

        if ($value['kind'] === 'array') {
            return $this->summarizePdfDestinationOptionArray($value['value']);
        }

        if ($value['kind'] === 'dictionary') {
            $actionType = $this->extractPdfNameToken($value['value'], 'S');
            if ($actionType !== null && $actionType !== 'GoTo') {
                return null;
            }

            $destination = $this->extractPdfValueForName($value['value'], 'D')
                ?? $this->extractPdfValueForName($value['value'], 'Dest');

            return $destination === null
                ? null
                : $this->summarizePdfDestinationOptionValue($destination, $objects, $depth + 1);
        }

        if ($value['kind'] === 'reference') {
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return null;
            }

            $resolved = $this->parsePdfValueAt($body, 0);

            return $resolved === null
                ? null
                : $this->summarizePdfDestinationOptionValue($resolved, $objects, $depth + 1);
        }

        if (in_array($value['kind'], ['literal', 'hex', 'name'], true)) {
            $target = trim($value['value']);

            return $target === ''
                ? null
                : $this->pdfDestinationOptionSummary(null, $target, null, []);
        }

        return null;
    }

    /**
     * @return array{pageObject:string|null, target:string|null, fit:string|null, arguments:list<float|null>, left:float|null, top:float|null, right:float|null, bottom:float|null, zoom:float|null}|null
     */
    private function summarizePdfDestinationOptionArray(string $array): ?array
    {
        $values = $this->pdfTopLevelArrayValues($array);
        if ($values === []) {
            return null;
        }

        $fitNames = ['XYZ' => true, 'Fit' => true, 'FitH' => true, 'FitV' => true, 'FitR' => true, 'FitB' => true, 'FitBH' => true, 'FitBV' => true];
        $pageObject = null;
        $target = null;
        $fit = null;
        $fitIndex = null;

        foreach ($values as $index => $value) {
            if ($pageObject === null && $value['kind'] === 'reference') {
                $pageObject = $value['value'];
                continue;
            }

            if ($value['kind'] === 'name' && isset($fitNames[$value['value']])) {
                $fit = $value['value'];
                $fitIndex = $index;
                break;
            }

            if ($pageObject === null && $target === null && in_array($value['kind'], ['literal', 'hex', 'name'], true)) {
                $targetValue = trim($value['value']);
                if ($targetValue !== '') {
                    $target = $targetValue;
                }
            }
        }

        if ($pageObject === null && $target === null && $fit === null) {
            return null;
        }

        $arguments = [];
        if ($fitIndex !== null) {
            for ($index = $fitIndex + 1; $index < count($values) && count($arguments) < 8; $index++) {
                $argument = $this->pdfDestinationArgumentValue($values[$index]);
                if ($argument['accepted']) {
                    $arguments[] = $argument['value'];
                }
            }
        }

        return $this->pdfDestinationOptionSummary($pageObject, $target, $fit, $arguments);
    }

    /**
     * @param list<float|null> $arguments
     * @return array{pageObject:string|null, target:string|null, fit:string|null, arguments:list<float|null>, left:float|null, top:float|null, right:float|null, bottom:float|null, zoom:float|null}
     */
    private function pdfDestinationOptionSummary(?string $pageObject, ?string $target, ?string $fit, array $arguments): array
    {
        $left = null;
        $top = null;
        $right = null;
        $bottom = null;
        $zoom = null;

        if ($fit === 'XYZ') {
            $left = $arguments[0] ?? null;
            $top = $arguments[1] ?? null;
            $zoom = $arguments[2] ?? null;
        } elseif ($fit === 'FitH' || $fit === 'FitBH') {
            $top = $arguments[0] ?? null;
        } elseif ($fit === 'FitV' || $fit === 'FitBV') {
            $left = $arguments[0] ?? null;
        } elseif ($fit === 'FitR') {
            $left = $arguments[0] ?? null;
            $bottom = $arguments[1] ?? null;
            $right = $arguments[2] ?? null;
            $top = $arguments[3] ?? null;
        }

        return [
            'pageObject' => $pageObject,
            'target' => $target,
            'fit' => $fit,
            'arguments' => $arguments,
            'left' => $left,
            'top' => $top,
            'right' => $right,
            'bottom' => $bottom,
            'zoom' => $zoom,
        ];
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @return array{accepted:bool, value:float|null}
     */
    private function pdfDestinationArgumentValue(array $value): array
    {
        if ($value['kind'] === 'number') {
            return ['accepted' => true, 'value' => (float) $value['value']];
        }

        if ($value['kind'] === 'keyword' && $value['value'] === 'null') {
            return ['accepted' => true, 'value' => null];
        }

        return ['accepted' => false, 'value' => null];
    }

    /**
     * @param list<array{fit:string|null}> $destinationOptions
     * @return array<string, int>
     */
    private function summarizePdfDestinationFits(array $destinationOptions): array
    {
        $fits = [];
        foreach ($destinationOptions as $destinationOption) {
            $fit = is_string($destinationOption['fit'] ?? null) && $destinationOption['fit'] !== ''
                ? $destinationOption['fit']
                : 'named';
            $fits[$fit] = ($fits[$fit] ?? 0) + 1;
        }

        ksort($fits);

        return $fits;
    }

    /**
     * @return list<array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}>
     */
    private function extractPdfActiveActions(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $actions = [];

        if ($catalog !== null) {
            $this->addPdfActiveActionFromNamedValue($actions, 'catalog.OpenAction', $catalog, 'OpenAction', $objects);
            $this->collectPdfAdditionalActions($actions, 'catalog', $catalog, $objects);
            $this->collectPdfNamedJavaScriptActions($actions, $catalog, $objects);
        }

        foreach ($objects as $reference => $body) {
            if (preg_match('/\/Type\s*\/Catalog\b/s', $body) === 1) {
                continue;
            }

            $source = $this->pdfActionContainerSource($reference, $body);
            if ($source === null) {
                continue;
            }

            $this->addPdfActiveActionFromNamedValue($actions, $source . '.A', $body, 'A', $objects);
            $this->collectPdfAdditionalActions($actions, $source, $body, $objects);
        }

        $actions = array_values($actions);
        usort($actions, static fn (array $a, array $b): int => [$a['source'], $a['type'], $a['target'] ?? ''] <=> [$b['source'], $b['type'], $b['target'] ?? '']);

        return $actions;
    }

    private function pdfActionContainerSource(string $reference, string $body): ?string
    {
        $pdfReference = $reference . ' R';
        $type = $this->extractPdfNameToken($body, 'Type');
        $subtype = $this->extractPdfNameToken($body, 'Subtype');
        if ($type === 'Page') {
            return 'page:' . $pdfReference;
        }
        if ($type === 'Annot' || $subtype !== null) {
            return 'annotation:' . $pdfReference;
        }
        if (str_contains($body, '/A') || str_contains($body, '/AA')) {
            return 'object:' . $pdfReference;
        }

        return null;
    }

    /**
     * @param array<string, array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param array<string, string> $objects
     */
    private function addPdfActiveActionFromNamedValue(array &$actions, string $source, string $dictionary, string $name, array $objects, ?string $nameHint = null): void
    {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return;
        }

        $this->addPdfActiveActionFromValue($actions, $source, $value, $objects, $nameHint);
    }

    /**
     * @param array<string, array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param array<string, string> $objects
     * @param array{kind:string, value:string} $value
     */
    private function addPdfActiveActionFromValue(
        array &$actions,
        string $source,
        array $value,
        array $objects,
        ?string $nameHint = null,
        int $depth = 0,
        array $visited = []
    ): void
    {
        if ($depth > 16) {
            return;
        }

        $actionDictionary = null;
        if ($value['kind'] === 'reference') {
            $referenceKey = $this->pdfReferenceKey($value['value']);
            if (isset($visited[$referenceKey])) {
                return;
            }

            $visited[$referenceKey] = true;
            $body = $objects[$referenceKey] ?? null;
            if ($body === null) {
                return;
            }

            $actionDictionary = $body;
            $summary = $this->summarizePdfActiveActionDictionary($body, $source, $objects, $nameHint);
        } elseif ($value['kind'] === 'dictionary') {
            $actionDictionary = $value['value'];
            $summary = $this->summarizePdfActiveActionDictionary($actionDictionary, $source, $objects, $nameHint);
        } elseif ($value['kind'] === 'name' || $value['kind'] === 'literal' || $value['kind'] === 'hex') {
            $target = trim($value['value']);
            $summary = $target === ''
                ? null
                : [
                    'source' => $source,
                    'type' => 'Named',
                    'target' => $target,
                    'scriptBytes' => null,
                    'scriptSha256' => null,
                ];
        } else {
            $summary = null;
        }

        if ($summary === null) {
            return;
        }

        $key = implode("\0", [
            $summary['source'],
            $summary['type'],
            $summary['target'] ?? '',
            (string) ($summary['scriptBytes'] ?? ''),
            $summary['scriptSha256'] ?? '',
        ]);
        $actions[$key] = $summary;

        if ($actionDictionary !== null) {
            $this->collectPdfNextActions($actions, $source, $actionDictionary, $objects, $depth + 1, $visited);
        }
    }

    /**
     * @param array<string, array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param array<string, string> $objects
     */
    private function collectPdfNextActions(array &$actions, string $source, string $dictionary, array $objects, int $depth, array $visited): void
    {
        if ($depth > 16) {
            return;
        }

        $next = $this->extractPdfValueForName($dictionary, 'Next');
        if ($next === null) {
            return;
        }

        $this->addPdfActiveNextActionValue($actions, $source . '.Next', $next, $objects, $depth, $visited);
    }

    /**
     * @param array<string, array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param array<string, string> $objects
     * @param array{kind:string, value:string, next?:int} $value
     */
    private function addPdfActiveNextActionValue(array &$actions, string $source, array $value, array $objects, int $depth, array $visited): void
    {
        if ($depth > 16) {
            return;
        }

        if ($value['kind'] === 'array') {
            $cursor = str_starts_with($value['value'], '[') ? 1 : 0;
            $length = strlen($value['value']);
            if (str_ends_with($value['value'], ']')) {
                $length--;
            }
            $index = 0;
            while ($cursor < $length) {
                $item = $this->parsePdfValueAt($value['value'], $cursor);
                if ($item === null) {
                    $cursor++;
                    continue;
                }

                $this->addPdfActiveNextActionValue($actions, $source . '[' . $index . ']', $item, $objects, $depth + 1, $visited);
                $index++;
                $cursor = max($cursor + 1, min($length, $item['next']));
            }

            return;
        }

        if ($value['kind'] === 'reference') {
            $referenceKey = $this->pdfReferenceKey($value['value']);
            if (isset($visited[$referenceKey])) {
                return;
            }

            $body = $objects[$referenceKey] ?? null;
            if ($body === null) {
                return;
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved !== null && $resolved['kind'] === 'array') {
                $visited[$referenceKey] = true;
                $this->addPdfActiveNextActionValue($actions, $source, $resolved, $objects, $depth + 1, $visited);
                return;
            }
        }

        $this->addPdfActiveActionFromValue($actions, $source, $value, $objects, null, $depth + 1, $visited);
    }

    /**
     * @param array<string, array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param array<string, string> $objects
     */
    private function collectPdfAdditionalActions(array &$actions, string $source, string $dictionary, array $objects): void
    {
        $additionalActions = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'AA', $objects);
        if ($additionalActions === null) {
            return;
        }

        foreach (['E', 'X', 'D', 'U', 'Fo', 'Bl', 'PO', 'PC', 'PV', 'PI', 'O', 'C', 'K', 'F', 'V', 'WC', 'WS', 'DS', 'WP', 'DP'] as $trigger) {
            $this->addPdfActiveActionFromNamedValue($actions, $source . '.AA.' . $trigger, $additionalActions, $trigger, $objects);
        }
    }

    /**
     * @param array<string, array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param array<string, string> $objects
     */
    private function collectPdfNamedJavaScriptActions(array &$actions, string $catalog, array $objects): void
    {
        $names = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Names', $objects);
        if ($names === null) {
            return;
        }

        $javaScript = $this->extractPdfDictionaryOrReferenceValue($names, 'JavaScript', $objects);
        if ($javaScript === null) {
            return;
        }

        $visited = [];
        $this->collectPdfJavaScriptNameTreeActions(
            $actions,
            'catalog.Names.JavaScript',
            $javaScript,
            $objects,
            $visited,
            0
        );
    }

    /**
     * @param array<string, array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfJavaScriptNameTreeActions(
        array &$actions,
        string $source,
        string $dictionary,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array !== null) {
            $values = $this->pdfTopLevelArrayValues($array);
            $count = count($values);
            for ($index = 0; $index + 1 < $count; $index += 2) {
                $name = $values[$index];
                $action = $values[$index + 1];
                if (!in_array($name['kind'], ['literal', 'hex', 'name'], true)) {
                    continue;
                }

                $nameValue = trim($name['value']);
                $actionSource = $source . ($nameValue === '' ? '' : '.' . $this->pdfActionSourceToken($nameValue));
                $this->addPdfActiveActionFromValue(
                    $actions,
                    $actionSource,
                    $action,
                    $objects,
                    $nameValue === '' ? null : $nameValue
                );
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            $kidKey = $this->pdfReferenceKey($kidReference);
            if (isset($visited[$kidKey]) || !isset($objects[$kidKey])) {
                continue;
            }

            $visited[$kidKey] = true;
            $this->collectPdfJavaScriptNameTreeActions(
                $actions,
                $source . '.Kids.' . $kidKey . ' R',
                $objects[$kidKey],
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}|null
     */
    private function summarizePdfActiveActionDictionary(string $dictionary, string $source, array $objects, ?string $nameHint = null): ?array
    {
        $type = $this->extractPdfNameToken($dictionary, 'S');
        if ($type === null || !$this->isPdfActiveActionType($type)) {
            return null;
        }

        $script = $type === 'JavaScript' ? $this->extractPdfJavaScriptActionBytes($dictionary, $objects) : null;

        return [
            'source' => $source,
            'type' => $type,
            'target' => $this->pdfActiveActionTarget($dictionary, $type, $objects, $nameHint),
            'scriptBytes' => $script === null ? null : strlen($script),
            'scriptSha256' => $script === null ? null : hash('sha256', $script),
        ];
    }

    private function isPdfActiveActionType(string $type): bool
    {
        return in_array($type, [
            'GoToR',
            'GoToE',
            'Hide',
            'ImportData',
            'JavaScript',
            'Launch',
            'Movie',
            'Named',
            'Rendition',
            'ResetForm',
            'Sound',
            'SubmitForm',
            'URI',
        ], true);
    }

    /**
     * @param list<array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @return array<string, int>
     */
    private function summarizePdfActiveActionTypes(array $actions): array
    {
        $types = [];
        foreach ($actions as $action) {
            $types[$action['type']] = ($types[$action['type']] ?? 0) + 1;
        }

        ksort($types);

        return $types;
    }

    /**
     * @param list<array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @return array{reviewStatus:string, actionCount:int, sourceCount:int, sourceCategories:array<string, int>, actionTypes:array<string, int>, chainedActionCount:int, maxNextDepth:int, scriptActionCount:int, remoteTargetCount:int, remoteTargetSchemes?:array<string, int>, launchActionCount:int, formActionCount:int, embeddedFileActionCount?:int, issues:list<string>}|array{}
     */
    private function summarizePdfActiveActionPolicy(array $actions): array
    {
        if ($actions === []) {
            return [];
        }

        $sources = [];
        $sourceCategories = [];
        $actionTypes = [];
        $chainedActionCount = 0;
        $maxNextDepth = 0;
        $scriptActionCount = 0;
        $remoteTargetCount = 0;
        $remoteTargetSchemes = [];
        $launchActionCount = 0;
        $formActionCount = 0;
        $embeddedFileActionCount = 0;
        $issues = [];

        foreach ($actions as $action) {
            $source = is_string($action['source'] ?? null) ? $action['source'] : '';
            if ($source !== '') {
                $sources[$source] = true;
                $category = str_contains($source, ':')
                    ? substr($source, 0, (int) strpos($source, ':'))
                    : (str_contains($source, '.') ? substr($source, 0, (int) strpos($source, '.')) : $source);
                if ($category === '') {
                    $category = 'unknown';
                }
                $sourceCategories[$category] = ($sourceCategories[$category] ?? 0) + 1;

                $nextDepth = substr_count($source, '.Next');
                if ($nextDepth > 0) {
                    $chainedActionCount++;
                    $maxNextDepth = max($maxNextDepth, $nextDepth);
                    $issues[] = 'next-action-chain';
                    if ($nextDepth > 2) {
                        $issues[] = 'deep-next-action-chain';
                    }
                }
            }

            $type = is_string($action['type'] ?? null) ? $action['type'] : '';
            if ($type !== '') {
                $actionTypes[$type] = ($actionTypes[$type] ?? 0) + 1;
                if ($type === 'JavaScript') {
                    $issues[] = 'script-action';
                } elseif ($type === 'Launch') {
                    $launchActionCount++;
                    $issues[] = 'launch-action';
                } elseif ($type === 'SubmitForm') {
                    $formActionCount++;
                    $issues[] = 'submit-form-action';
                } elseif ($type === 'ResetForm') {
                    $formActionCount++;
                    $issues[] = 'reset-form-action';
                } elseif ($type === 'ImportData') {
                    $formActionCount++;
                    $issues[] = 'import-data-action';
                } elseif ($type === 'URI') {
                    $issues[] = 'uri-action';
                } elseif ($type === 'GoToE') {
                    $embeddedFileActionCount++;
                    $issues[] = 'embedded-file-action';
                }
            }

            if (($action['scriptBytes'] ?? null) !== null) {
                $scriptActionCount++;
                $issues[] = 'script-action';
            }

            $target = is_string($action['target'] ?? null) ? $action['target'] : null;
            $scheme = $this->pdfActionTargetScheme($target);
            if ($scheme !== null && in_array($scheme, ['ftp', 'ftps', 'http', 'https', 'mailto'], true)) {
                $remoteTargetCount++;
                $remoteTargetSchemes[$scheme] = ($remoteTargetSchemes[$scheme] ?? 0) + 1;
                $issues[] = 'remote-action-target';
            }
        }

        if ($issues === []) {
            $issues[] = 'active-action';
        }

        ksort($sourceCategories);
        ksort($actionTypes);
        ksort($remoteTargetSchemes);
        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        $policy = [
            'reviewStatus' => 'review',
            'actionCount' => count($actions),
            'sourceCount' => count($sources),
            'sourceCategories' => $sourceCategories,
            'actionTypes' => $actionTypes,
            'chainedActionCount' => $chainedActionCount,
            'maxNextDepth' => $maxNextDepth,
            'scriptActionCount' => $scriptActionCount,
            'remoteTargetCount' => $remoteTargetCount,
        ];
        if ($remoteTargetSchemes !== []) {
            $policy['remoteTargetSchemes'] = $remoteTargetSchemes;
        }
        $policy['launchActionCount'] = $launchActionCount;
        $policy['formActionCount'] = $formActionCount;
        if ($embeddedFileActionCount > 0) {
            $policy['embeddedFileActionCount'] = $embeddedFileActionCount;
        }
        $policy['issues'] = $issues;

        return $policy;
    }

    /**
     * @return list<array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}>
     */
    private function extractPdfJavaScriptActions(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $actions = [];

        if ($catalog !== null) {
            $this->addPdfJavaScriptActionFromNamedValue($actions, 'catalog.OpenAction', $catalog, 'OpenAction', $objects);
            $this->collectPdfAdditionalJavaScriptActions($actions, 'catalog', $catalog, $objects);
            $this->collectPdfNamedJavaScriptActionMetadata($actions, $catalog, $objects);
        }

        foreach ($objects as $reference => $body) {
            if (preg_match('/\/Type\s*\/Catalog\b/s', $body) === 1) {
                continue;
            }

            $source = $this->pdfActionContainerSource($reference, $body);
            if ($source === null) {
                continue;
            }

            $this->addPdfJavaScriptActionFromNamedValue($actions, $source . '.A', $body, 'A', $objects);
            $this->collectPdfAdditionalJavaScriptActions($actions, $source, $body, $objects);
        }

        $actions = array_values($actions);
        usort(
            $actions,
            static fn (array $a, array $b): int => [
                $a['source'],
                $a['target'] ?? '',
                $a['scriptSha256'] ?? '',
            ] <=> [
                $b['source'],
                $b['target'] ?? '',
                $b['scriptSha256'] ?? '',
            ]
        );

        return $actions;
    }

    /**
     * @param array<string, array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}> $actions
     * @param array<string, string> $objects
     */
    private function addPdfJavaScriptActionFromNamedValue(array &$actions, string $source, string $dictionary, string $name, array $objects, ?string $nameHint = null): void
    {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return;
        }

        $this->addPdfJavaScriptActionFromValue($actions, $source, $value, $objects, $nameHint);
    }

    /**
     * @param array<string, array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}> $actions
     * @param array<string, string> $objects
     * @param array{kind:string, value:string, next?:int} $value
     */
    private function addPdfJavaScriptActionFromValue(
        array &$actions,
        string $source,
        array $value,
        array $objects,
        ?string $nameHint = null,
        int $depth = 0,
        array $visited = []
    ): void {
        if ($depth > 16) {
            return;
        }

        $actionDictionary = null;
        $activeSummary = null;
        if ($value['kind'] === 'reference') {
            $referenceKey = $this->pdfReferenceKey($value['value']);
            if (isset($visited[$referenceKey])) {
                return;
            }

            $visited[$referenceKey] = true;
            $actionDictionary = $objects[$referenceKey] ?? null;
            if ($actionDictionary === null) {
                return;
            }

            $activeSummary = $this->summarizePdfActiveActionDictionary($actionDictionary, $source, $objects, $nameHint);
        } elseif ($value['kind'] === 'dictionary') {
            $actionDictionary = $value['value'];
            $activeSummary = $this->summarizePdfActiveActionDictionary($actionDictionary, $source, $objects, $nameHint);
        }

        if ($activeSummary === null || $actionDictionary === null) {
            return;
        }

        if (($activeSummary['type'] ?? null) === 'JavaScript') {
            $summary = $this->summarizePdfJavaScriptActionDictionary($actionDictionary, $source, $objects, $nameHint);
            if ($summary !== null) {
                $key = implode("\0", [
                    $summary['source'],
                    $summary['target'] ?? '',
                    (string) ($summary['scriptBytes'] ?? ''),
                    $summary['scriptSha256'] ?? '',
                ]);
                $actions[$key] = $summary;
            }
        }

        $this->collectPdfNextJavaScriptActions($actions, $source, $actionDictionary, $objects, $depth + 1, $visited);
    }

    /**
     * @param array<string, array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}> $actions
     * @param array<string, string> $objects
     */
    private function collectPdfNextJavaScriptActions(array &$actions, string $source, string $dictionary, array $objects, int $depth, array $visited): void
    {
        if ($depth > 16) {
            return;
        }

        $next = $this->extractPdfValueForName($dictionary, 'Next');
        if ($next === null) {
            return;
        }

        $this->addPdfNextJavaScriptActionValue($actions, $source . '.Next', $next, $objects, $depth, $visited);
    }

    /**
     * @param array<string, array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}> $actions
     * @param array<string, string> $objects
     * @param array{kind:string, value:string, next?:int} $value
     */
    private function addPdfNextJavaScriptActionValue(array &$actions, string $source, array $value, array $objects, int $depth, array $visited): void
    {
        if ($depth > 16) {
            return;
        }

        if ($value['kind'] === 'array') {
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $index => $item) {
                $this->addPdfNextJavaScriptActionValue($actions, $source . '[' . $index . ']', $item, $objects, $depth + 1, $visited);
            }

            return;
        }

        if ($value['kind'] === 'reference') {
            $referenceKey = $this->pdfReferenceKey($value['value']);
            if (isset($visited[$referenceKey])) {
                return;
            }

            $body = $objects[$referenceKey] ?? null;
            if ($body === null) {
                return;
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved !== null && $resolved['kind'] === 'array') {
                $visited[$referenceKey] = true;
                $this->addPdfNextJavaScriptActionValue($actions, $source, $resolved, $objects, $depth + 1, $visited);
                return;
            }
        }

        $this->addPdfJavaScriptActionFromValue($actions, $source, $value, $objects, null, $depth + 1, $visited);
    }

    /**
     * @param array<string, array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}> $actions
     * @param array<string, string> $objects
     */
    private function collectPdfAdditionalJavaScriptActions(array &$actions, string $source, string $dictionary, array $objects): void
    {
        $additionalActions = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'AA', $objects);
        if ($additionalActions === null) {
            return;
        }

        foreach (['E', 'X', 'D', 'U', 'Fo', 'Bl', 'PO', 'PC', 'PV', 'PI', 'O', 'C', 'K', 'F', 'V', 'WC', 'WS', 'DS', 'WP', 'DP'] as $trigger) {
            $this->addPdfJavaScriptActionFromNamedValue($actions, $source . '.AA.' . $trigger, $additionalActions, $trigger, $objects);
        }
    }

    /**
     * @param array<string, array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}> $actions
     * @param array<string, string> $objects
     */
    private function collectPdfNamedJavaScriptActionMetadata(array &$actions, string $catalog, array $objects): void
    {
        $names = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Names', $objects);
        if ($names === null) {
            return;
        }

        $javaScript = $this->extractPdfDictionaryOrReferenceValue($names, 'JavaScript', $objects);
        if ($javaScript === null) {
            return;
        }

        $visited = [];
        $this->collectPdfJavaScriptNameTreeActionMetadata(
            $actions,
            'catalog.Names.JavaScript',
            $javaScript,
            $objects,
            $visited,
            0
        );
    }

    /**
     * @param array<string, array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}> $actions
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfJavaScriptNameTreeActionMetadata(
        array &$actions,
        string $source,
        string $dictionary,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array !== null) {
            $values = $this->pdfTopLevelArrayValues($array);
            $count = count($values);
            for ($index = 0; $index + 1 < $count; $index += 2) {
                $name = $values[$index];
                $action = $values[$index + 1];
                if (!in_array($name['kind'], ['literal', 'hex', 'name'], true)) {
                    continue;
                }

                $nameValue = trim($name['value']);
                $actionSource = $source . ($nameValue === '' ? '' : '.' . $this->pdfActionSourceToken($nameValue));
                $this->addPdfJavaScriptActionFromValue(
                    $actions,
                    $actionSource,
                    $action,
                    $objects,
                    $nameValue === '' ? null : $nameValue
                );
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            $kidKey = $this->pdfReferenceKey($kidReference);
            if (isset($visited[$kidKey]) || !isset($objects[$kidKey])) {
                continue;
            }

            $visited[$kidKey] = true;
            $this->collectPdfJavaScriptNameTreeActionMetadata(
                $actions,
                $source . '.Kids.' . $kidKey . ' R',
                $objects[$kidKey],
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}|null
     */
    private function summarizePdfJavaScriptActionDictionary(string $dictionary, string $source, array $objects, ?string $nameHint = null): ?array
    {
        if ($this->extractPdfNameToken($dictionary, 'S') !== 'JavaScript') {
            return null;
        }

        $script = $this->extractPdfJavaScriptActionBytes($dictionary, $objects);

        return [
            'source' => $source,
            'target' => $this->pdfActiveActionTarget($dictionary, 'JavaScript', $objects, $nameHint),
            'scriptBytes' => $script === null ? null : strlen($script),
            'scriptSha256' => $script === null ? null : hash('sha256', $script),
            'tokenFlags' => $script === null ? [] : $this->pdfJavaScriptActionTokenFlags($script),
            'urlCount' => $script === null ? 0 : $this->countPdfJavaScriptUrls($script),
            'submitFormCount' => $script === null ? 0 : $this->countPdfJavaScriptSubmitForms($script),
        ];
    }

    /**
     * @param list<array{source:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null, tokenFlags:list<string>, urlCount:int, submitFormCount:int}> $actions
     * @return array{reviewStatus:string, scriptCount:int, sourceCount:int, sourceCategories:array<string, int>, tokenCounts:array<string, int>, totalScriptBytes:int, maxScriptBytes:int|null, urlCount:int, submitFormCount:int, missingScriptCount:int, issues:list<string>}|array{}
     */
    private function summarizePdfJavaScriptActionPolicy(array $actions): array
    {
        if ($actions === []) {
            return [];
        }

        $sources = [];
        $sourceCategories = [];
        $tokenCounts = [];
        $totalScriptBytes = 0;
        $maxScriptBytes = null;
        $urlCount = 0;
        $submitFormCount = 0;
        $missingScriptCount = 0;
        $issues = ['script-action'];

        foreach ($actions as $action) {
            $source = is_string($action['source'] ?? null) ? $action['source'] : '';
            if ($source !== '') {
                $sources[$source] = true;
                $sourceCategory = $this->pdfActionSourceCategory($source);
                $sourceCategories[$sourceCategory] = ($sourceCategories[$sourceCategory] ?? 0) + 1;
            }

            if (is_int($action['scriptBytes'] ?? null)) {
                $totalScriptBytes += $action['scriptBytes'];
                $maxScriptBytes = $maxScriptBytes === null ? $action['scriptBytes'] : max($maxScriptBytes, $action['scriptBytes']);
            } else {
                $missingScriptCount++;
                $issues[] = 'missing-javascript-source';
            }

            $urlCount += is_int($action['urlCount'] ?? null) ? $action['urlCount'] : 0;
            $submitFormCount += is_int($action['submitFormCount'] ?? null) ? $action['submitFormCount'] : 0;

            foreach (($action['tokenFlags'] ?? []) as $tokenFlag) {
                if (!is_string($tokenFlag) || $tokenFlag === '') {
                    continue;
                }
                $tokenCounts[$tokenFlag] = ($tokenCounts[$tokenFlag] ?? 0) + 1;
                $issues[] = 'javascript-' . $tokenFlag;
            }
        }

        if ($urlCount > 0) {
            $issues[] = 'javascript-url-literal';
        }
        if ($submitFormCount > 0) {
            $issues[] = 'javascript-submit-form';
        }

        ksort($sourceCategories);
        ksort($tokenCounts);
        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        return [
            'reviewStatus' => 'review',
            'scriptCount' => count($actions),
            'sourceCount' => count($sources),
            'sourceCategories' => $sourceCategories,
            'tokenCounts' => $tokenCounts,
            'totalScriptBytes' => $totalScriptBytes,
            'maxScriptBytes' => $maxScriptBytes,
            'urlCount' => $urlCount,
            'submitFormCount' => $submitFormCount,
            'missingScriptCount' => $missingScriptCount,
            'issues' => $issues,
        ];
    }

    private function pdfActionSourceCategory(string $source): string
    {
        if (str_contains($source, ':')) {
            $category = substr($source, 0, (int) strpos($source, ':'));
        } elseif (str_contains($source, '.')) {
            $category = substr($source, 0, (int) strpos($source, '.'));
        } else {
            $category = $source;
        }

        return $category === '' ? 'unknown' : $category;
    }

    /**
     * @return list<string>
     */
    private function pdfJavaScriptActionTokenFlags(string $script): array
    {
        $tokens = [];
        foreach ($this->pdfJavaScriptActionTokenPatterns() as $token => $pattern) {
            if (preg_match($pattern, $script) === 1) {
                $tokens[] = $token;
            }
        }

        return $tokens;
    }

    /**
     * @return array<string, string>
     */
    private function pdfJavaScriptActionTokenPatterns(): array
    {
        return [
            'launch-url' => '~\b(?:app\s*\.\s*)?launchURL\s*\(~i',
            'external-open' => '~\b(?:app\s*\.\s*)?(?:openDoc|getURL)\s*\(~i',
            'submit-form' => '~\b(?:this\s*\.\s*)?submitForm\s*\(~i',
            'mail-doc' => '~\b(?:this\s*\.\s*)?mailDoc\s*\(~i',
            'import-data-object' => '~\b(?:this\s*\.\s*)?importDataObject\s*\(~i',
            'export-data-object' => '~\b(?:this\s*\.\s*)?exportDataObject\s*\(~i',
            'dynamic-eval' => '~\beval\s*\(~i',
            'timer' => '~\b(?:app\s*\.\s*)?(?:setTimeOut|setInterval)\s*\(~i',
            'field-write' => '~\bgetField\s*\([^)]*\)\s*\.\s*(?:value|defaultValue|readonly|required)\s*=~i',
        ];
    }

    private function countPdfJavaScriptUrls(string $script): int
    {
        return $this->countPdfJavaScriptPattern($script, '~\b(?:https?://|ftp://|mailto:)[^\s\'")<>]+~i');
    }

    private function countPdfJavaScriptSubmitForms(string $script): int
    {
        return $this->countPdfJavaScriptPattern($script, '~\b(?:this\s*\.\s*)?submitForm\s*\(~i');
    }

    private function countPdfJavaScriptPattern(string $script, string $pattern): int
    {
        $count = preg_match_all($pattern, $script, $matches);

        return $count === false ? 0 : $count;
    }

    /**
     * @param array<string, string> $objects
     */
    private function extractPdfJavaScriptActionBytes(string $dictionary, array $objects): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, 'JS');
        if ($value === null) {
            return null;
        }

        if ($value['kind'] === 'literal' || $value['kind'] === 'hex' || $value['kind'] === 'name') {
            return $value['value'];
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return null;
            }

            return $this->extractPdfStreamBytes($body) ?? $this->extractPdfStringOrNameValue($body, 'JS');
        }

        if ($value['kind'] === 'dictionary') {
            return $this->extractPdfStreamBytes($value['value']) ?? $this->extractPdfStringOrNameValue($value['value'], 'JS');
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     */
    private function pdfActiveActionTarget(string $dictionary, string $type, array $objects, ?string $nameHint): ?string
    {
        if ($type === 'JavaScript') {
            return $nameHint;
        }
        if ($type === 'Named') {
            return $this->extractPdfStringOrNameValue($dictionary, 'N');
        }
        if ($type === 'Launch') {
            return $this->pdfLaunchActionTarget($dictionary, $objects);
        }
        if ($type === 'URI') {
            $uris = $this->extractPdfNamedStrings($dictionary, 'URI');

            return $uris === [] ? null : trim($uris[0]);
        }
        if (in_array($type, ['SubmitForm', 'GoToR', 'ImportData'], true)) {
            return $this->extractPdfStringOrNameValue($dictionary, 'F');
        }
        if ($type === 'GoToE') {
            return $this->pdfEmbeddedGoToActionTarget($dictionary, $objects);
        }
        if ($type === 'Hide') {
            return $this->extractPdfStringOrNameValue($dictionary, 'T');
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     */
    private function pdfLaunchActionTarget(string $dictionary, array $objects = []): ?string
    {
        $platformTargets = [];
        foreach (['Win', 'Unix', 'Mac'] as $platform) {
            $platformDictionary = $this->pdfDictionaryValueForName($dictionary, $platform, $objects);
            if ($platformDictionary === null) {
                continue;
            }

            $target = $this->pdfLaunchPlatformTarget($platform, $platformDictionary, $objects);
            if ($target !== null && $target !== '') {
                $platformTargets[] = $target;
            }
        }

        if ($platformTargets !== []) {
            return implode('|', $platformTargets);
        }

        return $this->pdfLaunchFileTargetFromValue($this->extractPdfValueForName($dictionary, 'F'), $objects);
    }

    /**
     * @param array<string, string> $objects
     */
    private function pdfDictionaryValueForName(string $dictionary, string $name, array $objects): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return null;
        }

        return $this->pdfDictionaryFromValue($value, $objects);
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     */
    private function pdfDictionaryFromValue(array $value, array $objects, int $depth = 0): ?string
    {
        if ($depth > 8) {
            return null;
        }

        if ($value['kind'] === 'dictionary') {
            return $value['value'];
        }

        if ($value['kind'] !== 'reference') {
            return null;
        }

        $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        if ($body === null) {
            return null;
        }

        $resolved = $this->parsePdfValueAt($body, 0);
        if ($resolved === null) {
            return str_starts_with(ltrim($body), '<<') ? $body : null;
        }

        return $this->pdfDictionaryFromValue($resolved, $objects, $depth + 1);
    }

    /**
     * @param array<string, string> $objects
     */
    private function pdfLaunchPlatformTarget(string $platform, string $dictionary, array $objects): ?string
    {
        $components = [];
        foreach (['F', 'D', 'O', 'P'] as $key) {
            $value = $key === 'F'
                ? $this->pdfLaunchFileTargetFromValue($this->extractPdfValueForName($dictionary, $key), $objects)
                : $this->pdfScalarTargetFromValue($this->extractPdfValueForName($dictionary, $key), $objects);
            if ($value === null || trim($value) === '') {
                continue;
            }

            $components[] = $key . '=' . $this->normalizePdfActionTargetComponent($value);
        }

        return $components === [] ? null : $platform . ':' . implode(';', $components);
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     */
    private function pdfLaunchFileTargetFromValue(?array $value, array $objects, int $depth = 0): ?string
    {
        if ($value === null || $depth > 8) {
            return null;
        }

        if (in_array($value['kind'], ['literal', 'hex', 'name', 'number'], true)) {
            $target = trim($value['value']);

            return $target === '' ? null : $target;
        }

        if ($value['kind'] === 'dictionary') {
            $target = $this->extractPdfStringOrNameValue($value['value'], 'UF')
                ?? $this->extractPdfStringOrNameValue($value['value'], 'F');
            $target = $target === null ? null : trim($target);

            return $target === '' ? null : $target;
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return null;
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved === null) {
                return null;
            }

            return $this->pdfLaunchFileTargetFromValue($resolved, $objects, $depth + 1);
        }

        return null;
    }

    /**
     * @param array{kind:string, value:string, next:int}|null $value
     * @param array<string, string> $objects
     */
    private function pdfScalarTargetFromValue(?array $value, array $objects, int $depth = 0): ?string
    {
        if ($value === null || $depth > 8) {
            return null;
        }

        if (in_array($value['kind'], ['literal', 'hex', 'name', 'number', 'keyword'], true)) {
            $target = trim($value['value']);

            return $target === '' ? null : $target;
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return null;
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved === null) {
                return null;
            }

            return $this->pdfScalarTargetFromValue($resolved, $objects, $depth + 1);
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     */
    private function pdfEmbeddedGoToActionTarget(string $dictionary, array $objects): ?string
    {
        $components = [];
        $file = $this->pdfLaunchFileTargetFromValue($this->extractPdfValueForName($dictionary, 'F'), $objects);
        if ($file !== null && $file !== '') {
            $components[] = 'F=' . $this->normalizePdfActionTargetComponent($file);
        }

        $targetDictionary = $this->pdfDictionaryValueForName($dictionary, 'T', $objects);
        if ($targetDictionary !== null) {
            $target = $this->pdfEmbeddedGoToTargetDictionaryTarget($targetDictionary, $objects);
            if ($target !== null && $target !== '') {
                $components[] = 'T=' . $target;
            }
        }

        $destination = $this->pdfEmbeddedGoToDestinationTarget($this->extractPdfValueForName($dictionary, 'D'), $objects);
        if ($destination !== null && $destination !== '') {
            $components[] = 'D=' . $destination;
        }

        return $components === [] ? null : implode(';', $components);
    }

    /**
     * @param array<string, string> $objects
     */
    private function pdfEmbeddedGoToTargetDictionaryTarget(string $dictionary, array $objects): ?string
    {
        $components = [];
        $relation = $this->extractPdfNameToken($dictionary, 'R');
        if ($relation !== null && $relation !== '') {
            $components[] = 'R=' . $this->normalizePdfActionTargetComponent($relation);
        }

        foreach (['N', 'P', 'A'] as $key) {
            $target = $this->pdfScalarTargetFromValue($this->extractPdfValueForName($dictionary, $key), $objects);
            if ($target !== null && $target !== '') {
                $components[] = $key . '=' . $this->normalizePdfActionTargetComponent($target);
            }
        }

        $childDictionary = $this->pdfDictionaryValueForName($dictionary, 'T', $objects);
        if ($childDictionary !== null) {
            $target = $this->pdfEmbeddedGoToTargetDictionaryTarget($childDictionary, $objects);
            if ($target !== null && $target !== '') {
                $components[] = 'T=' . $target;
            }
        }

        return $components === [] ? null : implode(',', $components);
    }

    /**
     * @param array{kind:string, value:string, next:int}|null $value
     * @param array<string, string> $objects
     */
    private function pdfEmbeddedGoToDestinationTarget(?array $value, array $objects): ?string
    {
        if ($value === null) {
            return null;
        }

        $destination = $this->summarizePdfNamedDestinationValue($value, $objects);
        if ($destination === null) {
            return null;
        }

        $components = [];
        foreach (['target', 'pageObject', 'fit'] as $key) {
            if (is_string($destination[$key] ?? null) && $destination[$key] !== '') {
                $components[] = $key . '=' . $this->normalizePdfActionTargetComponent($destination[$key]);
            }
        }

        return $components === [] ? null : implode(',', $components);
    }

    private function normalizePdfActionTargetComponent(string $value): string
    {
        $value = preg_replace('/\s+/u', ' ', trim($value)) ?? trim($value);

        return str_replace(['|', ';'], ['/', ','], $value);
    }

    private function pdfActionSourceToken(string $value): string
    {
        $token = preg_replace('/[^A-Za-z0-9_.:-]+/', '-', trim($value)) ?? '';
        $token = trim($token, '-');

        return $token === '' ? 'unnamed' : $token;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, annotationObject:string|null, rect:list<float>|null, contents:string|null, contentObject:string|null, settingsObject:string|null, assetNames:list<string>, activationCondition:string|null, deactivationCondition:string|null, presentationStyle:string|null, presentationTransparent:bool|null, presentationToolbar:bool|null, presentationNavigationPane:bool|null, presentationPassContextClick:bool|null, configurations:list<array{object:string|null, subtype:string|null, name:string|null, instanceCount:int, assetReferences:list<string>, assetNames:list<string>}>}>
     */
    private function extractPdfRichMediaAnnotations(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $annotations = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfRichMediaAnnotationsFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $annotations,
                $pageNumber,
                0
            );
        }

        if ($annotations === []) {
            foreach ($objects as $reference => $body) {
                $summary = $this->summarizePdfRichMediaAnnotation($body, $reference . ' R', null, null, $objects);
                if ($summary !== null) {
                    $annotations[] = $summary;
                }
            }
        }

        usort(
            $annotations,
            fn (array $left, array $right): int => [$left['page'], $this->pdfReferenceSortKey($left['annotationObject'] ?? '')]
                <=> [$right['page'], $this->pdfReferenceSortKey($right['annotationObject'] ?? '')]
        );

        return $annotations;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, rect:list<float>|null, contents:string|null, contentObject:string|null, settingsObject:string|null, assetNames:list<string>, activationCondition:string|null, deactivationCondition:string|null, presentationStyle:string|null, presentationTransparent:bool|null, presentationToolbar:bool|null, presentationNavigationPane:bool|null, presentationPassContextClick:bool|null, configurations:list<array{object:string|null, subtype:string|null, name:string|null, instanceCount:int, assetReferences:list<string>, assetNames:list<string>}>}> $annotations
     */
    private function collectPdfRichMediaAnnotationsFromPageTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$annotations,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $this->collectPdfRichMediaAnnotationsFromPage($body, $reference, $pageNumber, $objects, $annotations);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfRichMediaAnnotationsFromPageTree(
                $objects,
                $this->pdfReferenceKey($kidReference),
                $visited,
                $annotations,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, rect:list<float>|null, contents:string|null, contentObject:string|null, settingsObject:string|null, assetNames:list<string>, activationCondition:string|null, deactivationCondition:string|null, presentationStyle:string|null, presentationTransparent:bool|null, presentationToolbar:bool|null, presentationNavigationPane:bool|null, presentationPassContextClick:bool|null, configurations:list<array{object:string|null, subtype:string|null, name:string|null, instanceCount:int, assetReferences:list<string>, assetNames:list<string>}>}> $annotations
     */
    private function collectPdfRichMediaAnnotationsFromPage(
        string $pageDictionary,
        string $pageReference,
        int $pageNumber,
        array $objects,
        array &$annotations
    ): void {
        $array = $this->extractPdfArrayOrReferenceValue($pageDictionary, 'Annots', $objects);
        if ($array === null) {
            return;
        }

        foreach ($this->pdfTopLevelArrayValues($array) as $value) {
            if (!in_array($value['kind'], ['reference', 'dictionary'], true)) {
                continue;
            }

            $summary = $this->summarizePdfRichMediaAnnotationValue(
                $value,
                $objects,
                $pageNumber,
                $pageReference . ' R'
            );
            if ($summary !== null) {
                $annotations[] = $summary;
            }
        }
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, annotationObject:string|null, rect:list<float>|null, contents:string|null, contentObject:string|null, settingsObject:string|null, assetNames:list<string>, activationCondition:string|null, deactivationCondition:string|null, presentationStyle:string|null, presentationTransparent:bool|null, presentationToolbar:bool|null, presentationNavigationPane:bool|null, presentationPassContextClick:bool|null, configurations:list<array{object:string|null, subtype:string|null, name:string|null, instanceCount:int, assetReferences:list<string>, assetNames:list<string>}>}|null
     */
    private function summarizePdfRichMediaAnnotationValue(array $value, array $objects, int $pageNumber, string $pageReference): ?array
    {
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $dictionary = $objects[$reference] ?? null;

            return $dictionary === null
                ? null
                : $this->summarizePdfRichMediaAnnotation($dictionary, $reference . ' R', $pageNumber, $pageReference, $objects);
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfRichMediaAnnotation($value['value'], 'inline', $pageNumber, $pageReference, $objects);
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, annotationObject:string|null, rect:list<float>|null, contents:string|null, contentObject:string|null, settingsObject:string|null, assetNames:list<string>, activationCondition:string|null, deactivationCondition:string|null, presentationStyle:string|null, presentationTransparent:bool|null, presentationToolbar:bool|null, presentationNavigationPane:bool|null, presentationPassContextClick:bool|null, configurations:list<array{object:string|null, subtype:string|null, name:string|null, instanceCount:int, assetReferences:list<string>, assetNames:list<string>}>}|null
     */
    private function summarizePdfRichMediaAnnotation(
        string $dictionary,
        ?string $annotationObject,
        ?int $pageNumber,
        ?string $pageReference,
        array $objects
    ): ?array {
        if ($this->extractPdfNameToken($dictionary, 'Subtype') !== 'RichMedia') {
            return null;
        }

        $contentValue = $this->extractPdfValueForName($dictionary, 'RichMediaContent');
        $settingsValue = $this->extractPdfValueForName($dictionary, 'RichMediaSettings');
        $contentDictionary = $this->pdfDictionaryForValue($contentValue, $objects);
        $settingsDictionary = $this->pdfDictionaryForValue($settingsValue, $objects);
        $assets = $contentDictionary === null
            ? ['names' => [], 'namesByReference' => []]
            : $this->extractPdfRichMediaAssets($contentDictionary, $objects);
        $settings = $settingsDictionary === null
            ? $this->emptyPdfRichMediaSettings()
            : $this->summarizePdfRichMediaSettings($settingsDictionary, $objects);

        return [
            'page' => $pageNumber ?? 0,
            'pageObject' => $pageReference,
            'annotationObject' => $annotationObject,
            'rect' => $this->extractPdfNumberArrayToken($dictionary, 'Rect', 4),
            'contents' => $this->extractPdfStringOrNameValue($dictionary, 'Contents'),
            'contentObject' => $this->pdfReferenceObjectForValue($contentValue),
            'settingsObject' => $this->pdfReferenceObjectForValue($settingsValue),
            'assetNames' => $assets['names'],
            'activationCondition' => $settings['activationCondition'],
            'deactivationCondition' => $settings['deactivationCondition'],
            'presentationStyle' => $settings['presentationStyle'],
            'presentationTransparent' => $settings['presentationTransparent'],
            'presentationToolbar' => $settings['presentationToolbar'],
            'presentationNavigationPane' => $settings['presentationNavigationPane'],
            'presentationPassContextClick' => $settings['presentationPassContextClick'],
            'configurations' => $contentDictionary === null
                ? []
                : $this->extractPdfRichMediaConfigurations($contentDictionary, $objects, $assets['namesByReference']),
        ];
    }

    /**
     * @param array{kind:string, value:string, next:int}|null $value
     * @param array<string, string> $objects
     */
    private function pdfDictionaryForValue(?array $value, array $objects): ?string
    {
        if ($value === null) {
            return null;
        }
        if ($value['kind'] === 'dictionary') {
            return $value['value'];
        }
        if ($value['kind'] === 'reference') {
            return $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        }

        return null;
    }

    /**
     * @param array{kind:string, value:string, next:int}|null $value
     */
    private function pdfReferenceObjectForValue(?array $value): ?string
    {
        return $value !== null && $value['kind'] === 'reference'
            ? $this->pdfReferenceKey($value['value']) . ' R'
            : null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{names:list<string>, namesByReference:array<string, string>}
     */
    private function extractPdfRichMediaAssets(string $contentDictionary, array $objects): array
    {
        $assets = $this->extractPdfDictionaryOrReferenceValue($contentDictionary, 'Assets', $objects);
        if ($assets === null) {
            return ['names' => [], 'namesByReference' => []];
        }

        $names = [];
        $namesByReference = [];
        $this->collectPdfRichMediaAssetNameTree($assets, $objects, $names, $namesByReference, 0);
        $names = array_values(array_unique($names));
        sort($names);
        ksort($namesByReference);

        return [
            'names' => $names,
            'namesByReference' => $namesByReference,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @param list<string> $names
     * @param array<string, string> $namesByReference
     */
    private function collectPdfRichMediaAssetNameTree(
        string $dictionary,
        array $objects,
        array &$names,
        array &$namesByReference,
        int $depth
    ): void {
        if ($depth > 8) {
            return;
        }

        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array !== null) {
            $values = $this->pdfTopLevelArrayValues($array);
            $count = count($values);
            for ($index = 0; $index + 1 < $count; $index += 2) {
                $name = $values[$index];
                $asset = $values[$index + 1];
                if (!in_array($name['kind'], ['literal', 'hex', 'name'], true)) {
                    continue;
                }

                $nameValue = trim($name['value']);
                if ($nameValue === '') {
                    continue;
                }

                $names[] = $nameValue;
                if ($asset['kind'] === 'reference') {
                    $namesByReference[$this->pdfReferenceKey($asset['value']) . ' R'] = $nameValue;
                }
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            $kidDictionary = $objects[$this->pdfReferenceKey($kidReference)] ?? null;
            if ($kidDictionary !== null) {
                $this->collectPdfRichMediaAssetNameTree($kidDictionary, $objects, $names, $namesByReference, $depth + 1);
            }
        }
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, string> $assetNamesByReference
     * @return list<array{object:string|null, subtype:string|null, name:string|null, instanceCount:int, assetReferences:list<string>, assetNames:list<string>}>
     */
    private function extractPdfRichMediaConfigurations(string $contentDictionary, array $objects, array $assetNamesByReference): array
    {
        $array = $this->extractPdfArrayOrReferenceValue($contentDictionary, 'Configurations', $objects);
        if ($array === null) {
            return [];
        }

        $configurations = [];
        foreach ($this->pdfTopLevelArrayValues($array) as $value) {
            if (!in_array($value['kind'], ['reference', 'dictionary'], true)) {
                continue;
            }

            $summary = $this->summarizePdfRichMediaConfiguration($value, $objects, $assetNamesByReference);
            if ($summary !== null) {
                $configurations[] = $summary;
            }
        }

        usort($configurations, static fn (array $a, array $b): int => [$a['object'] ?? '', $a['name'] ?? ''] <=> [$b['object'] ?? '', $b['name'] ?? '']);

        return $configurations;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @param array<string, string> $assetNamesByReference
     * @return array{object:string|null, subtype:string|null, name:string|null, instanceCount:int, assetReferences:list<string>, assetNames:list<string>}|null
     */
    private function summarizePdfRichMediaConfiguration(array $value, array $objects, array $assetNamesByReference): ?array
    {
        $dictionary = $this->pdfDictionaryForValue($value, $objects);
        if ($dictionary === null) {
            return null;
        }

        $instances = $this->extractPdfArrayOrReferenceValue($dictionary, 'Instances', $objects);
        $instanceCount = 0;
        $assetReferences = [];
        if ($instances !== null) {
            foreach ($this->pdfTopLevelArrayValues($instances) as $instanceValue) {
                if (!in_array($instanceValue['kind'], ['reference', 'dictionary'], true)) {
                    continue;
                }

                $instanceDictionary = $this->pdfDictionaryForValue($instanceValue, $objects);
                if ($instanceDictionary === null) {
                    continue;
                }

                $instanceCount++;
                $assetValue = $this->extractPdfValueForName($instanceDictionary, 'Asset');
                $assetReference = $this->pdfReferenceObjectForValue($assetValue);
                if ($assetReference !== null) {
                    $assetReferences[] = $assetReference;
                }
            }
        }

        $assetReferences = array_values(array_unique($assetReferences));
        sort($assetReferences);
        $assetNames = [];
        foreach ($assetReferences as $assetReference) {
            if (isset($assetNamesByReference[$assetReference])) {
                $assetNames[] = $assetNamesByReference[$assetReference];
            }
        }
        $assetNames = array_values(array_unique($assetNames));
        sort($assetNames);

        return [
            'object' => $this->pdfReferenceObjectForValue($value),
            'subtype' => $this->extractPdfNameToken($dictionary, 'Subtype'),
            'name' => $this->extractPdfStringOrNameValue($dictionary, 'Name'),
            'instanceCount' => $instanceCount,
            'assetReferences' => $assetReferences,
            'assetNames' => $assetNames,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return array{activationCondition:string|null, deactivationCondition:string|null, presentationStyle:string|null, presentationTransparent:bool|null, presentationToolbar:bool|null, presentationNavigationPane:bool|null, presentationPassContextClick:bool|null}
     */
    private function summarizePdfRichMediaSettings(string $settingsDictionary, array $objects): array
    {
        $activation = $this->extractPdfDictionaryOrReferenceValue($settingsDictionary, 'Activation', $objects);
        $deactivation = $this->extractPdfDictionaryOrReferenceValue($settingsDictionary, 'Deactivation', $objects);
        $presentation = $activation === null
            ? null
            : $this->extractPdfDictionaryOrReferenceValue($activation, 'Presentation', $objects);

        return [
            'activationCondition' => $activation === null ? null : $this->extractPdfNameToken($activation, 'Condition'),
            'deactivationCondition' => $deactivation === null ? null : $this->extractPdfNameToken($deactivation, 'Condition'),
            'presentationStyle' => $presentation === null ? null : $this->extractPdfNameToken($presentation, 'Style'),
            'presentationTransparent' => $presentation === null ? null : $this->extractPdfBooleanToken($presentation, 'Transparent'),
            'presentationToolbar' => $presentation === null ? null : $this->extractPdfBooleanToken($presentation, 'Toolbar'),
            'presentationNavigationPane' => $presentation === null ? null : $this->extractPdfBooleanToken($presentation, 'NavigationPane'),
            'presentationPassContextClick' => $presentation === null ? null : $this->extractPdfBooleanToken($presentation, 'PassContextClick'),
        ];
    }

    /**
     * @return array{activationCondition:string|null, deactivationCondition:string|null, presentationStyle:string|null, presentationTransparent:bool|null, presentationToolbar:bool|null, presentationNavigationPane:bool|null, presentationPassContextClick:bool|null}
     */
    private function emptyPdfRichMediaSettings(): array
    {
        return [
            'activationCondition' => null,
            'deactivationCondition' => null,
            'presentationStyle' => null,
            'presentationTransparent' => null,
            'presentationToolbar' => null,
            'presentationNavigationPane' => null,
            'presentationPassContextClick' => null,
        ];
    }

    /**
     * @param list<array{activationCondition:string|null}> $annotations
     * @return array<string, int>
     */
    private function summarizePdfRichMediaActivationModes(array $annotations): array
    {
        $modes = [];
        foreach ($annotations as $annotation) {
            if (!is_string($annotation['activationCondition'] ?? null) || $annotation['activationCondition'] === '') {
                continue;
            }

            $modes[$annotation['activationCondition']] = ($modes[$annotation['activationCondition']] ?? 0) + 1;
        }
        ksort($modes);

        return $modes;
    }

    /**
     * @return array<string, bool|int|string|list<int>|list<string>>
     */
    private function extractPdfViewerPreferences(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/ViewerPreferences')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $dictionary = null;
        if (preg_match('/\/ViewerPreferences\s+(\d+)\s+(\d+)\s+R\b/s', $catalog, $matches) === 1) {
            $dictionary = $objects[$matches[1] . ' ' . $matches[2]] ?? null;
        }

        if ($dictionary === null) {
            $dictionary = $this->extractPdfNestedDictionary($catalog, 'ViewerPreferences');
        }

        if ($dictionary === null) {
            return [];
        }

        $preferences = [];
        foreach (['HideToolbar', 'HideMenubar', 'HideWindowUI', 'FitWindow', 'CenterWindow', 'DisplayDocTitle', 'PickTrayByPDFSize'] as $key) {
            $value = $this->extractPdfBooleanToken($dictionary, $key);
            if ($value !== null) {
                $preferences[$key] = $value;
            }
        }

        foreach (['NonFullScreenPageMode', 'Direction', 'ViewArea', 'ViewClip', 'PrintArea', 'PrintClip', 'PrintScaling', 'Duplex'] as $key) {
            $value = $this->extractPdfNameToken($dictionary, $key);
            if ($value !== null && $value !== '') {
                $preferences[$key] = $value;
            }
        }

        foreach (['NumCopies'] as $key) {
            $value = $this->extractPdfIntegerToken($dictionary, $key);
            if ($value !== null) {
                $preferences[$key] = $value;
            }
        }

        $printPageRange = $this->extractPdfArrayOrReferenceValue($dictionary, 'PrintPageRange', $objects);
        if ($printPageRange !== null && preg_match_all('/-?\d+/', $printPageRange, $matches) > 0) {
            $preferences['PrintPageRange'] = array_map('intval', $matches[0]);
        }

        $enforceValue = $this->extractPdfValueForName($dictionary, 'Enforce');
        if ($enforceValue !== null) {
            $enforcedPreferences = $this->collectPdfNamesFromValue($enforceValue, $objects);
            if ($enforcedPreferences !== []) {
                $preferences['Enforce'] = $enforcedPreferences;
            }
        }

        return $preferences;
    }

    /**
     * @param array<string, bool|int|string|list<int>|list<string>> $preferences
     * @return array{
     *     reviewStatus:string,
     *     preferenceCount:int,
     *     uiPreferences:array<string, bool|int|string|list<int>|list<string>>,
     *     printPreferences:array<string, bool|int|string|list<int>|list<string>>,
     *     enforcedPreferences:list<string>,
     *     enforcedUiPreferences:list<string>,
     *     enforcedPrintPreferences:list<string>,
     *     printPageRangePairs:int,
     *     printPageRanges:list<array{start:int, end:int}>,
     *     issues:list<string>
     * }|array{}
     */
    private function summarizePdfViewerPreferencePolicy(array $preferences): array
    {
        if ($preferences === []) {
            return [];
        }

        $uiPreferences = [];
        foreach (['HideToolbar', 'HideMenubar', 'HideWindowUI', 'FitWindow', 'CenterWindow', 'DisplayDocTitle', 'NonFullScreenPageMode', 'Direction'] as $key) {
            if (array_key_exists($key, $preferences)) {
                $uiPreferences[$key] = $preferences[$key];
            }
        }

        $printPreferences = [];
        foreach (['PickTrayByPDFSize', 'ViewArea', 'ViewClip', 'PrintArea', 'PrintClip', 'PrintScaling', 'Duplex', 'NumCopies', 'PrintPageRange'] as $key) {
            if (array_key_exists($key, $preferences)) {
                $printPreferences[$key] = $preferences[$key];
            }
        }

        $enforcedPreferences = [];
        if (isset($preferences['Enforce']) && is_array($preferences['Enforce'])) {
            foreach ($preferences['Enforce'] as $preference) {
                if (is_string($preference) && $preference !== '' && !in_array($preference, $enforcedPreferences, true)) {
                    $enforcedPreferences[] = $preference;
                }
            }
        }

        $enforcedUiPreferences = [];
        $enforcedPrintPreferences = [];
        foreach ($enforcedPreferences as $preference) {
            if (array_key_exists($preference, $uiPreferences)) {
                $enforcedUiPreferences[] = $preference;
            }
            if (array_key_exists($preference, $printPreferences)) {
                $enforcedPrintPreferences[] = $preference;
            }
        }

        $printPageRanges = [];
        $printPageRange = isset($preferences['PrintPageRange']) && is_array($preferences['PrintPageRange'])
            ? $preferences['PrintPageRange']
            : [];
        for ($i = 0; $i + 1 < count($printPageRange); $i += 2) {
            if (is_int($printPageRange[$i]) && is_int($printPageRange[$i + 1])) {
                $printPageRanges[] = [
                    'start' => $printPageRange[$i],
                    'end' => $printPageRange[$i + 1],
                ];
            }
        }

        $issues = [];
        if ($printPageRanges !== []) {
            $issues[] = 'bounded-print-page-range';
        }
        if (isset($preferences['Duplex']) && is_string($preferences['Duplex']) && $preferences['Duplex'] !== '' && $preferences['Duplex'] !== 'Simplex') {
            $issues[] = 'duplex-printing-requested';
        }
        if ($enforcedPreferences !== []) {
            $issues[] = 'enforces-viewer-preferences';
        }
        if (($preferences['HideToolbar'] ?? false) === true || ($preferences['HideMenubar'] ?? false) === true || ($preferences['HideWindowUI'] ?? false) === true) {
            $issues[] = 'hides-viewer-ui';
        }
        if (isset($preferences['NumCopies']) && is_int($preferences['NumCopies']) && $preferences['NumCopies'] > 1) {
            $issues[] = 'multiple-print-copies';
        }
        if (isset($preferences['PrintScaling']) && is_string($preferences['PrintScaling']) && $preferences['PrintScaling'] !== '' && $preferences['PrintScaling'] !== 'AppDefault') {
            $issues[] = 'non-default-print-scaling';
        }
        if (($preferences['PickTrayByPDFSize'] ?? false) === true) {
            $issues[] = 'print-tray-by-pdf-size';
        }
        if (($preferences['Direction'] ?? null) === 'R2L') {
            $issues[] = 'right-to-left-viewer-direction';
        }
        if ($printPageRange !== [] && count($printPageRange) % 2 !== 0) {
            $issues[] = 'odd-print-page-range-bound';
        }
        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'preferenceCount' => count($preferences),
            'uiPreferences' => $uiPreferences,
            'printPreferences' => $printPreferences,
            'enforcedPreferences' => $enforcedPreferences,
            'enforcedUiPreferences' => $enforcedUiPreferences,
            'enforcedPrintPreferences' => $enforcedPrintPreferences,
            'printPageRangePairs' => count($printPageRanges),
            'printPageRanges' => $printPageRanges,
            'issues' => $issues,
        ];
    }

    private function extractPdfNeedsRendering(?string $catalog): ?bool
    {
        if ($catalog === null || !str_contains($catalog, '/NeedsRendering')) {
            return null;
        }

        return $this->extractPdfBooleanToken($catalog, 'NeedsRendering');
    }

    /**
     * @return list<array{object:string|null, type:string|null, subtype:string|null, handlerObject:string|null, handlerType:string|null, handlerName:string|null, handlerCode:string|null, handlerVersion:string|null, keys:list<string>}>
     */
    private function extractPdfCatalogRequirements(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/Requirements')) {
            return [];
        }

        $value = $this->extractPdfValueForName($catalog, 'Requirements');
        if ($value === null) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $values = $value['kind'] === 'array' ? $this->pdfTopLevelArrayValues($value['value']) : [$value];
        $requirements = [];
        foreach ($values as $item) {
            $summary = $this->summarizePdfCatalogRequirementValue($item, $objects, 0);
            if ($summary !== null) {
                $requirements[] = $summary;
            }
            if (count($requirements) >= 64) {
                break;
            }
        }

        return $requirements;
    }

    /**
     * @param list<array{object:string|null, type:string|null, subtype:string|null, handlerObject:string|null, handlerType:string|null, handlerName:string|null, handlerCode:string|null, handlerVersion:string|null, keys:list<string>}> $requirements
     * @return array{reviewStatus:string, needsRendering:bool|null, requirementCount:int, handlerCount:int, subtypeCounts:array<string, int>, rendererDependentSubtypeCount:int, rendererDependentSubtypes:list<string>, issues:list<string>}|array{}
     */
    private function summarizePdfCatalogRequirementPolicy(?bool $needsRendering, array $requirements): array
    {
        if ($needsRendering === null && $requirements === []) {
            return [];
        }

        $rendererDependentRequirementSubtypes = [
            '3D' => true,
            'EnableJavaScripts' => true,
            'Flash' => true,
            'JavaScript' => true,
            'Movie' => true,
            'RichMedia' => true,
            'Sound' => true,
        ];
        $subtypeCounts = [];
        $rendererDependentSubtypes = [];
        $handlerCount = 0;
        foreach ($requirements as $requirement) {
            $subtype = is_string($requirement['subtype'] ?? null) && $requirement['subtype'] !== ''
                ? $requirement['subtype']
                : 'unknown';
            $subtypeCounts[$subtype] = ($subtypeCounts[$subtype] ?? 0) + 1;
            if (isset($rendererDependentRequirementSubtypes[$subtype])) {
                $rendererDependentSubtypes[$subtype] = true;
            }

            foreach (['handlerObject', 'handlerType', 'handlerName', 'handlerCode', 'handlerVersion'] as $handlerKey) {
                if (is_string($requirement[$handlerKey] ?? null) && $requirement[$handlerKey] !== '') {
                    $handlerCount++;
                    break;
                }
            }
        }
        ksort($subtypeCounts);
        $rendererDependentSubtypes = array_keys($rendererDependentSubtypes);
        sort($rendererDependentSubtypes, SORT_STRING);

        $issues = [];
        if ($needsRendering === true) {
            $issues[] = 'catalog-needs-rendering';
        }
        if ($rendererDependentSubtypes !== []) {
            $issues[] = 'renderer-dependent-catalog-requirements';
        }
        sort($issues, SORT_STRING);

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'needsRendering' => $needsRendering,
            'requirementCount' => count($requirements),
            'handlerCount' => $handlerCount,
            'subtypeCounts' => $subtypeCounts,
            'rendererDependentSubtypeCount' => count($rendererDependentSubtypes),
            'rendererDependentSubtypes' => $rendererDependentSubtypes,
            'issues' => $issues,
        ];
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{object:string|null, type:string|null, subtype:string|null, handlerObject:string|null, handlerType:string|null, handlerName:string|null, handlerCode:string|null, handlerVersion:string|null, keys:list<string>}|null
     */
    private function summarizePdfCatalogRequirementValue(array $value, array $objects, int $depth): ?array
    {
        if ($depth > 8) {
            return null;
        }

        $object = null;
        $dictionary = null;
        if ($value['kind'] === 'dictionary') {
            $dictionary = $value['value'];
        } elseif ($value['kind'] === 'reference') {
            $objectKey = $this->pdfReferenceKey($value['value']);
            $object = $objectKey . ' R';
            $body = $objects[$objectKey] ?? null;
            if ($body !== null) {
                $resolved = $this->parsePdfValueAt($body, 0);
                if ($resolved !== null && $resolved['kind'] === 'dictionary') {
                    $dictionary = $resolved['value'];
                } elseif (str_starts_with(ltrim($body), '<<')) {
                    $dictionary = $body;
                }
            }
        }

        if ($dictionary === null) {
            return null;
        }

        return $this->summarizePdfCatalogRequirement($dictionary, $object, $objects, $depth + 1);
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string|null, type:string|null, subtype:string|null, handlerObject:string|null, handlerType:string|null, handlerName:string|null, handlerCode:string|null, handlerVersion:string|null, keys:list<string>}|null
     */
    private function summarizePdfCatalogRequirement(string $dictionary, ?string $object, array $objects, int $depth): ?array
    {
        $keys = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            if ($entry['key'] !== '') {
                $keys[] = $entry['key'];
            }
        }
        $keys = array_values(array_unique($keys));
        sort($keys, SORT_STRING);

        $handler = $this->resolvePdfRequirementHandlerDictionary(
            $this->extractPdfValueForName($dictionary, 'RH') ?? $this->extractPdfValueForName($dictionary, 'Handler'),
            $objects,
            $depth
        );
        $type = $this->extractPdfNameToken($dictionary, 'Type');
        $subtype = $this->extractPdfNameToken($dictionary, 'S') ?? $this->extractPdfNameToken($dictionary, 'Subtype');
        $handlerDictionary = $handler['dictionary'] ?? null;
        $summary = [
            'object' => $object,
            'type' => $type,
            'subtype' => $subtype,
            'handlerObject' => $handler['object'] ?? null,
            'handlerType' => $handlerDictionary === null ? null : $this->extractPdfNameToken($handlerDictionary, 'Type'),
            'handlerName' => $handlerDictionary === null ? null : $this->extractPdfStringOrNameValue($handlerDictionary, 'Name'),
            'handlerCode' => $handlerDictionary === null ? null : $this->extractPdfStringOrNameValue($handlerDictionary, 'C'),
            'handlerVersion' => $handlerDictionary === null
                ? null
                : ($this->extractPdfStringOrNameValue($handlerDictionary, 'V') ?? $this->extractPdfStringOrNameValue($handlerDictionary, 'Version')),
            'keys' => $keys,
        ];

        if (
            $summary['type'] === null
            && $summary['subtype'] === null
            && $summary['handlerObject'] === null
            && $summary['handlerType'] === null
            && $summary['handlerName'] === null
            && $summary['handlerCode'] === null
            && $summary['handlerVersion'] === null
            && $summary['keys'] === []
        ) {
            return null;
        }

        return $summary;
    }

    /**
     * @param array{kind:string, value:string, next:int}|null $value
     * @param array<string, string> $objects
     * @return array{object:string|null, dictionary:string}|null
     */
    private function resolvePdfRequirementHandlerDictionary(?array $value, array $objects, int $depth): ?array
    {
        if ($value === null || $depth > 8) {
            return null;
        }

        if ($value['kind'] === 'dictionary') {
            return [
                'object' => 'inline',
                'dictionary' => $value['value'],
            ];
        }

        if ($value['kind'] !== 'reference') {
            return null;
        }

        $objectKey = $this->pdfReferenceKey($value['value']);
        $body = $objects[$objectKey] ?? null;
        if ($body === null) {
            return null;
        }

        $resolved = $this->parsePdfValueAt($body, 0);
        if ($resolved === null || $resolved['kind'] !== 'dictionary') {
            return null;
        }

        return [
            'object' => $objectKey . ' R',
            'dictionary' => $resolved['value'],
        ];
    }

    /**
     * @return array{object:string|null, type:string|null, language:string|null, status:string|null, jurisdiction:string|null, attestation:string|null, attestationObject:string|null, attestationBytes:int|null, attestationSha256:string|null, attestationSkipped:string|null, associatedFiles:list<string>, keys:list<string>}|array{}
     */
    private function extractPdfLegalAttestationMetadata(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/LegalAttestation')) {
            return [];
        }

        $value = $this->extractPdfValueForName($catalog, 'LegalAttestation');
        if ($value === null) {
            return [];
        }

        return $this->summarizePdfLegalAttestationValue(
            $value,
            $this->pdfObjectBodiesByReference($pdfBytes),
            0
        );
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{object:string|null, type:string|null, language:string|null, status:string|null, jurisdiction:string|null, attestation:string|null, attestationObject:string|null, attestationBytes:int|null, attestationSha256:string|null, attestationSkipped:string|null, associatedFiles:list<string>, keys:list<string>}|array{}
     */
    private function summarizePdfLegalAttestationValue(array $value, array $objects, int $depth): array
    {
        if ($depth > 8) {
            return [];
        }

        $object = null;
        $dictionary = null;
        if ($value['kind'] === 'dictionary') {
            $object = 'inline';
            $dictionary = $value['value'];
        } elseif ($value['kind'] === 'reference') {
            $objectKey = $this->pdfReferenceKey($value['value']);
            $object = $objectKey . ' R';
            $body = $objects[$objectKey] ?? null;
            if ($body !== null) {
                $resolved = $this->parsePdfValueAt($body, 0);
                if ($resolved !== null && $resolved['kind'] === 'dictionary') {
                    $dictionary = $resolved['value'];
                } elseif (str_starts_with(ltrim($body), '<<')) {
                    $dictionary = $body;
                }
            }
        }

        if ($dictionary === null) {
            return [];
        }

        $keys = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            if ($entry['key'] !== '') {
                $keys[] = $entry['key'];
            }
        }
        $keys = array_values(array_unique($keys));
        sort($keys, SORT_STRING);

        $attestation = $this->summarizePdfLegalAttestationPayload(
            $this->extractPdfValueForName($dictionary, 'Attestation')
                ?? $this->extractPdfValueForName($dictionary, 'Statement')
                ?? $this->extractPdfValueForName($dictionary, 'Contents')
                ?? $this->extractPdfValueForName($dictionary, 'Text'),
            $objects,
            $depth + 1
        );
        $associatedFiles = array_map(
            static fn (string $reference): string => $reference . ' R',
            $this->extractPdfReferenceArray($dictionary, 'AF')
        );
        $associatedFiles = array_values(array_unique($associatedFiles));
        sort($associatedFiles, SORT_STRING);

        return [
            'object' => $object,
            'type' => $this->extractPdfNameToken($dictionary, 'Type'),
            'language' => $this->extractPdfStringOrNameValue($dictionary, 'Lang'),
            'status' => $this->extractPdfStringOrNameValue($dictionary, 'Status'),
            'jurisdiction' => $this->extractPdfStringOrNameValue($dictionary, 'Jurisdiction'),
            'attestation' => $attestation['text'],
            'attestationObject' => $attestation['object'],
            'attestationBytes' => $attestation['bytes'],
            'attestationSha256' => $attestation['sha256'],
            'attestationSkipped' => $attestation['skipped'],
            'associatedFiles' => $associatedFiles,
            'keys' => $keys,
        ];
    }

    /**
     * @param array{kind:string, value:string, next:int}|null $value
     * @param array<string, string> $objects
     * @return array{text:string|null, object:string|null, bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function summarizePdfLegalAttestationPayload(?array $value, array $objects, int $depth): array
    {
        $empty = [
            'text' => null,
            'object' => null,
            'bytes' => null,
            'sha256' => null,
            'skipped' => null,
        ];
        if ($value === null || $depth > 8) {
            return $empty;
        }

        if (in_array($value['kind'], ['literal', 'hex', 'name', 'number'], true)) {
            $text = trim($value['value']);
            $empty['text'] = $text === '' ? null : $text;

            return $empty;
        }

        if ($value['kind'] === 'dictionary') {
            $text = $this->extractPdfStringOrNameValue($value['value'], 'Statement')
                ?? $this->extractPdfStringOrNameValue($value['value'], 'Contents')
                ?? $this->extractPdfStringOrNameValue($value['value'], 'Text');
            $empty['text'] = $text === null || trim($text) === '' ? null : trim($text);

            return $empty;
        }

        if ($value['kind'] !== 'reference') {
            return $empty;
        }

        $objectKey = $this->pdfReferenceKey($value['value']);
        $summary = $empty;
        $summary['object'] = $objectKey . ' R';
        $body = $objects[$objectKey] ?? null;
        if ($body === null) {
            return $summary;
        }

        $streamBytes = $this->extractPdfStreamBytes($body);
        if ($streamBytes !== null) {
            $summary['bytes'] = strlen($streamBytes);
            if (preg_match('/\/Filter\b/s', $body) === 1) {
                $summary['skipped'] = 'filtered';

                return $summary;
            }
            if (strlen($streamBytes) > self::MAX_LEGAL_ATTESTATION_STREAM_BYTES) {
                $summary['skipped'] = 'too-large';

                return $summary;
            }

            $summary['sha256'] = hash('sha256', $streamBytes);

            return $summary;
        }

        $resolved = $this->parsePdfValueAt($body, 0);
        if ($resolved === null) {
            return $summary;
        }

        $resolvedSummary = $this->summarizePdfLegalAttestationPayload($resolved, $objects, $depth + 1);
        $summary['text'] = $resolvedSummary['text'];
        $summary['bytes'] = $resolvedSummary['bytes'];
        $summary['sha256'] = $resolvedSummary['sha256'];
        $summary['skipped'] = $resolvedSummary['skipped'];

        return $summary;
    }

    /**
     * @param array{object:string|null, type:string|null, language:string|null, status:string|null, jurisdiction:string|null, attestation:string|null, attestationObject:string|null, attestationBytes:int|null, attestationSha256:string|null, attestationSkipped:string|null, associatedFiles:list<string>, keys:list<string>}|array{} $metadata
     * @return array{reviewStatus:string, object:string|null, status:string|null, jurisdiction:string|null, hasAttestation:bool, attestationObject:string|null, attestationBytes:int|null, attestationSkipped:string|null, associatedFileCount:int, keys:list<string>, issues:list<string>}|array{}
     */
    private function summarizePdfLegalAttestationPolicy(array $metadata): array
    {
        if ($metadata === []) {
            return [];
        }

        $status = is_string($metadata['status'] ?? null) && $metadata['status'] !== ''
            ? $metadata['status']
            : null;
        $jurisdiction = is_string($metadata['jurisdiction'] ?? null) && $metadata['jurisdiction'] !== ''
            ? $metadata['jurisdiction']
            : null;
        $attestationText = is_string($metadata['attestation'] ?? null) && trim($metadata['attestation']) !== ''
            ? trim($metadata['attestation'])
            : null;
        $attestationObject = is_string($metadata['attestationObject'] ?? null) && $metadata['attestationObject'] !== ''
            ? $metadata['attestationObject']
            : null;
        $attestationBytes = is_int($metadata['attestationBytes'] ?? null)
            ? $metadata['attestationBytes']
            : null;
        $attestationSha256 = is_string($metadata['attestationSha256'] ?? null) && $metadata['attestationSha256'] !== ''
            ? $metadata['attestationSha256']
            : null;
        $attestationSkipped = is_string($metadata['attestationSkipped'] ?? null) && $metadata['attestationSkipped'] !== ''
            ? $metadata['attestationSkipped']
            : null;
        $associatedFiles = is_array($metadata['associatedFiles'] ?? null)
            ? array_values(array_filter($metadata['associatedFiles'], static fn (mixed $file): bool => is_string($file) && $file !== ''))
            : [];
        $keys = is_array($metadata['keys'] ?? null)
            ? array_values(array_filter($metadata['keys'], static fn (mixed $key): bool => is_string($key) && $key !== ''))
            : [];

        $hasAttestation = $attestationText !== null
            || $attestationObject !== null
            || $attestationBytes !== null
            || $attestationSha256 !== null;
        $issues = [];
        if ($status === null) {
            $issues[] = 'legal-attestation-missing-status';
        }
        if (!$hasAttestation) {
            $issues[] = 'legal-attestation-missing-statement';
        }
        if ($attestationSkipped !== null) {
            $issues[] = 'legal-attestation-stream-skipped';
        }
        if ($associatedFiles === []) {
            $issues[] = 'legal-attestation-missing-associated-files';
        }

        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'object' => is_string($metadata['object'] ?? null) && $metadata['object'] !== '' ? $metadata['object'] : null,
            'status' => $status,
            'jurisdiction' => $jurisdiction,
            'hasAttestation' => $hasAttestation,
            'attestationObject' => $attestationObject,
            'attestationBytes' => $attestationBytes,
            'attestationSkipped' => $attestationSkipped,
            'associatedFileCount' => count($associatedFiles),
            'keys' => $keys,
            'issues' => $issues,
        ];
    }

    private function extractPdfUriBase(string $pdfBytes, ?string $catalog): ?string
    {
        if ($catalog === null || !str_contains($catalog, '/URI')) {
            return null;
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $uriDictionary = $this->extractPdfDictionaryOrReferenceValue($catalog, 'URI', $objects);
        if ($uriDictionary === null) {
            return null;
        }

        $base = $this->extractPdfStringOrNameValue($uriDictionary, 'Base');
        if ($base === null) {
            return null;
        }

        $base = trim($base);

        return $base === '' ? null : $base;
    }

    /**
     * @return array{marked:bool|null, userProperties:bool|null, suspects:bool|null, structTreeRoot:string|null, roleMap:array<string, string>, structureChildren:int|null, parentTree:string|null, parentTreeNextKey:int|null, idTree:string|null}|array{}
     */
    private function extractPdfTaggingMetadata(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || (!str_contains($catalog, '/MarkInfo') && !str_contains($catalog, '/StructTreeRoot'))) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $markInfo = $this->extractPdfDictionaryOrReferenceValue($catalog, 'MarkInfo', $objects);
        $structTreeRootReference = $this->extractPdfReferenceToken($catalog, 'StructTreeRoot');
        $structTreeRoot = $this->extractPdfDictionaryOrReferenceValue($catalog, 'StructTreeRoot', $objects);

        if ($markInfo === null && $structTreeRootReference === null && $structTreeRoot === null) {
            return [];
        }

        $metadata = [
            'marked' => null,
            'userProperties' => null,
            'suspects' => null,
            'structTreeRoot' => $structTreeRootReference,
            'roleMap' => [],
            'structureChildren' => null,
            'parentTree' => null,
            'parentTreeNextKey' => null,
            'idTree' => null,
        ];

        if ($markInfo !== null) {
            $metadata['marked'] = $this->extractPdfBooleanToken($markInfo, 'Marked');
            $metadata['userProperties'] = $this->extractPdfBooleanToken($markInfo, 'UserProperties');
            $metadata['suspects'] = $this->extractPdfBooleanToken($markInfo, 'Suspects');
        }

        if ($structTreeRoot !== null) {
            if ($metadata['structTreeRoot'] === null) {
                $metadata['structTreeRoot'] = 'inline';
            }
            $metadata['roleMap'] = $this->extractPdfStructureRoleMap($structTreeRoot, $objects);
            $metadata['structureChildren'] = $this->countPdfStructureChildren($structTreeRoot);
            $metadata['parentTree'] = $this->extractPdfReferenceToken($structTreeRoot, 'ParentTree');
            $metadata['parentTreeNextKey'] = $this->extractPdfIntegerToken($structTreeRoot, 'ParentTreeNextKey');
            $metadata['idTree'] = $this->extractPdfReferenceToken($structTreeRoot, 'IDTree');
        }

        return $metadata;
    }

    /**
     * @return list<array{object:string|null, type:string|null, namespace:string|null, schemaObject:string|null, schemaType:string|null, roleMap:array<string, string>, keys:list<string>}>
     */
    private function extractPdfStructureNamespaces(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/StructTreeRoot')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $structTreeRoot = $this->extractPdfDictionaryOrReferenceValue($catalog, 'StructTreeRoot', $objects);
        if ($structTreeRoot === null || !str_contains($structTreeRoot, '/Namespaces')) {
            return [];
        }

        $namespaces = $this->extractPdfValueForName($structTreeRoot, 'Namespaces');
        if ($namespaces === null) {
            return [];
        }

        return $this->summarizePdfStructureNamespaceValue($namespaces, $objects, null, 0);
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return list<array{object:string|null, type:string|null, namespace:string|null, schemaObject:string|null, schemaType:string|null, roleMap:array<string, string>, keys:list<string>}>
     */
    private function summarizePdfStructureNamespaceValue(array $value, array $objects, ?string $object, int $depth): array
    {
        if ($depth > 8) {
            return [];
        }

        if ($value['kind'] === 'array') {
            $namespaces = [];
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $entry) {
                foreach ($this->summarizePdfStructureNamespaceValue($entry, $objects, null, $depth + 1) as $namespace) {
                    $namespaces[] = $namespace;
                }
            }

            return $namespaces;
        }

        if ($value['kind'] === 'reference') {
            $reference = $value['value'];
            $body = trim($objects[$this->pdfReferenceKey($reference)] ?? '');
            if ($body === '') {
                return [$this->summarizePdfStructureNamespaceDictionary('', $objects, $reference)];
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved === null) {
                return [$this->summarizePdfStructureNamespaceDictionary($body, $objects, $reference)];
            }

            return $this->summarizePdfStructureNamespaceValue($resolved, $objects, $reference, $depth + 1);
        }

        if ($value['kind'] !== 'dictionary') {
            return [];
        }

        return [$this->summarizePdfStructureNamespaceDictionary($value['value'], $objects, $object ?? 'inline')];
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string|null, type:string|null, namespace:string|null, schemaObject:string|null, schemaType:string|null, roleMap:array<string, string>, keys:list<string>}
     */
    private function summarizePdfStructureNamespaceDictionary(string $dictionary, array $objects, ?string $object): array
    {
        $keys = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            $key = trim($entry['key']);
            if ($key !== '') {
                $keys[] = $key;
            }
        }
        $keys = $this->uniqueStrings($keys);
        sort($keys, SORT_STRING);

        $schemaObject = null;
        $schemaType = null;
        $schemaValue = $this->extractPdfValueForName($dictionary, 'Schema');
        if ($schemaValue !== null) {
            if ($schemaValue['kind'] === 'reference') {
                $schemaObject = $schemaValue['value'];
                $schemaDictionary = $objects[$this->pdfReferenceKey($schemaObject)] ?? null;
                if ($schemaDictionary !== null) {
                    $schemaType = $this->extractPdfNameToken($schemaDictionary, 'Type');
                }
            } elseif ($schemaValue['kind'] === 'dictionary') {
                $schemaObject = 'inline';
                $schemaType = $this->extractPdfNameToken($schemaValue['value'], 'Type');
            }
        }

        return [
            'object' => $object,
            'type' => $this->extractPdfNameToken($dictionary, 'Type'),
            'namespace' => $this->extractPdfStringOrNameValue($dictionary, 'NS'),
            'schemaObject' => $schemaObject,
            'schemaType' => $schemaType,
            'roleMap' => $this->extractPdfStructureRoleMap($dictionary, $objects),
            'keys' => $keys,
        ];
    }

    /**
     * @return list<array{page:int, pageObject:string|null, structParents:int, source:string}>
     */
    private function extractPdfPageStructureParents(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $parents = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageStructureParentsFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $parents,
                $pageNumber,
                0
            );
        }

        if ($parents === []) {
            uksort($objects, fn (string $a, string $b): int => $this->pdfReferenceSortKey($a . ' R') <=> $this->pdfReferenceSortKey($b . ' R'));
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $summary = $this->summarizePdfPageStructureParents($body, $reference, $pageNumber);
                if ($summary !== null) {
                    $parents[] = $summary;
                }
            }
        }

        return $parents;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, structParents:int, source:string}> $parents
     */
    private function collectPdfPageStructureParentsFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$parents,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $summary = $this->summarizePdfPageStructureParents($body, $reference, $pageNumber);
            if ($summary !== null) {
                $parents[] = $summary;
            }

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageStructureParentsFromTree(
                $objects,
                $kidReference,
                $visited,
                $parents,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @return array{page:int, pageObject:string|null, structParents:int, source:string}|null
     */
    private function summarizePdfPageStructureParents(string $dictionary, ?string $reference, int $pageNumber): ?array
    {
        $structParents = $this->extractPdfIntegerToken($dictionary, 'StructParents');
        if ($structParents === null) {
            return null;
        }

        $pageObject = $reference === null ? null : $reference . ' R';

        return [
            'page' => $pageNumber,
            'pageObject' => $pageObject,
            'structParents' => $structParents,
            'source' => ($pageObject === null ? 'page' : 'page:' . $pageObject) . '.StructParents',
        ];
    }

    /**
     * @param list<array{page:int, pageObject:string|null, structParents:int, source:string}> $parents
     * @return array<int, int>
     */
    private function summarizePdfPageStructureParentIndexes(array $parents): array
    {
        $indexes = [];
        foreach ($parents as $entry) {
            if (!isset($entry['structParents']) || !is_int($entry['structParents'])) {
                continue;
            }

            $indexes[$entry['structParents']] = ($indexes[$entry['structParents']] ?? 0) + 1;
        }
        ksort($indexes, SORT_NUMERIC);

        return $indexes;
    }

    /**
     * @param array<string, string> $objects
     * @return array<string, string>
     */
    private function extractPdfStructureRoleMap(string $structTreeRoot, array $objects): array
    {
        $roleMap = $this->extractPdfDictionaryOrReferenceValue($structTreeRoot, 'RoleMap', $objects);
        if ($roleMap === null) {
            return [];
        }

        $mapped = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($roleMap) as $entry) {
            $value = $entry['value'];
            if (!in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
                continue;
            }

            $role = trim($entry['key']);
            $mapsTo = trim($value['value']);
            if ($role === '' || $mapsTo === '') {
                continue;
            }

            $mapped[$role] = $mapsTo;
        }

        ksort($mapped);

        return $mapped;
    }

    /**
     * @param list<array{object:string, type:string|null, parent:string|null, pageObject:string|null, id:string|null, alt:string|null, actualText:string|null, language:string|null, title:string|null, childCount:int|null}> $structureElements
     * @param array<string, string> $roleMap
     * @return list<array{object:string, type:string, mappedType:string, roleChain:list<string>, mappedByRoleMap:bool, standardRole:bool, cycle:bool, issues:list<string>}>
     */
    private function summarizePdfStructureRoleMapUsage(array $structureElements, array $roleMap): array
    {
        $usage = [];
        foreach ($structureElements as $element) {
            $object = is_string($element['object'] ?? null) ? trim($element['object']) : '';
            $type = is_string($element['type'] ?? null) ? trim($element['type']) : '';
            if ($object === '' || $type === '') {
                continue;
            }

            $roleChain = $this->pdfStructureRoleMapChain($type, $roleMap);
            $mappedType = $roleChain[count($roleChain) - 1] ?? $type;
            $cycle = $this->pdfStructureRoleMapChainHasCycle($roleChain);
            $standardRole = $this->isPdfStandardStructureRole($mappedType);
            $issues = [];
            if ($cycle) {
                $issues[] = 'role-map-cycle';
            } elseif (!$standardRole && count($roleChain) > 1) {
                $issues[] = 'role-map-nonstandard-terminal';
            } elseif (!$standardRole) {
                $issues[] = 'structure-role-unmapped-custom';
            }

            $usage[] = [
                'object' => $object,
                'type' => $type,
                'mappedType' => $mappedType,
                'roleChain' => $roleChain,
                'mappedByRoleMap' => count($roleChain) > 1,
                'standardRole' => $standardRole,
                'cycle' => $cycle,
                'issues' => $issues,
            ];
        }

        usort($usage, fn (array $a, array $b): int => $this->pdfReferenceSortKey($a['object']) <=> $this->pdfReferenceSortKey($b['object']));

        return $usage;
    }

    /**
     * @param array<string, string> $roleMap
     * @return list<string>
     */
    private function pdfStructureRoleMapChain(string $role, array $roleMap): array
    {
        $role = trim($role);
        if ($role === '') {
            return [];
        }

        $chain = [$role];
        $seen = [$role => true];
        $current = $role;
        for ($depth = 0; $depth < 16; $depth++) {
            $next = isset($roleMap[$current]) ? trim($roleMap[$current]) : '';
            if ($next === '' || $next === $current) {
                break;
            }

            $chain[] = $next;
            if (isset($seen[$next])) {
                break;
            }

            $seen[$next] = true;
            $current = $next;
        }

        return $chain;
    }

    /**
     * @param list<string> $roleChain
     */
    private function pdfStructureRoleMapChainHasCycle(array $roleChain): bool
    {
        $seen = [];
        foreach ($roleChain as $role) {
            if (isset($seen[$role])) {
                return true;
            }

            $seen[$role] = true;
        }

        return false;
    }

    private function isPdfStandardStructureRole(string $role): bool
    {
        static $roles = null;
        if ($roles === null) {
            $roles = array_fill_keys([
                'Document',
                'Part',
                'Art',
                'Sect',
                'Div',
                'BlockQuote',
                'Caption',
                'TOC',
                'TOCI',
                'Index',
                'NonStruct',
                'Private',
                'P',
                'H',
                'H1',
                'H2',
                'H3',
                'H4',
                'H5',
                'H6',
                'L',
                'LI',
                'Lbl',
                'LBody',
                'Table',
                'TR',
                'TH',
                'TD',
                'THead',
                'TBody',
                'TFoot',
                'Span',
                'Quote',
                'Note',
                'Reference',
                'BibEntry',
                'Code',
                'Link',
                'Annot',
                'Ruby',
                'RB',
                'RT',
                'RP',
                'Warichu',
                'WT',
                'WP',
                'Figure',
                'Formula',
                'Form',
            ], true);
        }

        return isset($roles[$role]);
    }

    /**
     * @return list<array{className:string, attributeObject:string, owner:string|null, revision:int|null, placement:string|null, writingMode:string|null, textAlign:string|null, blockAlign:string|null, inlineAlign:string|null, listNumbering:string|null, bbox:list<float>|null, rowSpan:int|null, colSpan:int|null, scope:string|null, headers:list<string>}>
     */
    private function extractPdfStructureClassMap(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/StructTreeRoot')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $structTreeRoot = $this->extractPdfDictionaryOrReferenceValue($catalog, 'StructTreeRoot', $objects);
        if ($structTreeRoot === null || !str_contains($structTreeRoot, '/ClassMap')) {
            return [];
        }

        $classMap = $this->extractPdfDictionaryOrReferenceValue($structTreeRoot, 'ClassMap', $objects);
        if ($classMap === null) {
            return [];
        }

        $classAttributes = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($classMap) as $entry) {
            $className = trim($entry['key']);
            if ($className === '') {
                continue;
            }

            foreach ($this->summarizePdfStructureAttributeValues($entry['value'], $objects, 'class:' . $className, null, 0) as $attribute) {
                $classAttributes[] = [
                    'className' => $className,
                    'attributeObject' => $attribute['attributeObject'],
                    'owner' => $attribute['owner'],
                    'revision' => $attribute['revision'],
                    'placement' => $attribute['placement'],
                    'writingMode' => $attribute['writingMode'],
                    'textAlign' => $attribute['textAlign'],
                    'blockAlign' => $attribute['blockAlign'],
                    'inlineAlign' => $attribute['inlineAlign'],
                    'listNumbering' => $attribute['listNumbering'],
                    'bbox' => $attribute['bbox'],
                    'rowSpan' => $attribute['rowSpan'],
                    'colSpan' => $attribute['colSpan'],
                    'scope' => $attribute['scope'],
                    'headers' => $attribute['headers'],
                ];
            }
        }

        usort($classAttributes, static function (array $a, array $b): int {
            return [$a['className'], $a['attributeObject'], $a['owner'] ?? ''] <=> [$b['className'], $b['attributeObject'], $b['owner'] ?? ''];
        });

        return $classAttributes;
    }

    /**
     * @return list<array{object:string, type:string|null, classNames:list<string>, missingClasses:list<string>, mappedAttributeCounts:array<string, int>}>
     */
    private function extractPdfStructureClassUsage(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $classAttributeCounts = [];
        if ($catalog !== null && str_contains($catalog, '/StructTreeRoot')) {
            $structTreeRoot = $this->extractPdfDictionaryOrReferenceValue($catalog, 'StructTreeRoot', $objects);
            if ($structTreeRoot !== null && str_contains($structTreeRoot, '/ClassMap')) {
                $classMap = $this->extractPdfDictionaryOrReferenceValue($structTreeRoot, 'ClassMap', $objects);
                if ($classMap !== null) {
                    foreach ($this->extractPdfTopLevelDictionaryEntries($classMap) as $entry) {
                        $className = trim($entry['key']);
                        if ($className === '') {
                            continue;
                        }

                        $classAttributeCounts[$className] = count(
                            $this->summarizePdfStructureAttributeValues($entry['value'], $objects, 'class:' . $className, null, 0)
                        );
                    }
                }
            }
        }

        $usage = [];
        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'Type') !== 'StructElem') {
                continue;
            }

            $classValue = $this->extractPdfValueForName($body, 'C');
            if ($classValue === null) {
                continue;
            }

            $classNames = $this->extractPdfStructureClassNames($classValue);
            if ($classNames === []) {
                continue;
            }

            $missingClasses = [];
            $mappedAttributeCounts = [];
            foreach ($classNames as $className) {
                if (array_key_exists($className, $classAttributeCounts)) {
                    $mappedAttributeCounts[$className] = $classAttributeCounts[$className];
                    continue;
                }

                $missingClasses[] = $className;
            }

            ksort($mappedAttributeCounts);
            sort($missingClasses, SORT_STRING);
            $usage[] = [
                'object' => $reference . ' R',
                'type' => $this->extractPdfNameToken($body, 'S'),
                'classNames' => $classNames,
                'missingClasses' => $missingClasses,
                'mappedAttributeCounts' => $mappedAttributeCounts,
            ];
        }

        usort($usage, fn (array $a, array $b): int => $this->pdfReferenceSortKey($a['object']) <=> $this->pdfReferenceSortKey($b['object']));

        return $usage;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @return list<string>
     */
    private function extractPdfStructureClassNames(array $value): array
    {
        $classNames = [];
        if ($value['kind'] === 'name') {
            $classNames[] = trim($value['value']);
        } elseif ($value['kind'] === 'array') {
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $entry) {
                if ($entry['kind'] !== 'name') {
                    continue;
                }

                $classNames[] = trim($entry['value']);
            }
        }

        $classNames = array_values(array_filter($classNames, static fn (string $className): bool => $className !== ''));

        return $this->uniqueStrings($classNames);
    }

    private function countPdfStructureChildren(string $structTreeRoot): ?int
    {
        $value = $this->extractPdfValueForName($structTreeRoot, 'K');
        if ($value === null) {
            return null;
        }

        if ($value['kind'] !== 'array') {
            return 1;
        }

        return $this->countPdfTopLevelArrayValues($value['value']);
    }

    /**
     * @return list<array{source:string, nodeObject:string|null, mcid:int, valueKind:string, valueObject:string|null, arrayCount:int|null, structureReferences:list<string>, missingReferences:list<string>, limits:list<int>}>
     */
    private function extractPdfStructureParentTree(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/StructTreeRoot')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $structTreeRoot = $this->extractPdfDictionaryOrReferenceValue($catalog, 'StructTreeRoot', $objects);
        if ($structTreeRoot === null || !str_contains($structTreeRoot, '/ParentTree')) {
            return [];
        }

        $parentTree = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($structTreeRoot, 'ParentTree'), $objects);
        if ($parentTree['dictionary'] === null) {
            return [];
        }

        $entries = [];
        $visited = [];
        $nodeObject = is_string($parentTree['object']) ? $parentTree['object'] : null;
        if ($nodeObject !== null && $nodeObject !== 'inline') {
            $visited[$this->pdfReferenceKey($nodeObject)] = true;
        }

        $this->collectPdfStructureParentTree(
            $entries,
            'structTreeRoot.ParentTree',
            $parentTree['dictionary'],
            $nodeObject,
            $objects,
            $visited,
            0
        );

        usort($entries, static fn (array $a, array $b): int => [$a['mcid'], $a['source'], $a['nodeObject'] ?? ''] <=> [$b['mcid'], $b['source'], $b['nodeObject'] ?? '']);

        return $entries;
    }

    /**
     * @param list<array{source:string, nodeObject:string|null, mcid:int, valueKind:string, valueObject:string|null, arrayCount:int|null, structureReferences:list<string>, missingReferences:list<string>, limits:list<int>}> $entries
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfStructureParentTree(
        array &$entries,
        string $source,
        string $dictionary,
        ?string $nodeObject,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $limits = $this->extractPdfIntegerArrayValues($dictionary, 'Limits');
        $array = $this->extractPdfArrayValue($dictionary, 'Nums');
        if ($array !== null) {
            $values = $this->pdfTopLevelArrayValues($array);
            for ($index = 0; $index + 1 < count($values); $index += 2) {
                $mcidValue = $values[$index];
                $parentValue = $values[$index + 1];
                if ($mcidValue['kind'] !== 'number') {
                    continue;
                }

                $mcid = (int) $mcidValue['value'];
                if ($mcid < 0) {
                    continue;
                }

                $entries[] = $this->summarizePdfStructureParentTreeEntry(
                    $source,
                    $nodeObject,
                    $mcid,
                    $parentValue,
                    $objects,
                    $limits
                );
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $this->collectPdfStructureParentTree(
                $entries,
                $source . '.Kids.' . $kidReference . ' R',
                $objects[$kidReference],
                $kidReference . ' R',
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @param list<int> $limits
     * @return array{source:string, nodeObject:string|null, mcid:int, valueKind:string, valueObject:string|null, arrayCount:int|null, structureReferences:list<string>, missingReferences:list<string>, limits:list<int>}
     */
    private function summarizePdfStructureParentTreeEntry(
        string $source,
        ?string $nodeObject,
        int $mcid,
        array $value,
        array $objects,
        array $limits
    ): array {
        $valueKind = $value['kind'] === 'keyword' && $value['value'] === 'null' ? 'null' : $value['kind'];
        $valueObject = $value['kind'] === 'reference' ? $this->pdfReferenceKey($value['value']) . ' R' : null;
        $structureReferences = array_map(
            fn (string $reference): string => $this->pdfReferenceKey($reference) . ' R',
            $this->collectPdfReferencesFromValue($value, $objects)
        );
        $structureReferences = $this->uniqueStrings($structureReferences);
        sort($structureReferences, SORT_STRING);

        $missingReferences = [];
        foreach ($structureReferences as $reference) {
            $key = $this->pdfReferenceKey($reference);
            if (!isset($objects[$key])) {
                $missingReferences[] = $reference;
            }
        }
        sort($missingReferences, SORT_STRING);

        return [
            'source' => $source,
            'nodeObject' => $nodeObject,
            'mcid' => $mcid,
            'valueKind' => $valueKind,
            'valueObject' => $valueObject,
            'arrayCount' => $value['kind'] === 'array' ? $this->countPdfTopLevelArrayValues($value['value']) : null,
            'structureReferences' => $structureReferences,
            'missingReferences' => $missingReferences,
            'limits' => $limits,
        ];
    }

    /**
     * @param list<array{source:string, nodeObject:string|null, mcid:int, valueKind:string, valueObject:string|null, arrayCount:int|null, structureReferences:list<string>, missingReferences:list<string>, limits:list<int>}> $parentTree
     * @param list<array{object:string, type:string|null, parent:string|null, pageObject:string|null, id:string|null, alt:string|null, actualText:string|null, language:string|null, title:string|null, childCount:int|null}> $structureElements
     * @param list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, textObjectCount:int, imagePaintCount:int, formPaintCount:int, markedContentBeginCount:int, markedContentEndCount:int, mcidValues:list<int>, propertyNames:list<string>, resourceNames:list<string>}> $pageContentStreams
     * @param list<array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, mcid:int|null, language:string|null, alt:string|null, actualText:string|null, expanded:string|null, associatedFiles:list<string>}> $markedContentProperties
     * @param list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, operator:string, type:string|null, subtype:string|null, bbox:list<float>|null, attached:list<string>, mcid:int|null, propertyName:string|null}> $markedContentArtifacts
     * @param list<array{page:int, pageObject:string|null, structParents:int, source:string}> $pageStructureParents
     * @return array<string, mixed>
     */
    private function summarizePdfStructureParentTreePolicy(
        array $parentTree,
        array $structureElements,
        array $pageContentStreams,
        array $markedContentProperties,
        array $markedContentArtifacts,
        array $pageStructureParents = []
    ): array {
        if ($parentTree === [] && $structureElements === [] && $pageContentStreams === [] && $markedContentProperties === [] && $markedContentArtifacts === [] && $pageStructureParents === []) {
            return [];
        }

        $structureObjects = [];
        foreach ($structureElements as $element) {
            if (is_string($element['object'] ?? null) && $element['object'] !== '') {
                $structureObjects[$element['object']] = true;
            }
        }

        $artifactMcids = [];
        $artifactPropertyNames = [];
        foreach ($markedContentArtifacts as $artifact) {
            if (is_int($artifact['mcid'] ?? null) && $artifact['mcid'] >= 0) {
                $artifactMcids[$artifact['mcid']] = true;
            }
            if (is_string($artifact['propertyName'] ?? null) && $artifact['propertyName'] !== '') {
                $artifactPropertyNames[$artifact['propertyName']] = true;
            }
        }

        $markedContentMcids = [];
        foreach ($pageContentStreams as $stream) {
            foreach (($stream['mcidValues'] ?? []) as $mcid) {
                if (is_int($mcid) && $mcid >= 0 && !isset($artifactMcids[$mcid])) {
                    $markedContentMcids[$mcid] = true;
                }
            }
        }
        foreach ($markedContentProperties as $property) {
            if (is_string($property['propertyName'] ?? null) && isset($artifactPropertyNames[$property['propertyName']])) {
                continue;
            }
            if (is_int($property['mcid'] ?? null) && $property['mcid'] >= 0 && !isset($artifactMcids[$property['mcid']])) {
                $markedContentMcids[$property['mcid']] = true;
            }
        }

        $pageStructParentIndexes = [];
        foreach ($pageStructureParents as $pageStructureParent) {
            if (is_int($pageStructureParent['structParents'] ?? null) && $pageStructureParent['structParents'] >= 0) {
                $pageStructParentIndexes[$pageStructureParent['structParents']] = true;
            }
        }

        if ($parentTree === [] && $structureElements === [] && $markedContentMcids === [] && $pageStructParentIndexes === []) {
            return [];
        }

        $mcidCounts = [];
        $parentMcids = [];
        $referencedObjects = [];
        $missingReferences = [];
        $nonStructureReferences = [];
        $outOfLimitMcids = [];
        foreach ($parentTree as $entry) {
            $mcid = $entry['mcid'];
            $mcidCounts[$mcid] = ($mcidCounts[$mcid] ?? 0) + 1;
            $parentMcids[$mcid] = true;

            foreach (($entry['structureReferences'] ?? []) as $reference) {
                if (!is_string($reference) || $reference === '') {
                    continue;
                }
                $referencedObjects[$reference] = true;
                if (in_array($reference, $entry['missingReferences'] ?? [], true)) {
                    $missingReferences[$reference] = true;
                    continue;
                }
                if (!isset($structureObjects[$reference])) {
                    $nonStructureReferences[$reference] = true;
                }
            }

            $limits = $entry['limits'] ?? [];
            if (count($limits) >= 2 && ($mcid < $limits[0] || $mcid > $limits[1])) {
                $outOfLimitMcids[$mcid] = true;
            }
        }

        $duplicateMcids = [];
        foreach ($mcidCounts as $mcid => $count) {
            if ($count > 1) {
                $duplicateMcids[(int) $mcid] = true;
            }
        }

        $missingMarkedContentMcids = [];
        foreach (array_keys($markedContentMcids) as $mcid) {
            if (!isset($parentMcids[(int) $mcid])) {
                $missingMarkedContentMcids[(int) $mcid] = true;
            }
        }
        $missingPageStructParentIndexes = [];
        foreach (array_keys($pageStructParentIndexes) as $index) {
            if (!isset($parentMcids[(int) $index])) {
                $missingPageStructParentIndexes[(int) $index] = true;
            }
        }

        $duplicateMcidList = $this->sortedIntegerKeys($duplicateMcids);
        $outOfLimitMcidList = $this->sortedIntegerKeys($outOfLimitMcids);
        $markedContentMcidList = $this->sortedIntegerKeys($markedContentMcids);
        $missingMarkedContentMcidList = $this->sortedIntegerKeys($missingMarkedContentMcids);
        $pageStructParentIndexList = $this->sortedIntegerKeys($pageStructParentIndexes);
        $missingPageStructParentIndexList = $this->sortedIntegerKeys($missingPageStructParentIndexes);
        $referencedObjectList = $this->sortedPdfReferenceKeys($referencedObjects);
        $missingReferenceList = $this->sortedPdfReferenceKeys($missingReferences);
        $nonStructureReferenceList = $this->sortedPdfReferenceKeys($nonStructureReferences);

        $issues = [];
        if ($duplicateMcidList !== []) {
            $issues[] = 'duplicate-parent-mcid';
        }
        if ($outOfLimitMcidList !== []) {
            $issues[] = 'parent-mcid-outside-limits';
        }
        if ($missingReferenceList !== []) {
            $issues[] = 'missing-structure-reference';
        }
        if ($nonStructureReferenceList !== []) {
            $issues[] = 'non-structure-reference';
        }
        if ($missingMarkedContentMcidList !== []) {
            $issues[] = 'marked-content-mcid-missing-parent';
        }
        if ($parentTree === [] && $markedContentMcidList !== []) {
            $issues[] = 'parent-tree-missing-for-marked-content';
        }
        if ($parentTree === [] && $pageStructParentIndexList !== []) {
            $issues[] = 'parent-tree-missing-for-page-struct-parents';
        } elseif ($missingPageStructParentIndexList !== []) {
            $issues[] = 'page-struct-parent-missing-parent-tree';
        }
        sort($issues, SORT_STRING);

        $entries = [];
        foreach ($parentTree as $entry) {
            $entryIssues = [];
            if (in_array($entry['mcid'], $duplicateMcidList, true)) {
                $entryIssues[] = 'duplicate-parent-mcid';
            }
            if (in_array($entry['mcid'], $outOfLimitMcidList, true)) {
                $entryIssues[] = 'parent-mcid-outside-limits';
            }
            if (($entry['missingReferences'] ?? []) !== []) {
                $entryIssues[] = 'missing-structure-reference';
            }
            foreach (($entry['structureReferences'] ?? []) as $reference) {
                if (is_string($reference) && in_array($reference, $nonStructureReferenceList, true)) {
                    $entryIssues[] = 'non-structure-reference';
                    break;
                }
            }
            $entryIssues = $this->uniqueStrings($entryIssues);
            sort($entryIssues, SORT_STRING);

            $entries[] = [
                'source' => $entry['source'],
                'nodeObject' => $entry['nodeObject'],
                'mcid' => $entry['mcid'],
                'valueKind' => $entry['valueKind'],
                'structureReferences' => $entry['structureReferences'],
                'missingReferences' => $entry['missingReferences'],
                'reviewStatus' => $entryIssues === [] ? 'ok' : 'review',
                'issues' => $entryIssues,
            ];
        }

        return [
            'source' => 'structure-parent-tree',
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'parentTreeEntryCount' => count($parentTree),
            'structureElementCount' => count($structureElements),
            'markedContentMcidCount' => count($markedContentMcidList),
            'referencedStructureObjects' => $referencedObjectList,
            'missingStructureReferences' => $missingReferenceList,
            'nonStructureReferences' => $nonStructureReferenceList,
            'duplicateMcids' => $duplicateMcidList,
            'outOfLimitMcids' => $outOfLimitMcidList,
            'markedContentMcids' => $markedContentMcidList,
            'missingMarkedContentMcids' => $missingMarkedContentMcidList,
            'issues' => $issues,
            'entries' => $entries,
        ] + ($pageStructParentIndexList === [] ? [] : [
            'pageStructParentIndexes' => $pageStructParentIndexList,
            'missingPageStructParentIndexes' => $missingPageStructParentIndexList,
        ]);
    }

    /**
     * @param array<int, bool> $values
     * @return list<int>
     */
    private function sortedIntegerKeys(array $values): array
    {
        $keys = array_map('intval', array_keys($values));
        sort($keys, SORT_NUMERIC);

        return $keys;
    }

    /**
     * @param array<string, bool> $values
     * @return list<string>
     */
    private function sortedPdfReferenceKeys(array $values): array
    {
        $references = array_keys($values);
        usort($references, fn (string $a, string $b): int => $this->pdfReferenceSortKey($a) <=> $this->pdfReferenceSortKey($b));

        return $references;
    }

    /**
     * @param array<string, bool> $values
     * @return list<string>
     */
    private function sortedStringKeys(array $values): array
    {
        $keys = array_keys($values);
        sort($keys, SORT_STRING);

        return $keys;
    }

    /**
     * @return list<array{source:string, nodeObject:string|null, id:string, valueKind:string, valueObject:string|null, structureReferences:list<string>, missingReferences:list<string>, limits:list<string>}>
     */
    private function extractPdfStructureIdTree(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/StructTreeRoot')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $structTreeRoot = $this->extractPdfDictionaryOrReferenceValue($catalog, 'StructTreeRoot', $objects);
        if ($structTreeRoot === null || !str_contains($structTreeRoot, '/IDTree')) {
            return [];
        }

        $idTree = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($structTreeRoot, 'IDTree'), $objects);
        if ($idTree['dictionary'] === null) {
            return [];
        }

        $entries = [];
        $visited = [];
        $nodeObject = is_string($idTree['object']) ? $idTree['object'] : null;
        if ($nodeObject !== null && $nodeObject !== 'inline') {
            $visited[$this->pdfReferenceKey($nodeObject)] = true;
        }

        $this->collectPdfStructureIdTree(
            $entries,
            'structTreeRoot.IDTree',
            $idTree['dictionary'],
            $nodeObject,
            $objects,
            $visited,
            0
        );

        usort($entries, static fn (array $a, array $b): int => [$a['id'], $a['source'], $a['nodeObject'] ?? '', $a['valueObject'] ?? ''] <=> [$b['id'], $b['source'], $b['nodeObject'] ?? '', $b['valueObject'] ?? '']);

        return $entries;
    }

    /**
     * @param list<array{source:string, nodeObject:string|null, id:string, valueKind:string, valueObject:string|null, structureReferences:list<string>, missingReferences:list<string>, limits:list<string>}> $entries
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfStructureIdTree(
        array &$entries,
        string $source,
        string $dictionary,
        ?string $nodeObject,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $limits = $this->extractPdfStringArrayValues($dictionary, 'Limits');
        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array !== null) {
            $values = $this->pdfTopLevelArrayValues($array);
            for ($index = 0; $index + 1 < count($values); $index += 2) {
                $idValue = $values[$index];
                $targetValue = $values[$index + 1];
                if (!in_array($idValue['kind'], ['literal', 'hex', 'name'], true)) {
                    continue;
                }

                $id = trim($idValue['value']);
                if ($id === '') {
                    continue;
                }

                $entries[] = $this->summarizePdfStructureIdTreeEntry(
                    $source,
                    $nodeObject,
                    $id,
                    $targetValue,
                    $objects,
                    $limits
                );
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $this->collectPdfStructureIdTree(
                $entries,
                $source . '.Kids.' . $kidReference . ' R',
                $objects[$kidReference],
                $kidReference . ' R',
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @param list<string> $limits
     * @return array{source:string, nodeObject:string|null, id:string, valueKind:string, valueObject:string|null, structureReferences:list<string>, missingReferences:list<string>, limits:list<string>}
     */
    private function summarizePdfStructureIdTreeEntry(
        string $source,
        ?string $nodeObject,
        string $id,
        array $value,
        array $objects,
        array $limits
    ): array {
        $valueKind = $value['kind'] === 'keyword' && $value['value'] === 'null' ? 'null' : $value['kind'];
        $valueObject = $value['kind'] === 'reference' ? $this->pdfReferenceKey($value['value']) . ' R' : null;
        $structureReferences = array_map(
            fn (string $reference): string => $this->pdfReferenceKey($reference) . ' R',
            $this->collectPdfReferencesFromValue($value, $objects)
        );
        $structureReferences = $this->uniqueStrings($structureReferences);
        sort($structureReferences, SORT_STRING);

        $missingReferences = [];
        foreach ($structureReferences as $reference) {
            $key = $this->pdfReferenceKey($reference);
            if (!isset($objects[$key])) {
                $missingReferences[] = $reference;
            }
        }
        sort($missingReferences, SORT_STRING);

        return [
            'source' => $source,
            'nodeObject' => $nodeObject,
            'id' => $id,
            'valueKind' => $valueKind,
            'valueObject' => $valueObject,
            'structureReferences' => $structureReferences,
            'missingReferences' => $missingReferences,
            'limits' => $limits,
        ];
    }

    /**
     * @param list<array{source:string, nodeObject:string|null, id:string, valueKind:string, valueObject:string|null, structureReferences:list<string>, missingReferences:list<string>, limits:list<string>}> $idTree
     * @param list<array{object:string, type:string|null, parent:string|null, pageObject:string|null, id:string|null, alt:string|null, actualText:string|null, language:string|null, title:string|null, childCount:int|null}> $structureElements
     * @return array<string, mixed>
     */
    private function summarizePdfStructureIdTreePolicy(array $idTree, array $structureElements): array
    {
        if ($idTree === [] && $structureElements === []) {
            return [];
        }

        $structureObjects = [];
        $structureElementIds = [];
        foreach ($structureElements as $element) {
            if (is_string($element['object'] ?? null) && $element['object'] !== '') {
                $structureObjects[$element['object']] = true;
            }
            if (is_string($element['id'] ?? null) && $element['id'] !== '') {
                $structureElementIds[$element['id']] = true;
            }
        }

        if ($idTree === [] && $structureElementIds === []) {
            return [];
        }

        $idCounts = [];
        $idTreeIds = [];
        $referencedObjects = [];
        $missingReferences = [];
        $nonStructureReferences = [];
        $outOfLimitIds = [];
        foreach ($idTree as $entry) {
            $id = $entry['id'];
            $idCounts[$id] = ($idCounts[$id] ?? 0) + 1;
            $idTreeIds[$id] = true;

            foreach (($entry['structureReferences'] ?? []) as $reference) {
                if (!is_string($reference) || $reference === '') {
                    continue;
                }
                $referencedObjects[$reference] = true;
                if (in_array($reference, $entry['missingReferences'] ?? [], true)) {
                    $missingReferences[$reference] = true;
                    continue;
                }
                if (!isset($structureObjects[$reference])) {
                    $nonStructureReferences[$reference] = true;
                }
            }

            $limits = $entry['limits'] ?? [];
            if (
                count($limits) >= 2
                && (strcmp($id, (string) $limits[0]) < 0 || strcmp($id, (string) $limits[1]) > 0)
            ) {
                $outOfLimitIds[$id] = true;
            }
        }

        $duplicateIds = [];
        foreach ($idCounts as $id => $count) {
            if ($count > 1) {
                $duplicateIds[(string) $id] = true;
            }
        }

        $missingStructureElementIds = [];
        foreach (array_keys($structureElementIds) as $id) {
            if (!isset($idTreeIds[(string) $id])) {
                $missingStructureElementIds[(string) $id] = true;
            }
        }

        $duplicateIdList = $this->sortedStringKeys($duplicateIds);
        $outOfLimitIdList = $this->sortedStringKeys($outOfLimitIds);
        $structureElementIdList = $this->sortedStringKeys($structureElementIds);
        $missingStructureElementIdList = $this->sortedStringKeys($missingStructureElementIds);
        $referencedObjectList = $this->sortedPdfReferenceKeys($referencedObjects);
        $missingReferenceList = $this->sortedPdfReferenceKeys($missingReferences);
        $nonStructureReferenceList = $this->sortedPdfReferenceKeys($nonStructureReferences);

        $issues = [];
        if ($duplicateIdList !== []) {
            $issues[] = 'duplicate-id';
        }
        if ($outOfLimitIdList !== []) {
            $issues[] = 'id-outside-limits';
        }
        if ($missingReferenceList !== []) {
            $issues[] = 'missing-structure-reference';
        }
        if ($nonStructureReferenceList !== []) {
            $issues[] = 'non-structure-reference';
        }
        if ($missingStructureElementIdList !== []) {
            $issues[] = 'structure-element-id-missing-id-tree';
        }
        if ($idTree === [] && $structureElementIdList !== []) {
            $issues[] = 'id-tree-missing-for-structure-elements';
        }
        sort($issues, SORT_STRING);

        $entries = [];
        foreach ($idTree as $entry) {
            $entryIssues = [];
            if (in_array($entry['id'], $duplicateIdList, true)) {
                $entryIssues[] = 'duplicate-id';
            }
            if (in_array($entry['id'], $outOfLimitIdList, true)) {
                $entryIssues[] = 'id-outside-limits';
            }
            if (($entry['missingReferences'] ?? []) !== []) {
                $entryIssues[] = 'missing-structure-reference';
            }
            foreach (($entry['structureReferences'] ?? []) as $reference) {
                if (is_string($reference) && in_array($reference, $nonStructureReferenceList, true)) {
                    $entryIssues[] = 'non-structure-reference';
                    break;
                }
            }
            $entryIssues = $this->uniqueStrings($entryIssues);
            sort($entryIssues, SORT_STRING);

            $entries[] = [
                'source' => $entry['source'],
                'nodeObject' => $entry['nodeObject'],
                'id' => $entry['id'],
                'valueKind' => $entry['valueKind'],
                'structureReferences' => $entry['structureReferences'],
                'missingReferences' => $entry['missingReferences'],
                'reviewStatus' => $entryIssues === [] ? 'ok' : 'review',
                'issues' => $entryIssues,
            ];
        }

        return [
            'source' => 'structure-id-tree',
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'idTreeEntryCount' => count($idTree),
            'structureElementCount' => count($structureElements),
            'structureElementIdCount' => count($structureElementIdList),
            'referencedStructureObjects' => $referencedObjectList,
            'missingStructureReferences' => $missingReferenceList,
            'nonStructureReferences' => $nonStructureReferenceList,
            'duplicateIds' => $duplicateIdList,
            'outOfLimitIds' => $outOfLimitIdList,
            'structureElementIds' => $structureElementIdList,
            'missingStructureElementIds' => $missingStructureElementIdList,
            'issues' => $issues,
            'entries' => $entries,
        ];
    }

    /**
     * @return list<int>
     */
    private function extractPdfIntegerArrayValues(string $dictionary, string $name): array
    {
        $array = $this->extractPdfArrayValue($dictionary, $name);
        if ($array === null) {
            return [];
        }

        $values = [];
        foreach ($this->pdfTopLevelArrayValues($array) as $value) {
            if ($value['kind'] === 'number') {
                $values[] = (int) $value['value'];
            }
        }

        return $values;
    }

    /**
     * @return list<string>
     */
    private function extractPdfStringArrayValues(string $dictionary, string $name): array
    {
        return $this->collectPdfStringsFromArray($this->extractPdfArrayValue($dictionary, $name));
    }

    /**
     * @return list<array{object:string, type:string|null, parent:string|null, pageObject:string|null, id:string|null, alt:string|null, actualText:string|null, language:string|null, title:string|null, childCount:int|null}>
     */
    private function extractPdfStructureElements(string $pdfBytes): array
    {
        $elements = [];
        foreach ($this->pdfObjectBodiesByReference($pdfBytes) as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'Type') !== 'StructElem') {
                continue;
            }

            $elements[] = $this->summarizePdfStructureElement($reference . ' R', $body);
        }

        usort($elements, fn (array $a, array $b): int => $this->pdfReferenceSortKey($a['object']) <=> $this->pdfReferenceSortKey($b['object']));

        return $elements;
    }

    /**
     * @return array{object:string, type:string|null, parent:string|null, pageObject:string|null, id:string|null, alt:string|null, actualText:string|null, language:string|null, title:string|null, childCount:int|null}
     */
    private function summarizePdfStructureElement(string $reference, string $dictionary): array
    {
        $children = null;
        $value = $this->extractPdfValueForName($dictionary, 'K');
        if ($value !== null) {
            $children = $value['kind'] === 'array'
                ? $this->countPdfTopLevelArrayValues($value['value'])
                : 1;
        }

        return [
            'object' => $reference,
            'type' => $this->extractPdfNameToken($dictionary, 'S'),
            'parent' => $this->extractPdfReferenceToken($dictionary, 'P'),
            'pageObject' => $this->extractPdfReferenceToken($dictionary, 'Pg'),
            'id' => $this->extractPdfStringOrNameValue($dictionary, 'ID'),
            'alt' => $this->extractPdfStringOrNameValue($dictionary, 'Alt'),
            'actualText' => $this->extractPdfStringOrNameValue($dictionary, 'ActualText'),
            'language' => $this->extractPdfStringOrNameValue($dictionary, 'Lang'),
            'title' => $this->extractPdfStringOrNameValue($dictionary, 'T'),
            'childCount' => $children,
        ];
    }

    /**
     * @return list<array{object:string, type:string|null, attributeObject:string, owner:string|null, revision:int|null, placement:string|null, writingMode:string|null, textAlign:string|null, blockAlign:string|null, inlineAlign:string|null, listNumbering:string|null, bbox:list<float>|null, rowSpan:int|null, colSpan:int|null, scope:string|null, headers:list<string>}>
     */
    private function extractPdfStructureAttributes(string $pdfBytes): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $attributes = [];
        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'Type') !== 'StructElem') {
                continue;
            }

            $value = $this->extractPdfValueForName($body, 'A');
            if ($value === null) {
                continue;
            }

            foreach ($this->summarizePdfStructureAttributeValues(
                $value,
                $objects,
                $reference . ' R',
                $this->extractPdfNameToken($body, 'S'),
                0
            ) as $attribute) {
                $attributes[] = $attribute;
            }
        }

        usort($attributes, static function (array $a, array $b): int {
            return [$a['object'], $a['attributeObject'], $a['owner'] ?? ''] <=> [$b['object'], $b['attributeObject'], $b['owner'] ?? ''];
        });

        return $attributes;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return list<array{object:string, type:string|null, attributeObject:string, owner:string|null, revision:int|null, placement:string|null, writingMode:string|null, textAlign:string|null, blockAlign:string|null, inlineAlign:string|null, listNumbering:string|null, bbox:list<float>|null, rowSpan:int|null, colSpan:int|null, scope:string|null, headers:list<string>}>
     */
    private function summarizePdfStructureAttributeValues(array $value, array $objects, string $structureObject, ?string $structureType, int $depth): array
    {
        if ($depth > 8) {
            return [];
        }

        if ($value['kind'] === 'array') {
            $attributes = [];
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $entry) {
                foreach ($this->summarizePdfStructureAttributeValues($entry, $objects, $structureObject, $structureType, $depth + 1) as $attribute) {
                    $attributes[] = $attribute;
                }
            }

            return $attributes;
        }

        if ($value['kind'] !== 'dictionary' && $value['kind'] !== 'reference') {
            return [];
        }

        $dictionary = $this->pdfDictionaryForValue($value, $objects);
        if ($dictionary === null) {
            return [];
        }

        $summary = $this->summarizePdfStructureAttributeDictionary(
            $structureObject,
            $structureType,
            $value['kind'] === 'reference' ? $this->pdfReferenceKey($value['value']) . ' R' : 'inline',
            $dictionary,
            $objects
        );

        return $summary === null ? [] : [$summary];
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string, type:string|null, attributeObject:string, owner:string|null, revision:int|null, placement:string|null, writingMode:string|null, textAlign:string|null, blockAlign:string|null, inlineAlign:string|null, listNumbering:string|null, bbox:list<float>|null, rowSpan:int|null, colSpan:int|null, scope:string|null, headers:list<string>}|null
     */
    private function summarizePdfStructureAttributeDictionary(string $structureObject, ?string $structureType, string $attributeObject, string $dictionary, array $objects): ?array
    {
        $owner = $this->extractPdfStringOrNameValue($dictionary, 'O');
        if ($owner === 'UserProperties') {
            return null;
        }

        $headers = [];
        foreach ($this->collectPdfReferencesFromValue($this->extractPdfValueForName($dictionary, 'Headers'), $objects, 0) as $reference) {
            $headers[] = $this->pdfReferenceKey($reference) . ' R';
        }

        $summary = [
            'object' => $structureObject,
            'type' => $structureType,
            'attributeObject' => $attributeObject,
            'owner' => $owner,
            'revision' => $this->extractPdfIntegerToken($dictionary, 'R'),
            'placement' => $this->extractPdfStringOrNameValue($dictionary, 'Placement'),
            'writingMode' => $this->extractPdfStringOrNameValue($dictionary, 'WritingMode'),
            'textAlign' => $this->extractPdfStringOrNameValue($dictionary, 'TextAlign'),
            'blockAlign' => $this->extractPdfStringOrNameValue($dictionary, 'BlockAlign'),
            'inlineAlign' => $this->extractPdfStringOrNameValue($dictionary, 'InlineAlign'),
            'listNumbering' => $this->extractPdfStringOrNameValue($dictionary, 'ListNumbering'),
            'bbox' => $this->extractPdfNumberArrayToken($dictionary, 'BBox', 4),
            'rowSpan' => $this->extractPdfIntegerToken($dictionary, 'RowSpan'),
            'colSpan' => $this->extractPdfIntegerToken($dictionary, 'ColSpan'),
            'scope' => $this->extractPdfStringOrNameValue($dictionary, 'Scope'),
            'headers' => $this->uniqueStrings($headers),
        ];

        foreach (['owner', 'revision', 'placement', 'writingMode', 'textAlign', 'blockAlign', 'inlineAlign', 'listNumbering', 'bbox', 'rowSpan', 'colSpan', 'scope'] as $key) {
            if ($summary[$key] !== null) {
                return $summary;
            }
        }
        if ($summary['headers'] !== []) {
            return $summary;
        }

        return null;
    }

    /**
     * @return list<array{object:string, type:string|null, attributeObject:string, propertyName:string, value:string|int|float|bool|null, valueType:string, formatted:string|null, hidden:bool|null}>
     */
    private function extractPdfStructureUserProperties(string $pdfBytes): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $properties = [];
        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'Type') !== 'StructElem') {
                continue;
            }

            $value = $this->extractPdfValueForName($body, 'A');
            if ($value === null) {
                continue;
            }

            foreach ($this->summarizePdfStructureUserPropertyAttributeValues(
                $value,
                $objects,
                $reference . ' R',
                $this->extractPdfNameToken($body, 'S'),
                0
            ) as $property) {
                $properties[] = $property;
            }
        }

        usort($properties, static function (array $a, array $b): int {
            return [$a['object'], $a['attributeObject'], $a['propertyName']] <=> [$b['object'], $b['attributeObject'], $b['propertyName']];
        });

        return $properties;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return list<array{object:string, type:string|null, attributeObject:string, propertyName:string, value:string|int|float|bool|null, valueType:string, formatted:string|null, hidden:bool|null}>
     */
    private function summarizePdfStructureUserPropertyAttributeValues(array $value, array $objects, string $structureObject, ?string $structureType, int $depth): array
    {
        if ($depth > 8) {
            return [];
        }

        if ($value['kind'] === 'array') {
            $properties = [];
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $entry) {
                foreach ($this->summarizePdfStructureUserPropertyAttributeValues($entry, $objects, $structureObject, $structureType, $depth + 1) as $property) {
                    $properties[] = $property;
                }
            }

            return $properties;
        }

        if ($value['kind'] !== 'dictionary' && $value['kind'] !== 'reference') {
            return [];
        }

        $dictionary = $this->pdfDictionaryForValue($value, $objects);
        if ($dictionary === null || $this->extractPdfStringOrNameValue($dictionary, 'O') !== 'UserProperties') {
            return [];
        }

        $propertyValue = $this->extractPdfValueForName($dictionary, 'P');
        if ($propertyValue === null) {
            return [];
        }

        return $this->summarizePdfStructureUserPropertyValues(
            $propertyValue,
            $objects,
            $structureObject,
            $structureType,
            $value['kind'] === 'reference' ? $this->pdfReferenceKey($value['value']) . ' R' : 'inline',
            0
        );
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return list<array{object:string, type:string|null, attributeObject:string, propertyName:string, value:string|int|float|bool|null, valueType:string, formatted:string|null, hidden:bool|null}>
     */
    private function summarizePdfStructureUserPropertyValues(array $value, array $objects, string $structureObject, ?string $structureType, string $attributeObject, int $depth): array
    {
        if ($depth > 8) {
            return [];
        }

        if ($value['kind'] === 'reference') {
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return [];
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved === null) {
                return [];
            }

            return $this->summarizePdfStructureUserPropertyValues($resolved, $objects, $structureObject, $structureType, $attributeObject, $depth + 1);
        }

        if ($value['kind'] === 'array') {
            $properties = [];
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $entry) {
                foreach ($this->summarizePdfStructureUserPropertyValues($entry, $objects, $structureObject, $structureType, $attributeObject, $depth + 1) as $property) {
                    $properties[] = $property;
                }
            }

            return $properties;
        }

        if ($value['kind'] !== 'dictionary') {
            return [];
        }

        $name = $this->extractPdfStringOrNameValue($value['value'], 'N');
        if ($name === null || trim($name) === '') {
            return [];
        }

        $propertyValue = $this->summarizePdfFileSpecCollectionItemValue(
            $this->extractPdfValueForName($value['value'], 'V') ?? ['kind' => 'keyword', 'value' => 'null', 'next' => 0],
            $objects,
            0
        ) ?? ['value' => null, 'valueType' => 'null'];

        return [[
            'object' => $structureObject,
            'type' => $structureType,
            'attributeObject' => $attributeObject,
            'propertyName' => trim($name),
            'value' => $propertyValue['value'],
            'valueType' => $propertyValue['valueType'],
            'formatted' => $this->extractPdfStringOrNameValue($value['value'], 'F'),
            'hidden' => $this->extractPdfBooleanToken($value['value'], 'H'),
        ]];
    }

    /**
     * @return list<array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, mcid:int|null, language:string|null, alt:string|null, actualText:string|null, expanded:string|null, associatedFiles:list<string>}>
     */
    private function extractPdfMarkedContentProperties(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $properties = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfMarkedContentPropertiesFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                $visited,
                $properties,
                $pageNumber,
                0
            );
        }

        if ($properties === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageProperties = $this->summarizePdfPageMarkedContentProperties($body, $reference, null, $objects);
                foreach ($pageProperties as &$property) {
                    $property['page'] = $pageNumber;
                }
                unset($property);
                array_push($properties, ...$pageProperties);
            }
        }

        $properties = array_values($properties);
        usort(
            $properties,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['propertyName'],
                $a['propertyObject'] ?? '',
            ] <=> [
                $b['page'],
                $b['propertyName'],
                $b['propertyObject'] ?? '',
            ]
        );

        return $properties;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, mcid:int|null, language:string|null, alt:string|null, actualText:string|null, expanded:string|null, associatedFiles:list<string>}> $properties
     */
    private function collectPdfMarkedContentPropertiesFromPageTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        array &$visited,
        array &$properties,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $pageProperties = $this->summarizePdfPageMarkedContentProperties($body, $reference, $ownResources === null ? $inheritedResources : null, $objects);
            foreach ($pageProperties as &$property) {
                $property['page'] = $pageNumber;
            }
            unset($property);
            array_push($properties, ...$pageProperties);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfMarkedContentPropertiesFromPageTree(
                $objects,
                $kidReference,
                $resources,
                $visited,
                $properties,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, mcid:int|null, language:string|null, alt:string|null, actualText:string|null, expanded:string|null, associatedFiles:list<string>}>
     */
    private function summarizePdfPageMarkedContentProperties(string $pageDictionary, string $pageReference, ?string $inheritedResources, array $objects): array
    {
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        if ($resources === null) {
            return [];
        }

        $propertyDictionary = $this->extractPdfDictionaryOrReferenceValue($resources, 'Properties', $objects);
        if ($propertyDictionary === null) {
            return [];
        }

        $properties = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($propertyDictionary) as $entry) {
            $property = $this->summarizePdfMarkedContentProperty(
                $entry['key'],
                $entry['value'],
                $objects,
                $pageReference,
                $ownResources === null
            );
            if ($property !== null) {
                $properties[] = $property;
            }
        }

        return $properties;
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, mcid:int|null, language:string|null, alt:string|null, actualText:string|null, expanded:string|null, associatedFiles:list<string>}|null
     */
    private function summarizePdfMarkedContentProperty(string $propertyName, array $value, array $objects, string $pageReference, bool $inherited): ?array
    {
        $dictionary = null;
        $propertyObject = null;
        if ($value['kind'] === 'reference') {
            $propertyObject = $value['value'];
            $dictionary = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        } elseif ($value['kind'] === 'dictionary') {
            $propertyObject = 'inline';
            $dictionary = $value['value'];
        }

        if ($dictionary === null) {
            return null;
        }
        if ($this->extractPdfNameToken($dictionary, 'Type') === 'OCMD') {
            return null;
        }

        $associatedFiles = [];
        foreach ($this->extractPdfReferenceArray($dictionary, 'AF') as $reference) {
            $associatedFiles[] = $reference . ' R';
        }

        return [
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'propertyName' => $propertyName,
            'propertyObject' => $propertyObject,
            'inherited' => $inherited,
            'mcid' => $this->extractPdfIntegerToken($dictionary, 'MCID'),
            'language' => $this->extractPdfStringOrNameValue($dictionary, 'Lang'),
            'alt' => $this->extractPdfStringOrNameValue($dictionary, 'Alt'),
            'actualText' => $this->extractPdfStringOrNameValue($dictionary, 'ActualText'),
            'expanded' => $this->extractPdfStringOrNameValue($dictionary, 'E'),
            'associatedFiles' => $associatedFiles,
        ];
    }

    /**
     * @return list<array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, type:string|null, groups:list<string>, policy:string|null, visibilityExpressionOperators:list<string>, visibilityExpressionGroups:list<string>}>
     */
    private function extractPdfOptionalContentMemberships(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $memberships = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfOptionalContentMembershipsFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                $visited,
                $memberships,
                $pageNumber,
                0
            );
        }

        if ($memberships === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageMemberships = $this->summarizePdfPageOptionalContentMemberships($body, $reference, null, $objects);
                foreach ($pageMemberships as &$membership) {
                    $membership['page'] = $pageNumber;
                }
                unset($membership);
                array_push($memberships, ...$pageMemberships);
            }
        }

        $memberships = array_values($memberships);
        usort(
            $memberships,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['propertyName'],
                $a['propertyObject'] ?? '',
            ] <=> [
                $b['page'],
                $b['propertyName'],
                $b['propertyObject'] ?? '',
            ]
        );

        return $memberships;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, type:string|null, groups:list<string>, policy:string|null, visibilityExpressionOperators:list<string>, visibilityExpressionGroups:list<string>}> $memberships
     */
    private function collectPdfOptionalContentMembershipsFromPageTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        array &$visited,
        array &$memberships,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $pageMemberships = $this->summarizePdfPageOptionalContentMemberships($body, $reference, $ownResources === null ? $inheritedResources : null, $objects);
            foreach ($pageMemberships as &$membership) {
                $membership['page'] = $pageNumber;
            }
            unset($membership);
            array_push($memberships, ...$pageMemberships);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfOptionalContentMembershipsFromPageTree(
                $objects,
                $kidReference,
                $resources,
                $visited,
                $memberships,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, type:string|null, groups:list<string>, policy:string|null, visibilityExpressionOperators:list<string>, visibilityExpressionGroups:list<string>}>
     */
    private function summarizePdfPageOptionalContentMemberships(string $pageDictionary, string $pageReference, ?string $inheritedResources, array $objects): array
    {
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        if ($resources === null) {
            return [];
        }

        $propertyDictionary = $this->extractPdfDictionaryOrReferenceValue($resources, 'Properties', $objects);
        if ($propertyDictionary === null) {
            return [];
        }

        $memberships = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($propertyDictionary) as $entry) {
            $membership = $this->summarizePdfOptionalContentMembership(
                $entry['key'],
                $entry['value'],
                $objects,
                $pageReference,
                $ownResources === null
            );
            if ($membership !== null) {
                $memberships[] = $membership;
            }
        }

        return $memberships;
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, propertyName:string, propertyObject:string|null, inherited:bool, type:string|null, groups:list<string>, policy:string|null, visibilityExpressionOperators:list<string>, visibilityExpressionGroups:list<string>}|null
     */
    private function summarizePdfOptionalContentMembership(string $propertyName, array $value, array $objects, string $pageReference, bool $inherited): ?array
    {
        $dictionary = null;
        $propertyObject = null;
        if ($value['kind'] === 'reference') {
            $propertyObject = $value['value'];
            $dictionary = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        } elseif ($value['kind'] === 'dictionary') {
            $propertyObject = 'inline';
            $dictionary = $value['value'];
        }

        if ($dictionary === null || $this->extractPdfNameToken($dictionary, 'Type') !== 'OCMD') {
            return null;
        }

        $visibilityExpression = $this->extractPdfValueForName($dictionary, 'VE');

        return [
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'propertyName' => $propertyName,
            'propertyObject' => $propertyObject,
            'inherited' => $inherited,
            'type' => $this->extractPdfNameToken($dictionary, 'Type'),
            'groups' => $this->collectPdfReferencesFromValue($this->extractPdfValueForName($dictionary, 'OCGs'), $objects),
            'policy' => $this->extractPdfNameToken($dictionary, 'P'),
            'visibilityExpressionOperators' => $this->collectPdfNamesFromValue($visibilityExpression, $objects),
            'visibilityExpressionGroups' => $this->collectPdfReferencesFromValue($visibilityExpression, $objects),
        ];
    }

    /**
     * @return array{
     *     groups:list<array{object:string, name:string|null, intent:list<string>, usageViewState:string|null, usagePrintState:string|null, usageExportState:string|null, usageCreator:string|null, usageCreatorSubtype:string|null, usageLanguage:string|null, usageLanguagePreferred:bool|null, usageZoomMin:float|null, usageZoomMax:float|null}>,
     *     config:array{name:string|null, creator:string|null, baseState:string|null, listMode:string|null, on:list<string>, off:list<string>, order:list<string>, orderLabels:list<string>, locked?:list<string>, radioButtonGroups?:list<list<string>>}|array{},
     *     usageApplications:list<array{source:string, object:string|null, event:string|null, categories:list<string>, groups:list<string>, groupCount:int, keys:list<string>}>,
     *     alternateConfigs:list<array{source:string, object:string, name:string|null, creator:string|null, baseState:string|null, listMode:string|null, on:list<string>, off:list<string>, order:list<string>, orderLabels:list<string>, locked?:list<string>, radioButtonGroups?:list<list<string>>, keys:list<string>}>
     * }
     */
    private function extractPdfOptionalContent(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $groupReferences = [];
        $config = [];
        $usageApplications = [];
        $alternateConfigs = [];

        if ($catalog !== null && str_contains($catalog, '/OCProperties')) {
            $properties = $this->extractPdfDictionaryOrReferenceValue($catalog, 'OCProperties', $objects);
            if ($properties !== null) {
                foreach ($this->collectPdfReferencesFromArray($this->extractPdfArrayOrReferenceValue($properties, 'OCGs', $objects)) as $reference) {
                    $groupReferences[$this->pdfReferenceKey($reference)] = $reference;
                }
                $config = $this->summarizePdfOptionalContentConfig($properties, $objects);
                $usageApplications = $this->summarizePdfOptionalContentUsageApplications($properties, $objects);
                $alternateConfigs = $this->summarizePdfOptionalContentAlternateConfigs($properties, $objects);
            }
        }

        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'Type') === 'OCG') {
                $groupReferences[$reference] = $reference . ' R';
            }
        }

        $references = array_values($groupReferences);
        usort($references, fn (string $a, string $b): int => $this->pdfReferenceSortKey($a) <=> $this->pdfReferenceSortKey($b));

        $groups = [];
        foreach ($references as $reference) {
            $body = $objects[$this->pdfReferenceKey($reference)] ?? null;
            if ($body === null) {
                continue;
            }

            $groups[] = $this->summarizePdfOptionalContentGroup($reference, $body, $objects);
        }

        return [
            'groups' => $groups,
            'config' => $config,
            'usageApplications' => $usageApplications,
            'alternateConfigs' => $alternateConfigs,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string, name:string|null, intent:list<string>, usageViewState:string|null, usagePrintState:string|null, usageExportState:string|null, usageCreator:string|null, usageCreatorSubtype:string|null, usageLanguage:string|null, usageLanguagePreferred:bool|null, usageZoomMin:float|null, usageZoomMax:float|null}
     */
    private function summarizePdfOptionalContentGroup(string $reference, string $dictionary, array $objects): array
    {
        $usage = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'Usage', $objects);
        $creatorInfo = $usage === null ? null : $this->extractPdfDictionaryOrReferenceValue($usage, 'CreatorInfo', $objects);
        $language = $usage === null ? null : $this->extractPdfDictionaryOrReferenceValue($usage, 'Language', $objects);
        $zoom = $usage === null ? null : $this->extractPdfDictionaryOrReferenceValue($usage, 'Zoom', $objects);

        return [
            'object' => $reference,
            'name' => $this->extractPdfStringOrNameValue($dictionary, 'Name'),
            'intent' => $this->extractPdfOptionalContentIntent($dictionary, $objects),
            'usageViewState' => $this->extractPdfOptionalContentUsageState($usage, 'View', 'ViewState', $objects),
            'usagePrintState' => $this->extractPdfOptionalContentUsageState($usage, 'Print', 'PrintState', $objects),
            'usageExportState' => $this->extractPdfOptionalContentUsageState($usage, 'Export', 'ExportState', $objects),
            'usageCreator' => $creatorInfo === null ? null : $this->extractPdfStringOrNameValue($creatorInfo, 'Creator'),
            'usageCreatorSubtype' => $creatorInfo === null ? null : $this->extractPdfNameToken($creatorInfo, 'Subtype'),
            'usageLanguage' => $language === null ? null : $this->extractPdfStringOrNameValue($language, 'Lang'),
            'usageLanguagePreferred' => $language === null ? null : $this->extractPdfBooleanToken($language, 'Preferred'),
            'usageZoomMin' => $zoom === null ? null : $this->extractPdfNumberToken($zoom, 'min'),
            'usageZoomMax' => $zoom === null ? null : $this->extractPdfNumberToken($zoom, 'max'),
        ];
    }

    /**
     * @param array<string, string> $objects
     */
    private function extractPdfOptionalContentUsageState(?string $usage, string $section, string $stateName, array $objects): ?string
    {
        if ($usage === null) {
            return null;
        }

        $dictionary = $this->extractPdfDictionaryOrReferenceValue($usage, $section, $objects);
        if ($dictionary === null) {
            return null;
        }

        return $this->extractPdfNameToken($dictionary, $stateName);
    }

    /**
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function extractPdfOptionalContentIntent(string $dictionary, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'Intent');
        if ($value === null) {
            return [];
        }

        return $this->pdfValueToNameList($value, $objects);
    }

    /**
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function pdfValueToNameList(array $value, array $objects, int $depth = 0): array
    {
        if ($depth > 8) {
            return [];
        }

        if (in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
            $name = trim($value['value']);

            return $name === '' ? [] : [$name];
        }

        if ($value['kind'] === 'array') {
            return $this->collectPdfNamesFromArray($value['value']);
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return [];
            }

            $resolved = $this->parsePdfValueAt($body, 0);

            return $resolved === null ? [] : $this->pdfValueToNameList($resolved, $objects, $depth + 1);
        }

        return [];
    }

    /**
     * @param array<string, string> $objects
     * @return array{name:string|null, creator:string|null, baseState:string|null, listMode:string|null, on:list<string>, off:list<string>, order:list<string>, orderLabels:list<string>, locked?:list<string>, radioButtonGroups?:list<list<string>>}|array{}
     */
    private function summarizePdfOptionalContentConfig(string $properties, array $objects): array
    {
        $configuration = $this->extractPdfDictionaryOrReferenceValue($properties, 'D', $objects);
        if ($configuration === null) {
            return [];
        }

        return $this->summarizePdfOptionalContentConfigDictionary($configuration, $objects);
    }

    /**
     * @param array<string, string> $objects
     * @return array{name:string|null, creator:string|null, baseState:string|null, listMode:string|null, on:list<string>, off:list<string>, order:list<string>, orderLabels:list<string>, locked?:list<string>, radioButtonGroups?:list<list<string>>}
     */
    private function summarizePdfOptionalContentConfigDictionary(string $configuration, array $objects): array
    {
        $config = [
            'name' => $this->extractPdfStringOrNameValue($configuration, 'Name'),
            'creator' => $this->extractPdfStringOrNameValue($configuration, 'Creator'),
            'baseState' => $this->extractPdfNameToken($configuration, 'BaseState'),
            'listMode' => $this->extractPdfNameToken($configuration, 'ListMode'),
            'on' => $this->collectPdfReferencesFromArray($this->extractPdfArrayOrReferenceValue($configuration, 'ON', $objects)),
            'off' => $this->collectPdfReferencesFromArray($this->extractPdfArrayOrReferenceValue($configuration, 'OFF', $objects)),
            'order' => $this->collectPdfReferencesFromArray($this->extractPdfArrayOrReferenceValue($configuration, 'Order', $objects)),
            'orderLabels' => $this->collectPdfStringsFromArray($this->extractPdfArrayOrReferenceValue($configuration, 'Order', $objects)),
        ];

        $locked = $this->collectPdfReferencesFromArray($this->extractPdfArrayOrReferenceValue($configuration, 'Locked', $objects));
        if ($locked !== []) {
            $config['locked'] = $locked;
        }

        $radioButtonGroups = $this->collectPdfReferenceGroupsFromArray(
            $this->extractPdfArrayOrReferenceValue($configuration, 'RBGroups', $objects),
            $objects
        );
        if ($radioButtonGroups !== []) {
            $config['radioButtonGroups'] = $radioButtonGroups;
        }

        return $config;
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{source:string, object:string, name:string|null, creator:string|null, baseState:string|null, listMode:string|null, on:list<string>, off:list<string>, order:list<string>, orderLabels:list<string>, locked?:list<string>, radioButtonGroups?:list<list<string>>, keys:list<string>}>
     */
    private function summarizePdfOptionalContentAlternateConfigs(string $properties, array $objects): array
    {
        $configsArray = $this->extractPdfArrayOrReferenceValue($properties, 'Configs', $objects);
        if ($configsArray === null) {
            return [];
        }

        $configs = [];
        foreach ($this->pdfTopLevelArrayValues($configsArray) as $index => $value) {
            $resolved = $this->resolvePdfDictionaryValue($value, $objects);
            if (!is_string($resolved['dictionary'])) {
                continue;
            }

            $summary = $this->summarizePdfOptionalContentConfigDictionary($resolved['dictionary'], $objects);
            $config = [
                'source' => 'Configs[' . $index . ']',
                'object' => is_string($resolved['object']) ? $resolved['object'] : 'inline',
                'name' => $summary['name'],
                'creator' => $summary['creator'],
                'baseState' => $summary['baseState'],
                'listMode' => $summary['listMode'],
                'on' => $summary['on'],
                'off' => $summary['off'],
                'order' => $summary['order'],
                'orderLabels' => $summary['orderLabels'],
            ];
            if (isset($summary['locked'])) {
                $config['locked'] = $summary['locked'];
            }
            if (isset($summary['radioButtonGroups'])) {
                $config['radioButtonGroups'] = $summary['radioButtonGroups'];
            }
            $config['keys'] = $this->pdfDictionaryKeys($resolved['dictionary']);
            $configs[] = $config;

            if (count($configs) >= 64) {
                break;
            }
        }

        return $configs;
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{source:string, object:string|null, event:string|null, categories:list<string>, groups:list<string>, groupCount:int, keys:list<string>}>
     */
    private function summarizePdfOptionalContentUsageApplications(string $properties, array $objects): array
    {
        $configuration = $this->extractPdfDictionaryOrReferenceValue($properties, 'D', $objects);
        if ($configuration === null) {
            return [];
        }

        $applications = [];
        foreach ($this->pdfTopLevelArrayValues($this->extractPdfArrayOrReferenceValue($configuration, 'AS', $objects) ?? '') as $index => $value) {
            $resolved = $this->resolvePdfDictionaryValue($value, $objects);
            if ($resolved['dictionary'] === null) {
                continue;
            }

            $keys = [];
            foreach ($this->extractPdfTopLevelDictionaryEntries($resolved['dictionary']) as $entry) {
                $keys[] = $entry['key'];
            }
            $keys = $this->uniqueStrings($keys);
            sort($keys);
            $groups = $this->collectPdfReferencesFromValue($this->extractPdfValueForName($resolved['dictionary'], 'OCGs'), $objects);

            $applications[] = [
                'source' => 'catalog.OCProperties.D.AS[' . $index . ']',
                'object' => $resolved['object'],
                'event' => $this->extractPdfNameToken($resolved['dictionary'], 'Event'),
                'categories' => $this->collectPdfNamesFromValue($this->extractPdfValueForName($resolved['dictionary'], 'Category'), $objects),
                'groups' => $groups,
                'groupCount' => count($groups),
                'keys' => $keys,
            ];
        }

        return $applications;
    }

    /**
     * @param array<string, string> $objects
     * @return list<list<string>>
     */
    private function collectPdfReferenceGroupsFromArray(?string $array, array $objects): array
    {
        if ($array === null) {
            return [];
        }

        $groups = [];
        foreach ($this->pdfTopLevelArrayValues($array) as $value) {
            if ($value['kind'] === 'array') {
                $references = $this->collectPdfReferencesFromArray($value['value']);
            } elseif ($value['kind'] === 'reference') {
                $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
                $resolved = $body === '' ? null : $this->parsePdfValueAt($body, 0);
                $references = $resolved !== null && $resolved['kind'] === 'array'
                    ? $this->collectPdfReferencesFromArray($resolved['value'])
                    : [$value['value']];
            } else {
                $references = [];
            }

            $references = $this->uniqueStrings($references);
            if ($references !== []) {
                $groups[] = $references;
            }
        }

        return $groups;
    }

    /**
     * @return list<array{object:string, infoTitle:string|null, infoAuthor:string|null, infoSubject:string|null, firstBead:string|null, beadCount:int, beads:list<array{object:string, pageObject:string|null, rect:list<float>|null, next:string|null, prev:string|null}>}>
     */
    private function extractPdfThreads(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/Threads')) {
            return [];
        }

        $value = $this->extractPdfValueForName($catalog, 'Threads');
        if ($value === null) {
            return [];
        }

        $threads = [];
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $this->addPdfThreadsFromValue($threads, $value, $objects);
        usort(
            $threads,
            fn (array $left, array $right): int => $this->pdfReferenceSortKey($left['object'])
                <=> $this->pdfReferenceSortKey($right['object'])
                ?: strcmp($left['object'], $right['object'])
        );

        return array_values($threads);
    }

    /**
     * @param list<array{object:string, infoTitle:string|null, infoAuthor:string|null, infoSubject:string|null, firstBead:string|null, beadCount:int, beads:list<array{object:string, pageObject:string|null, rect:list<float>|null, next:string|null, prev:string|null}>}> $threads
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     */
    private function addPdfThreadsFromValue(array &$threads, array $value, array $objects, int $depth = 0): void
    {
        if ($depth > 8) {
            return;
        }

        if ($value['kind'] === 'array') {
            $cursor = str_starts_with($value['value'], '[') ? 1 : 0;
            $length = strlen($value['value']);
            if (str_ends_with($value['value'], ']')) {
                $length--;
            }
            while ($cursor < $length) {
                $item = $this->parsePdfValueAt($value['value'], $cursor);
                if ($item === null) {
                    $cursor++;
                    continue;
                }
                if (in_array($item['kind'], ['array', 'dictionary', 'reference'], true)) {
                    $this->addPdfThreadsFromValue($threads, $item, $objects, $depth + 1);
                }
                $cursor = max($cursor + 1, min($length, $item['next']));
            }

            return;
        }

        if ($value['kind'] === 'reference') {
            $reference = $value['value'];
            $body = $objects[$this->pdfReferenceKey($reference)] ?? null;
            if ($body === null) {
                return;
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved !== null && $resolved['kind'] === 'array') {
                $this->addPdfThreadsFromValue($threads, $resolved, $objects, $depth + 1);
                return;
            }

            $this->addPdfThreadSummary($threads, $this->summarizePdfThread($reference, $body, $objects));
            return;
        }

        if ($value['kind'] === 'dictionary') {
            $this->addPdfThreadSummary($threads, $this->summarizePdfThread('inline', $value['value'], $objects));
        }
    }

    /**
     * @param list<array{object:string, infoTitle:string|null, infoAuthor:string|null, infoSubject:string|null, firstBead:string|null, beadCount:int, beads:list<array{object:string, pageObject:string|null, rect:list<float>|null, next:string|null, prev:string|null}>}> $threads
     * @param array{object:string, infoTitle:string|null, infoAuthor:string|null, infoSubject:string|null, firstBead:string|null, beadCount:int, beads:list<array{object:string, pageObject:string|null, rect:list<float>|null, next:string|null, prev:string|null}>} $summary
     */
    private function addPdfThreadSummary(array &$threads, array $summary): void
    {
        if ($summary['object'] !== 'inline') {
            foreach ($threads as $thread) {
                if ($thread['object'] === $summary['object']) {
                    return;
                }
            }
        }

        $threads[] = $summary;
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string, infoTitle:string|null, infoAuthor:string|null, infoSubject:string|null, firstBead:string|null, beadCount:int, beads:list<array{object:string, pageObject:string|null, rect:list<float>|null, next:string|null, prev:string|null}>}
     */
    private function summarizePdfThread(string $reference, string $dictionary, array $objects): array
    {
        $info = $this->extractPdfThreadInfoMetadata($dictionary, $objects);
        $firstBead = $this->extractPdfReferenceToken($dictionary, 'F');
        $beads = $firstBead === null ? [] : $this->extractPdfThreadBeads($firstBead, $objects);

        return [
            'object' => $reference,
            'infoTitle' => $info['title'],
            'infoAuthor' => $info['author'],
            'infoSubject' => $info['subject'],
            'firstBead' => $firstBead,
            'beadCount' => count($beads),
            'beads' => $beads,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return array{title:string|null, author:string|null, subject:string|null}
     */
    private function extractPdfThreadInfoMetadata(string $thread, array $objects): array
    {
        $info = $this->extractPdfDictionaryOrReferenceValue($thread, 'I', $objects);
        if ($info === null) {
            $info = $thread;
        }

        return [
            'title' => $this->extractPdfStringOrNameValue($info, 'Title'),
            'author' => $this->extractPdfStringOrNameValue($info, 'Author'),
            'subject' => $this->extractPdfStringOrNameValue($info, 'Subject'),
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{object:string, pageObject:string|null, rect:list<float>|null, next:string|null, prev:string|null}>
     */
    private function extractPdfThreadBeads(string $firstBead, array $objects): array
    {
        $beads = [];
        $visited = [];
        $firstKey = $this->pdfReferenceKey($firstBead);
        $cursor = $firstKey;
        for ($depth = 0; $depth < 64; $depth++) {
            if (isset($visited[$cursor])) {
                break;
            }
            $body = $objects[$cursor] ?? null;
            if ($body === null) {
                break;
            }

            $visited[$cursor] = true;
            $next = $this->extractPdfReferenceToken($body, 'N');
            $beads[] = [
                'object' => $cursor . ' R',
                'pageObject' => $this->extractPdfReferenceToken($body, 'P'),
                'rect' => $this->extractPdfNumberArrayToken($body, 'R', 4),
                'next' => $next,
                'prev' => $this->extractPdfReferenceToken($body, 'V'),
            ];

            if ($next === null) {
                break;
            }

            $nextKey = $this->pdfReferenceKey($next);
            if ($nextKey === $firstKey || isset($visited[$nextKey])) {
                break;
            }

            $cursor = $nextKey;
        }

        return $beads;
    }

    /**
     * @param list<array{object:string, infoTitle:string|null, infoAuthor:string|null, infoSubject:string|null, firstBead:string|null, beadCount:int, beads:list<array{object:string, pageObject:string|null, rect:list<float>|null, next:string|null, prev:string|null}>}> $threads
     * @return array<string, mixed>
     */
    private function summarizePdfThreadPolicy(array $threads): array
    {
        if ($threads === []) {
            return [];
        }

        $issueCounts = [];
        $threadPolicies = [];
        $pageObjects = [];
        $beadCount = 0;
        $titledThreadCount = 0;
        $missingFirstBeadCount = 0;
        $unresolvedFirstBeadCount = 0;
        $missingPageCount = 0;
        $missingRectCount = 0;
        $openLinkCount = 0;
        $outsideLinkCount = 0;
        $reciprocalMismatchCount = 0;

        $addIssue = static function (array &$counts, string $issue): void {
            $counts[$issue] = ($counts[$issue] ?? 0) + 1;
        };

        foreach ($threads as $thread) {
            $threadIssueCounts = [];
            $threadPageObjects = [];
            $threadMissingPageCount = 0;
            $threadMissingRectCount = 0;
            $threadOpenLinkCount = 0;
            $threadOutsideLinkCount = 0;
            $threadReciprocalMismatchCount = 0;
            $threadBeads = is_array($thread['beads'] ?? null) ? $thread['beads'] : [];
            $threadBeadCount = count($threadBeads);
            $beadCount += $threadBeadCount;

            if (is_string($thread['infoTitle'] ?? null) && $thread['infoTitle'] !== '') {
                $titledThreadCount++;
            }

            $firstBead = is_string($thread['firstBead'] ?? null) && $thread['firstBead'] !== ''
                ? $thread['firstBead']
                : null;
            if ($firstBead === null) {
                $missingFirstBeadCount++;
                $addIssue($threadIssueCounts, 'thread-missing-first-bead');
                $addIssue($issueCounts, 'thread-missing-first-bead');
            } elseif ($threadBeadCount === 0) {
                $unresolvedFirstBeadCount++;
                $addIssue($threadIssueCounts, 'thread-first-bead-unresolved');
                $addIssue($issueCounts, 'thread-first-bead-unresolved');
            }

            $beadsByObject = [];
            foreach ($threadBeads as $bead) {
                if (is_string($bead['object'] ?? null) && $bead['object'] !== '') {
                    $beadsByObject[$bead['object']] = $bead;
                }
            }

            foreach ($threadBeads as $bead) {
                $object = is_string($bead['object'] ?? null) ? $bead['object'] : '';
                $pageObject = is_string($bead['pageObject'] ?? null) && $bead['pageObject'] !== ''
                    ? $bead['pageObject']
                    : null;
                if ($pageObject === null) {
                    $missingPageCount++;
                    $threadMissingPageCount++;
                    $addIssue($threadIssueCounts, 'thread-bead-missing-page');
                    $addIssue($issueCounts, 'thread-bead-missing-page');
                } else {
                    $pageObjects[$pageObject] = true;
                    $threadPageObjects[$pageObject] = true;
                }

                if (!is_array($bead['rect'] ?? null)) {
                    $missingRectCount++;
                    $threadMissingRectCount++;
                    $addIssue($threadIssueCounts, 'thread-bead-missing-rect');
                    $addIssue($issueCounts, 'thread-bead-missing-rect');
                }

                $next = is_string($bead['next'] ?? null) && $bead['next'] !== '' ? $bead['next'] : null;
                $prev = is_string($bead['prev'] ?? null) && $bead['prev'] !== '' ? $bead['prev'] : null;
                if ($next === null) {
                    $openLinkCount++;
                    $threadOpenLinkCount++;
                    $addIssue($threadIssueCounts, 'thread-bead-missing-next-link');
                    $addIssue($issueCounts, 'thread-bead-missing-next-link');
                } elseif (!isset($beadsByObject[$next])) {
                    $outsideLinkCount++;
                    $threadOutsideLinkCount++;
                    $addIssue($threadIssueCounts, 'thread-bead-next-outside-chain');
                    $addIssue($issueCounts, 'thread-bead-next-outside-chain');
                } elseif (($beadsByObject[$next]['prev'] ?? null) !== $object) {
                    $reciprocalMismatchCount++;
                    $threadReciprocalMismatchCount++;
                    $addIssue($threadIssueCounts, 'thread-bead-next-prev-mismatch');
                    $addIssue($issueCounts, 'thread-bead-next-prev-mismatch');
                }

                if ($prev === null) {
                    $openLinkCount++;
                    $threadOpenLinkCount++;
                    $addIssue($threadIssueCounts, 'thread-bead-missing-prev-link');
                    $addIssue($issueCounts, 'thread-bead-missing-prev-link');
                } elseif (!isset($beadsByObject[$prev])) {
                    $outsideLinkCount++;
                    $threadOutsideLinkCount++;
                    $addIssue($threadIssueCounts, 'thread-bead-prev-outside-chain');
                    $addIssue($issueCounts, 'thread-bead-prev-outside-chain');
                } elseif (($beadsByObject[$prev]['next'] ?? null) !== $object) {
                    $reciprocalMismatchCount++;
                    $threadReciprocalMismatchCount++;
                    $addIssue($threadIssueCounts, 'thread-bead-prev-next-mismatch');
                    $addIssue($issueCounts, 'thread-bead-prev-next-mismatch');
                }
            }

            ksort($threadIssueCounts);
            $threadPolicies[] = [
                'object' => is_string($thread['object'] ?? null) ? $thread['object'] : '',
                'firstBead' => $firstBead,
                'reviewStatus' => $threadIssueCounts === [] ? 'ok' : 'review',
                'beadCount' => $threadBeadCount,
                'pageObjects' => $this->sortedPdfReferenceKeys($threadPageObjects),
                'missingPageCount' => $threadMissingPageCount,
                'missingRectCount' => $threadMissingRectCount,
                'openLinkCount' => $threadOpenLinkCount,
                'outsideLinkCount' => $threadOutsideLinkCount,
                'reciprocalMismatchCount' => $threadReciprocalMismatchCount,
                'issues' => array_keys($threadIssueCounts),
            ];
        }

        ksort($issueCounts);

        return [
            'reviewStatus' => $issueCounts === [] ? 'ok' : 'review',
            'threadCount' => count($threads),
            'beadCount' => $beadCount,
            'titledThreadCount' => $titledThreadCount,
            'pageObjectCount' => count($pageObjects),
            'pageObjects' => $this->sortedPdfReferenceKeys($pageObjects),
            'missingFirstBeadCount' => $missingFirstBeadCount,
            'unresolvedFirstBeadCount' => $unresolvedFirstBeadCount,
            'missingPageCount' => $missingPageCount,
            'missingRectCount' => $missingRectCount,
            'openLinkCount' => $openLinkCount,
            'outsideLinkCount' => $outsideLinkCount,
            'reciprocalMismatchCount' => $reciprocalMismatchCount,
            'issueCounts' => $issueCounts,
            'issues' => array_keys($issueCounts),
            'threads' => $threadPolicies,
        ];
    }

    /**
     * @return list<array{source:string, object:string|null, type:string|null, parentObject:string|null, metadataObject:string|null, metadataKeys:list<string>, metadataItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, startPageObject:string|null, endPageObject:string|null, childObjects:list<string>, missingChildObjects:list<string>, childCount:int, depth:int}>
     */
    private function extractPdfDocumentPartMetadata(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/DPartRoot')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $root = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($catalog, 'DPartRoot'), $objects);
        if ($root['dictionary'] === null) {
            return [];
        }

        $parts = [];
        $visited = [];
        $this->collectPdfDocumentPartMetadata(
            $parts,
            $root['dictionary'],
            $root['object'],
            null,
            'catalog.DPartRoot',
            $objects,
            $visited,
            0
        );

        return $parts;
    }

    /**
     * @param list<array{source:string, object:string|null, type:string|null, parentObject:string|null, metadataObject:string|null, metadataKeys:list<string>, metadataItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, startPageObject:string|null, endPageObject:string|null, childObjects:list<string>, missingChildObjects:list<string>, childCount:int, depth:int}> $parts
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfDocumentPartMetadata(
        array &$parts,
        string $dictionary,
        ?string $object,
        ?string $parentObject,
        string $source,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $visitKey = $object !== null && $object !== 'inline' ? $object : $source;
        if (isset($visited[$visitKey])) {
            return;
        }
        $visited[$visitKey] = true;

        $metadata = $this->extractPdfDocumentPartMetadataItems($dictionary, $objects);
        $children = $this->pdfDocumentPartChildValues($dictionary, $objects);
        $childObjects = [];
        $missingChildObjects = [];
        foreach ($children as $child) {
            if (($child['kind'] ?? null) !== 'reference') {
                continue;
            }

            $childObjects[] = $child['value'];
            if (!isset($objects[$this->pdfReferenceKey($child['value'])])) {
                $missingChildObjects[] = $child['value'];
            }
        }

        $parts[] = [
            'source' => $source,
            'object' => $object,
            'type' => $this->extractPdfDirectNameToken($dictionary, 'Type'),
            'parentObject' => $this->extractPdfDirectReferenceToken($dictionary, 'Parent') ?? $parentObject,
            'metadataObject' => $metadata['object'],
            'metadataKeys' => $metadata['keys'],
            'metadataItems' => $metadata['items'],
            'startPageObject' => $this->extractPdfDirectReferenceToken($dictionary, 'Start'),
            'endPageObject' => $this->extractPdfDirectReferenceToken($dictionary, 'End'),
            'childObjects' => $this->uniqueStrings($childObjects),
            'missingChildObjects' => $this->uniqueStrings($missingChildObjects),
            'childCount' => count($children),
            'depth' => $depth,
        ];

        foreach ($children as $index => $child) {
            $childDictionary = null;
            $childObject = null;
            if ($child['kind'] === 'dictionary') {
                $childDictionary = $child['value'];
                $childObject = 'inline';
            } elseif ($child['kind'] === 'reference') {
                $childObject = $child['value'];
                $childDictionary = $objects[$this->pdfReferenceKey($childObject)] ?? null;
            }

            if ($childDictionary === null) {
                continue;
            }

            $this->collectPdfDocumentPartMetadata(
                $parts,
                $childDictionary,
                $childObject,
                $object,
                $source . '.DParts[' . $index . ']',
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{kind:string, value:string, next:int}>
     */
    private function pdfDocumentPartChildValues(string $dictionary, array $objects): array
    {
        $array = $this->extractPdfArrayOrReferenceValue($dictionary, 'DParts', $objects);

        return $array === null ? [] : $this->pdfTopLevelArrayValues($array);
    }

    private function extractPdfDirectNameToken(string $dictionary, string $name): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, $name);

        return $value !== null && $value['kind'] === 'name' ? $value['value'] : null;
    }

    private function extractPdfDirectReferenceToken(string $dictionary, string $name): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, $name);

        return $value !== null && $value['kind'] === 'reference' ? $value['value'] : null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string|null, keys:list<string>, items:list<array{name:string, value:string|int|float|bool|null, valueType:string}>}
     */
    private function extractPdfDocumentPartMetadataItems(string $dictionary, array $objects): array
    {
        $metadata = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($dictionary, 'DPM'), $objects);
        if ($metadata['dictionary'] === null) {
            return [
                'object' => null,
                'keys' => [],
                'items' => [],
            ];
        }

        $keys = [];
        $items = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($metadata['dictionary']) as $entry) {
            if ($entry['key'] === '' || $entry['key'] === 'Type') {
                continue;
            }

            $keys[] = $entry['key'];
            $summary = $this->summarizePdfFileSpecCollectionItemValue($entry['value'], $objects, 0);
            if ($summary === null) {
                continue;
            }

            $items[] = [
                'name' => $entry['key'],
                'value' => $summary['value'],
                'valueType' => $summary['valueType'],
            ];
        }

        $keys = $this->uniqueStrings($keys);
        sort($keys, SORT_STRING);
        usort($items, static fn (array $left, array $right): int => strcmp($left['name'], $right['name']));

        return [
            'object' => $metadata['object'],
            'keys' => $keys,
            'items' => $items,
        ];
    }

    /**
     * @param list<array{source:string, object:string|null, type:string|null, parentObject:string|null, metadataObject:string|null, metadataKeys:list<string>, metadataItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, startPageObject:string|null, endPageObject:string|null, childObjects:list<string>, missingChildObjects:list<string>, childCount:int, depth:int}> $parts
     * @return array<string, mixed>
     */
    private function summarizePdfDocumentPartPolicy(array $parts): array
    {
        if ($parts === []) {
            return [];
        }

        $partCount = 0;
        $metadataNodeCount = 0;
        $metadataItemCount = 0;
        $childReferenceCount = 0;
        $missingChildCount = 0;
        $maxDepth = 0;
        $issues = [];
        foreach ($parts as $part) {
            if (($part['type'] ?? null) === 'DPart') {
                $partCount++;
            }
            if (($part['metadataItems'] ?? []) !== []) {
                $metadataNodeCount++;
                $metadataItemCount += count($part['metadataItems']);
            }
            if (isset($part['childObjects']) && is_array($part['childObjects'])) {
                $childReferenceCount += count($part['childObjects']);
            }
            if (isset($part['missingChildObjects']) && is_array($part['missingChildObjects'])) {
                $missingChildCount += count($part['missingChildObjects']);
            }
            if (is_int($part['depth'] ?? null)) {
                $maxDepth = max($maxDepth, $part['depth']);
            }
        }

        if ($missingChildCount > 0) {
            $issues[] = 'document-part-missing-child';
        }
        if ($partCount === 0) {
            $issues[] = 'document-part-root-empty';
        }

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'nodeCount' => count($parts),
            'partCount' => $partCount,
            'metadataNodeCount' => $metadataNodeCount,
            'metadataItemCount' => $metadataItemCount,
            'childReferenceCount' => $childReferenceCount,
            'missingChildCount' => $missingChildCount,
            'maxDepth' => $maxDepth,
            'issues' => $issues,
        ];
    }

    /**
     * @return array{type:string|null, view:string|null, defaultDocument:string|null, schemaFields:list<array{name:string, subtype:string|null, title:string|null, order:int|null, visible:bool|null, editable:bool|null}>, sort:array{fields:list<string>, ascending:list<bool>}|array{}}|array{}
     */
    private function extractPdfCollectionMetadata(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/Collection')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $collection = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Collection', $objects);
        if ($collection === null) {
            return [];
        }

        return [
            'type' => $this->extractPdfNameToken($collection, 'Type'),
            'view' => $this->extractPdfNameToken($collection, 'View'),
            'defaultDocument' => $this->extractPdfStringOrNameValue($collection, 'D'),
            'schemaFields' => $this->extractPdfCollectionSchemaFields($collection, $objects),
            'sort' => $this->extractPdfCollectionSort($collection, $objects),
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{name:string, subtype:string|null, title:string|null, order:int|null, visible:bool|null, editable:bool|null}>
     */
    private function extractPdfCollectionSchemaFields(string $collection, array $objects): array
    {
        $schema = $this->extractPdfDictionaryOrReferenceValue($collection, 'Schema', $objects);
        if ($schema === null) {
            return [];
        }

        $fields = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($schema) as $entry) {
            if ($entry['key'] === 'Type') {
                continue;
            }

            $dictionary = null;
            if ($entry['value']['kind'] === 'dictionary') {
                $dictionary = $entry['value']['value'];
            } elseif ($entry['value']['kind'] === 'reference') {
                $dictionary = $objects[$this->pdfReferenceKey($entry['value']['value'])] ?? null;
            }
            if ($dictionary === null) {
                continue;
            }

            $summary = $this->summarizePdfCollectionField($entry['key'], $dictionary);
            if ($summary !== null) {
                $fields[] = $summary;
            }
        }

        usort(
            $fields,
            static function (array $left, array $right): int {
                $leftOrder = $left['order'] ?? PHP_INT_MAX;
                $rightOrder = $right['order'] ?? PHP_INT_MAX;
                if ($leftOrder !== $rightOrder) {
                    return $leftOrder <=> $rightOrder;
                }

                return strcmp($left['name'], $right['name']);
            }
        );

        return $fields;
    }

    /**
     * @return array{name:string, subtype:string|null, title:string|null, order:int|null, visible:bool|null, editable:bool|null}|null
     */
    private function summarizePdfCollectionField(string $name, string $dictionary): ?array
    {
        $name = trim($name);
        if ($name === '') {
            return null;
        }

        return [
            'name' => $name,
            'subtype' => $this->extractPdfNameToken($dictionary, 'Subtype'),
            'title' => $this->extractPdfStringOrNameValue($dictionary, 'N'),
            'order' => $this->extractPdfIntegerToken($dictionary, 'O'),
            'visible' => $this->extractPdfBooleanToken($dictionary, 'V'),
            'editable' => $this->extractPdfBooleanToken($dictionary, 'E'),
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return array{fields:list<string>, ascending:list<bool>}|array{}
     */
    private function extractPdfCollectionSort(string $collection, array $objects): array
    {
        $sort = $this->extractPdfDictionaryOrReferenceValue($collection, 'Sort', $objects);
        if ($sort === null) {
            return [];
        }

        $fieldsValue = $this->extractPdfValueForName($sort, 'S');
        $fields = $fieldsValue === null ? [] : $this->pdfValueToNameList($fieldsValue, $objects);
        $ascendingValue = $this->extractPdfValueForName($sort, 'A');
        $ascending = $ascendingValue === null ? [] : $this->pdfValueToBooleanList($ascendingValue, $objects);
        if ($fields === [] && $ascending === []) {
            return [];
        }

        return [
            'fields' => $fields,
            'ascending' => $ascending,
        ];
    }

    /**
     * @param array{type?:string|null, view?:string|null, defaultDocument?:string|null, schemaFields?:list<array{name:string, subtype:string|null, title:string|null, order:int|null, visible:bool|null, editable:bool|null}>, sort?:array{fields?:list<string>, ascending?:list<bool>}} $collection
     * @param list<array{source?:string, name:string|null, unicodeName:string|null, collectionItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>}> $embeddedFiles
     * @return array{reviewStatus:string, defaultDocument:string|null, defaultDocumentMatched:bool|null, embeddedFileCount:int, collectionItemFileCount:int, schemaFieldCount:int, sortFieldCount:int, visibleFieldCount:int, editableFieldCount:int, undefinedSortFields:list<string>, embeddedFiles:list<array{name:string|null, collectionItemCount:int, missingSchemaFields:list<string>, extraCollectionItems:list<string>>>, issues:list<string>}|array{}
     */
    private function summarizePdfCollectionPolicy(array $collection, array $embeddedFiles): array
    {
        if ($collection === []) {
            return [];
        }

        $schemaFields = isset($collection['schemaFields']) && is_array($collection['schemaFields'])
            ? $collection['schemaFields']
            : [];
        $schemaNames = [];
        $visibleFieldCount = 0;
        $editableFieldCount = 0;
        foreach ($schemaFields as $field) {
            $name = is_string($field['name'] ?? null) ? trim($field['name']) : '';
            if ($name !== '') {
                $schemaNames[$name] = true;
            }
            if (($field['visible'] ?? null) === true) {
                $visibleFieldCount++;
            }
            if (($field['editable'] ?? null) === true) {
                $editableFieldCount++;
            }
        }
        $schemaNames = array_keys($schemaNames);
        sort($schemaNames);
        $schemaNameSet = array_fill_keys($schemaNames, true);

        $sortFields = isset($collection['sort']['fields']) && is_array($collection['sort']['fields'])
            ? array_values(array_filter($collection['sort']['fields'], static fn (mixed $value): bool => is_string($value) && $value !== ''))
            : [];
        $undefinedSortFields = [];
        foreach ($sortFields as $sortField) {
            if (!isset($schemaNameSet[$sortField])) {
                $undefinedSortFields[$sortField] = true;
            }
        }
        $undefinedSortFields = array_keys($undefinedSortFields);
        sort($undefinedSortFields);

        $issues = [];
        if ($undefinedSortFields !== []) {
            $issues['sort-field-not-in-schema'] = true;
        }

        $collectionEmbeddedFiles = array_values(array_filter(
            $embeddedFiles,
            static fn (array $embeddedFile): bool => ($embeddedFile['source'] ?? null) === 'catalog.Names.EmbeddedFiles'
        ));
        $embeddedFileNames = [];
        $policyFiles = [];
        $collectionItemFileCount = 0;
        if ($collectionEmbeddedFiles === []) {
            $issues['collection-without-embedded-files'] = true;
        }
        foreach ($collectionEmbeddedFiles as $embeddedFile) {
            $name = $this->pdfCollectionPolicyFileName($embeddedFile);
            if ($name !== null && $name !== '') {
                $embeddedFileNames[$name] = true;
            }

            $collectionItems = isset($embeddedFile['collectionItems']) && is_array($embeddedFile['collectionItems'])
                ? $embeddedFile['collectionItems']
                : [];
            if ($collectionItems !== []) {
                $collectionItemFileCount++;
            }

            $itemNames = [];
            foreach ($collectionItems as $item) {
                $itemName = is_string($item['name'] ?? null) ? trim($item['name']) : '';
                if ($itemName !== '') {
                    $itemNames[$itemName] = true;
                }
            }
            $itemNames = array_keys($itemNames);
            sort($itemNames);
            $itemNameSet = array_fill_keys($itemNames, true);

            $missingSchemaFields = [];
            foreach ($schemaNames as $schemaName) {
                if (!isset($itemNameSet[$schemaName])) {
                    $missingSchemaFields[] = $schemaName;
                }
            }

            $extraCollectionItems = [];
            foreach ($itemNames as $itemName) {
                if (!isset($schemaNameSet[$itemName])) {
                    $extraCollectionItems[] = $itemName;
                }
            }

            if ($collectionItems === [] && $schemaNames !== []) {
                $issues['embedded-file-missing-collection-items'] = true;
            }
            if ($missingSchemaFields !== []) {
                $issues['schema-field-missing-on-collection-item'] = true;
            }
            if ($extraCollectionItems !== []) {
                $issues['collection-item-field-not-in-schema'] = true;
            }

            $policyFiles[] = [
                'name' => $name,
                'collectionItemCount' => count($collectionItems),
                'missingSchemaFields' => $missingSchemaFields,
                'extraCollectionItems' => $extraCollectionItems,
            ];
        }
        usort(
            $policyFiles,
            static fn (array $left, array $right): int => strcmp((string) ($left['name'] ?? ''), (string) ($right['name'] ?? ''))
        );

        $defaultDocument = is_string($collection['defaultDocument'] ?? null) && $collection['defaultDocument'] !== ''
            ? $collection['defaultDocument']
            : null;
        $defaultDocumentMatched = null;
        if ($defaultDocument !== null) {
            $defaultDocumentMatched = isset($embeddedFileNames[$defaultDocument]);
            if (!$defaultDocumentMatched) {
                $issues['default-document-not-embedded'] = true;
            }
        }

        $issues = array_keys($issues);
        sort($issues);

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'defaultDocument' => $defaultDocument,
            'defaultDocumentMatched' => $defaultDocumentMatched,
            'embeddedFileCount' => count($collectionEmbeddedFiles),
            'collectionItemFileCount' => $collectionItemFileCount,
            'schemaFieldCount' => count($schemaNames),
            'sortFieldCount' => count($sortFields),
            'visibleFieldCount' => $visibleFieldCount,
            'editableFieldCount' => $editableFieldCount,
            'undefinedSortFields' => $undefinedSortFields,
            'embeddedFiles' => $policyFiles,
            'issues' => $issues,
        ];
    }

    /**
     * @param array{name?:string|null, unicodeName?:string|null} $embeddedFile
     */
    private function pdfCollectionPolicyFileName(array $embeddedFile): ?string
    {
        foreach (['name', 'unicodeName'] as $key) {
            $name = is_string($embeddedFile[$key] ?? null) ? trim((string) $embeddedFile[$key]) : '';
            if ($name !== '') {
                return $name;
            }
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return list<bool>
     */
    private function pdfValueToBooleanList(array $value, array $objects, int $depth = 0): array
    {
        if ($depth > 8) {
            return [];
        }

        if ($value['kind'] === 'keyword' && in_array($value['value'], ['true', 'false'], true)) {
            return [$value['value'] === 'true'];
        }

        if ($value['kind'] === 'array') {
            $booleans = [];
            $this->walkPdfArrayValues($value['value'], function (array $item) use (&$booleans, $objects, $depth): void {
                if ($item['kind'] === 'keyword' && in_array($item['value'], ['true', 'false'], true)) {
                    $booleans[] = $item['value'] === 'true';
                    return;
                }

                if ($item['kind'] === 'reference') {
                    foreach ($this->pdfValueToBooleanList($item, $objects, $depth + 1) as $boolean) {
                        $booleans[] = $boolean;
                    }
                }
            });

            return $booleans;
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return [];
            }

            $resolved = $this->parsePdfValueAt($body, 0);

            return $resolved === null ? [] : $this->pdfValueToBooleanList($resolved, $objects, $depth + 1);
        }

        return [];
    }

    /**
     * @return list<array{permission:string, signatureObject:string|null, filter:string|null, subFilter:string|null, name:string|null, reason:string|null, location:string|null, contactInfo:string|null, signingTime:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null, contentsSha256:string|null, contentsSkipped:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>}>
     */
    private function extractPdfCatalogPermissions(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/Perms')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $permissionsDictionary = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Perms', $objects);
        if ($permissionsDictionary === null) {
            return [];
        }

        $permissions = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($permissionsDictionary) as $entry) {
            $permission = $entry['key'];
            if ($permission === 'Type' || $permission === '') {
                continue;
            }

            $summary = null;
            $value = $entry['value'];
            if ($value['kind'] === 'reference') {
                $reference = $this->pdfReferenceKey($value['value']);
                $body = $objects[$reference] ?? null;
                if ($body !== null) {
                    $summary = $this->summarizePdfSignatureDictionary($body, null, null, $reference . ' R', $objects);
                }
            } elseif ($value['kind'] === 'dictionary') {
                $summary = $this->summarizePdfSignatureDictionary($value['value'], null, null, 'inline', $objects);
            }

            if ($summary === null || !$this->isPdfSignatureLikeSummary($summary)) {
                continue;
            }

            $permissions[] = [
                'permission' => $permission,
                'signatureObject' => $summary['signatureObject'],
                'filter' => $summary['filter'],
                'subFilter' => $summary['subFilter'],
                'name' => $summary['name'],
                'reason' => $summary['reason'],
                'location' => $summary['location'],
                'contactInfo' => $summary['contactInfo'],
                'signingTime' => $summary['signingTime'],
                'byteRange' => $summary['byteRange'],
                'byteRangeSegmentCount' => $summary['byteRangeSegmentCount'],
                'coveredBytes' => $summary['coveredBytes'],
                'contentsBytes' => $summary['contentsBytes'],
                'contentsSha256' => $summary['contentsSha256'],
                'contentsSkipped' => $summary['contentsSkipped'],
                'referenceTransforms' => $summary['referenceTransforms'],
            ];
        }

        usort(
            $permissions,
            static fn (array $a, array $b): int => [
                $a['permission'],
                $a['signatureObject'] ?? '',
            ] <=> [
                $b['permission'],
                $b['signatureObject'] ?? '',
            ]
        );

        return $permissions;
    }

    /**
     * @param array{filter:string|null, subFilter:string|null, name:string|null, reason:string|null, location:string|null, contactInfo:string|null, signingTime:string|null, byteRange:list<int>, contentsBytes:int|null, referenceTransforms:list<array<string, mixed>>} $summary
     */
    private function isPdfSignatureLikeSummary(array $summary): bool
    {
        if (($summary['byteRange'] ?? []) !== [] || ($summary['contentsBytes'] ?? null) !== null) {
            return true;
        }
        if (($summary['referenceTransforms'] ?? []) !== []) {
            return true;
        }

        foreach (['filter', 'subFilter', 'name', 'reason', 'location', 'contactInfo', 'signingTime'] as $key) {
            if (is_string($summary[$key] ?? null) && $summary[$key] !== '') {
                return true;
            }
        }

        return false;
    }

    /**
     * @return list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, filter:string|null, subFilter:string|null, name:string|null, reason:string|null, location:string|null, contactInfo:string|null, signingTime:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null, contentsSha256:string|null, contentsSkipped:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>}>
     */
    private function extractPdfSignatures(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $signatures = [];
        $visitedFields = [];
        $acroForm = $this->extractPdfAcroFormDictionary($pdfBytes, $catalog);

        if ($acroForm !== null) {
            foreach ($this->extractPdfReferenceArray($acroForm, 'Fields') as $reference) {
                $this->collectPdfSignatureFields($signatures, $objects, $reference, $visitedFields, 0);
            }
        }

        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'FT') === 'Sig') {
                $this->addPdfSignatureFromField($signatures, $reference . ' R', $body, $objects);
                continue;
            }

            if (
                $this->extractPdfNameToken($body, 'Type') === 'Sig'
                || (str_contains($body, '/ByteRange') && str_contains($body, '/Contents'))
            ) {
                $this->addPdfSignatureEntry(
                    $signatures,
                    $this->summarizePdfSignatureDictionary($body, null, null, $reference . ' R', $objects)
                );
            }
        }

        $signatures = array_values($signatures);
        usort(
            $signatures,
            static fn (array $a, array $b): int => [
                $a['fieldName'] ?? '',
                $a['fieldObject'] ?? '',
                $a['signatureObject'] ?? '',
            ] <=> [
                $b['fieldName'] ?? '',
                $b['fieldObject'] ?? '',
                $b['signatureObject'] ?? '',
            ]
        );

        return $signatures;
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function extractPdfSignatureSeedValues(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $seedValues = [];
        $visitedFields = [];
        $acroForm = $this->extractPdfAcroFormDictionary($pdfBytes, $catalog);

        if ($acroForm !== null) {
            foreach ($this->extractPdfReferenceArray($acroForm, 'Fields') as $reference) {
                $this->collectPdfSignatureSeedValueFields($seedValues, $objects, $reference, $visitedFields, 0);
            }
        }

        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'FT') === 'Sig' && $this->extractPdfValueForName($body, 'SV') !== null) {
                $this->addPdfSignatureSeedValueFromField($seedValues, $reference . ' R', $body, $objects);
            }
        }

        $seedValues = array_values($seedValues);
        usort(
            $seedValues,
            static fn (array $a, array $b): int => [
                $a['fieldName'] ?? '',
                $a['fieldObject'] ?? '',
                $a['seedValueObject'] ?? '',
            ] <=> [
                $b['fieldName'] ?? '',
                $b['fieldObject'] ?? '',
                $b['seedValueObject'] ?? '',
            ]
        );

        return $seedValues;
    }

    /**
     * @param array<string, array<string, mixed>> $seedValues
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfSignatureSeedValueFields(array &$seedValues, array $objects, string $reference, array &$visited, int $depth): void
    {
        if ($depth > 16 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }

        $visited[$reference] = true;
        $body = $objects[$reference];
        $this->addPdfSignatureSeedValueFromField($seedValues, $reference . ' R', $body, $objects);

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfSignatureSeedValueFields($seedValues, $objects, $kidReference, $visited, $depth + 1);
        }
    }

    /**
     * @param array<string, array<string, mixed>> $seedValues
     * @param array<string, string> $objects
     */
    private function addPdfSignatureSeedValueFromField(array &$seedValues, string $fieldReference, string $fieldDictionary, array $objects): void
    {
        if ($this->extractPdfNameToken($fieldDictionary, 'FT') !== 'Sig') {
            return;
        }

        $seedValue = $this->extractPdfValueForName($fieldDictionary, 'SV');
        if ($seedValue === null) {
            return;
        }

        $fieldName = $this->extractPdfStringOrNameValue($fieldDictionary, 'T')
            ?? $this->extractPdfStringOrNameValue($fieldDictionary, 'TU')
            ?? $this->extractPdfStringOrNameValue($fieldDictionary, 'TM');
        $summary = $this->summarizePdfSignatureSeedValueDictionary($seedValue, $fieldName, $fieldReference, $objects);
        if ($summary === null) {
            return;
        }

        $key = ($summary['fieldObject'] ?? '') . "\0" . ($summary['seedValueObject'] ?? '');
        $seedValues[$key] = $summary;
    }

    /**
     * @param array{kind:string, value:string, next?:int} $seedValue
     * @param array<string, string> $objects
     * @return array<string, mixed>|null
     */
    private function summarizePdfSignatureSeedValueDictionary(array $seedValue, ?string $fieldName, string $fieldObject, array $objects): ?array
    {
        $resolved = $this->resolvePdfDictionaryValue($seedValue, $objects);
        $dictionary = $resolved['dictionary'];
        if ($dictionary === null) {
            return null;
        }

        $flags = $this->extractPdfIntegerToken($dictionary, 'Ff') ?? 0;
        $mdpDictionary = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'MDP', $objects);
        $timestampDictionary = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'TimeStamp', $objects);

        return [
            'fieldName' => $fieldName === '' ? null : $fieldName,
            'fieldObject' => $fieldObject,
            'seedValueObject' => $resolved['object'],
            'flags' => $flags,
            'flagNames' => $this->pdfSignatureSeedValueFlagNames($flags),
            'filters' => $this->collectPdfNamesFromValue($this->extractPdfValueForName($dictionary, 'Filter'), $objects),
            'subFilters' => $this->collectPdfNamesFromValue($this->extractPdfValueForName($dictionary, 'SubFilter'), $objects),
            'digestMethods' => $this->collectPdfNamesFromValue($this->extractPdfValueForName($dictionary, 'DigestMethod'), $objects),
            'minimumVersion' => $this->extractPdfNumberToken($dictionary, 'V'),
            'reasons' => $this->collectPdfTextFromValue($this->extractPdfValueForName($dictionary, 'Reasons'), $objects),
            'legalAttestations' => $this->collectPdfTextFromValue($this->extractPdfValueForName($dictionary, 'LegalAttestation'), $objects),
            'mdpPermissions' => $mdpDictionary === null ? null : $this->extractPdfIntegerToken($mdpDictionary, 'P'),
            'timestampUrl' => $timestampDictionary === null ? null : $this->extractPdfStringOrNameValue($timestampDictionary, 'URL'),
            'timestampRequired' => $timestampDictionary !== null && (($this->extractPdfIntegerToken($timestampDictionary, 'Ff') ?? 0) & 1) !== 0,
            'addRevInfo' => $this->extractPdfBooleanToken($dictionary, 'AddRevInfo'),
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function extractPdfSignatureLockPolicies(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $policies = [];
        $visitedFields = [];
        $acroForm = $this->extractPdfAcroFormDictionary($pdfBytes, $catalog);

        if ($acroForm !== null) {
            foreach ($this->extractPdfReferenceArray($acroForm, 'Fields') as $reference) {
                $this->collectPdfSignatureLockPolicyFields($policies, $objects, $reference, $visitedFields, 0);
            }
        }

        foreach ($objects as $reference => $body) {
            if ($this->extractPdfNameToken($body, 'FT') === 'Sig'
                && ($this->extractPdfValueForName($body, 'SV') !== null || $this->extractPdfValueForName($body, 'Lock') !== null)
            ) {
                $this->addPdfSignatureLockPolicyFromField($policies, $reference . ' R', $body, $objects);
            }
        }

        $policies = array_values($policies);
        usort(
            $policies,
            static fn (array $a, array $b): int => [
                $a['fieldName'] ?? '',
                $a['fieldObject'] ?? '',
                $a['seedValueObject'] ?? '',
                $a['fieldLockObject'] ?? '',
            ] <=> [
                $b['fieldName'] ?? '',
                $b['fieldObject'] ?? '',
                $b['seedValueObject'] ?? '',
                $b['fieldLockObject'] ?? '',
            ]
        );

        return $policies;
    }

    /**
     * @param array<string, array<string, mixed>> $policies
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfSignatureLockPolicyFields(array &$policies, array $objects, string $reference, array &$visited, int $depth): void
    {
        if ($depth > 16 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }

        $visited[$reference] = true;
        $body = $objects[$reference];
        $this->addPdfSignatureLockPolicyFromField($policies, $reference . ' R', $body, $objects);

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfSignatureLockPolicyFields($policies, $objects, $kidReference, $visited, $depth + 1);
        }
    }

    /**
     * @param array<string, array<string, mixed>> $policies
     * @param array<string, string> $objects
     */
    private function addPdfSignatureLockPolicyFromField(array &$policies, string $fieldReference, string $fieldDictionary, array $objects): void
    {
        if ($this->extractPdfNameToken($fieldDictionary, 'FT') !== 'Sig') {
            return;
        }

        $seedValue = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($fieldDictionary, 'SV'), $objects);
        $fieldLock = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($fieldDictionary, 'Lock'), $objects);
        $seedDictionary = $seedValue['dictionary'];
        $fieldLockDictionary = $fieldLock['dictionary'];
        $seedLockDocument = $seedDictionary === null ? null : $this->extractPdfNameToken($seedDictionary, 'LockDocument');
        if ($seedLockDocument === null && $fieldLockDictionary === null) {
            return;
        }

        $fieldName = $this->extractPdfStringOrNameValue($fieldDictionary, 'T')
            ?? $this->extractPdfStringOrNameValue($fieldDictionary, 'TU')
            ?? $this->extractPdfStringOrNameValue($fieldDictionary, 'TM');
        $fieldLockAction = $fieldLockDictionary === null ? null : $this->extractPdfNameToken($fieldLockDictionary, 'Action');
        $fieldLockFields = $fieldLockDictionary === null ? [] : $this->extractPdfStringArrayValue($fieldLockDictionary, 'Fields');
        $issues = $this->pdfSignatureLockPolicyIssues($seedLockDocument, $fieldLockAction, $fieldLockFields);

        $policy = [
            'fieldName' => $fieldName === '' ? null : $fieldName,
            'fieldObject' => $fieldReference,
            'seedValueObject' => $seedDictionary === null ? null : $seedValue['object'],
            'seedLockDocument' => $seedLockDocument,
            'fieldLockObject' => $fieldLockDictionary === null ? null : $fieldLock['object'],
            'fieldLockType' => $fieldLockDictionary === null ? null : $this->extractPdfNameToken($fieldLockDictionary, 'Type'),
            'fieldLockAction' => $fieldLockAction,
            'fieldLockFields' => $fieldLockFields,
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'issues' => $issues,
        ];
        $key = ($policy['fieldObject'] ?? '') . "\0" . ($policy['seedValueObject'] ?? '') . "\0" . ($policy['fieldLockObject'] ?? '');
        $policies[$key] = $policy;
    }

    /**
     * @param list<string> $fieldLockFields
     * @return list<string>
     */
    private function pdfSignatureLockPolicyIssues(?string $seedLockDocument, ?string $fieldLockAction, array $fieldLockFields): array
    {
        $issues = [];
        if ($seedLockDocument !== null
            && !in_array($seedLockDocument, ['NoChanges', 'FormFilling', 'FormFillingAndAnnotations'], true)
        ) {
            $issues[] = 'seed-lock-unknown-document-policy';
        }

        if ($fieldLockAction !== null && !in_array($fieldLockAction, ['All', 'Include', 'Exclude'], true)) {
            $issues[] = 'field-lock-unknown-action';
        }
        if (($fieldLockAction === 'Include' || $fieldLockAction === 'Exclude') && $fieldLockFields === []) {
            $issues[] = 'field-lock-missing-fields';
        }
        if ($fieldLockAction === null && $fieldLockFields !== []) {
            $issues[] = 'field-lock-missing-action';
        }
        if ($seedLockDocument === 'NoChanges'
            && $fieldLockAction !== null
            && $fieldLockAction !== 'All'
            && $fieldLockFields !== []
        ) {
            $issues[] = 'seed-lock-no-changes-overrides-field-list';
        }

        return $issues;
    }

    /**
     * @param list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>}> $signatures
     * @param list<array{permission:string, signatureObject:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>}> $catalogPermissions
     * @param list<array<string, mixed>> $signatureLockPolicies
     * @return list<array{source:string, permission:string|null, fieldName:string|null, fieldObject:string|null, signatureObject:string|null, transformAction:string|null, transformFields:list<string>, fieldLockObject:string|null, fieldLockAction:string|null, fieldLockFields:list<string>, matchedFieldLock:bool, reviewStatus:string, issues:list<string>}>
     */
    private function summarizePdfSignatureFieldMdpPolicies(array $signatures, array $catalogPermissions, array $signatureLockPolicies): array
    {
        $locksByFieldObject = [];
        $locksByFieldName = [];
        foreach ($signatureLockPolicies as $policy) {
            if (is_string($policy['fieldObject'] ?? null) && $policy['fieldObject'] !== '') {
                $locksByFieldObject[$policy['fieldObject']] = $policy;
            }
            if (is_string($policy['fieldName'] ?? null) && $policy['fieldName'] !== '') {
                $locksByFieldName[$policy['fieldName']] = $policy;
            }
        }

        $policies = [];
        $signatureFieldMdpObjects = [];
        foreach ($signatures as $signature) {
            $fieldName = is_string($signature['fieldName'] ?? null) && $signature['fieldName'] !== '' ? $signature['fieldName'] : null;
            $fieldObject = is_string($signature['fieldObject'] ?? null) && $signature['fieldObject'] !== '' ? $signature['fieldObject'] : null;
            $signatureObject = is_string($signature['signatureObject'] ?? null) && $signature['signatureObject'] !== '' ? $signature['signatureObject'] : null;
            $lockPolicy = null;
            if ($fieldObject !== null && isset($locksByFieldObject[$fieldObject])) {
                $lockPolicy = $locksByFieldObject[$fieldObject];
            } elseif ($fieldName !== null && isset($locksByFieldName[$fieldName])) {
                $lockPolicy = $locksByFieldName[$fieldName];
            }

            foreach (($signature['referenceTransforms'] ?? []) as $transform) {
                if (!is_array($transform) || ($transform['transformMethod'] ?? null) !== 'FieldMDP') {
                    continue;
                }
                if ($signatureObject !== null) {
                    $signatureFieldMdpObjects[$signatureObject] = true;
                }

                $policies[] = $this->summarizePdfSignatureFieldMdpPolicyEntry(
                    'signature',
                    null,
                    $fieldName,
                    $fieldObject,
                    $signatureObject,
                    $transform,
                    $lockPolicy
                );
            }
        }

        foreach ($catalogPermissions as $permission) {
            $signatureObject = is_string($permission['signatureObject'] ?? null) && $permission['signatureObject'] !== '' ? $permission['signatureObject'] : null;
            foreach (($permission['referenceTransforms'] ?? []) as $transform) {
                if (!is_array($transform) || ($transform['transformMethod'] ?? null) !== 'FieldMDP') {
                    continue;
                }
                if ($signatureObject !== null && isset($signatureFieldMdpObjects[$signatureObject])) {
                    continue;
                }

                $policies[] = $this->summarizePdfSignatureFieldMdpPolicyEntry(
                    'catalog-permission',
                    is_string($permission['permission'] ?? null) && $permission['permission'] !== '' ? $permission['permission'] : null,
                    null,
                    null,
                    $signatureObject,
                    $transform,
                    null
                );
            }
        }

        usort(
            $policies,
            static fn (array $a, array $b): int => [
                $a['source'],
                $a['permission'] ?? '',
                $a['fieldName'] ?? '',
                $a['fieldObject'] ?? '',
                $a['signatureObject'] ?? '',
                $a['transformAction'] ?? '',
            ] <=> [
                $b['source'],
                $b['permission'] ?? '',
                $b['fieldName'] ?? '',
                $b['fieldObject'] ?? '',
                $b['signatureObject'] ?? '',
                $b['transformAction'] ?? '',
            ]
        );

        return $policies;
    }

    /**
     * @param array{action?:string|null, fields?:list<string>} $transform
     * @param array<string, mixed>|null $lockPolicy
     * @return array{source:string, permission:string|null, fieldName:string|null, fieldObject:string|null, signatureObject:string|null, transformAction:string|null, transformFields:list<string>, fieldLockObject:string|null, fieldLockAction:string|null, fieldLockFields:list<string>, matchedFieldLock:bool, reviewStatus:string, issues:list<string>}
     */
    private function summarizePdfSignatureFieldMdpPolicyEntry(
        string $source,
        ?string $permission,
        ?string $fieldName,
        ?string $fieldObject,
        ?string $signatureObject,
        array $transform,
        ?array $lockPolicy
    ): array {
        $transformAction = is_string($transform['action'] ?? null) && $transform['action'] !== '' ? $transform['action'] : null;
        $transformFields = [];
        foreach (($transform['fields'] ?? []) as $field) {
            if (is_string($field) && $field !== '') {
                $transformFields[] = $field;
            }
        }

        $fieldLockFields = [];
        if (is_array($lockPolicy)) {
            foreach (($lockPolicy['fieldLockFields'] ?? []) as $field) {
                if (is_string($field) && $field !== '') {
                    $fieldLockFields[] = $field;
                }
            }
        }

        $issues = $this->pdfSignatureFieldMdpPolicyIssues($transformAction, $transformFields, $lockPolicy, $fieldLockFields);

        return [
            'source' => $source,
            'permission' => $permission,
            'fieldName' => $fieldName,
            'fieldObject' => $fieldObject,
            'signatureObject' => $signatureObject,
            'transformAction' => $transformAction,
            'transformFields' => $transformFields,
            'fieldLockObject' => is_array($lockPolicy) && is_string($lockPolicy['fieldLockObject'] ?? null) && $lockPolicy['fieldLockObject'] !== '' ? $lockPolicy['fieldLockObject'] : null,
            'fieldLockAction' => is_array($lockPolicy) && is_string($lockPolicy['fieldLockAction'] ?? null) && $lockPolicy['fieldLockAction'] !== '' ? $lockPolicy['fieldLockAction'] : null,
            'fieldLockFields' => $fieldLockFields,
            'matchedFieldLock' => is_array($lockPolicy),
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'issues' => $issues,
        ];
    }

    /**
     * @param list<string> $transformFields
     * @param array<string, mixed>|null $lockPolicy
     * @param list<string> $fieldLockFields
     * @return list<string>
     */
    private function pdfSignatureFieldMdpPolicyIssues(?string $transformAction, array $transformFields, ?array $lockPolicy, array $fieldLockFields): array
    {
        $issues = [];
        if ($transformAction === null) {
            $issues[] = 'field-mdp-missing-transform-action';
        } elseif (!in_array($transformAction, ['All', 'Include', 'Exclude'], true)) {
            $issues[] = 'field-mdp-unknown-transform-action';
        }
        if (($transformAction === 'Include' || $transformAction === 'Exclude') && $transformFields === []) {
            $issues[] = 'field-mdp-missing-transform-fields';
        }
        if ($transformAction === 'All' && $transformFields !== []) {
            $issues[] = 'field-mdp-all-transform-has-fields';
        }

        if ($lockPolicy === null) {
            $issues[] = 'field-mdp-missing-field-lock';

            return $issues;
        }

        $fieldLockAction = is_string($lockPolicy['fieldLockAction'] ?? null) && $lockPolicy['fieldLockAction'] !== '' ? $lockPolicy['fieldLockAction'] : null;
        if ($transformAction !== null && $fieldLockAction !== $transformAction) {
            $issues[] = 'field-mdp-field-lock-action-mismatch';
        }

        if ($this->canonicalPdfFieldNames($fieldLockFields) !== $this->canonicalPdfFieldNames($transformFields)) {
            $issues[] = 'field-mdp-field-lock-fields-mismatch';
        }

        return $issues;
    }

    /**
     * @param list<string> $fields
     * @return list<string>
     */
    private function canonicalPdfFieldNames(array $fields): array
    {
        $canonical = [];
        foreach ($fields as $field) {
            if ($field !== '') {
                $canonical[$field] = true;
            }
        }

        $names = array_keys($canonical);
        sort($names, SORT_STRING);

        return $names;
    }

    /**
     * @return list<string>
     */
    private function pdfSignatureSeedValueFlagNames(int $flags): array
    {
        $definitions = [
            1 => 'filter',
            2 => 'subFilter',
            4 => 'minimumVersion',
            8 => 'reasons',
            16 => 'legalAttestation',
            32 => 'addRevInfo',
            64 => 'digestMethod',
        ];
        $names = [];
        foreach ($definitions as $bit => $name) {
            if (($flags & $bit) !== 0) {
                $names[] = $name;
            }
        }

        return $names;
    }

    /**
     * @param array<string, array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, filter:string|null, subFilter:string|null, name:string|null, reason:string|null, location:string|null, contactInfo:string|null, signingTime:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null, contentsSha256:string|null, contentsSkipped:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>}> $signatures
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfSignatureFields(array &$signatures, array $objects, string $reference, array &$visited, int $depth): void
    {
        if ($depth > 16 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }

        $visited[$reference] = true;
        $body = $objects[$reference];
        $this->addPdfSignatureFromField($signatures, $reference . ' R', $body, $objects);

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfSignatureFields($signatures, $objects, $kidReference, $visited, $depth + 1);
        }
    }

    /**
     * @param array<string, array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, filter:string|null, subFilter:string|null, name:string|null, reason:string|null, location:string|null, contactInfo:string|null, signingTime:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null, contentsSha256:string|null, contentsSkipped:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>}> $signatures
     * @param array<string, string> $objects
     */
    private function addPdfSignatureFromField(array &$signatures, string $fieldReference, string $fieldDictionary, array $objects): void
    {
        if ($this->extractPdfNameToken($fieldDictionary, 'FT') !== 'Sig') {
            return;
        }

        $fieldName = $this->extractPdfStringOrNameValue($fieldDictionary, 'T')
            ?? $this->extractPdfStringOrNameValue($fieldDictionary, 'TU')
            ?? $this->extractPdfStringOrNameValue($fieldDictionary, 'TM');
        $value = $this->extractPdfValueForName($fieldDictionary, 'V');
        if ($value === null) {
            return;
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body !== null) {
                $this->addPdfSignatureEntry(
                    $signatures,
                    $this->summarizePdfSignatureDictionary($body, $fieldName, $fieldReference, $value['value'], $objects)
                );
            }

            return;
        }

        if ($value['kind'] === 'dictionary') {
            $this->addPdfSignatureEntry(
                $signatures,
                $this->summarizePdfSignatureDictionary($value['value'], $fieldName, $fieldReference, 'inline', $objects)
            );
        }
    }

    /**
     * @param array<string, array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, filter:string|null, subFilter:string|null, name:string|null, reason:string|null, location:string|null, contactInfo:string|null, signingTime:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null, contentsSha256:string|null, contentsSkipped:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>}> $signatures
     * @param array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, filter:string|null, subFilter:string|null, name:string|null, reason:string|null, location:string|null, contactInfo:string|null, signingTime:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null, contentsSha256:string|null, contentsSkipped:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>} $entry
     */
    private function addPdfSignatureEntry(array &$signatures, array $entry): void
    {
        $key = $entry['signatureObject'] ?? $entry['fieldObject'] ?? hash('sha256', json_encode($entry) ?: serialize($entry));
        if (
            !isset($signatures[$key])
            || (($signatures[$key]['fieldName'] ?? null) === null && ($entry['fieldName'] ?? null) !== null)
        ) {
            $signatures[$key] = $entry;
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, filter:string|null, subFilter:string|null, name:string|null, reason:string|null, location:string|null, contactInfo:string|null, signingTime:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null, contentsSha256:string|null, contentsSkipped:string|null, referenceTransforms:list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>}
     */
    private function summarizePdfSignatureDictionary(
        string $dictionary,
        ?string $fieldName,
        ?string $fieldObject,
        ?string $signatureObject,
        array $objects
    ): array {
        $byteRange = $this->extractPdfIntegerArrayToken($dictionary, 'ByteRange');
        $contents = $this->summarizePdfSignatureContents($dictionary);

        return [
            'fieldName' => $fieldName === '' ? null : $fieldName,
            'fieldObject' => $fieldObject,
            'signatureObject' => $signatureObject,
            'filter' => $this->extractPdfStringOrNameValue($dictionary, 'Filter'),
            'subFilter' => $this->extractPdfStringOrNameValue($dictionary, 'SubFilter'),
            'name' => $this->extractPdfStringOrNameValue($dictionary, 'Name'),
            'reason' => $this->extractPdfStringOrNameValue($dictionary, 'Reason'),
            'location' => $this->extractPdfStringOrNameValue($dictionary, 'Location'),
            'contactInfo' => $this->extractPdfStringOrNameValue($dictionary, 'ContactInfo'),
            'signingTime' => $this->extractPdfStringOrNameValue($dictionary, 'M'),
            'byteRange' => $byteRange,
            'byteRangeSegmentCount' => intdiv(count($byteRange), 2),
            'coveredBytes' => $this->coveredBytesForPdfSignatureRange($byteRange),
            'contentsBytes' => $contents['bytes'],
            'contentsSha256' => $contents['sha256'],
            'contentsSkipped' => $contents['skipped'],
            'referenceTransforms' => $this->extractPdfSignatureReferenceTransforms($dictionary, $objects),
        ];
    }

    /**
     * @return array{bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function summarizePdfSignatureContents(string $dictionary): array
    {
        $hex = $this->extractPdfByteStringHexValue($dictionary, 'Contents');
        if ($hex === null) {
            return ['bytes' => null, 'sha256' => null, 'skipped' => null];
        }

        $bytes = hex2bin($hex);
        if ($bytes === false) {
            return ['bytes' => null, 'sha256' => null, 'skipped' => null];
        }

        if (strlen($bytes) > self::MAX_SIGNATURE_CONTENTS_BYTES) {
            return ['bytes' => strlen($bytes), 'sha256' => null, 'skipped' => 'too-large'];
        }

        return ['bytes' => strlen($bytes), 'sha256' => hash('sha256', $bytes), 'skipped' => null];
    }

    /**
     * @param list<int> $byteRange
     */
    private function coveredBytesForPdfSignatureRange(array $byteRange): ?int
    {
        if (count($byteRange) < 2 || count($byteRange) % 2 !== 0) {
            return null;
        }

        $coveredBytes = 0;
        for ($index = 1; $index < count($byteRange); $index += 2) {
            $coveredBytes += $byteRange[$index];
        }

        return $coveredBytes;
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}>
     */
    private function extractPdfSignatureReferenceTransforms(string $dictionary, array $objects): array
    {
        $array = $this->extractPdfArrayOrReferenceValue($dictionary, 'Reference', $objects);
        if ($array === null) {
            return [];
        }

        $transforms = [];
        $cursor = str_starts_with($array, '[') ? 1 : 0;
        $length = strlen($array);
        if (str_ends_with($array, ']')) {
            $length--;
        }

        while ($cursor < $length && count($transforms) < 16) {
            $value = $this->parsePdfValueAt($array, $cursor);
            if ($value === null) {
                $cursor++;
                continue;
            }

            $summary = null;
            if ($value['kind'] === 'dictionary') {
                $summary = $this->summarizePdfSignatureReferenceTransform($value['value'], $objects);
            } elseif ($value['kind'] === 'reference') {
                $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
                if ($body !== null) {
                    $summary = $this->summarizePdfSignatureReferenceTransform($body, $objects);
                }
            }
            if ($summary !== null) {
                $transforms[] = $summary;
            }

            $cursor = max($cursor + 1, min($length, $value['next']));
        }

        return $transforms;
    }

    /**
     * @param array<string, string> $objects
     * @return array{transformMethod:string|null, transformParamsType:string|null, permissions:int|null, action:string|null, fields:list<string>}|null
     */
    private function summarizePdfSignatureReferenceTransform(string $dictionary, array $objects): ?array
    {
        $params = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'TransformParams', $objects);
        $transformMethod = $this->extractPdfNameToken($dictionary, 'TransformMethod');
        if ($transformMethod === null && $params === null) {
            return null;
        }

        return [
            'transformMethod' => $transformMethod,
            'transformParamsType' => $params === null ? null : $this->extractPdfNameToken($params, 'Type'),
            'permissions' => $params === null ? null : $this->extractPdfIntegerToken($params, 'P'),
            'action' => $params === null ? null : $this->extractPdfNameToken($params, 'Action'),
            'fields' => $params === null ? [] : $this->extractPdfStringArrayValue($params, 'Fields'),
        ];
    }

    /**
     * @param list<array{subFilter:string|null}> $signatures
     * @return array<string, int>
     */
    private function summarizePdfSignatureSubFilters(array $signatures): array
    {
        $subFilters = [];
        foreach ($signatures as $signature) {
            $subFilter = $signature['subFilter'] ?? null;
            if (!is_string($subFilter) || $subFilter === '') {
                continue;
            }

            $subFilters[$subFilter] = ($subFilters[$subFilter] ?? 0) + 1;
        }

        ksort($subFilters);

        return $subFilters;
    }

    /**
     * @param list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null}> $signatures
     * @param list<array{permission:string, signatureObject:string|null, byteRange:list<int>, byteRangeSegmentCount:int, coveredBytes:int|null, contentsBytes:int|null}> $catalogPermissions
     * @return list<array{source:string, permission:string|null, fieldName:string|null, fieldObject:string|null, signatureObject:string|null, byteRange:list<int>, segmentCount:int, coveredBytes:int|null, fileBytes:int, gapCount:int, gapBytes:int, firstGapOffset:int|null, firstGapLength:int|null, startsAtZero:bool, coversToEnd:bool|null, ordered:bool, nonOverlapping:bool, fitsFile:bool|null, contentsBytes:int|null, contentsFitsFirstGap:bool|null, reviewStatus:string, issues:list<string>}>
     */
    private function summarizePdfSignatureByteRangePolicy(array $signatures, array $catalogPermissions, int $fileBytes): array
    {
        $policies = [];
        foreach ($signatures as $signature) {
            $policies[] = $this->summarizePdfSignatureByteRangePolicyEntry('signature', null, $signature, $fileBytes);
        }

        foreach ($catalogPermissions as $permission) {
            $permissionName = is_string($permission['permission'] ?? null) && $permission['permission'] !== ''
                ? $permission['permission']
                : null;
            $policies[] = $this->summarizePdfSignatureByteRangePolicyEntry('catalog-permission', $permissionName, $permission, $fileBytes);
        }

        usort(
            $policies,
            static fn (array $a, array $b): int => [
                $a['source'],
                $a['permission'] ?? '',
                $a['fieldName'] ?? '',
                $a['signatureObject'] ?? '',
            ] <=> [
                $b['source'],
                $b['permission'] ?? '',
                $b['fieldName'] ?? '',
                $b['signatureObject'] ?? '',
            ]
        );

        return $policies;
    }

    /**
     * @param array{permission?:string, fieldName?:string|null, fieldObject?:string|null, signatureObject?:string|null, byteRange?:list<int>, byteRangeSegmentCount?:int, coveredBytes?:int|null, contentsBytes?:int|null} $signature
     * @return array{source:string, permission:string|null, fieldName:string|null, fieldObject:string|null, signatureObject:string|null, byteRange:list<int>, segmentCount:int, coveredBytes:int|null, fileBytes:int, gapCount:int, gapBytes:int, firstGapOffset:int|null, firstGapLength:int|null, startsAtZero:bool, coversToEnd:bool|null, ordered:bool, nonOverlapping:bool, fitsFile:bool|null, contentsBytes:int|null, contentsFitsFirstGap:bool|null, reviewStatus:string, issues:list<string>}
     */
    private function summarizePdfSignatureByteRangePolicyEntry(string $source, ?string $permission, array $signature, int $fileBytes): array
    {
        $byteRange = [];
        foreach (($signature['byteRange'] ?? []) as $value) {
            if (is_int($value)) {
                $byteRange[] = $value;
            }
        }

        $issues = [];
        $rangeCount = count($byteRange);
        $validPairCount = $rangeCount >= 2 && $rangeCount % 2 === 0;
        $startsAtZero = $validPairCount && $byteRange[0] === 0;
        $coversToEnd = null;
        $ordered = true;
        $nonOverlapping = true;
        $fitsFile = $validPairCount ? true : null;
        $gapCount = 0;
        $gapBytes = 0;
        $firstGapOffset = null;
        $firstGapLength = null;
        $previousOffset = null;
        $previousEnd = null;
        $lastEnd = null;

        if ($rangeCount === 0) {
            $issues[] = 'missing-byte-range';
        } elseif (!$validPairCount) {
            $issues[] = 'invalid-pair-count';
        } else {
            for ($index = 0; $index < $rangeCount; $index += 2) {
                $offset = $byteRange[$index];
                $length = $byteRange[$index + 1];
                if ($offset < 0 || $length < 0) {
                    $issues[] = 'negative-range';
                    $fitsFile = false;
                }
                $end = $offset + $length;
                if ($offset > $fileBytes || $end > $fileBytes) {
                    $fitsFile = false;
                }
                if ($previousOffset !== null && $offset < $previousOffset) {
                    $ordered = false;
                }
                if ($previousEnd !== null) {
                    if ($offset < $previousEnd) {
                        $nonOverlapping = false;
                    } elseif ($offset > $previousEnd) {
                        $gapLength = $offset - $previousEnd;
                        $gapCount++;
                        $gapBytes += $gapLength;
                        if ($firstGapOffset === null) {
                            $firstGapOffset = $previousEnd;
                            $firstGapLength = $gapLength;
                        }
                    }
                }
                $previousOffset = $offset;
                $previousEnd = $end;
                $lastEnd = $end;
            }

            $coversToEnd = $lastEnd === $fileBytes;
            if (!$startsAtZero) {
                $issues[] = 'does-not-start-at-zero';
            }
            if ($fitsFile === false) {
                $issues[] = 'out-of-bounds';
            }
            if (!$ordered) {
                $issues[] = 'unordered-ranges';
            }
            if (!$nonOverlapping) {
                $issues[] = 'overlapping-ranges';
            }
            if ($gapCount === 0 && ($signature['contentsBytes'] ?? null) !== null) {
                $issues[] = 'missing-contents-gap';
            }
            if ($coversToEnd === false) {
                $issues[] = 'does-not-cover-to-end';
            }
        }

        $contentsBytes = is_int($signature['contentsBytes'] ?? null) ? $signature['contentsBytes'] : null;
        $contentsFitsFirstGap = null;
        if ($contentsBytes !== null && $firstGapLength !== null) {
            $contentsFitsFirstGap = $contentsBytes <= $firstGapLength;
            if (!$contentsFitsFirstGap) {
                $issues[] = 'contents-exceeds-gap';
            }
        }

        $issues = array_values(array_unique($issues));

        return [
            'source' => $source,
            'permission' => $permission,
            'fieldName' => is_string($signature['fieldName'] ?? null) && $signature['fieldName'] !== '' ? $signature['fieldName'] : null,
            'fieldObject' => is_string($signature['fieldObject'] ?? null) && $signature['fieldObject'] !== '' ? $signature['fieldObject'] : null,
            'signatureObject' => is_string($signature['signatureObject'] ?? null) && $signature['signatureObject'] !== '' ? $signature['signatureObject'] : null,
            'byteRange' => $byteRange,
            'segmentCount' => is_int($signature['byteRangeSegmentCount'] ?? null) ? $signature['byteRangeSegmentCount'] : intdiv($rangeCount, 2),
            'coveredBytes' => is_int($signature['coveredBytes'] ?? null) ? $signature['coveredBytes'] : $this->coveredBytesForPdfSignatureRange($byteRange),
            'fileBytes' => $fileBytes,
            'gapCount' => $gapCount,
            'gapBytes' => $gapBytes,
            'firstGapOffset' => $firstGapOffset,
            'firstGapLength' => $firstGapLength,
            'startsAtZero' => $startsAtZero,
            'coversToEnd' => $coversToEnd,
            'ordered' => $ordered,
            'nonOverlapping' => $nonOverlapping,
            'fitsFile' => $fitsFile,
            'contentsBytes' => $contentsBytes,
            'contentsFitsFirstGap' => $contentsFitsFirstGap,
            'reviewStatus' => $this->pdfSignatureByteRangeReviewStatus($issues),
            'issues' => $issues,
        ];
    }

    /**
     * @param list<string> $issues
     */
    private function pdfSignatureByteRangeReviewStatus(array $issues): string
    {
        if ($issues === []) {
            return 'ok';
        }
        if (in_array('missing-byte-range', $issues, true)) {
            return 'missing-byte-range';
        }
        foreach (['invalid-pair-count', 'negative-range', 'out-of-bounds', 'unordered-ranges', 'overlapping-ranges'] as $issue) {
            if (in_array($issue, $issues, true)) {
                return 'invalid';
            }
        }

        return 'review';
    }

    /**
     * @param list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, signingTime:string|null, byteRange:list<int>}> $signatures
     * @param list<array{permission:string, signatureObject:string|null, signingTime:string|null, byteRange:list<int>}> $catalogPermissions
     * @param list<array{revision:int, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, startxref:int|null, id:list<string>}> $trailerRevisions
     * @return list<array{source:string, permission:string|null, fieldName:string|null, fieldObject:string|null, signatureObject:string|null, signingTime:string|null, byteRangeEnd:int|null, revision:int|null, revisionStartXref:int|null, revisionPrev:int|null, revisionRoot:string|null, revisionInfo:string|null, revisionEncrypt:string|null, revisionByteEnd:int|null, coversRevisionEnd:bool|null, latestRevision:int|null, laterRevisions:int, reviewStatus:string}>
     */
    private function summarizePdfSignatureRevisionMetadata(
        array $signatures,
        array $catalogPermissions,
        array $trailerRevisions,
        string $pdfBytes
    ): array {
        $revisionBoundaries = $this->pdfTrailerRevisionBoundaries($pdfBytes, $trailerRevisions);
        $metadata = [];
        foreach ($signatures as $signature) {
            $metadata[] = $this->summarizePdfSignatureRevisionMetadataEntry(
                'signature',
                null,
                $signature,
                $revisionBoundaries
            );
        }

        foreach ($catalogPermissions as $permission) {
            $permissionName = is_string($permission['permission'] ?? null) && $permission['permission'] !== ''
                ? $permission['permission']
                : null;
            $metadata[] = $this->summarizePdfSignatureRevisionMetadataEntry(
                'catalog-permission',
                $permissionName,
                $permission,
                $revisionBoundaries
            );
        }

        usort(
            $metadata,
            static fn (array $a, array $b): int => [
                $a['source'],
                $a['permission'] ?? '',
                $a['fieldName'] ?? '',
                $a['signatureObject'] ?? '',
            ] <=> [
                $b['source'],
                $b['permission'] ?? '',
                $b['fieldName'] ?? '',
                $b['signatureObject'] ?? '',
            ]
        );

        return $metadata;
    }

    /**
     * @param array{permission?:string, fieldName?:string|null, fieldObject?:string|null, signatureObject?:string|null, signingTime?:string|null, byteRange?:list<int>} $signature
     * @param list<array{revision:int, startxref:int|null, prev:int|null, root:string|null, info:string|null, encrypt:string|null, revisionByteEnd:int|null}> $revisionBoundaries
     * @return array{source:string, permission:string|null, fieldName:string|null, fieldObject:string|null, signatureObject:string|null, signingTime:string|null, byteRangeEnd:int|null, revision:int|null, revisionStartXref:int|null, revisionPrev:int|null, revisionRoot:string|null, revisionInfo:string|null, revisionEncrypt:string|null, revisionByteEnd:int|null, coversRevisionEnd:bool|null, latestRevision:int|null, laterRevisions:int, reviewStatus:string}
     */
    private function summarizePdfSignatureRevisionMetadataEntry(
        string $source,
        ?string $permission,
        array $signature,
        array $revisionBoundaries
    ): array {
        $byteRangeEnd = $this->pdfSignatureByteRangeEnd($signature['byteRange'] ?? []);
        $latestRevision = null;
        if ($revisionBoundaries !== []) {
            $latest = $revisionBoundaries[count($revisionBoundaries) - 1];
            $latestRevision = $latest['revision'];
        }

        $matchedRevision = null;
        if ($byteRangeEnd !== null) {
            foreach ($revisionBoundaries as $revision) {
                if (($revision['revisionByteEnd'] ?? null) === null) {
                    continue;
                }
                if ($byteRangeEnd <= $revision['revisionByteEnd']) {
                    $matchedRevision = $revision;
                    break;
                }
            }
        }

        $revisionNumber = is_array($matchedRevision) ? $matchedRevision['revision'] : null;
        $revisionByteEnd = is_array($matchedRevision) ? $matchedRevision['revisionByteEnd'] : null;
        $coversRevisionEnd = $byteRangeEnd !== null && $revisionByteEnd !== null
            ? $byteRangeEnd === $revisionByteEnd
            : null;
        $laterRevisions = $revisionNumber !== null && $latestRevision !== null
            ? max(0, $latestRevision - $revisionNumber)
            : 0;

        return [
            'source' => $source,
            'permission' => $permission,
            'fieldName' => is_string($signature['fieldName'] ?? null) && $signature['fieldName'] !== '' ? $signature['fieldName'] : null,
            'fieldObject' => is_string($signature['fieldObject'] ?? null) && $signature['fieldObject'] !== '' ? $signature['fieldObject'] : null,
            'signatureObject' => is_string($signature['signatureObject'] ?? null) && $signature['signatureObject'] !== '' ? $signature['signatureObject'] : null,
            'signingTime' => is_string($signature['signingTime'] ?? null) && $signature['signingTime'] !== '' ? $signature['signingTime'] : null,
            'byteRangeEnd' => $byteRangeEnd,
            'revision' => $revisionNumber,
            'revisionStartXref' => is_array($matchedRevision) ? $matchedRevision['startxref'] : null,
            'revisionPrev' => is_array($matchedRevision) ? $matchedRevision['prev'] : null,
            'revisionRoot' => is_array($matchedRevision) ? $matchedRevision['root'] : null,
            'revisionInfo' => is_array($matchedRevision) ? $matchedRevision['info'] : null,
            'revisionEncrypt' => is_array($matchedRevision) ? $matchedRevision['encrypt'] : null,
            'revisionByteEnd' => $revisionByteEnd,
            'coversRevisionEnd' => $coversRevisionEnd,
            'latestRevision' => $latestRevision,
            'laterRevisions' => $laterRevisions,
            'reviewStatus' => $this->pdfSignatureRevisionReviewStatus($byteRangeEnd, $matchedRevision, $coversRevisionEnd, $laterRevisions),
        ];
    }

    /**
     * @param list<array{revision:int, size:int|null, root:string|null, info:string|null, encrypt:string|null, prev:int|null, startxref:int|null, id:list<string>}> $trailerRevisions
     * @return list<array{revision:int, startxref:int|null, prev:int|null, root:string|null, info:string|null, encrypt:string|null, revisionByteEnd:int|null}>
     */
    private function pdfTrailerRevisionBoundaries(string $pdfBytes, array $trailerRevisions): array
    {
        preg_match_all('/%%EOF\b/', $pdfBytes, $matches, PREG_OFFSET_CAPTURE);
        $eofMatches = is_array($matches[0] ?? null) ? $matches[0] : [];
        $boundaries = [];
        foreach ($trailerRevisions as $index => $revision) {
            $eofOffset = isset($eofMatches[$index][1]) && is_int($eofMatches[$index][1])
                ? $eofMatches[$index][1]
                : null;
            $boundaries[] = [
                'revision' => $revision['revision'],
                'startxref' => $revision['startxref'],
                'prev' => $revision['prev'],
                'root' => $revision['root'],
                'info' => $revision['info'],
                'encrypt' => $revision['encrypt'],
                'revisionByteEnd' => $eofOffset === null ? null : $eofOffset + strlen('%%EOF'),
            ];
        }

        return $boundaries;
    }

    /**
     * @param list<int> $byteRange
     */
    private function pdfSignatureByteRangeEnd(array $byteRange): ?int
    {
        $rangeCount = count($byteRange);
        if ($rangeCount < 2 || $rangeCount % 2 !== 0) {
            return null;
        }

        $end = null;
        for ($index = 0; $index < $rangeCount; $index += 2) {
            $offset = $byteRange[$index];
            $length = $byteRange[$index + 1];
            if (!is_int($offset) || !is_int($length) || $offset < 0 || $length < 0) {
                return null;
            }
            $candidateEnd = $offset + $length;
            $end = $end === null ? $candidateEnd : max($end, $candidateEnd);
        }

        return $end;
    }

    private function pdfSignatureRevisionReviewStatus(?int $byteRangeEnd, mixed $matchedRevision, ?bool $coversRevisionEnd, int $laterRevisions): string
    {
        if ($byteRangeEnd === null) {
            return 'missing-byte-range';
        }
        if (!is_array($matchedRevision)) {
            return 'outside-revision-chain';
        }
        if ($laterRevisions > 0) {
            return 'superseded-by-incremental-update';
        }
        if ($coversRevisionEnd === false) {
            return 'revision-partial-coverage';
        }

        return 'current-revision';
    }

    /**
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $annotationAppearances
     * @return list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearanceCount:int, normalAppearanceCount:int, rolloverAppearanceCount:int, downAppearanceCount:int, streamCount:int, streamBytes:int, skippedStreamCount:int, appearanceStates:list<string>, appearanceObjects:list<string>, reviewStatus:string, issues:list<string>}>
     */
    private function summarizePdfAnnotationAppearancePolicy(array $annotationAppearances): array
    {
        if ($annotationAppearances === []) {
            return [];
        }

        $groups = [];
        foreach ($annotationAppearances as $appearance) {
            $key = implode("\0", [
                (string) ($appearance['page'] ?? 0),
                is_string($appearance['pageObject'] ?? null) ? $appearance['pageObject'] : '',
                is_string($appearance['annotationObject'] ?? null) ? $appearance['annotationObject'] : '',
            ]);
            $groups[$key][] = $appearance;
        }

        $summaries = [];
        foreach ($groups as $appearances) {
            $anchor = $appearances[0];
            $normalAppearances = [];
            $rolloverAppearanceCount = 0;
            $downAppearanceCount = 0;
            $streamCount = 0;
            $streamBytes = 0;
            $skippedStreamCount = 0;
            $appearanceStates = [];
            $normalAppearanceStates = [];
            $appearanceObjects = [];
            $normalMissingStream = false;
            $normalStreamSkipped = false;

            foreach ($appearances as $appearance) {
                $appearanceKind = is_string($appearance['appearance'] ?? null) ? $appearance['appearance'] : '';
                if ($appearanceKind === 'N') {
                    $normalAppearances[] = $appearance;
                } elseif ($appearanceKind === 'R') {
                    $rolloverAppearanceCount++;
                } elseif ($appearanceKind === 'D') {
                    $downAppearanceCount++;
                }

                if (is_string($appearance['stateName'] ?? null) && $appearance['stateName'] !== '') {
                    $appearanceStates[$appearance['stateName']] = true;
                    if ($appearanceKind === 'N') {
                        $normalAppearanceStates[$appearance['stateName']] = true;
                    }
                }
                if (is_string($appearance['appearanceObject'] ?? null) && $appearance['appearanceObject'] !== '') {
                    $appearanceObjects[$appearance['appearanceObject']] = true;
                }
                $streamSkipped = is_string($appearance['streamSkipped'] ?? null) && $appearance['streamSkipped'] !== '';
                if (is_int($appearance['streamBytes'] ?? null)) {
                    $streamCount++;
                    $streamBytes += $appearance['streamBytes'];
                } elseif ($appearanceKind === 'N' && !$streamSkipped) {
                    $normalMissingStream = true;
                }
                if ($streamSkipped) {
                    $skippedStreamCount++;
                    if ($appearanceKind === 'N') {
                        $normalStreamSkipped = true;
                    }
                }
            }

            $appearanceStateList = array_keys($appearanceStates);
            sort($appearanceStateList, SORT_STRING);
            $normalAppearanceStateList = array_keys($normalAppearanceStates);
            sort($normalAppearanceStateList, SORT_STRING);
            $appearanceObjectList = array_keys($appearanceObjects);
            usort($appearanceObjectList, fn (string $left, string $right): int => $this->pdfReferenceSortKey($left) <=> $this->pdfReferenceSortKey($right));

            $selectedState = is_string($anchor['selectedState'] ?? null) && $anchor['selectedState'] !== ''
                ? $anchor['selectedState']
                : null;
            $issues = [];
            if ($normalAppearances === []) {
                $issues[] = 'missing-normal-appearance';
            }
            if ($normalAppearanceStateList !== [] && $selectedState === null) {
                $issues[] = 'missing-selected-state';
            }
            if ($normalAppearanceStateList !== [] && $selectedState !== null && !in_array($selectedState, $normalAppearanceStateList, true)) {
                $issues[] = 'selected-state-appearance-missing';
            }
            if ($normalMissingStream) {
                $issues[] = 'missing-normal-appearance-stream';
            }
            if ($normalStreamSkipped) {
                $issues[] = 'normal-appearance-stream-skipped';
            }

            $summaries[] = [
                'page' => is_int($anchor['page'] ?? null) ? $anchor['page'] : 0,
                'pageObject' => is_string($anchor['pageObject'] ?? null) && $anchor['pageObject'] !== '' ? $anchor['pageObject'] : null,
                'annotationObject' => is_string($anchor['annotationObject'] ?? null) && $anchor['annotationObject'] !== '' ? $anchor['annotationObject'] : null,
                'subtype' => is_string($anchor['subtype'] ?? null) && $anchor['subtype'] !== '' ? $anchor['subtype'] : null,
                'fieldName' => is_string($anchor['fieldName'] ?? null) && $anchor['fieldName'] !== '' ? $anchor['fieldName'] : null,
                'selectedState' => $selectedState,
                'appearanceCount' => count($appearances),
                'normalAppearanceCount' => count($normalAppearances),
                'rolloverAppearanceCount' => $rolloverAppearanceCount,
                'downAppearanceCount' => $downAppearanceCount,
                'streamCount' => $streamCount,
                'streamBytes' => $streamBytes,
                'skippedStreamCount' => $skippedStreamCount,
                'appearanceStates' => $appearanceStateList,
                'appearanceObjects' => $appearanceObjectList,
                'reviewStatus' => $this->pdfAnnotationAppearancePolicyReviewStatus($issues),
                'issues' => $issues,
            ];
        }

        usort(
            $summaries,
            fn (array $a, array $b): int => [
                $a['page'],
                $this->pdfReferenceSortKey($a['annotationObject'] ?? ''),
                $a['subtype'] ?? '',
                $a['fieldName'] ?? '',
            ] <=> [
                $b['page'],
                $this->pdfReferenceSortKey($b['annotationObject'] ?? ''),
                $b['subtype'] ?? '',
                $b['fieldName'] ?? '',
            ]
        );

        return $summaries;
    }

    /**
     * @param list<string> $issues
     */
    private function pdfAnnotationAppearancePolicyReviewStatus(array $issues): string
    {
        if ($issues === []) {
            return 'ok';
        }
        if (in_array('missing-normal-appearance', $issues, true)) {
            return 'missing';
        }

        return 'review';
    }

    /**
     * @param list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, byteRange:list<int>}> $signatures
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $annotationAppearances
     * @return list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, page:int, pageObject:string|null, annotationObject:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, appearanceObjectOffset:int|null, appearanceObjectBytes:int|null, appearanceStreamOffset:int|null, appearanceStreamBytes:int|null, objectCoveredBySignature:bool|null, streamCoveredBySignature:bool|null, reviewStatus:string, issues:list<string>}>
     */
    private function summarizePdfSignatureAppearanceByteRanges(array $signatures, array $annotationAppearances, string $pdfBytes): array
    {
        if ($signatures === [] || $annotationAppearances === []) {
            return [];
        }

        $objectRanges = $this->pdfObjectByteRangesByReference($pdfBytes);
        $summaries = [];
        foreach ($signatures as $signature) {
            foreach ($annotationAppearances as $appearance) {
                if (($appearance['subtype'] ?? null) !== 'Widget') {
                    continue;
                }
                if (!$this->pdfSignatureMatchesAppearance($signature, $appearance)) {
                    continue;
                }

                $appearanceObject = is_string($appearance['appearanceObject'] ?? null) && $appearance['appearanceObject'] !== ''
                    ? $appearance['appearanceObject']
                    : null;
                $range = $appearanceObject === null ? null : ($objectRanges[$this->pdfReferenceKey($appearanceObject)] ?? null);
                $objectCovered = $this->pdfByteRangeCoversSpan(
                    $signature['byteRange'] ?? [],
                    $range['objectOffset'] ?? null,
                    $range['objectBytes'] ?? null
                );
                $streamCovered = $this->pdfByteRangeCoversSpan(
                    $signature['byteRange'] ?? [],
                    $range['streamOffset'] ?? null,
                    $range['streamBytes'] ?? null
                );
                $issues = $this->pdfSignatureAppearanceByteRangeIssues($signature['byteRange'] ?? [], $range, $objectCovered, $streamCovered);

                $summaries[] = [
                    'fieldName' => is_string($signature['fieldName'] ?? null) && $signature['fieldName'] !== '' ? $signature['fieldName'] : null,
                    'fieldObject' => is_string($signature['fieldObject'] ?? null) && $signature['fieldObject'] !== '' ? $signature['fieldObject'] : null,
                    'signatureObject' => is_string($signature['signatureObject'] ?? null) && $signature['signatureObject'] !== '' ? $signature['signatureObject'] : null,
                    'page' => is_int($appearance['page'] ?? null) ? $appearance['page'] : 0,
                    'pageObject' => is_string($appearance['pageObject'] ?? null) && $appearance['pageObject'] !== '' ? $appearance['pageObject'] : null,
                    'annotationObject' => is_string($appearance['annotationObject'] ?? null) && $appearance['annotationObject'] !== '' ? $appearance['annotationObject'] : null,
                    'appearance' => is_string($appearance['appearance'] ?? null) && $appearance['appearance'] !== '' ? $appearance['appearance'] : 'unknown',
                    'stateName' => is_string($appearance['stateName'] ?? null) && $appearance['stateName'] !== '' ? $appearance['stateName'] : null,
                    'appearanceObject' => $appearanceObject,
                    'appearanceObjectOffset' => is_array($range) ? $range['objectOffset'] : null,
                    'appearanceObjectBytes' => is_array($range) ? $range['objectBytes'] : null,
                    'appearanceStreamOffset' => is_array($range) ? $range['streamOffset'] : null,
                    'appearanceStreamBytes' => is_array($range) ? $range['streamBytes'] : null,
                    'objectCoveredBySignature' => $objectCovered,
                    'streamCoveredBySignature' => $streamCovered,
                    'reviewStatus' => $this->pdfSignatureAppearanceByteRangeReviewStatus($issues),
                    'issues' => $issues,
                ];
            }
        }

        usort(
            $summaries,
            static fn (array $a, array $b): int => [
                $a['fieldName'] ?? '',
                $a['fieldObject'] ?? '',
                $a['page'],
                $a['appearance'],
                $a['stateName'] ?? '',
                $a['appearanceObject'] ?? '',
            ] <=> [
                $b['fieldName'] ?? '',
                $b['fieldObject'] ?? '',
                $b['page'],
                $b['appearance'],
                $b['stateName'] ?? '',
                $b['appearanceObject'] ?? '',
            ]
        );

        return $summaries;
    }

    /**
     * @param list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null}> $signatures
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $annotationAppearances
     * @param list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, page:int, pageObject:string|null, annotationObject:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, objectCoveredBySignature:bool|null, streamCoveredBySignature:bool|null, reviewStatus:string, issues:list<string>}> $signatureAppearanceByteRanges
     * @return list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, page:int|null, pageObject:string|null, annotationObject:string|null, selectedState:string|null, normalAppearanceCount:int, appearanceStates:list<string>, appearanceObjects:list<string>, streamBytes:int, coveredAppearanceCount:int, reviewStatus:string, issues:list<string>}>
     */
    private function summarizePdfSignatureAppearancePolicy(array $signatures, array $annotationAppearances, array $signatureAppearanceByteRanges): array
    {
        if ($signatures === []) {
            return [];
        }

        $summaries = [];
        foreach ($signatures as $signature) {
            $matchingAppearances = [];
            $normalAppearances = [];
            foreach ($annotationAppearances as $appearance) {
                if (($appearance['subtype'] ?? null) !== 'Widget') {
                    continue;
                }
                if (!$this->pdfSignatureMatchesAppearance($signature, $appearance)) {
                    continue;
                }

                $matchingAppearances[] = $appearance;
                if (($appearance['appearance'] ?? null) === 'N') {
                    $normalAppearances[] = $appearance;
                }
            }

            $anchor = $normalAppearances[0] ?? ($matchingAppearances[0] ?? null);
            $appearanceStates = [];
            $appearanceObjects = [];
            $streamBytes = 0;
            $hasStateDictionary = false;
            $selectedState = null;
            $missingStream = false;
            $streamSkipped = false;

            foreach ($normalAppearances as $appearance) {
                if (is_string($appearance['stateName'] ?? null) && $appearance['stateName'] !== '') {
                    $hasStateDictionary = true;
                    $appearanceStates[] = $appearance['stateName'];
                }
                if (is_string($appearance['selectedState'] ?? null) && $appearance['selectedState'] !== '') {
                    $selectedState = $appearance['selectedState'];
                }
                if (is_string($appearance['appearanceObject'] ?? null) && $appearance['appearanceObject'] !== '') {
                    $appearanceObjects[] = $appearance['appearanceObject'];
                }
                if (is_int($appearance['streamBytes'] ?? null)) {
                    $streamBytes += $appearance['streamBytes'];
                } else {
                    $missingStream = true;
                }
                if (is_string($appearance['streamSkipped'] ?? null) && $appearance['streamSkipped'] !== '') {
                    $streamSkipped = true;
                }
            }

            $appearanceStates = array_values(array_unique($appearanceStates));
            sort($appearanceStates);
            $appearanceObjects = array_values(array_unique($appearanceObjects));
            usort($appearanceObjects, fn (string $left, string $right): int => $this->pdfReferenceSortKey($left) <=> $this->pdfReferenceSortKey($right));
            $coveredAppearanceCount = $this->countCoveredPdfSignatureNormalAppearances($signature, $signatureAppearanceByteRanges);
            $issues = [];
            if ($matchingAppearances === []) {
                $issues[] = 'missing-signature-widget-appearance';
            } elseif ($normalAppearances === []) {
                $issues[] = 'missing-normal-appearance';
            }
            if ($normalAppearances !== [] && $hasStateDictionary && $selectedState === null) {
                $issues[] = 'missing-selected-state';
            }
            if ($normalAppearances !== [] && $hasStateDictionary && $selectedState !== null && !in_array($selectedState, $appearanceStates, true)) {
                $issues[] = 'selected-state-appearance-missing';
            }
            if ($normalAppearances !== [] && $missingStream) {
                $issues[] = 'missing-appearance-stream';
            }
            if ($normalAppearances !== [] && $streamSkipped) {
                $issues[] = 'appearance-stream-skipped';
            }
            if ($normalAppearances !== [] && $coveredAppearanceCount < count($normalAppearances)) {
                $issues[] = 'appearance-not-covered-by-signature';
            }

            $summaries[] = [
                'fieldName' => is_string($signature['fieldName'] ?? null) && $signature['fieldName'] !== '' ? $signature['fieldName'] : null,
                'fieldObject' => is_string($signature['fieldObject'] ?? null) && $signature['fieldObject'] !== '' ? $signature['fieldObject'] : null,
                'signatureObject' => is_string($signature['signatureObject'] ?? null) && $signature['signatureObject'] !== '' ? $signature['signatureObject'] : null,
                'page' => is_array($anchor) && is_int($anchor['page'] ?? null) ? $anchor['page'] : null,
                'pageObject' => is_array($anchor) && is_string($anchor['pageObject'] ?? null) && $anchor['pageObject'] !== '' ? $anchor['pageObject'] : null,
                'annotationObject' => is_array($anchor) && is_string($anchor['annotationObject'] ?? null) && $anchor['annotationObject'] !== '' ? $anchor['annotationObject'] : null,
                'selectedState' => $selectedState,
                'normalAppearanceCount' => count($normalAppearances),
                'appearanceStates' => $appearanceStates,
                'appearanceObjects' => $appearanceObjects,
                'streamBytes' => $streamBytes,
                'coveredAppearanceCount' => $coveredAppearanceCount,
                'reviewStatus' => $this->pdfSignatureAppearancePolicyReviewStatus($issues),
                'issues' => $issues,
            ];
        }

        usort(
            $summaries,
            static fn (array $a, array $b): int => [
                $a['fieldName'] ?? '',
                $a['fieldObject'] ?? '',
                $a['signatureObject'] ?? '',
            ] <=> [
                $b['fieldName'] ?? '',
                $b['fieldObject'] ?? '',
                $b['signatureObject'] ?? '',
            ]
        );

        return $summaries;
    }

    /**
     * @param array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null} $signature
     * @param list<array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null, appearance:string, streamCoveredBySignature:bool|null, reviewStatus:string}> $signatureAppearanceByteRanges
     */
    private function countCoveredPdfSignatureNormalAppearances(array $signature, array $signatureAppearanceByteRanges): int
    {
        $count = 0;
        foreach ($signatureAppearanceByteRanges as $appearanceRange) {
            if (($appearanceRange['appearance'] ?? null) !== 'N') {
                continue;
            }
            if (!$this->pdfSignatureAppearanceRangeMatchesSignature($signature, $appearanceRange)) {
                continue;
            }
            if (($appearanceRange['reviewStatus'] ?? null) === 'covered' && ($appearanceRange['streamCoveredBySignature'] ?? null) === true) {
                $count++;
            }
        }

        return $count;
    }

    /**
     * @param array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null} $signature
     * @param array{fieldName:string|null, fieldObject:string|null, signatureObject:string|null} $appearanceRange
     */
    private function pdfSignatureAppearanceRangeMatchesSignature(array $signature, array $appearanceRange): bool
    {
        foreach (['fieldObject', 'signatureObject', 'fieldName'] as $key) {
            $left = is_string($signature[$key] ?? null) && $signature[$key] !== '' ? $signature[$key] : null;
            $right = is_string($appearanceRange[$key] ?? null) && $appearanceRange[$key] !== '' ? $appearanceRange[$key] : null;
            if ($left !== null && $right !== null && $left !== $right) {
                return false;
            }
        }

        return true;
    }

    /**
     * @param list<string> $issues
     */
    private function pdfSignatureAppearancePolicyReviewStatus(array $issues): string
    {
        if ($issues === []) {
            return 'ok';
        }
        if (in_array('missing-signature-widget-appearance', $issues, true) || in_array('missing-normal-appearance', $issues, true)) {
            return 'missing';
        }

        return 'review';
    }

    private function pdfSignatureMatchesAppearance(array $signature, array $appearance): bool
    {
        $fieldObject = is_string($signature['fieldObject'] ?? null) && $signature['fieldObject'] !== ''
            ? $signature['fieldObject']
            : null;
        $annotationObject = is_string($appearance['annotationObject'] ?? null) && $appearance['annotationObject'] !== ''
            ? $appearance['annotationObject']
            : null;
        if ($fieldObject !== null && $annotationObject !== null && $fieldObject === $annotationObject) {
            return true;
        }

        $fieldName = is_string($signature['fieldName'] ?? null) && $signature['fieldName'] !== ''
            ? $signature['fieldName']
            : null;
        $appearanceFieldName = is_string($appearance['fieldName'] ?? null) && $appearance['fieldName'] !== ''
            ? $appearance['fieldName']
            : null;

        return $fieldName !== null && $appearanceFieldName !== null && $fieldName === $appearanceFieldName;
    }

    /**
     * @return array<string, array{objectOffset:int, objectBytes:int, streamOffset:int|null, streamBytes:int|null}>
     */
    private function pdfObjectByteRangesByReference(string $pdfBytes): array
    {
        if (preg_match_all('/\b(\d+)\s+(\d+)\s+obj\b(.*?)\bendobj\b/s', $pdfBytes, $matches, PREG_SET_ORDER | PREG_OFFSET_CAPTURE) < 1) {
            return [];
        }

        $ranges = [];
        foreach ($matches as $match) {
            $objectBytes = $match[0][0];
            $objectOffset = $match[0][1];
            $stream = $this->pdfStreamByteRangeForObjectBytes($objectBytes, $objectOffset);
            $ranges[$match[1][0] . ' ' . $match[2][0]] = [
                'objectOffset' => $objectOffset,
                'objectBytes' => strlen($objectBytes),
                'streamOffset' => $stream['offset'],
                'streamBytes' => $stream['bytes'],
            ];
        }

        return $ranges;
    }

    /**
     * @return array{offset:int|null, bytes:int|null}
     */
    private function pdfStreamByteRangeForObjectBytes(string $objectBytes, int $objectOffset): array
    {
        $streamPosition = strpos($objectBytes, 'stream');
        if ($streamPosition === false) {
            return ['offset' => null, 'bytes' => null];
        }

        $start = $streamPosition + strlen('stream');
        if (substr($objectBytes, $start, 2) === "\r\n") {
            $start += 2;
        } elseif (isset($objectBytes[$start]) && ($objectBytes[$start] === "\n" || $objectBytes[$start] === "\r")) {
            $start++;
        }

        $end = strpos($objectBytes, 'endstream', $start);
        if ($end === false || $end < $start) {
            return ['offset' => null, 'bytes' => null];
        }

        $bytes = substr($objectBytes, $start, $end - $start);
        if (str_ends_with($bytes, "\r\n")) {
            $bytes = substr($bytes, 0, -2);
        } elseif (str_ends_with($bytes, "\n") || str_ends_with($bytes, "\r")) {
            $bytes = substr($bytes, 0, -1);
        }

        return [
            'offset' => $objectOffset + $start,
            'bytes' => strlen($bytes),
        ];
    }

    /**
     * @param list<int> $byteRange
     */
    private function pdfByteRangeCoversSpan(array $byteRange, ?int $offset, ?int $bytes): ?bool
    {
        if ($offset === null || $bytes === null) {
            return null;
        }
        if (count($byteRange) < 2 || count($byteRange) % 2 !== 0) {
            return null;
        }

        $end = $offset + max(0, $bytes);
        for ($index = 0; $index < count($byteRange); $index += 2) {
            $rangeOffset = $byteRange[$index];
            $rangeLength = $byteRange[$index + 1];
            if (!is_int($rangeOffset) || !is_int($rangeLength) || $rangeOffset < 0 || $rangeLength < 0) {
                return null;
            }
            $rangeEnd = $rangeOffset + $rangeLength;
            if ($offset >= $rangeOffset && $end <= $rangeEnd) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<int> $byteRange
     * @param array{objectOffset:int, objectBytes:int, streamOffset:int|null, streamBytes:int|null}|null $range
     * @return list<string>
     */
    private function pdfSignatureAppearanceByteRangeIssues(array $byteRange, ?array $range, ?bool $objectCovered, ?bool $streamCovered): array
    {
        $issues = [];
        if (count($byteRange) < 2 || count($byteRange) % 2 !== 0) {
            $issues[] = 'missing-or-invalid-byte-range';
        }
        if ($range === null) {
            $issues[] = 'missing-appearance-object-offset';
        }
        if ($objectCovered === false) {
            $issues[] = 'appearance-object-outside-byte-range';
        }
        if ($streamCovered === false) {
            $issues[] = 'appearance-stream-outside-byte-range';
        }

        return array_values(array_unique($issues));
    }

    /**
     * @param list<string> $issues
     */
    private function pdfSignatureAppearanceByteRangeReviewStatus(array $issues): string
    {
        if ($issues === []) {
            return 'covered';
        }
        if (in_array('missing-or-invalid-byte-range', $issues, true)) {
            return 'missing-byte-range';
        }
        if (in_array('missing-appearance-object-offset', $issues, true)) {
            return 'unresolved';
        }

        return 'review';
    }

    /**
     * @return array{object:string|null, certs:list<array{object:string, bytes:int|null, sha256:string|null, skipped:string|null}>, ocsp:list<array{object:string, bytes:int|null, sha256:string|null, skipped:string|null}>, crls:list<array{object:string, bytes:int|null, sha256:string|null, skipped:string|null}>, vri:list<array{name:string, object:string|null, type:string|null, timestamp:string|null, certs:list<string>, ocsp:list<string>, crls:list<string>, keys:list<string>}>, keys:list<string>}|array{}
     */
    private function extractPdfDocumentSecurityStore(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/DSS')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $dss = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($catalog, 'DSS'), $objects);
        if ($dss['dictionary'] === null) {
            return [];
        }

        $dictionary = $dss['dictionary'];

        return [
            'object' => $dss['object'],
            'certs' => $this->summarizePdfDocumentSecurityStoreStreams(
                $this->collectPdfReferencesFromValue($this->extractPdfValueForName($dictionary, 'Certs'), $objects),
                $objects
            ),
            'ocsp' => $this->summarizePdfDocumentSecurityStoreStreams(
                $this->collectPdfReferencesFromValue($this->extractPdfValueForName($dictionary, 'OCSPs'), $objects),
                $objects
            ),
            'crls' => $this->summarizePdfDocumentSecurityStoreStreams(
                $this->collectPdfReferencesFromValue($this->extractPdfValueForName($dictionary, 'CRLs'), $objects),
                $objects
            ),
            'vri' => $this->extractPdfDocumentSecurityStoreVri($dictionary, $objects),
            'keys' => $this->pdfDictionaryKeys($dictionary),
        ];
    }

    /**
     * @param list<string> $references
     * @param array<string, string> $objects
     * @return list<array{object:string, bytes:int|null, sha256:string|null, skipped:string|null}>
     */
    private function summarizePdfDocumentSecurityStoreStreams(array $references, array $objects): array
    {
        $references = $this->uniqueStrings($references);
        sort($references, SORT_STRING);

        $streams = [];
        foreach ($references as $reference) {
            $body = $objects[$this->pdfReferenceKey($reference)] ?? null;
            $stream = $body === null
                ? ['bytes' => null, 'sha256' => null, 'skipped' => 'missing']
                : $this->summarizePdfStructuralStream($body, self::MAX_DOCUMENT_SECURITY_STORE_STREAM_BYTES);
            $streams[] = [
                'object' => $reference,
                'bytes' => $stream['bytes'],
                'sha256' => $stream['sha256'],
                'skipped' => $stream['skipped'],
            ];
        }

        return $streams;
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{name:string, object:string|null, type:string|null, timestamp:string|null, certs:list<string>, ocsp:list<string>, crls:list<string>, keys:list<string>}>
     */
    private function extractPdfDocumentSecurityStoreVri(string $dssDictionary, array $objects): array
    {
        $vri = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($dssDictionary, 'VRI'), $objects);
        if ($vri['dictionary'] === null) {
            return [];
        }

        $entries = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($vri['dictionary']) as $entry) {
            if ($entry['key'] === '' || $entry['key'] === 'Type') {
                continue;
            }

            $resolved = $this->resolvePdfDictionaryValue($entry['value'], $objects);
            if ($resolved['dictionary'] === null) {
                continue;
            }

            $dictionary = $resolved['dictionary'];
            $entries[] = [
                'name' => $entry['key'],
                'object' => $resolved['object'],
                'type' => $this->extractPdfNameToken($dictionary, 'Type'),
                'timestamp' => $this->extractPdfStringOrNameValue($dictionary, 'TU')
                    ?? $this->extractPdfStringOrNameValue($dictionary, 'TS'),
                'certs' => $this->pdfReferenceLabels(
                    $this->collectPdfReferencesFromValue(
                        $this->extractPdfValueForName($dictionary, 'Cert')
                            ?? $this->extractPdfValueForName($dictionary, 'Certs'),
                        $objects
                    )
                ),
                'ocsp' => $this->pdfReferenceLabels(
                    $this->collectPdfReferencesFromValue(
                        $this->extractPdfValueForName($dictionary, 'OCSP')
                            ?? $this->extractPdfValueForName($dictionary, 'OCSPs'),
                        $objects
                    )
                ),
                'crls' => $this->pdfReferenceLabels(
                    $this->collectPdfReferencesFromValue(
                        $this->extractPdfValueForName($dictionary, 'CRL')
                            ?? $this->extractPdfValueForName($dictionary, 'CRLs'),
                        $objects
                    )
                ),
                'keys' => $this->pdfDictionaryKeys($dictionary),
            ];
        }

        usort(
            $entries,
            static fn (array $a, array $b): int => [
                $a['name'],
                $a['object'] ?? '',
            ] <=> [
                $b['name'],
                $b['object'] ?? '',
            ]
        );

        return $entries;
    }

    /**
     * @param array<string, mixed> $documentSecurityStore
     * @param list<array{fieldName:string|null, signatureObject:string|null, contentsSha256:string|null}> $signatures
     * @return array<string, mixed>
     */
    private function summarizePdfDocumentSecurityStorePolicy(array $documentSecurityStore, array $signatures): array
    {
        if ($documentSecurityStore === []) {
            return [];
        }

        $certObjects = $this->pdfDocumentSecurityStoreObjects($documentSecurityStore['certs'] ?? []);
        $ocspObjects = $this->pdfDocumentSecurityStoreObjects($documentSecurityStore['ocsp'] ?? []);
        $crlObjects = $this->pdfDocumentSecurityStoreObjects($documentSecurityStore['crls'] ?? []);
        $signatureDigestIndex = $this->pdfSignatureDigestIndex($signatures);
        $vriEntries = is_array($documentSecurityStore['vri'] ?? null) ? $documentSecurityStore['vri'] : [];
        $issues = [];
        foreach ($this->pdfDocumentSecurityStoreStreamIssues($documentSecurityStore['certs'] ?? [], 'dss-cert-stream-skipped') as $issue) {
            $issues[] = $issue;
        }
        foreach ($this->pdfDocumentSecurityStoreStreamIssues($documentSecurityStore['ocsp'] ?? [], 'dss-ocsp-stream-skipped') as $issue) {
            $issues[] = $issue;
        }
        foreach ($this->pdfDocumentSecurityStoreStreamIssues($documentSecurityStore['crls'] ?? [], 'dss-crl-stream-skipped') as $issue) {
            $issues[] = $issue;
        }

        $vriPolicies = [];
        $matchedVriCount = 0;
        if ($vriEntries === []) {
            $issues[] = 'dss-missing-vri';
        }

        foreach ($vriEntries as $vriEntry) {
            if (!is_array($vriEntry)) {
                continue;
            }

            $name = is_string($vriEntry['name'] ?? null) ? $vriEntry['name'] : '';
            $normalizedName = $this->normalizePdfDocumentSecurityStoreVriName($name);
            $matchedSignature = $normalizedName !== '' && isset($signatureDigestIndex[$normalizedName])
                ? $signatureDigestIndex[$normalizedName]
                : null;
            $certs = $this->pdfDocumentSecurityStoreVriReferences($vriEntry['certs'] ?? []);
            $ocsp = $this->pdfDocumentSecurityStoreVriReferences($vriEntry['ocsp'] ?? []);
            $crls = $this->pdfDocumentSecurityStoreVriReferences($vriEntry['crls'] ?? []);
            $missingCerts = $this->pdfDocumentSecurityStoreMissingReferences($certs, $certObjects);
            $missingOcsp = $this->pdfDocumentSecurityStoreMissingReferences($ocsp, $ocspObjects);
            $missingCrls = $this->pdfDocumentSecurityStoreMissingReferences($crls, $crlObjects);
            $entryIssues = [];

            if ($normalizedName === '') {
                $entryIssues[] = 'vri-missing-name';
            } elseif ($matchedSignature === null) {
                $entryIssues[] = 'vri-name-not-matched-to-signature-contents';
            } else {
                $matchedVriCount++;
            }
            if ($certs === [] && $ocsp === [] && $crls === []) {
                $entryIssues[] = 'vri-missing-evidence-references';
            }
            if ($missingCerts !== []) {
                $entryIssues[] = 'vri-cert-not-in-dss-certs';
            }
            if ($missingOcsp !== []) {
                $entryIssues[] = 'vri-ocsp-not-in-dss-ocsp';
            }
            if ($missingCrls !== []) {
                $entryIssues[] = 'vri-crl-not-in-dss-crls';
            }

            foreach ($entryIssues as $issue) {
                $issues[] = $issue;
            }

            $vriPolicies[] = [
                'name' => $name,
                'matchedSignatureObject' => is_array($matchedSignature) && is_string($matchedSignature['signatureObject'] ?? null) && $matchedSignature['signatureObject'] !== ''
                    ? $matchedSignature['signatureObject']
                    : null,
                'matchedFieldName' => is_array($matchedSignature) && is_string($matchedSignature['fieldName'] ?? null) && $matchedSignature['fieldName'] !== ''
                    ? $matchedSignature['fieldName']
                    : null,
                'certs' => $certs,
                'ocsp' => $ocsp,
                'crls' => $crls,
                'missingCerts' => $missingCerts,
                'missingOcsp' => $missingOcsp,
                'missingCrls' => $missingCrls,
                'reviewStatus' => $entryIssues === [] ? 'ok' : 'review',
                'issues' => $entryIssues,
            ];
        }

        usort(
            $vriPolicies,
            static fn (array $a, array $b): int => [
                $a['name'] ?? '',
                $a['matchedSignatureObject'] ?? '',
            ] <=> [
                $b['name'] ?? '',
                $b['matchedSignatureObject'] ?? '',
            ]
        );
        sort($issues, SORT_STRING);

        return [
            'object' => is_string($documentSecurityStore['object'] ?? null) && $documentSecurityStore['object'] !== ''
                ? $documentSecurityStore['object']
                : null,
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'certStoreCount' => count($certObjects),
            'ocspStoreCount' => count($ocspObjects),
            'crlStoreCount' => count($crlObjects),
            'vriCount' => count($vriPolicies),
            'signatureDigestCount' => count($signatureDigestIndex),
            'matchedVriCount' => $matchedVriCount,
            'certObjects' => $certObjects,
            'ocspObjects' => $ocspObjects,
            'crlObjects' => $crlObjects,
            'issues' => $issues,
            'vri' => $vriPolicies,
        ];
    }

    /**
     * @return array<string, array{signatureObject:string|null, fieldName:string|null}>
     */
    private function pdfSignatureDigestIndex(array $signatures): array
    {
        $index = [];
        foreach ($signatures as $signature) {
            if (!is_array($signature)) {
                continue;
            }

            $sha256 = is_string($signature['contentsSha256'] ?? null) ? $signature['contentsSha256'] : '';
            if ($sha256 === '') {
                continue;
            }

            $normalized = strtoupper($sha256);
            if (isset($index[$normalized])) {
                continue;
            }

            $index[$normalized] = [
                'signatureObject' => is_string($signature['signatureObject'] ?? null) && $signature['signatureObject'] !== ''
                    ? $signature['signatureObject']
                    : null,
                'fieldName' => is_string($signature['fieldName'] ?? null) && $signature['fieldName'] !== ''
                    ? $signature['fieldName']
                    : null,
            ];
        }

        ksort($index, SORT_STRING);

        return $index;
    }

    /**
     * @return list<string>
     */
    private function pdfDocumentSecurityStoreObjects(mixed $entries): array
    {
        if (!is_array($entries)) {
            return [];
        }

        $objects = [];
        foreach ($entries as $entry) {
            if (is_array($entry) && is_string($entry['object'] ?? null) && $entry['object'] !== '') {
                $objects[] = $entry['object'];
            }
        }

        $objects = $this->uniqueStrings($objects);
        usort($objects, fn (string $left, string $right): int => $this->pdfReferenceSortKey($left) <=> $this->pdfReferenceSortKey($right));

        return $objects;
    }

    /**
     * @return list<string>
     */
    private function pdfDocumentSecurityStoreStreamIssues(mixed $entries, string $issue): array
    {
        if (!is_array($entries)) {
            return [];
        }

        $issues = [];
        foreach ($entries as $entry) {
            if (is_array($entry) && is_string($entry['skipped'] ?? null) && $entry['skipped'] !== '') {
                $issues[] = $issue;
            }
        }

        return $issues;
    }

    /**
     * @return list<string>
     */
    private function pdfDocumentSecurityStoreVriReferences(mixed $references): array
    {
        if (!is_array($references)) {
            return [];
        }

        $labels = [];
        foreach ($references as $reference) {
            if (is_string($reference) && $reference !== '') {
                $labels[] = $reference;
            }
        }

        $labels = $this->uniqueStrings($labels);
        usort($labels, fn (string $left, string $right): int => $this->pdfReferenceSortKey($left) <=> $this->pdfReferenceSortKey($right));

        return $labels;
    }

    /**
     * @param list<string> $references
     * @param list<string> $available
     * @return list<string>
     */
    private function pdfDocumentSecurityStoreMissingReferences(array $references, array $available): array
    {
        $availableSet = array_fill_keys($available, true);
        $missing = [];
        foreach ($references as $reference) {
            if (!isset($availableSet[$reference])) {
                $missing[] = $reference;
            }
        }

        return $missing;
    }

    private function normalizePdfDocumentSecurityStoreVriName(string $name): string
    {
        return strtoupper(ltrim($name, '/'));
    }

    /**
     * @return list<string>
     */
    private function pdfDictionaryKeys(string $dictionary): array
    {
        $keys = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            if ($entry['key'] !== '') {
                $keys[] = $entry['key'];
            }
        }

        $keys = array_values(array_unique($keys));
        sort($keys, SORT_STRING);

        return $keys;
    }

    /**
     * @param list<string> $references
     * @return list<string>
     */
    private function pdfReferenceLabels(array $references): array
    {
        $references = $this->uniqueStrings($references);
        sort($references, SORT_STRING);

        return $references;
    }

    /**
     * @param array<string, string> $objects
     */
    private function extractPdfArrayOrReferenceValue(string $dictionary, string $name, array $objects): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return null;
        }

        if ($value['kind'] === 'array') {
            return $value['value'];
        }

        if ($value['kind'] !== 'reference') {
            return null;
        }

        $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        if ($body === null) {
            return null;
        }

        $resolved = $this->parsePdfValueAt($body, 0);

        return $resolved !== null && $resolved['kind'] === 'array' ? $resolved['value'] : null;
    }

    /**
     * @return list<string>
     */
    private function collectPdfReferencesFromArray(?string $array): array
    {
        if ($array === null) {
            return [];
        }

        $references = [];
        $this->walkPdfArrayValues($array, static function (array $value) use (&$references): void {
            if ($value['kind'] === 'reference') {
                $references[] = $value['value'];
            }
        });

        return $this->uniqueStrings($references);
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function collectPdfReferencesFromValue(?array $value, array $objects, int $depth = 0): array
    {
        if ($value === null || $depth > 8) {
            return [];
        }

        if ($value['kind'] === 'array') {
            return $this->collectPdfReferencesFromArray($value['value']);
        }

        if ($value['kind'] !== 'reference') {
            return [];
        }

        $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
        if ($body !== '') {
            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved !== null && $resolved['kind'] === 'array') {
                return $this->collectPdfReferencesFromValue($resolved, $objects, $depth + 1);
            }
        }

        return [$value['value']];
    }

    /**
     * @return list<string>
     */
    private function collectPdfNamesFromArray(string $array): array
    {
        $names = [];
        $this->walkPdfArrayValues($array, static function (array $value) use (&$names): void {
            if (!in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
                return;
            }

            $name = trim($value['value']);
            if ($name !== '') {
                $names[] = $name;
            }
        });

        return $this->uniqueStrings($names);
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function collectPdfNamesFromValue(?array $value, array $objects, int $depth = 0): array
    {
        if ($value === null || $depth > 8) {
            return [];
        }

        if (in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
            $name = trim($value['value']);

            return $name === '' ? [] : [$name];
        }

        if ($value['kind'] === 'array') {
            return $this->collectPdfNamesFromArray($value['value']);
        }

        if ($value['kind'] === 'reference') {
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return [];
            }

            $resolved = $this->parsePdfValueAt($body, 0);

            return $resolved === null ? [] : $this->collectPdfNamesFromValue($resolved, $objects, $depth + 1);
        }

        return [];
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function collectPdfTextFromValue(?array $value, array $objects, int $depth = 0): array
    {
        if ($value === null || $depth > 8) {
            return [];
        }

        if (in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
            $text = trim($value['value']);

            return $text === '' ? [] : [$text];
        }

        if ($value['kind'] === 'array') {
            $strings = [];
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $entry) {
                foreach ($this->collectPdfTextFromValue($entry, $objects, $depth + 1) as $string) {
                    $strings[] = $string;
                }
            }

            return $this->uniqueStrings($strings);
        }

        if ($value['kind'] === 'reference') {
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return [];
            }

            $resolved = $this->parsePdfValueAt($body, 0);

            return $resolved === null ? [] : $this->collectPdfTextFromValue($resolved, $objects, $depth + 1);
        }

        return [];
    }

    /**
     * @return list<string>
     */
    private function collectPdfStringsFromArray(?string $array): array
    {
        if ($array === null) {
            return [];
        }

        $strings = [];
        $this->walkPdfArrayValues($array, static function (array $value) use (&$strings): void {
            if (!in_array($value['kind'], ['literal', 'hex'], true)) {
                return;
            }

            $string = trim($value['value']);
            if ($string !== '') {
                $strings[] = $string;
            }
        });

        return $this->uniqueStrings($strings);
    }

    private function walkPdfArrayValues(string $array, callable $visitor, int $depth = 0): void
    {
        if ($depth > 8) {
            return;
        }

        $cursor = str_starts_with($array, '[') ? 1 : 0;
        $length = strlen($array);
        if (str_ends_with($array, ']')) {
            $length--;
        }

        while ($cursor < $length) {
            $value = $this->parsePdfValueAt($array, $cursor);
            if ($value === null) {
                $cursor++;
                continue;
            }

            $visitor($value);
            if ($value['kind'] === 'array') {
                $this->walkPdfArrayValues($value['value'], $visitor, $depth + 1);
            }
            $cursor = max($cursor + 1, min($length, $value['next']));
        }
    }

    /**
     * @return list<array{kind:string, value:string, next:int}>
     */
    private function pdfTopLevelArrayValues(string $array): array
    {
        $values = [];
        $cursor = str_starts_with($array, '[') ? 1 : 0;
        $length = strlen($array);
        if (str_ends_with($array, ']')) {
            $length--;
        }

        while ($cursor < $length && count($values) < 1024) {
            $value = $this->parsePdfValueAt($array, $cursor);
            if ($value === null) {
                $cursor++;
                continue;
            }

            $values[] = $value;
            $cursor = max($cursor + 1, min($length, $value['next']));
        }

        return $values;
    }

    /**
     * @param list<string> $values
     * @return list<string>
     */
    private function uniqueStrings(array $values): array
    {
        $unique = [];
        $seen = [];
        foreach ($values as $value) {
            if (isset($seen[$value])) {
                continue;
            }

            $seen[$value] = true;
            $unique[] = $value;
        }

        return $unique;
    }

    /**
     * @param list<int> $values
     * @return list<int>
     */
    private function uniqueIntegers(array $values): array
    {
        $unique = [];
        $seen = [];
        foreach ($values as $value) {
            $key = (string) $value;
            if (isset($seen[$key])) {
                continue;
            }

            $seen[$key] = true;
            $unique[] = $value;
        }

        return $unique;
    }

    private function countPdfTopLevelArrayValues(string $array): int
    {
        $cursor = str_starts_with($array, '[') ? 1 : 0;
        $length = strlen($array);
        if (str_ends_with($array, ']')) {
            $length--;
        }

        $count = 0;
        while ($cursor < $length && $count < 1024) {
            $value = $this->parsePdfValueAt($array, $cursor);
            if ($value === null) {
                $cursor++;
                continue;
            }

            $count++;
            $cursor = max($cursor + 1, min($length, $value['next']));
        }

        return $count;
    }

    private function extractPdfNestedDictionary(string $dictionary, string $name): ?string
    {
        $needle = '/' . $name;
        $offset = 0;
        $length = strlen($dictionary);
        while (($position = strpos($dictionary, $needle, $offset)) !== false) {
            $cursor = $position + strlen($needle);
            if ($cursor < $length && preg_match('/[A-Za-z0-9_.-]/', $dictionary[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < $length && ctype_space($dictionary[$cursor])) {
                $cursor++;
            }
            if (substr($dictionary, $cursor, 2) !== '<<') {
                $offset = $cursor + 1;
                continue;
            }

            $parsed = $this->parsePdfDictionary($dictionary, $cursor);
            if ($parsed !== null) {
                return $parsed['value'];
            }

            $offset = $cursor + 2;
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     */
    private function extractPdfDictionaryOrReferenceValue(string $dictionary, string $name, array $objects): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return null;
        }

        if ($value['kind'] === 'dictionary') {
            return $value['value'];
        }
        if ($value['kind'] === 'reference') {
            return $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        }

        return null;
    }

    /**
     * @return list<array{key:string, value:array{kind:string, value:string, next:int}}>
     */
    private function extractPdfTopLevelDictionaryEntries(string $dictionary): array
    {
        $length = strlen($dictionary);
        $start = 0;
        $end = $length;

        while ($start < $length && ctype_space($dictionary[$start])) {
            $start++;
        }
        if (substr($dictionary, $start, 2) === '<<') {
            $parsed = $this->parsePdfDictionary($dictionary, $start);
            if ($parsed !== null) {
                $start += 2;
                $end = max($start, $parsed['next'] - 2);
            }
        }

        $entries = [];
        $cursor = $start;
        while ($cursor < $end) {
            while ($cursor < $end && ctype_space($dictionary[$cursor])) {
                $cursor++;
            }
            if ($cursor >= $end) {
                break;
            }

            if ($dictionary[$cursor] !== '/') {
                $value = $this->parsePdfValueAt($dictionary, $cursor);
                $cursor = $value === null ? $cursor + 1 : min($end, $value['next']);
                continue;
            }

            if (preg_match('/\A\/([A-Za-z0-9_.#+-]+)/s', substr($dictionary, $cursor), $matches) !== 1) {
                $cursor++;
                continue;
            }

            $key = $this->decodePdfNameToken($matches[1]);
            $cursor += strlen($matches[0]);
            $value = $this->parsePdfValueAt($dictionary, $cursor);
            if ($value !== null) {
                $entries[] = [
                    'key' => $key,
                    'value' => $value,
                ];
                $cursor = min($end, $value['next']);
                continue;
            }

            $cursor++;
        }

        return $entries;
    }

    /**
     * @return array{kind:string, value:string, next:int}|null
     */
    private function extractPdfValueForName(string $dictionary, string $name): ?array
    {
        $length = strlen($dictionary);
        $start = 0;
        $end = $length;

        while ($start < $length && ctype_space($dictionary[$start])) {
            $start++;
        }
        if (substr($dictionary, $start, 2) === '<<') {
            $parsed = $this->parsePdfDictionary($dictionary, $start);
            if ($parsed !== null) {
                $start += 2;
                $end = max($start, $parsed['next'] - 2);
            }
        }

        $cursor = $start;
        while ($cursor < $end) {
            while ($cursor < $end && ctype_space($dictionary[$cursor])) {
                $cursor++;
            }
            if ($cursor >= $end) {
                break;
            }

            if ($dictionary[$cursor] !== '/') {
                $value = $this->parsePdfValueAt($dictionary, $cursor);
                $cursor = $value === null ? $cursor + 1 : min($end, $value['next']);
                continue;
            }

            if (preg_match('/\A\/([A-Za-z0-9_.#+-]+)/s', substr($dictionary, $cursor), $matches) !== 1) {
                $cursor++;
                continue;
            }

            $key = $this->decodePdfNameToken($matches[1]);
            $cursor += strlen($matches[0]);
            $value = $this->parsePdfValueAt($dictionary, $cursor);
            if ($key === $name && $value !== null) {
                return $value;
            }

            $cursor = $value === null ? $cursor + 1 : min($end, $value['next']);
        }

        return null;
    }

    /**
     * @return array{kind:string, value:string, next:int}|null
     */
    private function parsePdfValueAt(string $bytes, int $offset): ?array
    {
        $length = strlen($bytes);
        while ($offset < $length && ctype_space($bytes[$offset])) {
            $offset++;
        }
        if ($offset >= $length) {
            return null;
        }

        if (substr($bytes, $offset, 2) === '<<') {
            $parsed = $this->parsePdfDictionary($bytes, $offset);

            return $parsed === null ? null : ['kind' => 'dictionary', 'value' => $parsed['value'], 'next' => $parsed['next']];
        }

        if ($bytes[$offset] === '[') {
            $parsed = $this->parsePdfArray($bytes, $offset);

            return $parsed === null ? null : ['kind' => 'array', 'value' => $parsed['value'], 'next' => $parsed['next']];
        }

        if ($bytes[$offset] === '(') {
            $parsed = $this->parsePdfLiteralString($bytes, $offset);

            return $parsed === null ? null : ['kind' => 'literal', 'value' => $parsed['value'], 'next' => $parsed['next']];
        }

        if ($bytes[$offset] === '<' && ($offset + 1 >= $length || $bytes[$offset + 1] !== '<')) {
            $parsed = $this->parsePdfHexString($bytes, $offset);

            return $parsed === null ? null : ['kind' => 'hex', 'value' => $parsed['value'], 'next' => $parsed['next']];
        }

        $chunk = substr($bytes, $offset);
        if (preg_match('/\A(\d+)\s+(\d+)\s+R\b/s', $chunk, $matches) === 1) {
            return [
                'kind' => 'reference',
                'value' => $matches[1] . ' ' . $matches[2] . ' R',
                'next' => $offset + strlen($matches[0]),
            ];
        }

        if (preg_match('/\A\/([A-Za-z0-9_.#+-]+)/s', $chunk, $matches) === 1) {
            return [
                'kind' => 'name',
                'value' => $this->decodePdfNameToken($matches[1]),
                'next' => $offset + strlen($matches[0]),
            ];
        }

        if (preg_match('/\A(true|false|null)\b/si', $chunk, $matches) === 1) {
            return [
                'kind' => 'keyword',
                'value' => strtolower($matches[1]),
                'next' => $offset + strlen($matches[0]),
            ];
        }

        if (preg_match('/\A[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[Ee][-+]?\d+)?\b/s', $chunk, $matches) === 1) {
            return [
                'kind' => 'number',
                'value' => $matches[0],
                'next' => $offset + strlen($matches[0]),
            ];
        }

        return null;
    }

    /**
     * @return array{
     *     encrypted:bool,
     *     filter:string|null,
     *     version:int|null,
     *     revision:int|null,
     *     length:int|null,
     *     permissions:int|null,
     *     permissionFlags:array<string, bool>,
     *     encryptMetadata:bool|null,
     *     defaultFilters:array{stream:string|null, string:string|null, embeddedFile:string|null}|array{},
     *     cryptFilters:list<array{name:string, object:string|null, cryptFilterMethod:string|null, length:int|null, authEvent:string|null, recipients:int, rawKeys:list<string>}>
     * }
     */
    private function extractPdfEncryptionInfo(string $pdfBytes): array
    {
        $info = [
            'encrypted' => false,
            'filter' => null,
            'version' => null,
            'revision' => null,
            'length' => null,
            'permissions' => null,
            'permissionFlags' => [],
            'encryptMetadata' => null,
            'defaultFilters' => [],
            'cryptFilters' => [],
        ];

        if (preg_match('/\/Encrypt\b/s', $pdfBytes) !== 1) {
            return $info;
        }

        $info['encrypted'] = true;
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $dictionary = $this->extractPdfEncryptDictionary($pdfBytes);
        if ($dictionary === null) {
            return $info;
        }

        $info['filter'] = $this->extractPdfNameToken($dictionary, 'Filter');
        $info['version'] = $this->extractPdfIntegerToken($dictionary, 'V');
        $info['revision'] = $this->extractPdfIntegerToken($dictionary, 'R');
        $info['length'] = $this->extractPdfIntegerToken($dictionary, 'Length');
        $info['permissions'] = $this->extractPdfIntegerToken($dictionary, 'P');
        $info['encryptMetadata'] = $this->extractPdfBooleanToken($dictionary, 'EncryptMetadata');
        $info['defaultFilters'] = $this->extractPdfEncryptionDefaultFilters($dictionary);
        $info['cryptFilters'] = $this->extractPdfEncryptionCryptFilters($dictionary, $objects);
        if ($info['permissions'] !== null) {
            $info['permissionFlags'] = $this->decodePdfPermissionFlags($info['permissions']);
        }

        return $info;
    }

    /**
     * @return array{stream:string|null, string:string|null, embeddedFile:string|null}|array{}
     */
    private function extractPdfEncryptionDefaultFilters(string $dictionary): array
    {
        $filters = [
            'stream' => $this->extractPdfNameToken($dictionary, 'StmF'),
            'string' => $this->extractPdfNameToken($dictionary, 'StrF'),
            'embeddedFile' => $this->extractPdfNameToken($dictionary, 'EFF'),
        ];

        return array_filter(
            $filters,
            static fn (?string $filter): bool => $filter !== null && $filter !== ''
        ) === [] ? [] : $filters;
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{name:string, object:string|null, cryptFilterMethod:string|null, length:int|null, authEvent:string|null, recipients:int, rawKeys:list<string>}>
     */
    private function extractPdfEncryptionCryptFilters(string $dictionary, array $objects): array
    {
        $cryptFilterDictionary = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'CF', $objects);
        if ($cryptFilterDictionary === null) {
            return [];
        }

        $filters = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($cryptFilterDictionary) as $entry) {
            if ($entry['key'] === '' || $entry['key'] === 'Type') {
                continue;
            }

            $filterDictionary = null;
            $filterObject = null;
            if ($entry['value']['kind'] === 'dictionary') {
                $filterDictionary = $entry['value']['value'];
            } elseif ($entry['value']['kind'] === 'reference') {
                $filterObject = $entry['value']['value'];
                $filterDictionary = $objects[$this->pdfReferenceKey($filterObject)] ?? null;
            }
            if ($filterDictionary === null) {
                continue;
            }

            $recipients = 0;
            $recipientsArray = $this->extractPdfArrayOrReferenceValue($filterDictionary, 'Recipients', $objects);
            if ($recipientsArray !== null) {
                $recipients = count($this->pdfTopLevelArrayValues($recipientsArray));
            }

            $filters[] = [
                'name' => $entry['key'],
                'object' => $filterObject,
                'cryptFilterMethod' => $this->extractPdfNameToken($filterDictionary, 'CFM'),
                'length' => $this->extractPdfIntegerToken($filterDictionary, 'Length'),
                'authEvent' => $this->extractPdfNameToken($filterDictionary, 'AuthEvent'),
                'recipients' => $recipients,
                'rawKeys' => $this->pdfDictionaryKeys($filterDictionary),
            ];
        }

        usort(
            $filters,
            static fn (array $a, array $b): int => [
                $a['name'],
                $a['object'] ?? '',
            ] <=> [
                $b['name'],
                $b['object'] ?? '',
            ]
        );

        return $filters;
    }

    private function extractPdfEncryptDictionary(string $pdfBytes): ?string
    {
        if (preg_match('/\/Encrypt\s+(\d+)\s+(\d+)\s+R\b/s', $pdfBytes, $matches) === 1) {
            $objects = $this->pdfObjectBodiesByReference($pdfBytes);
            $key = $matches[1] . ' ' . $matches[2];

            return $objects[$key] ?? null;
        }

        $offset = 0;
        while (($position = strpos($pdfBytes, '/Encrypt', $offset)) !== false) {
            $cursor = $position + strlen('/Encrypt');
            if ($cursor < strlen($pdfBytes) && preg_match('/[A-Za-z0-9_.-]/', $pdfBytes[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < strlen($pdfBytes) && ctype_space($pdfBytes[$cursor])) {
                $cursor++;
            }
            if (substr($pdfBytes, $cursor, 2) !== '<<') {
                $offset = $cursor + 1;
                continue;
            }

            $parsed = $this->parsePdfDictionary($pdfBytes, $cursor);
            if ($parsed !== null) {
                return $parsed['value'];
            }

            $offset = $cursor + 2;
        }

        return null;
    }

    private function extractPdfNameToken(string $dictionary, string $name): ?string
    {
        if (preg_match('/\/' . preg_quote($name, '/') . '\s*\/([A-Za-z0-9_.#+-]+)/s', $dictionary, $matches) !== 1) {
            return null;
        }

        return $this->decodePdfNameToken($matches[1]);
    }

    private function decodePdfNameToken(string $name): string
    {
        return preg_replace_callback(
            '/#([0-9A-Fa-f]{2})/',
            static fn (array $matches): string => chr(hexdec($matches[1])),
            $name
        ) ?? $name;
    }

    private function extractPdfIntegerToken(string $dictionary, string $name): ?int
    {
        if (preg_match('/\/' . preg_quote($name, '/') . '\s+(-?\d+)\b/s', $dictionary, $matches) !== 1) {
            return null;
        }

        return (int) $matches[1];
    }

    private function extractPdfNumberToken(string $dictionary, string $name): ?float
    {
        if (preg_match('/\/' . preg_quote($name, '/') . '\s+([-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[Ee][-+]?\d+)?)\b/s', $dictionary, $matches) !== 1) {
            return null;
        }

        return (float) $matches[1];
    }

    private function extractPdfBooleanToken(string $dictionary, string $name): ?bool
    {
        if (preg_match('/\/' . preg_quote($name, '/') . '\s+(true|false)\b/si', $dictionary, $matches) !== 1) {
            return null;
        }

        return strtolower($matches[1]) === 'true';
    }

    /**
     * @return array<string, bool>
     */
    private function decodePdfPermissionFlags(int $permissions): array
    {
        $bits = $permissions < 0 ? $permissions + 4294967296 : $permissions;

        return [
            'printLowQuality' => ($bits & 0x0004) !== 0,
            'modify' => ($bits & 0x0008) !== 0,
            'copy' => ($bits & 0x0010) !== 0,
            'annotate' => ($bits & 0x0020) !== 0,
            'fillForms' => ($bits & 0x0100) !== 0,
            'extractAccessibility' => ($bits & 0x0200) !== 0,
            'assemble' => ($bits & 0x0400) !== 0,
            'printHighQuality' => ($bits & 0x0800) !== 0,
        ];
    }

    private function extractPdfPageCount(string $pdfBytes): ?int
    {
        $objects = $this->pdfObjectBodies($pdfBytes);
        $pageTreeCounts = [];
        foreach ($objects as $body) {
            if (preg_match('/\/Type\s*\/Pages\b/s', $body) !== 1) {
                continue;
            }
            if (preg_match('/\/Count\s+(\d+)\b/s', $body, $matches) !== 1) {
                continue;
            }

            $count = (int) $matches[1];
            if ($count > 0) {
                $pageTreeCounts[] = $count;
            }
        }
        if ($pageTreeCounts !== []) {
            return max($pageTreeCounts);
        }

        $pageObjects = 0;
        foreach ($objects as $body) {
            if (preg_match('/\/Type\s*\/Page\b/s', $body) === 1) {
                $pageObjects++;
            }
        }

        return $pageObjects > 0 ? $pageObjects : null;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, mediaBox:list<float>|null, cropBox:list<float>|null, bleedBox:list<float>|null, trimBox:list<float>|null, artBox:list<float>|null, rotation:int|null, inherited:list<string>}>
     */
    private function extractPdfPageBoxes(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $pages = [];
        $visited = [];
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageBoxesFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                [],
                $visited,
                $pages,
                0
            );
        }

        if ($pages === []) {
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pages[] = $this->summarizePdfPageBox($body, $reference, []);
            }
        }

        foreach ($pages as $index => &$page) {
            $page['page'] = $index + 1;
        }
        unset($page);

        return $pages;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, mixed> $inherited
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, mediaBox:list<float>|null, cropBox:list<float>|null, bleedBox:list<float>|null, trimBox:list<float>|null, artBox:list<float>|null, rotation:int|null, inherited:list<string>}> $pages
     */
    private function collectPdfPageBoxesFromTree(
        array $objects,
        string $reference,
        array $inherited,
        array &$visited,
        array &$pages,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pages[] = $this->summarizePdfPageBox($body, $reference, $inherited);
            return;
        }

        $childInherited = $this->pdfPageTreeInheritedValues($body, $inherited);
        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageBoxesFromTree(
                $objects,
                $kidReference,
                $childInherited,
                $visited,
                $pages,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, mixed> $inherited
     * @return array<string, mixed>
     */
    private function pdfPageTreeInheritedValues(string $dictionary, array $inherited): array
    {
        foreach (['MediaBox', 'CropBox'] as $boxName) {
            $box = $this->extractPdfBoxValue($dictionary, $boxName);
            if ($box !== null) {
                $inherited[$boxName] = $box;
            }
        }

        $rotation = $this->extractPdfRotationValue($dictionary);
        if ($rotation !== null) {
            $inherited['Rotate'] = $rotation;
        }

        return $inherited;
    }

    /**
     * @param array<string, mixed> $inherited
     * @return array{page:int, pageObject:string|null, mediaBox:list<float>|null, cropBox:list<float>|null, bleedBox:list<float>|null, trimBox:list<float>|null, artBox:list<float>|null, rotation:int|null, inherited:list<string>}
     */
    private function summarizePdfPageBox(string $dictionary, ?string $reference, array $inherited): array
    {
        $inheritedNames = [];
        $boxValues = [];
        foreach (['MediaBox', 'CropBox', 'BleedBox', 'TrimBox', 'ArtBox'] as $boxName) {
            $box = $this->extractPdfBoxValue($dictionary, $boxName);
            if ($box === null && isset($inherited[$boxName]) && is_array($inherited[$boxName])) {
                $box = $inherited[$boxName];
                $inheritedNames[] = $this->pdfPageGeometryKey($boxName);
            }

            $boxValues[$boxName] = $box;
        }

        $rotation = $this->extractPdfRotationValue($dictionary);
        if ($rotation === null && isset($inherited['Rotate']) && is_int($inherited['Rotate'])) {
            $rotation = $inherited['Rotate'];
            $inheritedNames[] = 'rotation';
        }

        $inheritedNames = array_values(array_unique($inheritedNames));
        sort($inheritedNames);

        return [
            'page' => 0,
            'pageObject' => $reference === null ? null : $reference . ' R',
            'mediaBox' => $boxValues['MediaBox'],
            'cropBox' => $boxValues['CropBox'],
            'bleedBox' => $boxValues['BleedBox'],
            'trimBox' => $boxValues['TrimBox'],
            'artBox' => $boxValues['ArtBox'],
            'rotation' => $rotation,
            'inherited' => $inheritedNames,
        ];
    }

    /**
     * @return list<float>|null
     */
    private function extractPdfBoxValue(string $dictionary, string $name): ?array
    {
        $array = $this->extractPdfArrayValue($dictionary, $name);
        if ($array === null) {
            return null;
        }
        if (preg_match_all('/[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[Ee][-+]?\d+)?/', $array, $matches) < 4) {
            return null;
        }

        $box = [];
        foreach (array_slice($matches[0], 0, 4) as $number) {
            $box[] = (float) $number;
        }

        return $box;
    }

    /**
     * @return list<float>|null
     */
    private function extractPdfNumberArrayValues(string $dictionary, string $name): ?array
    {
        $array = $this->extractPdfArrayValue($dictionary, $name);
        if ($array === null) {
            return null;
        }
        if (preg_match_all('/[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[Ee][-+]?\d+)?/', $array, $matches) < 1) {
            return null;
        }

        $numbers = [];
        foreach (array_slice($matches[0], 0, 128) as $number) {
            $numbers[] = (float) $number;
        }

        return $numbers;
    }

    private function extractPdfRotationValue(string $dictionary): ?int
    {
        $rotation = $this->extractPdfIntegerToken($dictionary, 'Rotate');
        if ($rotation === null) {
            return null;
        }

        $rotation %= 360;
        if ($rotation < 0) {
            $rotation += 360;
        }

        return $rotation;
    }

    private function pdfPageGeometryKey(string $pdfName): string
    {
        return match ($pdfName) {
            'MediaBox' => 'mediaBox',
            'CropBox' => 'cropBox',
            'BleedBox' => 'bleedBox',
            'TrimBox' => 'trimBox',
            'ArtBox' => 'artBox',
            default => $pdfName,
        };
    }

    /**
     * @param list<array{page:int, pageObject:string|null, mediaBox:list<float>|null, cropBox:list<float>|null, bleedBox:list<float>|null, trimBox:list<float>|null, artBox:list<float>|null, rotation:int|null, inherited:list<string>}> $pageBoxes
     * @return array<int, int>
     */
    private function summarizePdfPageRotations(array $pageBoxes): array
    {
        $rotations = [];
        foreach ($pageBoxes as $pageBox) {
            if ($pageBox['rotation'] === null) {
                continue;
            }

            $rotations[$pageBox['page']] = $pageBox['rotation'];
        }

        return $rotations;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, boxColorInfoObject:string|null, boxColorInfo:list<array{box:string, color:list<float>|null, width:float|null, style:string|null}>, separationInfoObject:string|null, separationPages:list<string>, separationDeviceColorant:string|null, separationColorSpace:string|null, presStepsObject:string|null, presStepsSubtype:string|null, presStepsNext:list<string>}>
     */
    private function extractPdfPageProductionMetadata(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $metadata = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageProductionMetadataFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $metadata,
                $pageNumber,
                0
            );
        }

        if ($metadata === []) {
            uksort($objects, fn (string $a, string $b): int => $this->pdfReferenceSortKey($a . ' R') <=> $this->pdfReferenceSortKey($b . ' R'));
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $summary = $this->summarizePdfPageProductionMetadata($body, $reference, $objects, $pageNumber);
                if ($this->pdfPageProductionMetadataHasValues($summary)) {
                    $metadata[] = $summary;
                }
            }
        }

        return $metadata;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, boxColorInfoObject:string|null, boxColorInfo:list<array{box:string, color:list<float>|null, width:float|null, style:string|null}>, separationInfoObject:string|null, separationPages:list<string>, separationDeviceColorant:string|null, separationColorSpace:string|null, presStepsObject:string|null, presStepsSubtype:string|null, presStepsNext:list<string>}> $metadata
     */
    private function collectPdfPageProductionMetadataFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$metadata,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $summary = $this->summarizePdfPageProductionMetadata($body, $reference, $objects, $pageNumber);
            if ($this->pdfPageProductionMetadataHasValues($summary)) {
                $metadata[] = $summary;
            }

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageProductionMetadataFromTree(
                $objects,
                $kidReference,
                $visited,
                $metadata,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, boxColorInfoObject:string|null, boxColorInfo:list<array{box:string, color:list<float>|null, width:float|null, style:string|null}>, separationInfoObject:string|null, separationPages:list<string>, separationDeviceColorant:string|null, separationColorSpace:string|null, presStepsObject:string|null, presStepsSubtype:string|null, presStepsNext:list<string>}
     */
    private function summarizePdfPageProductionMetadata(string $dictionary, string $reference, array $objects, int $pageNumber): array
    {
        $boxColorInfo = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($dictionary, 'BoxColorInfo'), $objects);
        $separationInfo = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($dictionary, 'SeparationInfo'), $objects);
        $presSteps = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($dictionary, 'PresSteps'), $objects);
        $separationDictionary = $separationInfo['dictionary'];
        $presStepsDictionary = $presSteps['dictionary'];

        return [
            'page' => $pageNumber,
            'pageObject' => $reference . ' R',
            'boxColorInfoObject' => $boxColorInfo['object'],
            'boxColorInfo' => $boxColorInfo['dictionary'] === null
                ? []
                : $this->extractPdfBoxColorInfoEntries($boxColorInfo['dictionary'], $objects),
            'separationInfoObject' => $separationInfo['object'],
            'separationPages' => $separationDictionary === null
                ? []
                : $this->collectPdfReferencesFromValue($this->extractPdfValueForName($separationDictionary, 'Pages'), $objects),
            'separationDeviceColorant' => $separationDictionary === null
                ? null
                : $this->extractPdfStringOrNameValue($separationDictionary, 'DeviceColorant'),
            'separationColorSpace' => $separationDictionary === null
                ? null
                : $this->extractPdfColorSpaceNameValue($separationDictionary, 'ColorSpace', $objects),
            'presStepsObject' => $presSteps['object'],
            'presStepsSubtype' => $presStepsDictionary === null ? null : $this->extractPdfNameToken($presStepsDictionary, 'S'),
            'presStepsNext' => $presStepsDictionary === null
                ? []
                : $this->collectPdfReferencesFromValue($this->extractPdfValueForName($presStepsDictionary, 'Next'), $objects),
        ];
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     * @return array{dictionary:string|null, object:string|null}
     */
    private function resolvePdfDictionaryValue(?array $value, array $objects): array
    {
        if ($value === null) {
            return ['dictionary' => null, 'object' => null];
        }

        if ($value['kind'] === 'dictionary') {
            return ['dictionary' => $value['value'], 'object' => 'inline'];
        }

        if ($value['kind'] === 'reference') {
            return [
                'dictionary' => $objects[$this->pdfReferenceKey($value['value'])] ?? null,
                'object' => $value['value'],
            ];
        }

        return ['dictionary' => null, 'object' => null];
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{box:string, color:list<float>|null, width:float|null, style:string|null}>
     */
    private function extractPdfBoxColorInfoEntries(string $dictionary, array $objects): array
    {
        $entries = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            if ($entry['key'] === 'Type') {
                continue;
            }

            $boxInfo = $this->resolvePdfDictionaryValue($entry['value'], $objects);
            if ($boxInfo['dictionary'] === null) {
                continue;
            }

            $entries[] = [
                'box' => $entry['key'],
                'color' => $this->extractPdfNumberArrayValues($boxInfo['dictionary'], 'C'),
                'width' => $this->extractPdfNumberToken($boxInfo['dictionary'], 'W'),
                'style' => $this->extractPdfNameToken($boxInfo['dictionary'], 'S'),
            ];
        }

        usort($entries, static fn (array $a, array $b): int => strcmp($a['box'], $b['box']));

        return $entries;
    }

    /**
     * @param array<string, mixed> $metadata
     */
    private function pdfPageProductionMetadataHasValues(array $metadata): bool
    {
        return ($metadata['boxColorInfo'] ?? []) !== []
            || ($metadata['separationInfoObject'] ?? null) !== null
            || ($metadata['presStepsObject'] ?? null) !== null;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, language:string|null, userUnit:float|null, tabOrder:string|null, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, thumbnailObject:string|null, lastModified:string|null}>
     */
    private function extractPdfPageDisplayMetadata(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $metadata = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageDisplayMetadataFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $metadata,
                $pageNumber,
                0
            );
        }

        if ($metadata === []) {
            uksort($objects, fn (string $a, string $b): int => $this->pdfReferenceSortKey($a . ' R') <=> $this->pdfReferenceSortKey($b . ' R'));
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $summary = $this->summarizePdfPageDisplayMetadata($body, $reference, $objects, $pageNumber);
                if ($this->pdfPageDisplayMetadataHasValues($summary)) {
                    $metadata[] = $summary;
                }
            }
        }

        return $metadata;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, language:string|null, userUnit:float|null, tabOrder:string|null, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, thumbnailObject:string|null, lastModified:string|null}> $metadata
     */
    private function collectPdfPageDisplayMetadataFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$metadata,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $summary = $this->summarizePdfPageDisplayMetadata($body, $reference, $objects, $pageNumber);
            if ($this->pdfPageDisplayMetadataHasValues($summary)) {
                $metadata[] = $summary;
            }

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageDisplayMetadataFromTree(
                $objects,
                $kidReference,
                $visited,
                $metadata,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, language:string|null, userUnit:float|null, tabOrder:string|null, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, thumbnailObject:string|null, lastModified:string|null}
     */
    private function summarizePdfPageDisplayMetadata(string $dictionary, ?string $reference, array $objects, int $pageNumber): array
    {
        $group = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'Group', $objects);

        return [
            'page' => $pageNumber,
            'pageObject' => $reference === null ? null : $reference . ' R',
            'language' => $this->extractPdfStringOrNameValue($dictionary, 'Lang'),
            'userUnit' => $this->extractPdfNumberToken($dictionary, 'UserUnit'),
            'tabOrder' => $this->extractPdfNameToken($dictionary, 'Tabs'),
            'groupSubtype' => $group === null ? null : $this->extractPdfNameToken($group, 'S'),
            'groupColorSpace' => $group === null ? null : $this->extractPdfColorSpaceNameValue($group, 'CS', $objects),
            'groupIsolated' => $group === null ? null : $this->extractPdfBooleanToken($group, 'I'),
            'groupKnockout' => $group === null ? null : $this->extractPdfBooleanToken($group, 'K'),
            'thumbnailObject' => $this->extractPdfReferenceToken($dictionary, 'Thumb'),
            'lastModified' => $this->extractPdfStringOrNameValue($dictionary, 'LastModified'),
        ];
    }

    /**
     * @param array<string, mixed> $metadata
     */
    private function pdfPageDisplayMetadataHasValues(array $metadata): bool
    {
        foreach (['language', 'userUnit', 'tabOrder', 'groupSubtype', 'groupColorSpace', 'groupIsolated', 'groupKnockout', 'thumbnailObject', 'lastModified'] as $key) {
            if (($metadata[$key] ?? null) !== null) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, language:string|null, userUnit:float|null, tabOrder:string|null, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, thumbnailObject:string|null, lastModified:string|null}> $metadata
     * @return array<string, int>
     */
    private function summarizePdfPageTabOrders(array $metadata): array
    {
        $orders = [];
        foreach ($metadata as $pageDisplay) {
            $tabOrder = $pageDisplay['tabOrder'] ?? null;
            if (!is_string($tabOrder) || $tabOrder === '') {
                continue;
            }

            $orders[$tabOrder] = ($orders[$tabOrder] ?? 0) + 1;
        }
        ksort($orders);

        return $orders;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, thumbnailObject:string|null, valueKind:string, subtype:string|null, validImage:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, reviewStatus:string, issues:list<string>}>
     */
    private function extractPdfPageThumbnails(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $thumbnails = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageThumbnailsFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $thumbnails,
                $pageNumber,
                0
            );
        }

        if ($thumbnails === []) {
            $pageNumber = 0;
            uksort($objects, fn (string $a, string $b): int => $this->pdfReferenceSortKey($a . ' R') <=> $this->pdfReferenceSortKey($b . ' R'));
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $summary = $this->summarizePdfPageThumbnail($body, $reference, $objects, $pageNumber);
                if ($summary !== null) {
                    $thumbnails[] = $summary;
                }
            }
        }

        usort(
            $thumbnails,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['thumbnailObject'] ?? '',
                $a['pageObject'] ?? '',
            ] <=> [
                $b['page'],
                $b['thumbnailObject'] ?? '',
                $b['pageObject'] ?? '',
            ]
        );

        return array_values($thumbnails);
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, thumbnailObject:string|null, valueKind:string, subtype:string|null, validImage:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, reviewStatus:string, issues:list<string>}> $thumbnails
     */
    private function collectPdfPageThumbnailsFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$thumbnails,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $summary = $this->summarizePdfPageThumbnail($body, $reference, $objects, $pageNumber);
            if ($summary !== null) {
                $thumbnails[] = $summary;
            }

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageThumbnailsFromTree(
                $objects,
                $kidReference,
                $visited,
                $thumbnails,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, thumbnailObject:string|null, valueKind:string, subtype:string|null, validImage:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, reviewStatus:string, issues:list<string>}|null
     */
    private function summarizePdfPageThumbnail(string $dictionary, ?string $reference, array $objects, int $pageNumber): ?array
    {
        $value = $this->extractPdfValueForName($dictionary, 'Thumb');
        if ($value === null) {
            return null;
        }

        $thumbnailObject = null;
        $thumbnailDictionary = null;
        $issues = [];

        if ($value['kind'] === 'reference') {
            $thumbnailObject = $value['value'];
            $thumbnailDictionary = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($thumbnailDictionary === null) {
                $issues[] = 'missing-thumbnail-object';
            }
        } elseif ($value['kind'] === 'dictionary') {
            $thumbnailDictionary = $value['value'];
        } else {
            $issues[] = 'invalid-thumbnail-value';
        }

        $subtype = null;
        $validImage = false;
        $width = null;
        $height = null;
        $bitsPerComponent = null;
        $colorSpace = null;
        $filters = [];
        $interpolate = null;
        $imageMask = null;
        $softMask = null;
        $stream = [
            'bytes' => null,
            'sha256' => null,
            'skipped' => null,
        ];

        if ($thumbnailDictionary !== null) {
            $subtype = $this->extractPdfNameToken($thumbnailDictionary, 'Subtype');
            $validImage = $subtype === 'Image';
            if (!$validImage) {
                $issues[] = $subtype === null ? 'missing-image-subtype' : 'non-image-thumbnail';
            } else {
                $width = $this->extractPdfIntegerToken($thumbnailDictionary, 'Width');
                $height = $this->extractPdfIntegerToken($thumbnailDictionary, 'Height');
                $bitsPerComponent = $this->extractPdfIntegerToken($thumbnailDictionary, 'BitsPerComponent');
                $colorSpace = $this->extractPdfColorSpaceValue($thumbnailDictionary, $objects);
                $filters = $this->extractPdfFilterNames($thumbnailDictionary, $objects);
                $interpolate = $this->extractPdfBooleanToken($thumbnailDictionary, 'Interpolate');
                $imageMask = $this->extractPdfBooleanToken($thumbnailDictionary, 'ImageMask');
                $softMask = $this->extractPdfReferenceToken($thumbnailDictionary, 'SMask') ?? $this->extractPdfNameToken($thumbnailDictionary, 'SMask');
                $stream = $this->summarizePdfImageStream($thumbnailDictionary);

                if ($width === null || $height === null) {
                    $issues[] = 'missing-thumbnail-dimensions';
                }
                if ($stream['bytes'] === null) {
                    $issues[] = 'missing-thumbnail-stream';
                }
                if ($stream['skipped'] !== null) {
                    $issues[] = 'thumbnail-stream-' . $stream['skipped'];
                }
            }
        }

        $issues = array_values(array_unique($issues));
        sort($issues);

        return [
            'page' => $pageNumber,
            'pageObject' => $reference === null ? null : $reference . ' R',
            'thumbnailObject' => $thumbnailObject,
            'valueKind' => $value['kind'],
            'subtype' => $subtype,
            'validImage' => $validImage,
            'width' => $width,
            'height' => $height,
            'bitsPerComponent' => $bitsPerComponent,
            'colorSpace' => $colorSpace,
            'filters' => $filters,
            'interpolate' => $interpolate,
            'imageMask' => $imageMask,
            'softMask' => $softMask,
            'streamBytes' => $stream['bytes'],
            'streamSha256' => $stream['sha256'],
            'streamSkipped' => $stream['skipped'],
            'reviewStatus' => $issues === [] ? 'accepted' : 'review',
            'issues' => $issues,
        ];
    }

    /**
     * @param list<array{page:int, pageObject:string|null, thumbnailObject:string|null, valueKind:string, subtype:string|null, validImage:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, reviewStatus:string, issues:list<string>}> $thumbnails
     * @return array{reviewStatus:string, pageCount:int|null, thumbnailCount:int, thumbnailPages:list<int>, imageThumbnailCount:int, missingObjectCount:int, nonImageCount:int, missingStreamCount:int, skippedStreamCount:int, streamCount:int, colorSpaces:array<string, int>, filters:array<string, int>, issues:list<string>}|array{}
     */
    private function summarizePdfPageThumbnailPolicy(array $thumbnails, ?int $pageCount): array
    {
        if ($thumbnails === []) {
            return [];
        }

        $thumbnailPages = [];
        $imageThumbnailCount = 0;
        $missingObjectCount = 0;
        $nonImageCount = 0;
        $missingStreamCount = 0;
        $skippedStreamCount = 0;
        $streamCount = 0;
        $colorSpaces = [];
        $filters = [];
        $issues = [];

        foreach ($thumbnails as $thumbnail) {
            if (isset($thumbnail['page']) && is_int($thumbnail['page']) && $thumbnail['page'] > 0) {
                $thumbnailPages[$thumbnail['page']] = true;
            }
            if (($thumbnail['validImage'] ?? false) === true) {
                $imageThumbnailCount++;
            }
            if (($thumbnail['streamBytes'] ?? null) !== null) {
                $streamCount++;
            }
            if (($thumbnail['streamSkipped'] ?? null) !== null) {
                $skippedStreamCount++;
            }

            $colorSpace = $thumbnail['colorSpace'] ?? null;
            if (is_string($colorSpace) && $colorSpace !== '') {
                $colorSpaces[$colorSpace] = ($colorSpaces[$colorSpace] ?? 0) + 1;
            }
            foreach (($thumbnail['filters'] ?? []) as $filter) {
                if (!is_string($filter) || $filter === '') {
                    continue;
                }
                $filters[$filter] = ($filters[$filter] ?? 0) + 1;
            }

            foreach (($thumbnail['issues'] ?? []) as $issue) {
                if (!is_string($issue) || $issue === '') {
                    continue;
                }
                $issues[$issue] = true;
                if ($issue === 'missing-thumbnail-object') {
                    $missingObjectCount++;
                } elseif ($issue === 'non-image-thumbnail' || $issue === 'missing-image-subtype' || $issue === 'invalid-thumbnail-value') {
                    $nonImageCount++;
                } elseif ($issue === 'missing-thumbnail-stream') {
                    $missingStreamCount++;
                }
            }
        }

        $thumbnailPages = array_map('intval', array_keys($thumbnailPages));
        sort($thumbnailPages);
        ksort($colorSpaces);
        ksort($filters);
        $issues = array_keys($issues);
        sort($issues);

        return [
            'reviewStatus' => $issues === [] ? 'accepted' : 'review',
            'pageCount' => $pageCount,
            'thumbnailCount' => count($thumbnails),
            'thumbnailPages' => $thumbnailPages,
            'imageThumbnailCount' => $imageThumbnailCount,
            'missingObjectCount' => $missingObjectCount,
            'nonImageCount' => $nonImageCount,
            'missingStreamCount' => $missingStreamCount,
            'skippedStreamCount' => $skippedStreamCount,
            'streamCount' => $streamCount,
            'colorSpaces' => $colorSpaces,
            'filters' => $filters,
            'issues' => $issues,
        ];
    }

    /**
     * @return list<array{page:int, pageObject:string|null, viewportObject:string|null, source:string, name:string|null, bbox:list<float>|null, measureSubtype:string|null, scaleRatio:string|null, xUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, yUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, distanceUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, areaUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, angleUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>}>
     */
    private function extractPdfPageViewports(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $viewports = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageViewportsFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $viewports,
                $pageNumber,
                0
            );
        }

        if ($viewports === []) {
            uksort($objects, fn (string $a, string $b): int => $this->pdfReferenceSortKey($a . ' R') <=> $this->pdfReferenceSortKey($b . ' R'));
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                foreach ($this->summarizePdfPageViewports($body, $reference, $objects) as $viewport) {
                    $viewport['page'] = $pageNumber;
                    $viewports[] = $viewport;
                }
            }
        }

        return $viewports;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, viewportObject:string|null, source:string, name:string|null, bbox:list<float>|null, measureSubtype:string|null, scaleRatio:string|null, xUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, yUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, distanceUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, areaUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, angleUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>}> $viewports
     */
    private function collectPdfPageViewportsFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$viewports,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            foreach ($this->summarizePdfPageViewports($body, $reference, $objects) as $viewport) {
                $viewport['page'] = $pageNumber;
                $viewports[] = $viewport;
            }

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageViewportsFromTree(
                $objects,
                $kidReference,
                $visited,
                $viewports,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, viewportObject:string|null, source:string, name:string|null, bbox:list<float>|null, measureSubtype:string|null, scaleRatio:string|null, xUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, yUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, distanceUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, areaUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, angleUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>}>
     */
    private function summarizePdfPageViewports(string $dictionary, ?string $pageReference, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'VP');
        if ($value === null) {
            return [];
        }

        $values = $value['kind'] === 'array' ? $this->pdfTopLevelArrayValues($value['value']) : [$value];
        $viewports = [];
        foreach ($values as $index => $viewportValue) {
            $sourceSuffix = $value['kind'] === 'array' ? 'VP[' . $index . ']' : 'VP';
            $viewport = $this->summarizePdfViewportValue(
                $viewportValue,
                $objects,
                $pageReference,
                ($pageReference === null ? 'page' : 'page:' . $pageReference . ' R') . '.' . $sourceSuffix
            );
            if ($viewport !== null) {
                $viewports[] = $viewport;
            }
        }

        return $viewports;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, viewportObject:string|null, source:string, name:string|null, bbox:list<float>|null, measureSubtype:string|null, scaleRatio:string|null, xUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, yUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, distanceUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, areaUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>, angleUnits:list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>}|null
     */
    private function summarizePdfViewportValue(array $value, array $objects, ?string $pageReference, string $source): ?array
    {
        $dictionary = null;
        $viewportObject = null;
        if ($value['kind'] === 'dictionary') {
            $dictionary = $value['value'];
        } elseif ($value['kind'] === 'reference') {
            $viewportObject = $value['value'];
            $dictionary = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        }

        if ($dictionary === null) {
            return null;
        }

        $measure = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'Measure', $objects);

        return [
            'page' => 0,
            'pageObject' => $pageReference === null ? null : $pageReference . ' R',
            'viewportObject' => $viewportObject,
            'source' => $source,
            'name' => $this->extractPdfStringOrNameValue($dictionary, 'Name'),
            'bbox' => $this->extractPdfNumberArrayToken($dictionary, 'BBox', 4),
            'measureSubtype' => $measure === null ? null : $this->extractPdfNameToken($measure, 'Subtype'),
            'scaleRatio' => $measure === null ? null : $this->extractPdfStringOrNameValue($measure, 'R'),
            'xUnits' => $measure === null ? [] : $this->extractPdfMeasureUnitFormats($measure, 'X', $objects),
            'yUnits' => $measure === null ? [] : $this->extractPdfMeasureUnitFormats($measure, 'Y', $objects),
            'distanceUnits' => $measure === null ? [] : $this->extractPdfMeasureUnitFormats($measure, 'D', $objects),
            'areaUnits' => $measure === null ? [] : $this->extractPdfMeasureUnitFormats($measure, 'A', $objects),
            'angleUnits' => $measure === null ? [] : $this->extractPdfMeasureUnitFormats($measure, 'T', $objects),
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}>
     */
    private function extractPdfMeasureUnitFormats(string $dictionary, string $name, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return [];
        }

        $values = $value['kind'] === 'array' ? $this->pdfTopLevelArrayValues($value['value']) : [$value];
        $units = [];
        foreach ($values as $unitValue) {
            $unit = $this->summarizePdfMeasureUnitFormatValue($unitValue, $objects);
            if ($unit !== null) {
                $units[] = $unit;
            }
        }

        return $units;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{unit:string|null, conversionFactor:float|null, fractionalDisplay:string|null}|null
     */
    private function summarizePdfMeasureUnitFormatValue(array $value, array $objects): ?array
    {
        $dictionary = null;
        if ($value['kind'] === 'dictionary') {
            $dictionary = $value['value'];
        } elseif ($value['kind'] === 'reference') {
            $dictionary = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        }

        if ($dictionary === null) {
            return null;
        }

        $unit = $this->extractPdfStringOrNameValue($dictionary, 'U');
        $conversionFactor = $this->extractPdfNumberToken($dictionary, 'C');
        $fractionalDisplay = $this->extractPdfStringOrNameValue($dictionary, 'F');
        if ($unit === null && $conversionFactor === null && $fractionalDisplay === null) {
            return null;
        }

        return [
            'unit' => $unit,
            'conversionFactor' => $conversionFactor,
            'fractionalDisplay' => $fractionalDisplay,
        ];
    }

    /**
     * @return list<array{page:int, pageObject:string|null, duration:float|null, transitionType:string|null, transitionDuration:float|null, direction:string|null, dimension:string|null, motion:string|null, scale:float|null, background:bool|null}>
     */
    private function extractPdfPageTimings(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $timings = [];
        $visited = [];
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageTimingsFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $timings,
                0
            );
        }

        if ($timings === []) {
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $timings[] = $this->summarizePdfPageTiming($body, $reference, $objects);
            }
        }

        foreach ($timings as $index => &$timing) {
            $timing['page'] = $index + 1;
        }
        unset($timing);

        return array_values(array_filter(
            $timings,
            fn (array $timing): bool => ($timing['duration'] ?? null) !== null || $this->pdfPageTimingHasTransition($timing)
        ));
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, duration:float|null, transitionType:string|null, transitionDuration:float|null, direction:string|null, dimension:string|null, motion:string|null, scale:float|null, background:bool|null}> $timings
     */
    private function collectPdfPageTimingsFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$timings,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $timings[] = $this->summarizePdfPageTiming($body, $reference, $objects);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageTimingsFromTree(
                $objects,
                $kidReference,
                $visited,
                $timings,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, duration:float|null, transitionType:string|null, transitionDuration:float|null, direction:string|null, directionLabel:string|null, dimension:string|null, motion:string|null, scale:float|null, background:bool|null}
     */
    private function summarizePdfPageTiming(string $dictionary, ?string $reference, array $objects): array
    {
        $transition = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'Trans', $objects);
        $direction = $transition === null ? null : $this->extractPdfTransitionDirection($transition);

        return [
            'page' => 0,
            'pageObject' => $reference === null ? null : $reference . ' R',
            'duration' => $this->extractPdfNumberToken($dictionary, 'Dur'),
            'transitionType' => $transition === null ? null : $this->extractPdfNameToken($transition, 'S'),
            'transitionDuration' => $transition === null ? null : $this->extractPdfNumberToken($transition, 'D'),
            'direction' => $direction,
            'directionLabel' => $direction === null ? null : $this->pdfTransitionDirectionLabel($direction),
            'dimension' => $transition === null ? null : $this->extractPdfNameToken($transition, 'Dm'),
            'motion' => $transition === null ? null : $this->extractPdfNameToken($transition, 'M'),
            'scale' => $transition === null ? null : $this->extractPdfNumberToken($transition, 'SS'),
            'background' => $transition === null ? null : $this->extractPdfBooleanToken($transition, 'B'),
        ];
    }

    private function extractPdfTransitionDirection(string $dictionary): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, 'Di');
        if ($value === null) {
            return null;
        }
        if ($value['kind'] === 'number') {
            return $this->normalizePdfNumberString($value['value']);
        }
        if (in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
            $direction = trim($value['value']);

            return $direction === '' ? null : $direction;
        }

        return null;
    }

    private function pdfTransitionDirectionLabel(string $direction): ?string
    {
        $direction = trim($direction);
        if ($direction === '') {
            return null;
        }

        if (preg_match('/\A-?(?:\d+(?:\.\d*)?|\.\d+)\z/', $direction) === 1) {
            $degrees = $this->normalizePdfNumberString($direction);

            return [
                '0' => 'left-to-right',
                '90' => 'bottom-to-top',
                '180' => 'right-to-left',
                '270' => 'top-to-bottom',
                '315' => 'top-left-to-bottom-right',
            ][$degrees] ?? 'degrees:' . $degrees;
        }

        $label = strtolower((string) preg_replace('/(?<!^)[A-Z]/', '-$0', $direction));
        $label = preg_replace('/[^a-z0-9]+/', '-', $label);
        if (!is_string($label)) {
            return null;
        }
        $label = trim($label, '-');

        return $label === '' ? null : $label;
    }

    private function normalizePdfNumberString(string $number): string
    {
        $number = trim($number);
        if ($number === '') {
            return '';
        }
        $float = (float) $number;
        if (fmod($float, 1.0) === 0.0) {
            return (string) (int) $float;
        }

        return rtrim(rtrim(sprintf('%.12F', $float), '0'), '.');
    }

    /**
     * @param array<string, mixed> $timing
     */
    private function pdfPageTimingHasTransition(array $timing): bool
    {
        foreach (['transitionType', 'transitionDuration', 'direction', 'dimension', 'motion', 'scale', 'background'] as $key) {
            if (($timing[$key] ?? null) !== null) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, duration:float|null, transitionType:string|null, transitionDuration:float|null, direction:string|null, directionLabel:string|null, dimension:string|null, motion:string|null, scale:float|null, background:bool|null}> $pageTimings
     * @return array{reviewStatus:string, pageCount:int, timingCount:int, durationCount:int, transitionCount:int, pagesWithTiming:list<int>, durationPages:list<int>, transitionPages:list<int>, transitionTypes:array<string, int>, directionLabels:array<string, int>, maxDuration:float|null, maxTransitionDuration:float|null, issues:list<string>}|array{}
     */
    private function summarizePdfPageTimingPolicy(array $pageTimings, ?int $pageCount): array
    {
        if ($pageTimings === []) {
            return [];
        }

        $pagesWithTiming = [];
        $durationPages = [];
        $transitionPages = [];
        $maxDuration = null;
        $maxTransitionDuration = null;
        $hasDirection = false;
        $hasMotion = false;
        $hasScale = false;
        $hasBackground = false;

        foreach ($pageTimings as $timing) {
            $page = isset($timing['page']) && is_int($timing['page']) ? $timing['page'] : null;
            if ($page !== null) {
                $pagesWithTiming[$page] = true;
            }

            $duration = $timing['duration'] ?? null;
            if (is_int($duration) || is_float($duration)) {
                if ($page !== null) {
                    $durationPages[$page] = true;
                }
                $maxDuration = $maxDuration === null ? (float) $duration : max($maxDuration, (float) $duration);
            }

            if ($this->pdfPageTimingHasTransition($timing)) {
                if ($page !== null) {
                    $transitionPages[$page] = true;
                }
                $transitionDuration = $timing['transitionDuration'] ?? null;
                if (is_int($transitionDuration) || is_float($transitionDuration)) {
                    $maxTransitionDuration = $maxTransitionDuration === null
                        ? (float) $transitionDuration
                        : max($maxTransitionDuration, (float) $transitionDuration);
                }
            }

            $hasDirection = $hasDirection || is_string($timing['directionLabel'] ?? null);
            $hasMotion = $hasMotion || is_string($timing['dimension'] ?? null) || is_string($timing['motion'] ?? null);
            $hasScale = $hasScale || is_int($timing['scale'] ?? null) || is_float($timing['scale'] ?? null);
            $hasBackground = $hasBackground || ($timing['background'] ?? null) === true;
        }

        $issues = [];
        if ($durationPages !== []) {
            $issues[] = 'auto-advance-duration';
        }
        if ($transitionPages !== []) {
            $issues[] = 'page-transition-effects';
        }
        if ($hasDirection) {
            $issues[] = 'transition-direction-overrides';
        }
        if ($hasMotion) {
            $issues[] = 'transition-motion-overrides';
        }
        if ($hasScale) {
            $issues[] = 'transition-scale-overrides';
        }
        if ($hasBackground) {
            $issues[] = 'transition-background-fill';
        }
        sort($issues);

        $pageList = array_keys($pagesWithTiming);
        $durationPageList = array_keys($durationPages);
        $transitionPageList = array_keys($transitionPages);
        sort($pageList);
        sort($durationPageList);
        sort($transitionPageList);

        return [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'pageCount' => $pageCount ?? 0,
            'timingCount' => count($pageTimings),
            'durationCount' => count($durationPageList),
            'transitionCount' => count($transitionPageList),
            'pagesWithTiming' => $pageList,
            'durationPages' => $durationPageList,
            'transitionPages' => $transitionPageList,
            'transitionTypes' => $this->summarizePdfPageTransitionTypes($pageTimings),
            'directionLabels' => $this->summarizePdfPageTransitionDirectionLabels($pageTimings),
            'maxDuration' => $maxDuration,
            'maxTransitionDuration' => $maxTransitionDuration,
            'issues' => $issues,
        ];
    }

    /**
     * @return list<array{page:int, pageObject:string|null, trigger:string, triggerLabel:string, source:string, actionType:string, actionTarget:string|null, scriptBytes:int|null, scriptSha256:string|null}>
     */
    private function extractPdfPageActions(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $actions = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageActionsFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $actions,
                $pageNumber,
                0
            );
        }

        if ($actions !== []) {
            return $actions;
        }

        foreach ($objects as $reference => $body) {
            if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                continue;
            }

            $pageNumber++;
            $this->collectPdfPageActionsFromPage($body, $reference, $pageNumber, $objects, $actions);
        }

        return $actions;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, trigger:string, triggerLabel:string, source:string, actionType:string, actionTarget:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     */
    private function collectPdfPageActionsFromTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$actions,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $this->collectPdfPageActionsFromPage($body, $reference, $pageNumber, $objects, $actions);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageActionsFromTree(
                $objects,
                $this->pdfReferenceKey($kidReference),
                $visited,
                $actions,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @param list<array{page:int, pageObject:string|null, trigger:string, triggerLabel:string, source:string, actionType:string, actionTarget:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     */
    private function collectPdfPageActionsFromPage(
        string $pageDictionary,
        string $pageReference,
        int $pageNumber,
        array $objects,
        array &$actions
    ): void {
        $additionalActions = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'AA', $objects);
        if ($additionalActions === null) {
            return;
        }

        $pageObject = $pageReference . ' R';
        foreach (['O' => 'page-open', 'C' => 'page-close'] as $trigger => $triggerLabel) {
            $value = $this->extractPdfValueForName($additionalActions, $trigger);
            if ($value === null) {
                continue;
            }

            $source = 'page:' . $pageObject . '.AA.' . $trigger;
            $summary = $this->summarizePdfPageActionValue($value, $objects, $source);
            if ($summary === null) {
                continue;
            }

            $actions[] = [
                'page' => $pageNumber,
                'pageObject' => $pageObject,
                'trigger' => $trigger,
                'triggerLabel' => $triggerLabel,
                'source' => $source,
                'actionType' => $summary['type'],
                'actionTarget' => $summary['target'],
                'scriptBytes' => $summary['scriptBytes'],
                'scriptSha256' => $summary['scriptSha256'],
            ];
        }
    }

    /**
     * @param array<string, string> $objects
     * @param array{kind:string, value:string, next:int} $value
     * @return array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}|null
     */
    private function summarizePdfPageActionValue(array $value, array $objects, string $source): ?array
    {
        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return null;
            }

            return $this->summarizePdfActiveActionDictionary($body, $source, $objects);
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfActiveActionDictionary($value['value'], $source, $objects);
        }

        if (in_array($value['kind'], ['literal', 'hex', 'name'], true)) {
            $target = trim($value['value']);
            if ($target === '') {
                return null;
            }

            return [
                'source' => $source,
                'type' => 'Named',
                'target' => $target,
                'scriptBytes' => null,
                'scriptSha256' => null,
            ];
        }

        return null;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, trigger:string, triggerLabel:string, source:string, actionType:string, actionTarget:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @return array{reviewStatus:string, pageCount:int|null, actionCount:int, pagesWithActions:list<int>, openActionPages:list<int>, closeActionPages:list<int>, triggerCounts:array<string, int>, actionTypes:array<string, int>, scriptActionCount:int, remoteTargetCount:int, remoteTargetSchemes?:array<string, int>, launchActionCount:int, embeddedFileActionCount?:int, issues:list<string>}|array{}
     */
    private function summarizePdfPageActionPolicy(array $actions, ?int $pageCount): array
    {
        if ($actions === []) {
            return [];
        }

        $pages = [];
        $openPages = [];
        $closePages = [];
        $triggerCounts = [];
        $actionTypes = [];
        $scriptActionCount = 0;
        $remoteTargetCount = 0;
        $remoteTargetSchemes = [];
        $launchActionCount = 0;
        $embeddedFileActionCount = 0;
        $issues = [];

        foreach ($actions as $action) {
            $page = is_int($action['page'] ?? null) ? $action['page'] : null;
            if ($page !== null) {
                $pages[$page] = true;
            }

            $trigger = is_string($action['trigger'] ?? null) ? $action['trigger'] : '';
            if ($trigger !== '') {
                $triggerCounts[$trigger] = ($triggerCounts[$trigger] ?? 0) + 1;
                if ($trigger === 'O') {
                    $issues[] = 'page-open-action';
                    if ($page !== null) {
                        $openPages[$page] = true;
                    }
                } elseif ($trigger === 'C') {
                    $issues[] = 'page-close-action';
                    if ($page !== null) {
                        $closePages[$page] = true;
                    }
                }
            }

            $type = is_string($action['actionType'] ?? null) ? $action['actionType'] : '';
            if ($type !== '') {
                $actionTypes[$type] = ($actionTypes[$type] ?? 0) + 1;
                if ($type === 'JavaScript') {
                    $issues[] = 'script-action';
                } elseif ($type === 'Launch') {
                    $launchActionCount++;
                    $issues[] = 'launch-action';
                } elseif ($type === 'SubmitForm') {
                    $issues[] = 'submit-form-action';
                } elseif ($type === 'ImportData') {
                    $issues[] = 'import-data-action';
                } elseif ($type === 'ResetForm') {
                    $issues[] = 'reset-form-action';
                } elseif ($type === 'URI') {
                    $issues[] = 'uri-action';
                } elseif ($type === 'GoToE') {
                    $embeddedFileActionCount++;
                    $issues[] = 'embedded-file-action';
                }
            }

            if (($action['scriptBytes'] ?? null) !== null) {
                $scriptActionCount++;
                $issues[] = 'script-action';
            }

            $target = is_string($action['actionTarget'] ?? null) ? $action['actionTarget'] : null;
            $scheme = $this->pdfActionTargetScheme($target);
            if ($scheme !== null && in_array($scheme, ['ftp', 'ftps', 'http', 'https', 'mailto'], true)) {
                $remoteTargetCount++;
                $remoteTargetSchemes[$scheme] = ($remoteTargetSchemes[$scheme] ?? 0) + 1;
                $issues[] = 'remote-action-target';
            }
        }

        ksort($triggerCounts);
        ksort($actionTypes);
        ksort($remoteTargetSchemes);
        $pageList = array_keys($pages);
        $openPageList = array_keys($openPages);
        $closePageList = array_keys($closePages);
        sort($pageList);
        sort($openPageList);
        sort($closePageList);
        $issues = array_values(array_unique($issues));
        sort($issues, SORT_STRING);

        $policy = [
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'pageCount' => $pageCount,
            'actionCount' => count($actions),
            'pagesWithActions' => $pageList,
            'openActionPages' => $openPageList,
            'closeActionPages' => $closePageList,
            'triggerCounts' => $triggerCounts,
            'actionTypes' => $actionTypes,
            'scriptActionCount' => $scriptActionCount,
            'remoteTargetCount' => $remoteTargetCount,
        ];
        if ($remoteTargetSchemes !== []) {
            $policy['remoteTargetSchemes'] = $remoteTargetSchemes;
        }
        $policy['launchActionCount'] = $launchActionCount;
        if ($embeddedFileActionCount > 0) {
            $policy['embeddedFileActionCount'] = $embeddedFileActionCount;
        }
        $policy['issues'] = $issues;

        return $policy;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, duration:float|null, transitionType:string|null, transitionDuration:float|null, direction:string|null, directionLabel:string|null, dimension:string|null, motion:string|null, scale:float|null, background:bool|null}> $pageTimings
     * @return array<string, int>
     */
    private function summarizePdfPageTransitionTypes(array $pageTimings): array
    {
        $types = [];
        foreach ($pageTimings as $pageTiming) {
            $type = $pageTiming['transitionType'] ?? null;
            if (!is_string($type) || $type === '') {
                continue;
            }

            $types[$type] = ($types[$type] ?? 0) + 1;
        }
        ksort($types);

        return $types;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, duration:float|null, transitionType:string|null, transitionDuration:float|null, direction:string|null, directionLabel:string|null, dimension:string|null, motion:string|null, scale:float|null, background:bool|null}> $pageTimings
     * @return array<string, int>
     */
    private function summarizePdfPageTransitionDirectionLabels(array $pageTimings): array
    {
        $directions = [];
        foreach ($pageTimings as $pageTiming) {
            $direction = $pageTiming['directionLabel'] ?? null;
            if (!is_string($direction) || $direction === '') {
                continue;
            }

            $directions[$direction] = ($directions[$direction] ?? 0) + 1;
        }
        ksort($directions);

        return $directions;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, textObjectCount:int, imagePaintCount:int, formPaintCount:int, markedContentBeginCount:int, markedContentEndCount:int, mcidValues:list<int>, propertyNames:list<string>, resourceNames:list<string>}>
     */
    private function extractPdfPageContentStreams(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $streams = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageContentStreamsFromTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                $visited,
                $streams,
                $pageNumber,
                0
            );
        }

        if ($streams === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageStreams = $this->summarizePdfPageContentStreams($body, $reference, null, $objects);
                foreach ($pageStreams as &$stream) {
                    $stream['page'] = $pageNumber;
                }
                unset($stream);
                array_push($streams, ...$pageStreams);
            }
        }

        return $streams;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, textObjectCount:int, imagePaintCount:int, formPaintCount:int, markedContentBeginCount:int, markedContentEndCount:int, mcidValues:list<int>, propertyNames:list<string>, resourceNames:list<string>}> $streams
     */
    private function collectPdfPageContentStreamsFromTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        array &$visited,
        array &$streams,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $pageStreams = $this->summarizePdfPageContentStreams($body, $reference, $resources, $objects);
            foreach ($pageStreams as &$stream) {
                $stream['page'] = $pageNumber;
            }
            unset($stream);
            array_push($streams, ...$pageStreams);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageContentStreamsFromTree(
                $objects,
                $kidReference,
                $resources,
                $visited,
                $streams,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, textObjectCount:int, imagePaintCount:int, formPaintCount:int, markedContentBeginCount:int, markedContentEndCount:int, mcidValues:list<int>, propertyNames:list<string>, resourceNames:list<string>}>
     */
    private function summarizePdfPageContentStreams(string $pageDictionary, string $pageReference, ?string $resources, array $objects): array
    {
        $value = $this->extractPdfValueForName($pageDictionary, 'Contents');
        if ($value === null) {
            return [];
        }

        $xobjectTypes = $resources === null ? [] : $this->pdfPageXObjectResourceTypes($resources, $objects);
        $contentValues = [];
        if ($value['kind'] === 'array') {
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $index => $arrayValue) {
                $contentValues[] = [$arrayValue, 'Contents[' . $index . ']'];
            }
        } else {
            $contentValues[] = [$value, 'Contents'];
        }

        $streams = [];
        foreach ($contentValues as [$contentValue, $sourceSuffix]) {
            $stream = $this->summarizePdfPageContentStreamValue(
                $contentValue,
                $objects,
                $pageReference,
                'page:' . $pageReference . ' R.' . $sourceSuffix,
                $xobjectTypes
            );
            if ($stream !== null) {
                $streams[] = $stream;
            }
        }

        return $streams;
    }

    /**
     * @param array{kind:string, value:string, next?:int} $value
     * @param array<string, string> $objects
     * @param array<string, string> $xobjectTypes
     * @return array{page:int, pageObject:string|null, contentObject:string|null, source:string, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, textObjectCount:int, imagePaintCount:int, formPaintCount:int, markedContentBeginCount:int, markedContentEndCount:int, mcidValues:list<int>, propertyNames:list<string>, resourceNames:list<string>}|null
     */
    private function summarizePdfPageContentStreamValue(array $value, array $objects, string $pageReference, string $source, array $xobjectTypes): ?array
    {
        $contentObject = null;
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $contentDictionary = $objects[$reference] ?? null;
            $contentObject = $reference . ' R';
        } elseif ($value['kind'] === 'dictionary') {
            $contentDictionary = $value['value'];
        } else {
            return null;
        }

        if ($contentDictionary === null) {
            return null;
        }

        $filters = $this->extractPdfFilterNames($contentDictionary, $objects);
        $bytes = $this->extractPdfStreamBytes($contentDictionary);
        $summary = [
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'contentObject' => $contentObject,
            'source' => $source,
            'filters' => $filters,
            'streamBytes' => $bytes === null ? null : strlen($bytes),
            'streamSha256' => null,
            'streamSkipped' => null,
            'textObjectCount' => 0,
            'imagePaintCount' => 0,
            'formPaintCount' => 0,
            'markedContentBeginCount' => 0,
            'markedContentEndCount' => 0,
            'mcidValues' => [],
            'propertyNames' => [],
            'resourceNames' => [],
        ];

        if ($bytes === null) {
            return $summary;
        }
        if ($filters !== []) {
            $summary['streamSkipped'] = 'filtered';

            return $summary;
        }
        if (strlen($bytes) > self::MAX_PAGE_CONTENT_STREAM_BYTES) {
            $summary['streamSkipped'] = 'too-large';

            return $summary;
        }

        $summary['streamSha256'] = hash('sha256', $bytes);
        $operators = $this->summarizePdfPageContentOperators($bytes, $xobjectTypes);
        $summary['textObjectCount'] = $operators['textObjectCount'];
        $summary['imagePaintCount'] = $operators['imagePaintCount'];
        $summary['formPaintCount'] = $operators['formPaintCount'];
        $summary['markedContentBeginCount'] = $operators['markedContentBeginCount'];
        $summary['markedContentEndCount'] = $operators['markedContentEndCount'];
        $summary['mcidValues'] = $operators['mcidValues'];
        $summary['propertyNames'] = $operators['propertyNames'];
        $summary['resourceNames'] = $operators['resourceNames'];

        return $summary;
    }

    /**
     * @param array<string, string> $objects
     * @return array<string, string>
     */
    private function pdfPageXObjectResourceTypes(string $resources, array $objects): array
    {
        $xobjectDictionary = $this->extractPdfDictionaryOrReferenceValue($resources, 'XObject', $objects);
        if ($xobjectDictionary === null) {
            return [];
        }

        $types = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($xobjectDictionary) as $entry) {
            $objectDictionary = null;
            if ($entry['value']['kind'] === 'reference') {
                $objectDictionary = $objects[$this->pdfReferenceKey($entry['value']['value'])] ?? null;
            } elseif ($entry['value']['kind'] === 'dictionary') {
                $objectDictionary = $entry['value']['value'];
            }

            if ($objectDictionary === null) {
                continue;
            }
            $subtype = $this->extractPdfNameToken($objectDictionary, 'Subtype');
            if ($subtype !== null && $subtype !== '') {
                $types[$entry['key']] = $subtype;
            }
        }

        return $types;
    }

    /**
     * @param array<string, string> $xobjectTypes
     * @return array{textObjectCount:int, imagePaintCount:int, formPaintCount:int, markedContentBeginCount:int, markedContentEndCount:int, mcidValues:list<int>, propertyNames:list<string>, resourceNames:list<string>}
     */
    private function summarizePdfPageContentOperators(string $bytes, array $xobjectTypes): array
    {
        $summary = [
            'textObjectCount' => (int) preg_match_all('/(?<![A-Za-z0-9])BT(?![A-Za-z0-9])/', $bytes),
            'imagePaintCount' => 0,
            'formPaintCount' => 0,
            'markedContentBeginCount' => (int) preg_match_all('/(?<![A-Za-z0-9])(?:BMC|BDC)(?![A-Za-z0-9])/', $bytes),
            'markedContentEndCount' => (int) preg_match_all('/(?<![A-Za-z0-9])EMC(?![A-Za-z0-9])/', $bytes),
            'mcidValues' => [],
            'propertyNames' => [],
            'resourceNames' => [],
        ];

        if (preg_match_all('/\/([A-Za-z0-9_.#+-]+)\s+Do\b/', $bytes, $matches) >= 1) {
            foreach ($matches[1] as $name) {
                $resourceName = $this->decodePdfNameToken($name);
                if ($resourceName === '') {
                    continue;
                }
                $summary['resourceNames'][] = $resourceName;
                $subtype = $xobjectTypes[$resourceName] ?? null;
                if ($subtype === 'Image') {
                    $summary['imagePaintCount']++;
                } elseif ($subtype === 'Form') {
                    $summary['formPaintCount']++;
                }
            }
        }
        if (preg_match_all('/\/MCID\s+(-?\d+)/', $bytes, $matches) >= 1) {
            foreach ($matches[1] as $mcid) {
                $summary['mcidValues'][] = (int) $mcid;
            }
        }
        if (preg_match_all('/\/([A-Za-z0-9_.#+-]+)(?:\s+(?:<<.*?>>|\/[A-Za-z0-9_.#+-]+))?\s+(?:BMC|BDC)\b/sU', $bytes, $matches) >= 1) {
            foreach ($matches[1] as $name) {
                $propertyName = $this->decodePdfNameToken($name);
                if ($propertyName !== '') {
                    $summary['propertyNames'][] = $propertyName;
                }
            }
        }

        $summary['mcidValues'] = array_values(array_unique($summary['mcidValues']));
        sort($summary['mcidValues']);
        $summary['propertyNames'] = $this->uniqueStrings($summary['propertyNames']);
        $summary['resourceNames'] = $this->uniqueStrings($summary['resourceNames']);

        return $summary;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, textObjectCount:int, imagePaintCount:int, formPaintCount:int, markedContentBeginCount:int, markedContentEndCount:int, mcidValues:list<int>, propertyNames:list<string>, resourceNames:list<string>}> $streams
     * @return array<string, int>
     */
    private function summarizePdfPageContentResourceUsage(array $streams): array
    {
        $usage = [];
        foreach ($streams as $stream) {
            foreach ($stream['resourceNames'] as $resourceName) {
                if (!is_string($resourceName) || $resourceName === '') {
                    continue;
                }

                $usage[$resourceName] = ($usage[$resourceName] ?? 0) + 1;
            }
        }

        ksort($usage);

        return $usage;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, operator:string, type:string|null, subtype:string|null, bbox:list<float>|null, attached:list<string>, mcid:int|null, propertyName:string|null}>
     */
    private function extractPdfMarkedContentArtifacts(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $artifacts = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfMarkedContentArtifactsFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $artifacts,
                $pageNumber,
                0
            );
        }

        if ($artifacts === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageArtifacts = $this->summarizePdfPageMarkedContentArtifacts($body, $reference, $objects);
                foreach ($pageArtifacts as &$artifact) {
                    $artifact['page'] = $pageNumber;
                }
                unset($artifact);
                array_push($artifacts, ...$pageArtifacts);
            }
        }

        $artifacts = array_values($artifacts);
        usort(
            $artifacts,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['source'],
                $a['type'] ?? '',
                $a['subtype'] ?? '',
            ] <=> [
                $b['page'],
                $b['source'],
                $b['type'] ?? '',
                $b['subtype'] ?? '',
            ]
        );

        return $artifacts;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, operator:string, type:string|null, subtype:string|null, bbox:list<float>|null, attached:list<string>, mcid:int|null, propertyName:string|null}> $artifacts
     */
    private function collectPdfMarkedContentArtifactsFromPageTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$artifacts,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        if ($this->extractPdfNameToken($body, 'Type') === 'Page') {
            $pageNumber++;
            $pageArtifacts = $this->summarizePdfPageMarkedContentArtifacts($body, $reference, $objects);
            foreach ($pageArtifacts as &$artifact) {
                $artifact['page'] = $pageNumber;
            }
            unset($artifact);
            array_push($artifacts, ...$pageArtifacts);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfMarkedContentArtifactsFromPageTree(
                $objects,
                $kidReference,
                $visited,
                $artifacts,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, operator:string, type:string|null, subtype:string|null, bbox:list<float>|null, attached:list<string>, mcid:int|null, propertyName:string|null}>
     */
    private function summarizePdfPageMarkedContentArtifacts(string $pageDictionary, string $pageReference, array $objects): array
    {
        $value = $this->extractPdfValueForName($pageDictionary, 'Contents');
        if ($value === null) {
            return [];
        }

        $contentValues = [];
        if ($value['kind'] === 'array') {
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $index => $arrayValue) {
                $contentValues[] = [$arrayValue, 'Contents[' . $index . ']'];
            }
        } else {
            $contentValues[] = [$value, 'Contents'];
        }

        $artifacts = [];
        foreach ($contentValues as [$contentValue, $sourceSuffix]) {
            array_push(
                $artifacts,
                ...$this->summarizePdfMarkedContentArtifactsFromStreamValue(
                    $contentValue,
                    $objects,
                    $pageReference,
                    'page:' . $pageReference . ' R.' . $sourceSuffix
                )
            );
        }

        return $artifacts;
    }

    /**
     * @param array{kind:string, value:string, next?:int} $value
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, operator:string, type:string|null, subtype:string|null, bbox:list<float>|null, attached:list<string>, mcid:int|null, propertyName:string|null}>
     */
    private function summarizePdfMarkedContentArtifactsFromStreamValue(array $value, array $objects, string $pageReference, string $source): array
    {
        $contentObject = null;
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $contentDictionary = $objects[$reference] ?? null;
            $contentObject = $reference . ' R';
        } elseif ($value['kind'] === 'dictionary') {
            $contentDictionary = $value['value'];
        } else {
            return [];
        }

        if ($contentDictionary === null || $this->extractPdfFilterNames($contentDictionary, $objects) !== []) {
            return [];
        }

        $bytes = $this->extractPdfStreamBytes($contentDictionary);
        if ($bytes === null || strlen($bytes) > self::MAX_PAGE_CONTENT_STREAM_BYTES) {
            return [];
        }

        return $this->extractPdfMarkedContentArtifactsFromStream(
            $bytes,
            $source,
            $pageReference . ' R',
            $contentObject
        );
    }

    /**
     * @return list<array{page:int, pageObject:string|null, contentObject:string|null, source:string, operator:string, type:string|null, subtype:string|null, bbox:list<float>|null, attached:list<string>, mcid:int|null, propertyName:string|null}>
     */
    private function extractPdfMarkedContentArtifactsFromStream(string $bytes, string $source, string $pageObject, ?string $contentObject): array
    {
        if (preg_match_all('/\/Artifact\b/s', $bytes, $matches, PREG_OFFSET_CAPTURE) < 1) {
            return [];
        }

        $artifacts = [];
        $artifactIndex = 0;
        $length = strlen($bytes);
        foreach ($matches[0] as $match) {
            if (count($artifacts) >= 256) {
                break;
            }

            $cursor = $match[1] + strlen($match[0]);
            while ($cursor < $length && ctype_space($bytes[$cursor])) {
                $cursor++;
            }

            $property = null;
            $operator = null;
            if (preg_match('/\A(BMC|BDC)(?![A-Za-z0-9])/', substr($bytes, $cursor), $operatorMatch) === 1) {
                $operator = $operatorMatch[1];
            } else {
                $property = $this->parsePdfValueAt($bytes, $cursor);
                if ($property === null) {
                    continue;
                }

                $cursor = $property['next'];
                while ($cursor < $length && ctype_space($bytes[$cursor])) {
                    $cursor++;
                }
                if (preg_match('/\A(BMC|BDC)(?![A-Za-z0-9])/', substr($bytes, $cursor), $operatorMatch) !== 1) {
                    continue;
                }
                $operator = $operatorMatch[1];
            }

            $artifact = [
                'page' => 0,
                'pageObject' => $pageObject,
                'contentObject' => $contentObject,
                'source' => $source . '.Artifact[' . $artifactIndex . ']',
                'operator' => $operator,
                'type' => null,
                'subtype' => null,
                'bbox' => null,
                'attached' => [],
                'mcid' => null,
                'propertyName' => null,
            ];

            if ($property !== null && $property['kind'] === 'dictionary') {
                $artifact['type'] = $this->extractPdfNameToken($property['value'], 'Type');
                $artifact['subtype'] = $this->extractPdfNameToken($property['value'], 'Subtype');
                $artifact['bbox'] = $this->extractPdfNumberArrayValues($property['value'], 'BBox');
                $artifact['attached'] = $this->extractPdfArtifactAttachedValues($property['value']);
                $artifact['mcid'] = $this->extractPdfIntegerToken($property['value'], 'MCID');
            } elseif ($property !== null && $property['kind'] === 'name') {
                $artifact['propertyName'] = $property['value'];
            }

            $artifacts[] = $artifact;
            $artifactIndex++;
        }

        return $artifacts;
    }

    /**
     * @return list<string>
     */
    private function extractPdfArtifactAttachedValues(string $dictionary): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'Attached');
        if ($value === null) {
            return [];
        }

        if ($value['kind'] === 'name') {
            return $value['value'] === '' ? [] : [$value['value']];
        }

        if ($value['kind'] !== 'array') {
            return [];
        }

        $attached = [];
        foreach ($this->pdfTopLevelArrayValues($value['value']) as $arrayValue) {
            if ($arrayValue['kind'] === 'name' && $arrayValue['value'] !== '') {
                $attached[] = $arrayValue['value'];
            }
        }

        return $this->uniqueStrings($attached);
    }

    /**
     * @return list<array{page:int, pageObject:string|null, resourceSourceObject:string|null, inherited:bool, categories:list<string>, procSetNames:list<string>, fontNames:list<string>, xobjectNames:list<string>, colorSpaceNames:list<string>, graphicsStateNames:list<string>, patternNames:list<string>, shadingNames:list<string>, propertyNames:list<string>}>
     */
    private function extractPdfPageResourceSources(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $sources = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfPageResourceSourcesFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                null,
                $visited,
                $sources,
                $pageNumber,
                0
            );
        }

        if ($sources === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $summary = $this->summarizePdfPageResourceSource(
                    $body,
                    $reference,
                    null,
                    null,
                    $objects,
                    $pageNumber
                );
                if ($summary !== null) {
                    $sources[] = $summary;
                }
            }
        }

        usort(
            $sources,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['resourceSourceObject'] ?? '',
                $a['pageObject'] ?? '',
            ] <=> [
                $b['page'],
                $b['resourceSourceObject'] ?? '',
                $b['pageObject'] ?? '',
            ]
        );

        return $sources;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, resourceSourceObject:string|null, inherited:bool, categories:list<string>, procSetNames:list<string>, fontNames:list<string>, xobjectNames:list<string>, colorSpaceNames:list<string>, graphicsStateNames:list<string>, patternNames:list<string>, shadingNames:list<string>, propertyNames:list<string>}> $sources
     */
    private function collectPdfPageResourceSourcesFromPageTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        ?string $inheritedResourceSourceObject,
        array &$visited,
        array &$sources,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resourceSourceObject = $ownResources === null ? $inheritedResourceSourceObject : $reference . ' R';
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $summary = $this->summarizePdfPageResourceSource(
                $body,
                $reference,
                $ownResources === null ? $resources : null,
                $ownResources === null ? $resourceSourceObject : null,
                $objects,
                $pageNumber
            );
            if ($summary !== null) {
                $sources[] = $summary;
            }

            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfPageResourceSourcesFromPageTree(
                $objects,
                $kidReference,
                $resources,
                $resourceSourceObject,
                $visited,
                $sources,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, resourceSourceObject:string|null, inherited:bool, categories:list<string>, procSetNames:list<string>, fontNames:list<string>, xobjectNames:list<string>, colorSpaceNames:list<string>, graphicsStateNames:list<string>, patternNames:list<string>, shadingNames:list<string>, propertyNames:list<string>}|null
     */
    private function summarizePdfPageResourceSource(
        string $pageDictionary,
        string $pageReference,
        ?string $inheritedResources,
        ?string $inheritedResourceSourceObject,
        array $objects,
        int $pageNumber
    ): ?array {
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        if ($resources === null) {
            return null;
        }

        $procSetNames = $this->pdfResourceProcSetNames($resources, $objects);
        $fontNames = $this->pdfResourceDictionaryNames($resources, 'Font', $objects);
        $xobjectNames = $this->pdfResourceDictionaryNames($resources, 'XObject', $objects);
        $colorSpaceNames = $this->pdfResourceDictionaryNames($resources, 'ColorSpace', $objects);
        $graphicsStateNames = $this->pdfResourceDictionaryNames($resources, 'ExtGState', $objects);
        $patternNames = $this->pdfResourceDictionaryNames($resources, 'Pattern', $objects);
        $shadingNames = $this->pdfResourceDictionaryNames($resources, 'Shading', $objects);
        $propertyNames = $this->pdfResourceDictionaryNames($resources, 'Properties', $objects);

        $categories = [];
        if ($procSetNames !== []) {
            $categories[] = 'ProcSet';
        }
        if ($fontNames !== []) {
            $categories[] = 'Font';
        }
        if ($xobjectNames !== []) {
            $categories[] = 'XObject';
        }
        if ($colorSpaceNames !== []) {
            $categories[] = 'ColorSpace';
        }
        if ($graphicsStateNames !== []) {
            $categories[] = 'ExtGState';
        }
        if ($patternNames !== []) {
            $categories[] = 'Pattern';
        }
        if ($shadingNames !== []) {
            $categories[] = 'Shading';
        }
        if ($propertyNames !== []) {
            $categories[] = 'Properties';
        }
        sort($categories);

        if ($categories === []) {
            return null;
        }

        $inherited = $ownResources === null;

        return [
            'page' => $pageNumber,
            'pageObject' => $pageReference . ' R',
            'resourceSourceObject' => $inherited ? $inheritedResourceSourceObject : $pageReference . ' R',
            'inherited' => $inherited,
            'categories' => $categories,
            'procSetNames' => $procSetNames,
            'fontNames' => $fontNames,
            'xobjectNames' => $xobjectNames,
            'colorSpaceNames' => $colorSpaceNames,
            'graphicsStateNames' => $graphicsStateNames,
            'patternNames' => $patternNames,
            'shadingNames' => $shadingNames,
            'propertyNames' => $propertyNames,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function pdfResourceProcSetNames(string $resources, array $objects): array
    {
        $value = $this->extractPdfValueForName($resources, 'ProcSet');
        if ($value === null) {
            return [];
        }

        $names = $this->pdfValueToNameList($value, $objects);
        $names = array_values(array_unique(array_filter($names, static fn (string $name): bool => $name !== '')));
        sort($names);

        return $names;
    }

    /**
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function pdfResourceDictionaryNames(string $resources, string $name, array $objects): array
    {
        $dictionary = $this->extractPdfDictionaryOrReferenceValue($resources, $name, $objects);
        if ($dictionary === null) {
            return [];
        }

        $names = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            if ($entry['key'] !== '') {
                $names[] = $entry['key'];
            }
        }
        $names = array_values(array_unique($names));
        sort($names);

        return $names;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, resourceName:string, fontObject:string|null, inherited:bool, subtype:string|null, baseFont:string|null, encoding:string|null, toUnicode:string|null, descendantFonts:list<string>, descriptor:string|null, descriptorFontName:string|null, descriptorFontFamily:string|null, descriptorFlags:int|null, descriptorItalicAngle:float|null, descriptorFontWeight:int|null, embedded:bool, embeddedFile:string|null, embeddedFileKind:string|null, embeddedFileSubtype:string|null, embeddedFileBytes:int|null, embeddedFileSha256:string|null, embeddedFileSkipped:string|null}>
     */
    private function extractPdfFonts(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $fonts = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfFontsFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                $visited,
                $fonts,
                $pageNumber,
                0
            );
        }

        if ($fonts === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageFonts = $this->summarizePdfPageFonts($body, $reference, null, $objects);
                foreach ($pageFonts as &$font) {
                    $font['page'] = $pageNumber;
                }
                unset($font);
                array_push($fonts, ...$pageFonts);
            }
        }

        $fonts = array_values($fonts);
        usort(
            $fonts,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['resourceName'],
                $a['fontObject'] ?? '',
                $a['baseFont'] ?? '',
            ] <=> [
                $b['page'],
                $b['resourceName'],
                $b['fontObject'] ?? '',
                $b['baseFont'] ?? '',
            ]
        );

        return $fonts;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, resourceName:string, fontObject:string|null, inherited:bool, subtype:string|null, baseFont:string|null, encoding:string|null, toUnicode:string|null, descendantFonts:list<string>, descriptor:string|null, descriptorFontName:string|null, descriptorFontFamily:string|null, descriptorFlags:int|null, descriptorItalicAngle:float|null, descriptorFontWeight:int|null, embedded:bool, embeddedFile:string|null, embeddedFileKind:string|null, embeddedFileSubtype:string|null, embeddedFileBytes:int|null, embeddedFileSha256:string|null, embeddedFileSkipped:string|null}> $fonts
     */
    private function collectPdfFontsFromPageTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        array &$visited,
        array &$fonts,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $pageFonts = $this->summarizePdfPageFonts($body, $reference, $ownResources === null ? $inheritedResources : null, $objects);
            foreach ($pageFonts as &$font) {
                $font['page'] = $pageNumber;
            }
            unset($font);
            array_push($fonts, ...$pageFonts);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfFontsFromPageTree(
                $objects,
                $kidReference,
                $resources,
                $visited,
                $fonts,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, resourceName:string, fontObject:string|null, inherited:bool, subtype:string|null, baseFont:string|null, encoding:string|null, toUnicode:string|null, descendantFonts:list<string>, descriptor:string|null, descriptorFontName:string|null, descriptorFontFamily:string|null, descriptorFlags:int|null, descriptorItalicAngle:float|null, descriptorFontWeight:int|null, embedded:bool, embeddedFile:string|null, embeddedFileKind:string|null, embeddedFileSubtype:string|null, embeddedFileBytes:int|null, embeddedFileSha256:string|null, embeddedFileSkipped:string|null}>
     */
    private function summarizePdfPageFonts(string $pageDictionary, string $pageReference, ?string $inheritedResources, array $objects): array
    {
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        if ($resources === null) {
            return [];
        }

        $fontDictionary = $this->extractPdfDictionaryOrReferenceValue($resources, 'Font', $objects);
        if ($fontDictionary === null) {
            return [];
        }

        $fonts = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($fontDictionary) as $entry) {
            $font = $this->summarizePdfFontResource(
                $entry['key'],
                $entry['value'],
                $objects,
                $pageReference,
                $ownResources === null
            );
            if ($font !== null) {
                $fonts[] = $font;
            }
        }

        return $fonts;
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, resourceName:string, fontObject:string|null, inherited:bool, subtype:string|null, baseFont:string|null, encoding:string|null, toUnicode:string|null, descendantFonts:list<string>, descriptor:string|null, descriptorFontName:string|null, descriptorFontFamily:string|null, descriptorFlags:int|null, descriptorItalicAngle:float|null, descriptorFontWeight:int|null, embedded:bool, embeddedFile:string|null, embeddedFileKind:string|null, embeddedFileSubtype:string|null, embeddedFileBytes:int|null, embeddedFileSha256:string|null, embeddedFileSkipped:string|null}|null
     */
    private function summarizePdfFontResource(string $resourceName, array $value, array $objects, string $pageReference, bool $inherited): ?array
    {
        $fontObject = null;
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $fontDictionary = $objects[$reference] ?? null;
            $fontObject = $reference . ' R';
        } elseif ($value['kind'] === 'dictionary') {
            $fontDictionary = $value['value'];
        } else {
            return null;
        }

        if ($fontDictionary === null) {
            return null;
        }

        $descendantFonts = [];
        $descriptorDictionary = null;
        $descriptorReference = $this->extractPdfReferenceToken($fontDictionary, 'FontDescriptor');
        if ($descriptorReference !== null) {
            $descriptorDictionary = $objects[$this->pdfReferenceKey($descriptorReference)] ?? null;
        } else {
            $descriptorDictionary = $this->extractPdfDictionaryOrReferenceValue($fontDictionary, 'FontDescriptor', $objects);
            if ($descriptorDictionary !== null) {
                $descriptorReference = 'inline';
            }
        }

        foreach ($this->extractPdfReferenceArray($fontDictionary, 'DescendantFonts') as $descendantReference) {
            $descendantFonts[] = $descendantReference . ' R';
            if ($descriptorDictionary !== null || !isset($objects[$descendantReference])) {
                continue;
            }

            $descriptorReference = $this->extractPdfReferenceToken($objects[$descendantReference], 'FontDescriptor');
            if ($descriptorReference !== null) {
                $descriptorDictionary = $objects[$this->pdfReferenceKey($descriptorReference)] ?? null;
                continue;
            }

            $descriptorDictionary = $this->extractPdfDictionaryOrReferenceValue($objects[$descendantReference], 'FontDescriptor', $objects);
            if ($descriptorDictionary !== null) {
                $descriptorReference = 'inline';
            }
        }

        sort($descendantFonts);
        $embedded = $descriptorDictionary === null
            ? $this->emptyPdfFontFileSummary()
            : $this->extractPdfFontFileSummary($descriptorDictionary, $objects);

        return [
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'resourceName' => $resourceName,
            'fontObject' => $fontObject,
            'inherited' => $inherited,
            'subtype' => $this->extractPdfNameToken($fontDictionary, 'Subtype'),
            'baseFont' => $this->extractPdfNameToken($fontDictionary, 'BaseFont'),
            'encoding' => $this->extractPdfNameToken($fontDictionary, 'Encoding'),
            'toUnicode' => $this->extractPdfReferenceToken($fontDictionary, 'ToUnicode'),
            'descendantFonts' => $descendantFonts,
            'descriptor' => $descriptorReference,
            'descriptorFontName' => $descriptorDictionary === null ? null : $this->extractPdfNameToken($descriptorDictionary, 'FontName'),
            'descriptorFontFamily' => $descriptorDictionary === null ? null : $this->extractPdfStringOrNameValue($descriptorDictionary, 'FontFamily'),
            'descriptorFlags' => $descriptorDictionary === null ? null : $this->extractPdfIntegerToken($descriptorDictionary, 'Flags'),
            'descriptorItalicAngle' => $descriptorDictionary === null ? null : $this->extractPdfNumberToken($descriptorDictionary, 'ItalicAngle'),
            'descriptorFontWeight' => $descriptorDictionary === null ? null : $this->extractPdfIntegerToken($descriptorDictionary, 'FontWeight'),
            'embedded' => $embedded['reference'] !== null,
            'embeddedFile' => $embedded['reference'],
            'embeddedFileKind' => $embedded['kind'],
            'embeddedFileSubtype' => $embedded['subtype'],
            'embeddedFileBytes' => $embedded['bytes'],
            'embeddedFileSha256' => $embedded['sha256'],
            'embeddedFileSkipped' => $embedded['skipped'],
        ];
    }

    /**
     * @return array{reference:string|null, kind:string|null, subtype:string|null, bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function emptyPdfFontFileSummary(): array
    {
        return [
            'reference' => null,
            'kind' => null,
            'subtype' => null,
            'bytes' => null,
            'sha256' => null,
            'skipped' => null,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return array{reference:string|null, kind:string|null, subtype:string|null, bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function extractPdfFontFileSummary(string $descriptorDictionary, array $objects): array
    {
        foreach (['FontFile', 'FontFile2', 'FontFile3'] as $kind) {
            $value = $this->extractPdfValueForName($descriptorDictionary, $kind);
            if ($value === null) {
                continue;
            }

            $streamObject = null;
            $reference = null;
            if ($value['kind'] === 'reference') {
                $referenceKey = $this->pdfReferenceKey($value['value']);
                $streamObject = $objects[$referenceKey] ?? null;
                $reference = $streamObject === null ? null : $referenceKey . ' R';
            } elseif ($value['kind'] === 'dictionary') {
                $streamObject = $value['value'];
                $reference = 'inline';
            }

            if ($streamObject === null) {
                continue;
            }

            $summary = [
                'reference' => $reference,
                'kind' => $kind,
                'subtype' => $this->extractPdfNameToken($streamObject, 'Subtype'),
                'bytes' => null,
                'sha256' => null,
                'skipped' => null,
            ];
            $streamBytes = $this->extractPdfStreamBytes($streamObject);
            if ($streamBytes === null) {
                return $summary;
            }

            $summary['bytes'] = strlen($streamBytes);
            if (preg_match('/\/Filter\b/s', $streamObject) === 1) {
                $summary['skipped'] = 'filtered';

                return $summary;
            }
            if (strlen($streamBytes) > self::MAX_EMBEDDED_FONT_STREAM_BYTES) {
                $summary['skipped'] = 'too-large';

                return $summary;
            }

            $summary['sha256'] = hash('sha256', $streamBytes);

            return $summary;
        }

        return $this->emptyPdfFontFileSummary();
    }

    /**
     * @param list<array{page:int, pageObject:string|null, resourceName:string, fontObject:string|null, inherited:bool, subtype:string|null, baseFont:string|null, encoding:string|null, toUnicode:string|null, descendantFonts:list<string>, descriptor:string|null, descriptorFontName:string|null, descriptorFontFamily:string|null, descriptorFlags:int|null, descriptorItalicAngle:float|null, descriptorFontWeight:int|null, embedded:bool, embeddedFile:string|null, embeddedFileKind:string|null, embeddedFileSubtype:string|null, embeddedFileBytes:int|null, embeddedFileSha256:string|null, embeddedFileSkipped:string|null}> $fonts
     * @return array<string, int>
     */
    private function summarizePdfFontSubtypes(array $fonts): array
    {
        $subtypes = [];
        foreach ($fonts as $font) {
            $subtype = $font['subtype'] ?? null;
            if (!is_string($subtype) || $subtype === '') {
                continue;
            }

            $subtypes[$subtype] = ($subtypes[$subtype] ?? 0) + 1;
        }

        ksort($subtypes);

        return $subtypes;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, resourceName:string, imageObject:string|null, inherited:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function extractPdfImages(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $images = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfImagesFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                $visited,
                $images,
                $pageNumber,
                0
            );
        }

        if ($images === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageImages = $this->summarizePdfPageImages($body, $reference, null, $objects);
                foreach ($pageImages as &$image) {
                    $image['page'] = $pageNumber;
                }
                unset($image);
                array_push($images, ...$pageImages);
            }
        }

        $images = array_values($images);
        usort(
            $images,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['resourceName'],
                $a['imageObject'] ?? '',
            ] <=> [
                $b['page'],
                $b['resourceName'],
                $b['imageObject'] ?? '',
            ]
        );

        return $images;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, resourceName:string, imageObject:string|null, inherited:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $images
     */
    private function collectPdfImagesFromPageTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        array &$visited,
        array &$images,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $pageImages = $this->summarizePdfPageImages($body, $reference, $ownResources === null ? $inheritedResources : null, $objects);
            foreach ($pageImages as &$image) {
                $image['page'] = $pageNumber;
            }
            unset($image);
            array_push($images, ...$pageImages);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfImagesFromPageTree(
                $objects,
                $kidReference,
                $resources,
                $visited,
                $images,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, resourceName:string, imageObject:string|null, inherited:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function summarizePdfPageImages(string $pageDictionary, string $pageReference, ?string $inheritedResources, array $objects): array
    {
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        if ($resources === null) {
            return [];
        }

        $xobjectDictionary = $this->extractPdfDictionaryOrReferenceValue($resources, 'XObject', $objects);
        if ($xobjectDictionary === null) {
            return [];
        }

        $images = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($xobjectDictionary) as $entry) {
            $image = $this->summarizePdfImageXObject(
                $entry['key'],
                $entry['value'],
                $objects,
                $pageReference,
                $ownResources === null
            );
            if ($image !== null) {
                $images[] = $image;
            }
        }

        return $images;
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, resourceName:string, imageObject:string|null, inherited:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}|null
     */
    private function summarizePdfImageXObject(string $resourceName, array $value, array $objects, string $pageReference, bool $inherited): ?array
    {
        $imageObject = null;
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $imageDictionary = $objects[$reference] ?? null;
            $imageObject = $reference . ' R';
        } elseif ($value['kind'] === 'dictionary') {
            $imageDictionary = $value['value'];
        } else {
            return null;
        }

        if ($imageDictionary === null || $this->extractPdfNameToken($imageDictionary, 'Subtype') !== 'Image') {
            return null;
        }

        $stream = $this->summarizePdfImageStream($imageDictionary);

        return [
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'resourceName' => $resourceName,
            'imageObject' => $imageObject,
            'inherited' => $inherited,
            'width' => $this->extractPdfIntegerToken($imageDictionary, 'Width'),
            'height' => $this->extractPdfIntegerToken($imageDictionary, 'Height'),
            'bitsPerComponent' => $this->extractPdfIntegerToken($imageDictionary, 'BitsPerComponent'),
            'colorSpace' => $this->extractPdfColorSpaceValue($imageDictionary, $objects),
            'filters' => $this->extractPdfFilterNames($imageDictionary, $objects),
            'interpolate' => $this->extractPdfBooleanToken($imageDictionary, 'Interpolate'),
            'imageMask' => $this->extractPdfBooleanToken($imageDictionary, 'ImageMask'),
            'softMask' => $this->extractPdfReferenceToken($imageDictionary, 'SMask') ?? $this->extractPdfNameToken($imageDictionary, 'SMask'),
            'streamBytes' => $stream['bytes'],
            'streamSha256' => $stream['sha256'],
            'streamSkipped' => $stream['skipped'],
        ];
    }

    /**
     * @return array{bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function summarizePdfImageStream(string $imageDictionary): array
    {
        $summary = [
            'bytes' => null,
            'sha256' => null,
            'skipped' => null,
        ];
        $bytes = $this->extractPdfStreamBytes($imageDictionary);
        if ($bytes === null) {
            return $summary;
        }

        $summary['bytes'] = strlen($bytes);
        if (strlen($bytes) > self::MAX_IMAGE_STREAM_BYTES) {
            $summary['skipped'] = 'too-large';

            return $summary;
        }

        $summary['sha256'] = hash('sha256', $bytes);

        return $summary;
    }

    /**
     * @param array<string, string> $objects
     */
    private function extractPdfColorSpaceValue(string $dictionary, array $objects): ?string
    {
        return $this->extractPdfColorSpaceNameValue($dictionary, 'ColorSpace', $objects);
    }

    /**
     * @param array<string, string> $objects
     */
    private function extractPdfColorSpaceNameValue(string $dictionary, string $name, array $objects): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return null;
        }

        return $this->summarizePdfColorSpaceValue($value, $objects, 0);
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     */
    private function summarizePdfColorSpaceValue(array $value, array $objects, int $depth): ?string
    {
        if ($value['kind'] === 'name' || $value['kind'] === 'literal' || $value['kind'] === 'hex') {
            $colorSpace = trim($value['value']);

            return $colorSpace === '' ? null : $colorSpace;
        }

        if ($value['kind'] === 'array') {
            if (preg_match('/\[\s*\/([A-Za-z0-9_.#+-]+)/s', $value['value'], $matches) === 1) {
                return $this->decodePdfNameToken($matches[1]);
            }

            return null;
        }

        if ($value['kind'] === 'reference') {
            if ($depth >= 2) {
                return $value['value'];
            }
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return $value['value'];
            }
            $resolved = $this->parsePdfValueAt($body, 0);

            return $resolved === null ? $value['value'] : $this->summarizePdfColorSpaceValue($resolved, $objects, $depth + 1);
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function extractPdfFilterNames(string $dictionary, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'Filter');
        if ($value === null) {
            return [];
        }

        $filters = $this->summarizePdfFilterValue($value, $objects, 0);
        $filters = array_values(array_unique(array_filter($filters, static fn (string $filter): bool => $filter !== '')));
        sort($filters);

        return $filters;
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function summarizePdfFilterValue(array $value, array $objects, int $depth): array
    {
        if ($value['kind'] === 'name' || $value['kind'] === 'literal' || $value['kind'] === 'hex') {
            $filter = trim($value['value']);

            return $filter === '' ? [] : [$this->canonicalPdfFilterName($filter)];
        }

        if ($value['kind'] === 'array') {
            $filters = [];
            if (preg_match_all('/\/([A-Za-z0-9_.#+-]+)/s', $value['value'], $matches) >= 1) {
                foreach ($matches[1] as $filter) {
                    $filters[] = $this->canonicalPdfFilterName($this->decodePdfNameToken($filter));
                }
            }

            return $filters;
        }

        if ($value['kind'] === 'reference') {
            if ($depth >= 2) {
                return [$value['value']];
            }
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return [$value['value']];
            }
            $resolved = $this->parsePdfValueAt($body, 0);

            return $resolved === null ? [$value['value']] : $this->summarizePdfFilterValue($resolved, $objects, $depth + 1);
        }

        return [];
    }

    private function canonicalPdfFilterName(string $filter): string
    {
        return match ($filter) {
            'AHx' => 'ASCIIHexDecode',
            'A85' => 'ASCII85Decode',
            'LZW' => 'LZWDecode',
            'Fl' => 'FlateDecode',
            'RL' => 'RunLengthDecode',
            'CCF' => 'CCITTFaxDecode',
            'DCT' => 'DCTDecode',
            default => $filter,
        };
    }

    /**
     * @param list<array{page:int, pageObject:string|null, resourceName:string, imageObject:string|null, inherited:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $images
     * @return array<string, int>
     */
    private function summarizePdfImageColorSpaces(array $images): array
    {
        $colorSpaces = [];
        foreach ($images as $image) {
            $colorSpace = $image['colorSpace'] ?? null;
            if (!is_string($colorSpace) || $colorSpace === '') {
                continue;
            }

            $colorSpaces[$colorSpace] = ($colorSpaces[$colorSpace] ?? 0) + 1;
        }

        ksort($colorSpaces);

        return $colorSpaces;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, resourceName:string, imageObject:string|null, inherited:bool, width:int|null, height:int|null, bitsPerComponent:int|null, colorSpace:string|null, filters:list<string>, interpolate:bool|null, imageMask:bool|null, softMask:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $images
     * @return array<string, int>
     */
    private function summarizePdfImageFilters(array $images): array
    {
        $filters = [];
        foreach ($images as $image) {
            foreach ($image['filters'] as $filter) {
                if (!is_string($filter) || $filter === '') {
                    continue;
                }

                $filters[$filter] = ($filters[$filter] ?? 0) + 1;
            }
        }

        ksort($filters);

        return $filters;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, resourceName:string, colorSpaceObject:string|null, inherited:bool, family:string|null, colorantNames:list<string>, alternateColorSpace:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null, tintTransform:string|null}>
     */
    private function extractPdfColorSpaces(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $colorSpaces = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfColorSpacesFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                $visited,
                $colorSpaces,
                $pageNumber,
                0
            );
        }

        if ($colorSpaces === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageColorSpaces = $this->summarizePdfPageColorSpaces($body, $reference, null, $objects);
                foreach ($pageColorSpaces as &$colorSpace) {
                    $colorSpace['page'] = $pageNumber;
                }
                unset($colorSpace);
                array_push($colorSpaces, ...$pageColorSpaces);
            }
        }

        $colorSpaces = array_values($colorSpaces);
        usort(
            $colorSpaces,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['resourceName'],
                $a['colorSpaceObject'] ?? '',
                $a['family'] ?? '',
            ] <=> [
                $b['page'],
                $b['resourceName'],
                $b['colorSpaceObject'] ?? '',
                $b['family'] ?? '',
            ]
        );

        return $colorSpaces;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, resourceName:string, colorSpaceObject:string|null, inherited:bool, family:string|null, colorantNames:list<string>, alternateColorSpace:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null, tintTransform:string|null}> $colorSpaces
     */
    private function collectPdfColorSpacesFromPageTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        array &$visited,
        array &$colorSpaces,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $pageColorSpaces = $this->summarizePdfPageColorSpaces($body, $reference, $ownResources === null ? $inheritedResources : null, $objects);
            foreach ($pageColorSpaces as &$colorSpace) {
                $colorSpace['page'] = $pageNumber;
            }
            unset($colorSpace);
            array_push($colorSpaces, ...$pageColorSpaces);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfColorSpacesFromPageTree(
                $objects,
                $kidReference,
                $resources,
                $visited,
                $colorSpaces,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, resourceName:string, colorSpaceObject:string|null, inherited:bool, family:string|null, colorantNames:list<string>, alternateColorSpace:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null, tintTransform:string|null}>
     */
    private function summarizePdfPageColorSpaces(string $pageDictionary, string $pageReference, ?string $inheritedResources, array $objects): array
    {
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        if ($resources === null) {
            return [];
        }

        $colorSpaceDictionary = $this->extractPdfDictionaryOrReferenceValue($resources, 'ColorSpace', $objects);
        if ($colorSpaceDictionary === null) {
            return [];
        }

        $colorSpaces = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($colorSpaceDictionary) as $entry) {
            $colorSpace = $this->summarizePdfColorSpaceResource(
                $entry['key'],
                $entry['value'],
                $objects,
                $pageReference,
                $ownResources === null,
                null,
                0
            );
            if ($colorSpace !== null) {
                $colorSpaces[] = $colorSpace;
            }
        }

        return $colorSpaces;
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, resourceName:string, colorSpaceObject:string|null, inherited:bool, family:string|null, colorantNames:list<string>, alternateColorSpace:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null, tintTransform:string|null}|null
     */
    private function summarizePdfColorSpaceResource(
        string $resourceName,
        array $value,
        array $objects,
        string $pageReference,
        bool $inherited,
        ?string $colorSpaceObject,
        int $depth
    ): ?array {
        if ($depth > 8) {
            return null;
        }

        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $body = trim($objects[$reference] ?? '');
            if ($body === '') {
                return null;
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved === null) {
                return null;
            }

            return $this->summarizePdfColorSpaceResource(
                $resourceName,
                $resolved,
                $objects,
                $pageReference,
                $inherited,
                $reference . ' R',
                $depth + 1
            );
        }

        $summary = $this->emptyPdfColorSpaceSummary($resourceName, $pageReference, $inherited, $colorSpaceObject);
        if (in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
            $family = trim($value['value']);
            if ($family === '') {
                return null;
            }

            $summary['family'] = $family;

            return $summary;
        }

        if ($value['kind'] !== 'array') {
            return null;
        }

        return $this->summarizePdfColorSpaceArray($summary, $value['value'], $objects);
    }

    /**
     * @return array{page:int, pageObject:string|null, resourceName:string, colorSpaceObject:string|null, inherited:bool, family:string|null, colorantNames:list<string>, alternateColorSpace:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null, tintTransform:string|null}
     */
    private function emptyPdfColorSpaceSummary(string $resourceName, string $pageReference, bool $inherited, ?string $colorSpaceObject): array
    {
        return [
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'resourceName' => $resourceName,
            'colorSpaceObject' => $colorSpaceObject,
            'inherited' => $inherited,
            'family' => null,
            'colorantNames' => [],
            'alternateColorSpace' => null,
            'profileComponents' => null,
            'profileAlternate' => null,
            'profileBytes' => null,
            'profileSha256' => null,
            'profileSkipped' => null,
            'tintTransform' => null,
        ];
    }

    /**
     * @param array{page:int, pageObject:string|null, resourceName:string, colorSpaceObject:string|null, inherited:bool, family:string|null, colorantNames:list<string>, alternateColorSpace:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null, tintTransform:string|null} $summary
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, resourceName:string, colorSpaceObject:string|null, inherited:bool, family:string|null, colorantNames:list<string>, alternateColorSpace:string|null, profileComponents:int|null, profileAlternate:string|null, profileBytes:int|null, profileSha256:string|null, profileSkipped:string|null, tintTransform:string|null}|null
     */
    private function summarizePdfColorSpaceArray(array $summary, string $array, array $objects): ?array
    {
        $values = $this->pdfTopLevelArrayValues($array);
        if ($values === [] || !in_array($values[0]['kind'], ['name', 'literal', 'hex'], true)) {
            return null;
        }

        $family = trim($values[0]['value']);
        if ($family === '') {
            return null;
        }

        $summary['family'] = $family;
        if ($family === 'ICCBased') {
            $profile = $this->pdfProfileSummaryForColorSpaceValue($values[1] ?? null, $objects);
            $summary['profileComponents'] = $profile['components'];
            $summary['profileAlternate'] = $profile['alternate'];
            $summary['profileBytes'] = $profile['bytes'];
            $summary['profileSha256'] = $profile['sha256'];
            $summary['profileSkipped'] = $profile['skipped'];
            $summary['alternateColorSpace'] = $profile['alternate'];
        } elseif ($family === 'Separation') {
            $summary['colorantNames'] = $this->pdfColorantNamesFromValue($values[1] ?? null, $objects);
            $summary['alternateColorSpace'] = isset($values[2]) ? $this->summarizePdfColorSpaceValue($values[2], $objects, 0) : null;
            $summary['tintTransform'] = $this->pdfColorSpaceTintTransformName($values[3] ?? null);
        } elseif ($family === 'DeviceN') {
            $summary['colorantNames'] = $this->pdfColorantNamesFromValue($values[1] ?? null, $objects);
            $summary['alternateColorSpace'] = isset($values[2]) ? $this->summarizePdfColorSpaceValue($values[2], $objects, 0) : null;
            $summary['tintTransform'] = $this->pdfColorSpaceTintTransformName($values[3] ?? null);
        } elseif (isset($values[1])) {
            $summary['alternateColorSpace'] = $this->summarizePdfColorSpaceValue($values[1], $objects, 0);
        }

        return $summary;
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function pdfColorantNamesFromValue(?array $value, array $objects): array
    {
        if ($value === null) {
            return [];
        }

        $names = $this->collectPdfNamesFromValue($value, $objects);
        $names = array_values(array_filter($names, static fn (string $name): bool => $name !== ''));
        sort($names);

        return $names;
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     * @param array<string, string> $objects
     * @return array{components:int|null, alternate:string|null, bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function pdfProfileSummaryForColorSpaceValue(?array $value, array $objects): array
    {
        if ($value === null) {
            return $this->summarizePdfOutputProfile(null);
        }

        if ($value['kind'] === 'reference') {
            return $this->summarizePdfOutputProfile($objects[$this->pdfReferenceKey($value['value'])] ?? null);
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfOutputProfile($value['value']);
        }

        return $this->summarizePdfOutputProfile(null);
    }

    /**
     * @param array{kind:string, value:string, next?:int}|null $value
     */
    private function pdfColorSpaceTintTransformName(?array $value): ?string
    {
        if ($value === null) {
            return null;
        }

        if ($value['kind'] === 'reference') {
            return $value['value'];
        }
        if ($value['kind'] === 'dictionary') {
            return 'inline';
        }
        if (in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
            $name = trim($value['value']);

            return $name === '' ? null : $name;
        }

        return null;
    }

    /**
     * @param list<array{family:string|null}> $colorSpaces
     * @return array<string, int>
     */
    private function summarizePdfColorSpaceFamilies(array $colorSpaces): array
    {
        $families = [];
        foreach ($colorSpaces as $colorSpace) {
            $family = $colorSpace['family'] ?? null;
            if (!is_string($family) || $family === '') {
                continue;
            }

            $families[$family] = ($families[$family] ?? 0) + 1;
        }

        ksort($families);

        return $families;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, resourceName:string, formObject:string|null, inherited:bool, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function extractPdfFormXObjects(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $forms = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfFormXObjectsFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                $visited,
                $forms,
                $pageNumber,
                0
            );
        }

        if ($forms === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageForms = $this->summarizePdfPageFormXObjects($body, $reference, null, $objects);
                foreach ($pageForms as &$form) {
                    $form['page'] = $pageNumber;
                }
                unset($form);
                array_push($forms, ...$pageForms);
            }
        }

        $forms = array_values($forms);
        usort(
            $forms,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['resourceName'],
                $a['formObject'] ?? '',
            ] <=> [
                $b['page'],
                $b['resourceName'],
                $b['formObject'] ?? '',
            ]
        );

        return $forms;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, resourceName:string, formObject:string|null, inherited:bool, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $forms
     */
    private function collectPdfFormXObjectsFromPageTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        array &$visited,
        array &$forms,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $pageForms = $this->summarizePdfPageFormXObjects($body, $reference, $ownResources === null ? $inheritedResources : null, $objects);
            foreach ($pageForms as &$form) {
                $form['page'] = $pageNumber;
            }
            unset($form);
            array_push($forms, ...$pageForms);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfFormXObjectsFromPageTree(
                $objects,
                $kidReference,
                $resources,
                $visited,
                $forms,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, resourceName:string, formObject:string|null, inherited:bool, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function summarizePdfPageFormXObjects(string $pageDictionary, string $pageReference, ?string $inheritedResources, array $objects): array
    {
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        if ($resources === null) {
            return [];
        }

        $xobjectDictionary = $this->extractPdfDictionaryOrReferenceValue($resources, 'XObject', $objects);
        if ($xobjectDictionary === null) {
            return [];
        }

        $forms = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($xobjectDictionary) as $entry) {
            $form = $this->summarizePdfFormXObject(
                $entry['key'],
                $entry['value'],
                $objects,
                $pageReference,
                $ownResources === null
            );
            if ($form !== null) {
                $forms[] = $form;
            }
        }

        return $forms;
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, resourceName:string, formObject:string|null, inherited:bool, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}|null
     */
    private function summarizePdfFormXObject(string $resourceName, array $value, array $objects, string $pageReference, bool $inherited): ?array
    {
        $formObject = null;
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $formDictionary = $objects[$reference] ?? null;
            $formObject = $reference . ' R';
        } elseif ($value['kind'] === 'dictionary') {
            $formDictionary = $value['value'];
        } else {
            return null;
        }

        if ($formDictionary === null || $this->extractPdfNameToken($formDictionary, 'Subtype') !== 'Form') {
            return null;
        }

        $group = $this->extractPdfDictionaryOrReferenceValue($formDictionary, 'Group', $objects);
        $stream = $this->summarizePdfFormXObjectStream($formDictionary);

        return [
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'resourceName' => $resourceName,
            'formObject' => $formObject,
            'inherited' => $inherited,
            'bbox' => $this->extractPdfNumberArrayToken($formDictionary, 'BBox', 4),
            'matrix' => $this->extractPdfNumberArrayToken($formDictionary, 'Matrix', 6),
            'resourcesPresent' => $this->extractPdfValueForName($formDictionary, 'Resources') !== null,
            'groupSubtype' => $group === null ? null : $this->extractPdfNameToken($group, 'S'),
            'groupColorSpace' => $group === null ? null : $this->extractPdfColorSpaceNameValue($group, 'CS', $objects),
            'groupIsolated' => $group === null ? null : $this->extractPdfBooleanToken($group, 'I'),
            'groupKnockout' => $group === null ? null : $this->extractPdfBooleanToken($group, 'K'),
            'filters' => $this->extractPdfFilterNames($formDictionary, $objects),
            'streamBytes' => $stream['bytes'],
            'streamSha256' => $stream['sha256'],
            'streamSkipped' => $stream['skipped'],
        ];
    }

    /**
     * @return array{bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function summarizePdfFormXObjectStream(string $formDictionary): array
    {
        $summary = [
            'bytes' => null,
            'sha256' => null,
            'skipped' => null,
        ];
        $bytes = $this->extractPdfStreamBytes($formDictionary);
        if ($bytes === null) {
            return $summary;
        }

        $summary['bytes'] = strlen($bytes);
        if (strlen($bytes) > self::MAX_FORM_XOBJECT_STREAM_BYTES) {
            $summary['skipped'] = 'too-large';

            return $summary;
        }

        $summary['sha256'] = hash('sha256', $bytes);

        return $summary;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, resourceName:string, formObject:string|null, inherited:bool, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $forms
     * @return array<string, int>
     */
    private function summarizePdfFormXObjectFilters(array $forms): array
    {
        $filters = [];
        foreach ($forms as $form) {
            foreach ($form['filters'] as $filter) {
                if (!is_string($filter) || $filter === '') {
                    continue;
                }

                $filters[$filter] = ($filters[$filter] ?? 0) + 1;
            }
        }

        ksort($filters);

        return $filters;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, resourceName:string, graphicsStateObject:string|null, inherited:bool, strokingAlpha:float|null, nonstrokingAlpha:float|null, blendModes:list<string>, overprintStroking:bool|null, overprintNonstroking:bool|null, overprintMode:int|null, alphaSource:bool|null, textKnockout:bool|null, softMask:string|null}>
     */
    private function extractPdfGraphicsStates(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $states = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfGraphicsStatesFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                null,
                $visited,
                $states,
                $pageNumber,
                0
            );
        }

        if ($states === []) {
            $pageNumber = 0;
            foreach ($objects as $reference => $body) {
                if (preg_match('/\/Type\s*\/Page\b/s', $body) !== 1) {
                    continue;
                }

                $pageNumber++;
                $pageStates = $this->summarizePdfPageGraphicsStates($body, $reference, null, $objects);
                foreach ($pageStates as &$state) {
                    $state['page'] = $pageNumber;
                }
                unset($state);
                array_push($states, ...$pageStates);
            }
        }

        $states = array_values($states);
        usort(
            $states,
            static fn (array $a, array $b): int => [
                $a['page'],
                $a['resourceName'],
                $a['graphicsStateObject'] ?? '',
            ] <=> [
                $b['page'],
                $b['resourceName'],
                $b['graphicsStateObject'] ?? '',
            ]
        );

        return $states;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, resourceName:string, graphicsStateObject:string|null, inherited:bool, strokingAlpha:float|null, nonstrokingAlpha:float|null, blendModes:list<string>, overprintStroking:bool|null, overprintNonstroking:bool|null, overprintMode:int|null, alphaSource:bool|null, textKnockout:bool|null, softMask:string|null}> $states
     */
    private function collectPdfGraphicsStatesFromPageTree(
        array $objects,
        string $reference,
        ?string $inheritedResources,
        array &$visited,
        array &$states,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($body, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $pageStates = $this->summarizePdfPageGraphicsStates($body, $reference, $ownResources === null ? $inheritedResources : null, $objects);
            foreach ($pageStates as &$state) {
                $state['page'] = $pageNumber;
            }
            unset($state);
            array_push($states, ...$pageStates);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfGraphicsStatesFromPageTree(
                $objects,
                $kidReference,
                $resources,
                $visited,
                $states,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, resourceName:string, graphicsStateObject:string|null, inherited:bool, strokingAlpha:float|null, nonstrokingAlpha:float|null, blendModes:list<string>, overprintStroking:bool|null, overprintNonstroking:bool|null, overprintMode:int|null, alphaSource:bool|null, textKnockout:bool|null, softMask:string|null}>
     */
    private function summarizePdfPageGraphicsStates(string $pageDictionary, string $pageReference, ?string $inheritedResources, array $objects): array
    {
        $ownResources = $this->extractPdfDictionaryOrReferenceValue($pageDictionary, 'Resources', $objects);
        $resources = $ownResources ?? $inheritedResources;
        if ($resources === null) {
            return [];
        }

        $stateDictionary = $this->extractPdfDictionaryOrReferenceValue($resources, 'ExtGState', $objects);
        if ($stateDictionary === null) {
            return [];
        }

        $states = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($stateDictionary) as $entry) {
            $state = $this->summarizePdfGraphicsStateResource(
                $entry['key'],
                $entry['value'],
                $objects,
                $pageReference,
                $ownResources === null
            );
            if ($state !== null) {
                $states[] = $state;
            }
        }

        return $states;
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, resourceName:string, graphicsStateObject:string|null, inherited:bool, strokingAlpha:float|null, nonstrokingAlpha:float|null, blendModes:list<string>, overprintStroking:bool|null, overprintNonstroking:bool|null, overprintMode:int|null, alphaSource:bool|null, textKnockout:bool|null, softMask:string|null}|null
     */
    private function summarizePdfGraphicsStateResource(string $resourceName, array $value, array $objects, string $pageReference, bool $inherited): ?array
    {
        $graphicsStateObject = null;
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $graphicsStateDictionary = $objects[$reference] ?? null;
            $graphicsStateObject = $reference . ' R';
        } elseif ($value['kind'] === 'dictionary') {
            $graphicsStateDictionary = $value['value'];
        } else {
            return null;
        }

        if ($graphicsStateDictionary === null) {
            return null;
        }

        return [
            'page' => 0,
            'pageObject' => $pageReference . ' R',
            'resourceName' => $resourceName,
            'graphicsStateObject' => $graphicsStateObject,
            'inherited' => $inherited,
            'strokingAlpha' => $this->extractPdfNumberToken($graphicsStateDictionary, 'CA'),
            'nonstrokingAlpha' => $this->extractPdfNumberToken($graphicsStateDictionary, 'ca'),
            'blendModes' => $this->extractPdfGraphicsStateBlendModes($graphicsStateDictionary, $objects),
            'overprintStroking' => $this->extractPdfExactBooleanValue($graphicsStateDictionary, 'OP'),
            'overprintNonstroking' => $this->extractPdfExactBooleanValue($graphicsStateDictionary, 'op'),
            'overprintMode' => $this->extractPdfIntegerToken($graphicsStateDictionary, 'OPM'),
            'alphaSource' => $this->extractPdfExactBooleanValue($graphicsStateDictionary, 'AIS'),
            'textKnockout' => $this->extractPdfExactBooleanValue($graphicsStateDictionary, 'TK'),
            'softMask' => $this->extractPdfGraphicsStateSoftMask($graphicsStateDictionary),
        ];
    }

    private function extractPdfExactBooleanValue(string $dictionary, string $name): ?bool
    {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null || $value['kind'] !== 'keyword') {
            return null;
        }
        if ($value['value'] === 'true') {
            return true;
        }
        if ($value['value'] === 'false') {
            return false;
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function extractPdfGraphicsStateBlendModes(string $dictionary, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'BM');
        if ($value === null) {
            return [];
        }

        return $this->pdfValueToNameList($value, $objects);
    }

    private function extractPdfGraphicsStateSoftMask(string $dictionary): ?string
    {
        $value = $this->extractPdfValueForName($dictionary, 'SMask');
        if ($value === null) {
            return null;
        }

        if ($value['kind'] === 'reference') {
            return $value['value'];
        }
        if (in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
            $softMask = trim($value['value']);

            return $softMask === '' ? null : $softMask;
        }
        if ($value['kind'] === 'dictionary') {
            return 'inline';
        }

        return null;
    }

    /**
     * @param list<array{page:int, pageObject:string|null, resourceName:string, graphicsStateObject:string|null, inherited:bool, strokingAlpha:float|null, nonstrokingAlpha:float|null, blendModes:list<string>, overprintStroking:bool|null, overprintNonstroking:bool|null, overprintMode:int|null, alphaSource:bool|null, textKnockout:bool|null, softMask:string|null}> $states
     * @return array<string, int>
     */
    private function summarizePdfGraphicsStateBlendModes(array $states): array
    {
        $blendModes = [];
        foreach ($states as $state) {
            foreach ($state['blendModes'] as $blendMode) {
                if (!is_string($blendMode) || $blendMode === '') {
                    continue;
                }

                $blendModes[$blendMode] = ($blendModes[$blendMode] ?? 0) + 1;
            }
        }

        ksort($blendModes);

        return $blendModes;
    }

    /**
     * @return list<array{pageIndex:int, pageNumber:int, style:string|null, styleLabel:string|null, prefix:string, start:int, firstLabel:string, source:string}>
     */
    private function extractPdfPageLabels(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/PageLabels')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $pageLabels = $this->extractPdfDictionaryOrReferenceValue($catalog, 'PageLabels', $objects);
        if ($pageLabels === null) {
            return [];
        }

        $labels = [];
        $visited = [];
        $this->collectPdfPageLabels($labels, 'catalog.PageLabels', $pageLabels, $objects, $visited, 0);

        $labels = array_values($labels);
        usort($labels, static fn (array $a, array $b): int => [$a['pageIndex'], $a['source']] <=> [$b['pageIndex'], $b['source']]);

        return $labels;
    }

    /**
     * @return array{source:string, object:string|null, reviewStatus:string, pageCount:int|null, entryCount:int, kidCount:int, limits:list<int>, issues:list<string>, nodes:list<array{source:string, object:string|null, kind:string, entryCount:int, pageIndexes:list<int>, kidCount:int, limits:list<int>, reviewStatus:string, issues:list<string>}>}|array{}
     */
    private function extractPdfPageLabelPolicy(string $pdfBytes, ?string $catalog): array
    {
        if ($catalog === null || !str_contains($catalog, '/PageLabels')) {
            return [];
        }

        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $pageLabels = $this->resolvePdfDictionaryValue($this->extractPdfValueForName($catalog, 'PageLabels'), $objects);
        if ($pageLabels['dictionary'] === null) {
            return [];
        }

        $nodes = [];
        $visited = [];
        $rootObject = null;
        if (is_string($pageLabels['object']) && $pageLabels['object'] !== 'inline') {
            $visited[$this->pdfReferenceKey($pageLabels['object'])] = true;
            $rootObject = $pageLabels['object'];
        }
        $pageCount = $this->extractPdfPageCount($pdfBytes);

        $this->collectPdfPageLabelPolicyNodes(
            $nodes,
            'catalog.PageLabels',
            $rootObject,
            'root',
            $pageLabels['dictionary'],
            $objects,
            $visited,
            $pageCount,
            0
        );

        $entryCount = 0;
        $kidCount = 0;
        $limits = [];
        $issues = [];
        foreach ($nodes as $node) {
            $entryCount += $node['entryCount'];
            $kidCount += $node['kidCount'];
            foreach ($node['limits'] as $limit) {
                $limits[] = $limit;
            }
            foreach ($node['issues'] as $issue) {
                $issues[] = $issue;
            }
        }

        $issues = $this->uniqueStrings($issues);
        sort($issues);

        return [
            'source' => 'catalog.PageLabels',
            'object' => $rootObject,
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'pageCount' => $pageCount,
            'entryCount' => $entryCount,
            'kidCount' => $kidCount,
            'limits' => $this->uniqueIntegers($limits),
            'issues' => $issues,
            'nodes' => $nodes,
        ];
    }

    /**
     * @param list<array{source:string, object:string|null, kind:string, entryCount:int, pageIndexes:list<int>, kidCount:int, limits:list<int>, reviewStatus:string, issues:list<string>}> $nodes
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfPageLabelPolicyNodes(
        array &$nodes,
        string $source,
        ?string $object,
        string $kind,
        string $dictionary,
        array $objects,
        array &$visited,
        ?int $pageCount,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $pageIndexes = $this->extractPdfPageLabelIndexKeys($dictionary);
        $limits = $this->extractPdfPageLabelLimitValues($dictionary);
        $limitValues = $limits ?? [];
        $kids = $this->extractPdfReferenceArray($dictionary, 'Kids');
        $issues = $this->pdfPageLabelNodeIssues($pageIndexes, $limits, $pageCount);
        $parentLimitsValid = count($limitValues) === 2
            && $limitValues[0] <= $limitValues[1];

        $previousKidUpper = null;
        foreach ($kids as $kidReference) {
            $kidDictionary = $objects[$kidReference] ?? null;
            if ($kidDictionary === null) {
                $issues[] = 'kid-reference-missing';
                continue;
            }

            $kidLimits = $this->extractPdfPageLabelLimitValues($kidDictionary);
            if ($kidLimits === null || count($kidLimits) !== 2) {
                $issues[] = 'kid-limits-missing';
            } elseif ($kidLimits[0] > $kidLimits[1]) {
                $issues[] = 'kid-limits-out-of-order';
            } else {
                if (
                    $parentLimitsValid
                    && ($kidLimits[0] < $limitValues[0] || $kidLimits[1] > $limitValues[1])
                ) {
                    $issues[] = 'kid-limits-outside-parent';
                }
                if ($previousKidUpper !== null && $previousKidUpper >= $kidLimits[0]) {
                    $issues[] = 'kid-limits-overlap-or-unsorted';
                }
                $previousKidUpper = $kidLimits[1];
            }
        }

        $issues = $this->uniqueStrings($issues);
        sort($issues);

        $nodes[] = [
            'source' => $source,
            'object' => $object,
            'kind' => $kind,
            'entryCount' => count($pageIndexes),
            'pageIndexes' => array_slice($pageIndexes, 0, 128),
            'kidCount' => count($kids),
            'limits' => $limitValues,
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'issues' => $issues,
        ];

        foreach ($kids as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $this->collectPdfPageLabelPolicyNodes(
                $nodes,
                $source . '.Kids.' . $this->formatPdfIndirectReference($kidReference),
                $this->formatPdfIndirectReference($kidReference),
                'kid',
                $objects[$kidReference],
                $objects,
                $visited,
                $pageCount,
                $depth + 1
            );
        }
    }

    /**
     * @return list<int>
     */
    private function extractPdfPageLabelIndexKeys(string $dictionary): array
    {
        $array = $this->extractPdfArrayValue($dictionary, 'Nums');
        if ($array === null) {
            return [];
        }

        $indexes = [];
        $values = $this->pdfTopLevelArrayValues($array);
        for ($index = 0; $index + 1 < count($values); $index += 2) {
            $pageIndex = $values[$index];
            if ($pageIndex['kind'] !== 'number') {
                continue;
            }
            $indexes[] = (int) $pageIndex['value'];
        }

        return $indexes;
    }

    /**
     * @return list<int>|null
     */
    private function extractPdfPageLabelLimitValues(string $dictionary): ?array
    {
        $array = $this->extractPdfArrayValue($dictionary, 'Limits');
        if ($array === null) {
            return null;
        }

        $limits = [];
        foreach ($this->pdfTopLevelArrayValues($array) as $value) {
            if ($value['kind'] === 'number') {
                $limits[] = (int) $value['value'];
            }
        }

        return $limits;
    }

    /**
     * @param list<int>|null $limits
     * @return list<string>
     */
    private function pdfPageLabelNodeIssues(array $pageIndexes, ?array $limits, ?int $pageCount): array
    {
        $issues = [];
        if ($limits !== null) {
            if (count($limits) !== 2) {
                $issues[] = 'invalid-limits';
            } elseif ($limits[0] > $limits[1]) {
                $issues[] = 'limits-out-of-order';
            }
        }

        $previous = null;
        foreach ($pageIndexes as $pageIndex) {
            if ($pageIndex < 0) {
                $issues[] = 'negative-page-index';
            }
            if ($pageCount !== null && $pageIndex >= $pageCount) {
                $issues[] = 'page-index-out-of-range';
            }
            if ($previous !== null && $previous >= $pageIndex) {
                $issues[] = 'nums-out-of-order';
            }
            $previous = $pageIndex;
        }

        if ($limits !== null && count($limits) === 2 && $limits[0] <= $limits[1] && $pageIndexes !== []) {
            $sortedIndexes = $pageIndexes;
            sort($sortedIndexes, SORT_NUMERIC);
            $firstIndex = $sortedIndexes[0];
            $lastIndex = $sortedIndexes[count($sortedIndexes) - 1];
            if ($firstIndex < $limits[0] || $lastIndex > $limits[1]) {
                $issues[] = 'nums-outside-limits';
            }
        }

        $issues = $this->uniqueStrings($issues);
        sort($issues);

        return $issues;
    }

    /**
     * @param array<string, array{pageIndex:int, pageNumber:int, style:string|null, styleLabel:string|null, prefix:string, start:int, firstLabel:string, source:string}> $labels
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfPageLabels(
        array &$labels,
        string $source,
        string $dictionary,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $array = $this->extractPdfArrayValue($dictionary, 'Nums');
        if ($array !== null) {
            $cursor = str_starts_with($array, '[') ? 1 : 0;
            $length = strlen($array);
            if (str_ends_with($array, ']')) {
                $length--;
            }

            while ($cursor < $length) {
                $pageIndex = $this->parsePdfValueAt($array, $cursor);
                if ($pageIndex === null) {
                    $cursor++;
                    continue;
                }
                $cursor = $pageIndex['next'];

                $labelValue = $this->parsePdfValueAt($array, $cursor);
                if ($labelValue === null) {
                    break;
                }
                $cursor = $labelValue['next'];

                if ($pageIndex['kind'] !== 'number') {
                    continue;
                }

                $index = (int) $pageIndex['value'];
                if ($index < 0) {
                    continue;
                }

                $labelDictionary = $this->pdfPageLabelDictionaryForValue($labelValue, $objects);
                if ($labelDictionary === null) {
                    continue;
                }

                $label = $this->summarizePdfPageLabel($index, $labelDictionary, $source);
                $labels[$label['pageIndex'] . "\0" . $label['source']] = $label;
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $this->collectPdfPageLabels(
                $labels,
                $source . '.Kids.' . $kidReference . ' R',
                $objects[$kidReference],
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     */
    private function pdfPageLabelDictionaryForValue(array $value, array $objects): ?string
    {
        if ($value['kind'] === 'dictionary') {
            return $value['value'];
        }

        if ($value['kind'] !== 'reference') {
            return null;
        }

        $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        if ($body === null) {
            return null;
        }

        $body = trim($body);
        if (str_starts_with($body, '<<')) {
            return $body;
        }

        $parsed = $this->parsePdfValueAt($body, 0);

        return $parsed !== null && $parsed['kind'] === 'dictionary' ? $parsed['value'] : null;
    }

    /**
     * @return array{pageIndex:int, pageNumber:int, style:string|null, styleLabel:string|null, prefix:string, start:int, firstLabel:string, source:string}
     */
    private function summarizePdfPageLabel(int $pageIndex, string $dictionary, string $source): array
    {
        $style = $this->extractPdfNameToken($dictionary, 'S');
        $prefixValues = $this->extractPdfNamedStrings($dictionary, 'P');
        $prefix = $prefixValues === [] ? ($this->extractPdfNameToken($dictionary, 'P') ?? '') : $prefixValues[0];
        $start = $this->extractPdfIntegerToken($dictionary, 'St') ?? 1;
        if ($start < 1) {
            $start = 1;
        }

        return [
            'pageIndex' => $pageIndex,
            'pageNumber' => $pageIndex + 1,
            'style' => $style,
            'styleLabel' => $this->pdfPageLabelStyleName($style),
            'prefix' => $prefix,
            'start' => $start,
            'firstLabel' => $prefix . $this->formatPdfPageLabelNumber($start, $style),
            'source' => $source,
        ];
    }

    private function pdfPageLabelStyleName(?string $style): ?string
    {
        return match ($style) {
            'D' => 'decimal',
            'R' => 'upper-roman',
            'r' => 'lower-roman',
            'A' => 'upper-alpha',
            'a' => 'lower-alpha',
            null => null,
            default => 'unknown',
        };
    }

    private function formatPdfPageLabelNumber(int $number, ?string $style): string
    {
        if ($style === null) {
            return '';
        }

        return match ($style) {
            'D' => (string) $number,
            'R' => $this->formatPdfRomanPageLabel($number),
            'r' => strtolower($this->formatPdfRomanPageLabel($number)),
            'A' => $this->formatPdfAlphabeticPageLabel($number),
            'a' => strtolower($this->formatPdfAlphabeticPageLabel($number)),
            default => (string) $number,
        };
    }

    private function formatPdfRomanPageLabel(int $number): string
    {
        if ($number < 1) {
            return '';
        }

        $roman = '';
        foreach ([1000 => 'M', 900 => 'CM', 500 => 'D', 400 => 'CD', 100 => 'C', 90 => 'XC', 50 => 'L', 40 => 'XL', 10 => 'X', 9 => 'IX', 5 => 'V', 4 => 'IV', 1 => 'I'] as $value => $token) {
            while ($number >= $value) {
                $roman .= $token;
                $number -= $value;
            }
        }

        return $roman;
    }

    private function formatPdfAlphabeticPageLabel(int $number): string
    {
        if ($number < 1) {
            return '';
        }

        $label = '';
        while ($number > 0) {
            $number--;
            $label = chr(65 + ($number % 26)) . $label;
            $number = intdiv($number, 26);
        }

        return $label;
    }

    private function pdfReferenceKey(string $reference): string
    {
        if (preg_match('/\A(\d+)\s+(\d+)\s+R\z/', trim($reference), $matches) !== 1) {
            return $reference;
        }

        return $matches[1] . ' ' . $matches[2];
    }

    /**
     * @return list<string>
     */
    private function extractPdfOutlineTitles(string $pdfBytes): array
    {
        $titles = [];
        foreach ($this->pdfObjectBodies($pdfBytes) as $body) {
            if (!str_contains($body, '/Title')) {
                continue;
            }
            if (preg_match('/\/(?:Parent|Dest|A|Next|Prev)\b/s', $body) !== 1) {
                continue;
            }

            foreach ($this->extractPdfTitleStrings($body) as $title) {
                $titles[] = $title;
            }
        }

        return $titles;
    }

    /**
     * @return list<array{object:string, title:string, parent:string|null, prev:string|null, next:string|null, first:string|null, last:string|null, count:int|null, open:bool|null, destPageObject:string|null, destFit:string|null, actionType:string|null, actionTarget:string|null}>
     */
    private function extractPdfOutlines(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $outlines = [];
        $visited = [];
        $outlinesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Outlines');
        if ($outlinesReference !== null) {
            $root = $objects[$this->pdfReferenceKey($outlinesReference)] ?? null;
            if ($root !== null) {
                $first = $this->extractPdfReferenceToken($root, 'First');
                if ($first !== null) {
                    $this->collectPdfOutlinesFromSiblingChain(
                        $objects,
                        $this->pdfReferenceKey($first),
                        $outlines,
                        $visited,
                        0
                    );
                }
            }
        }

        if ($outlines === []) {
            foreach ($objects as $reference => $body) {
                if (!str_contains($body, '/Title')) {
                    continue;
                }
                if (preg_match('/\/(?:Parent|Dest|A|Next|Prev|First|Last)\b/s', $body) !== 1) {
                    continue;
                }

                $summary = $this->summarizePdfOutlineItem($reference, $body, $objects);
                if ($summary !== null) {
                    $outlines[] = $summary;
                }
            }
            usort($outlines, fn (array $a, array $b): int => $this->pdfReferenceSortKey($a['object']) <=> $this->pdfReferenceSortKey($b['object']));
        }

        return $outlines;
    }

    /**
     * @return list<array{object:string, title:string, color:list<float>|null, flags:int, flagNames:list<string>}>
     */
    private function extractPdfOutlineDisplayMetadata(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $metadata = [];
        $visited = [];
        $outlinesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Outlines');
        if ($outlinesReference !== null) {
            $root = $objects[$this->pdfReferenceKey($outlinesReference)] ?? null;
            if ($root !== null) {
                $first = $this->extractPdfReferenceToken($root, 'First');
                if ($first !== null) {
                    $this->collectPdfOutlineDisplayMetadataFromSiblingChain(
                        $objects,
                        $this->pdfReferenceKey($first),
                        $metadata,
                        $visited,
                        0
                    );
                }
            }
        }

        if ($metadata === []) {
            foreach ($objects as $reference => $body) {
                if (!str_contains($body, '/Title')) {
                    continue;
                }
                if (preg_match('/\/(?:Parent|Dest|A|Next|Prev|First|Last)\b/s', $body) !== 1) {
                    continue;
                }

                $summary = $this->summarizePdfOutlineDisplayMetadata($reference, $body);
                if ($summary !== null) {
                    $metadata[] = $summary;
                }
            }
            usort($metadata, fn (array $a, array $b): int => $this->pdfReferenceSortKey($a['object']) <=> $this->pdfReferenceSortKey($b['object']));
        }

        return $metadata;
    }

    /**
     * @param array<string, string> $objects
     * @param list<array{object:string, title:string, parent:string|null, prev:string|null, next:string|null, first:string|null, last:string|null, count:int|null, open:bool|null, destPageObject:string|null, destFit:string|null, actionType:string|null, actionTarget:string|null}> $outlines
     * @param array<string, bool> $visited
     */
    private function collectPdfOutlinesFromSiblingChain(
        array $objects,
        string $reference,
        array &$outlines,
        array &$visited,
        int $depth
    ): void {
        $cursor = $reference;
        $siblingCount = 0;
        while ($depth <= 32 && $siblingCount < 256 && isset($objects[$cursor]) && !isset($visited[$cursor])) {
            $visited[$cursor] = true;
            $summary = $this->summarizePdfOutlineItem($cursor, $objects[$cursor], $objects);
            if ($summary !== null) {
                $outlines[] = $summary;
            }

            $first = $this->extractPdfReferenceToken($objects[$cursor], 'First');
            if ($first !== null) {
                $this->collectPdfOutlinesFromSiblingChain(
                    $objects,
                    $this->pdfReferenceKey($first),
                    $outlines,
                    $visited,
                    $depth + 1
                );
            }

            $next = $this->extractPdfReferenceToken($objects[$cursor], 'Next');
            if ($next === null) {
                return;
            }
            $cursor = $this->pdfReferenceKey($next);
            $siblingCount++;
        }
    }

    /**
     * @param array<string, string> $objects
     * @param list<array{object:string, title:string, color:list<float>|null, flags:int, flagNames:list<string>}> $metadata
     * @param array<string, bool> $visited
     */
    private function collectPdfOutlineDisplayMetadataFromSiblingChain(
        array $objects,
        string $reference,
        array &$metadata,
        array &$visited,
        int $depth
    ): void {
        $cursor = $reference;
        $siblingCount = 0;
        while ($depth <= 32 && $siblingCount < 256 && isset($objects[$cursor]) && !isset($visited[$cursor])) {
            $visited[$cursor] = true;
            $summary = $this->summarizePdfOutlineDisplayMetadata($cursor, $objects[$cursor]);
            if ($summary !== null) {
                $metadata[] = $summary;
            }

            $first = $this->extractPdfReferenceToken($objects[$cursor], 'First');
            if ($first !== null) {
                $this->collectPdfOutlineDisplayMetadataFromSiblingChain(
                    $objects,
                    $this->pdfReferenceKey($first),
                    $metadata,
                    $visited,
                    $depth + 1
                );
            }

            $next = $this->extractPdfReferenceToken($objects[$cursor], 'Next');
            if ($next === null) {
                return;
            }
            $cursor = $this->pdfReferenceKey($next);
            $siblingCount++;
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string, title:string, parent:string|null, prev:string|null, next:string|null, first:string|null, last:string|null, count:int|null, open:bool|null, destPageObject:string|null, destFit:string|null, actionType:string|null, actionTarget:string|null}|null
     */
    private function summarizePdfOutlineItem(string $reference, string $dictionary, array $objects): ?array
    {
        $title = null;
        foreach ($this->extractPdfNamedStrings($dictionary, 'Title') as $value) {
            $trimmed = trim($value);
            if ($trimmed !== '') {
                $title = $trimmed;
                break;
            }
        }
        if ($title === null) {
            return null;
        }

        $count = $this->extractPdfIntegerToken($dictionary, 'Count');
        $destination = $this->extractPdfOutlineDestination($dictionary, $objects);
        $action = $this->extractPdfOutlineAction($dictionary, $objects);

        return [
            'object' => $reference . ' R',
            'title' => $title,
            'parent' => $this->extractPdfReferenceToken($dictionary, 'Parent'),
            'prev' => $this->extractPdfReferenceToken($dictionary, 'Prev'),
            'next' => $this->extractPdfReferenceToken($dictionary, 'Next'),
            'first' => $this->extractPdfReferenceToken($dictionary, 'First'),
            'last' => $this->extractPdfReferenceToken($dictionary, 'Last'),
            'count' => $count,
            'open' => $count === null ? null : $count >= 0,
            'destPageObject' => $destination['pageObject'],
            'destFit' => $destination['fit'],
            'actionType' => $action['type'],
            'actionTarget' => $action['target'],
        ];
    }

    /**
     * @return array{object:string, title:string, color:list<float>|null, flags:int, flagNames:list<string>}|null
     */
    private function summarizePdfOutlineDisplayMetadata(string $reference, string $dictionary): ?array
    {
        $title = null;
        foreach ($this->extractPdfNamedStrings($dictionary, 'Title') as $value) {
            $trimmed = trim($value);
            if ($trimmed !== '') {
                $title = $trimmed;
                break;
            }
        }
        if ($title === null) {
            return null;
        }

        $color = $this->extractPdfNumberArrayToken($dictionary, 'C', 3);
        $flags = max(0, $this->extractPdfIntegerToken($dictionary, 'F') ?? 0);
        if ($color === null && $flags === 0) {
            return null;
        }

        return [
            'object' => $reference . ' R',
            'title' => $title,
            'color' => $color,
            'flags' => $flags,
            'flagNames' => $this->pdfOutlineDisplayFlagNames($flags),
        ];
    }

    /**
     * @return list<string>
     */
    private function pdfOutlineDisplayFlagNames(int $flags): array
    {
        $names = [];
        if (($flags & 1) !== 0) {
            $names[] = 'italic';
        }
        if (($flags & 2) !== 0) {
            $names[] = 'bold';
        }

        return $names;
    }

    /**
     * @param array<string, string> $objects
     * @return array{pageObject:string|null, fit:string|null}
     */
    private function extractPdfOutlineDestination(string $dictionary, array $objects): array
    {
        $destination = ['pageObject' => null, 'fit' => null];
        $value = $this->extractPdfValueForName($dictionary, 'Dest');
        if ($value === null) {
            return $destination;
        }

        if ($value['kind'] === 'array') {
            return $this->summarizePdfOutlineDestinationArray($value['value']);
        }
        if ($value['kind'] !== 'reference') {
            return $destination;
        }

        $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        if ($body === null) {
            return $destination;
        }

        $resolved = $this->parsePdfValueAt($body, 0);
        if ($resolved !== null && $resolved['kind'] === 'array') {
            return $this->summarizePdfOutlineDestinationArray($resolved['value']);
        }

        $nested = $this->extractPdfArrayOrReferenceValue($body, 'D', $objects);
        if ($nested !== null) {
            return $this->summarizePdfOutlineDestinationArray($nested);
        }

        return $destination;
    }

    /**
     * @return array{pageObject:string|null, fit:string|null}
     */
    private function summarizePdfOutlineDestinationArray(string $array): array
    {
        $pageObject = null;
        $fit = null;
        $cursor = str_starts_with($array, '[') ? 1 : 0;
        $length = strlen($array);
        if (str_ends_with($array, ']')) {
            $length--;
        }

        while ($cursor < $length) {
            $value = $this->parsePdfValueAt($array, $cursor);
            if ($value === null) {
                $cursor++;
                continue;
            }
            if ($pageObject === null && $value['kind'] === 'reference') {
                $pageObject = $value['value'];
            } elseif ($fit === null && $value['kind'] === 'name') {
                $fit = $value['value'];
            }
            if ($pageObject !== null && $fit !== null) {
                break;
            }

            $cursor = max($cursor + 1, min($length, $value['next']));
        }

        return [
            'pageObject' => $pageObject,
            'fit' => $fit,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return array{type:string|null, target:string|null}
     */
    private function extractPdfOutlineAction(string $dictionary, array $objects): array
    {
        $action = ['type' => null, 'target' => null];
        $actionDictionary = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'A', $objects);
        if ($actionDictionary === null) {
            return $action;
        }

        $action['type'] = $this->extractPdfNameToken($actionDictionary, 'S');
        if ($action['type'] === 'URI') {
            $action['target'] = $this->extractPdfStringOrNameValue($actionDictionary, 'URI');
        } elseif ($action['type'] === 'Launch') {
            $action['target'] = $this->extractPdfStringOrNameValue($actionDictionary, 'F');
        } elseif ($action['type'] === 'Named') {
            $action['target'] = $this->extractPdfStringOrNameValue($actionDictionary, 'N');
        } elseif ($action['type'] === 'GoTo') {
            $destination = $this->extractPdfArrayOrReferenceValue($actionDictionary, 'D', $objects);
            if ($destination !== null) {
                $summary = $this->summarizePdfOutlineDestinationArray($destination);
                $action['target'] = $summary['pageObject'];
            } else {
                $action['target'] = $this->extractPdfStringOrNameValue($actionDictionary, 'D');
            }
        }

        return $action;
    }

    /**
     * @return array<string, int>
     */
    private function extractPdfAnnotationTypes(string $pdfBytes): array
    {
        $counts = [];
        foreach ($this->pdfObjectBodies($pdfBytes) as $body) {
            if (preg_match_all('/\/Subtype\s*\/([A-Za-z0-9_.-]+)/s', $body, $matches) < 1) {
                continue;
            }

            foreach ($matches[1] as $type) {
                if (!$this->isPdfAnnotationSubtype($type)) {
                    continue;
                }

                $counts[$type] = ($counts[$type] ?? 0) + 1;
            }
        }

        ksort($counts);

        return $counts;
    }

    private function isPdfAnnotationSubtype(string $type): bool
    {
        return in_array($type, [
            '3D',
            'Caret',
            'Circle',
            'FileAttachment',
            'FreeText',
            'Highlight',
            'Ink',
            'Line',
            'Link',
            'Movie',
            'Polygon',
            'PolyLine',
            'Popup',
            'PrinterMark',
            'Redact',
            'RichMedia',
            'Screen',
            'Sound',
            'Square',
            'Squiggly',
            'Stamp',
            'StrikeOut',
            'Text',
            'TrapNet',
            'Underline',
            'Watermark',
            'Widget',
        ], true);
    }

    /**
     * @return list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function extractPdfAnnotationAppearances(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $appearances = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfAnnotationAppearancesFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $appearances,
                $pageNumber,
                0
            );
        }

        if ($appearances === []) {
            foreach ($objects as $reference => $body) {
                $subtype = $this->extractPdfNameToken($body, 'Subtype');
                if ($subtype === null || !$this->isPdfAnnotationSubtype($subtype)) {
                    continue;
                }

                array_push(
                    $appearances,
                    ...$this->summarizePdfAnnotationAppearances($body, $reference . ' R', null, null, $objects)
                );
            }
        }

        usort(
            $appearances,
            fn (array $left, array $right): int => [
                $left['page'],
                $this->pdfReferenceSortKey($left['annotationObject'] ?? ''),
                $this->pdfAnnotationAppearanceSortOrder((string) ($left['appearance'] ?? '')),
                (string) ($left['stateName'] ?? ''),
                $this->pdfReferenceSortKey($left['appearanceObject'] ?? ''),
            ] <=> [
                $right['page'],
                $this->pdfReferenceSortKey($right['annotationObject'] ?? ''),
                $this->pdfAnnotationAppearanceSortOrder((string) ($right['appearance'] ?? '')),
                (string) ($right['stateName'] ?? ''),
                $this->pdfReferenceSortKey($right['appearanceObject'] ?? ''),
            ]
        );

        return $appearances;
    }

    private function pdfAnnotationAppearanceSortOrder(string $appearance): int
    {
        return match ($appearance) {
            'N' => 0,
            'R' => 1,
            'D' => 2,
            default => 9,
        };
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $appearances
     */
    private function collectPdfAnnotationAppearancesFromPageTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$appearances,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $this->collectPdfAnnotationAppearancesFromPage($body, $reference, $pageNumber, $objects, $appearances);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfAnnotationAppearancesFromPageTree(
                $objects,
                $this->pdfReferenceKey($kidReference),
                $visited,
                $appearances,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}> $appearances
     */
    private function collectPdfAnnotationAppearancesFromPage(
        string $pageDictionary,
        string $pageReference,
        int $pageNumber,
        array $objects,
        array &$appearances
    ): void {
        $array = $this->extractPdfArrayOrReferenceValue($pageDictionary, 'Annots', $objects);
        if ($array === null) {
            return;
        }

        $this->walkPdfArrayValues($array, function (array $value) use (&$appearances, $objects, $pageNumber, $pageReference): void {
            if (!in_array($value['kind'], ['reference', 'dictionary'], true)) {
                return;
            }

            array_push(
                $appearances,
                ...$this->summarizePdfAnnotationAppearancesFromValue(
                    $value,
                    $objects,
                    $pageNumber,
                    $pageReference . ' R'
                )
            );
        });
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function summarizePdfAnnotationAppearancesFromValue(array $value, array $objects, int $pageNumber, string $pageReference): array
    {
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $dictionary = $objects[$reference] ?? null;

            return $dictionary === null
                ? []
                : $this->summarizePdfAnnotationAppearances($dictionary, $reference . ' R', $pageNumber, $pageReference, $objects);
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfAnnotationAppearances($value['value'], 'inline', $pageNumber, $pageReference, $objects);
        }

        return [];
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function summarizePdfAnnotationAppearances(
        string $dictionary,
        ?string $annotationObject,
        ?int $pageNumber,
        ?string $pageReference,
        array $objects
    ): array {
        $subtype = $this->extractPdfNameToken($dictionary, 'Subtype');
        if ($subtype === null || !$this->isPdfAnnotationSubtype($subtype)) {
            return [];
        }

        $appearanceDictionary = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'AP', $objects);
        if ($appearanceDictionary === null) {
            return [];
        }

        $appearances = [];
        $base = [
            'page' => $pageNumber ?? 0,
            'pageObject' => $pageReference,
            'annotationObject' => $annotationObject,
            'subtype' => $subtype,
            'fieldName' => $this->extractPdfStringOrNameValue($dictionary, 'T'),
            'selectedState' => $this->extractPdfNameToken($dictionary, 'AS'),
            'source' => $annotationObject === null || $annotationObject === '' ? 'annotation:inline' : 'annotation:' . $annotationObject,
        ];

        foreach ($this->extractPdfTopLevelDictionaryEntries($appearanceDictionary) as $entry) {
            if (!in_array($entry['key'], ['N', 'R', 'D'], true)) {
                continue;
            }

            array_push(
                $appearances,
                ...$this->summarizePdfAnnotationAppearanceEntry(
                    $entry['key'],
                    null,
                    $entry['value'],
                    $objects,
                    $base
                )
            );
        }

        return $appearances;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @param array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, source:string} $base
     * @return list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}>
     */
    private function summarizePdfAnnotationAppearanceEntry(
        string $appearance,
        ?string $stateName,
        array $value,
        array $objects,
        array $base
    ): array {
        $appearanceObject = null;
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $dictionary = $objects[$reference] ?? null;
            $appearanceObject = $reference . ' R';
        } elseif ($value['kind'] === 'dictionary') {
            $dictionary = $value['value'];
        } else {
            return [];
        }

        if ($dictionary === null) {
            return [];
        }

        $source = $base['source'] . '.AP.' . $appearance;
        if ($stateName !== null && $stateName !== '') {
            $source .= '.' . $stateName;
        }

        if ($this->isPdfAnnotationAppearanceStreamDictionary($dictionary)) {
            return [
                $this->summarizePdfAnnotationAppearanceStream(
                    $dictionary,
                    $appearance,
                    $stateName,
                    $appearanceObject,
                    $source,
                    $objects,
                    $base
                ),
            ];
        }

        $appearances = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($dictionary) as $entry) {
            array_push(
                $appearances,
                ...$this->summarizePdfAnnotationAppearanceEntry(
                    $appearance,
                    $entry['key'],
                    $entry['value'],
                    $objects,
                    $base
                )
            );
        }

        return $appearances;
    }

    private function isPdfAnnotationAppearanceStreamDictionary(string $dictionary): bool
    {
        return $this->extractPdfStreamBytes($dictionary) !== null
            || $this->extractPdfNameToken($dictionary, 'Subtype') === 'Form'
            || $this->extractPdfValueForName($dictionary, 'BBox') !== null
            || $this->extractPdfValueForName($dictionary, 'Length') !== null;
    }

    /**
     * @param array<string, string> $objects
     * @param array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, source:string} $base
     * @return array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, fieldName:string|null, selectedState:string|null, appearance:string, stateName:string|null, appearanceObject:string|null, source:string, bbox:list<float>|null, matrix:list<float>|null, resourcesPresent:bool, groupSubtype:string|null, groupColorSpace:string|null, groupIsolated:bool|null, groupKnockout:bool|null, filters:list<string>, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}
     */
    private function summarizePdfAnnotationAppearanceStream(
        string $dictionary,
        string $appearance,
        ?string $stateName,
        ?string $appearanceObject,
        string $source,
        array $objects,
        array $base
    ): array {
        $group = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'Group', $objects);
        $stream = $this->summarizePdfAnnotationAppearanceStreamBytes($dictionary);

        return [
            'page' => $base['page'],
            'pageObject' => $base['pageObject'],
            'annotationObject' => $base['annotationObject'],
            'subtype' => $base['subtype'],
            'fieldName' => $base['fieldName'],
            'selectedState' => $base['selectedState'],
            'appearance' => $appearance,
            'stateName' => $stateName,
            'appearanceObject' => $appearanceObject,
            'source' => $source,
            'bbox' => $this->extractPdfNumberArrayToken($dictionary, 'BBox', 4),
            'matrix' => $this->extractPdfNumberArrayToken($dictionary, 'Matrix', 6),
            'resourcesPresent' => $this->extractPdfValueForName($dictionary, 'Resources') !== null,
            'groupSubtype' => $group === null ? null : $this->extractPdfNameToken($group, 'S'),
            'groupColorSpace' => $group === null ? null : $this->extractPdfColorSpaceNameValue($group, 'CS', $objects),
            'groupIsolated' => $group === null ? null : $this->extractPdfBooleanToken($group, 'I'),
            'groupKnockout' => $group === null ? null : $this->extractPdfBooleanToken($group, 'K'),
            'filters' => $this->extractPdfFilterNames($dictionary, $objects),
            'streamBytes' => $stream['bytes'],
            'streamSha256' => $stream['sha256'],
            'streamSkipped' => $stream['skipped'],
        ];
    }

    /**
     * @return array{bytes:int|null, sha256:string|null, skipped:string|null}
     */
    private function summarizePdfAnnotationAppearanceStreamBytes(string $dictionary): array
    {
        $summary = [
            'bytes' => null,
            'sha256' => null,
            'skipped' => null,
        ];
        $bytes = $this->extractPdfStreamBytes($dictionary);
        if ($bytes === null) {
            return $summary;
        }

        $summary['bytes'] = strlen($bytes);
        if (strlen($bytes) > self::MAX_ANNOTATION_APPEARANCE_STREAM_BYTES) {
            $summary['skipped'] = 'too-large';

            return $summary;
        }

        $summary['sha256'] = hash('sha256', $bytes);

        return $summary;
    }

    /**
     * @return list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, rect:list<float>|null, quadPoints:list<float>|null, contents:string|null, title:string|null, name:string|null, modified:string|null, iconName:string|null, replyTo:string|null, replyType:string|null, state:string|null, stateModel:string|null, flags:int, flagNames:list<string>, color:list<float>|null, border:list<float>|null, actionType:string|null, actionTarget:string|null, destPageObject:string|null, destFit:string|null, destTarget:string|null}>
     */
    private function extractPdfAnnotations(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $annotations = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfAnnotationsFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $annotations,
                $pageNumber,
                0
            );
        }

        if ($annotations !== []) {
            return $annotations;
        }

        foreach ($objects as $reference => $body) {
            $subtype = $this->extractPdfNameToken($body, 'Subtype');
            if ($subtype === null || !$this->isPdfAnnotationSubtype($subtype)) {
                continue;
            }

            $summary = $this->summarizePdfAnnotation($body, $reference . ' R', null, null, $objects);
            if ($summary !== null) {
                $annotations[] = $summary;
            }
        }

        usort(
            $annotations,
            fn (array $left, array $right): int => $this->pdfReferenceSortKey($left['annotationObject'] ?? '')
                <=> $this->pdfReferenceSortKey($right['annotationObject'] ?? '')
        );

        return $annotations;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, rect:list<float>|null, quadPoints:list<float>|null, contents:string|null, title:string|null, name:string|null, modified:string|null, iconName:string|null, replyTo:string|null, replyType:string|null, state:string|null, stateModel:string|null, flags:int, flagNames:list<string>, color:list<float>|null, border:list<float>|null, actionType:string|null, actionTarget:string|null, destPageObject:string|null, destFit:string|null, destTarget:string|null}> $annotations
     */
    private function collectPdfAnnotationsFromPageTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$annotations,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $this->collectPdfAnnotationsFromPage($body, $reference, $pageNumber, $objects, $annotations);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfAnnotationsFromPageTree(
                $objects,
                $this->pdfReferenceKey($kidReference),
                $visited,
                $annotations,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, rect:list<float>|null, quadPoints:list<float>|null, contents:string|null, title:string|null, name:string|null, modified:string|null, iconName:string|null, replyTo:string|null, replyType:string|null, state:string|null, stateModel:string|null, flags:int, flagNames:list<string>, color:list<float>|null, border:list<float>|null, actionType:string|null, actionTarget:string|null, destPageObject:string|null, destFit:string|null, destTarget:string|null}> $annotations
     */
    private function collectPdfAnnotationsFromPage(
        string $pageDictionary,
        string $pageReference,
        int $pageNumber,
        array $objects,
        array &$annotations
    ): void {
        $array = $this->extractPdfArrayOrReferenceValue($pageDictionary, 'Annots', $objects);
        if ($array === null) {
            return;
        }

        $this->walkPdfArrayValues($array, function (array $value) use (&$annotations, $objects, $pageNumber, $pageReference): void {
            if (!in_array($value['kind'], ['reference', 'dictionary'], true)) {
                return;
            }

            $summary = $this->summarizePdfAnnotationValue(
                $value,
                $objects,
                $pageNumber,
                $pageReference . ' R'
            );
            if ($summary !== null) {
                $annotations[] = $summary;
            }
        });
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, rect:list<float>|null, quadPoints:list<float>|null, contents:string|null, title:string|null, name:string|null, modified:string|null, iconName:string|null, replyTo:string|null, replyType:string|null, state:string|null, stateModel:string|null, flags:int, flagNames:list<string>, color:list<float>|null, border:list<float>|null, actionType:string|null, actionTarget:string|null, destPageObject:string|null, destFit:string|null, destTarget:string|null}|null
     */
    private function summarizePdfAnnotationValue(array $value, array $objects, int $pageNumber, string $pageReference): ?array
    {
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $dictionary = $objects[$reference] ?? null;

            return $dictionary === null
                ? null
                : $this->summarizePdfAnnotation($dictionary, $reference . ' R', $pageNumber, $pageReference, $objects);
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfAnnotation($value['value'], 'inline', $pageNumber, $pageReference, $objects);
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, rect:list<float>|null, quadPoints:list<float>|null, contents:string|null, title:string|null, name:string|null, modified:string|null, iconName:string|null, replyTo:string|null, replyType:string|null, state:string|null, stateModel:string|null, flags:int, flagNames:list<string>, color:list<float>|null, border:list<float>|null, actionType:string|null, actionTarget:string|null, destPageObject:string|null, destFit:string|null, destTarget:string|null}|null
     */
    private function summarizePdfAnnotation(
        string $dictionary,
        ?string $annotationObject,
        ?int $pageNumber,
        ?string $pageReference,
        array $objects
    ): ?array {
        $subtype = $this->extractPdfNameToken($dictionary, 'Subtype');
        if ($subtype === null || !$this->isPdfAnnotationSubtype($subtype)) {
            return null;
        }

        $action = $this->extractPdfAnnotationAction($dictionary, $objects);
        $destination = $this->extractPdfAnnotationDestination($dictionary, $objects);
        $flags = $this->extractPdfIntegerToken($dictionary, 'F') ?? 0;

        return [
            'page' => $pageNumber ?? 0,
            'pageObject' => $pageReference,
            'annotationObject' => $annotationObject,
            'subtype' => $subtype,
            'rect' => $this->extractPdfNumberArrayToken($dictionary, 'Rect', 4),
            'quadPoints' => $this->extractPdfNumberArrayValues($dictionary, 'QuadPoints'),
            'contents' => $this->extractPdfStringOrNameValue($dictionary, 'Contents'),
            'title' => $this->extractPdfStringOrNameValue($dictionary, 'T'),
            'name' => $this->extractPdfStringOrNameValue($dictionary, 'NM'),
            'modified' => $this->extractPdfStringOrNameValue($dictionary, 'M'),
            'iconName' => $this->extractPdfStringOrNameValue($dictionary, 'Name'),
            'replyTo' => $this->extractPdfReferenceToken($dictionary, 'IRT'),
            'replyType' => $this->extractPdfStringOrNameValue($dictionary, 'RT'),
            'state' => $this->extractPdfStringOrNameValue($dictionary, 'State'),
            'stateModel' => $this->extractPdfStringOrNameValue($dictionary, 'StateModel'),
            'flags' => $flags,
            'flagNames' => $this->pdfAnnotationFlagNames($flags),
            'color' => $this->extractPdfNumberArrayValues($dictionary, 'C'),
            'border' => $this->extractPdfNumberArrayValues($dictionary, 'Border'),
            'actionType' => is_string($action['type'] ?? null) ? $action['type'] : null,
            'actionTarget' => is_string($action['target'] ?? null) ? $action['target'] : null,
            'destPageObject' => is_string($destination['pageObject'] ?? null)
                ? $destination['pageObject']
                : (is_string($action['pageObject'] ?? null) ? $action['pageObject'] : null),
            'destFit' => is_string($destination['fit'] ?? null)
                ? $destination['fit']
                : (is_string($action['fit'] ?? null) ? $action['fit'] : null),
            'destTarget' => is_string($destination['target'] ?? null) ? $destination['target'] : null,
        ];
    }

    /**
     * @return list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, borderStyle:string|null, borderStyleLabel:string|null, borderWidth:float|null, borderDashPattern:list<float>|null, popupObject:string|null, popupRect:list<float>|null, popupOpen:bool|null, popupParent:string|null}>
     */
    private function extractPdfAnnotationReviewMetadata(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $metadata = [];
        $visited = [];
        $pageNumber = 0;
        $pagesReference = $catalog === null ? null : $this->extractPdfReferenceToken($catalog, 'Pages');

        if ($pagesReference !== null) {
            $this->collectPdfAnnotationReviewMetadataFromPageTree(
                $objects,
                $this->pdfReferenceKey($pagesReference),
                $visited,
                $metadata,
                $pageNumber,
                0
            );
        }

        if ($metadata !== []) {
            return $metadata;
        }

        foreach ($objects as $reference => $body) {
            $summary = $this->summarizePdfAnnotationReviewMetadata($body, $reference . ' R', null, null, $objects);
            if ($summary !== null) {
                $metadata[] = $summary;
            }
        }

        usort(
            $metadata,
            fn (array $left, array $right): int => $this->pdfReferenceSortKey($left['annotationObject'] ?? '')
                <=> $this->pdfReferenceSortKey($right['annotationObject'] ?? '')
        );

        return $metadata;
    }

    /**
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, borderStyle:string|null, borderStyleLabel:string|null, borderWidth:float|null, borderDashPattern:list<float>|null, popupObject:string|null, popupRect:list<float>|null, popupOpen:bool|null, popupParent:string|null}> $metadata
     */
    private function collectPdfAnnotationReviewMetadataFromPageTree(
        array $objects,
        string $reference,
        array &$visited,
        array &$metadata,
        int &$pageNumber,
        int $depth
    ): void {
        if ($depth > 32 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $type = $this->extractPdfNameToken($body, 'Type');
        if ($type === 'Page') {
            $pageNumber++;
            $this->collectPdfAnnotationReviewMetadataFromPage($body, $reference, $pageNumber, $objects, $metadata);
            return;
        }

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfAnnotationReviewMetadataFromPageTree(
                $objects,
                $this->pdfReferenceKey($kidReference),
                $visited,
                $metadata,
                $pageNumber,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, string> $objects
     * @param list<array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, borderStyle:string|null, borderStyleLabel:string|null, borderWidth:float|null, borderDashPattern:list<float>|null, popupObject:string|null, popupRect:list<float>|null, popupOpen:bool|null, popupParent:string|null}> $metadata
     */
    private function collectPdfAnnotationReviewMetadataFromPage(
        string $pageDictionary,
        string $pageReference,
        int $pageNumber,
        array $objects,
        array &$metadata
    ): void {
        $array = $this->extractPdfArrayOrReferenceValue($pageDictionary, 'Annots', $objects);
        if ($array === null) {
            return;
        }

        $this->walkPdfArrayValues($array, function (array $value) use (&$metadata, $objects, $pageNumber, $pageReference): void {
            if (!in_array($value['kind'], ['reference', 'dictionary'], true)) {
                return;
            }

            $summary = $this->summarizePdfAnnotationReviewMetadataValue(
                $value,
                $objects,
                $pageNumber,
                $pageReference . ' R'
            );
            if ($summary !== null) {
                $metadata[] = $summary;
            }
        });
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, borderStyle:string|null, borderStyleLabel:string|null, borderWidth:float|null, borderDashPattern:list<float>|null, popupObject:string|null, popupRect:list<float>|null, popupOpen:bool|null, popupParent:string|null}|null
     */
    private function summarizePdfAnnotationReviewMetadataValue(array $value, array $objects, int $pageNumber, string $pageReference): ?array
    {
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $dictionary = $objects[$reference] ?? null;

            return $dictionary === null
                ? null
                : $this->summarizePdfAnnotationReviewMetadata($dictionary, $reference . ' R', $pageNumber, $pageReference, $objects);
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfAnnotationReviewMetadata($value['value'], 'inline', $pageNumber, $pageReference, $objects);
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, borderStyle:string|null, borderStyleLabel:string|null, borderWidth:float|null, borderDashPattern:list<float>|null, popupObject:string|null, popupRect:list<float>|null, popupOpen:bool|null, popupParent:string|null}|null
     */
    private function summarizePdfAnnotationReviewMetadata(
        string $dictionary,
        ?string $annotationObject,
        ?int $pageNumber,
        ?string $pageReference,
        array $objects
    ): ?array {
        $subtype = $this->extractPdfNameToken($dictionary, 'Subtype');
        if ($subtype === null || !$this->isPdfAnnotationSubtype($subtype)) {
            return null;
        }

        $borderStyle = $this->extractPdfAnnotationBorderStyle($dictionary, $objects);
        $popup = $this->extractPdfAnnotationPopup($dictionary, $objects);
        $summary = [
            'page' => $pageNumber ?? 0,
            'pageObject' => $pageReference,
            'annotationObject' => $annotationObject,
            'subtype' => $subtype,
            'borderStyle' => $borderStyle['style'],
            'borderStyleLabel' => $borderStyle['styleLabel'],
            'borderWidth' => $borderStyle['width'],
            'borderDashPattern' => $borderStyle['dashPattern'],
            'popupObject' => $popup['object'],
            'popupRect' => $popup['rect'],
            'popupOpen' => $popup['open'],
            'popupParent' => $popup['parent'],
        ];

        return $this->pdfAnnotationReviewMetadataHasValues($summary) ? $summary : null;
    }

    /**
     * @param array{page:int, pageObject:string|null, annotationObject:string|null, subtype:string|null, borderStyle:string|null, borderStyleLabel:string|null, borderWidth:float|null, borderDashPattern:list<float>|null, popupObject:string|null, popupRect:list<float>|null, popupOpen:bool|null, popupParent:string|null} $summary
     */
    private function pdfAnnotationReviewMetadataHasValues(array $summary): bool
    {
        return $summary['borderStyle'] !== null
            || $summary['borderWidth'] !== null
            || $summary['borderDashPattern'] !== null
            || $summary['popupObject'] !== null
            || $summary['popupRect'] !== null
            || $summary['popupOpen'] !== null
            || $summary['popupParent'] !== null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{style:string|null, styleLabel:string|null, width:float|null, dashPattern:list<float>|null}
     */
    private function extractPdfAnnotationBorderStyle(string $dictionary, array $objects): array
    {
        $styleDictionary = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'BS', $objects);
        if ($styleDictionary === null) {
            return [
                'style' => null,
                'styleLabel' => null,
                'width' => null,
                'dashPattern' => null,
            ];
        }

        $style = $this->extractPdfNameToken($styleDictionary, 'S');

        return [
            'style' => $style,
            'styleLabel' => $style === null ? null : $this->pdfAnnotationBorderStyleLabel($style),
            'width' => $this->extractPdfNumberToken($styleDictionary, 'W'),
            'dashPattern' => $this->extractPdfNumberArrayValues($styleDictionary, 'D'),
        ];
    }

    private function pdfAnnotationBorderStyleLabel(string $style): ?string
    {
        return [
            'S' => 'solid',
            'D' => 'dashed',
            'B' => 'beveled',
            'I' => 'inset',
            'U' => 'underline',
        ][$style] ?? null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{object:string|null, rect:list<float>|null, open:bool|null, parent:string|null}
     */
    private function extractPdfAnnotationPopup(string $dictionary, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'Popup');
        if ($value === null) {
            return [
                'object' => null,
                'rect' => null,
                'open' => null,
                'parent' => null,
            ];
        }

        $popupObject = null;
        $popupDictionary = null;
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $popupObject = $reference . ' R';
            $popupDictionary = $objects[$reference] ?? null;
        } elseif ($value['kind'] === 'dictionary') {
            $popupObject = 'inline';
            $popupDictionary = $value['value'];
        }

        if ($popupDictionary === null) {
            return [
                'object' => $popupObject,
                'rect' => null,
                'open' => null,
                'parent' => null,
            ];
        }

        return [
            'object' => $popupObject,
            'rect' => $this->extractPdfNumberArrayToken($popupDictionary, 'Rect', 4),
            'open' => $this->extractPdfBooleanToken($popupDictionary, 'Open'),
            'parent' => $this->extractPdfReferenceToken($popupDictionary, 'Parent'),
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return array<string, mixed>
     */
    private function extractPdfAnnotationAction(string $dictionary, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'A');
        if ($value === null) {
            return [];
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfActionDictionary($value['value']) ?? [];
        }

        if ($value['kind'] !== 'reference') {
            return [];
        }

        $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;

        return $body === null ? [] : ($this->summarizePdfActionDictionary($body) ?? []);
    }

    /**
     * @param array<string, string> $objects
     * @return array<string, mixed>
     */
    private function extractPdfAnnotationDestination(string $dictionary, array $objects): array
    {
        $value = $this->extractPdfValueForName($dictionary, 'Dest');
        if ($value === null) {
            return [];
        }

        return $this->summarizePdfNamedDestinationValue($value, $objects) ?? [];
    }

    /**
     * @return list<string>
     */
    private function pdfAnnotationFlagNames(int $flags): array
    {
        if ($flags === 0) {
            return [];
        }

        $definitions = [
            0x001 => 'invisible',
            0x002 => 'hidden',
            0x004 => 'print',
            0x008 => 'noZoom',
            0x010 => 'noRotate',
            0x020 => 'noView',
            0x040 => 'readOnly',
            0x080 => 'locked',
            0x100 => 'toggleNoView',
            0x200 => 'lockedContents',
        ];

        $names = [];
        foreach ($definitions as $bit => $name) {
            if (($flags & $bit) !== 0) {
                $names[] = $name;
            }
        }

        return $names;
    }

    /**
     * @return list<string>
     */
    private function extractPdfLinkTargets(string $pdfBytes): array
    {
        $targets = [];
        foreach ($this->pdfObjectBodies($pdfBytes) as $body) {
            if (!str_contains($body, '/URI')) {
                continue;
            }
            if (preg_match('/\/(?:Subtype\s*\/Link|S\s*\/URI)\b/s', $body) !== 1) {
                continue;
            }

            foreach ($this->extractPdfNamedStrings($body, 'URI') as $target) {
                $target = trim($target);
                if ($target !== '') {
                    $targets[] = $target;
                }
            }
        }

        return array_values(array_unique($targets));
    }

    /**
     * @param list<array{name:string, embeddedFile:string|null, streamBytes:int|null, streamSkipped:string|null, source:string}> $embeddedFiles
     * @return list<array{source:string, object:string|null, filters:list<string>, streamBytes:int|null, streamSkipped:string|null}>
     */
    private function extractPdfEmbeddedFileStreamFilterPolicyEntries(array $embeddedFiles, string $pdfBytes): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $entries = [];

        foreach ($embeddedFiles as $embeddedFile) {
            $object = is_string($embeddedFile['embeddedFile'] ?? null) ? $embeddedFile['embeddedFile'] : null;
            if ($object === null || preg_match('/\A(\d+\s+\d+)\s+R\z/', $object, $matches) !== 1) {
                continue;
            }

            $dictionary = $objects[$matches[1]] ?? null;
            if ($dictionary === null) {
                continue;
            }

            $filters = $this->extractPdfFilterNames($dictionary, $objects);
            if ($filters === []) {
                continue;
            }

            $source = 'embedded-file:';
            $source .= is_string($embeddedFile['source'] ?? null) && $embeddedFile['source'] !== ''
                ? $embeddedFile['source']
                : 'unknown';
            if (is_string($embeddedFile['name'] ?? null) && $embeddedFile['name'] !== '') {
                $source .= ':' . $embeddedFile['name'];
            }

            $entries[] = [
                'source' => $source,
                'object' => $object,
                'filters' => $filters,
                'streamBytes' => is_int($embeddedFile['streamBytes'] ?? null) ? $embeddedFile['streamBytes'] : null,
                'streamSkipped' => is_string($embeddedFile['streamSkipped'] ?? null) ? $embeddedFile['streamSkipped'] : null,
            ];
        }

        return $entries;
    }

    /**
     * @return list<string>
     */
    private function extractPdfEmbeddedFileNames(string $pdfBytes): array
    {
        $names = [];
        foreach ($this->pdfObjectBodies($pdfBytes) as $body) {
            if (
                !str_contains($body, '/EmbeddedFile')
                && !str_contains($body, '/EmbeddedFiles')
                && !str_contains($body, '/Filespec')
                && !str_contains($body, '/FileAttachment')
            ) {
                continue;
            }

            foreach (['UF', 'F'] as $key) {
                foreach ($this->extractPdfNamedStrings($body, $key) as $name) {
                    $name = trim($name);
                    if ($name !== '') {
                        $names[] = $name;
                    }
                }
            }
            if (str_contains($body, '/EmbeddedFiles')) {
                $embeddedFiles = $this->extractPdfNestedDictionary($body, 'EmbeddedFiles');
                if ($embeddedFiles !== null) {
                    foreach ($this->extractPdfNamesArrayStrings($embeddedFiles) as $name) {
                        $name = trim($name);
                        if ($name !== '') {
                            $names[] = $name;
                        }
                    }
                }
            }
        }

        return array_values(array_unique($names));
    }

    /**
     * @return list<array{name:string, unicodeName:string|null, description:string|null, afRelationship:string|null, filespec:string|null, embeddedFile:string|null, subtype:string|null, size:int|null, modDate:string|null, checksum:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, collectionItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, source:string}>
     */
    private function extractPdfEmbeddedFiles(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $files = [];
        $visited = [];

        if ($catalog !== null) {
            $names = $this->extractPdfDictionaryOrReferenceValue($catalog, 'Names', $objects);
            if ($names !== null) {
                $embeddedFiles = $this->extractPdfDictionaryOrReferenceValue($names, 'EmbeddedFiles', $objects);
                if ($embeddedFiles !== null) {
                    $this->collectPdfEmbeddedFileNameTree(
                        $files,
                        'catalog.Names.EmbeddedFiles',
                        $embeddedFiles,
                        $objects,
                        $visited,
                        0
                    );
                }
            }

            foreach ($this->extractPdfReferenceArray($catalog, 'AF') as $reference) {
                if (!isset($objects[$reference])) {
                    continue;
                }
                $this->addPdfEmbeddedFileEntry(
                    $files,
                    $this->summarizePdfFileSpec($objects[$reference], $objects, 'catalog.AF', $reference . ' R', null)
                );
            }
        }

        foreach ($this->extractPdfMarkedContentProperties($pdfBytes, $catalog) as $property) {
            $pageObject = isset($property['pageObject']) && is_string($property['pageObject']) ? $property['pageObject'] : 'page';
            $propertyName = isset($property['propertyName']) && is_string($property['propertyName']) ? $property['propertyName'] : 'unnamed';
            $source = 'marked-content:' . $pageObject . '.Properties.' . $propertyName . '.AF';
            foreach ($property['associatedFiles'] as $associatedFileReference) {
                if (preg_match('/\A(\d+)\s+(\d+)\s+R\z/', $associatedFileReference, $matches) !== 1) {
                    continue;
                }

                $reference = $matches[1] . ' ' . $matches[2];
                if (!isset($objects[$reference])) {
                    continue;
                }

                $this->addPdfEmbeddedFileEntry(
                    $files,
                    $this->summarizePdfFileSpec($objects[$reference], $objects, $source, $associatedFileReference, null)
                );
            }
        }

        foreach ($objects as $reference => $body) {
            $associatedFileSource = $this->pdfAssociatedFileSource($reference, $body);
            if ($associatedFileSource !== null) {
                foreach ($this->extractPdfReferenceArray($body, 'AF') as $associatedFileReference) {
                    if (!isset($objects[$associatedFileReference])) {
                        continue;
                    }

                    $this->addPdfEmbeddedFileEntry(
                        $files,
                        $this->summarizePdfFileSpec(
                            $objects[$associatedFileReference],
                            $objects,
                            $associatedFileSource,
                            $associatedFileReference . ' R',
                            null
                        )
                    );
                }
            }

            if (preg_match('/\/Subtype\s*\/FileAttachment\b/s', $body) === 1) {
                $value = $this->extractPdfValueForName($body, 'FS');
                if ($value !== null) {
                    $this->addPdfEmbeddedFileFromValue(
                        $files,
                        'annotation:' . $reference . ' R.FS',
                        $value,
                        $objects,
                        null
                    );
                }
            }

            if (preg_match('/\/Type\s*\/Filespec\b/s', $body) === 1 || (str_contains($body, '/EF') && preg_match('/\/(?:UF|F)\b/s', $body) === 1)) {
                $this->addPdfEmbeddedFileEntry(
                    $files,
                    $this->summarizePdfFileSpec($body, $objects, 'filespec:' . $reference . ' R', $reference . ' R', null)
                );
            }
        }

        $files = array_values($files);
        usort(
            $files,
            static fn (array $a, array $b): int => [
                $a['name'],
                $a['source'],
                $a['filespec'] ?? '',
                $a['embeddedFile'] ?? '',
            ] <=> [
                $b['name'],
                $b['source'],
                $b['filespec'] ?? '',
                $b['embeddedFile'] ?? '',
            ]
        );

        return $files;
    }

    private function pdfAssociatedFileSource(string $reference, string $body): ?string
    {
        if (!str_contains($body, '/AF')) {
            return null;
        }

        $references = $this->extractPdfReferenceArray($body, 'AF');
        if ($references === []) {
            return null;
        }

        $type = $this->extractPdfNameToken($body, 'Type');
        $pdfReference = $reference . ' R';
        if ($type === 'Catalog' || $type === 'Filespec') {
            return null;
        }
        if ($type === 'Page') {
            return 'page:' . $pdfReference . '.AF';
        }
        if ($type === 'StructElem') {
            return 'structure:' . $pdfReference . '.AF';
        }
        if ($type === 'Annot') {
            return 'annotation:' . $pdfReference . '.AF';
        }
        if ($type === 'XObject') {
            return 'xobject:' . $pdfReference . '.AF';
        }

        return 'object:' . $pdfReference . '.AF';
    }

    /**
     * @param array<string, array{name:string, unicodeName:string|null, description:string|null, afRelationship:string|null, filespec:string|null, embeddedFile:string|null, subtype:string|null, size:int|null, modDate:string|null, checksum:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, collectionItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, source:string}> $files
     * @param array<string, string> $objects
     * @param array<string, bool> $visited
     */
    private function collectPdfEmbeddedFileNameTree(
        array &$files,
        string $source,
        string $dictionary,
        array $objects,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16) {
            return;
        }

        $array = $this->extractPdfArrayValue($dictionary, 'Names');
        if ($array !== null) {
            $cursor = str_starts_with($array, '[') ? 1 : 0;
            $length = strlen($array);
            if (str_ends_with($array, ']')) {
                $length--;
            }

            while ($cursor < $length) {
                $name = $this->parsePdfValueAt($array, $cursor);
                if ($name === null) {
                    $cursor++;
                    continue;
                }
                $cursor = $name['next'];

                $value = $this->parsePdfValueAt($array, $cursor);
                if ($value === null) {
                    break;
                }
                $cursor = $value['next'];

                if (!in_array($name['kind'], ['literal', 'hex', 'name'], true)) {
                    continue;
                }

                $nameHint = trim($name['value']);
                if ($nameHint === '') {
                    $nameHint = null;
                }

                $this->addPdfEmbeddedFileFromValue($files, $source, $value, $objects, $nameHint);
            }
        }

        foreach ($this->extractPdfReferenceArray($dictionary, 'Kids') as $kidReference) {
            if (isset($visited[$kidReference]) || !isset($objects[$kidReference])) {
                continue;
            }

            $visited[$kidReference] = true;
            $this->collectPdfEmbeddedFileNameTree(
                $files,
                $source . '.Kids.' . $kidReference . ' R',
                $objects[$kidReference],
                $objects,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @param array<string, array{name:string, unicodeName:string|null, description:string|null, afRelationship:string|null, filespec:string|null, embeddedFile:string|null, subtype:string|null, size:int|null, modDate:string|null, checksum:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, collectionItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, source:string}> $files
     * @param array{kind:string, value:string} $value
     * @param array<string, string> $objects
     */
    private function addPdfEmbeddedFileFromValue(array &$files, string $source, array $value, array $objects, ?string $nameHint): void
    {
        if ($value['kind'] === 'reference') {
            $reference = $this->pdfReferenceKey($value['value']);
            $body = $objects[$reference] ?? null;
            if ($body === null) {
                return;
            }

            $this->addPdfEmbeddedFileEntry(
                $files,
                $this->summarizePdfFileSpec($body, $objects, $source, $reference . ' R', $nameHint)
            );
            return;
        }

        if ($value['kind'] === 'dictionary') {
            $this->addPdfEmbeddedFileEntry(
                $files,
                $this->summarizePdfFileSpec($value['value'], $objects, $source, null, $nameHint)
            );
            return;
        }

        if (in_array($value['kind'], ['literal', 'hex', 'name'], true)) {
            $name = trim($value['value']);
            if ($name === '') {
                return;
            }

            $this->addPdfEmbeddedFileEntry($files, [
                'name' => $name,
                'unicodeName' => null,
                'description' => null,
                'afRelationship' => null,
                'filespec' => null,
                'embeddedFile' => null,
                'subtype' => null,
                'size' => null,
                'modDate' => null,
                'checksum' => null,
                'streamBytes' => null,
                'streamSha256' => null,
                'streamSkipped' => null,
                'collectionItems' => [],
                'source' => $source,
            ]);
        }
    }

    /**
     * @param array<string, string> $objects
     * @return array{name:string, unicodeName:string|null, description:string|null, afRelationship:string|null, filespec:string|null, embeddedFile:string|null, subtype:string|null, size:int|null, modDate:string|null, checksum:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, collectionItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, source:string}|null
     */
    private function summarizePdfFileSpec(string $dictionary, array $objects, string $source, ?string $filespecReference, ?string $nameHint): ?array
    {
        $unicodeName = $this->extractPdfStringOrNameValue($dictionary, 'UF');
        $fallbackName = $this->extractPdfStringOrNameValue($dictionary, 'F');
        $name = $unicodeName ?? $fallbackName ?? $nameHint;
        if ($name === null || trim($name) === '') {
            return null;
        }

        $embedded = $this->extractPdfEmbeddedFileStreamForFileSpec($dictionary, $objects);

        return [
            'name' => trim($name),
            'unicodeName' => $unicodeName,
            'description' => $this->extractPdfStringOrNameValue($dictionary, 'Desc'),
            'afRelationship' => $this->extractPdfNameToken($dictionary, 'AFRelationship'),
            'filespec' => $filespecReference,
            'embeddedFile' => $embedded['reference'],
            'subtype' => $embedded['subtype'],
            'size' => $embedded['size'],
            'modDate' => $embedded['modDate'],
            'checksum' => $embedded['checksum'],
            'streamBytes' => $embedded['streamBytes'],
            'streamSha256' => $embedded['streamSha256'],
            'streamSkipped' => $embedded['streamSkipped'],
            'collectionItems' => $this->extractPdfFileSpecCollectionItems($dictionary, $objects),
            'source' => $source,
        ];
    }

    /**
     * @param array<string, string> $objects
     * @return list<array{name:string, value:string|int|float|bool|null, valueType:string}>
     */
    private function extractPdfFileSpecCollectionItems(string $dictionary, array $objects): array
    {
        $collectionItem = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'CI', $objects);
        if ($collectionItem === null) {
            return [];
        }

        $items = [];
        foreach ($this->extractPdfTopLevelDictionaryEntries($collectionItem) as $entry) {
            if ($entry['key'] === 'Type') {
                continue;
            }

            $summary = $this->summarizePdfFileSpecCollectionItemValue($entry['value'], $objects, 0);
            if ($summary === null) {
                continue;
            }

            $items[] = [
                'name' => $entry['key'],
                'value' => $summary['value'],
                'valueType' => $summary['valueType'],
            ];
        }

        usort(
            $items,
            static fn (array $left, array $right): int => strcmp($left['name'], $right['name'])
        );

        return $items;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{value:string|int|float|bool|null, valueType:string}|null
     */
    private function summarizePdfFileSpecCollectionItemValue(array $value, array $objects, int $depth): ?array
    {
        if ($depth > 8) {
            return null;
        }

        if ($value['kind'] === 'reference') {
            $body = trim($objects[$this->pdfReferenceKey($value['value'])] ?? '');
            if ($body === '') {
                return [
                    'value' => $value['value'],
                    'valueType' => 'reference',
                ];
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved === null) {
                return [
                    'value' => $value['value'],
                    'valueType' => 'reference',
                ];
            }

            return $this->summarizePdfFileSpecCollectionItemValue($resolved, $objects, $depth + 1);
        }

        if ($value['kind'] === 'literal' || $value['kind'] === 'hex') {
            return [
                'value' => trim($value['value']),
                'valueType' => 'string',
            ];
        }

        if ($value['kind'] === 'name') {
            return [
                'value' => trim($value['value']),
                'valueType' => 'name',
            ];
        }

        if ($value['kind'] === 'number') {
            $number = $value['value'];
            $numeric = preg_match('/[.Ee]/', $number) === 1 ? (float) $number : (int) $number;

            return [
                'value' => $numeric,
                'valueType' => is_int($numeric) ? 'integer' : 'number',
            ];
        }

        if ($value['kind'] === 'keyword') {
            if ($value['value'] === 'true' || $value['value'] === 'false') {
                return [
                    'value' => $value['value'] === 'true',
                    'valueType' => 'boolean',
                ];
            }

            return [
                'value' => null,
                'valueType' => 'null',
            ];
        }

        if ($value['kind'] === 'array') {
            return [
                'value' => count($this->pdfTopLevelArrayValues($value['value'])),
                'valueType' => 'array',
            ];
        }

        if ($value['kind'] === 'dictionary') {
            return [
                'value' => count($this->extractPdfTopLevelDictionaryEntries($value['value'])),
                'valueType' => 'dictionary',
            ];
        }

        return null;
    }

    /**
     * @param array<string, string> $objects
     * @return array{reference:string|null, subtype:string|null, size:int|null, modDate:string|null, checksum:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null}
     */
    private function extractPdfEmbeddedFileStreamForFileSpec(string $dictionary, array $objects): array
    {
        $summary = [
            'reference' => null,
            'subtype' => null,
            'size' => null,
            'modDate' => null,
            'checksum' => null,
            'streamBytes' => null,
            'streamSha256' => null,
            'streamSkipped' => null,
        ];

        $ef = $this->extractPdfDictionaryOrReferenceValue($dictionary, 'EF', $objects);
        $streamObject = null;
        if ($ef !== null) {
            foreach (['UF', 'F'] as $key) {
                $value = $this->extractPdfValueForName($ef, $key);
                if ($value === null) {
                    continue;
                }
                if ($value['kind'] === 'reference') {
                    $reference = $this->pdfReferenceKey($value['value']);
                    $streamObject = $objects[$reference] ?? null;
                    if ($streamObject !== null) {
                        $summary['reference'] = $reference . ' R';
                        break;
                    }
                } elseif ($value['kind'] === 'dictionary') {
                    $streamObject = $value['value'];
                    $summary['reference'] = 'inline';
                    break;
                }
            }
        } elseif (str_contains($dictionary, 'stream') && preg_match('/\/Type\s*\/EmbeddedFile\b/s', $dictionary) === 1) {
            $streamObject = $dictionary;
            $summary['reference'] = 'inline';
        }

        if ($streamObject === null) {
            return $summary;
        }

        $summary['subtype'] = $this->extractPdfNameToken($streamObject, 'Subtype');
        $params = $this->extractPdfDictionaryOrReferenceValue($streamObject, 'Params', $objects);
        if ($params !== null) {
            $summary['size'] = $this->extractPdfIntegerToken($params, 'Size');
            $summary['modDate'] = $this->extractPdfStringOrNameValue($params, 'ModDate');
            $summary['checksum'] = $this->extractPdfByteStringHexValue($params, 'CheckSum');
        }

        $streamBytes = $this->extractPdfStreamBytes($streamObject);
        if ($streamBytes === null) {
            return $summary;
        }

        $summary['streamBytes'] = strlen($streamBytes);
        if (preg_match('/\/Filter\b/s', $streamObject) === 1) {
            $summary['streamSkipped'] = 'filtered';

            return $summary;
        }
        if (strlen($streamBytes) > self::MAX_EMBEDDED_FILE_STREAM_BYTES) {
            $summary['streamSkipped'] = 'too-large';

            return $summary;
        }

        $summary['streamSha256'] = hash('sha256', $streamBytes);

        return $summary;
    }

    /**
     * @param array<string, array{name:string, unicodeName:string|null, description:string|null, afRelationship:string|null, filespec:string|null, embeddedFile:string|null, subtype:string|null, size:int|null, modDate:string|null, checksum:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, collectionItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, source:string}> $files
     * @param array{name:string, unicodeName:string|null, description:string|null, afRelationship:string|null, filespec:string|null, embeddedFile:string|null, subtype:string|null, size:int|null, modDate:string|null, checksum:string|null, streamBytes:int|null, streamSha256:string|null, streamSkipped:string|null, collectionItems:list<array{name:string, value:string|int|float|bool|null, valueType:string}>, source:string}|null $entry
     */
    private function addPdfEmbeddedFileEntry(array &$files, ?array $entry): void
    {
        if ($entry === null) {
            return;
        }

        $key = $entry['filespec'] ?? null;
        if ($key === null || $key === '') {
            $key = implode("\0", [
                $entry['name'],
                $entry['source'],
                $entry['embeddedFile'] ?? '',
            ]);
        }

        if (!isset($files[$key])) {
            $files[$key] = $entry;
        }
    }

    /**
     * @return list<array{fieldName:string|null, fieldObject:string|null, fieldType:string|null, fieldTypeLabel:string|null, trigger:string, source:string, actionType:string, actionTarget:string|null, scriptBytes:int|null, scriptSha256:string|null}>
     */
    private function extractPdfFormFieldActions(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $candidates = $this->pdfFormFieldActionCandidates($pdfBytes, $catalog, $objects);

        $actions = [];
        foreach ($candidates as $candidate) {
            $this->addPdfFormFieldActionFromNamedValue($actions, $candidate, 'A', $candidate['dictionary'], 'A', $objects);

            $additionalActions = $this->extractPdfDictionaryOrReferenceValue($candidate['dictionary'], 'AA', $objects);
            if ($additionalActions === null) {
                continue;
            }

            foreach (['E', 'X', 'D', 'U', 'Fo', 'Bl', 'PO', 'PC', 'PV', 'PI', 'O', 'C', 'K', 'F', 'V', 'WC', 'WS', 'DS', 'WP', 'DP'] as $trigger) {
                $this->addPdfFormFieldActionFromNamedValue($actions, $candidate, 'AA.' . $trigger, $additionalActions, $trigger, $objects);
            }
        }

        $actions = array_values($actions);
        usort(
            $actions,
            static fn (array $left, array $right): int => [
                $left['fieldName'] ?? '',
                $left['fieldObject'] ?? '',
                $left['trigger'],
                $left['actionType'],
                $left['actionTarget'] ?? '',
            ] <=> [
                $right['fieldName'] ?? '',
                $right['fieldObject'] ?? '',
                $right['trigger'],
                $right['actionType'],
                $right['actionTarget'] ?? '',
            ]
        );

        return $actions;
    }

    /**
     * @param array<string, string> $objects
     * @return array<string, array{dictionary:string, fieldObject:string|null, fieldName:string|null, fieldType:string|null, fieldTypeLabel:string|null}>
     */
    private function pdfFormFieldActionCandidates(string $pdfBytes, ?string $catalog, array $objects): array
    {
        $candidates = [];
        $acroForm = $this->extractPdfAcroFormDictionary($pdfBytes, $catalog);

        if ($acroForm !== null) {
            $visited = [];
            foreach ($this->extractPdfReferenceArray($acroForm, 'Fields') as $reference) {
                $this->collectPdfFormFieldActionCandidates(
                    $objects,
                    $reference,
                    ['name' => null, 'type' => null],
                    $candidates,
                    $visited,
                    0
                );
            }
        }

        if ($candidates === []) {
            foreach ($objects as $reference => $body) {
                if ((!str_contains($body, '/A') && !str_contains($body, '/AA')) || !str_contains($body, '/FT')) {
                    continue;
                }

                $candidates[$reference] = $this->pdfFormFieldActionCandidate($body, $reference . ' R', null, null);
            }
        }

        return $candidates;
    }

    /**
     * @param array<string, string> $objects
     * @param array{name:string|null, type:string|null} $inherited
     * @param array<string, array{dictionary:string, fieldObject:string|null, fieldName:string|null, fieldType:string|null, fieldTypeLabel:string|null}> $candidates
     * @param array<string, bool> $visited
     */
    private function collectPdfFormFieldActionCandidates(
        array $objects,
        string $reference,
        array $inherited,
        array &$candidates,
        array &$visited,
        int $depth
    ): void {
        if ($depth > 16 || isset($visited[$reference]) || !isset($objects[$reference])) {
            return;
        }
        $visited[$reference] = true;

        $body = $objects[$reference];
        $candidate = $this->pdfFormFieldActionCandidate($body, $reference . ' R', $inherited['name'], $inherited['type']);
        $candidates[$reference] = $candidate;

        foreach ($this->extractPdfReferenceArray($body, 'Kids') as $kidReference) {
            $this->collectPdfFormFieldActionCandidates(
                $objects,
                $this->pdfReferenceKey($kidReference),
                [
                    'name' => $candidate['fieldName'],
                    'type' => $candidate['fieldType'],
                ],
                $candidates,
                $visited,
                $depth + 1
            );
        }
    }

    /**
     * @return array{dictionary:string, fieldObject:string|null, fieldName:string|null, fieldType:string|null, fieldTypeLabel:string|null}
     */
    private function pdfFormFieldActionCandidate(
        string $dictionary,
        ?string $fieldObject,
        ?string $inheritedName,
        ?string $inheritedType
    ): array {
        $partialName = $this->extractPdfStringOrNameValue($dictionary, 'T');
        if ($partialName !== null && $partialName !== '') {
            $fieldName = $inheritedName !== null && $inheritedName !== ''
                ? $inheritedName . '.' . $partialName
                : $partialName;
        } else {
            $fieldName = $inheritedName;
        }

        $fieldType = $this->extractPdfNameToken($dictionary, 'FT') ?? $inheritedType;

        return [
            'dictionary' => $dictionary,
            'fieldObject' => $fieldObject,
            'fieldName' => $fieldName,
            'fieldType' => $fieldType,
            'fieldTypeLabel' => $fieldType === null ? null : $this->pdfFormFieldTypeLabel($fieldType),
        ];
    }

    /**
     * @param array<string, array{fieldName:string|null, fieldObject:string|null, fieldType:string|null, fieldTypeLabel:string|null, trigger:string, source:string, actionType:string, actionTarget:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param array{dictionary:string, fieldObject:string|null, fieldName:string|null, fieldType:string|null, fieldTypeLabel:string|null} $candidate
     * @param array<string, string> $objects
     */
    private function addPdfFormFieldActionFromNamedValue(
        array &$actions,
        array $candidate,
        string $trigger,
        string $dictionary,
        string $name,
        array $objects
    ): void {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return;
        }

        $summary = $this->summarizePdfFormFieldActionValue($this->pdfFormFieldActionSource($candidate, $trigger), $value, $objects);
        if ($summary === null) {
            return;
        }

        $entry = [
            'fieldName' => $candidate['fieldName'],
            'fieldObject' => $candidate['fieldObject'],
            'fieldType' => $candidate['fieldType'],
            'fieldTypeLabel' => $candidate['fieldTypeLabel'],
            'trigger' => $trigger,
            'source' => $summary['source'],
            'actionType' => $summary['type'],
            'actionTarget' => $summary['target'],
            'scriptBytes' => $summary['scriptBytes'],
            'scriptSha256' => $summary['scriptSha256'],
        ];
        $key = implode("\0", [
            $entry['fieldObject'] ?? '',
            $entry['fieldName'] ?? '',
            $entry['trigger'],
            $entry['actionType'],
            $entry['actionTarget'] ?? '',
            (string) ($entry['scriptBytes'] ?? ''),
            $entry['scriptSha256'] ?? '',
        ]);
        $actions[$key] = $entry;
    }

    /**
     * @param array{dictionary:string, fieldObject:string|null, fieldName:string|null, fieldType:string|null, fieldTypeLabel:string|null} $candidate
     */
    private function pdfFormFieldActionSource(array $candidate, string $trigger): string
    {
        $field = is_string($candidate['fieldObject']) && $candidate['fieldObject'] !== ''
            ? $candidate['fieldObject']
            : $this->pdfActionSourceToken($candidate['fieldName'] ?? 'unknown');

        return 'field:' . $field . '.' . $trigger;
    }

    /**
     * @param array{kind:string, value:string, next?:int} $value
     * @param array<string, string> $objects
     * @return array{source:string, type:string, target:string|null, scriptBytes:int|null, scriptSha256:string|null}|null
     */
    private function summarizePdfFormFieldActionValue(string $source, array $value, array $objects, int $depth = 0): ?array
    {
        if ($depth > 8) {
            return null;
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return null;
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved !== null && in_array($resolved['kind'], ['dictionary', 'reference', 'name', 'literal', 'hex'], true)) {
                return $this->summarizePdfFormFieldActionValue($source, $resolved, $objects, $depth + 1);
            }

            return $this->summarizePdfActiveActionDictionary($body, $source, $objects);
        }

        if ($value['kind'] === 'dictionary') {
            return $this->summarizePdfActiveActionDictionary($value['value'], $source, $objects);
        }

        if (in_array($value['kind'], ['name', 'literal', 'hex'], true)) {
            $target = trim($value['value']);
            if ($target === '') {
                return null;
            }

            return [
                'source' => $source,
                'type' => 'Named',
                'target' => $target,
                'scriptBytes' => null,
                'scriptSha256' => null,
            ];
        }

        return null;
    }

    /**
     * @return list<array{fieldName:string|null, fieldObject:string|null, fieldType:string|null, fieldTypeLabel:string|null, trigger:string, source:string, actionType:string, actionTarget:string|null, flags:int|null, flagNames:list<string>, fieldNames:list<string>, fieldSelection:string}>
     */
    private function extractPdfFormFieldActionTargets(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $candidates = $this->pdfFormFieldActionCandidates($pdfBytes, $catalog, $objects);
        $targets = [];

        foreach ($candidates as $candidate) {
            $this->addPdfFormFieldActionTargetFromNamedValue($targets, $candidate, 'A', $candidate['dictionary'], 'A', $objects);

            $additionalActions = $this->extractPdfDictionaryOrReferenceValue($candidate['dictionary'], 'AA', $objects);
            if ($additionalActions === null) {
                continue;
            }

            foreach (['E', 'X', 'D', 'U', 'Fo', 'Bl', 'PO', 'PC', 'PV', 'PI', 'O', 'C', 'K', 'F', 'V', 'WC', 'WS', 'DS', 'WP', 'DP'] as $trigger) {
                $this->addPdfFormFieldActionTargetFromNamedValue($targets, $candidate, 'AA.' . $trigger, $additionalActions, $trigger, $objects);
            }
        }

        $targets = array_values($targets);
        usort(
            $targets,
            static fn (array $left, array $right): int => [
                $left['fieldName'] ?? '',
                $left['fieldObject'] ?? '',
                $left['trigger'],
                $left['actionType'],
                $left['actionTarget'] ?? '',
            ] <=> [
                $right['fieldName'] ?? '',
                $right['fieldObject'] ?? '',
                $right['trigger'],
                $right['actionType'],
                $right['actionTarget'] ?? '',
            ]
        );

        return $targets;
    }

    /**
     * @param array<string, array{fieldName:string|null, fieldObject:string|null, fieldType:string|null, fieldTypeLabel:string|null, trigger:string, source:string, actionType:string, actionTarget:string|null, flags:int|null, flagNames:list<string>, fieldNames:list<string>, fieldSelection:string}> $targets
     * @param array{dictionary:string, fieldObject:string|null, fieldName:string|null, fieldType:string|null, fieldTypeLabel:string|null} $candidate
     * @param array<string, string> $objects
     */
    private function addPdfFormFieldActionTargetFromNamedValue(
        array &$targets,
        array $candidate,
        string $trigger,
        string $dictionary,
        string $name,
        array $objects
    ): void {
        $value = $this->extractPdfValueForName($dictionary, $name);
        if ($value === null) {
            return;
        }

        $summary = $this->summarizePdfFormFieldActionTargetValue($this->pdfFormFieldActionSource($candidate, $trigger), $value, $objects);
        if ($summary === null) {
            return;
        }

        $entry = [
            'fieldName' => $candidate['fieldName'],
            'fieldObject' => $candidate['fieldObject'],
            'fieldType' => $candidate['fieldType'],
            'fieldTypeLabel' => $candidate['fieldTypeLabel'],
            'trigger' => $trigger,
            'source' => $summary['source'],
            'actionType' => $summary['type'],
            'actionTarget' => $summary['target'],
            'flags' => $summary['flags'],
            'flagNames' => $summary['flagNames'],
            'fieldNames' => $summary['fieldNames'],
            'fieldSelection' => $summary['fieldSelection'],
        ];
        $key = implode("\0", [
            $entry['fieldObject'] ?? '',
            $entry['fieldName'] ?? '',
            $entry['trigger'],
            $entry['actionType'],
            $entry['actionTarget'] ?? '',
            (string) ($entry['flags'] ?? ''),
            implode('|', $entry['fieldNames']),
        ]);
        $targets[$key] = $entry;
    }

    /**
     * @param array{kind:string, value:string, next?:int} $value
     * @param array<string, string> $objects
     * @return array{source:string, type:string, target:string|null, flags:int|null, flagNames:list<string>, fieldNames:list<string>, fieldSelection:string}|null
     */
    private function summarizePdfFormFieldActionTargetValue(string $source, array $value, array $objects): ?array
    {
        $dictionary = $this->pdfDictionaryFromValue($value, $objects);
        if ($dictionary === null) {
            return null;
        }

        $type = $this->extractPdfNameToken($dictionary, 'S');
        if (!in_array($type, ['ImportData', 'ResetForm', 'SubmitForm'], true)) {
            return null;
        }

        $fieldNames = $this->pdfFormActionFieldNames($this->extractPdfValueForName($dictionary, 'Fields'), $objects);
        $flags = $this->extractPdfIntegerToken($dictionary, 'Flags');
        if ($fieldNames === [] && $flags === null) {
            return null;
        }

        return [
            'source' => $source,
            'type' => $type,
            'target' => $this->pdfActiveActionTarget($dictionary, $type, $objects, null),
            'flags' => $flags,
            'flagNames' => $flags === null ? [] : $this->pdfFormActionFlagNames($type, $flags),
            'fieldNames' => $fieldNames,
            'fieldSelection' => $this->pdfFormActionFieldSelection($type, $flags, $fieldNames),
        ];
    }

    /**
     * @param array{kind:string, value:string, next:int}|null $value
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function pdfFormActionFieldNames(?array $value, array $objects, int $depth = 0): array
    {
        if ($value === null || $depth > 8) {
            return [];
        }

        if ($value['kind'] === 'array') {
            $names = [];
            foreach ($this->pdfTopLevelArrayValues($value['value']) as $item) {
                foreach ($this->pdfFormActionFieldNames($item, $objects, $depth + 1) as $name) {
                    $names[] = $name;
                }
            }

            return $this->uniqueStrings($names);
        }

        if (in_array($value['kind'], ['literal', 'hex', 'name'], true)) {
            $name = trim($value['value']);

            return $name === '' ? [] : [$name];
        }

        if ($value['kind'] === 'dictionary') {
            $field = $this->summarizePdfFormField($value['value']);
            $name = $field['name'] ?? $this->extractPdfStringOrNameValue($value['value'], 'T');

            return $name === null || $name === '' ? [] : [$name];
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return [];
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved !== null && $resolved['kind'] !== 'number') {
                $names = $this->pdfFormActionFieldNames($resolved, $objects, $depth + 1);
                if ($names !== []) {
                    return $names;
                }
            }

            $field = $this->summarizePdfFormField($body);
            $name = $field['name'] ?? $this->extractPdfStringOrNameValue($body, 'T');

            return $name === null || $name === '' ? [] : [$name];
        }

        return [];
    }

    /**
     * @return list<string>
     */
    private function pdfFormActionFlagNames(string $type, int $flags): array
    {
        if ($flags === 0) {
            return [];
        }

        $definitions = [];
        if ($type === 'ResetForm') {
            $definitions[0x001] = 'excludeListedFields';
        } elseif ($type === 'SubmitForm') {
            $definitions = [
                0x001 => 'excludeListedFields',
                0x002 => 'includeNoValueFields',
                0x004 => 'exportFormat',
                0x008 => 'getMethod',
                0x010 => 'submitCoordinates',
                0x020 => 'xfdf',
                0x040 => 'includeAppendSaves',
                0x080 => 'includeAnnotations',
                0x100 => 'submitPdf',
                0x200 => 'canonicalFormat',
                0x400 => 'excludeNonUserAnnotations',
                0x800 => 'excludeFKey',
                0x2000 => 'embedForm',
            ];
        }

        $names = [];
        foreach ($definitions as $bit => $name) {
            if (($flags & $bit) !== 0) {
                $names[] = $name;
            }
        }

        return $names;
    }

    /**
     * @param list<string> $fieldNames
     */
    private function pdfFormActionFieldSelection(string $type, ?int $flags, array $fieldNames): string
    {
        if ($fieldNames === []) {
            return 'all-fields';
        }

        if (($type === 'ResetForm' || $type === 'SubmitForm') && $flags !== null && ($flags & 0x001) !== 0) {
            return 'exclude-listed';
        }

        return 'include-listed';
    }

    /**
     * @param list<array{fieldName:string|null, fieldObject:string|null, fieldType:string|null, fieldTypeLabel:string|null, trigger:string, source:string, actionType:string, actionTarget:string|null, scriptBytes:int|null, scriptSha256:string|null}> $actions
     * @param list<array{fieldName:string|null, fieldObject:string|null, fieldType:string|null, fieldTypeLabel:string|null, trigger:string, source:string, actionType:string, actionTarget:string|null, flags:int|null, flagNames:list<string>, fieldNames:list<string>, fieldSelection:string}> $targets
     * @return list<array{fieldName:string|null, fieldObject:string|null, fieldType:string|null, fieldTypeLabel:string|null, trigger:string, source:string, actionType:string, actionTarget:string|null, targetScheme:string|null, targetIsRemote:bool, flags:int|null, flagNames:list<string>, fieldNames:list<string>, fieldSelection:string, fieldCount:int, reviewStatus:string, issues:list<string>}>
     */
    private function summarizePdfFormFieldActionPolicy(array $actions, array $targets): array
    {
        $targetByKey = [];
        foreach ($targets as $target) {
            if (!$this->isPdfFormFieldActionPolicyType((string) ($target['actionType'] ?? ''))) {
                continue;
            }

            $targetByKey[$this->pdfFormFieldActionPolicyKey($target)] = $target;
        }

        $policy = [];
        foreach ($actions as $action) {
            if (!$this->isPdfFormFieldActionPolicyType((string) ($action['actionType'] ?? ''))) {
                continue;
            }

            $key = $this->pdfFormFieldActionPolicyKey($action);
            $policy[$key] = $this->pdfFormFieldActionPolicyEntry($action, $targetByKey[$key] ?? null);
        }

        foreach ($targetByKey as $key => $target) {
            if (isset($policy[$key])) {
                continue;
            }

            $policy[$key] = $this->pdfFormFieldActionPolicyEntry($target, $target);
        }

        $policy = array_values($policy);
        usort(
            $policy,
            static fn (array $left, array $right): int => [
                $left['fieldName'] ?? '',
                $left['fieldObject'] ?? '',
                $left['trigger'],
                $left['actionType'],
                $left['actionTarget'] ?? '',
            ] <=> [
                $right['fieldName'] ?? '',
                $right['fieldObject'] ?? '',
                $right['trigger'],
                $right['actionType'],
                $right['actionTarget'] ?? '',
            ]
        );

        return $policy;
    }

    private function isPdfFormFieldActionPolicyType(string $type): bool
    {
        return in_array($type, ['ImportData', 'ResetForm', 'SubmitForm'], true);
    }

    /**
     * @param array{fieldName?:string|null, fieldObject?:string|null, trigger?:string, actionType?:string, actionTarget?:string|null} $entry
     */
    private function pdfFormFieldActionPolicyKey(array $entry): string
    {
        return implode("\0", [
            $entry['fieldObject'] ?? '',
            $entry['fieldName'] ?? '',
            $entry['trigger'] ?? '',
            $entry['actionType'] ?? '',
            $entry['actionTarget'] ?? '',
        ]);
    }

    /**
     * @param array<string, mixed> $action
     * @param array<string, mixed>|null $target
     * @return array{fieldName:string|null, fieldObject:string|null, fieldType:string|null, fieldTypeLabel:string|null, trigger:string, source:string, actionType:string, actionTarget:string|null, targetScheme:string|null, targetIsRemote:bool, flags:int|null, flagNames:list<string>, fieldNames:list<string>, fieldSelection:string, fieldCount:int, reviewStatus:string, issues:list<string>}
     */
    private function pdfFormFieldActionPolicyEntry(array $action, ?array $target): array
    {
        $actionType = (string) ($action['actionType'] ?? $target['actionType'] ?? 'unknown');
        $actionTarget = is_string($target['actionTarget'] ?? null)
            ? $target['actionTarget']
            : (is_string($action['actionTarget'] ?? null) ? $action['actionTarget'] : null);
        $flags = is_int($target['flags'] ?? null) ? $target['flags'] : null;
        $flagNames = $this->stringList($target['flagNames'] ?? []);
        $fieldNames = $this->stringList($target['fieldNames'] ?? []);
        $fieldSelection = is_string($target['fieldSelection'] ?? null) && $target['fieldSelection'] !== ''
            ? $target['fieldSelection']
            : 'all-fields';
        $targetScheme = $this->pdfActionTargetScheme($actionTarget);
        $targetIsRemote = $targetScheme !== null && in_array($targetScheme, ['ftp', 'ftps', 'http', 'https', 'mailto'], true);
        $issues = $this->pdfFormFieldActionPolicyIssues($actionType, $actionTarget, $targetIsRemote, $flagNames, $fieldSelection);

        return [
            'fieldName' => is_string($action['fieldName'] ?? null) ? $action['fieldName'] : null,
            'fieldObject' => is_string($action['fieldObject'] ?? null) ? $action['fieldObject'] : null,
            'fieldType' => is_string($action['fieldType'] ?? null) ? $action['fieldType'] : null,
            'fieldTypeLabel' => is_string($action['fieldTypeLabel'] ?? null) ? $action['fieldTypeLabel'] : null,
            'trigger' => is_string($action['trigger'] ?? null) && $action['trigger'] !== '' ? $action['trigger'] : 'unknown',
            'source' => is_string($action['source'] ?? null) && $action['source'] !== '' ? $action['source'] : 'field:unknown',
            'actionType' => $actionType,
            'actionTarget' => $actionTarget,
            'targetScheme' => $targetScheme,
            'targetIsRemote' => $targetIsRemote,
            'flags' => $flags,
            'flagNames' => $flagNames,
            'fieldNames' => $fieldNames,
            'fieldSelection' => $fieldSelection,
            'fieldCount' => count($fieldNames),
            'reviewStatus' => $issues === [] ? 'ok' : 'review',
            'issues' => $issues,
        ];
    }

    /**
     * @param list<string> $flagNames
     * @return list<string>
     */
    private function pdfFormFieldActionPolicyIssues(
        string $type,
        ?string $target,
        bool $targetIsRemote,
        array $flagNames,
        string $fieldSelection
    ): array {
        $issues = [];

        if ($type === 'ImportData') {
            $issues[] = 'import-data-action';
            if ($target === null || $target === '') {
                $issues[] = 'missing-import-target';
            } elseif ($targetIsRemote) {
                $issues[] = 'remote-import-target';
            }

            return $issues;
        }

        if ($type === 'SubmitForm') {
            if ($target === null || $target === '') {
                $issues[] = 'missing-submit-target';
            } elseif ($targetIsRemote) {
                $issues[] = 'remote-submit-target';
            }
            if (in_array('submitPdf', $flagNames, true)) {
                $issues[] = 'submit-pdf-payload';
            }
            if (in_array('includeAnnotations', $flagNames, true)) {
                $issues[] = 'include-annotations';
            }
            if (in_array('includeAppendSaves', $flagNames, true)) {
                $issues[] = 'include-append-saves';
            }
            if (in_array('embedForm', $flagNames, true)) {
                $issues[] = 'embed-form';
            }
            if ($fieldSelection === 'all-fields') {
                $issues[] = 'submit-all-fields';
            } elseif ($fieldSelection === 'exclude-listed') {
                $issues[] = 'submit-excludes-listed-fields';
            }

            return $issues;
        }

        if ($type === 'ResetForm') {
            if ($fieldSelection === 'all-fields') {
                $issues[] = 'reset-all-fields';
            } elseif ($fieldSelection === 'exclude-listed') {
                $issues[] = 'reset-excludes-listed-fields';
            }
        }

        return $issues;
    }

    private function pdfActionTargetScheme(?string $target): ?string
    {
        if ($target === null || $target === '') {
            return null;
        }
        if (preg_match('/\A([A-Za-z][A-Za-z0-9+.-]*):/', $target, $matches) !== 1) {
            return null;
        }

        return strtolower($matches[1]);
    }

    /**
     * @param mixed $value
     * @return list<string>
     */
    private function stringList(mixed $value): array
    {
        if (!is_array($value)) {
            return [];
        }

        return array_values(array_filter($value, static fn (mixed $item): bool => is_string($item)));
    }

    /**
     * @return list<array{name:string, type:string, typeLabel:string, alternateName:string|null, mappingName:string|null, value:string|null, defaultValue:string|null, flags:int, flagNames:list<string>, options:list<string>}>
     */
    private function extractPdfFormFields(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $fieldBodies = [];
        $acroForm = $this->extractPdfAcroFormDictionary($pdfBytes, $catalog);

        if ($acroForm !== null) {
            foreach ($this->extractPdfReferenceArray($acroForm, 'Fields') as $reference) {
                if (isset($objects[$reference])) {
                    $fieldBodies[$reference] = $objects[$reference];
                }
            }
        }

        if ($fieldBodies === []) {
            foreach ($this->pdfObjectBodies($pdfBytes) as $index => $body) {
                if (!str_contains($body, '/FT') || !preg_match('/\/(?:T|TU|TM)\b/s', $body)) {
                    continue;
                }

                $fieldBodies[(string) $index] = $body;
            }
        }

        $fields = [];
        foreach ($fieldBodies as $body) {
            $field = $this->summarizePdfFormField($body);
            if ($field === null) {
                continue;
            }

            $fields[$field['name'] . "\0" . $field['type']] = $field;
        }

        $fields = array_values($fields);
        usort($fields, static fn (array $a, array $b): int => [$a['name'], $a['type']] <=> [$b['name'], $b['type']]);

        return $fields;
    }

    private function extractPdfAcroFormDictionary(string $pdfBytes, ?string $catalog): ?string
    {
        if ($catalog !== null) {
            if (preg_match('/\/AcroForm\s+(\d+)\s+(\d+)\s+R\b/s', $catalog, $matches) === 1) {
                $objects = $this->pdfObjectBodiesByReference($pdfBytes);
                $key = $matches[1] . ' ' . $matches[2];
                if (isset($objects[$key])) {
                    return $objects[$key];
                }
            }

            $nested = $this->extractPdfNestedDictionary($catalog, 'AcroForm');
            if ($nested !== null) {
                return $nested;
            }
        }

        foreach ($this->pdfObjectBodies($pdfBytes) as $body) {
            if (
                str_contains($body, '/Fields')
                && (
                    str_contains($body, '/NeedAppearances')
                    || str_contains($body, '/SigFlags')
                    || str_contains($body, '/DR')
                )
            ) {
                return $body;
            }
        }

        return null;
    }

    /**
     * @return array{fieldReferences:list<string>, fieldCount:int, needAppearances:bool|null, sigFlags:int|null, sigFlagNames:list<string>, defaultResourcesPresent:bool, defaultAppearance:string|null, quadding:int|null, calculationOrder:list<string>, xfaPresent:bool, xfaPacketNames:list<string>}|array{}
     */
    private function extractPdfAcroFormMetadata(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $acroForm = $this->extractPdfAcroFormDictionary($pdfBytes, $catalog);
        if ($acroForm === null) {
            return [];
        }

        $fieldReferences = array_map(
            static fn (string $reference): string => $reference . ' R',
            $this->extractPdfReferenceArray($acroForm, 'Fields')
        );
        $calculationOrder = array_map(
            static fn (string $reference): string => $reference . ' R',
            $this->extractPdfReferenceArray($acroForm, 'CO')
        );
        $xfaValue = $this->extractPdfValueForName($acroForm, 'XFA');

        return [
            'fieldReferences' => $fieldReferences,
            'fieldCount' => count($fieldReferences),
            'needAppearances' => $this->extractPdfBooleanToken($acroForm, 'NeedAppearances'),
            'sigFlags' => $this->extractPdfIntegerToken($acroForm, 'SigFlags'),
            'sigFlagNames' => $this->pdfAcroFormSigFlagNames($this->extractPdfIntegerToken($acroForm, 'SigFlags') ?? 0),
            'defaultResourcesPresent' => $this->extractPdfDictionaryOrReferenceValue($acroForm, 'DR', $objects) !== null,
            'defaultAppearance' => $this->extractPdfStringOrNameValue($acroForm, 'DA'),
            'quadding' => $this->extractPdfIntegerToken($acroForm, 'Q'),
            'calculationOrder' => $calculationOrder,
            'xfaPresent' => $xfaValue !== null,
            'xfaPacketNames' => $xfaValue === null ? [] : $this->extractPdfXfaPacketNames($xfaValue, $objects),
        ];
    }

    /**
     * @return list<array{packetName:string|null, packetObject:string|null, source:string, valueKind:string, filters:list<string>, packetBytes:int|null, packetSha256:string|null, packetSkipped:string|null}>
     */
    private function extractPdfXfaPackets(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $acroForm = $this->extractPdfAcroFormDictionary($pdfBytes, $catalog);
        if ($acroForm === null) {
            return [];
        }

        $xfaValue = $this->extractPdfValueForName($acroForm, 'XFA');
        if ($xfaValue === null) {
            return [];
        }

        return $this->collectPdfXfaPacketsFromValue($xfaValue, $objects, 'AcroForm.XFA');
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return list<array{packetName:string|null, packetObject:string|null, source:string, valueKind:string, filters:list<string>, packetBytes:int|null, packetSha256:string|null, packetSkipped:string|null}>
     */
    private function collectPdfXfaPacketsFromValue(array $value, array $objects, string $source, int $depth = 0): array
    {
        if ($depth > 8) {
            return [];
        }

        if ($value['kind'] === 'reference') {
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return [];
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved !== null && $resolved['kind'] === 'array' && $this->extractPdfStreamBytes($body) === null) {
                return $this->collectPdfXfaPacketsFromValue($resolved, $objects, $source, $depth + 1);
            }
        }

        if ($value['kind'] !== 'array') {
            $summary = $this->summarizePdfXfaPacketValue(null, $value, $objects, $source, $depth);

            return $summary === null ? [] : [$summary];
        }

        $packets = [];
        $values = $this->pdfTopLevelArrayValues($value['value']);
        for ($index = 0; $index < count($values); $index++) {
            $packetName = null;
            $packetValue = $values[$index];
            $packetSource = $source . '[' . $index . ']';
            if (
                in_array($packetValue['kind'], ['hex', 'literal', 'name'], true)
                && isset($values[$index + 1])
            ) {
                $packetName = trim($packetValue['value']);
                $packetName = $packetName === '' ? null : $packetName;
                $index++;
                $packetValue = $values[$index];
                $packetSource = $packetName === null
                    ? $source . '[' . $index . ']'
                    : $source . '[' . $packetName . ']';
            }

            $summary = $this->summarizePdfXfaPacketValue($packetName, $packetValue, $objects, $packetSource, $depth + 1);
            if ($summary !== null) {
                $packets[] = $summary;
            }
        }

        return $packets;
    }

    /**
     * @param array{kind:string, value:string, next:int} $value
     * @param array<string, string> $objects
     * @return array{packetName:string|null, packetObject:string|null, source:string, valueKind:string, filters:list<string>, packetBytes:int|null, packetSha256:string|null, packetSkipped:string|null}|null
     */
    private function summarizePdfXfaPacketValue(?string $packetName, array $value, array $objects, string $source, int $depth = 0): ?array
    {
        if ($depth > 8) {
            return null;
        }

        $packetObject = null;
        $filters = [];
        $packetBytes = null;
        $packetSha256 = null;
        $packetSkipped = null;
        $valueKind = $value['kind'];

        if ($value['kind'] === 'reference') {
            $packetObject = $value['value'];
            $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
            if ($body === null) {
                return [
                    'packetName' => $packetName,
                    'packetObject' => $packetObject,
                    'source' => $source,
                    'valueKind' => 'missing',
                    'filters' => [],
                    'packetBytes' => null,
                    'packetSha256' => null,
                    'packetSkipped' => 'missing-object',
                ];
            }

            if ($this->extractPdfStreamBytes($body) !== null) {
                $stream = $this->summarizePdfStructuralStream($body, self::MAX_XFA_PACKET_BYTES);

                return [
                    'packetName' => $packetName,
                    'packetObject' => $packetObject,
                    'source' => $source,
                    'valueKind' => 'stream',
                    'filters' => $this->extractPdfFilterNames($body, $objects),
                    'packetBytes' => $stream['bytes'],
                    'packetSha256' => $stream['sha256'],
                    'packetSkipped' => $stream['skipped'],
                ];
            }

            $resolved = $this->parsePdfValueAt($body, 0);
            if ($resolved !== null) {
                $summary = $this->summarizePdfXfaPacketValue($packetName, $resolved, $objects, $source, $depth + 1);
                if ($summary !== null) {
                    $summary['packetObject'] = $packetObject;
                }

                return $summary;
            }

            $valueKind = str_starts_with(ltrim($body), '<<') ? 'dictionary' : 'object';
        } elseif (in_array($value['kind'], ['hex', 'literal', 'name'], true)) {
            $bytes = $value['value'];
            $packetBytes = strlen($bytes);
            if ($packetBytes > self::MAX_XFA_PACKET_BYTES) {
                $packetSkipped = 'too-large';
            } else {
                $packetSha256 = hash('sha256', $bytes);
            }
        } elseif ($value['kind'] === 'dictionary') {
            $filters = $this->extractPdfFilterNames($value['value'], $objects);
        }

        return [
            'packetName' => $packetName,
            'packetObject' => $packetObject,
            'source' => $source,
            'valueKind' => $valueKind,
            'filters' => $filters,
            'packetBytes' => $packetBytes,
            'packetSha256' => $packetSha256,
            'packetSkipped' => $packetSkipped,
        ];
    }

    /**
     * @return list<array{order:int, fieldObject:string, fieldName:string|null, fieldType:string|null, fieldTypeLabel:string|null, alternateName:string|null, mappingName:string|null, flags:int|null, flagNames:list<string>, missing:bool}>
     */
    private function extractPdfAcroFormCalculationOrder(string $pdfBytes, ?string $catalog): array
    {
        $objects = $this->pdfObjectBodiesByReference($pdfBytes);
        $acroForm = $this->extractPdfAcroFormDictionary($pdfBytes, $catalog);
        if ($acroForm === null) {
            return [];
        }

        $entries = [];
        foreach ($this->extractPdfReferenceArray($acroForm, 'CO') as $index => $reference) {
            $fieldObject = $reference . ' R';
            $body = $objects[$reference] ?? null;
            if ($body === null) {
                $entries[] = [
                    'order' => $index + 1,
                    'fieldObject' => $fieldObject,
                    'fieldName' => null,
                    'fieldType' => null,
                    'fieldTypeLabel' => null,
                    'alternateName' => null,
                    'mappingName' => null,
                    'flags' => null,
                    'flagNames' => [],
                    'missing' => true,
                ];
                continue;
            }

            $field = $this->summarizePdfFormField($body);
            $fieldType = $field['type'] ?? $this->extractPdfNameToken($body, 'FT');
            $flags = isset($field['flags']) && is_int($field['flags'])
                ? $field['flags']
                : $this->extractPdfIntegerToken($body, 'Ff');

            $entries[] = [
                'order' => $index + 1,
                'fieldObject' => $fieldObject,
                'fieldName' => $field['name'] ?? null,
                'fieldType' => $fieldType,
                'fieldTypeLabel' => $fieldType === null ? null : $this->pdfFormFieldTypeLabel($fieldType),
                'alternateName' => $field['alternateName'] ?? $this->extractPdfStringOrNameValue($body, 'TU'),
                'mappingName' => $field['mappingName'] ?? $this->extractPdfStringOrNameValue($body, 'TM'),
                'flags' => $flags,
                'flagNames' => $fieldType === null || $flags === null ? [] : $this->pdfFormFieldFlagNames($fieldType, $flags),
                'missing' => false,
            ];
        }

        return $entries;
    }

    /**
     * @return list<string>
     */
    private function pdfAcroFormSigFlagNames(int $flags): array
    {
        $names = [];
        if (($flags & 1) !== 0) {
            $names[] = 'signaturesExist';
        }
        if (($flags & 2) !== 0) {
            $names[] = 'appendOnly';
        }

        return $names;
    }

    /**
     * @param array{kind:string, value:string, next?:int} $value
     * @param array<string, string> $objects
     * @return list<string>
     */
    private function extractPdfXfaPacketNames(array $value, array $objects, int $depth = 0): array
    {
        if ($depth > 8) {
            return [];
        }
        if ($value['kind'] === 'array') {
            return $this->collectPdfStringsFromArray($value['value']);
        }
        if ($value['kind'] !== 'reference') {
            return [];
        }

        $body = $objects[$this->pdfReferenceKey($value['value'])] ?? null;
        if ($body === null) {
            return [];
        }

        $resolved = $this->parsePdfValueAt($body, 0);

        return $resolved === null ? [] : $this->extractPdfXfaPacketNames($resolved, $objects, $depth + 1);
    }

    /**
     * @return list<string>
     */
    private function extractPdfReferenceArray(string $dictionary, string $name): array
    {
        $array = $this->extractPdfArrayValue($dictionary, $name);
        if ($array === null || preg_match_all('/\b(\d+)\s+(\d+)\s+R\b/s', $array, $matches, PREG_SET_ORDER) < 1) {
            return [];
        }

        $references = [];
        foreach ($matches as $match) {
            $references[] = $match[1] . ' ' . $match[2];
        }

        return array_values(array_unique($references));
    }

    /**
     * @return array{name:string, type:string, typeLabel:string, alternateName:string|null, mappingName:string|null, value:string|null, defaultValue:string|null, flags:int, flagNames:list<string>, options:list<string>}|null
     */
    private function summarizePdfFormField(string $fieldDictionary): ?array
    {
        $type = $this->extractPdfNameToken($fieldDictionary, 'FT') ?? 'unknown';
        $name = $this->extractPdfStringOrNameValue($fieldDictionary, 'T');
        if ($name === null) {
            $name = $this->extractPdfStringOrNameValue($fieldDictionary, 'TU')
                ?? $this->extractPdfStringOrNameValue($fieldDictionary, 'TM');
        }
        if ($name === null || $name === '') {
            return null;
        }

        $flags = $this->extractPdfIntegerToken($fieldDictionary, 'Ff') ?? 0;

        return [
            'name' => $name,
            'type' => $type,
            'typeLabel' => $this->pdfFormFieldTypeLabel($type),
            'alternateName' => $this->extractPdfStringOrNameValue($fieldDictionary, 'TU'),
            'mappingName' => $this->extractPdfStringOrNameValue($fieldDictionary, 'TM'),
            'value' => $this->extractPdfStringOrNameValue($fieldDictionary, 'V'),
            'defaultValue' => $this->extractPdfStringOrNameValue($fieldDictionary, 'DV'),
            'flags' => $flags,
            'flagNames' => $this->pdfFormFieldFlagNames($type, $flags),
            'options' => $this->extractPdfStringArrayValue($fieldDictionary, 'Opt'),
        ];
    }

    private function pdfFormFieldTypeLabel(string $type): string
    {
        return match ($type) {
            'Btn' => 'button',
            'Ch' => 'choice',
            'Sig' => 'signature',
            'Tx' => 'text',
            default => $type === '' ? 'unknown' : $type,
        };
    }

    /**
     * @param list<array{name:string, type:string, typeLabel:string, alternateName:string|null, mappingName:string|null, value:string|null, defaultValue:string|null, flags:int, flagNames:list<string>, options:list<string>}> $fields
     * @return array<string, int>
     */
    private function summarizePdfFormFieldTypes(array $fields): array
    {
        $types = [];
        foreach ($fields as $field) {
            $label = $field['typeLabel'];
            $types[$label] = ($types[$label] ?? 0) + 1;
        }

        ksort($types);

        return $types;
    }

    /**
     * @param list<array{actionType:string}> $actions
     * @return array<string, int>
     */
    private function summarizePdfFormFieldActionTypes(array $actions): array
    {
        $types = [];
        foreach ($actions as $action) {
            $type = $action['actionType'];
            $types[$type] = ($types[$type] ?? 0) + 1;
        }

        ksort($types);

        return $types;
    }

    private function extractPdfStringOrNameValue(string $dictionary, string $name): ?string
    {
        foreach ($this->extractPdfNamedStrings($dictionary, $name) as $value) {
            $value = trim($value);
            if ($value !== '') {
                return $value;
            }
        }

        $value = $this->extractPdfNameToken($dictionary, $name);

        return $value === null || $value === '' ? null : $value;
    }

    private function extractPdfByteStringHexValue(string $dictionary, string $name): ?string
    {
        $needle = '/' . $name;
        $offset = 0;
        $length = strlen($dictionary);
        while (($position = strpos($dictionary, $needle, $offset)) !== false) {
            $cursor = $position + strlen($needle);
            if ($cursor < $length && preg_match('/[A-Za-z0-9_.-]/', $dictionary[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < $length && ctype_space($dictionary[$cursor])) {
                $cursor++;
            }
            if ($cursor >= $length) {
                return null;
            }
            if ($dictionary[$cursor] === '<' && ($cursor + 1 >= $length || $dictionary[$cursor + 1] !== '<')) {
                $end = strpos($dictionary, '>', $cursor + 1);
                if ($end === false) {
                    return null;
                }

                $hex = strtoupper(preg_replace('/\s+/', '', substr($dictionary, $cursor + 1, $end - $cursor - 1)) ?? '');

                return $hex === '' ? null : $hex;
            }

            if ($dictionary[$cursor] === '(') {
                $parsed = $this->parsePdfLiteralString($dictionary, $cursor);
                if ($parsed !== null && $parsed['value'] !== '') {
                    return strtoupper(bin2hex($parsed['value']));
                }
            }

            $offset = $cursor + 1;
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private function extractPdfStringArrayValue(string $dictionary, string $name): array
    {
        $array = $this->extractPdfArrayValue($dictionary, $name);
        if ($array === null) {
            return [];
        }

        $values = [];
        $cursor = 0;
        $length = strlen($array);
        while ($cursor < $length) {
            $parsed = null;
            if ($array[$cursor] === '(') {
                $parsed = $this->parsePdfLiteralString($array, $cursor);
            } elseif (
                $array[$cursor] === '<'
                && ($cursor + 1 >= $length || $array[$cursor + 1] !== '<')
            ) {
                $parsed = $this->parsePdfHexString($array, $cursor);
            }

            if ($parsed !== null) {
                $value = trim($parsed['value']);
                if ($value !== '') {
                    $values[] = $value;
                }
                $cursor = $parsed['next'];
                continue;
            }

            $cursor++;
        }

        return array_values(array_unique($values));
    }

    private function extractPdfArrayValue(string $dictionary, string $name): ?string
    {
        $needle = '/' . $name;
        $offset = 0;
        $length = strlen($dictionary);
        while (($position = strpos($dictionary, $needle, $offset)) !== false) {
            $cursor = $position + strlen($needle);
            if ($cursor < $length && preg_match('/[A-Za-z0-9_.-]/', $dictionary[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < $length && ctype_space($dictionary[$cursor])) {
                $cursor++;
            }
            if ($cursor >= $length || $dictionary[$cursor] !== '[') {
                $offset = $cursor + 1;
                continue;
            }

            $parsed = $this->parsePdfArray($dictionary, $cursor);
            if ($parsed !== null) {
                return $parsed['value'];
            }

            $offset = $cursor + 1;
        }

        return null;
    }

    /**
     * @return list<string>
     */
    private function pdfFormFieldFlagNames(string $type, int $flags): array
    {
        if ($flags === 0) {
            return [];
        }

        $definitions = [
            0x000001 => 'readOnly',
            0x000002 => 'required',
            0x000004 => 'noExport',
        ];
        if ($type === 'Btn') {
            $definitions += [
                0x004000 => 'noToggleToOff',
                0x008000 => 'radio',
                0x010000 => 'pushbutton',
                0x2000000 => 'radiosInUnison',
            ];
        } elseif ($type === 'Tx') {
            $definitions += [
                0x001000 => 'multiline',
                0x002000 => 'password',
                0x100000 => 'fileSelect',
                0x400000 => 'doNotSpellCheck',
                0x800000 => 'doNotScroll',
                0x1000000 => 'comb',
                0x2000000 => 'richText',
            ];
        } elseif ($type === 'Ch') {
            $definitions += [
                0x020000 => 'combo',
                0x040000 => 'edit',
                0x080000 => 'sort',
                0x200000 => 'multiSelect',
                0x400000 => 'doNotSpellCheck',
                0x4000000 => 'commitOnSelChange',
            ];
        }

        $names = [];
        foreach ($definitions as $bit => $name) {
            if (($flags & $bit) !== 0) {
                $names[] = $name;
            }
        }

        return $names;
    }

    /**
     * @return list<string>
     */
    private function extractPdfNamedStrings(string $objectBody, string $name): array
    {
        $values = [];
        $needle = '/' . $name;
        $offset = 0;
        $length = strlen($objectBody);
        while (($position = strpos($objectBody, $needle, $offset)) !== false) {
            $cursor = $position + strlen($needle);
            if ($cursor < $length && preg_match('/[A-Za-z0-9_.-]/', $objectBody[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < $length && ctype_space($objectBody[$cursor])) {
                $cursor++;
            }

            $parsed = null;
            if ($cursor < $length && $objectBody[$cursor] === '(') {
                $parsed = $this->parsePdfLiteralString($objectBody, $cursor);
            } elseif (
                $cursor < $length
                && $objectBody[$cursor] === '<'
                && ($cursor + 1 >= $length || $objectBody[$cursor + 1] !== '<')
            ) {
                $parsed = $this->parsePdfHexString($objectBody, $cursor);
            }

            if ($parsed !== null) {
                $values[] = $parsed['value'];
                $offset = $parsed['next'];
                continue;
            }

            $offset = $cursor;
        }

        return $values;
    }

    /**
     * @return list<string>
     */
    private function extractPdfNamesArrayStrings(string $objectBody): array
    {
        $values = [];
        $offset = 0;
        $length = strlen($objectBody);
        while (($position = strpos($objectBody, '/Names', $offset)) !== false) {
            $cursor = $position + strlen('/Names');
            if ($cursor < $length && preg_match('/[A-Za-z0-9_.-]/', $objectBody[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < $length && ctype_space($objectBody[$cursor])) {
                $cursor++;
            }
            if ($cursor >= $length || $objectBody[$cursor] !== '[') {
                $offset = $cursor + 1;
                continue;
            }

            $cursor++;
            while ($cursor < $length) {
                if ($objectBody[$cursor] === ']') {
                    break;
                }

                $parsed = null;
                if ($objectBody[$cursor] === '(') {
                    $parsed = $this->parsePdfLiteralString($objectBody, $cursor);
                } elseif (
                    $objectBody[$cursor] === '<'
                    && ($cursor + 1 >= $length || $objectBody[$cursor + 1] !== '<')
                ) {
                    $parsed = $this->parsePdfHexString($objectBody, $cursor);
                }

                if ($parsed !== null) {
                    $values[] = $parsed['value'];
                    $cursor = $parsed['next'];
                    continue;
                }

                $cursor++;
            }

            $offset = $cursor + 1;
        }

        return $values;
    }

    /**
     * @return list<string>
     */
    private function pdfObjectBodies(string $pdfBytes): array
    {
        if (preg_match_all('/\b\d+\s+\d+\s+obj\b(.*?)\bendobj\b/s', $pdfBytes, $matches) < 1) {
            return [];
        }

        return $matches[1];
    }

    /**
     * @return array<string, string>
     */
    private function pdfObjectBodiesByReference(string $pdfBytes): array
    {
        if (preg_match_all('/\b(\d+)\s+(\d+)\s+obj\b(.*?)\bendobj\b/s', $pdfBytes, $matches, PREG_SET_ORDER) < 1) {
            return [];
        }

        $objects = [];
        foreach ($matches as $match) {
            $objects[$match[1] . ' ' . $match[2]] = $match[3];
        }

        return $objects;
    }

    /**
     * @return list<string>
     */
    private function extractPdfTitleStrings(string $objectBody): array
    {
        $titles = [];
        $offset = 0;
        $length = strlen($objectBody);
        while (($position = strpos($objectBody, '/Title', $offset)) !== false) {
            $cursor = $position + strlen('/Title');
            if ($cursor < $length && preg_match('/[A-Za-z0-9_.-]/', $objectBody[$cursor]) === 1) {
                $offset = $cursor;
                continue;
            }
            while ($cursor < $length && ctype_space($objectBody[$cursor])) {
                $cursor++;
            }

            $parsed = null;
            if ($cursor < $length && $objectBody[$cursor] === '(') {
                $parsed = $this->parsePdfLiteralString($objectBody, $cursor);
            } elseif (
                $cursor < $length
                && $objectBody[$cursor] === '<'
                && ($cursor + 1 >= $length || $objectBody[$cursor + 1] !== '<')
            ) {
                $parsed = $this->parsePdfHexString($objectBody, $cursor);
            }

            if ($parsed !== null) {
                $title = trim($parsed['value']);
                if ($title !== '') {
                    $titles[] = $title;
                }
                $offset = $parsed['next'];
                continue;
            }

            $offset = $cursor + 1;
        }

        return $titles;
    }

    /**
     * @return array{value:string, next:int}|null
     */
    private function parsePdfDictionary(string $bytes, int $offset): ?array
    {
        $length = strlen($bytes);
        if ($offset + 1 >= $length || substr($bytes, $offset, 2) !== '<<') {
            return null;
        }

        $depth = 1;
        for ($i = $offset + 2; $i < $length - 1; $i++) {
            if ($bytes[$i] === '(') {
                $end = $this->pdfLiteralStringEnd($bytes, $i);
                if ($end !== null) {
                    $i = $end - 1;
                }
                continue;
            }
            if ($bytes[$i] === '<' && $bytes[$i + 1] === '<') {
                $depth++;
                $i++;
                continue;
            }
            if ($bytes[$i] === '>' && $bytes[$i + 1] === '>') {
                $depth--;
                $i++;
                if ($depth === 0) {
                    return ['value' => substr($bytes, $offset, $i + 1 - $offset), 'next' => $i + 1];
                }
            }
        }

        return null;
    }

    /**
     * @return array{value:string, next:int}|null
     */
    private function parsePdfArray(string $bytes, int $offset): ?array
    {
        $length = strlen($bytes);
        if ($offset >= $length || $bytes[$offset] !== '[') {
            return null;
        }

        $depth = 1;
        for ($i = $offset + 1; $i < $length; $i++) {
            if ($bytes[$i] === '(') {
                $end = $this->pdfLiteralStringEnd($bytes, $i);
                if ($end !== null) {
                    $i = $end - 1;
                }
                continue;
            }
            if ($bytes[$i] === '<' && $i + 1 < $length && $bytes[$i + 1] === '<') {
                $parsed = $this->parsePdfDictionary($bytes, $i);
                if ($parsed !== null) {
                    $i = $parsed['next'] - 1;
                }
                continue;
            }
            if ($bytes[$i] === '[') {
                $depth++;
                continue;
            }
            if ($bytes[$i] === ']') {
                $depth--;
                if ($depth === 0) {
                    return ['value' => substr($bytes, $offset, $i + 1 - $offset), 'next' => $i + 1];
                }
            }
        }

        return null;
    }

    private function pdfLiteralStringEnd(string $bytes, int $offset): ?int
    {
        $length = strlen($bytes);
        if ($offset >= $length || $bytes[$offset] !== '(') {
            return null;
        }

        $depth = 1;
        for ($i = $offset + 1; $i < $length; $i++) {
            $char = $bytes[$i];
            if ($char === '\\') {
                if ($i + 1 < $length) {
                    $i++;
                }
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                $depth--;
                if ($depth === 0) {
                    return $i + 1;
                }
            }
        }

        return null;
    }

    /**
     * @return array{value:string, next:int}|null
     */
    private function parsePdfLiteralString(string $bytes, int $offset): ?array
    {
        $length = strlen($bytes);
        if ($offset >= $length || $bytes[$offset] !== '(') {
            return null;
        }

        $depth = 1;
        $value = '';
        for ($i = $offset + 1; $i < $length; $i++) {
            $char = $bytes[$i];
            if ($char === '\\') {
                if ($i + 1 >= $length) {
                    break;
                }
                $next = $bytes[++$i];
                if ($next === "\r" || $next === "\n") {
                    if ($next === "\r" && $i + 1 < $length && $bytes[$i + 1] === "\n") {
                        $i++;
                    }
                    continue;
                }
                if ($next >= '0' && $next <= '7') {
                    $octal = $next;
                    for ($j = 0; $j < 2 && $i + 1 < $length && $bytes[$i + 1] >= '0' && $bytes[$i + 1] <= '7'; $j++) {
                        $octal .= $bytes[++$i];
                    }
                    $value .= chr(octdec($octal));
                    continue;
                }

                $value .= match ($next) {
                    'n' => "\n",
                    'r' => "\r",
                    't' => "\t",
                    'b' => "\x08",
                    'f' => "\x0c",
                    default => $next,
                };
                continue;
            }
            if ($char === '(') {
                $depth++;
                $value .= $char;
                continue;
            }
            if ($char === ')') {
                $depth--;
                if ($depth === 0) {
                    return ['value' => $this->pdfTextBytesToUtf8($value), 'next' => $i + 1];
                }
                $value .= $char;
                continue;
            }

            $value .= $char;
        }

        return null;
    }

    /**
     * @return array{value:string, next:int}|null
     */
    private function parsePdfHexString(string $bytes, int $offset): ?array
    {
        $end = strpos($bytes, '>', $offset + 1);
        if ($end === false) {
            return null;
        }

        $hex = preg_replace('/\s+/', '', substr($bytes, $offset + 1, $end - $offset - 1)) ?? '';
        if ($hex === '' || preg_match('/\A[0-9A-Fa-f]+\z/', $hex) !== 1) {
            return null;
        }
        if (strlen($hex) % 2 === 1) {
            $hex .= '0';
        }

        $raw = hex2bin($hex);
        if ($raw === false) {
            return null;
        }

        return ['value' => $this->pdfTextBytesToUtf8($raw), 'next' => $end + 1];
    }

    private function pdfTextBytesToUtf8(string $bytes): string
    {
        if (str_starts_with($bytes, "\xFE\xFF")) {
            return $this->utf16BytesToUtf8(substr($bytes, 2), true);
        }
        if (str_starts_with($bytes, "\xFF\xFE")) {
            return $this->utf16BytesToUtf8(substr($bytes, 2), false);
        }
        if (preg_match('//u', $bytes) === 1) {
            return preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]+/', '', $bytes) ?? $bytes;
        }

        return $this->pdfDocEncodingBytesToUtf8($bytes);
    }

    private function pdfDocEncodingBytesToUtf8(string $bytes): string
    {
        $output = '';
        $length = strlen($bytes);
        for ($i = 0; $i < $length; $i++) {
            $byte = ord($bytes[$i]);
            $codepoint = self::PDF_DOC_ENCODING_OVERRIDES[$byte] ?? $byte;
            if ($codepoint === 0 || ($codepoint < 0x20 && !in_array($codepoint, [0x09, 0x0A, 0x0D], true))) {
                continue;
            }

            $output .= $this->codepointToUtf8($codepoint);
        }

        return $output;
    }

    private function utf16BytesToUtf8(string $bytes, bool $bigEndian): string
    {
        $output = '';
        $length = strlen($bytes) - (strlen($bytes) % 2);
        for ($i = 0; $i < $length; $i += 2) {
            $first = ord($bytes[$i]);
            $second = ord($bytes[$i + 1]);
            $codepoint = $bigEndian ? (($first << 8) | $second) : (($second << 8) | $first);
            if ($codepoint >= 0xD800 && $codepoint <= 0xDBFF && $i + 3 < $length) {
                $third = ord($bytes[$i + 2]);
                $fourth = ord($bytes[$i + 3]);
                $low = $bigEndian ? (($third << 8) | $fourth) : (($fourth << 8) | $third);
                if ($low >= 0xDC00 && $low <= 0xDFFF) {
                    $codepoint = 0x10000 + (($codepoint - 0xD800) << 10) + ($low - 0xDC00);
                    $i += 2;
                }
            }
            if ($codepoint === 0) {
                continue;
            }

            $output .= $this->codepointToUtf8($codepoint);
        }

        return $output;
    }

    private function codepointToUtf8(int $codepoint): string
    {
        if ($codepoint < 0 || $codepoint > 0x10FFFF || ($codepoint >= 0xD800 && $codepoint <= 0xDFFF)) {
            return '';
        }
        if ($codepoint <= 0x7F) {
            return chr($codepoint);
        }
        if ($codepoint <= 0x7FF) {
            return chr(0xC0 | ($codepoint >> 6))
                . chr(0x80 | ($codepoint & 0x3F));
        }
        if ($codepoint <= 0xFFFF) {
            return chr(0xE0 | ($codepoint >> 12))
                . chr(0x80 | (($codepoint >> 6) & 0x3F))
                . chr(0x80 | ($codepoint & 0x3F));
        }

        return chr(0xF0 | ($codepoint >> 18))
            . chr(0x80 | (($codepoint >> 12) & 0x3F))
            . chr(0x80 | (($codepoint >> 6) & 0x3F))
            . chr(0x80 | ($codepoint & 0x3F));
    }

    private function normalizeRelativePath(string $path, string $label): string
    {
        $path = str_replace('\\', '/', trim($path));
        if ($path === '') {
            throw new \InvalidArgumentException($label . ' must not be empty');
        }
        if (str_contains($path, "\0")) {
            throw new \InvalidArgumentException($label . ' must not contain NUL bytes');
        }
        if (str_starts_with($path, '/') || preg_match('/\A[A-Za-z]:\//', $path) === 1) {
            throw new \InvalidArgumentException($label . ' must be relative to the handoff workspace');
        }

        $parts = [];
        foreach (explode('/', $path) as $part) {
            if ($part === '' || $part === '.') {
                continue;
            }
            if ($part === '..') {
                throw new \InvalidArgumentException($label . ' must not contain parent-directory segments');
            }
            $parts[] = $part;
        }

        if ($parts === []) {
            throw new \InvalidArgumentException($label . ' must name a file');
        }

        return implode('/', $parts);
    }

    private function normalizeRelativeDirectory(string $path, string $label): string
    {
        $path = str_replace('\\', '/', trim($path));
        if ($path === '') {
            throw new \InvalidArgumentException($label . ' must not be empty');
        }
        if (str_contains($path, "\0")) {
            throw new \InvalidArgumentException($label . ' must not contain NUL bytes');
        }
        if (
            str_starts_with($path, '/')
            || preg_match('/\A[A-Za-z]:\//', $path) === 1
            || $this->isUriResourceReference($path)
        ) {
            throw new \InvalidArgumentException($label . ' must be relative to the handoff workspace');
        }

        $parts = [];
        foreach (explode('/', $path) as $part) {
            if ($part === '' || $part === '.') {
                continue;
            }
            if ($part === '..') {
                throw new \InvalidArgumentException($label . ' must not contain parent-directory segments');
            }
            $parts[] = $part;
        }

        return $parts === [] ? '.' : implode('/', $parts);
    }

    /**
     * @return list<string>
     */
    private function normalizeRelativePathList(mixed $value, string $label): array
    {
        if (is_string($value)) {
            $value = [$value];
        }
        if (!is_array($value)) {
            throw new \InvalidArgumentException($label . ' list must contain strings');
        }

        $paths = [];
        foreach ($value as $path) {
            $paths[] = $this->normalizeRelativePath($this->requireString($path, $label), $label);
        }

        return $paths;
    }

    /**
     * @return list<string>
     */
    private function normalizeResourceFileList(mixed $value, string $label): array
    {
        if ($value === null || $value === []) {
            return [];
        }
        if (is_string($value)) {
            $value = [$value];
        }
        if (!is_array($value)) {
            throw new \InvalidArgumentException($label . ' list must contain strings');
        }

        $paths = [];
        foreach ($value as $path) {
            $path = str_replace('\\', '/', trim($this->requireString($path, $label)));
            if ($this->isUriResourceReference($path)) {
                throw new \InvalidArgumentException($label . ' must be a relative file path, not a URI');
            }
            if (str_starts_with($path, '#') || str_contains($path, '?') || str_contains($path, '#')) {
                throw new \InvalidArgumentException($label . ' must be a direct relative file path without query or fragment');
            }
            $paths[] = $this->normalizeRelativePath($path, $label);
        }

        $paths = array_values(array_unique($paths));
        sort($paths);

        return $paths;
    }

    /**
     * @return list<string>
     */
    private function normalizeStringList(mixed $value): array
    {
        if (is_string($value)) {
            $value = [$value];
        }
        if (!is_array($value)) {
            throw new \InvalidArgumentException('PDF engine options must be strings');
        }

        $strings = [];
        foreach ($value as $item) {
            $strings[] = $this->requireString($item, 'PDF engine option');
        }

        return $strings;
    }

    /**
     * @return array<string, string>
     */
    private function normalizeEngineEnvironment(mixed $value): array
    {
        if ($value === null || $value === []) {
            return [];
        }
        if (!is_array($value) || array_is_list($value)) {
            throw new \InvalidArgumentException('PDF engine environment must be a keyed string array');
        }

        $environment = [];
        foreach ($value as $name => $item) {
            if (!is_string($name) || preg_match('/\A[A-Za-z_][A-Za-z0-9_]*\z/', $name) !== 1) {
                throw new \InvalidArgumentException('PDF engine environment variable names must be strings');
            }
            if (!is_string($item)) {
                throw new \InvalidArgumentException('PDF engine environment variable ' . $name . ' must be a string');
            }
            if (str_contains($name, "\0") || str_contains($item, "\0")) {
                throw new \InvalidArgumentException('PDF engine environment variable ' . $name . ' must not contain NUL bytes');
            }

            $environment[$name] = $item;
        }
        ksort($environment);

        return $environment;
    }

    /**
     * @return array<string, mixed>
     */
    private function normalizeVariables(mixed $value): array
    {
        if (!is_array($value) || array_is_list($value)) {
            throw new \InvalidArgumentException('PDF template variables must be a keyed array');
        }

        $variables = [];
        foreach ($value as $name => $item) {
            if (!is_string($name)) {
                throw new \InvalidArgumentException('PDF template variable names must be strings');
            }
            $this->requireTemplateVariableName($name);
            $variables[$name] = $this->normalizeVariableValue($item, $name);
        }

        return $variables;
    }

    private function normalizeVariableValue(mixed $value, string $name): mixed
    {
        if ($value === null || is_bool($value) || is_int($value) || is_float($value)) {
            return $value;
        }
        if (is_string($value)) {
            if (str_contains($value, "\0")) {
                throw new \InvalidArgumentException('PDF template variable ' . $name . ' must not contain NUL bytes');
            }

            return $value;
        }
        if (!is_array($value)) {
            throw new \InvalidArgumentException('PDF template variable ' . $name . ' must be scalar or an array');
        }

        $normalized = [];
        foreach ($value as $key => $item) {
            if (is_string($key)) {
                $this->requireTemplateVariableName($key);
            }
            $normalized[$key] = $this->normalizeVariableValue($item, $name . '.' . $key);
        }

        return $normalized;
    }

    private function requireTemplateVariableName(string $name): void
    {
        if ($name === '' || preg_match('/\A[A-Za-z0-9_][A-Za-z0-9_.:-]*\z/', $name) !== 1) {
            throw new \InvalidArgumentException('Invalid PDF template variable name: ' . $name);
        }
    }

    /**
     * @param array<string, mixed> $files
     * @return array<string, string>
     */
    private function normalizeFileMap(array $files): array
    {
        $normalized = [];
        foreach ($files as $path => $bytes) {
            $normalized[$this->normalizeRelativePath((string) $path, 'fake runner file path')] = $this->requireFileBytes($bytes);
        }

        return $normalized;
    }

    private function requireFileBytes(mixed $value): string
    {
        if (!is_string($value)) {
            throw new \InvalidArgumentException('fake runner file bytes must be a string');
        }

        return $value;
    }

    /**
     * @return list<string>
     */
    private function normalizePlanStringList(mixed $value, string $label): array
    {
        if ($value === null || $value === []) {
            return [];
        }
        if (!is_array($value)) {
            throw new \InvalidArgumentException($label . ' plan key must be a list of strings');
        }

        $strings = [];
        foreach ($value as $item) {
            $strings[] = $this->normalizeRelativePath($this->requireString($item, $label), $label);
        }

        return $strings;
    }

    private function requireString(mixed $value, string $label): string
    {
        if (!is_string($value)) {
            throw new \InvalidArgumentException($label . ' must be a string');
        }
        if ($value === '') {
            throw new \InvalidArgumentException($label . ' must not be empty');
        }
        if (str_contains($value, "\0")) {
            throw new \InvalidArgumentException($label . ' must not contain NUL bytes');
        }

        return $value;
    }

    /**
     * @param array<string, mixed> $plan
     */
    private function requirePlanString(array $plan, string $key): string
    {
        if (!isset($plan[$key]) || !is_string($plan[$key]) || $plan[$key] === '') {
            throw new \InvalidArgumentException('PDF fake runner requires plan key: ' . $key);
        }

        return $plan[$key];
    }
}
